CREATE FUNCTION [dbo].[ReturnTable]
(
	@ItemList NVARCHAR(4000), 
	@delimiter CHAR(1)
)
RETURNS @IDTable TABLE (Value VARCHAR(100))  
AS      
BEGIN    
	DECLARE @tempItemList NVARCHAR(4000)
	SET @tempItemList = @ItemList
	DECLARE @i INT    
	DECLARE @Item NVARCHAR(4000)
	--SET @tempItemList = REPLACE (@tempItemList, ' ', '')
	SET @i = CHARINDEX(@delimiter, @tempItemList)
	WHILE (LEN(@tempItemList) > 0)
	BEGIN
		IF @i = 0
			SET @Item = @tempItemList
		ELSE
			SET @Item = LEFT(@tempItemList, @i - 1)
		INSERT INTO @IDTable(VALUE) VALUES(@Item)
		IF @i = 0
			SET @tempItemList = ''
		ELSE
			SET @tempItemList = RIGHT(@tempItemList, LEN(@tempItemList) - @i)
		SET @i = CHARINDEX(@delimiter, @tempItemList)
	END 
	RETURN
END  
GO

CREATE FUNCTION [dbo].[fn_EncryptStringTW](@strInput NVARCHAR(MAX))
RETURNS NVARCHAR(MAX)
WITH ENCRYPTION
AS
BEGIN
    DECLARE @m INT = 0
    DECLARE @strEncKey NVARCHAR(MAX) = 'ASHOKKHE'
    DECLARE @gsEcDc NVARCHAR(1)
    DECLARE @gsFinal NVARCHAR(MAX) = ''
    DECLARE @gsCompare NVARCHAR(1)
    DECLARE @glNumber INT = LEN(LTRIM(RTRIM(@strInput)))
    DECLARE @sb NVARCHAR(MAX) = 'ASHOKKHE'
    WHILE (LEN(@sb) < @glNumber)
    BEGIN
        SET @sb = @sb + 'ASHOKKHE'
    END
    SET @strEncKey = LEFT(@sb, @glNumber)
    SET @m = 1
    WHILE @m <= @glNumber
    BEGIN
        SET @gsEcDc = SUBSTRING(@strInput, @m, 1)
        SET @gsCompare = SUBSTRING(@strEncKey, @m, 1)
        SET @gsFinal = @gsFinal + CHAR(ASCII(@gsEcDc) + ASCII(@gsCompare) + 13)
        SET @m = @m + 1
    END
    RETURN @gsFinal
END
GO

CREATE FUNCTION fn_ReturnQueryAccess (@strUseriD VARCHAR(50), @strSelection VARCHAR(1), @strSelectionValue VARCHAR(MAX)) RETURNS VARCHAR(MAX) 
AS
BEGIN
  DECLARE @strString VARCHAR(MAX)='', @strUserType VARCHAR(1)='' , @strUserRights1 VARCHAR(MAX)='',
  @strString1 VARCHAR(MAX)=''

  SELECT TOP 1 @strUserType = LA_grouping 
  FROM LoginAccess(NOLOCK) WHERE la_userID = @strUseriD 

  IF @strUserType <> 'A'
  BEGIN
    SELECT @strString = @strString +'OR '+Column1+' IN('+ConcatenatedValues+')'
    FROM(
    SELECT CASE WHEN La_grouping = 'B' THEN 'cm_brboffcode '
    WHEN La_grouping = 'G' THEN 'cm_groupcd '
    WHEN La_grouping = 'F' THEN 'cm_familycd '
    WHEN La_grouping = 'R' THEN 'cm_Subbroker '
    ELSE La_grouping END As Column1,
    STUFF((
    SELECT ',''' + ltrim(rtrim(t2.LA_GrCode))+''''
    FROM LoginAccess(NOLOCK) t2
    WHERE t2.La_grouping = t1.La_grouping
	and LA_UserId = @strUseriD
    ORDER BY t2.LA_GrCode  
    FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 1, '') AS ConcatenatedValues
    FROM LoginAccess(NOLOCK) t1
    WHERE LA_UserId = @strUseriD
    AND La_grouping IN('B','G','F','R') 
    GROUP BY t1.La_grouping) X1

    SET @strString =  REPLACE(@strString,')''',')')
  END
  IF ISNULL(@strString,'') <> ''
  BEGIN
    SET @strString  = '( ' +SUBSTRING(@strString,3,LEN(@strString))+' )'
  END	
  
  
  IF ISNULL(@strSelectionValue,'') <> ''
  BEGIN
    IF ISNULL(@strString,'') = ''
	BEGIN
      select @strString1 = @strString1 +'AND  '+CASE WHEN @strSelection = 'B' THEN 'cm_brboffcode '
      WHEN @strSelection = 'G' THEN 'cm_groupcd '
      WHEN @strSelection = 'F' THEN 'cm_familycd '
      WHEN @strSelection = 'R' THEN 'cm_Subbroker '
      WHEN @strSelection = 'C' THEN 'cm_cd '
      ELSE @strSelection END +' IN('+ConcatenatedValues+')'
      FROM(SELECT STUFF((SELECT ',''' + ltrim(rtrim(VALUE))+''''
      FROM DBO.RETURNTABLE(@strSelectionValue,',') FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 1, '') AS ConcatenatedValues) x1
      SET @strString1  = SUBSTRING(@strString1,4,LEN(@strString1))	  
	  SET @strString = @strString+' '+@strString1
	END  
	ELSE
	BEGIN
	  select @strString1 = @strString1 +'AND  '+CASE WHEN @strSelection = 'B' THEN 'cm_brboffcode '
      WHEN @strSelection = 'G' THEN 'cm_groupcd '
      WHEN @strSelection = 'F' THEN 'cm_familycd '
      WHEN @strSelection = 'R' THEN 'cm_Subbroker '
      WHEN @strSelection = 'C' THEN 'cm_cd '
      ELSE @strSelection END +' IN('+ConcatenatedValues+')'
      FROM(SELECT STUFF((SELECT ',''' + ltrim(rtrim(VALUE))+''''
      FROM DBO.RETURNTABLE(@strSelectionValue,',') FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 1, '') AS ConcatenatedValues) x1
	  SET @strString = @strString+' '+@strString1
	END
  END
  
  IF ISNULL(@strUserType,'') = '' AND EXISTS(SELECT 1 FROM CLIENT_MASTER(NOLOCK) 
  WHERE CM_cD = @strUseriD)
  BEGIN
    SET @strString = ' CM_CD = '''+@strUseriD+''''
  END
  IF ISNULL(@strString,'') <> ''
  BEGIN
    SET @strString  = ' 1 = 1 AND '+@strString+''
  END	
  ELSE
  BEGIN
    SET @strString  = ' 1 = 1 '
  END
  RETURN @strString
END
GO

CREATE FUNCTION [dbo].[fn_GetClients](@i_vcUserid VARCHAR(50), @i_vcSelectListTag VARCHAR(1)='', @i_vcSelectListCode VARCHAR(500)='') 
RETURNS @o_tbOutPutTable TABLE(Client_Code VARCHAR(50))
AS       
BEGIN 
  /*
 ///////////////////////////////////////////////////////////////////////////////////////////
 // Create By     : VAIBHAV GARG
 // Created Date  : 21-NOV-2023
 // Description   : 
 // Reviewed By   : 
 // Review Date   : 
 //////////////////////////////////////////////////////////////////////////////////////////
 */

  DECLARE @strUserType VARCHAR(1) = '', @strUserAccessValue VARCHAR(50)='', @userla_Group VARCHAR(10)='',
  @strUserRights1 VARCHAR(50)=''
  
  DECLARE @tbl_UserAccessRights TABLE(UserType VARCHAR(1), UserAccessValue VARCHAR(50))
  
  SELECT @userla_Group = LA_grouping from LoginAccess(NOLOCK) 
  WHERE LA_UserId IN(SELECT VALUE FROM ReturnTable(@i_vcUserid,','))
  
  IF @i_vcUserid <> ''
  BEGIN
    BEGIN
	  IF ISNULL(@userla_Group,'') = 'A'
	  BEGIN
	    INSERT INTO @tbl_UserAccessRights
	    SELECT 'B', bm_branchcd 
	    FROM Branch_Master(NOLOCK) 
	    WHERE bm_branchcd IN(SELECT cm_brboffcode FROM CLIENT_MASTER(NOLOCK) WHERE cm_schedule = '49843750')
	  END  
	  ELSE
	  BEGIN
	    INSERT INTO @tbl_UserAccessRights
	    SELECT LA_grouping, LA_GrCode from LoginAccess(NOLOCK) 
	    WHERE LA_UserId IN(SELECT VALUE FROM ReturnTable(@i_vcUserid,','))
	  END
	END

    DECLARE db_CursorClientList CURSOR FOR         
	SELECT distinct UserType, UserAccessValue 
	FROM @tbl_UserAccessRights  
 
	OPEN db_CursorClientList       
	FETCH NEXT FROM db_CursorClientList INTO @strUserType, @strUserAccessValue 
	WHILE @@FETCH_STATUS = 0     
	BEGIN
	  IF  @strUserType = 'B'
	  BEGIN
		INSERT INTO @o_tbOutPutTable(Client_Code)
		SELECT DISTINCT cm_cd from client_master(nolock) where cm_brboffcode = @strUserAccessValue and cm_schedule = '49843750'
	  END  
	  ELSE IF @strUserType = 'F'
	  BEGIN
		INSERT INTO @o_tbOutPutTable(Client_Code)
		SELECT DISTINCT cm_cd from client_master(nolock) where cm_familycd = @strUserAccessValue   and cm_schedule = '49843750'
	  END
	  ELSE IF @strUserType = 'A'
	  BEGIN
		INSERT INTO @o_tbOutPutTable(Client_Code)
		SELECT DISTINCT cm_cd from client_master(nolock) where ISNULL(cm_freezeyn,'N') = 'N'  and cm_schedule = '49843750'
	  END
	  ELSE IF @strUserType = 'G'
	  BEGIN
		INSERT INTO @o_tbOutPutTable(Client_Code)
		SELECT DISTINCT cm_cd from client_master(nolock) where cm_groupcd = @strUserAccessValue  and cm_schedule = '49843750'
	  END
	  ELSE IF @strUserType = 'C'
	  BEGIN
		INSERT INTO @o_tbOutPutTable(Client_Code)
		SELECT DISTINCT cm_cd from client_master(nolock) where cm_cd = @strUserAccessValue  and cm_schedule = '49843750'
	  END
	  FETCH NEXT FROM db_CursorClientList INTO @strUserType, @strUserAccessValue 
	END        
	CLOSE db_CursorClientList        
	DEALLOCATE db_CursorClientList
  END
  ELSE
  BEGIN
	INSERT INTO @o_tbOutPutTable(Client_Code)
	SELECT DISTINCT cm_cd from client_master(nolock) WHERE cm_schedule = 49843750
  END
  
  IF EXISTS(sELECT 1 FROM User_master(NOLOCK) WHERE um_user_id = @i_vcUserid AND ISNULL(um_specialrights,'') <> '')
  AND NOT EXISTS(SELECT 1 FROM @o_tbOutPutTable)
  BEGIN
    SELECT @strUserRights1 = DBO.fn_GetUserAccess(um_specialrights) FROM User_master(NOLOCK) WHERE um_user_id = @i_vcUserid
	IF ISNULL(@strUserRights1,'') = 'HO'
	BEGIN
	  INSERT INTO @o_tbOutPutTable(Client_Code)
	  SELECT DISTINCT cm_cd from client_master(nolock) where cm_schedule = '49843750'
	END
  END	
  
  IF @i_vcSelectListTag = 'B'
  BEGIN
    DELETE FROM @o_tbOutPutTable 
    WHERE Client_Code NOT IN(SELECT DISTINCT cm_cd from client_master(nolock) 
	WHERE cm_brboffcode IN( SELECT VALUE FROM DBO.ReturnTable(@i_vcSelectListCode,',')))
  END
  ELSE IF @i_vcSelectListTag = 'F'
  BEGIN
    DELETE FROM @o_tbOutPutTable 
    WHERE Client_Code NOT IN(SELECT DISTINCT cm_cd from client_master(nolock) WHERE cm_familycd IN( SELECT VALUE FROM DBO.ReturnTable(@i_vcSelectListCode,','))) 
  END
  ELSE IF @i_vcSelectListTag = 'C'
  BEGIN
    DELETE FROM @o_tbOutPutTable 
    WHERE Client_Code NOT IN(SELECT VALUE FROM DBO.ReturnTable(@i_vcSelectListCode,',')) 
   END
   ELSE IF @i_vcSelectListTag = 'G'
   BEGIN
     DELETE FROM @o_tbOutPutTable 
     WHERE Client_Code NOT IN(SELECT DISTINCT cm_cd from client_master(nolock) WHERE cm_groupcd IN( SELECT VALUE FROM DBO.ReturnTable(@i_vcSelectListCode,','))) 
   END

  IF NOT EXISTS(SELECT 1 FROM @o_tbOutPutTable)
  BEGIN
   INSERT INTO @o_tbOutPutTable(Client_Code)
   VALUES(@i_vcUserid)
  END
  RETURN
END
GO

