	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##',ISNULL(@strBillSumSegment,''))  
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','RiskManagement') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##','') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##SettType##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Option112A##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##OptionBF##','')	
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ExchSeg##','')
   
	 END 
	 
	 IF @strActionName = 'TradeWeb' and @strOption = 'PerformanceReport'
	 BEGIN
	   DECLARE @strPEReportType VARCHAR(50)=''
	   SELECT @strPEReportType = ParameterValue  FROM @tbl_InputJSONTable 
	   WHERE ParameterName = 'ReportType' 
	   
	   DECLARE @strPEGroupBy VARCHAR(50)=''
	   SELECT @strPEGroupBy = ParameterValue  FROM @tbl_InputJSONTable 
	   WHERE ParameterName = 'GroupBy' 
	   
	   IF ISNULL(@stroptTurnover,'') = ''
	   BEGIN
	     set @stroptTurnover = 'Premium'
	     
	   END
	   
	   IF ISNULL(@strASEXTurnover,'') = ''
	   BEGIN
	     set @strASEXTurnover = 'Difference'
	   END
	   
	   IF ISNULL(@strPEReportType,'') = ''
	   BEGIN 
	    set @strPEReportType = 'ClientWise'
	   END
	   
	   IF ISNULL(@strPEGroupBy,'') = ''
	   BEGIN
	     SET @strPEGroupBy = 'Client'
	   END
	   
	   IF ISNULL(@StrEXCHANGESEGMENT,'') = ''
	   BEGIN
	    SET @StrEXCHANGESEGMENT = 'ALL'
	   END
	   
	   SET @i_vcReportCode = 'PerformanceReport'
	   
	   SET @i_vcReportCategory ='ClientWise'
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##optTurnover##',ISNULL(@stroptTurnover,''))  
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ASEXTurnover##',ISNULL(@strASEXTurnover,''))  
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','')  
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##',@strPEReportType) 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##',@strPEGroupBy) 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##SettType##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Option112A##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##OptionBF##','')	
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ExchSeg##',@StrEXCHANGESEGMENT)
	   
	 END 
	 
	 IF @strActionName = 'TradeWeb' and @strOption = 'DeliveryStatement'
	 BEGIN
	   
	   SET @i_vcReportCode = 'DeliveryStatement'
	   
	   SET @i_vcReportCategory ='ClientWise'
	   SET @CommanXMLString = @CommanXMLString+'<ReportName>DeliveryStatement</ReportName>'
	 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##SettNo##',@StrBillSettlementNo)  
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','')  
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','DeliveryStatement') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##','') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##SettType##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Option112A##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##OptionBF##','')	
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ExchSeg##','')
   
	 END 
	 
	 IF @strActionName = 'TradeWeb' and @strOption = 'OutStandingBalances'
	 BEGIN
