	   @strOutStandingType VARCHAR(100)=''
	   SELECT @strBLAmountTag = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'AmountTag'
	   SELECT @strBLAmountTagValue = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'AmountTagValue'
	   
	   SELECT @strOutStandingType = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'ReportType'
	   
	   SET @i_vcReportCode = 'OutStandingBalances'
	   SET @i_vcReportCategory ='ClientWise'
	   
	   IF ISNULL(@strBLAmountTag,'') = ''
	   BEGIN
	     SET @strBLAmountTag = ''
		 SET @strBLAmountTagValue = 0
	   END
	   
	   SET @CommanXMLString = @CommanXMLString+'<ReportName>OutStandingBalances</ReportName>'
	   SET @CommanXMLString = @CommanXMLString+'<AmountTag>'+@strBLAmountTag+'</AmountTag>'
	   SET @CommanXMLString = @CommanXMLString+'<OutStandingType>'+@strOutStandingType+'</OutStandingType>'
	   SET @CommanXMLString = @CommanXMLString+'<AmountTagValue>'+cast(isnull(@strBLAmountTagValue,0) as varchar)+'</AmountTagValue>'
	   
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','')  
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','OutStandingBalances') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##','') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##SettType##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Option112A##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##OptionBF##','')	
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ExchSeg##','')
   
	 END 
	 
	 IF @strActionName = 'TradeWeb' and @strOption = 'DeliveryPending'
	 BEGIN
	   
	   SET @i_vcReportCode = 'DeliveryPending'
	   
	   SET @i_vcReportCategory ='ClientWise'
	   SET @CommanXMLString = @CommanXMLString+'<ReportName>DeliveryPending</ReportName>'
	   
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','')  
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','DeliveryPending') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##','') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##SettType##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Option112A##','')
