	 IF @strActionName = 'TradeWeb' and @strOption = 'DematAuditreport'
	 BEGIN
	   DECLARE @strDLDeliveryType VARCHAR(20)='', @strDLStatus VARCHAR(20)='', @strDLLockType VARCHAR(20)='',
	   @strDLDateType VARCHAR(1)=''
	   SELECT @strDLDeliveryType = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'DeliveryType'
	   SELECT @strDLStatus = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Status'
	   SELECT @strDLLockType = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'LockType'
	   SELECT @strDLDateType = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'DateType'
	   
	   SET @i_vcReportCode = 'DematAuditreport'
	   
	   IF ISNULL(@strDLDateType,'') = ''
	   BEGIN
	     SET @strDLDateType = 'T'
	   END
	   
	   SET @i_vcReportCategory ='ClientWise'
	   SET @CommanXMLString = @CommanXMLString+'<ReportName>DematAuditreport</ReportName>'
	   SET @CommanXMLString = @CommanXMLString+'<DeliveryType>'+@strDLDeliveryType+'</DeliveryType>'
	   SET @CommanXMLString = @CommanXMLString+'<Status>'+@strDLStatus+'</Status>'
	   SET @CommanXMLString = @CommanXMLString+'<LockType>'+@strDLLockType+'</LockType><DateType>'+@strDLDateType+'</DateType>'
	   
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','')  
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','DematAuditreport') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##','') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##SettType##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Option112A##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##OptionBF##','')	
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ExchSeg##','')
	   
	     --@strDeliveryType VARCHAR(20)='', @strDeliveryStatus VARCHAR(20)='',@strDeliveryLockType VARCHAR(20)=''
     END 
	 
	 IF @strActionName = 'TradeWeb' and @strOption in('PROFITLOSS','PROFITLOSSSUMMARY')
	 BEGIN
	   DECLARE @strPLSegment VARCHAR(50)='DERV', @StrplExchange VARCHAR(20)='', @StrPlRateType VARCHAR(50)='', @StrPlFIFOFlag VARCHAR(20)='',
	   @StrPlFIFOTAG VARCHAR(20)='', @StrPlOptionBF VARCHAR(10)=''
	   SELECT @strPLSegment = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Segment'
	   SELECT @StrPlExchange = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Exchange'
	   SELECT @StrPlRateType = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'RateType'
	   SELECT @StrPlFIFOTAG = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'FIFOFlag'
	   SELECT @StrPlOptionBF = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'OptionBF'
	 
  	   IF ISNULL(@StrPlOptionBF,'') = ''
	   BEGIN
	     SET @StrPlOptionBF = ''
	   END
	   
	   IF ISNULL(@StrPlFIFOTAG,'') = ''
	   BEGIN
	     SET @StrPlFIFOTAG = 'Avg Rate'
	   END
	   
	   IF ISNULL(@StrPlFIFOTAG,'Avg Rate') ='Avg Rate'
       BEGIN
         SET @StrPlFIFOFlag = 'N'   
	   END
       ELSE
       BEGIN
	     SET @StrPlFIFOFlag = 'Y'  
         SET @StrPlRateType = 'Do not Valuate'		 
       END	   
	   IF ISNULL(@StrPlRateType,'') =''
	   BEGIN
	     SET @StrPlRateType = 'Closing Premium'
	   END
	   
	   IF ISNULL(@StrPlExchange,'') = ''
	   BEGIN
	     SET @StrPlExchange = ''
	   END 
	   
	   SET @i_vcReportCode = 'InvestorReport'
	   IF @strPLSegment = 'CASH'
	   BEGIN
		 IF @strRequestFrom = 'W'
		 BEGIN
		   IF @strLevel = '1'
		   BEGIN
			 SET @i_vcReportCategory ='Cash_ScripWise Summary'
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Cash_ScripWise Summary') 
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##ScripCode##','') 
		   END
			ELSE IF @strLevel = '2'
		   BEGIN
			 SET @i_vcReportCategory ='Cash_ScripWise Summary'
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Cash_ScripWise Summary') 
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##ScripCode##',@StrPlScripCode) 
		   END
		 END
		 ELSE
		 BEGIN
		   IF @strLevel = '1'
		   BEGIN
			 SET @i_vcReportCategory ='MCash_ScripWise Summary'
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Cash_ScripWise Summary') 
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##ScripCode##','') 
			 IF @strOption = 'PROFITLOSSSUMMARY'
			 BEGIN
			   SET @i_vcReportCategory ='MCash_Summary'
			   SET @CommanXMLString = @CommanXMLString+'<RequestSummary>Y</RequestSummary>'
			   SET @strOption = 'PROFITLOSS'
			 END
			 ELSE
			 BEGIN
			   SET @CommanXMLString = @CommanXMLString+'<RequestSummary>N</RequestSummary>'
			 END  
		   END
		   ELSE IF @strLevel = '2'
		   BEGIN
			 SET @i_vcReportCategory ='Cash_ScripWise Summary'
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Cash_ScripWise Summary') 
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##ScripCode##',@StrPlScripCode) 
		   END
		 END
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##','Market Rate') 
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##OptionBF##','N')	
	   END
	   ELSE IF @strPLSegment IN('DERV','COMM')
	   BEGIN
		 IF @strRequestFrom = 'W'
		 BEGIN
		   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##',@StrPlRateType) 
		   IF @strPLSegment = 'COMM'
		   BEGIN
		     SET @strPLSegment = 'DERV'
		     SET @CommanXMLString = @CommanXMLString+'<CommodityFlag>Y</CommodityFlag>'
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##ReportDisplay##','P')
	         SET @CommanXMLString = REPLACE(@CommanXMLString,'##Display##',@strReportDisplay)
			 SET @strCommFlag ='Y'
		   END
		   
           SET @CommanXMLString = @CommanXMLString+'<FIFOTag>'+ISNULL(@StrPlFIFOFlag,'')+'</FIFOTag>'
		   SET @CommanXMLString = @CommanXMLString+'<FIFOFlag>'+ISNULL(@StrPlFIFOTAG,'')+'</FIFOFlag>'
		   SET @CommanXMLString = REPLACE(@CommanXMLString,'##OptionBF##',@StrPlOptionBF)	
	       --SELECT @CommanXMLString
		  
		   IF @strLevel = '1'
		   BEGIN
			 SET @i_vcReportCategory ='DERV_Series Wise'
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Series Wise') 
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##ScripCode##','')
		   END
		   ELSE IF @strLevel = '2'
		   BEGIN
			 SET @i_vcReportCategory ='DERV_Series Wise Detail'
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Series Wise Detail') 
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##ScripCode##',@StrPlScripCode) 
		   END		   
		 END
		 ELSE
		 BEGIN
		   IF @strLevel = '1'
		   BEGIN
			 SET @i_vcReportCategory ='MDERV_Series Wise'
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Series Wise') 
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##ScripCode##','')
			  IF @strOption = 'PROFITLOSSSUMMARY'
			 BEGIN
			   SET @i_vcReportCategory ='MDERV_Summary'
			   SET @CommanXMLString = @CommanXMLString+'<RequestSummary>Y</RequestSummary>'
			   SET @strOption = 'PROFITLOSS'
			 END
			 ELSE
			 BEGIN
			   SET @CommanXMLString = @CommanXMLString+'<RequestSummary>N</RequestSummary>'
			 END  
		   END	 
		   ELSE IF @strLevel = '2'
		   BEGIN
			 SET @i_vcReportCategory ='DERV_Series Wise'
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Series Wise') 
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##ScripCode##',@StrPlScripCode) 
		   END
		 END
		 --SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##','Do not Valuate') 
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##','Closing Premium') 
		 
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##OptionBF##','Y')	
	   END
	   
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##',@strPLSegment)  
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##SettNo##','')  

	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##SettType##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Option112A##','')
	   
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ExchSeg##',@StrPlExchange)
	   --SELECT @CommanXMLString
	 END  
	 ELSE 
	 IF @strActionName = 'TradeWeb' and @strOption = 'LEDGER'
	 BEGIN
	   DECLARE @strLedgerReportType VARCHAR(500)='', @strIncludeMTF VARCHAR(1), @strLReportType VARCHAR(100)='',
	   @strLedgerAccountType VARCHAR(50)=''
	   
	   SELECT @strLReportType = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'ReportType'
	   
	   DECLARE @strSubBrokerGLCode VARCHAR(50)='' , @strSubBrokerDepositGL VARCHAR(50)=''
	   SELECT @strSubBrokerGLCode = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'SubBrokerGLCode'
	   
	   SELECT @strSubBrokerDepositGL = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'SubBrokerDepositGL'
	   
	   IF ISNULL(@strSubBrokerGLCode,'') <> ''
	   BEGIN
	     SET @CommanXMLString = @CommanXMLString+'<SubBrokerGLCode>'+@strSubBrokerGLCode+'</SubBrokerGLCode>'  
	   END
	   
	    IF ISNULL(@strSubBrokerDepositGL,'') <> ''
	   BEGIN
	     SET @CommanXMLString = @CommanXMLString+'<SubBrokerDepositGL>'+@strSubBrokerDepositGL+'</SubBrokerDepositGL>'  
	   END
	   
	   IF ISNULL(@strLReportType,'') = ''
	   BEGIN
		 SET @strLReportType = 'TradingAC'
	   END
	   
	   SET @CommanXMLString = @CommanXMLString+'<LedgerAccountType>'+@strLReportType+'</LedgerAccountType>'
	   
	   IF CHARINDEX('Margin',@strLReportType) > 0 AND CHARINDEX('TradingAC',@strLReportType) > 0
	   AND CHARINDEX('MTF',@strLReportType) > 0
	   BEGIN
		 SET @strLedgerAccountType = 'EX,EM,MTF,CX,CM'
	   END
	   ELSE IF CHARINDEX('MTF',@strLReportType) > 0 AND CHARINDEX('TradingAC',@strLReportType) > 0
	   BEGIN
		 SET @strLedgerAccountType = 'MTF,EX,CX'
	   END
	   ELSE IF CHARINDEX('MTF',@strLReportType) > 0 AND CHARINDEX('Margin',@strLReportType) > 0
	   BEGIN
		 SET @strLedgerAccountType = 'MTF,EM,CM'
	   END
	   ELSE IF CHARINDEX('TradingAC',@strLReportType) > 0 AND CHARINDEX('Margin',@strLReportType) > 0
	   BEGIN
		 SET @strLedgerAccountType = 'EX,EM,CX,CM'
	   END
	   ELSE IF CHARINDEX('MTF',@strLReportType) > 0 
	   BEGIN
		 SET @strLedgerAccountType = 'MTF'
	   END
	   ELSE IF CHARINDEX('Margin',@strLReportType) > 0 
	   BEGIN
		 SET @strLedgerAccountType = 'EM,CM'
	   END
	   ELSE IF CHARINDEX('TradingAC',@strLReportType) > 0 
	   BEGIN
		 SET @strLedgerAccountType = 'EX,CX'
	   END
	   
	   IF ISNULL(@strLReportType,'') = ''
	   BEGIN
		 SET @strLedgerAccountType = 'EX,EM,CM,CX'
	   END
	   
	   
	   IF ISNULL(@strLedgerReportType,'')=''
	   BEGIN
		 SET @strLedgerReportType = 'TradingAC' 
	   END
	   
	   if ISNULL(@strIncludeMTF,'')=''
	   BEGIN
		 SET @strIncludeMTF = 'Y' 
	   END
	   
	   IF @strRequestFrom = 'W'
	   BEGIN
		 IF @strLevel = '1'
		 BEGIN
		   SET @i_vcReportCategory ='Trading_Detail'
		   SET @i_vcReportCode = 'Ledger'
		   SET @CommanXMLString = @CommanXMLString+'<OnlyTag>Y</OnlyTag>'
		 END
		 ELSE IF @strLevel = '2'
		 BEGIN
		   DECLARE @LedLookUp VARCHAR(100)='', @bill1FromDate VARCHAR(10)=''
		   SELECT @LedLookUp = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'LookUp' 
		   SET @CommanXMLString = @CommanXMLString+'<LookUp>'+ISNULL(@LedLookUp,'')+'</LookUp>'
		   SET @i_vcReportCode = 'BILL'
		   IF SUBSTRING(@LedLookUp,3,1) ='C'
		   BEGIN
		     SELECT @bill1FromDate = se_stdt FROM Settlements(NOLOCK) 
             WHERE se_exchange+'/'+'C'+'/'+se_stlmnt+'/'+se_payoutdt = @LedLookUp
		 
		     IF @StrSummaryDT <= @bill1FromDate
		     BEGIN
 		       SET @i_vcReportCategory ='Cash_Summary_New'
		     END
		     ELSE 
		     BEGIN
 		       SET @i_vcReportCategory ='Cash_Summary'
		     END
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','CASH')  
		   END
		   ELSE IF SUBSTRING(@LedLookUp,3,1) IN('F','X')		   
		   BEGIN
		     IF SUBSTRING(@LedLookUp,1,1) ='M'
			 BEGIN
			   SET @CommanXMLString = @CommanXMLString+'<CommodityFlag>Y</CommodityFlag>'
			   SET @i_vcReportCategory ='Derv_Summary'
			 END
			 ELSE
			 BEGIN
			   SET @bill1FromDate = SUBSTRING(@LedLookUp,5,8)
			   IF @StrSummaryDT <= @bill1FromDate
		       BEGIN
 		         SET @i_vcReportCategory ='Derv_Summary_New'
		       END
		       ELSE 
		       BEGIN
 		         SET @i_vcReportCategory ='Derv_Summary'
		       END
			 END
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','DERV')  
		   END
		   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Summary') 
		   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##','') 
		   SET @CommanXMLString = REPLACE(@CommanXMLString,'##SettType##','')
		   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Option112A##','')
		   SET @CommanXMLString = REPLACE(@CommanXMLString,'##OptionBF##','')	
		   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ExchSeg##','')
		 END		 
	   END
	   ELSE IF @strRequestFrom = 'M'
	   BEGIN
		 SET @i_vcReportCategory ='MTrading_Detail'
		 SET @i_vcReportCode = 'Ledger'
		 --SET @CommanXMLString = @CommanXMLString+'<OnlyTag>Y</OnlyTag>'
	   END
	   
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ExchSeg##','')
	   IF @strLedgerReportType IN('TradingAC') 
	   BEGIN
		 SET @CommanXMLString = @CommanXMLString+'<AccountType>'+@strLedgerAccountType+'</AccountType>'
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','Trading') 
	   END 
	   ELSE
	   BEGIN
		 SET @CommanXMLString = @CommanXMLString+'<AccountType>EM,MTF,CX,CM</AccountType>'
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','DP') 
	   END 
	 END 
	 IF @strActionName = 'TradeWeb' and @strOption = 'LedgerBalance'
	 BEGIN
	   DECLARE @strLedgerBReportType VARCHAR(50)='', @strIncludeBMTF VARCHAR(1)
	   SELECT @strLedgerBReportType = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'ReportType'
	   SELECT @strIncludeBMTF = (CASE WHEN ParameterValue = 'true' THEN 'Y' 
	   WHEN ParameterValue = 'False' THEN 'N' else ParameterValue END) FROM @tbl_InputJSONTable WHERE ParameterName = 'IncludeMTF'
	   if ISNULL(@strLedgerBReportType,'')=''
	   BEGIN
		 SET @strLedgerBReportType = 'Trading' 
	   END
	   
	   if ISNULL(@strIncludeBMTF,'')=''
	   BEGIN
		 SET @strIncludeBMTF = 'Y' 
	   END
	   IF @strRequestFrom = 'W'
	   BEGIN
		 SET @i_vcReportCategory ='Trading_Detail'
	   END
	   ELSE IF @strRequestFrom = 'M'
	   BEGIN
		 SET @i_vcReportCategory ='MTrading_Detail'
	   END
	   
	   SET @i_vcReportCode = 'LedgerBalance'
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ExchSeg##','')
	   IF @strLedgerReportType IN('Trading') 
	   BEGIN
		 IF ISNULL(@strIncludeBMTF,'N') = 'Y'
		 BEGIN
		   SET @CommanXMLString = @CommanXMLString+'<AccountType>EM,MTF,CX,CM</AccountType>'
		 END
		 ELSE
		 BEGIN
		   SET @CommanXMLString = @CommanXMLString+'<AccountType>EM,CX,CM</AccountType>'
		 END 		 
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','Trading') 
	   END 
	   ELSE
	   BEGIN
		 SET @CommanXMLString = @CommanXMLString+'<AccountType>EM,MTF,CX,CM</AccountType>'
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','DP') 
	   END 
	 END 
	 ELSE
	 IF @strActionName = 'TradeWeb' and @strOption = 'DASHBOARD'
	 BEGIN
	  declare @dsUserid VARCHAR(50)='', @dsReportType VARCHAR(50)='', @dsTag VARCHAR(100)='', @dsDescName VARCHAR(100)=''
	  SELECT @dsUserid = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Userid'
	  SELECT @dsReportType = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'ReportType'
	  SELECT @dsTag = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Tag'
	  SELECT @dsDescName = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'DescName'
	  SET @CommanXMLString = '<UserId>'+@dsUserid+'</UserId><RepType>'+@dsReportType+'</RepType><Tag>'+@dsTag+'</Tag><DescName>'+@dsDescName+'</DescName>'
	  SET @strNewVal = 2
	  SET @i_vcReportCategory ='TRADING'
	  SET @i_vcReportCode = 'DASHBOARD'
	 END 
	 ELSE
	 IF @strActionName = 'TradeWeb' and @strOption = 'HOLDING'
	 BEGIN
		DECLARE @OSProduct VARCHAR(20)=''
		SELECT @OSProduct = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Product'
		
		IF ISNULL(@OSProduct,'') = ''
		BEGIN
		  SET @OSProduct = 'Trading'
		END	 
		
		IF ISNULL(@OSProduct,'') = 'Trading'
		BEGIN
		  SET @i_vcReportCategory = 'Trading'
		END	 
		ELSE IF ISNULL(@OSProduct,'') = 'DP'
		BEGIN
		  SET @i_vcReportCategory ='DP'
		END
		
		IF @strRequestFrom = 'W'
		BEGIN
		  SET @i_vcReportCode = 'CombinedHolding'
		  --SET @i_vcReportCategory ='TRADING'
		END
		
		ELSE IF @strRequestFrom = 'M'
		BEGIN
		   IF @strLevel = '1'
		   BEGIN
			 SET @i_vcReportCode = 'CombinedHolding'
			 SET @i_vcReportCategory ='MTRADING'
		   END
		   ELSE IF @strLevel = '2'
		   BEGIN
			 SET @i_vcReportCode = 'CombinedHolding'
			 SET @i_vcReportCategory ='TRADING'
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##ScripCode##',@StrPlScripCode)
		   END
		END		
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ExchSeg##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##',@OSProduct)
	   --select @CommanXMLString
	 END  	
	 ELSE
	 IF @strActionName = 'TradeWeb' and @strOption = 'OSPosition'
	 BEGIN
	   DECLARE @OSSegment VARCHAR(10)='', @ex varchar(100)='', @OSReportType VARCHAR(50)='', @Str1AsOnDate VARCHAR(20)='',
	   @OSSegment1 VARCHAR(50)=''
	   SELECT @OSSegment = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Segment'
	   
	   SELECT @OSReportType = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'ReportType'
	   
	   SET @OSSegment1 = @OSSegment
	   
	   SELECT @ex =@ex +','+ ces_Cd FROM CompanyExchangeSegments(NOLOCK) 
	   WHERE  RIGHT(CES_cD,1) =  (CASE WHEN @OSSegment = 'DERV' THEN 'F'
	   WHEN @OSSegment = 'CURR' THEN 'K'
	   WHEN @OSSegment = 'COMM' THEN 'X' ELSE '' END)
	   
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ExchSeg##',@ex) 
	   IF @strRequestFrom = 'W'
	   BEGIN
	     SELECT @Str1AsOnDate = LTRIM(RTRIM(ParameterValue)) FROM @tbl_InputJSONTable WHERE ParameterName = 'AsOnDate'
	     IF ISNULL(@OSSegment,'') = ''
		 BEGIN
		   SET @OSSegment = 'Position'
		 END
		 
		 IF @OSReportType = 'Position'
		 BEGIN
		   SET @i_vcReportCategory ='MOBILE'
		   SET @i_vcReportCode = 'OSPosition'
		   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','DERV') 
		   SET @CommanXMLString = @CommanXMLString+'<ReportName>OPENPOS</ReportName>'
		   SET @CommanXMLString = @CommanXMLString+'<AsDate>'+@Str1AsOnDate+'</AsDate>'
		   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Productcd##',@OSSegment1)
		 END 
		 IF @OSReportType = 'TRXN'
		 BEGIN
		   SET @i_vcReportCategory ='TRADING'
		   SET @i_vcReportCode = 'OSPosition'
		   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','DERV') 
		   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Productcd##',@OSSegment1) 
		 END
	   END
	   ELSE
	   BEGIN
		 SET @i_vcReportCategory ='MOBILE'
		 SET @i_vcReportCode = 'OSPosition'
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','DERV') 
		 SET @CommanXMLString = @CommanXMLString+'<ReportName>OPENPOS</ReportName>'
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##Productcd##',@OSSegment1)
	   END  
	   
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ExchSeg##','')
	   
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','Trading') 
	 END 
	 IF @strActionName = 'TradeWeb' and @strOption = 'Collateral'
	 BEGIN
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ExchSeg##','') 
	   SET @i_vcReportCategory ='Pledge'
	   SET @i_vcReportCode = 'COLLPOS'
	   SET @CommanXMLString = @CommanXMLString+'<ReportName>COLLPOS</ReportName>'
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','Trading') 
	 END 
	 
	 ELSE
	 IF @strActionName = 'TradeWeb' and @strOption = 'CGain'
	 BEGIN
	   DECLARE @strOption112A VARCHAR(1)='N', @strCGReportType VARCHAR(10)=''
	   
	   SET @i_vcReportCode = 'CaptialGain'
	   
	   SELECT @strOption112A = (case when ParameterValue = 'true' then 'Y'  
	   WHEN ParameterValue = 'False' THEN 'N' ELSE ParameterValue END)
	   FROM @tbl_InputJSONTable WHERE ParameterName = 'Option112A'
	   
	   if ISNULL(@strOption112A,'') = ''
	   BEGIN
		 SET @strOption112A = 'N'
	   END
	   SELECT @strCGReportType = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'ReportType'
	  
	  IF ISNULL(@strCGReportType,'') = ''
	   BEGIN
		 SET @strCGReportType = 'Summary'
	   END
	   
	   IF @strRequestFrom = 'M'
	   BEGIN
	     SET @strCGReportType = 'Summary'
	   END
	   
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ExchSeg##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','CASH') 
	   IF @strCGReportType = 'Detail'
	   BEGIN
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Actual PL_Detail') 
		 SET @i_vcReportCategory ='Actual PL_Detail'	 
		 SET @CommanXMLString = @CommanXMLString+'<POS>N</POS>'
	   END
	   ELSE
	   IF @strCGReportType = 'Summary'
	   BEGIN
		 IF @strRequestFrom = 'W'
		 BEGIN
		   IF @strLevel = '1'
		   BEGIN
			 SET @i_vcReportCategory ='Actual PL_Summary'	 
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Actual PL_Summary') 
			 SET @CommanXMLString = @CommanXMLString+'<POS>N</POS>'		
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##ScripCode##','') 
		   END	 
		   ELSE IF @strLevel = '2'
		   BEGIN
			 SET @i_vcReportCategory ='Actual PL_Detail'	 
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Actual PL_Detail') 
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##ScripCode##',@StrPlScripCode) 			 
			 SET @CommanXMLString = @CommanXMLString+'<POS>N</POS>'		
		   END	 
		 end
		 ELSE
		 IF @strRequestFrom = 'M'
		 BEGIN
		   IF @strLevel = '1'
		   BEGIN
			 SET @i_vcReportCategory ='MActual PL_Summary'
			 SET @CommanXMLString = @CommanXMLString+'<POS>N</POS>'		   
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Actual PL_Summary') 
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##ScripCode##','') 
		   END
		   ELSE IF @strLevel = '2'
		   BEGIN
			 SET @i_vcReportCategory ='Actual PL_Detail'
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Actual PL_Detail')	
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##ScripCode##',@StrPlScripCode) 			 
			 SET @CommanXMLString = @CommanXMLString+'<POS>N</POS>'		
		   END
		 END
	   END
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##','') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Option112A##',@strOption112A)
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ScripCode##','') 
	 END  
	 ELSE
	 IF @strActionName = 'TradeWeb' and @strOption = 'CGainListing'
	 BEGIN
	   SET @CommanXMLString = @CommanXMLString+'<ReportName>CapitalGain</ReportName>'
	   SET @i_vcReportCode = 'CapitalGain'
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ExchSeg##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','TradeListing') 
	   IF @strRequestFrom = 'W'
	   BEGIN
		SET @i_vcReportCategory ='TradeListing'	 
	   END
	   ELSE 
	   IF @strRequestFrom = 'M'
	   BEGIN
		 SET @i_vcReportCategory ='MTradeListing'
	   END

	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##','ItemWise') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Option112A##','')
	 END  
	 ELSE
	 IF @strActionName = 'TradeWeb' and @strOption = 'CGainHolding'
	 BEGIN
	   DECLARE @strCHOption112A VARCHAR(1)='N', @strCHReportType VARCHAR(10)=''
	   
	   SET @i_vcReportCode = 'CaptialGain'
	   SELECT @strCHOption112A = (case when ParameterValue = 'true' then 'Y'  
	   WHEN ParameterValue = 'False' THEN 'N' ELSE ParameterValue END) FROM @tbl_InputJSONTable WHERE ParameterName = 'Option112A'
	   SELECT @strCHReportType = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'ReportType'
	   
	   if ISNULL(@strCHOption112A,'') = ''
	   BEGIN
		 SET @strCHOption112A = 'N'
	   END
	   
	   IF ISNULL(@strCHReportType,'') = ''
	   BEGIN
		 SET @strCHReportType = 'Summary'
	   END
	   
	    IF @strRequestFrom = 'M'
		BEGIN
		  SET @strCHReportType = 'Summary'
		END
	   
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ExchSeg##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','CASH') 
	   IF @strCHReportType = 'Detail'
	   BEGIN
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Notional_Detail') 
		 SET @i_vcReportCategory ='Notional_Detail'	 
	   END
	   ELSE
	   IF @strCHReportType = 'Summary'
	   BEGIN
		 IF @strRequestFrom = 'W'
		 BEGIN
		   IF @strLevel = '1'
		   BEGIN
			 SET @i_vcReportCategory ='Notional_Summary'	 
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Notional_Summary')
		   END
		   ELSE IF @strLevel = '2'
		   BEGIN
			 SET @i_vcReportCategory ='Notional_Detail'	 
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Notional_Detail')
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##ScripCode##',@StrPlScripCode) 	
		   END
		 END
		 ELSE IF @strRequestFrom = 'M'
		 BEGIN
		   IF @strLevel = '1'
		   BEGIN
			 SET @i_vcReportCategory ='MNotional_Summary'	 
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Notional_Summary')
		   END
		   ELSE IF @strLevel = '2'
		   BEGIN
			 SET @i_vcReportCategory ='Notional_Detail'	 
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Notional_Detail')
			 SET @CommanXMLString = REPLACE(@CommanXMLString,'##ScripCode##',@StrPlScripCode) 	
		   END
		 END
	   END
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##','') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Option112A##',@strCHOption112A)
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ScripCode##','') 	
	 END 
	 ELSE
	 IF @strActionName = 'TradeWeb' and @strOption IN('Margin','AvailableMargin')
	 BEGIN
	   SET @i_vcReportCode = 'Margin_NEW'
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ExchSeg##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','CASH') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##','') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Option112A##','')
	   SET @i_vcReportCategory ='ShortFall'	 
	   SET @CommanXMLString = @CommanXMLString+'<ReportName>Margin_NEW</ReportName>'
	 END 
	 ELSE
	 IF @strActionName = 'TradeWeb' and @strOption IN('Margin1')
	 BEGIN
	   SET @i_vcReportCode = 'Margin1'
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ExchSeg##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','CASH') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##','') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Option112A##','')
	   SET @i_vcReportCategory ='ShortFall'	 
	   SET @CommanXMLString = @CommanXMLString+'<ReportName>Margin1</ReportName>'
	 END 
	 ELSE
	 IF @strActionName = 'TradeWeb' and @strOption IN('Margin2')
	 BEGIN
	   SET @i_vcReportCode = 'Margin2'
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ExchSeg##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','CASH') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##','') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Option112A##','')
	   SET @i_vcReportCategory ='ShortFall'	 
	   SET @CommanXMLString = @CommanXMLString+'<ReportName>Margin2</ReportName>'
	 END 
	 ELSE
	  IF @strActionName = 'TradeWeb' and @strOption = 'Download'
	  BEGIN
	   DECLARE @strDownloadSegment VARCHAR(50)=''
	   SELECT @strDownloadSegment = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Segment'
	   SET @i_vcReportCode = 'Download'
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ExchSeg##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##',@strDownloadSegment) 
	   
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##','') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Option112A##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Segment##','') 
	   DECLARE @strDocumentType VARCHAR(50)='', @strDocumentNo VARCHAR(50)='', @strdocReportType VARCHAR(50)=''
	   SELECT @strdocReportType = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'RepType'
	   
	   SELECT @strDocumentType = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'DocumentType'
	   SELECT @strDocumentNo = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'DocumentNo'
	   
	   IF @strDocumentType <> '' and @strRequestFrom = 'M'
	   BEGIN
		 SET @strDocumentType = ''
	   END
	  
	   IF ISNULL(@strDocumentNo,'') <> '' AND ISNULL(@strdocReportType,'') = ''
	   BEGIN
		 SET @strdocReportType = 'DOCUMENT'
	   END
	   ELSE IF ISNULL(@strDocumentNo,'') = '' AND ISNULL(@strdocReportType,'')  = ''
	   BEGIN
		 SET @strdocReportType = 'LIST'
	   END
	  
	   
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##',@strdocReportType) 
	   SET @CommanXMLString = @CommanXMLString+'<ReportName>Download</ReportName><DocumentType>'+@strDocumentType+'</DocumentType><DocumentNo>'+@strDocumentNo+'</DocumentNo>'
	   SET @i_vcReportCategory ='TRADING'	 
	 END 
	 ELSE
	  IF @strActionName = 'TradeWeb' and @strOption = 'IPO'
	  BEGIN
	   SET @i_vcReportCode = 'IPO'
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ExchSeg##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','') 
	   
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##','') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Option112A##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','') 
	   SET @CommanXMLString = @CommanXMLString+'<ReportName>IPO_GETDATA</ReportName>'
	   SET @i_vcReportCategory ='GETDATA'	 
	 END 
	 ELSE
	 IF @strActionName = 'TradeWeb' and @strOption in('CGainDiviend','CGainDividend')
	 BEGIN
	   SET @CommanXMLString = @CommanXMLString+'<ReportName>CapitalGain</ReportName>'
	   SET @i_vcReportCode = 'CapitalGain'
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ExchSeg##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','CASH') 
	   SET @i_vcReportCategory ='Dividend'	 
	   
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Dividend') 	   
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##','ItemWise') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Option112A##','')
	 END 
	 IF @strActionName = 'TradeListing' and @strOption = 'FIND'
	 BEGIN
	   DECLARE @strTRDReportType VARCHAR(20)=''
	   SELECT @strTRDReportType = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'RepType'
	   SET @CommanXMLString = @CommanXMLString+'<ReportName>TradeListing</ReportName>'
	   SET @i_vcReportCode = 'TradeListing'
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ExchSeg##','')
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##','') 
	   
	   IF @strTRDReportType = 'SUMMARY'
	   BEGIN
		 SET @i_vcReportCategory ='GET_SUMMARY'	 
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','SUMMARY') 	   
	   END
	   ELSE
	   BEGIN
		 SET @i_vcReportCategory ='GET_DETAIL'	 
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','DETAIL') 	   
	   END
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##','') 
	   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Option112A##','')
	 END 
	 ELSE
	 IF @strActionName = 'TradeWeb' and @strOption = 'Transaction'
	 BEGIN
	   DECLARE @strtrReportType VARCHAR(50)='Trades', @strtrReportView varchar(50)='ItemWise', @strtrSegment VARCHAR(50)='CASH'
	   SELECT @strtrReportType = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'ReportType'
	   SELECT @strtrReportView = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'ReportView'
	   SELECT @strtrSegment = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Segment'
	   
	   IF @strtrSegment = 'DERV'
	   BEGIN
		 SET @strtrSegment = 'FO'
	   END
	   
	   SET @CommanXMLString = @CommanXMLString+'<ReportName>Transaction</ReportName>'
	   SET @i_vcReportCode = 'Transaction'
	   
	   IF @strtrReportType = 'Trades'
	   BEGIN
	    IF @strtrReportView = 'Details' And @strtrSegment = 'FO'
		 BEGIN
		   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','TradeSummary') 	   
		   SET @i_vcReportCategory ='TradeSummary_DetailsFO'
		   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##',@strtrReportView) 
		 END
		 Else IF @strLevel = '1'
		 BEGIN
		   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','TradeSummary') 	   
		   SET @i_vcReportCategory ='TradeSummary_'+@strtrReportView	 
		   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##',@strtrReportView) 
		 END
		 ELSE IF @strLevel = '2' 		 
		 BEGIN
		   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','TradeSummary') 	   
		   SET @i_vcReportCategory ='TradeSummary_DateWise'	 
		   SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##','DateWise') 
		   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ScripCode##',@StrPlScripCode)
		 END
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##',@strtrSegment) 
	   END
	   ELSE
	   IF @strtrReportType = 'Deliveries'
	   BEGIN
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Deliveries') 	   
		 SET @i_vcReportCategory ='Deliveries_'+@strtrReportView	 
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##',@strtrReportView) 
	   END
	   ELSE
	   IF @strtrReportType = 'Receipts'
	   BEGIN
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Receipts') 	   
		 SET @i_vcReportCategory ='Receipts'
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##',@strtrReportView) 
	   END
	   ELSE
	   IF @strtrReportType = 'Payments'
	   BEGIN
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Payments') 	   
		 SET @i_vcReportCategory ='Payments'
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##',@strtrReportView) 
	   END
	   ELSE
	   IF @strtrReportType = 'GSTInvoice'
	   BEGIN
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','GSTInvoice') 	   
		 SET @i_vcReportCategory ='GSTInvoice'
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##',@strtrReportView) 
	   END
	   ELSE
	   IF @strtrReportType = 'GSTReversal'
	   BEGIN
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','GSTReversal') 	   
		 SET @i_vcReportCategory ='GSTReversal'
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##',@strtrReportView) 
	   END
	   ELSE
	   IF @strtrReportType = 'Journals'
	   BEGIN
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Journals') 	   
		 SET @i_vcReportCategory ='Journals'
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##',@strtrReportView) 
	   END
	   ELSE
	   IF @strtrReportType = 'Bills'
	   BEGIN
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','Bills') 	   
		 SET @i_vcReportCategory ='Bills'
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##',@strtrReportView) 
		 
	   END
	   ELSE
	   IF @strtrReportType = 'AGTS'
	   BEGIN
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepType##','AGTS') 	   
		 SELECT @i_vcReportCategory = 'AGTS_'+(CASE WHEN @strtrSegment = 'FX' THEN 'FO' ELSE @strtrSegment END)
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##RepSubType##',@strtrSegment+'_'+@strtrReportView) 
		 SET @CommanXMLString = REPLACE(@CommanXMLString,'##Product##',@strtrSegment) 
	   END
	 END 
   END
   
   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ScripCode##','')
   
   IF @i_vcReportCode IN('DP') OR ISNULL(@strCommFlag,'N') = 'Y'
   BEGIN
     SET @CommanXMLString = REPLACE(@CommanXMLString,'##OutputType##','G')
   END 	 
   ELSE  IF @i_vcReportCode <> 'DP' AND ISNULL(@strCommFlag,'N') = 'N'
   BEGIN
     SET @CommanXMLString = REPLACE(@CommanXMLString,'##OutputType##','X')
   END 	 
   SET @CommanXMLString = REPLACE(@CommanXMLString,'##Client##',@strCode)
   SET @CommanXMLString = REPLACE(@CommanXMLString,'##ReportDisplay##',ISNULL(@strReportDisplay,''))
   SELECT @vcXML = @CommanXMLString
   --SELECT @vcXML
   EXEC stpr_Rpt_GridReports @vcXML, @i_vcProjectCode, @i_vcReportCode, @i_vcReportCategory, @o_vcErrorFlag OUTPUT, @o_vcErrorMessage OUTPUT, @strNewVal
 END
END
GO

CREATE PROCEDURE [dbo].[stpr_Rpt_GridReports] @vcXML NVARCHAR(MAX)='', 
@i_vcProjectCode VARCHAR(50), 
@i_vcReportCode VARCHAR(50), @i_vcReportCategory VARCHAR(50), @o_vcErrorFlag VARCHAR(1) OUTPUT, @o_vcErrorMessage VARCHAR(MAX) OUTPUT,
@strNewVal INT = 0 WITH ENCRYPTION  
AS
BEGIN
 /*
 ///////////////////////////////////////////////////////////////////////////////////////////
 // Create By     : VAIBHAV GARG
 // Created Date  : 12-DEC-2023
 // Description   : 
 // Reviewed By   : 
 // Review Date   : 
 //////////////////////////////////////////////////////////////////////////////////////////
*/
 --- Parameter Declaration

  IF @vcXML = ''
  BEGIN
	SET @o_vcErrorFlag  = 'E'
	SET @o_vcErrorMessage = 'Please Send Input Parameter(s)'
	RETURN 1
  END 
  DECLARE @strString NVARCHAR(MAX)='',
	@OutputValue varchar(10)='',
	@outputmessage VARCHAR(MAX)='', @vcProcedureName VARCHAR(50)='', @strGridType VARCHAR(20)='', @SettReportDispType VARCHAR(1)='P',
	@strCompanyCode VARCHAR(1), @XMLData XML,  @strUserId VARCHAR(50)='', @strCommodityFlag VARCHAR(1)='',
	@strOActionName VARCHAR(50)='', @strOOption VARCHAR(50)='', @strLog VARCHAR(1)='N'
 
   SET @XMLData = CAST('<root>'+@vcXML+'</root>' AS XML)
 
  SELECT TOP 1 @vcProcedureName = ProcedureName,  @strGridType = ColumnType
  FROM tbl_ReportGridViewFormat (NOLOCK) 
  WHERE ProductCode = @i_vcProjectCode AND ReportCode = @i_vcReportCode AND ReportCategroy = @i_vcReportCategory;
  IF @vcProcedureName = ''
  BEGIN
	SELECT TOP 1 @vcProcedureName = ProcedureName ,  @strGridType = ColumnType
	FROM tbl_ReportGridViewFormat (NOLOCK) 
	WHERE ProductCode = '' AND ReportCode = @i_vcReportCode 
	AND ReportCategroy = @i_vcReportCategory;
  END
	
  SET @vcXML = REPLACE(@vcXML,'''','''''')
  declare @strClient VARCHAR(20)='', @strSFromDate VARCHAR(11)='', @strSToDate VARCHAR(11)=''
  
  SELECT @strCommodityFlag = ISNULL(x.value('(CommodityFlag)[1]', 'VARCHAR(1)'),'')
  FROM @XMLData.nodes('/root') AS XTbl(x) 	
  
  SELECT @strSFromDate = ISNULL(x.value('(FromDt)[1]', 'VARCHAR(20)'),''), 
  @strSToDate = ISNULL(x.value('(ToDt)[1]', 'VARCHAR(20)'),''), 
  @strUserId = ISNULL(x.value('(UserId)[1]', 'VARCHAR(500)'),''), 
  @SettReportDispType = ISNULL(x.value('(Display)[1]', 'VARCHAR(1)'),''),
  @strCompanyCode = ISNULL(x.value('(CompanyCode)[1]', 'VARCHAR(1)'),''),
  @strClient = ISNULL(x.value('(Client)[1]', 'VARCHAR(20)'),''),
  @strOActionName = ISNULL(x.value('(OActionName)[1]', 'VARCHAR(50)'),''),
  @strOOption = ISNULL(x.value('(OOption)[1]', 'VARCHAR(50)'),'')  
  FROM @XMLData.nodes('/root') AS XTbl(x) 	  
  
  SELECT @strLog = ISNULL(IsDebugEnabled,'N') 
  FROM tbl_GenericAPIDefinition(NOLOCK)
  WHERE ModuleName = @strOActionName
  AND FunctionName = @strOOption
  
  IF ISNULL(@strGridType,'') = 'DPGrid'
  BEGIN
    SET @strNewVal = 3
	DECLARE @strOP_DataBase VARCHAR(100)='', @strOP_Owner  VARCHAR(100)=''
	SELECT @strOP_DataBase = ltrim(rtrim(OP_DataBase)), @strOP_Owner = ltrim(rtrim(OP_Owner)) 
	FROM Other_Products(NOLOCK) WHERE OP_Product='Cross'
	AND OP_Status='A'
	IF ISNULL(@strOP_DataBase,'') = ''
	BEGIN
	  SELECT @strOP_DataBase = ltrim(rtrim(OP_DataBase)), @strOP_Owner = ltrim(rtrim(OP_Owner)) 
	  FROM Other_Products(NOLOCK) WHERE OP_Product='Estro'
	  AND OP_Status='A'
	END
	declare  @strClient1 VARCHAR(20)=''
	
    IF ISNULL(@SettReportDispType,'') = ''
    BEGIN
      SET @SettReportDispType = 'P'
    END 
    
	IF @i_vcReportCategory = 'DPTransactionStatement' AND @SettReportDispType NOT IN('D','E','A','X')
	BEGIN
	  SET @vcXML = @vcXML+'<JsonFormat>Y</JsonFormat>'
	END
	
	--SET @vcXML = @vcXML+'<CallingFrom>T</CallingFrom>'
	SET @strString = 'EXEC '+@strOP_DataBase+'.'+@strOP_Owner+'.' + @vcProcedureName + ' ''' + @vcXML + ''', @o_vcErrorFlag OUTPUT, @o_vcErrorMessage OUTPUT';
	--SELECT @strString
	IF @SettReportDispType IN('D','E','A','X')
	BEGIN
	  DECLARE @o_Message NVARCHAR(MAX)=''
	  EXEC stpr_TypestHeaderProc @strClient, 'DP', @strUserId, @strCompanyCode,  @o_Message OUTPUT
	  
	  IF LTRIM(RTRIM(@i_vcReportCategory)) IN('DPHolding')
	  BEGIN
	    SET @o_Message = REPLACE(@o_Message,'##ReportName##',@i_vcReportCategory+' As On Date '+CONVERT(VARCHAR(30), Cast(@strSFromDate as date), 103))
	  END
	  ELSE IF (@strSFromDate = @strSToDate)
	  BEGIN
	    SET @o_Message = REPLACE(@o_Message,'##ReportName##',@i_vcReportCategory+' As On Date '+ CONVERT(VARCHAR(30), Cast(@strSFromDate as date), 103))
	  END	
	  ELSE
	  BEGIN
	    SET @o_Message = REPLACE(@o_Message,'##ReportName##',@i_vcReportCategory+' '+ CONVERT(VARCHAR(30), Cast(@strSFromDate as date), 103) + ' to ' + CONVERT(VARCHAR(30), Cast(@strSToDate as date), 103))
	  END
	  
      SET @o_Message = REPLACE(@o_Message,'##Grid1##','')
      SET @o_Message = REPLACE(@o_Message,'##Grid2##','')
      SET @o_Message = REPLACE(@o_Message,'##Grid3##','')
      SET @o_Message = REPLACE(@o_Message,'##Grid4##','')
	  SET @o_Message = REPLACE(@o_Message,'##PageOrientation##','Portrait')
	  SET @o_Message = REPLACE(@o_Message,'##PageSize##','A4')
	  IF @SettReportDispType IN('E','D','X')
	  BEGIN
	    SET @o_Message = REPLACE(@o_Message,'##FormatGrid##','Grid1')
	  END 
      ELSE 
	  BEGIN
	    SET @o_Message = REPLACE(@o_Message,'##FormatGrid##','')
	  END 
	
      SET @o_Message = '<root>' + @o_Message + '</root>';
  
      DECLARE @xmlData3 XML = CAST(@o_Message AS XML);
	
	  DECLARE @DynamicColumns NVARCHAR(MAX);
    
	  SET  @DynamicColumns = '';
  
	
      WITH DistinctNodes AS (
      SELECT DISTINCT
       NodeName = X.n.value('local-name(.)', 'NVARCHAR(100)')
      FROM @xmlData3.nodes('/root/ClientDetail/*') AS X(n))
    
      SELECT @DynamicColumns = @DynamicColumns+','+
        'LTRIM(RTRIM(X1.value(''(' + XX.NodeName + ')[1]'', ''NVARCHAR(MAX)''))) AS [' + XX.NodeName + ']'
      FROM DistinctNodes XX
	  WHERE NodeName NOT IN('Grid2','Grid3','Grid4')
   
      SELECT @DynamicColumns = SUBSTRING(@DynamicColumns,2,LEN(@DynamicColumns)-1) 
  
      DECLARE @sql NVARCHAR(MAX);
      SET @sql = '
      SELECT ' + @DynamicColumns + '
      FROM @xmlData3.nodes(''/root/ClientDetail'') AS T(X1)';
  
      EXEC sp_executesql @sql, N'@xmlData3 XML', @xmlData3;
	
	  IF @SettReportDispType NOT IN('A')
	  BEGIN
	    SELECT ColumnName, ColumnHeading, ColumnWidth, ColumnAlignement, ColumnFormat, Columnstyle, DecimalPlace, ColumnTotal,
        ColumnHide = CASE WHEN Userid = '1' THEN 'Y' ELSE 'N'	END   
        FROM tbl_ReportGridViewFormat(NOLOCK) 
	    WHERE ReportCode = @i_vcReportCode AND ReportCategroy = @i_vcReportCategory
		AND ColumnVisible = '0'
        Order By Orderby
      END
	END

	--SELECT @strString
  END
  ELSE
  IF ISNULL(@strCommodityFlag,'') = 'Y'
  BEGIN
    SET @strNewVal = 3
    DECLARE @strOPcomm_DataBase VARCHAR(100)='', @strOPcomm_Owner  VARCHAR(100)=''
	SELECT @strOPcomm_DataBase = ltrim(rtrim(OP_DataBase)), @strOPcomm_Owner = ltrim(rtrim(OP_Owner)) 
	FROM Other_Products(NOLOCK) WHERE OP_Product='COMMEX'
	AND OP_Status='A'
	
	SET @strString = 'EXEC '+@strOPcomm_DataBase+'.'+@strOPcomm_Owner+'.' + @vcProcedureName + ' ''' + @vcXML + ''', @o_vcErrorFlag OUTPUT, @o_vcErrorMessage OUTPUT';
	
	IF ISNULL(@SettReportDispType,'') = ''
    BEGIN
      SET @SettReportDispType = 'P'
    END  
	
	IF @SettReportDispType IN('D','E','A','X')
	BEGIN 
	
	  DECLARE @o_Message1 NVARCHAR(MAX)=''
 
	  EXEC stpr_TypestHeaderProc @strClient, '', '', @strCompanyCode,  @o_Message1 OUTPUT
	  
	  IF @strSFromDate = @strSToDate
	  BEGIN
	    SET @o_Message1 = REPLACE(@o_Message1,'##ReportName##',REPLACE(@i_vcReportCategory,'DERV','Commodity')+' As On Date '+ CONVERT(VARCHAR(30), Cast(@strSFromDate as date), 103))
	  END	
	  ELSE
	  BEGIN
	    SET @o_Message1 = REPLACE(@o_Message1,'##ReportName##',REPLACE(@i_vcReportCategory,'DERV','Commodity')+' '+ CONVERT(VARCHAR(30), Cast(@strSFromDate as date), 103) + ' to ' + CONVERT(VARCHAR(30), Cast(@strSToDate as date), 103))
	  END
	  
      SET @o_Message1 = REPLACE(@o_Message1,'##Grid1##','')
      SET @o_Message1 = REPLACE(@o_Message1,'##Grid2##','')
      SET @o_Message1 = REPLACE(@o_Message1,'##Grid3##','')
      SET @o_Message1 = REPLACE(@o_Message1,'##Grid4##','')
	  SET @o_Message1 = REPLACE(@o_Message1,'##PageOrientation##','Portrait')
	  SET @o_Message1 = REPLACE(@o_Message1,'##PageSize##','A4')
	  IF @SettReportDispType IN('E','D','X')
	  BEGIN
	    SET @o_Message1 = REPLACE(@o_Message1,'##FormatGrid##','Grid1')
	  END 
      ELSE 
	  BEGIN
	    SET @o_Message1 = REPLACE(@o_Message1,'##FormatGrid##','')
	  END 
	
      SET @o_Message1 = '<root>' + @o_Message1 + '</root>';
  
      DECLARE @xmlData4 XML = CAST(@o_Message1 AS XML);
	
	  DECLARE @DynamicColumns1 NVARCHAR(MAX);
    
	  SET  @DynamicColumns1 = '';
  
	
      WITH DistinctNodes AS (
      SELECT DISTINCT
       NodeName = X.n.value('local-name(.)', 'NVARCHAR(100)')
      FROM @xmlData4.nodes('/root/ClientDetail/*') AS X(n))
    
      SELECT @DynamicColumns1 = @DynamicColumns1+','+
        'LTRIM(RTRIM(X1.value(''(' + XX.NodeName + ')[1]'', ''NVARCHAR(MAX)''))) AS [' + XX.NodeName + ']'
      FROM DistinctNodes XX
	  WHERE NodeName NOT IN('Grid2','Grid3','Grid4')
   
      SELECT @DynamicColumns1 = SUBSTRING(@DynamicColumns1,2,LEN(@DynamicColumns1)-1) 
  
      DECLARE @sql11 NVARCHAR(MAX);
      SET @sql11 = '
      SELECT ' + @DynamicColumns1 + '
      FROM @xmlData4.nodes(''/root/ClientDetail'') AS T(X1)';
  
      EXEC sp_executesql @sql11, N'@xmlData4 XML', @xmlData4;
	
	  IF @SettReportDispType NOT IN('A')
	  BEGIN
	    SELECT ColumnName = ColumnHeading, ColumnHeading, ColumnWidth, ColumnAlignement, ColumnFormat, Columnstyle, DecimalPlace, ColumnTotal,
        ColumnHide = CASE WHEN Userid = '1' THEN 'Y' ELSE 'N'	END   
        FROM tbl_ReportGridViewFormat(NOLOCK) 
	    WHERE ReportCode = @i_vcReportCode AND ReportCategroy = @i_vcReportCategory
		AND ColumnVisible = '0'
        Order By Orderby
      END
	END
	
	--SELECT @strString
  END 
  ELSE
  BEGIN
    IF @vcProcedureName = 'stpr_Rpt_HoldingNew'  
	AND EXISTS(SELECT 1 FROM USER_MASTER(NOLOCK) WHERE um_user_id = @strUserId)
	BEGIN
	  DECLARE @strClientString11 VARCHAR(MAX)='', @StrString12 NVARCHAR(MAX)
      SELECT @strClientString11 = DBO.fn_ReturnQueryAccess(@strUserid,'','')
	  DECLARE @tbl_date TABLE(LastUpdateDate DATE)
      IF ISNULL(@strClientString11,'') = ''
      BEGIN  
	    SET @strClientString11 = ''
      END	
      SET @StrString12 = 'Select MIN(X.MKTDT) from tbl_DBHoldingDtl(nolock) X, CLIENT_MASTER(NOLOCK) CM WHERE 1 = 1 AND X.ClientCode = CM.CM_CD AND ' +@strClientString11
      INSERT INTO @tbl_date(LastUpdateDate)
      EXEC(@StrString12)
	  IF NOT EXISTS(SELECT 1 FROM @tbl_date WHERE LastUpdateDate >= CAST(GETDATE() AS DATE))
	  BEGIN
	    SELECT [ErrorMessage] = 'BOD process is incomplete. Please run it to continue.', [ErrorFlag] = 'E'
	    RETURN 1
      END
	  ELSE
	  BEGIN
	    SET @vcProcedureName = 'stpr_Rpt_HoldingNew_BOD'
      END	  
	END
 --SELECT @i_vcProjectCode, @i_vcReportCode, @i_vcReportCategory,@vcProcedureName
	SET @strString = 'EXEC DBO.' + @vcProcedureName + ' ''' + @vcXML + ''', @o_vcErrorFlag OUTPUT, @o_vcErrorMessage OUTPUT';
  END
  
  BEGIN TRY
	IF @strNewVal = 0 
	BEGIN
	  IF EXISTS(SELECT 1 FROM tbl_ReportGridViewFormat(NOLOCK) 
	  WHERE ProductCode = @i_vcProjectCode AND ReportCode = @i_vcReportCode
	  AND ReportCategroy = @i_vcReportCategory)
	  BEGIN
		SELECT ColumnType, ColumnName, ColumnHeading, ColumnWidth, ColumnAlignement, ColumnFormat, 
		ColumnStyle, DecimalPlace, ColumnTotal, OrderBy--, DetailProductCode, DetailReportCode, DetailReportCategroy, Detailxml
		FROM tbl_ReportGridViewFormat(NOLOCK) 
		WHERE ProductCode = @i_vcProjectCode AND ReportCode = @i_vcReportCode
		AND ReportCategroy = @i_vcReportCategory
		ORDER BY ORDERBY  
	  END
	  ELSE	
	  BEGIN
		SELECT ColumnType, ColumnName, ColumnHeading, ColumnWidth, ColumnAlignement, ColumnFormat, 
		ColumnStyle, DecimalPlace, ColumnTotal, OrderBy--, DetailProductCode, DetailReportCode, DetailReportCategroy, Detailxml
		FROM tbl_ReportGridViewFormat(NOLOCK) 
		WHERE ProductCode = '' AND ReportCode = @i_vcReportCode
		AND ReportCategroy = @i_vcReportCategory
		ORDER BY ORDERBY  
	  END
	END

	IF ISNULL(@strLog,'N') = 'Y'	
	BEGIN
	  INSERT INTO tbl_GenericAPIDebugLog(ParentSerialNo, RequestSource, RequestUniqueID, RequestString, ResponseString, ExceptionMessage, UpdateBy, UpdateTimeStamp)
      VALUES(0,@strOActionName, @strOOption, @strString, 'DECLARE @o_vcErrorFlag VARCHAR(1) ='''', @o_vcErrorMessage VARCHAR(MAX) = ''''; SELECT @o_vcErrorFlag, @o_vcErrorMessage ','SP Execute',@strUserId,GETDATE())	  
	END
	
	EXEC sp_executesql @strString, N'@o_vcErrorFlag VARCHAR(1) OUTPUT, @o_vcErrorMessage VARCHAR(MAX) OUTPUT', @o_vcErrorFlag OUTPUT, @o_vcErrorMessage OUTPUT;
	
	DECLARE @strClientName VARCHAR(150)='',
	@strReportHeader VARCHAR(MAX)='', @AsOnDate VARCHAR(12)='', @ToDt VARCHAR(11)='',
	@RequestFrom VARCHAR(1)='', @StrMenuOption VARCHAR(100)='', @StrProduct VARCHAR(100)='', @trxRepType VARCHAR(MAX)='', @SettRepType VARCHAR(20)='',
	@SettUserType VARCHAR(50)='', @SettoptTurnover VARCHAR(50), @SettASEXTurnover VARCHAR(50), @SettAccountType VARCHAR(100)='',
	@SettSelectionDispType VARCHAR(20)='', @SettCodeDispType VARCHAR(50)='', @AsDate VARCHAR(50)='', @trx1RepType VARCHAR(100)='',
	@menuname1 VARCHAR(100)='', @Exchange VARCHAR(100)='', @StrepSubType VARCHAR(50)='', @StrepFIFOTag VARCHAR(10)='',
	@StrepOption112A VARCHAR(10)='', @strOutStandingType VARCHAR(100)='', @strOutProductcd VARCHAR(50)=''
	
	--SELECT @XMLData
	
	SELECT @strUserId = ISNULL(x.value('(UserId)[1]', 'VARCHAR(500)'),''),
	@AsOnDate = ISNULL(x.value('(AsOnDate)[1]', 'VARCHAR(12)'),''),
	@ToDt = ISNULL(x.value('(ToDt)[1]', 'VARCHAR(12)'),''),
	@RequestFrom = ISNULL(x.value('(RequestFrom)[1]', 'VARCHAR(1)'),''),
	@StrMenuOption = ISNULL(x.value('(MenuOption)[1]', 'VARCHAR(100)'),''),
	@StrProduct = ISNULL(x.value('(Product)[1]', 'VARCHAR(100)'),''),
	@trxRepType = ISNULL(x.value('(RepType)[1]', 'VARCHAR(100)'),''),
	@SettRepType = ISNULL(x.value('(SettNo)[1]', 'VARCHAR(100)'),''),
	@StrepFIFOTag = ISNULL(x.value('(FIFOFlag)[1]', 'VARCHAR(100)'),''),
	@SettUserType = ISNULL(x.value('(UserType)[1]', 'VARCHAR(100)'),''),
	@SettoptTurnover = ISNULL(x.value('(optTurnover)[1]', 'VARCHAR(100)'),''),
	@SettASEXTurnover = ISNULL(x.value('(ASEXTurnover)[1]', 'VARCHAR(100)'),''),
	@SettAccountType = ISNULL(x.value('(LedgerAccountType)[1]', 'VARCHAR(100)'),''),
	@SettReportDispType = ISNULL(x.value('(ReportDisplay)[1]', 'VARCHAR(1)'),''),
	@SettSelectionDispType = ISNULL(x.value('(SelectTag)[1]', 'VARCHAR(1)'),''),
	@SettCodeDispType = ISNULL(x.value('(SelectUsers)[1]', 'VARCHAR(50)'),''),
	@AsDate = ISNULL(x.value('(AsDate)[1]', 'VARCHAR(12)'),''),
	@trx1RepType = ISNULL(x.value('(ReportType)[1]', 'VARCHAR(100)'),''),
	@menuname1 = ISNULL(x.value('(MenuName)[1]', 'VARCHAR(100)'),''),
	@Exchange = ISNULL(x.value('(ExchSeg)[1]', 'VARCHAR(100)'),''),
	@StrepSubType = ISNULL(x.value('(RepSubType)[1]', 'VARCHAR(100)'),''),
	@StrepOption112A = ISNULL(x.value('(Option112A)[1]', 'VARCHAR(1)'),''),
	@strClient = ISNULL(x.value('(Client)[1]', 'VARCHAR(20)'),''),
	@strOutStandingType = ISNULL(x.value('(OutStandingType)[1]', 'VARCHAR(100)'),''),
	@strOutProductcd = ISNULL(x.value('(Productcd)[1]', 'VARCHAR(100)'),'')
	FROM @XMLData.nodes('/root') AS XTbl(x) 	  


	
	IF ISNULL(@SettReportDispType,'P') = 'P'
	BEGIN
	  SET @SettReportDispType = 'P'
	END
	
	  DECLARE @strtag VARCHAR(50) = ''
	  
	  IF @i_vcReportCode = 'LEDGER'
	  BEGIN
		SET @strtag = 'Ledger'
	  END
	  ELSE IF @i_vcReportCode = 'CombinedHolding'
	  BEGIN
		SET @strtag = 'DPHolding'
	  END
	  ELSE IF @i_vcReportCode = 'OSPosition'
	  BEGIN
		SET @strtag = 'OSPosition'
	  END
	  ELSE IF @i_vcReportCode = 'InvestorReport'
	  BEGIN
		SET @strtag = 'ProfitLoss'
	  END
	  ELSE IF @i_vcReportCode IN('CaptialGain','CapitalGain','Transaction')
	  BEGIN
		SET @strtag = 'CapGain'
	  END
	  ELSE IF @i_vcReportCode IN('BILL')
	  BEGIN
		SET @strtag = 'Bill'
	  END
	  ELSE IF @i_vcReportCode IN('Margin','Margin_NEW','Margin1','Margin2')
	  BEGIN
		SET @strtag = 'Margin'
	  END
	  ELSE IF @i_vcReportCode IN('DP')
	  BEGIN
		SET @strtag = 'Detail'
	  END
	  else
	  BEGIN
		SET @strtag = @i_vcReportCode
	  END
	  --SELECT @o_vcErrorMessage
        IF ISNULL(@o_vcErrorMessage,'') NOT LIKE '%Process Executed%' 
	    BEGIN
	      BEGIN TRY 
	       EXEC stpr_GenerateMobileGrid @o_vcErrorMessage, @strtag, @i_vcReportCode, @i_vcReportCategory, @RequestFrom, @SettUserType, @SettReportDispType
	      END TRY
          BEGIN CATCH
	        PRINT '1'
          END CATCH	   
	    END  
	  
	  IF ISNULL(@o_vcErrorMessage,'') = ''
	  BEGIN
	    SET @strNewVal = 9
	  END
	  
	 IF @strNewVal IN(1,3)
	 BEGIN
	  DECLARE @TotalList VARCHAR(MAX)='', @RightList VARCHAR(MAX)='',@HideList VARCHAR(MAX)='',
	  @DateFormat VARCHAR(50)='DD-MMM-YYYY',@DateFormatList VARCHAR(MAX)='', @Dec2List VARCHAR(MAX)='', @Dec4List VARCHAR(MAX)='',
	  @DrCRColorList VARCHAR(MAX)='', @PnLColorList VARCHAR(MAX)='', @PrimaryKey VARCHAR(MAX)=''
	 
	  SELECT @TotalList = @TotalList+','+ColumnHeading
	  FROM tbl_ReportGridViewFormat(NOLOCK) 
	  WHERE ReportCode = @i_vcReportCode
	  AND ReportCategroy = @i_vcReportCategory
	  and ColumnTotal ='Y' 
	  AND ISNULL(ProductCode,'') = ''
	 -- AND (Productid = @RequestFrom OR Productid = '')
	  
	  SELECT @RightList = @RightList+','+ColumnHeading
	  FROM tbl_ReportGridViewFormat(NOLOCK) 
	  WHERE ReportCode = @i_vcReportCode
	  AND ReportCategroy = @i_vcReportCategory
	  and ColumnAlignement ='R'
	  AND ISNULL(ProductCode,'') = ''
	  --AND (Productid = @RequestFrom OR Productid = '')
	  
	  SELECT @DateFormatList = @DateFormatList+','+ColumnHeading
	  FROM tbl_ReportGridViewFormat(NOLOCK) 
	  WHERE ReportCode = @i_vcReportCode
	  AND ReportCategroy = @i_vcReportCategory
	  and ColumnFormat <> ''
	  AND ISNULL(ProductCode,'') = ''
	  --AND (Productid = @RequestFrom OR Productid = '')
	  
	  SELECT @Dec2List = @Dec2List+','+ColumnHeading
	  FROM tbl_ReportGridViewFormat(NOLOCK) 
	  WHERE ReportCode = @i_vcReportCode
	  AND ReportCategroy = @i_vcReportCategory
	  and DecimalPlace = 2
	  AND ISNULL(ProductCode,'') = ''
	  --AND (Productid = @RequestFrom OR Productid = '')
	  
	  SELECT @HIDEList = @HIDEList+','+ColumnHeading
	  FROM tbl_ReportGridViewFormat(NOLOCK) 
	  WHERE ReportCode = @i_vcReportCode
	  AND ReportCategroy = @i_vcReportCategory
	  and ColumnVisible = 1
	  AND ISNULL(ProductCode,'') = ''
	  --AND (Productid = @RequestFrom OR Productid = '')
	  
	  
	  SELECT @DrCRColorList = @DrCRColorList+','+ColumnHeading
	  FROM tbl_ReportGridViewFormat(NOLOCK) 
	  WHERE ReportCode = @i_vcReportCode
	  AND ReportCategroy = @i_vcReportCategory
	  and ColumnStyle = 'B'
	  AND ISNULL(ProductCode,'') = ''
	  --AND (Productid = @RequestFrom OR Productid = '')	
	  

	 DECLARE @MobileColumns VARCHAR(MAX)='', @TabletColumns VARCHAR(MAX)='',@WebColumns VARCHAR(MAX)=''
	 
	 SELECT @MobileColumns = @MobileColumns+','+ CASE WHEN ColumnType <> 'DPGRID' then ColumnHeading else ColumnName end
	 FROM tbl_ReportGridViewFormat(NOLOCK) 
	 WHERE ReportCode = @i_vcReportCode
	 AND ReportCategroy = @i_vcReportCategory
	 AND Productid = 'M'
	 and ColumnVisible = 0
	 AND ISNULL(ProductCode,'') = ''
	 and ((@settUserType = 'Client' and CASE WHEN ColumnType <> 'DPGRID' then ColumnHeading else ColumnName end not in('Client Code','Client Name'))
	 or @settUserType <> 'Client')
	 ORDER BY ORDERBY
	 
	 SET @MobileColumns = SUBSTRING(@MobileColumns,2,LEN(@MobileColumns))
	 
	 SELECT @TabletColumns = @TabletColumns+','+ CASE WHEN ColumnType <> 'DPGRID' then ColumnHeading else ColumnName end
	 FROM tbl_ReportGridViewFormat(NOLOCK) 
	 WHERE ReportCode = @i_vcReportCode
	 AND ReportCategroy = @i_vcReportCategory
	 AND Productid IN('T','M')
	 and ColumnVisible = 0
	 AND ISNULL(ProductCode,'') = ''
	 and ((@settUserType = 'Client' and CASE WHEN ColumnType <> 'DPGRID' then ColumnHeading else ColumnName end not in('Client Code','Client Name'))
	 or @settUserType <> 'Client')
	 ORDER BY ORDERBY
	 
	 SET @TabletColumns = SUBSTRING(@TabletColumns,2,LEN(@TabletColumns))
	 
	 SELECT @WebColumns = @WebColumns+','+CASE WHEN ColumnType <> 'DPGRID' then ColumnHeading else ColumnName end
	 FROM tbl_ReportGridViewFormat(NOLOCK) 
	 WHERE ReportCode = @i_vcReportCode
	 AND ReportCategroy = @i_vcReportCategory
	 and ColumnVisible = 0
	 AND ISNULL(ProductCode,'') = ''
	 and ((@settUserType = 'Client' and CASE WHEN ColumnType <> 'DPGRID' then ColumnHeading 
	 else ColumnName end not in('Client Code','Client Name'))
	 or @settUserType <> 'Client')
	 --AND Productid NOT IN('T','M')
	 ORDER BY ORDERBY
	 
	 SET @WebColumns = SUBSTRING(@WebColumns,2,LEN(@WebColumns))
		  
	  DECLARE @CompanyName VARCHAR(100) = Isnull((select em_name from Entity_Master with (nolock) 
	  where em_cd =(select min(em_cd) from Entity_master)),'')
	  DECLARE @CompanyAdd1 VARCHAR(1000) = '', @CompanyAdd2 VARCHAR(1000) = '', @CompanyAdd3 VARCHAR(1000) = ''

	  SELECT @CompanyName = em_name, @CompanyAdd1 = '', @CompanyAdd2 = '', @CompanyAdd3 = ''
	  FROM Entity_Master(NOLOCK) 
	  WHERE em_cd = (select min(em_cd) from Entity_master(NOLOCK))
	  
	  
	   /*SELECT @CompanyName = em_name, @CompanyAdd1 = em_add1, @CompanyAdd2 = em_add2, @CompanyAdd3 = em_add3+' '+em_add4 
	  FROM Entity_Master(NOLOCK) 
	  WHERE em_cd = (select min(em_cd) from Entity_master(NOLOCK))
	  */
	  
	  SELECT @strClientName = um_user_name FROM User_master(NOLOCK) WHERE um_user_id = @strUserId
	  
	  IF ISNULL(@strClientName,'') = ''
	  BEGIN
		SELECT @strClientName = CM_name FROM CLIENT_master(NOLOCK) WHERE CM_CD = @strUserId  
	  END
	  IF ISNULL(@ToDt,'') = ''
	  BEGIN
		SET @strReportHeader = replace(@menuname1,'_','') + ' As on Date - ' +CONVERT(VARCHAR(10), CAST(@AsOnDate AS DATE), 103)+ ' \n ' + RTRIM(@strClientName) + ' ( ' + RTRIM(@strUserId) +' )'
	  END
	  BEGIN
		SET @strReportHeader = replace(@menuname1,'_','') + ' From Date - ' +CONVERT(VARCHAR(10), CAST(@AsOnDate AS DATE), 103)+ ' to ' + CONVERT(VARCHAR(10), CAST(@ToDt AS DATE), 103) + ' \n ' + RTRIM(@strClientName) + ' ( ' + RTRIM(@strUserId) +' )'
	  END
	  
	  IF ISNULL(@strOutProductcd,'') <> ''
	  BEGIN
	    SET @StrProduct = @strOutProductcd
	  END
	  
	  SELECT @StrProduct = CASE WHEN @StrProduct = 'Derv' then 'Derivative' when @StrProduct = 'CASH' then 'Cash'
	  when @StrProduct = 'CURR' then 'Currency' ELSE @StrProduct END
	  
	  IF ISNULL(@strCommodityFlag,'') = 'Y' OR @StrProduct = 'COMM'
	  BEGIN
	    SET @StrProduct = 'Commodity'
	  END

	  DECLARE @StrShowFilter1 VARCHAR(MAX)='', @StrShowFilter2 VARCHAR(MAX)='', @StrShowFilter3 VARCHAR(MAX)=''
	  SELECT TOP 1 @StrShowFilter1 = ShowFilter1, @StrShowFilter2 = ShowFilter2, @StrShowFilter3 = ShowFilter3
	  FROM tbl_TradeWebMenu(NOLOCK) WHERE  MenuTag = @StrMenuOption
	  
	  IF ISNULL(@StrShowFilter1,'') = ''
	  SET @StrShowFilter1 = ''
	  
	  IF ISNULL(@StrShowFilter2,'') = ''
	  SET @StrShowFilter2 = ''
	  
	  IF ISNULL(@StrShowFilter3,'') = ''
	  SET @StrShowFilter3 = ''
	  
	  IF ISNULL(@SettSelectionDispType,'') <> ''
	  BEGIN
	    SELECT  @SettSelectionDispType = CASE WHEN @SettSelectionDispType = 'G' THEN 'Group'
	    WHEN @SettSelectionDispType = 'F' THEN 'Family'
	    WHEN @SettSelectionDispType = 'B' THEN 'Branch'
	    WHEN @SettSelectionDispType = 'C' THEN 'Client' else '' end
	  END 
	  
	  IF ISNULL(@AsDate,'') <> ''
	  BEGIN
	    SET @AsOnDate = @AsDate
	  END
	  
	
	  
	  SET @StrShowFilter1 = REPLACE(@StrShowFilter1,'<<SELECTION>>',ISNULL(@SettSelectionDispType,''))
      SET @StrShowFilter1 = REPLACE(@StrShowFilter1,'<<CODE>>',ISNULL(@SettCodeDispType,''))
	  
	  SET @StrShowFilter1 = REPLACE(@StrShowFilter1,'<<FROMDATE>>',ISNULL(CONVERT(VARCHAR(10), CAST(@AsOnDate AS DATE), 103),''))
	  SET @StrShowFilter1 = REPLACE(@StrShowFilter1,'<<TODATE>>',ISNULL(CONVERT(VARCHAR(10), CAST(@ToDt AS DATE), 103),''))
	  SET @StrShowFilter1 = REPLACE(@StrShowFilter1,'<<SEGMENT>>',ISNULL(@StrProduct,''))
	  SET @StrShowFilter1 = REPLACE(@StrShowFilter1,'<<RepType>>',ISNULL(@trxRepType,''))
	  SET @StrShowFilter1 = REPLACE(@StrShowFilter1,'<<SETTNO>>',ISNULL(@SettRepType,''))
	  
      SET @StrShowFilter2 = REPLACE(@StrShowFilter2,'<<FROMDATE>>',ISNULL(CONVERT(VARCHAR(10), CAST(@AsOnDate AS DATE), 103),''))
	  SET @StrShowFilter2 = REPLACE(@StrShowFilter2,'<<TODATE>>',ISNULL(CONVERT(VARCHAR(10), CAST(@ToDt AS DATE), 103),''))
	  SET @StrShowFilter2 = REPLACE(@StrShowFilter2,'<<SEGMENT>>',ISNULL(@StrProduct,''))
	  SET @StrShowFilter2 = REPLACE(@StrShowFilter2,'<<RepType>>',ISNULL(@trxRepType,''))
	  SET @StrShowFilter2 = REPLACE(@StrShowFilter2,'<<SETTNO>>',ISNULL(@SettRepType,''))
	  SET @StrShowFilter2 = REPLACE(@StrShowFilter2,'<<optTurnover>>',ISNULL(@SettoptTurnover,''))
	  SET @StrShowFilter2 = REPLACE(@StrShowFilter2,'<<LedgerReportType>>',ISNULL(@SettAccountType,''))
	  
	  SET @StrShowFilter2 = REPLACE(@StrShowFilter2,'<<SELECTION>>',ISNULL(@SettSelectionDispType,''))
      SET @StrShowFilter2 = REPLACE(@StrShowFilter2,'<<CODE>>',ISNULL(@SettCodeDispType,''))
	  
	  
	  SET @StrShowFilter3 = REPLACE(@StrShowFilter3,'<<FROMDATE>>',ISNULL(CONVERT(VARCHAR(10), CAST(@AsOnDate AS DATE), 103),''))
	  SET @StrShowFilter3 = REPLACE(@StrShowFilter3,'<<TODATE>>',ISNULL(CONVERT(VARCHAR(10), CAST(@ToDt AS DATE), 103),''))
	  
	  SET @StrShowFilter3 = REPLACE(@StrShowFilter3,'<<SEGMENT>>',ISNULL(@StrProduct,''))
	  SET @StrShowFilter3 = REPLACE(@StrShowFilter3,'<<RepType>>',ISNULL(@trxRepType,''))
	  SET @StrShowFilter3 = REPLACE(@StrShowFilter3,'<<SETTNO>>',ISNULL(@SettRepType,''))
	  SET @StrShowFilter3 = REPLACE(@StrShowFilter3,'<<ASEXTurnover>>',ISNULL(@SettASEXTurnover,''))
  
      SET @StrShowFilter3 = REPLACE(@StrShowFilter3,'<<SELECTION>>',ISNULL(@SettSelectionDispType,''))
      SET @StrShowFilter3 = REPLACE(@StrShowFilter3,'<<CODE>>',ISNULL(@SettCodeDispType,''))
	  
	  
	  IF CHARINDEX('<<RiskDate>>',@StrShowFilter1)>0 OR  CHARINDEX('<<RiskDate>>',@StrShowFilter2)>0 OR  CHARINDEX('<<RiskDate>>',@StrShowFilter3)>0
	  BEGIN
	    DECLARE @dtriskdate VARCHAR(10)=''
		SELECT @dtriskdate = max(rs_dt) FROM rms_summary WHERE Right(rs_CompanyCode, 1) NOT IN ('X', 'Z')
		SET @StrShowFilter1 = REPLACE(@StrShowFilter1,'<<RiskDate>>',ISNULL(CONVERT(VARCHAR,CAST(@dtriskdate AS DATE),103),''))
		SET @StrShowFilter2 = REPLACE(@StrShowFilter2,'<<RiskDate>>',ISNULL(CONVERT(VARCHAR,CAST(@dtriskdate AS DATE),103),''))
		SET @StrShowFilter3 = REPLACE(@StrShowFilter3,'<<RiskDate>>',ISNULL(CONVERT(VARCHAR,CAST(@dtriskdate AS DATE),103),''))
	  END
	  
      DECLARE @dpsql NVARCHAR(MAX)='', @dpdate VARCHAR(11)=''      
	  DECLARE @tbl_Data1 TABLE (Date1 VARCHAR(12))
	  IF CHARINDEX('<<RateDate>>',@StrShowFilter1)>0 OR  CHARINDEX('<<RateDate>>',@StrShowFilter2)>0 OR  CHARINDEX('<<RateDate>>',@StrShowFilter3)>0
      BEGIN
        SET @dpsql = 'SELECT max(rm_trx_date) from  '+@strOP_DataBase+'.'+@strOP_Owner+'.' +'Rate_master where rm_trx_date  <= '''+@AsOnDate+''''
		INSERT INTO @tbl_Data1
		EXEC(@dpsql)
		
		SELECT @dpdate = Date1 
		FROM @tbl_Data1
		SET @StrShowFilter1 = REPLACE(@StrShowFilter1,'<<RateDate>>',ISNULL(CONVERT(VARCHAR,@dpdate,103),''))
		SET @StrShowFilter2 = REPLACE(@StrShowFilter2,'<<RateDate>>',ISNULL(CONVERT(VARCHAR,@dpdate,103),''))
		SET @StrShowFilter3 = REPLACE(@StrShowFilter3,'<<RateDate>>',ISNULL(CONVERT(VARCHAR,@dpdate,103),''))
      END
      DELETE FROM @tbl_Data1
      IF CHARINDEX('<<HoldingDate>>',@StrShowFilter1)>0 OR  CHARINDEX('<<HoldingDate>>',@StrShowFilter2)>0 OR  CHARINDEX('<<HoldingDate>>',@StrShowFilter3)>0
      BEGIN
	    
        SET @dpsql = 'SELECT MAX(hld_hold_date) FROM '+@strOP_DataBase+'.'+@strOP_Owner+'.'+'Holding '
		INSERT INTO @tbl_Data1
		EXEC(@dpsql)
		SET @dpdate = ''
		SELECT @dpdate = Date1 
		FROM @tbl_Data1
		SET @StrShowFilter1 = REPLACE(@StrShowFilter1,'<<HoldingDate>>',ISNULL(CONVERT(VARCHAR,@dpdate,103),''))
		SET @StrShowFilter2 = REPLACE(@StrShowFilter2,'<<HoldingDate>>',ISNULL(CONVERT(VARCHAR,@dpdate,103),''))
		SET @StrShowFilter3 = REPLACE(@StrShowFilter3,'<<HoldingDate>>',ISNULL(CONVERT(VARCHAR,@dpdate,103),''))
      END

     IF ISNULL(@strOutStandingType,'') <> ''
	 Begin
       SET @StrShowFilter1 = REPLACE(@StrShowFilter1,'<<ReportType>>',ISNULL(@strOutStandingType,''))
	   SET @StrShowFilter2 = REPLACE(@StrShowFilter2,'<<ReportType>>',ISNULL(@strOutStandingType,''))
	   SET @StrShowFilter3 = REPLACE(@StrShowFilter3,'<<ReportType>>',ISNULL(@strOutStandingType,''))
	 END

     
     SET @StrShowFilter1 = REPLACE(@StrShowFilter1,'<<ReportType>>',ISNULL(@trx1RepType,''))
	 SET @StrShowFilter2 = REPLACE(@StrShowFilter2,'<<ReportType>>',ISNULL(@trx1RepType,''))
	 SET @StrShowFilter3 = REPLACE(@StrShowFilter3,'<<ReportType>>',ISNULL(@trx1RepType,''))
	 
	 SET @StrShowFilter1 = REPLACE(@StrShowFilter1,'<<Exchange>>',ISNULL(@Exchange,''))
	 SET @StrShowFilter2 = REPLACE(@StrShowFilter2,'<<Exchange>>',ISNULL(@Exchange,''))
	 SET @StrShowFilter3 = REPLACE(@StrShowFilter3,'<<Exchange>>',ISNULL(@Exchange,''))

	 SET @StrShowFilter1 = REPLACE(@StrShowFilter1,'<<Option112A>>',ISNULL(@StrepOption112A,''))
	 SET @StrShowFilter2 = REPLACE(@StrShowFilter2,'<<Option112A>>',ISNULL(@StrepOption112A,''))
	 SET @StrShowFilter3 = REPLACE(@StrShowFilter3,'<<Option112A>>',ISNULL(@StrepOption112A,''))
	 
	 

     
     IF @StrProduct IN('DERV','Derivative') AND @StrMenuOption = 'PROFITLOSS'
	 BEGIN
	   SET @StrShowFilter2 =  @StrShowFilter2+' / Rate Type :- '+ISNULL(@StrepSubType,'')+' / Rate :- '+ISNULL(@StrepFIFOTag,'')
	 END
	 
	 DECLARE @strClientName1 VARCHAR(100)=''
	 SELECT @strClientName1 = LTRIM(RTRIM(CM_NAME)) FROM CLIENT_MASTER(NOLOCK) WHERE CM_cD = @strClient
	 if ISNULL(@strClientName1,'') <> '' AND ISNULL(@strClient,'') <> ''
	 BEGIN
	   SET @StrShowFilter3 = ISNULL(@StrShowFilter3,'') +' Client Code :- '+@strClient+' / '+@strClientName1
	 END  

	 DECLARE @XMLStringFilter VARCHAR(MAX)=''
	  
	  --+'<WebColumns>'+ISNULL(@WebColumns,'')+'</WebColumns>'
	  
	  IF @RequestFrom = 'W'
	  BEGIN
		SET @XMLStringFilter = '<XmlData><TotalList>'+ISNULL(@TotalList,'')+'</TotalList>'
						+'<RightList>'+ISNULL(@RightList,'')+'</RightList>'
						+'<HideList>'+ISNULL(@HIDEList,'')+'</HideList>'
						+'<DateFormat>'+ISNULL(@DateFormat,'')+'</DateFormat>'
						+'<DateFormatList>'+ISNULL(@DateFormatList,'')+'</DateFormatList>'
						+'<Dec2List>'+ISNULL(@Dec2List,'')+'</Dec2List>'
						+'<Dec4List></Dec4List>'
						+'<DrCRColorList>'+ISNULL(@DrCRColorList,'')+'</DrCRColorList>'
						+'<PnLColorList></PnLColorList>'
						+'<PrimaryKey></PrimaryKey>'
						+'<CompanyName>' + ISNULL(@CompanyName,'') + '</CompanyName>'
						+'<CompanyAdd1>' + ISNULL(@CompanyAdd1,'') +'</CompanyAdd1>'
						+'<CompanyAdd2>' + ISNULL(@CompanyAdd2,'') + '</CompanyAdd2>'
						+'<CompanyAdd3>' + ISNULL(@CompanyAdd3,'') + '</CompanyAdd3>'
						+'<ReportHeader>'+ISNULL(@strReportHeader,'')+'</ReportHeader>'
						+'<PDFWidth>520</PDFWidth>'
						+'<PDFHeight>269</PDFHeight>'
						+'<MobileColumns>'+ISNULL(@MobileColumns,'')+'</MobileColumns>'
						+'<TabletColumns>'+ISNULL(@TabletColumns,'')+'</TabletColumns>'
						+'<Headings>'
	 END
	 ELSE IF @RequestFrom = 'M'
	 BEGIN
		SET @XMLStringFilter = '<XmlData>
						<Headings>'
	 END
	 
	 IF ISNULL(@StrShowFilter1,'') <> ''
	 BEGIN
	   SET @XMLStringFilter = @XMLStringFilter+'<Heading>'+@StrShowFilter1+'</Heading>'				
	 END                        
	 IF ISNULL(@StrShowFilter2,'') <> ''
	 BEGIN
	   SET @XMLStringFilter = @XMLStringFilter+'<Heading>'+@StrShowFilter2+'</Heading>'				
	 END                        
		
	 IF ISNULL(@StrShowFilter3,'') <> ''
	 BEGIN
	   SET @XMLStringFilter = @XMLStringFilter+'<Heading>'+@StrShowFilter3+'</Heading>'				
	 END                        
	 SET @XMLStringFilter = @XMLStringFilter+'</Headings></XmlData>' 
	 IF ISNULL(@StrShowFilter1,'') <> '' or ISNULL(@StrShowFilter2,'') <> '' or ISNULL(@StrShowFilter3,'') <> ''
	 BEGIN
	   SELECT [Settings] = @XMLStringFilter
	 END  
	 RETURN 1
	END
  END TRY
  BEGIN CATCH   
	 SET @o_vcErrorFlag  = 'E'
	SET @o_vcErrorMessage = ERROR_MESSAGE()
	RETURN 1  
  END CATCH
  RETURN 1
END
GO

CREATE PROCEDURE stpr_DashBoardBODProcess @strClient VARCHAR(20), @StrCompanyCode VARCHAR(1), @strUserType VARCHAR(50)='CLIENT', 
@strProcessType VARCHAR(50)='ALL' 
WITH ENCRYPTION
AS
BEGIN
   DECLARE @strString NVARCHAR(MAX)='' 
  IF @strUserType NOT IN('CLIENT','') AND @strProcessType IN('ALL','')
  BEGIN
    DELETE FROM tbl_DBCapitalGaindtl
    WHERE ClientCode IN(SELECT '~'+CLIENT_CODE FROM DBO.fn_GetClients(@strClient,'',''))
  
    INSERT INTO tbl_DBCapitalGaindtl(ClientCode, ScripCode, BuyQty, BuyRate, BuyValue,
    SaleQty, SaleRate, SaleValue, SP_TERM_PL, S_TERM_PL, L_TERM_PL, Mktdt)
    SELECT '~'+CLIENT_CODE, Scrip_Code ='', BuyQty = 0, BuyRate = 0, BuyValue = 0, SaleQty = 0, 
    SaleRate = 0, SaleValue = 0, SP_TERM_PL = 0, S_TERM_PL = 0, L_TERM_PL = 0, GETDATE() 
	FROM DBO.fn_GetClients(@strClient,'','')
  END
  
  DECLARE @FinancialYearStart DATE;
  DECLARE @FinancialYearEnd DATE;
  DECLARE @strtodate VARCHAR(20)=''
  
  SELECT @strtodate = MAX(FM_DT) FROM Fmargins(NOLOCK)
  
  DECLARE @InputDate DATE = @strtodate

  SET @FinancialYearStart = CASE WHEN MONTH(@InputDate) >= 4 THEN DATEFROMPARTS(YEAR(@InputDate), 4, 1) 
                            ELSE DATEFROMPARTS(YEAR(@InputDate) - 1, 4, 1) END;

  SET @FinancialYearEnd = DATEADD(DAY, -1, DATEADD(YEAR, 1, @FinancialYearStart));
  DECLARE @o_vcErrorFlag VARCHAR(1)='', @o_vcErrorMessage VARCHAR(MAX)='', 
  @vcXML NVARCHAR(MAX) = '<FromDt>'+CONVERT(VARCHAR,@FinancialYearStart,112)+'</FromDt><ToDt>'+@strtodate+'</ToDt><UserId>'+@strClient+'</UserId><Product></Product><SelectTag></SelectTag><SelectUsers></SelectUsers><OutputType>X</OutputType><SplFilter></SplFilter><RepType>Actual PL_Summary</RepType><Option112A>N</Option112A>'
  
  DECLARE @xml xml
  
  IF EXISTS(SELECT 1 FROM SYSOBJECTS WHERE NAME LIKE 'TRX_INVPL' AND TYPE='U')
  AND (ISNULL(@strProcessType,'') in('ALL','') OR CHARINDEX('CapitalGain-PL',@strProcessType) >0 )
  --AND ISNULL(@strProcessType,'') IN('ALL','','CapitalGain-PL')
  BEGIN
    EXEC stpr_Rpt_CapitalGain @vcXML, @o_vcErrorFlag OUTPUT, @o_vcErrorMessage OUTPUT
    SET @xml  = CAST(@o_vcErrorMessage AS XML)	
  
    --SELECT @o_vcErrorMessage
    --- CAPITAL GAIN START
  
    DECLARE @tbl_capitalGain TABLE(ClientCode VARCHAR(50), Scrip_Code VARCHAR(10), 
    BuyQty MONEY, BuyRate MONEY, BuyValue MONEY, SaleQty MONEY,
    SaleRate MONEY, SaleValue MONEY, SP_TERM_PL MONEY, S_TERM_PL MONEY, L_TERM_PL MONEY)

    INSERT INTO @tbl_capitalGain(ClientCode, Scrip_Code, BuyQty, BuyRate, BuyValue, SaleQty, SaleRate, SaleValue,
    SP_TERM_PL, S_TERM_PL, L_TERM_PL)
    SELECT CapGain.value('(ClientCode)[1]', 'VARCHAR(50)') AS ClientCode ,
    CapGain.value('(Scrip_Code)[1]', 'VARCHAR(50)') AS ScripCode ,
	CapGain.value('(BuyQty)[1]', 'MONEY') AS BuyQty ,
	CapGain.value('(BuyRate)[1]', 'MONEY') AS BuyRate ,
	CapGain.value('(BuyValue)[1]', 'MONEY') AS BuyValue ,
	CapGain.value('(SaleQty)[1]', 'MONEY') AS SaleQty ,
	CapGain.value('(SaleRate)[1]', 'MONEY') AS SaleRate ,
	CapGain.value('(SaleValue)[1]', 'MONEY') AS SaleValue ,
    CapGain.value('(SP_TERM_PL)[1]', 'MONEY') AS SP_TERM_PL,
	CapGain.value('(S_TERM_PL)[1]', 'MONEY') AS S_TERM_PL,
	CapGain.value('(L_TERM_PL)[1]', 'MONEY') AS L_TERM_PL
    FROM @xml.nodes('/CapGain') AS XTbl(CapGain)

    IF ISNULL(@strClient,'') <> ''
    BEGIN
	  IF @strUserType = 'CLIENT' 
	  BEGIN
        DELETE FROM tbl_DBCapitalGaindtl
        WHERE ClientCode = @strClient;
	  END
	  ELSE IF @strUserType <> 'CLIENT' 
	  BEGIN
	    DELETE FROM tbl_DBCapitalGaindtl
        WHERE ClientCode IN(SELECT CLIENT_CODE FROM DBO.fn_GetClients(@strClient,'',''))
      END
    END
    ELSE
    BEGIN
      TRUNCATE TABLE tbl_DBCapitalGaindtl;
    END
  
    INSERT INTO tbl_DBCapitalGaindtl(ClientCode, ScripCode, BuyQty, BuyRate, BuyValue,
    SaleQty, SaleRate, SaleValue, SP_TERM_PL, S_TERM_PL, L_TERM_PL, Mktdt)
    SELECT ClientCode, Scrip_Code, BuyQty, BuyRate, BuyValue, SaleQty, SaleRate, SaleValue,
    SP_TERM_PL, S_TERM_PL, L_TERM_PL, GETDATE() FROM @tbl_capitalGain
	
  END
  ---- CAPITAL GAIN END

  --- START PROFIT AND LOSS DERV  
  IF (ISNULL(@strProcessType,'') in('ALL','') OR CHARINDEX('ProfilLoss-Derivative',@strProcessType) >0 )
  BEGIN
    SET @o_vcErrorMessage =''
    set @vcXML = '<FromDt>'+CONVERT(VARCHAR,@FinancialYearStart,112)+'</FromDt><ToDt>'+@strtodate+'</ToDt><ExchSeg></ExchSeg><UserId>'+@strClient+'</UserId><Product>DERV</Product><SelectTag></SelectTag><SelectUsers></SelectUsers><OutputType>X</OutputType><SplFilter></SplFilter><RepType>Series Wise</RepType><RepSubType>Closing Premium</RepSubType><OptionBF>Y</OptionBF><FIFOTag>N</FIFOTag>'
    EXEC stpr_Rpt_ProfitLossNewDerv @vcXML, @o_vcErrorFlag OUTPUT, @o_vcErrorMessage OUTPUT
    set @xml = CAST(@o_vcErrorMessage AS XML)	

    DECLARE @tbl_Profit TABLE(ClientCode VARCHAR(30), Exchange VARCHAR(1),  
    ScripCode VARCHAR(10), OpenQty MONEY, BuyQty MONEY, SaleQty MONEY, 
    ExQty MONEY, AsQty MONEY, NETQTY MONEY, RelPL MONEY, UnRelPL MONEY, MTM MONEY, Segment VARCHAR(1))

    IF ISNULL(@strClient,'') <> ''
    BEGIN
      IF @strUserType = 'CLIENT' 
	  BEGIN
	    DELETE FROM tbl_DBProfitLossDervdtl
        WHERE ClientCode = @strClient;
	  END
      ELSE IF @strUserType <> 'CLIENT' 
	  BEGIN
	    DELETE FROM tbl_DBProfitLossDervdtl
        WHERE ClientCode IN(SELECT CLIENT_CODE FROM DBO.fn_GetClients(@strClient,'',''))
      END
    END
    ELSE
    BEGIN
      TRUNCATE TABLE tbl_DBProfitLossDervdtl;
    END
  
    INSERT INTO @tbl_Profit(ClientCode, Exchange, ScripCode, OpenQty, BuyQty, SaleQty, ExQty, AsQty, NETQTY, RelPL,
    UnRelPL, MTM, Segment)
    SELECT CapGain.value('(ClientCode)[1]', 'VARCHAR(50)') AS ClientCode ,
    CapGain.value('(Exchange)[1]', 'VARCHAR(50)') AS Exchange ,
    CapGain.value('(seriesid)[1]', 'VARCHAR(50)') AS seriesid ,
	CapGain.value('(BF_QTY)[1]', 'MONEY') AS BF_QTY,
	CapGain.value('(BOT_QTY)[1]', 'MONEY') AS BOT_QTY,
	CapGain.value('(SOLD_QTY)[1]', 'MONEY') AS SOLD_QTY,
	CapGain.value('(EX_QTY)[1]', 'MONEY') AS EX_QTY,
	CapGain.value('(AS_QTY)[1]', 'MONEY') AS AS_QTY,
	CapGain.value('(NET_QTY)[1]', 'MONEY') AS NETQTY,
	CapGain.value('(RelPL)[1]', 'MONEY') AS RelPL,
	CapGain.value('(UnRelPL)[1]', 'MONEY') AS UnRelPL,
	CapGain.value('(MTM)[1]', 'MONEY') AS MTM,
	CapGain.value('(Segment)[1]', 'VARCHAR(1)') AS Segment
    FROM @xml.nodes('/ProfitLoss') AS XTbl(CapGain)

    INSERT INTO tbl_DBProfitLossDervdtl(ClientCode, Exchange, ScripCode, OpenQty, BuyQty, SaleQty, 
    ExQty, AsQty,NETQTY,RelPL,UnRelPL,Mktdt, MTM, Segment)
    SELECT ClientCode, Exchange, ScripCode, OpenQty, BuyQty, SaleQty, ExQty, AsQty, NETQTY, RelPL,
    UnRelPL, GETDATE(), MTM, Segment FROM @tbl_Profit
	
	
	DECLARE @strOPcomm_DataBase VARCHAR(100)='', @strOPcomm_Owner  VARCHAR(100)=''
	SELECT @strOPcomm_DataBase = ltrim(rtrim(OP_DataBase)), @strOPcomm_Owner = ltrim(rtrim(OP_Owner)) 
	FROM Other_Products(NOLOCK) WHERE OP_Product='COMMEX'
	AND OP_Status='A'
	
	IF ISNULL(@strOPcomm_DataBase,'') <> ''
	BEGIN
	  set @vcXML = '<FromDt>'+CONVERT(VARCHAR,@FinancialYearStart,112)+'</FromDt><ToDt>'+@strtodate+'</ToDt><ExchSeg></ExchSeg><UserId>'+@strClient+'</UserId><Product>DERV</Product><SelectTag></SelectTag><SelectUsers></SelectUsers><OutputType>X</OutputType><SplFilter></SplFilter><RepType>Series Wise</RepType><RepSubType>Closing Premium</RepSubType><OptionBF>Y</OptionBF><FIFOTag>N</FIFOTag>'
	  SET @strString = 'EXEC '+@strOPcomm_DataBase+'.'+@strOPcomm_Owner+'.stpr_Rpt_ProfitLossNewDerv' + ' ''' + @vcXML + ''', @o_vcErrorFlag OUTPUT, @o_vcErrorMessage OUTPUT';
	  
	  EXEC sp_executesql @strString, N'@o_vcErrorFlag VARCHAR(1) OUTPUT, @o_vcErrorMessage VARCHAR(MAX) OUTPUT', @o_vcErrorFlag OUTPUT, @o_vcErrorMessage OUTPUT;
	  
	  set @xml = CAST(@o_vcErrorMessage AS XML)	
	  --select @o_vcErrorMessage
	  
	  DELETE FROM @tbl_Profit
	
	  INSERT INTO @tbl_Profit(ClientCode, Exchange, ScripCode, OpenQty, BuyQty, SaleQty, ExQty, AsQty, NETQTY, RelPL,
      UnRelPL, MTM, Segment)
    
	  SELECT CapGain.value('(ClientCode)[1]', 'VARCHAR(50)') AS ClientCode ,
      CapGain.value('(Exchange)[1]', 'VARCHAR(50)') AS Exchange ,
      ISNULL(CapGain.value('(seriesid)[1]', 'VARCHAR(50)'),'') AS seriesid ,
	  CapGain.value('(BF_QTY)[1]', 'MONEY') AS BF_QTY,
	  CapGain.value('(BOT_QTY)[1]', 'MONEY') AS BOT_QTY,
	  CapGain.value('(SOLD_QTY)[1]', 'MONEY') AS SOLD_QTY,
	  CapGain.value('(EX_QTY)[1]', 'MONEY') AS EX_QTY,
	  CapGain.value('(AS_QTY)[1]', 'MONEY') AS AS_QTY,
	  CapGain.value('(NET_QTY)[1]', 'MONEY') AS NETQTY,
	  CapGain.value('(RelPL)[1]', 'MONEY') AS RelPL,
	  CapGain.value('(UnRelPL)[1]', 'MONEY') AS UnRelPL,
	  CapGain.value('(MTM)[1]', 'MONEY') AS MTM,
	  CapGain.value('(Segment)[1]', 'VARCHAR(1)') AS Segment
      FROM @xml.nodes('/ProfitLoss') AS XTbl(CapGain)

      INSERT INTO tbl_DBProfitLossDervdtl(ClientCode, Exchange, ScripCode, OpenQty, BuyQty, SaleQty, 
      ExQty, AsQty,NETQTY,RelPL,UnRelPL,Mktdt, MTM, Segment)
      SELECT ClientCode, Exchange, ScripCode, OpenQty, BuyQty, SaleQty, ExQty, AsQty, NETQTY, RelPL,
      UnRelPL, GETDATE(), MTM, Segment FROM @tbl_Profit
    END
  END
  
  ---- END

  --  START NOTIONAL HOLDING
  IF EXISTS(SELECT 1 FROM SYSOBJECTS WHERE NAME LIKE 'TRX_INVPL' AND TYPE='U')
  --AND ISNULL(@strProcessType,'') IN('ALL','','CapitalGain-Holding')
  AND (ISNULL(@strProcessType,'') in('ALL','') OR CHARINDEX('CapitalGain-Holding',@strProcessType) >0)
  BEGIN
    SET @vcXML = '<FromDt></FromDt><ToDt>'+@strtodate+'</ToDt><UserId>'+@strClient+'</UserId><Product></Product>'
    +'<SelectTag></SelectTag><SelectUsers></SelectUsers><OutputType>X</OutputType><SplFilter></SplFilter><RepType>Notional_Summary</RepType>'
    +'<RepSubType></RepSubType><Option112A>N</Option112A>'
    SET @vcXML = REPLACE(@vcXML,'''','''''')
    SET @strString = 'EXEC DBO.stpr_Rpt_CapitalGainNotional' + ' ''' + @vcXML + ''', @o_vcErrorFlag OUTPUT, @o_vcErrorMessage OUTPUT';
    EXEC sp_executesql @strString, N'@o_vcErrorFlag VARCHAR(1) OUTPUT, @o_vcErrorMessage VARCHAR(MAX) OUTPUT', @o_vcErrorFlag OUTPUT, @o_vcErrorMessage OUTPUT;
  
    DECLARE @tbl_OpenPosition TABLE(td_SRNO INT, ClientCode VARCHAR(20), ScripCode VARCHAR(20), TradeDate VARCHAR(20),
    td_Stlmnt VARCHAR(20),
    BuyQty MONEY, BuyRate MONEY, BuyValue MONEY, CloseRate MONEY, CurrentValue MONEY, ShortTerm MONEY, 
    LongTerm MONEY)
    IF @o_vcErrorFlag = 'S'
    BEGIN
      SET @xml = CAST(@o_vcErrorMessage AS XML)
	  INSERT INTO @tbl_OpenPosition(td_SRNO, ClientCode, ScripCode, TradeDate, td_Stlmnt, BuyQty, BuyRate, BuyValue,
      CloseRate, CurrentValue, ShortTerm, LongTerm)
      SELECT CapGain.value('(td_SRNO)[1]', 'INT') AS td_SRNO,
	  CapGain.value('(ClientCode)[1]', 'VARCHAR(50)') AS ClientCode ,
      CapGain.value('(ScripCode)[1]', 'VARCHAR(50)') AS ScripCode ,
      CapGain.value('(TradeDate)[1]', 'VARCHAR(20)') AS TradeDate,
	  CapGain.value('(td_Stlmnt)[1]', 'VARCHAR(20)') AS td_Stlmnt,
      CapGain.value('(BuyQty)[1]', 'MONEY') AS BuyQty,
      CapGain.value('(BuyRate)[1]', 'MONEY') AS BuyRate,
      CapGain.value('(BuyValue)[1]', 'MONEY') AS BuyValue,
      CapGain.value('(CloseRate)[1]', 'MONEY') AS CloseRate,
      CapGain.value('(CurrentValue)[1]', 'MONEY') AS CurrentValue,
      CapGain.value('(ShortTerm)[1]', 'MONEY') AS ShortTerm,
	  CapGain.value('(LongTerm)[1]', 'MONEY') AS LongTerm
      FROM @xml.nodes('/CapGain') AS XTbl(CapGain)
    END  
  
    IF ISNULL(@strClient,'') <> ''
    BEGIN
      IF @strUserType = 'CLIENT' 
	  BEGIN
	    DELETE FROM tbl_DBCapitalGainHoldingdtl
        WHERE ClientCode = @strClient;
	  END
      ELSE IF @strUserType <> 'CLIENT' 
	  BEGIN
	    DELETE FROM tbl_DBCapitalGainHoldingdtl
        WHERE ClientCode IN(SELECT CLIENT_CODE FROM DBO.fn_GetClients(@strClient,'',''))
      END	  
    END
    ELSE
    BEGIN
      TRUNCATE TABLE tbl_DBCapitalGainHoldingdtl;
    END
  
    INSERT INTO tbl_DBCapitalGainHoldingdtl(ClientCode, ScripCode, TradeDate, BuyQty, BuyRate, BuyValue,
    CloseRate, CurrentValue, ShortTerm, LongTerm, Mktdt)
    SELECT ClientCode, ScripCode, ISNULL(CONVERT(VARCHAR,TradeDate,112),0),  BuyQty, BuyRate, BuyValue,
     CloseRate, CurrentValue, ShortTerm, LongTerm, GETDATE()
    FROM @tbl_OpenPosition WHERE ISNULL(ScripCode,'') <> ''
  END
  
  ---- END 
  IF (ISNULL(@strProcessType,'') in('ALL','') OR CHARINDEX('Holding',@strProcessType) >0)
  BEGIN
    DECLARE @TBL_Holding TABLE(ClientCode VARCHAR(20), ScripCode VARCHAR(10), ISIN VARCHAR(20), 
    FOCOLL money, Cuspa MONEY, DP MONEY, DP_POA MONEY, DP_NONPOA MONEY, EXPStk MONEY,
    UNDEL MONEY, MTFBENF MONEY, MTFCOLL MONEY, POOL MONEY, Ben MONEY, TotalQty MONEY,
    ClosingPrice MONEY, MarketValue MONEY, Haircut MONEY, NetValue MONEY)
     
    SET @vcXML ='<AsOnDate>'+@strtodate+'</AsOnDate><UserId>'+@strClient+'</UserId><Product>Trading</Product><SelectTag></SelectTag><SelectUsers></SelectUsers><OutputType>X</OutputType><SplFilter></SplFilter><CompanyCode>'+@StrCompanyCode+'</CompanyCode>'
    EXEC stpr_Rpt_HoldingNew @vcXML, @o_vcErrorFlag OUTPUT, @o_vcErrorMessage OUTPUT 
	   
    SET @xml = CAST(@o_vcErrorMessage AS XML)
    INSERT INTO @TBL_Holding(ClientCode, ScripCode, ISIN, FOCOLL, Cuspa, DP, DP_POA, DP_NONPOA, EXPStk,
    UNDEL, MTFBENF, MTFCOLL, POOL, Ben, TotalQty, ClosingPrice, MarketValue, Haircut, NetValue)
    SELECT X1.* FROM(
    SELECT DPHolding.value('(ClientCode)[1]', 'VARCHAR(50)') AS ClientCode ,
    DPHolding.value('(ScripCode)[1]', 'VARCHAR(100)') AS ScripCode ,
    DPHolding.value('(ISIN)[1]', 'VARCHAR(100)') AS ISIN,
    DPHolding.value('(FOCOLL)[1]', 'MONEY') AS FOCOLL,
    DPHolding.value('(Cuspa)[1]', 'MONEY') AS Cuspa,
    DPHolding.value('(DP)[1]', 'MONEY') AS DP,
    DPHolding.value('(DP_POA)[1]', 'MONEY') AS DP_POA,
    DPHolding.value('(DP_NONPOA)[1]', 'MONEY') AS DP_NONPOA,
    DPHolding.value('(EXP)[1]', 'MONEY') AS EXPStk,
    DPHolding.value('(UNDEL)[1]', 'MONEY') AS UNDEL,
    DPHolding.value('(MTFBENF)[1]', 'MONEY') AS MTFBENF,
    DPHolding.value('(MTFCOLL)[1]', 'MONEY') AS MTFCOLL,
    DPHolding.value('(POOL)[1]', 'MONEY') AS POOL,
    DPHolding.value('(Ben)[1]', 'MONEY') AS Ben,
    DPHolding.value('(TotalQty)[1]', 'MONEY') AS TotalQty,
    DPHolding.value('(ClosingPrice)[1]', 'MONEY') AS ClosingPrice,
    DPHolding.value('(MarketValue)[1]', 'MONEY') AS MarketValue,
    DPHolding.value('(Haircut)[1]', 'MONEY') AS Haircut,
    DPHolding.value('(NetValue)[1]', 'MONEY') AS NetValue
    FROM @xml.nodes('/DPHolding') AS XTbl(DPHolding)) X1
  
    IF ISNULL(@strClient,'') <> ''
    BEGIN
	  IF @strUserType = 'CLIENT' 
	  BEGIN
        DELETE FROM tbl_DBHoldingDtl
        WHERE ClientCode = @strClient;
	  END	
	  ELSE IF @strUserType <> 'CLIENT' 
	  BEGIN
	    DELETE FROM tbl_DBHoldingDtl
        WHERE ClientCode IN(SELECT CLIENT_CODE FROM DBO.fn_GetClients(@strClient,'',''))
      END
    END
    ELSE
    BEGIN
      TRUNCATE TABLE tbl_DBHoldingDtl;
    END
  
    INSERT INTO tbl_DBHoldingDtl(ClientCode, ScripCode, ISIN, FOCOLL, Cuspa, DP, DP_POA, DP_NONPOA, EXPStk,
    UNDEL, MTFBENF, MTFCOLL, POOL, Ben, TotalQty, ClosingPrice, MarketValue, Haircut, NetValue, Mktdt)
    SELECT ClientCode, ScripCode, ISIN, FOCOLL, Cuspa, DP, DP_POA, DP_NONPOA, EXPStk,
    UNDEL, MTFBENF, MTFCOLL, POOL, Ben, TotalQty, ClosingPrice, MarketValue, Haircut, NetValue, GETDATE()
    FROM @TBL_Holding
  END
  
  /*
  SET @vcXML = '<FromDt>'+CONVERT(VARCHAR,@FinancialYearStart,112)+'</FromDt><ToDt>'+CONVERT(VARCHAR,GETDATE(),112)+'></ToDt><ExchSeg></ExchSeg><UserId>'+@strClient+'</UserId><AccountType>EM,MTF,CX,CM</AccountType><Product>Trading</Product><SelectTag></Se
  lectTag><SelectUsers></SelectUsers><OutputType>X</OutputType><SplFilter></SplFilter><CompanyCode>'+@StrCompanyCode+'</CompanyCode>'
  EXEC stpr_Rpt_LedgerNew @vcXML , @o_vcErrorFlag OUTPUT, @o_vcErrorMessage OUTPUT
  SET @xml = CAST(@o_vcErrorMessage AS XML)
  	 
  DECLARE @TBL_Ledger TABLE(SerialNo int, ClientCode VARCHAR(20), TransactionDate VARCHAR(11), ExchSeg VARCHAR(20), 
  Voucher VARCHAR(20), Particular VARCHAR(500), DebitAmount MONEY, CreditAmount MONEY,
  Balance MONEY, BalanceTag VARCHAR(10))
  
  INSERT INTO @TBL_Ledger(SerialNo, ClientCode, TransactionDate, ExchSeg, Voucher, Particular,
  DebitAmount, CreditAmount, Balance, BalanceTag)
  SELECT Ledger.value('(SerialNo)[1]', 'int') AS SerialNo ,
  Ledger.value('(ClientCode)[1]', 'VARCHAR(50)') AS ClientCode ,
  Ledger.value('(Date)[1]', 'VARCHAR(11)') AS TransactionDate,
  Ledger.value('(ExchSeg)[1]', 'VARCHAR(100)') AS ExchSeg,
  Ledger.value('(Voucher)[1]', 'VARCHAR(100)') AS Voucher,
  Ledger.value('(Particular)[1]', 'VARCHAR(500)') AS Particular,
  Ledger.value('(DebitAmount)[1]', 'MONEY') AS DebitAmount,
  Ledger.value('(CreditAmount)[1]', 'MONEY') AS CreditAmount,
  Ledger.value('(Balance)[1]', 'MONEY') AS Balance,
  Ledger.value('(BalanceTag)[1]', 'VARCHAR(500)')
  FROM @xml.nodes('/Ledger') AS XTbl(Ledger)
  
  IF ISNULL(@strClient,'') <> ''
  BEGIN
    DELETE FROM tbl_DBLedgerBal
    WHERE ClientCode = @strClient;
  END
  ELSE
  BEGIN
    TRUNCATE TABLE tbl_DBLedgerBal;
  END
  
  INSERT INTO tbl_DBLedgerBal(ClientCode, TransactionDate, ExchSeg, Voucher, Particular,
  DebitAmount, CreditAmount, Balance, BalanceTag, Mktdt)
  SELECT ClientCode, TransactionDate, ExchSeg, Voucher, Particular,
  DebitAmount, CreditAmount, Balance, BalanceTag, GETDATE()
  FROM @TBL_Ledger
  ORDER BY TransactionDate, SerialNo
  */
  
END  
GO

CREATE PROCEDURE stpr_DashBoardFlashProcedure @dsXml VARCHAR(MAX)  
WITH ENCRYPTION AS
BEGIN 
  DECLARE @tbl_InputJSONTable DBO.tb_ParamList ;
  DECLARE @o_ParameterList varchar(max)='', @o_ParameterListxml XML; 
  DECLARE @tbl_UserList dbo.UserAccessList;
  DECLARE @StrCashActive VARCHAR(1) ='N', @StrfnoActive VARCHAR(1) ='N', @StrcURRActive VARCHAR(1) ='N'
  EXEC SP_ParameterXMLRep @dsXml, @o_ParameterList OUTPUT
  
  IF ISNULL(@o_ParameterList,'') <> ''
  BEGIN
	SET @o_ParameterListxml = CAST(@o_ParameterList AS XML)
	INSERT INTO @tbl_InputJSONTable (ParameterName,  ParameterValue, HeaderName, Jsontag) 
	SELECT Parameter.value('(ColumnName)[1]', 'VARCHAR(MAX)') AS Client_Code ,
	Parameter.value('(ColumnValue)[1]', 'VARCHAR(MAX)') AS ColumnValue,
	Parameter.value('(MasterTag)[1]', 'VARCHAR(MAX)') AS MasterTag,
	Parameter.value('(JsonLevel)[1]', 'VARCHAR(MAX)') AS JsonLevel
	FROM @o_ParameterListxml.nodes('/Parameter') AS XTbl(Parameter)
  END	  
  DECLARE @InputDate DATE = GETDATE(), @FinancialYearStart DATE='', @strUserCode varchar(40)=''
  
  SELECT @InputDate = MAX(FM_DT) FROM Fmargins(NOLOCK) 
  
  SET @FinancialYearStart = CASE WHEN MONTH(@InputDate) >= 4 THEN DATEFROMPARTS(YEAR(@InputDate), 4, 1) 
							ELSE DATEFROMPARTS(YEAR(@InputDate) - 1, 4, 1) END;
  
  DECLARE @StrRequestFrom VARCHAR(1)='M', @strJson VARCHAR(MAX)='', @strUserid VARCHAR(50)=''
  DECLARE @TBL_json TABLE(SerialNo int, Jsonvalue VARCHAR(MAX), ParentName VARCHAR(MAX))

  SELECT @strRequestFrom = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'RequestFrom'
  
  SELECT @strUserCode = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'ClientCode'
  
  SELECT @strUserid = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Userid'
  
  IF ISNULL(@strUserCode,'') <> ''
  BEGIN
	SET @strUserid = @strUserCode
  END
  
  DECLARE @strJsonMain VARCHAR(MAX)='', @strJsonMain1 VARCHAR(MAX)='', @strNetValue MONEY =  0,@strJsonMain2 VARCHAR(MAX)='',
  @strNetValue1 Money = 0, @strNetValue2 money = 0, @strJson1 VARCHAR(MAX)='', @strScripCount INT = 0
   
   
  SELECT @strScripCount = COUNT(ScripCode) FROM(
  SELECT ScripCode, COUNT(*) AS COUNT1 
  FROM tbl_DBCapitalGaindtl(NOLOCK)
  WHERE ClientCode = @strUserid
  GROUP BY ScripCode
  HAVING COUNT(*)  > 1) X1
  
  IF @strScripCount = 0
  BEGIN
    SELECT @strScripCount = COUNT(ScripCode) FROM(
    SELECT ScripCode, COUNT(*) AS COUNT1 
    FROM tbl_DBHoldingDtl(NOLOCK)
    WHERE ClientCode = @strUserid
    and FOCOLL > 0
    GROUP BY ScripCode
    HAVING COUNT(*)  > 1) X1
  END
  
  IF @strScripCount > 0
  BEGIN
	DELETE FROM tbl_DBCapitalGaindtl WHERE ClientCode LIKE '%'+ @strUserid
  END	
  
  IF NOT EXISTS(SELECT 1 FROM tbl_DBCapitalGaindtl(NOLOCK) WHERE ClientCode = '~'+@strUserid AND CAST(mktdt AS DATE) = CAST(GETDATE() AS DATE))
  BEGIN
		
	DELETE FROM tbl_DBCapitalGaindtl
	WHERE ClientCode = '~'+@strUserid;
  
	INSERT INTO tbl_DBCapitalGaindtl(ClientCode, ScripCode, BuyQty, BuyRate, BuyValue,
	SaleQty, SaleRate, SaleValue, SP_TERM_PL, S_TERM_PL, L_TERM_PL, Mktdt)
	SELECT '~'+@strUserid, Scrip_Code ='', BuyQty = 0, BuyRate = 0, BuyValue = 0, SaleQty = 0, 
	SaleRate = 0, SaleValue = 0, SP_TERM_PL = 0, S_TERM_PL = 0, L_TERM_PL = 0, GETDATE() 
  
	DECLARE @StrCompanyCode VARCHAR(1)= ISNULL((SELECT top 1 LTRIM(RTRIM(em_cd)) from Entity_master(NOLOCK) 
	WHERE em_cd =(select min(em_cd) from Entity_master(NOLOCK))),'A')
 
	DECLARE @StrCompanyCount INT = 0;
	SELECT @StrCompanyCount = ISNULL(SUM(ISNULL(cnt,0)),0) 
	FROM (SELECT COUNT(0) Cnt From Entity_master(NOLOCK) 
	WHERE em_bse <> 'N' and isNull(em_bclearingno,'') in ('189') 
	UNION ALL 
	SELECT count(0) Cnt From Entity_master(NOLOCK) 
	WHERE em_nse <> 'N' and isNull(em_nclearingno,'') in ('07277')) a
	IF @StrCompanyCount > 0
	BEGIN
	  SET @StrCompanyCode = 'B'
	END
	EXEC stpr_DashBoardBODProcess @strUserid, @StrCompanyCode,'CLIENT','ALL'
  END
   
  SET @strJsonMain1 = '[{"name": "","slogan": "","navigateTo": "", "boxSize":"full",
  "pieData": [{"name": "Available Margin","color": "black","navigateTo": "","textSize": 15,
  "gridItems": [{"label": {"pieColor": "#00008B","text": "Ledger", "size": 14,"color": "black","marginTop": 0},
  "value": {"pieColor": "#fff8e7","text": "##LNETVALUE##","size": 16,"color": "#4f4fe4","marginTop": 0},"navigateTo": "Ledger"},
  {"label": {"pieColor": "#1F75FE","text": "Pledge","size": 14,"color": "black","marginTop": 0},"value": {"text": "##PNETVALUE##","size": 16,"color": 
  "green","marginTop": 0},
  "navigateTo": "Collateral"},
  {"label": {"pieColor": "#1F75FE","text": "Total","size": 14,"color": "black","marginTop": 0,"showPie":false},"value": 
  {"text": "##TNETVALUE##","size": 16,"color": "##AMTcolor##","marginTop": 0},
  "navigateTo": ""}]}],
  "grids":[{"name":"Available Margin","color":"black","navigateTo":"","textSize":##textSize##,
	  "gridItems":[{"label":{"text":"Ledger","size":##label##,"color":"black","marginTop":0},
	  "value":{"text":"##LNETVALUE##","size":##text##,"color":"##Lcolor##","marginTop":0}, "navigateTo":"Ledger"},
			{"label":{"text":"Pledge","size":##label##,"color":"black","marginTop":0},
					  "value":{"text":"##PNETVALUE##","size":##text##,"color":"##Pcolor##","marginTop":0}, "navigateTo":"Collateral"},
					  {"label":{"text":"Total","size":##label##,"color":"black","marginTop":0},
					  "value":{"text":"##TNETVALUE##","size":##text##,"color":"##AMTcolor##","marginTop":0}}]},
					  {"name":"Margin","color":"black","navigateTo":"","textSize":##textSize##,
	  "gridItems":[{"label":{"text":"Margin Utilized","size":##label##,"color":"black","marginTop":0},
	  "value":{"text":"##MRRNETVALUE##","size":##text##,"color":"##MRRNETVALUEcolor##","marginTop":0},"navigateTo":"Margin1"},
					  {"label":{"text":"Available","size":##label##,"color":"black","marginTop":0},
					  "value":{"text":"##PLTMNETVALUE##","size":##text##,"color":"##PLTMNETVALUEcolor##","marginTop":0},"navigateTo":"Margin2"},
					  {"label":{"text":"Excess/Short","size":##label##,"color":"black","marginTop":0},
					  "value":{"text":"##ESTMNETVALUE##","size":##text##,"color":"##ESTMNETVALUEcolor##","marginTop":0},"navigateTo":"AvailableMargin"}]},'
  IF @StrRequestFrom = 'W'
  BEGIN
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'"Margin1"','""')
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'"Margin2"','""')
  END
  
  IF EXISTS(SELECT TOP 1 * FROM TRX(NOLOCK) WHERE td_clientcd = @strUserid)				  
  BEGIN
	SET @StrCashActive = 'Y'
	SET @strJsonMain1 = @strJsonMain1+' {"name":"Equity P/L","color":"black","navigateTo":"CGain","textSize":##textSize##,
	  "gridItems":[{"label":{"text":"Long Term","size":##label##,"color":"black","marginTop":0},
	  "value":{"text":"##LTNETVALUE##","size":##text##,"color":"##LTNETVALUEcolor##","marginTop":0}},
			{"label":{"text":"Short Term","size":##label##,"color":"black","marginTop":0},
					  "value":{"text":"##STNETVALUE##","size":##text##,"color":"##STNETVALUEcolor##","marginTop":0}},
					  {"label":{"text":"Trading","size":##label##,"color":"black","marginTop":0},
					  "value":{"text":"##TTNETVALUE##","size":##text##,"color":"##TTNETVALUEcolor##","marginTop":0}},
					  {"label":{"text":"Dividend","size":##label##,"color":"black","marginTop":0},
					  "value":{"text":"##DivNETVALUE##","size":##text##,"color":"##DivNETVALUEcolor##","marginTop":0},"navigateTo":"CGainDividend"},
					  {"label":{"text":"Total","size":##label##,"color":"black","marginTop":0},
					  "value":{"text":"##PTTNETVALUE##","size":##text##,"color":"##PTTNETVALUEcolor##","marginTop":0}}]},'
					  
	
	SELECT  @strNetValue2 = CONVERT(numeric(12,2),SUM(L_TERM_PL))  
	FROM tbl_DBCapitalGaindtl(NOLOCK) WHERE ClientCode = @strUserId
	
	
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##LTNETVALUE##',ISNULL(@strNetValue2,0))
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##LTNETVALUEcolor##',CASE WHEN @strNetValue2 < 0 THEN 'red' ELSE 'green' END)
	
	SET @strNetValue2 = 0
	SELECT  @strNetValue2 = CONVERT(numeric(12,2),SUM(S_TERM_PL))  
	FROM tbl_DBCapitalGaindtl(NOLOCK) WHERE ClientCode = @strUserId
	
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##STNETVALUE##',ISNULL(@strNetValue2,0))
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##STNETVALUEcolor##',CASE WHEN @strNetValue2 < 0 THEN 'red' ELSE 'green' END)
	
	SET @strNetValue2 = 0
	
	SELECT  @strNetValue2 = CONVERT(numeric(12,2),SUM(SP_TERM_PL))  
	FROM tbl_DBCapitalGaindtl(NOLOCK) WHERE ClientCode = @strUserId
	
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##TTNETVALUE##',ISNULL(@strNetValue2,0))
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##TTNETVALUEcolor##',CASE WHEN @strNetValue2 < 0 THEN 'red' ELSE 'green' END)
	  
	SET @strNetValue2 = 0
    
	IF EXISTS(SELECT 1 FROM SYSOBJECTS WHERE NAME LIKE 'INVPL_DIVIDEND' AND TYPE='U')
	BEGIN
	  SELECT @strNetValue2 = ISNULL(SUM(DV_Amount),0) 
	  FROM INVPL_DIVIDEND(NOLOCK)
	  WHERE DV_Amount > 0 AND DV_ClientCd = @strUserId
	  AND DV_Dt BETWEEN @FinancialYearStart AND @InputDate
	END  
	  
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##DivNETVALUE##',ISNULL(@strNetValue2,0))
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##DivNETVALUEcolor##',CASE WHEN @strNetValue2 < 0 THEN 'red' ELSE 'green' END)
	  
	  
	SELECT  @strNetValue2 = CONVERT(numeric(12,2),ISNULL(@strNetValue2,0)+SUM(ISNULL(SP_TERM_PL,0)+ISNULL(S_TERM_PL,0)+ISNULL(L_TERM_PL,0)))  
	FROM tbl_DBCapitalGaindtl(NOLOCK) WHERE ClientCode = @strUserId
	  
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##PTTNETVALUE##',ISNULL(@strNetValue2,0))
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##PTTNETVALUEcolor##',CASE WHEN @strNetValue2 < 0 THEN 'red' ELSE 'green' END)
						  
  END

  SET @strJsonMain1 = @strJsonMain1+' {"name":"Derivative P/L","color":"black","navigateTo":"PROFITLOSS","textSize":##textSize##, '
  IF EXISTS(SELECT TOP 1 * FROM trades(NOLOCK) WHERE td_clientcd = @strUserid AND td_Segment = 'F')				  
  BEGIN
	SET @StrfnoActive = 'Y'
	SET @strJsonMain1 = @strJsonMain1+' "gridItems":[{"label":{"text":"F&O","size":##label##,"color":"black","marginTop":0},
	  "value":{"text":"##FONETVALUE##","size":##text##,"color":"##FONETVALUEcolor##","marginTop":0}}, '
	  
	SET @strNetValue2 = 0
	
	SELECT @strNetValue2 = CONVERT(numeric(12,2),sum(MTM) )
	FROM tbl_DBProfitLossDervdtl(NOLOCK) WHERE ClientCode = @strUserId AND Segment = 'F' and Exchange <> 'M'
	
	
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##FONETVALUE##',ISNULL(@strNetValue2,0))
	
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##FONETVALUEcolor##',CASE WHEN @strNetValue2 < 0 THEN 'red' ELSE 'green' END)
  END
  ELSE
  BEGIN
	SET @strJsonMain1 = @strJsonMain1+' "gridItems":[{"label":{"text":"F&O","size":##label##,"color":"black","marginTop":0},
	  "value":{"text":"0","size":##text##,"color":"green","marginTop":0}}, '
  END
  
  IF EXISTS(SELECT TOP 1 * FROM trades(NOLOCK) WHERE td_clientcd = @strUserid AND td_Segment = 'K' and TD_EXCHANGE <> 'M' )				  
  BEGIN
	SET @StrcURRActive = 'Y'
	SET @strJsonMain1 = @strJsonMain1+'{"label":{"text":"Currency","size":##label##,"color":"black","marginTop":0},
					  "value":{"text":"##CURNETVALUE##","size":##text##,"color":"##CURNETVALUEcolor##","marginTop":0}},'
	SET @strNetValue2 = 0
	
	SELECT @strNetValue2 = CONVERT(numeric(12,2),sum(MTM) )
	FROM tbl_DBProfitLossDervdtl(NOLOCK) WHERE ClientCode = @strUserId AND Segment = 'K' and Exchange <> 'M'
	
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##CURNETVALUE##',ISNULL(@strNetValue2,0))
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##CURNETVALUEcolor##',CASE WHEN @strNetValue2 < 0 THEN 'red' ELSE 'green' END)
  END	
  
	
	
  DECLARE @strCommodityUser VARCHAR(50)='', @strActiveStatus VARCHAR(50)='', @String NVARCHAR(MAX)=''
  DECLARE @tbl_Commodity TABLE(ClientCode VARCHAR(50))
  SELECT @strCommodityUser = LTRIM(RTRIM(OP_DataBase)) 
  FROM Other_Products(NOLOCK) WHERE OP_Product='Commex' AND OP_Status = 'A'
	
  SET @String = 'SELECT top 1 td_clientcd FROM '+@strCommodityUser+'.DBO.trades(NOLOCK) WHERE  td_clientcd = '''+@strUserid+''' AND td_exchange = ''M'''
	
  INSERT INTO @tbl_Commodity(ClientCode)
  EXEC(@String)
	
  SELECT @strActiveStatus = ClientCode FROM @tbl_Commodity
	
  IF ISNULL(@strActiveStatus,'') <> ''
  BEGIN
	SET @strJsonMain1 = @strJsonMain1+'{"label":{"text":"MCX Commodity","size":##label##,"color":"black","marginTop":0},
					  "value":{"text":"##MCNETVALUE##","size":##text##,"color":"##MCNETVALUEcolor##","marginTop":0}},'
	SET @strNetValue2 = 0
	
	SELECT @strNetValue2 = CONVERT(numeric(12,2),sum(MTM) )
	FROM tbl_DBProfitLossDervdtl(NOLOCK) 
	WHERE ClientCode = @strUserId AND Exchange = 'M'

	
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##MCNETVALUE##',ISNULL(@strNetValue2,0))
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##MCNETVALUEcolor##',CASE WHEN @strNetValue2 < 0 THEN 'red' ELSE 'green' END)
  END	
	
  SET @strJsonMain1 = @strJsonMain1+'{"label":{"text":"Total","size":##label##,"color":"black","marginTop":0},
					  "value":{"text":"##CPTTNETVALUE##","size":##text##,"color":"##CPTTNETVALUEcolor##","marginTop":0}}]},'
  SET @strNetValue2 = 0
	
  SELECT @strNetValue2 = CONVERT(numeric(12,2),sum(MTM))
  FROM tbl_DBProfitLossDervdtl(NOLOCK) WHERE ClientCode = @strUserId
	--AND ScripCode <> '0'
  GROUP BY ClientCode
	
  SET @strJsonMain1 = REPLACE(@strJsonMain1,'##CPTTNETVALUE##',ISNULL(@strNetValue2,0))
  SET @strJsonMain1 = REPLACE(@strJsonMain1,'##CPTTNETVALUEcolor##',CASE WHEN @strNetValue2 < 0 THEN 'red' ELSE 'green' END)
						  
					  
  IF ISNULL(@StrCashActive,'N') = 'Y'
  BEGIN
	SET @strJsonMain1 = @strJsonMain1+'{"name":"Holding(Notional)","color":"black","navigateTo":"CGainHolding","textSize":##textSize##,
	  "gridItems":[{"label":{"text":"Invested","size":##label##,"color":"black","marginTop":0},
	  "value":{"text":"##INNETVALUE##","size":##text##,"color":"##INNETVALUEcolor##","marginTop":0}},
			{"label":{"text":"Current","size":##label##,"color":"black","marginTop":0},
					  "value":{"text":"##CUNETVALUE##","size":##text##,"color":"##CUNETVALUEcolor##","marginTop":0}},
					  {"label":{"text":"Long Term","size":##label##,"color":"black","marginTop":0},
					  "value":{"text":"##HLTNETVALUE##","size":##text##,"color":"##HLTNETVALUEcolor##","marginTop":0}},
					  {"label":{"text":"Short Term","size":##label##,"color":"black","marginTop":0},
					  "value":{"text":"##HSTNETVALUE##","size":##text##,"color":"##HSTNETVALUEcolor##","marginTop":0}},
					  {"label":{"text":"Total","size":##label##,"color":"black","marginTop":0},
					  "value":{"text":"##HTNETVALUE##","size":##text##,"color":"##HTNETVALUEcolor##","marginTop":0}}]},'
					  
	SET @strNetValue2 = 0
	
	SELECT  @strNetValue2 = CONVERT(numeric(12,2),sum(BuyValue) )  
	FROM tbl_DBCapitalGainHoldingdtl WHERE ClientCode = @strUserId 
	
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##INNETVALUE##',ISNULL(@strNetValue2,0))
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##INNETVALUEcolor##',CASE WHEN @strNetValue2 < 0 THEN 'red' ELSE 'green' END)
	
	SET @strNetValue2 = 0
	
	SELECT  @strNetValue2 = CONVERT(numeric(12,2),sum(CurrentValue) )  
	FROM tbl_DBCapitalGainHoldingdtl WHERE ClientCode = @strUserId 
	
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##CUNETVALUE##',ISNULL(@strNetValue2,0))
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##CUNETVALUEcolor##',CASE WHEN @strNetValue2 < 0 THEN 'red' ELSE 'green' END)
	
	SET @strNetValue2 = 0
	
	SELECT  @strNetValue2 = CONVERT(numeric(12,2),sum(LongTerm) )  
	FROM tbl_DBCapitalGainHoldingdtl WHERE ClientCode = @strUserId 
	
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##HLTNETVALUE##',ISNULL(@strNetValue2,0))
	
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##HLTNETVALUEcolor##',CASE WHEN @strNetValue2 < 0 THEN 'red' ELSE 'green' END)
	
	SET @strNetValue2 = 0
	
	SELECT  @strNetValue2 = CONVERT(numeric(12,2),sum(ShortTerm) )  
	FROM tbl_DBCapitalGainHoldingdtl WHERE ClientCode = @strUserId 
	
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##HSTNETVALUE##',ISNULL(@strNetValue2,0))
	
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##HSTNETVALUEcolor##',CASE WHEN @strNetValue2 < 0 THEN 'red' ELSE 'green' END)
	
	SET @strNetValue2 = 0
	
	SELECT  @strNetValue2 = CONVERT(numeric(12,2),sum(ShortTerm+LongTerm) )  
	FROM tbl_DBCapitalGainHoldingdtl WHERE ClientCode = @strUserId 
	
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##HTNETVALUE##',ISNULL(@strNetValue2,0))
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##HTNETVALUEcolor##',CASE WHEN @strNetValue2 < 0 THEN 'red' ELSE 'green' END)
  END
	 
  SET @strJsonMain1 = @strJsonMain1+'{"name":"Position (OBG)","color":"black","navigateTo":"","textSize":##textSize##,"gridItems":['
	 
  IF ISNULL(@StrCashActive,'N') = 'Y'
  BEGIN 
	SET @strJsonMain1 = @strJsonMain1+'{"label":{"text":"Cash","size":##label##,"color":"black","marginTop":0},
	"value":{"text":"##CSHNETVALUE##","size":##text##,"color":"##CSHNETVALUEcolor##","marginTop":0},"navigateTo":"Transaction"},'
	 
	SET @strNetValue2 = 0
	SELECT @strNetValue2 = SUM(CASE WHEN td_bsflag = 'B' THEN td_bqty*td_rate ELSE td_sqty * td_rate*-1 END)
	FROM TRX(NOLOCK) 
	WHERE td_clientcd = @strUserId
	AND TD_DT IN (SELECT MAX(TD_DT) FROM trx(NOLOCK))
	   
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##CSHNETVALUE##',ISNULL(@strNetValue2,0))
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##CSHNETVALUEcolor##',CASE WHEN @strNetValue2 < 0 THEN 'red' ELSE 'green' END)
			 
  END
	 
  IF ISNULL(@StrfnoActive,'N') = 'Y'
  BEGIN 
	SET @strJsonMain1 = @strJsonMain1+'{"label":{"text":"F&O","size":##label##,"color":"black","marginTop":0},
					  "value":{"text":"##FOHNETVALUE##","size":##text##,"color":"##FOHNETVALUEcolor##","marginTop":0},"navigateTo":"OSPosition"},'
	SET @strNetValue2 = 0
	
	--SELECT @strNetValue2 = ISNULL(SUM((ISNULL(po_postlongqty,0)-ISNULL(po_postshortqty,0))*po_settleprice),0)   
	SELECT @strNetValue2 = ISNULL(SUM(ISNULL(po_futvalue,0)+ISNULL(po_Diffvalue,0)+ISNULL(po_netpremium,0)),0)   
	FROM Fpositions(NOLOCK) X WHERE po_clientcd = @strUserId
	AND po_dt IN(SELECT MAX(po_dt) FROM Fpositions(NOLOCK) WHERE po_companycode = X.po_companycode 
	AND po_exchange = X.po_exchange AND po_Segment = X.po_Segment)
	--AND ISNULL(po_postlongqty,0)-ISNULL(po_postshortqty,0) <> 0
	AND po_Segment = 'F'
	   
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##FOHNETVALUE##',ISNULL(@strNetValue2,0))
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##FOHNETVALUEcolor##',CASE WHEN @strNetValue2 < 0 THEN 'red' ELSE 'green' END)
				  
  END					  
	 
  IF ISNULL(@StrcURRActive,'N') = 'Y'
  BEGIN 
	SET @strJsonMain1 = @strJsonMain1+'{"label":{"text":"Currency","size":##label##,"color":"black","marginTop":0},
					  "value":{"text":"##CUHNETVALUE##","size":##text##,"color":"##CUHNETVALUEcolor##","marginTop":0},"navigateTo":"OSPosition"}'
	SET @strNetValue2 = 0
	
	SELECT @strNetValue2 = ISNULL(SUM(ISNULL(po_futvalue,0)+ISNULL(po_Diffvalue,0)+ISNULL(po_netpremium,0)),0)  
	FROM Fpositions(NOLOCK) X WHERE po_clientcd = @strUserId
	AND po_dt IN(SELECT MAX(po_dt) FROM Fpositions(NOLOCK) WHERE po_companycode = X.po_companycode 
	AND po_exchange = X.po_exchange AND po_Segment = X.po_Segment)
	--AND ISNULL(po_postlongqty,0)-ISNULL(po_postshortqty,0) > 0
	AND po_Segment = 'K'
	
	
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##CUHNETVALUE##',ISNULL(@strNetValue2,0))
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##CUHNETVALUEcolor##',CASE WHEN @strNetValue2 < 0 THEN 'red' ELSE 'green' END)
  END
	 
  SET @strJsonMain1 = @strJsonMain1+']}]}]'
   
	---- LEDGER BALANCE
	
  SELECT @strNetValue = ISNULL(SUM(ld_Amount),0)*-1
  FROM Ledger(NOLOCK) WHERE ld_clientcd = @strUserId
	
  SET @strJsonMain1 = REPLACE(@strJsonMain1,'##LNETVALUE##',cast((ISNULL(@strNetValue,0)) as VARCHAR))
  SET @strJsonMain1 = REPLACE(@strJsonMain1,'##Lcolor##',CASE WHEN @strNetValue < 0 THEN 'red' ELSE 'green' END)
	
	---- Collateral BALANCE
	
  SELECT @strNetValue1 = SUM(round(((FOCOLL *ClosingPrice) * (100- Haircut))/100,2))
  FROM tbl_DBHoldingDtl(NOLOCK) WHERE  ClientCode = @strUserId
	
  SET @strJsonMain1 = REPLACE(@strJsonMain1,'##PNETVALUE##',cast(ISNULL(@strNetValue1,0) as VARCHAR))
  SET @strJsonMain1 = REPLACE(@strJsonMain1,'##Pcolor##',CASE WHEN @strNetValue1 < 0 THEN 'red' ELSE 'green' END)
	
	---- TOTAL AVAIABLE MARGIN
	
  SET @strJsonMain1 = REPLACE(@strJsonMain1,'##TNETVALUE##',cast(CONVERT(numeric(19,2),isnull(@strNetValue1,0))+
  CONVERT(numeric(19,2),isnull(@strNetValue,0)) as VARCHAR))
	 
  SET @strJsonMain1 = REPLACE(@strJsonMain1,'##AMTcolor##',CASE WHEN CONVERT(numeric(19,2),isnull(@strNetValue1,0))+
  CONVERT(numeric(19,2),isnull(@strNetValue,0)) < 0 THEN 'red' ELSE 'green' END)
	
  SET @strNetValue2 = 0
  DECLARE @TBL_MarginRequire TABLE(SerialNo int identity(1,1), TAG VARCHAR(50), Amount Money)
	
	
  IF ISNULL(@strCommodityUser,'') <> ''
  BEGIN
	DECLARE @strStringCOmm NVARCHAR(MAX)=''
	DECLARE @tbl_CommodityMargin TABLE(ClientCode VARCHAR(50), InitialMargin MONEY, MTMLOSS MONEY)
	   
	DECLARE @tbl_CommodityMTMMargin TABLE(ClientCode VARCHAR(50), MTMLOSS MONEY)
	   
	SET @strStringCOmm = 'SELECT fm_clientcd, (case fm_exchange When ''M'' Then fm_Regmargin + fm_exposurevalue + fm_buypremmargin else fm_initialmargin + fm_exposurevalue end) '
     +' fm_initialmargin,   case fm_Exchange When ''M'' Then fm_additionalmargin + fm_Tndmargin + fm_Dlvmargin - fm_SpreadBen + fm_ConcMargin + fm_DelvPMargin '
     +' else fm_additionalmargin + fm_SplMargin end+0 fm_MTMLoss '
     +' from '+@strCommodityUser+'.DBO.fmargins '
     +' Where fm_clientcd  = '''+@strUserId+''' AND fm_dt IN(SELECT MAX(fm_dt) FROM '+@strCommodityUser+'.DBO.fmargins) '
       
	INSERT INTO @tbl_CommodityMargin(ClientCode, InitialMargin, MTMLOSS)
	EXEC(@strStringCOmm)
	   
    SET @strStringCOmm = ' Select po_clientcd, case When -sum(po_futvalue) > 0 Then -sum(po_futvalue) else 0 end fm_MTMLoss '
	   +' FROM '+@strCommodityUser+'.DBO.Fpositions '
       +' Where po_clientcd  = '''+@strUserId+''' AND po_dt IN(SELECT MAX(po_dt) FROM '+@strCommodityUser+'.DBO.Fpositions) '
       +' Group by po_clientcd '
	   
	INSERT INTO @tbl_CommodityMTMMargin(ClientCode, MTMLOSS)
	EXEC(@strStringCOmm)
	   
	UPDATE A SET A.MTMLOSS = ISNULL(A.MTMLOSS,0) + ISNULL(B.MTMLOSS,0)
	FROM @tbl_CommodityMargin A, @tbl_CommodityMTMMargin B
	WHERE A.ClientCode = B.ClientCode
	   
  END	
  
  INSERT INTO @TBL_MarginRequire(TAG, Amount)
  SELECT TAG = '[Margin Require]', SUM(AMOUNT) AS AMOUNT FROM(
  SELECT Amount = fm_TotalMrgn
  FROM Fmargins(NOLOCK) WHERE fm_dt IN(SELECT MAX(fm_dt) FROM Fmargins(NOLOCK))
  AND fm_clientcd = @strUserId) X1
  UNION ALL
  SELECT TAG = '[Margin Require]', SUM(ISNULL(InitialMargin,0)+ISNULL(MTMLOSS,0)) AS AMOUNT 
  FROM @tbl_CommodityMargin WHERE ClientCode = @strUserId
  UNION ALL
  SELECT TAG = '[Ledger Balance]', Amount = SUM(LD_AMOUNT)*-1 FROM ledger(NOLOCK)
  WHERE ld_clientcd = @strUserId
  Group By ld_clientcd
  UNION ALL
  SELECT TAG = '[collateral Balance]', Amount = SUM(ROUND(((FOCOLL*ClosingPrice) * (100-Haircut))/100,2)) FROM tbl_DBHoldingDtl(NOLOCK)
  WHERE ClientCode = @strUserId
	

  SET @strNetValue2 = 0
  SELECT @strNetValue2 = AMOUNT FROM @TBL_MarginRequire WHERE TAG = '[Margin Require]'
	
  SET @strJsonMain1 = REPLACE(@strJsonMain1,'##MRRNETVALUE##',ISNULL(@strNetValue2,0))
  SET @strJsonMain1 = REPLACE(@strJsonMain1,'##MRRNETVALUEcolor##',CASE WHEN @strNetValue2 < 0 THEN 'red' ELSE 'green' END)
	
  SET @strNetValue2 = 0
  SELECT @strNetValue2 = AMOUNT FROM @TBL_MarginRequire WHERE TAG = '[Ledger Balance]'
	
  SET @strJsonMain1 = REPLACE(@strJsonMain1,'##CCMNETVALUE##',ISNULL(@strNetValue2,0))
  SET @strJsonMain1 = REPLACE(@strJsonMain1,'##CCMNETVALUEcolor##',CASE WHEN @strNetValue2 < 0 THEN 'red' ELSE 'green' END)
	
  SET @strNetValue2 = 0
  SELECT @strNetValue2 = AMOUNT FROM @TBL_MarginRequire WHERE TAG = '[collateral Balance]'
	
  SET @strJsonMain1 = REPLACE(@strJsonMain1,'##PLMNETVALUE##',ISNULL(@strNetValue2,0))
	
  SET @strJsonMain1 = REPLACE(@strJsonMain1,'##PLMNETVALUEcolor##',CASE WHEN @strNetValue2 < 0 THEN 'red' ELSE 'green' END)
	
  SET @strNetValue2 = 0
  SELECT @strNetValue2 = SUM(AMOUNT) FROM @TBL_MarginRequire WHERE TAG IN('[collateral Balance]','[Ledger Balance]')
	
  SET @strJsonMain1 = REPLACE(@strJsonMain1,'##PLTMNETVALUE##',ISNULL(@strNetValue2,0))
  SET @strJsonMain1 = REPLACE(@strJsonMain1,'##PLTMNETVALUEcolor##',CASE WHEN @strNetValue2 < 0 THEN 'red' ELSE 'green' END)
	
  SET @strNetValue2 = 0
  SELECT @strNetValue2 = SUM(CASE WHEN TAG ='[Margin Require]' THEN Amount*-1 ELSE AMOUNT END) 
  FROM @TBL_MarginRequire 
	
  SET @strJsonMain1 = REPLACE(@strJsonMain1,'##ESTMNETVALUE##',ISNULL(@strNetValue2,0))
  SET @strJsonMain1 = REPLACE(@strJsonMain1,'##ESTMNETVALUEcolor##',CASE WHEN @strNetValue2 < 0 THEN 'red' ELSE 'green' END)
  
  IF @StrRequestFrom = 'M'
  BEGIN
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##textSize##','13')
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##label##','12')
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##text##','14')
  END
  ELSE
  BEGIN
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##textSize##','25')
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##label##','12')
	SET @strJsonMain1 = REPLACE(@strJsonMain1,'##text##','15')
  END 	
  SELECT @strJsonMain1
END	
GO

CREATE PROCEDURE SP_RemoveMasterJsoninArray @inputJson NVARCHAR(MAX), @tagName VARCHAR(50), @outputJson NVARCHAR(MAX) OUTPUT
AS
BEGIN
   SELECT @outputJson = JSON_MODIFY(@inputJson, '$.Master', NULL);
   SELECT @outputJson = JSON_QUERY(@outputJson, '$.' + @tagName);
   RETURN 1
END
GO

CREATE PROCEDURE stpr_GetClientsFromMobile @dsXml VARCHAR(MAX) 
WITH ENCRYPTION  AS
BEGIN 
  DECLARE @tbl_InputJSONTable DBO.tb_ParamList ;
  DECLARE @o_ParameterList varchar(max)='', @o_ParameterListxml XML; 
  DECLARE @tbl_UserList dbo.UserAccessList;
  
  EXEC SP_ParameterXMLRep @dsXml, @o_ParameterList OUTPUT
  
  IF ISNULL(@o_ParameterList,'') <> ''
  BEGIN
	SET @o_ParameterListxml = CAST(@o_ParameterList AS XML)
    INSERT INTO @tbl_InputJSONTable (ParameterName,  ParameterValue, HeaderName, Jsontag) 
    SELECT Parameter.value('(ColumnName)[1]', 'VARCHAR(MAX)') AS Client_Code ,
    Parameter.value('(ColumnValue)[1]', 'VARCHAR(MAX)') AS ColumnValue,
	Parameter.value('(MasterTag)[1]', 'VARCHAR(MAX)') AS MasterTag,
	Parameter.value('(JsonLevel)[1]', 'VARCHAR(MAX)') AS JsonLevel
    FROM @o_ParameterListxml.nodes('/Parameter') AS XTbl(Parameter)
  END	  
  DECLARE @strtradeplustempdb VARCHAR(50) = ''

  DECLARE @StrRequestFrom VARCHAR(1)='M', @strOption VARCHAR(50)='', @strModuleName VARCHAR(50), 
  @strEntryName VARCHAR(100)='', @strUserid VARCHAR(100)='', @strNomSerial INT = 0, @strFormNo VARCHAR(10)=''
  
  SELECT @strOption = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Option'
  
  SELECT @strModuleName = ParameterValue FROM @tbl_InputJSONTable where ParameterName = 'ActionName'
  SELECT @strEntryName = ParameterValue FROM @tbl_InputJSONTable where ParameterName = 'EntryName'
  SELECT @strUserid = ParameterValue FROM @tbl_InputJSONTable where ParameterName = 'Userid'
  SELECT @strNomSerial = ParameterValue FROM @tbl_InputJSONTable where ParameterName = 'NomSerial'
  SELECT @strFormNo = ParameterValue FROM @tbl_InputJSONTable where ParameterName = 'FormNo'
  
  IF @strFormNo = '##FormNo##'
  BEGIN
    SET @strFormNo = '0'
  END
  
  DECLARE @strMobile VARCHAR(12) = '', @strTrading VARCHAR(MAX) = '', @strDemat VARCHAR(MAX) = '', @jsonv VARCHAR(MAX)=''
  
  IF @strOption IN('GetClientsFromMobile','ClientListByMobile')
  BEGIN
    SET @strMobile = (SELECT ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Mobile')

    DECLARE @TempTable TABLE (ClientCode VARCHAR(20),Product NVARCHAR(10));

    INSERT INTO @TempTable 
    SELECT LTRIM(RTRIM(cm_cd)), 'Trading'  
    FROM Client_master(NOLOCK) WHERE LTRIM(RTRIM(cm_mobile)) = @strMobile

    DECLARE @StrString VARCHAR(MAX), @dp_Server VARCHAR(50)='', @dp_Database VARCHAR(50)='', @dp_Owner  VARCHAR(50)=''

    SELECT TOP 1 @dp_Server = LTRIM(RTRIM(OP_Server)), @dp_Database = LTRIM(RTRIM(OP_DataBase)), @dp_Owner = LTRIM(RTRIM(OP_Owner)) 
    FROM Other_Products(NOLOCK) 
    WHERE op_Status = 'A' AND OP_Product IN ('Cross', 'Estro')

    IF @dp_Database <> ''
    BEGIN
      SET @StrString = 'SELECT LTRIM(RTRIM(cm_cd)), ''Demat'' FROM '+@dp_Database+'.[dbo].Client_master(NOLOCK) WHERE LTRIM(RTRIM(cm_mobile)) = ''' + @strMobile + ''''
	  INSERT INTO @TempTable 
      EXEC(@StrString)
    END

    SELECT @strTrading = @strTrading+',"'+LTRIM(RTRIM(ClientCode))+'"'  
    from @TempTable where Product = 'Trading'
    SELECT @strDemat = @strDemat+',"'+LTRIM(RTRIM(ClientCode))+'"'  
    from @TempTable where Product = 'Demat'

    SET @jsonv = '{"Trading": ##Trading##,"Demat": ##Demat##}'
    SET @jsonv = REPLACE(@jsonv,'##Trading##','['+SUBSTRING(@strTrading,2,LEN(@strTrading))+']')
    SET @jsonv = REPLACE(@jsonv,'##Demat##','['+SUBSTRING(@strDemat,2,LEN(@strDemat))+']')
    SELECT @jsonv
  END
  ELSE IF @strOption = 'UserProfile'
  BEGIN
    DECLARE @UserProfilejson VARCHAR(MAX) ='', @ProfileUser VARCHAR(50)='', @ProfileClient VARCHAR(50)=''
	
	SELECT TOP 1 @ProfileUser = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Userid'
	SELECT TOP 1 @ProfileClient = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'ClientCode'
	
	
	IF ISNULL(@ProfileClient,'') <> '' 
    BEGIN
	 DECLARE @tbl_AccessRights TABLE(Client VARCHAR(50))
	 INSERT INTO @tbl_AccessRights(Client)
	 SELECT CLIENT_CODE FROM DBO.fn_GetClients(@ProfileUser,'C',@ProfileClient)
	 
	 INSERT INTO @tbl_AccessRights(Client)
	 SELECT CF_CD FROM  Client_Family(NOLOCK) XX WHERE CF_FamilyCd IN(
     SELECT CF_FamilyCd FROM Client_Family(NOLOCK) WHERE CF_CD = @ProfileUser)
	 AND NOT EXISTS(SELECT 1 FROM @tbl_UserList WHERE ClientCode = XX.CF_CD)
	 
	 IF NOT EXISTS(SELECT 1 FROM @tbl_AccessRights WHERE CLIENT = @ProfileClient)	 
	 BEGIN
	   SELECT [ErrorMessage] = 'Wrong Client', [ErrorFlag] = 'E'
	   RETURN 1 
  	 END
	 SET @ProfileUser = @ProfileClient
    END	
	
	IF EXISTS(SELECT 1 FROM CLIENT_MASTER WHERE CM_cD = @ProfileUser)
	BEGIN
	
	  DECLARE @StrExchangeSegment VARCHAR(MAx)=''
      SELECT @StrExchangeSegment = @StrExchangeSegment+','+LTRIM(RTRIM(CES_Exchange))+'-'+LTRIM(RTRIM(CES_Segment)) FROM Client_details(NOLOCK), CompanyExchangeSegments(NOLOCK)
      WHERE ISNULL(ce_regDt,'') <> '' AND ce_clientcd = @ProfileUser
      AND ce_companycode = CES_Cd
	  
	  SELECT @StrExchangeSegment = @StrExchangeSegment+','+CASE WHEN SUBSTRING(LTRIM(RTRIM(ce_companycode)),2,1) = 'B' THEN 'BSE' ELSE 'NSE' END  +'-'+CASE WHEN SUBSTRING(LTRIM(RTRIM(ce_companycode)),3,1) = 'S' THEN 'SLBM' ELSE '' END
	  FROM Client_details(NOLOCK)
      WHERE ISNULL(ce_regDt,'') <> '' AND ce_clientcd = @ProfileUser
	  AND  NOT EXISTS(SELECT 1 FROM CompanyExchangeSegments(NOLOCK) WHERE 
	  ce_companycode = CES_Cd)
	  AND SUBSTRING(LTRIM(RTRIM(ce_companycode)),2,1) IN('B','N')
	  AND  SUBSTRING(LTRIM(RTRIM(ce_companycode)),3,1) = 'S'
      
	
      SET @UserProfilejson =(SELECT [Personal Detail] = (select [Code] = ltrim(rtrim(CM_CD)),
         [Name] = ltrim(rtrim(CM_NAME)), 	
         [Mobile] = CASE WHEN ISNULL(cm_MOBILE,'') <> '' THEN RIGHT('XXXXXX', LEN(ltrim(rtrim(cm_MOBILE))) - 4) + RIGHT(ltrim(rtrim(cm_MOBILE)), 4)
         ELSE '' END, [Email] = CASE WHEN ISNULL(cm_email,'') <> '' THEN LEFT(ltrim(rtrim(cm_email)), 3) + '****@' + 
         SUBSTRING(ltrim(rtrim(cm_email)), CHARINDEX('@', ltrim(rtrim(cm_email))) + 1, LEN(ltrim(rtrim(cm_email)))) else '' end,
         [Gender] = CASE WHEN cm_sex = 'M' THEN 'Male' WHEN cm_sex = 'F' THEN 'Female' WHEN cm_sex = 'O' THEN 'Other' END,
		 [PAN] = RIGHT('XXXXXX', LEN(ltrim(rtrim(cm_panno))) - 4) + RIGHT(ltrim(rtrim(cm_panno)), 4),
		 [Register Exchange] = @StrExchangeSegment
		 FROM CLIENT_MASTER(NOLOCK)
         WHERE cm_cd = @ProfileUser FOR JSON PATH),
         [Address Details] = (select [Address1] = ltrim(rtrim(cm_add1)),
         [Address2] = ltrim(rtrim(cm_add2)), [Address3] = ltrim(rtrim(CM_ADD3)), [City] = ltrim(rtrim(cm_add4)),
         [State] = ltrim(rtrim(cm_state))+' - '+ltrim(rtrim(cm_pincode)),
         [Country] = ltrim(rtrim(cm_bankactno))
         FROM CLIENT_MASTER(NOLOCK),  Client_Info(NOLOCK)
         WHERE cm_cd = cm2_Cd
         AND CM_cD = @ProfileUser  FOR JSON PATH),
         [Bank Details] = (SELECT [Name] = ltrim(rtrim(mas.bk_name)), [Account No] = RIGHT('XXXXXXXXXX', LEN(ltrim(rtrim(ba_actno))) - 4) + RIGHT(ltrim(rtrim(ba_actno)), 4) , 
					[IFSC] = ltrim(rtrim(ba_ifsccode)), [MICR] 
					= ltrim(rtrim(ba_micr)),[AccountType] 
					= case when ltrim(rtrim(ba_acttype)) = 'SB' THEN 'Saving' else ltrim(rtrim(ba_acttype)) end
				FROM Bankact x, Bank_master mas
				WHERE x.ba_micr = mas.bk_micr AND x.ba_ifsccode = mas.bk_IFCCode
					AND ba_default = 'Y' and ba_clientcd = @ProfileUser FOR JSON PATH),
         [Demat Details] = (SELECT [DP ID] = ltrim(rtrim(da_dpid)), [DP Account No] = RIGHT('XXXXXXXXXX', LEN(ltrim(rtrim(da_actno))) - 4) + RIGHT(ltrim(rtrim(da_actno)), 4)
				FROM Dematact(NOLOCK)
				WHERE da_clientcd = @ProfileUser AND da_status = 'A'
				and da_defaultyn = 'Y'   FOR JSON PATH) FOR JSON PATH)
     END
     ELSE
     BEGIN
	   SET @UserProfilejson = ( SELECT [Personal Detail] = (select [Code] = ltrim(rtrim(um_user_id)),
         [Name] = ltrim(rtrim(um_user_name)), 	
         [LastLogin] = CONVERT(VARCHAR,um_lastlogin,106)
		 FROM USER_MASTER(NOLOCK) WHERE UM_USER_ID =@ProfileUser FOR JSON PATH),
		 [Address Details] = (select [Address1] = ltrim(rtrim(um_add1)),
         [Address2] = ltrim(rtrim(um_add2)), [Address3] = ltrim(rtrim(um_add3)), [City] = ltrim(rtrim(um_add4)),
         [PIN] = ltrim(rtrim(um_pin)),
		 [Designation] = ltrim(rtrim(um_designation))
		 FROM USER_MASTER (NOLOCK) WHERE UM_USER_ID =@ProfileUser FOR JSON PATH) FOR JSON PATH) 
     END	 
    SELECT @UserProfilejson				
  END
  ELSE IF @strOption = 'RegisterPublicKey'
  BEGIN
    Declare @strPublicKey NVARCHAR(MAX)='', @StrClientCD VARCHAR(50)=''
	SELECT @strPublicKey = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'PublicKey' 
    SELECT TOP 1 @StrClientCD = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Userid' 	
	IF ISNULL(@strPublicKey,'') <> ''
	BEGIN
	  IF EXISTS(SELECT 1 FROM tbl_UserLoginToken(NOLOCK) WHERE Userid = @StrClientCD) 
	  BEGIN
	    UPDATE A SET PublicKey = @strPublicKey
	    FROM tbl_UserLoginToken A
	    WHERE Userid = @StrClientCD AND ISNULL(PublicKey,'') <> @strPublicKey
	
	    SELECT [Flag] = 'E', [Message] = 'Already Register', [PublicKey] = PublicKey
	    FROM tbl_UserLoginToken(NOLOCK) WHERE Userid = @StrClientCD AND ISNULL(PublicKey,'') <> ''
	  END  
	  ELSE
      BEGIN	
	    INSERT INTO tbl_UserLoginToken(Userid, PublicKey, secretPin, cn_filler1, cn_filler2, cn_filler3, cn_filler4, 
	    cn_Nfiller1, cn_Nfiller2, cn_Nfiller3, cn_Nfiller4, mkrdt, mkrid)
	    VALUES(@StrClientCD, @strPublicKey, '','','','','',0,0,0,0, GETDATE(), @StrClientCD)
	    SELECT [Flag] = 'S', [Message] = 'Process Completed', [PublicKey] = @strPublicKey
	  END
    END
	ELSE
	BEGIN
	  SELECT [Flag] = 'E', [Message] = 'Already Register', [PublicKey] = PublicKey
	  FROM tbl_UserLoginToken(NOLOCK) WHERE Userid = @StrClientCD AND ISNULL(PublicKey,'') <> ''
	END  
  END
  ELSE IF @strOption = 'Theme'
  BEGIN
    SELECT LevelSetting 
    FROM tbl_TradeWebMenu(NOLOCK) WHERE ModuleCode = 1 
	
	SELECT [LevelSetting1] = '{"fontSettings":{"sidebar":"Arial","content":"Arial"}}'
  END  
  ELSE IF @strOption = 'UPDATETHEME'
  BEGIN
    DECLARE @xstring1 VARCHAR(MAX) , @xml XML = @dsXml
	SELECT @xstring1 =  cast(@xml.query('/dsXml/X_Data') as VARCHAR(MAX))
	SELECT @xstring1 = SUBSTRING(@xstring1,CHARINDEX('<X_Data>',@xstring1)+8,CHARINDEX('</X_Data>',@xstring1)-9)
	
    --SELECT @strX_Data = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'X_Data'
	IF ISNULL(@xstring1,'') <> ''
	BEGIN
	  UPDATE A SET A.LevelSetting = @xstring1
      FROM tbl_TradeWebMenu A WHERE ModuleCode = 1 
	  SELECT [Flag] = 'S', [Message] = 'Theme Updated'
	  RETURN 1
	END
	ELSE 
	BEGIN
	  SELECT [Flag] = 'E', [Message] = 'Theme Not Updated'
	  RETURN 1
	END
  END  
  ELSE IF @strOption = 'EmailSend'
  BEGIN
    DECLARE @strMailClientCode VARCHAR(20)='', @strMailReportName VARCHAR(100), 
	@strMailFileName VARCHAR(100), @strMailBase64 NVARCHAR(MAX)='', @strParam VARCHAR(MAX)='',
	@strEmailJson NVARCHAR(MAX)='', @o_errorFlag VARCHAR(1), @o_errormessage VARCHAR(MAX)=''
	SELECT @strMailClientCode = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'ClientCode'
	SELECT @strMailReportName = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'ReportName'
	SELECT @strMailFileName = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'FileName'
	SELECT @strMailBase64 = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Base64'
	
	IF ISNULL(@strMailClientCode,'') <> '' 
	BEGIN
	  SET @strEmailJson = (select ParameterName, ParameterValue from @tbl_InputJSONTable where HeaderName = 'X_Filter' 
	  and ParameterName <> 'X_Filter' FOR JSON PATH);
	  --SELECT @strParam = '{' + 
      --STUFF((SELECT ',"' + ParameterName + '":"' + ParameterValue + '"'
      --FROM OPENJSON(@strEmailJson) WITH ( ParameterName NVARCHAR(100), ParameterValue NVARCHAR(MAX))
      --FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 1, '') + '}';
      DECLARE @strDanSql1 NVARCHAR(MAX)='', @o_vcString VARCHAR(MAX)=''
	  
	  SELECT @strtradeplustempdb = sp_sysvalue 
      FROM WebParameter(NOLOCK) WHERE sp_parmcd = 'TRADEPLUSTEMPDB' 
  
	  SET @strDanSql1 = 'EXEC '+@strtradeplustempdb+'.DBO.sp_ProcessRekyc'+' '''+@strEmailJson+''' ,''Emailjson'',  @o_vcString OUTPUT';
      EXEC sp_executesql @strDanSql1, N'@o_vcString VARCHAR(MAX) OUTPUT', @o_vcString OUTPUT;
	  	  
	  --EXEC sp_ProcessRekyc @i_vcString VARCHAR(MAX), @i_vcType VARCHAR(20), @o_vcString VARCHAR(MAX)
	  EXEC stpr_MobileApplicationMail @strMailClientCode, @strMailReportName, @strMailFileName, @strMailBase64, @o_vcString, 
	  @o_errorFlag  OUTPUT, @o_errormessage  OUTPUT
	  IF @o_errorFlag = 'S'
	  BEGIN
	    SELECT 'Email has been sent successfully'
		RETURN 1
	  END
      ELSE
      BEGIN
	    SELECT @o_errormessage
      END	  
	END
	ELSE
	BEGIN
	  SELECT 'Client Code can not be blank'
	  RETURN 1
	END
  END

  ELSE IF @strOption IN('Entry','ChildEntry','Master_Edit','ChildEntry_Edit')
  BEGIN
    DECLARE @StrTempateJson VARCHAR(MAX)=''
	IF EXISTS(SELECT 1 FROM CLIENT_MASTER WHERE CM_cD = @strUserid AND cm_freezeyn = 'A')
	BEGIN
	  SELECT  [Flag] = 'E', [Message] = 'Client is Freeze of All, So Not Allow do Any Entry'
	  RETURN 1
	END
	
	IF @strEntryName NOT IN('Rekyc','RekycOffLine')
	BEGIN
	  SELECT @StrTempateJson = '[' + STUFF((
      SELECT ',' +
      '{"Srno": '+CAST(ORDERBY AS VARCHAR)+',"type": "'+
      CASE WHEN CONTROLTYPE='DropDown' THEN 'WDropDownBox' 
         WHEN CONTROLTYPE='EditBox' THEN 'WTextBox' 
         WHEN CONTROLTYPE='DatePicker' THEN 'WDateBox' 
         WHEN CONTROLTYPE='DisplayBox' THEN 'WDisplayBox' 
		 WHEN CONTROLTYPE='File' THEN 'WFile' 
		 WHEN CONTROLTYPE='CheckBox' THEN 'WCheckBox' 
		 ELSE CONTROLTYPE 
      END+
      '","label": "'+ISNULL(displayname,'')+'","wKey": "'+ISNULL(TagName,'')+'","FieldWidth":"'+CAST(FieldWidth AS VARCHAR)+'","FieldSize":"'+CASE WHEN CONTROLTYPE='File' THEN '-1' ELSE CAST(FieldSize AS VARCHAR) END+'",'+'
	  "isResizable":"'+case when CONTROLTYPE='File' THEN 'true' ELSE 'false' end+'",
	  "FieldEnabledTag":"'+CASE WHEN ISNULL(FieldList,'') ='Y' THEN 'Y' ELSE 'N' END+'",
	  "FieldVisibleTag":"'+CASE WHEN ISNULL(FieldList,'') ='X' THEN 'N' ELSE 'Y' END+'","CombinedName":"'+CAST(DisplayValue AS VARCHAR)+'",'+'"iscreatable":"'+CASE WHEN isnull(FieldQuery,'') = 'XX' THEN 'true' else 'false' end +'",'+
	  '"isMandatory":"'+CASE WHEN isnull(isMandatory,'') = 'Y' THEN 'true' else 'false' end +'",
	  "FieldType":"'+CAST(FieldType AS VARCHAR(100))+'",'+CASE WHEN @strOption in('Master_Edit','ChildEntry_Edit') THEN '"wValue":"~~'+FieldName+'~~",'
	  ELSE '' END+'
	  "childDependents":'+ISNULL((SELECT '["'+STUFF((
      SELECT ', ' + TAGNAME
      FROM tbl_GenericTemplateDefinition(NOLOCK) GG , tbl_InsertUpdateXMLDropDownQuery(NOLOCK) dd 
      WHERE GG.TEMPLATENAME =  @strEntryName
      AND GG.ParentTemplateCode = 'ChildEntry'
	  AND ISNULL(DD.DependentField,'') = G.TAGNAME
	  AND GG.TEMPLATENAME = DD.ModuleName AND GG.TAGNAME = DD.ColumnName
      FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, '') AS AllValues)+'"]','[]')+',
      "ValidationAPI":'+
      CASE WHEN ISNULL(ValidationQuery,'') = '' THEN '{}' 
      ELSE ISNULL(
        (SELECT TOP 1 REPLACE(ISNULL(DependentField,'{}'),'<<USERID>>',@strUserid) 
         FROM tbl_InsertUpdateXMLDropDownQuery WITH(NOLOCK) 
         WHERE ModuleName = @strEntryName
         AND ColumnName = ISNULL(g.ValidationQuery,'')),
        '{}') END +
      CASE WHEN CONTROLTYPE='DropDown' THEN 
        CASE WHEN ISNULL(DependentField,'') <> '' THEN 
            ',"dependsOn": {"field": ["'+ISNULL(DependentField,'')+'"],
            "wQuery": {"Sql": "","J_Ui": 
            {"ActionName": "'+ISNULL(MODULENAME,'')+'","Option": "'+ISNULL(ColumnName,'')+'","RequestFrom": "W"},
            "X_Filter_Multiple": "'+ISNULL(DependentField,'')+'","X_Filter": "","J_Api": {"UserId": "'+@strUserid+'","AccYear": 24,"MyDbPrefix": "SVVS","MemberCode": "undefined",
            "SecretKey": "undefined","MenuCode": 7}}},"wDropDownKey":{"key": "DisplayName","value": "Value"}}'
        ELSE 
            ',"wQuery": {"Sql": "","J_Ui": 
            {"ActionName": "'+ISNULL(MODULENAME,'')+'","Option": "'+ISNULL(ColumnName,'')+'","RequestFrom": "W"},
            "X_Filter_Multiple": "","X_Filter": "","J_Api": {"UserId": "'+@strUserid+'","AccYear": 24,"MyDbPrefix": "SVVS","MemberCode": "undefined",
            "SecretKey": "undefined","MenuCode": 7}},"wDropDownKey":{"key": "DisplayName","value": "Value"}}' 
        END
       WHEN CONTROLTYPE='DatePicker' AND @strOption not in('Master_Edit','ChildEntry_Edit') THEN 
        ',"wValue":"'+CONVERT(VARCHAR,GETDATE(),112)+'"}' 
      ELSE '}' 
      END
      FROM tbl_GenericTemplateDefinition g WITH(NOLOCK) 
      LEFT OUTER JOIN tbl_InsertUpdateXMLDropDownQuery d WITH(NOLOCK) 
        ON(g.TEMPLATENAME = d.ModuleName AND g.TAGNAME = d.ColumnName)
      WHERE g.TEMPLATENAME = @strEntryName
      AND g.ParentTemplateCode = CASE WHEN @strOption = 'Master_Edit' THEN 'Entry' 
	  WHEN @strOption = 'ChildEntry_Edit' THEN 'ChildEntry' else @strOption end
      ORDER BY g.OrderBy
      FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 1, '') + ']' 
    END
	ELSE
    BEGIN
	  SET @StrTempateJson = '[' + STUFF((
	  SELECT ',{' +'"TabName":"'+GroupName+'",
	  "tableData":'+CASE WHEN @strOption in('Master_Edit','ChildEntry_Edit') THEN '"~~'+GroupName+'~~"' ELSE '[]' END +',
	  "Settings":{"isTable": "true", "maxAllowedRecords": "5","isGroup":"true",
	  "isTable": "'+CASE WHEN GroupName in('BankDetails','DematDetails','RelatedPersonDetails') then 'true' 
	  WHEN GROUPNAME = 'Attachments' and @strEntryName='RekycOffline' THEN 'true' 
	  else 'false' 
	  end +'",
	  "TabChangeAPI":{"J_Ui": {"ActionName": "TradeWeb","Option": "TabChangeAPI"},
	  "Sql": {},"X_Filter": {"EntryName": "'+@strEntryName+'",
	  "TabName":"'+GroupName+'","ClientCode":"##ClientCode##","Constitution":"##Constitution##"},
	  "J_Api": {"UserId": "##UserId##"}},
	  "SaveNextAPI":{"J_Ui": {"ActionName": "TradeWeb","Option": "SaveNext"},"Sql": {},
	  "X_Filter_Multiple": {"EntryName": "'+@strEntryName+'","ClientCode": 
	  "##ClientCode##","TabName":"'+GroupName+'"},"X_DataJson":"##X_DataJson##",
		"J_Api": {"UserId": "##UserId##"}}'+
		CASE WHEN GroupName = 'Attachments' THEN ',"MakerSaveAPI":{"J_Ui": {"ActionName": "TradeWeb","Option": "MakerSave"},"Sql": {},
	  "X_Filter_Multiple": {"EntryName": "'+@strEntryName+'","ClientCode": 
	  "##ClientCode##"},"X_DataJson":"##X_DataJson##",
		"J_Api": {"UserId": "##UserId##"}},"existsDigiLockerAPI":"##existsDigiLockerAPI##","DigiLockerAPI":{"dsXml": {"J_Ui": {"ActionName": "Rekyc","Option": "DigilockerRequest"},
		"Sql": null,"X_Filter": "","X_Filter_Multiple": {"ClientCode": "##ClientCode##"},"J_Api": {"UserId": "##UserId##"}}}
		,"DigiLockerCallBackAPI":{"dsXml": {"J_Ui": {"ActionName": "Rekyc","Option": "DigilockerJSON"},
		"Sql": null,"X_Filter": "","X_Filter_Multiple": {"ClientCode": "##ClientCode##","NoAddressUpdate":"Y"},"J_Api": {"UserId": "##UserId##"}}},
		"IsKRAESigned":"##IsKRAESigned##","IsFinalKRAESigned":"##IsFinalKRAESigned##","viewMode":"##viewMode##", 
		"EsignAPI":{"dsXml": {"J_Ui": {"ActionName": "Rekyc","Option": "EsignRequest"},
		"Sql": null,"X_Filter": "","X_Filter_Multiple": {"ClientCode": "##ClientCode##","base64":"##base64##","pdfpage":"##pdfpage##","FileType":"##FileType##"},"J_Api": {"UserId": "##UserId##"}}}
		}' ELSE '}' END +',
	  "Data":'+data1 from(
	  SELECT DISTINCT GroupName, 'Data1' = isnull((select '[{' + STUFF((SELECT ',' +
      '{"Srno": '+CAST(ORDERBY AS VARCHAR)+',"type": "'+ CASE WHEN CONTROLTYPE='DropDown' THEN 'WDropDownBox'  WHEN CONTROLTYPE='EditBox' THEN 'WTextBox'  WHEN CONTROLTYPE='DatePicker' THEN 'WDateBox' 
         WHEN CONTROLTYPE='DisplayBox' THEN 'WDisplayBox' WHEN CONTROLTYPE='File' THEN 'WFile'  WHEN CONTROLTYPE='CheckBox' THEN 'WCheckBox' ELSE CONTROLTYPE END+
      '","label": "'+ISNULL(displayname,'')+'","wKey": "'+ISNULL(TagName,'')+'","FieldWidth":"'+CAST(FieldWidth AS VARCHAR)+'","FieldSize":"'+CASE WHEN CONTROLTYPE='File' THEN '-1' ELSE CAST(FieldSize AS VARCHAR) END+'",'+'
	  "isResizable":"'+case when CONTROLTYPE='File' THEN 'true' ELSE 'false' end+'",
	  "isChangeColumn":"##'+TagName+'~C##",
	  "FieldEnabledTag":"'+CASE WHEN ISNULL(FieldList,'') ='Y' THEN 'Y' ELSE 'N' END+'",
	  "FieldVisibleTag":"'+CASE WHEN ISNULL(FieldList,'') ='X' THEN 'N' ELSE 'Y' END+'","CombinedName":"'+CAST(DisplayValue AS VARCHAR)+'",'+'"iscreatable":"'+CASE WHEN isnull(FieldQuery,'') = 'XX' THEN 'true' else 'false' end +'",'+
	  '"isMandatory":"'+CASE WHEN isnull(isMandatory,'') = 'Y' THEN 'true' else 'false' end +'",
	  "FieldType":"'+CAST(FieldType AS VARCHAR(100))+'","redirectUrl":"'+CASE WHEN TagName IN('BankAccNo') 
	  AND EXISTS(SELECT 1 FROM WebParameter(NOLOCK) WHERE sp_parmcd='SETUSETTING' AND sp_sysvalue LIKE '%RPD')
	  THEN  'true' WHEN TagName IN ('CorrAddress1') THEN 'true' else 'false' end +'",
	  "GetResponseFlag":"'+CASE WHEN TagName IN('BankAccNo') AND EXISTS(SELECT 1 FROM WebParameter(NOLOCK) WHERE sp_parmcd='SETUSETTING' AND sp_sysvalue LIKE '%RPD')
	  THEN 'true' else 'false' end +
	   '","isVisibleinTable":"'+CASE WHEN DisplayLendingPage ='Y' THEN 'true' else 'false' end +
	  '","isBR":"'+CASE WHEN ISNULL(UpdateBy,'N') ='Y' THEN 'true' ELSE 'false' end +'","OTPRequire":"'+CASE WHEN FieldQuery = '12' THEN 'OLD|NEW' WHEN FieldQuery = '2' THEN 'NEW'
	   WHEN FieldQuery = '1' THEN 'OLD' else '' end+'"'+
	   ',"isChildFormEntryRequired":"'+CASE WHEN GroupName = 'NomineeDetails' AND TAGNAME ='NomineeDOB' THEN 'true'  else 'false' end+'"'+
	   ',"FileType":"'+CASE WHEN CONTROLTYPE = 'FILE' 
	   THEN case when TagName = 'SignAttachment' then 'jpg,png' else 'jpg,png,gif,tiff,bmp,PDF' end ELSE '' END +'","OlddataValue":"'+case when TagName in('Email','Mobile') then '##'+TagName+'1##' else '' end+'","OTPSend":'+CASE WHEN ISNULL(G.FieldQuery,'') IN('12','1','2')  
	  THEN CASE WHEN ISNULL(FieldValue,'') = '' THEN '{}' 
      ELSE ISNULL(
        (SELECT TOP 1 REPLACE(ISNULL(DependentField,'{}'),'<<USERID>>',@strUserid) 
         FROM tbl_InsertUpdateXMLDropDownQuery WITH(NOLOCK) 
         WHERE ModuleName = @strEntryName
         AND ColumnName = ISNULL(g.FieldValue,'')),
        '{}') END
		ELSE '{}' END +
		',"OTPValidate":'+CASE WHEN ISNULL(G.FieldQuery,'') IN('12','1','2')  
	  THEN CASE WHEN ISNULL(FieldValue,'') = '' THEN '{}' 
      ELSE ISNULL(
        (SELECT TOP 1 REPLACE(ISNULL(DependentField,'{}'),'<<USERID>>',@strUserid) 
         FROM tbl_InsertUpdateXMLDropDownQuery WITH(NOLOCK) 
         WHERE ModuleName = @strEntryName
         AND ColumnName = ISNULL(g.ValidationQuery,'')),
        '{}') END
		ELSE '{}' END +',"childDependents":'+ISNULL((SELECT '["'+STUFF((
      SELECT ', ' + TAGNAME
      FROM tbl_GenericTemplateDefinition(NOLOCK) GG , tbl_InsertUpdateXMLDropDownQuery(NOLOCK) dd 
      WHERE GG.TEMPLATENAME =  @strEntryName
      AND GG.ParentTemplateCode = 'ChildEntry'
	  AND ISNULL(DD.DependentField,'') = G.TAGNAME
	  AND GG.TEMPLATENAME = DD.ModuleName AND GG.TAGNAME = DD.ColumnName
      FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, '') AS AllValues)+'"]','[]')+',"ThirdPartyAPI":'+CASE WHEN G.TableName = 'TJSON' 
	  THEN CASE WHEN (ISNULL(FieldValue,'') = '' OR ISNULL(G.FieldQuery,'') IN('12','1','2')) THEN '{}' 
      ELSE ISNULL(
        (SELECT TOP 1 REPLACE(ISNULL(DependentField,'{}'),'<<USERID>>',@strUserid) 
         FROM tbl_InsertUpdateXMLDropDownQuery WITH(NOLOCK) 
         WHERE ModuleName = @strEntryName
         AND ColumnName = ISNULL(g.FieldValue,'')),
        '{}') END
		ELSE '{}' END +',"ValidationAPI":'+
      CASE WHEN (ISNULL(ValidationQuery,'') = '' OR ISNULL(G.FieldQuery,'') IN('12','1','2'))   THEN '{}' 
      ELSE ISNULL(
        (SELECT TOP 1 REPLACE(ISNULL(DependentField,'{}'),'<<USERID>>',@strUserid) 
         FROM tbl_InsertUpdateXMLDropDownQuery WITH(NOLOCK) 
         WHERE ModuleName = @strEntryName
         AND ColumnName = ISNULL(g.ValidationQuery,'')),
        '{}') END +
      CASE WHEN CONTROLTYPE='DropDown' THEN 
        CASE WHEN ISNULL(DependentField,'') <> '' THEN 
            ',"dependsOn": {"field": ["'+ISNULL(DependentField,'')+'"],
            "wQuery": {"Sql": "","J_Ui": 
            {"ActionName": "'+ISNULL(MODULENAME,'')+'","Option": "'+ISNULL(ColumnName,'')+'","RequestFrom": "W"},
            "X_Filter_Multiple": "'+ISNULL(DependentField,'')+'","X_Filter": "","J_Api": {"UserId": "'+@strUserid+'","AccYear": 24,"MyDbPrefix": "SVVS","MemberCode": "undefined",
            "SecretKey": "undefined","MenuCode": 7}}},"wDropDownKey":{"key": "DisplayName","value": "Value"}}'
        ELSE 
            ',"wQuery": {"Sql": "","J_Ui": 
            {"ActionName": "'+ISNULL(MODULENAME,'')+'","Option": "'+ISNULL(ColumnName,'')+'","RequestFrom": "W"},
            "X_Filter_Multiple": "","X_Filter": "","J_Api": {"UserId": "'+@strUserid+'","AccYear": 24,"MyDbPrefix": "SVVS","MemberCode": "undefined",
            "SecretKey": "undefined","MenuCode": 7}},"wDropDownKey":{"key": "DisplayName","value": "Value"}}' 
        END
       WHEN CONTROLTYPE='DatePicker' AND @strOption not in('Master_Edit','ChildEntry_Edit') THEN 
        ',"wValue":"'+CONVERT(VARCHAR,GETDATE(),112)+'"}' 
      ELSE '}' 
      END as Text1
      FROM tbl_GenericTemplateDefinition g WITH(NOLOCK) 
      LEFT OUTER JOIN tbl_InsertUpdateXMLDropDownQuery d WITH(NOLOCK) 
        ON(g.TEMPLATENAME = d.ModuleName AND g.TAGNAME = d.ColumnName)
      WHERE g.TEMPLATENAME = @strEntryName
      AND g.ParentTemplateCode = CASE WHEN @strOption = 'Master_Edit' THEN 'Entry' 
	  WHEN @strOption = 'ChildEntry_Edit' THEN 'ChildEntry' else @strOption end
	  and g.GroupName = xmain.GroupName order by g.OrderBy FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, '') AS AllValues)+']}','[]')
      FROM tbl_GenericTemplateDefinition xmain
      where TEMPLATENAME = @strEntryName 
	  AND xmain.ParentTemplateCode = CASE WHEN @strOption = 'Master_Edit' THEN 'Entry' 
	  WHEN @strOption = 'ChildEntry_Edit' THEN 'ChildEntry' else @strOption end) x111 
	  ORDER BY CASE WHEN GROUPNAME  = 'MASTER' THEN 1 WHEN GROUPNAME  = 'PersonalDetails' then 2
	  WHEN GROUPNAME  = 'BankDetails'  then 3 WHEN GROUPNAME  = 'RelatedPersonDetails' THEN 4 else 5 end
	  FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 1, '') + ']' 
    END
    IF @strOption IN('Entry','ChildEntry')
	BEGIN
	  SELECT @StrTempateJson
	  RETURN 1
	END
	
	DECLARE @StrGetFilter VARCHAR(MAX)='', @strTableName VARCHAR(100)='', @strChildtableName VARCHAR(100)=''
    
	SELECT @strTableName = CASE WHEN @strOption= 'Master_Edit' 
    THEN CASE WHEN isnull(MasterTableName,'') = '' THEN DetailTableName else MasterTableName end
    WHEN @strOption= 'ChildEntry_Edit' then CASE WHEN isnull(DetailTableName,'') = '' THEN MasterTableName else DetailTableName end 
    ELSE DetailTableName end
    FROM tbl_InsertUpdateConfig(NOLOCK)
    WHERE ModuleName = @strEntryName 
  
    SELECT @strChildtableName = CASE WHEN isnull(DetailTableName,'') = '' 
	THEN MasterTableName else DetailTableName end
    FROM tbl_InsertUpdateConfig(NOLOCK)
    WHERE ModuleName = @strEntryName 
    
	SELECT @strtradeplustempdb = sp_sysvalue
    FROM WebParameter(NOLOCK)
    WHERE sp_parmcd = 'TRADEPLUSTEMPDB'

    IF OBJECT_ID('tempdb..#tbl_jsonoutput1') IS NOT NULL
    BEGIN
	   DROP TABLE #tbl_jsonoutput1
    END

    CREATE TABLE #tbl_jsonoutput1 (SerialNo INT identity(1,1), ColumnName VARCHAR(50), ColumnValue VARCHAR(MAX), MasterTag VARCHAR(100), 
	JSONLEVEL INT, MASTERLEVEL INT, FieldName VARCHAR(50))

    DECLARE @jsonCutterOutput VARCHAR(MAX)='', @strDanSql NVARCHAR(MAX)=''
    DECLARE @JsonCutterXML XML, @strEmail VARCHAR(100)='', @strMobile1 VARCHAR(100)=''	
	
	IF ISNULL(@strTableName,'') = 'JSON'
	BEGIN  
	  IF @strEntryName IN('REKYC','RekycOffLine') AND @strOption = 'Master_Edit'
	  BEGIN
	    DECLARE @RekyClientCode VARCHAR(20)=''
		SELECT @RekyClientCode = ParameterValue FROM @tbl_InputJSONTable where ParameterName = 'ClientCode'
	    IF isnull(@RekyClientCode,'') <> ''
		BEGIN
		  SET @strUserid = @RekyClientCode
		END
		
	    SELECT @strMobile1 = cm_mobile, @strEmail = CM_EMAIL From Client_master(NOLOCK) WHERE CM_cD = @strUserid
		SET @StrTempateJson = REPLACE(@StrTempateJson,'##Mobile1##',LTRIM(RTRIM(@strMobile1)))
		SET @StrTempateJson = REPLACE(@StrTempateJson,'##Email1##',LTRIM(RTRIM(@strEmail)))
		
	    IF ISNULL(@strFormNo,'') = ''
		BEGIN
		  SET @strFormNo = '0'
		END
		
		DECLARE @sql1 NVARCHAR(MAX);
        DECLARE @json NVARCHAR(MAX);
        
		INSERT INTO #tbl_jsonoutput1(ColumnName,ColumnValue,MasterTag, JsonLevel, MasterLevel )
		SELECT ColumnName = 'GuardianDetails', ColumnValue = '#'+ColumnValue+'#', MasterTag, JsonLevel, MasterLevel 
		FROM #tbl_jsonoutput1 WHERE MasterTag = 'NomineeDetails' AND ColumnName = 'NomSerial'

        DECLARE @strStep INT = 1, @i_vcRefNo INT = 0
 
        IF EXISTS(SELECT 1 FROM Client_ReKycMain(NOLOCK) WHERE rm_cmcd = @strUserid AND rm_RequestType = @strEntryName
        AND ISNULL(rm_rekyc,'N') = 'N') 
        BEGIN
          SELECT @i_vcRefNo = rm_refno, @strStep = rm_step FROM Client_ReKycMain(NOLOCK) 
	      WHERE rm_cmcd = @strUserid AND rm_RequestType = @strEntryName
          AND ISNULL(rm_rekyc,'N') = 'N' AND rm_srno IN( SELECT MAX(ISNULL(rm_srno, 0)) 
	      FROM Client_ReKycMain(NOLOCK) WHERE rm_cmcd = @strUserid AND rm_RequestType = @strEntryName
	      AND ISNULL(rm_rekyc,'N') = 'N')
        END
        
		IF ISNULL(@strFormNo ,'') NOT IN('','0')
        BEGIN
		  SET @i_vcRefNo = @strFormNo
        END	

		DECLARE @ftformNo INT = @i_vcRefNo
		
		IF @strEntryName = 'RekycOffLine'
		BEGIN
		  DECLARE @strKRAApiUrl VARCHAR(200)=''
		  SELECT @strKRAApiUrl = APIUrl FROM tbl_VendorAPISetting(NOLOCK) 
		  WHERE APIVendorName='CVLKRA' AND APIName = 'GetToken' 
		  
		  IF ISNULL(@strKRAApiUrl,'') <> ''
		  BEGIN
		    DECLARE @vcXML11 XML, @o_vcErrorFlag12 VARCHAR(1)='', @o_vcErrorMessage12 VARCHAR(MAX)='',
			@xmlDatr1 VARCHAR(MAX)=''
			
		    SET @vcXML11 ='<root><ClientCode>'+@strUserid+'</ClientCode></root>'
			SET @xmlDatr1 = CAST(@vcXML11 AS NVARCHAR(MAX))
            EXEC stpr_APICVLKRAStatusUpdate @xmlDatr1, @o_vcErrorFlag12 OUTPUT, @o_vcErrorMessage12 OUTPUT
			IF ISNULL(@o_vcErrorFlag12,'') <> 'S'
            BEGIN
			  INSERT INTO tbl_GenericAPIDebugLog(ParentSerialNo,RequestSource,RequestUniqueID,RequestString,ResponseString,ExceptionMessage,UpdateBy,UpdateTimeStamp)
               VALUES(@i_vcRefNo,'CVLKRA',@strUserid,'','',@o_vcErrorMessage12,'SA',GETDATE())
            END			
		  END
        END
		
	    DECLARE @o_JsonvcErrorFlag VARCHAR(1)='', @o_JsonvcErrorMessage VARCHAR(500)='', @o_JsonvcJsonOutput VARCHAR(MAX) 
        EXEC [SP_ReKyc_GetData] @strUserid,  @o_JsonvcErrorFlag OUTPUT, @o_JsonvcErrorMessage OUTPUT, @o_JsonvcJsonOutput OUTPUT, 'Template1', 'G',  @ftformNo
        IF ISNULL(@o_JsonvcErrorFlag,'') <> 'S'
		BEGIN
		  SELECT 'Invalid Json Found In Rekyc Procedure '+@o_JsonvcJsonOutput
		  RETURN 1
		END

        SET @strDanSql = 'EXEC '+@strtradeplustempdb+'.DBO.sp_JsonCutter'+' '''+@o_JsonvcJsonOutput+''' , @jsonCutterOutput OUTPUT';
        EXEC sp_executesql @strDanSql, N'@jsonCutterOutput VARCHAR(MAX) OUTPUT', @jsonCutterOutput OUTPUT;
        SET @JsonCutterXML= CAST(@jsonCutterOutput AS XML)

        INSERT INTO #tbl_jsonoutput1(ColumnName, ColumnValue, MasterTag, JsonLevel, MasterLevel)
        SELECT X1.* FROM(
        SELECT --JsonCutter.value('(SerialNo)[1]', 'int') AS SerialNo ,
        JsonCutter.value('(ColumnName)[1]', 'VARCHAR(1000)') AS ColumnName ,
        JsonCutter.value('(ColumnValue)[1]', 'VARCHAR(max)') AS ColumnValue,
        JsonCutter.value('(MasterTag)[1]', 'VARCHAR(50)') AS MasterTag,
        JsonCutter.value('(JsonLevel)[1]', 'INT') AS JsonLevel,
        JsonCutter.value('(MasterLevel)[1]', 'INT') AS MasterLevel
        FROM @JsonCutterXML.nodes('/JsonCutter') AS XTbl(JsonCutter)) X1
	  
		
        IF ISNULL(@i_vcRefNo,0) > 0  
		BEGIN
		  DECLARE @strTagName VARCHAR(100)
		  DECLARE ColumnCursor_N2 CURSOR FOR
          SELECT DISTINCT ca_desc AS tag 
		  FROM Client_ModifyAPI(NOLOCK) 
		  WHERE ca_cmcd = @strUserid AND ca_Nfiller3 = @i_vcRefNo --AND ISNULL(ca_Tplus,'N') = 'N'
          OPEN ColumnCursor_N2;
		  FETCH NEXT FROM ColumnCursor_N2 INTO @strTagName
          WHILE @@FETCH_STATUS = 0
          BEGIN
		    SET @StrTempateJson = REPLACE(@StrTempateJson,'##'+@strTagName+'~C##','true')
		    FETCH NEXT FROM ColumnCursor_N2 INTO @strTagName
          END;
		
		  CLOSE ColumnCursor_N2;
          DEALLOCATE ColumnCursor_N2;		  
        

          --DECLARE @strTagName VARCHAR(100)
		  DECLARE ColumnCursor_N3 CURSOR FOR
          SELECT x1.JsonKey FROM Client_ModifyAPI(NOLOCK) X, tbl_ReKycAuditColumnMapping_new X1 
          WHERE CA_CMCD = @strUserid AND ca_Nfiller3 = @i_vcRefNo
          AND X.ca_field = X1.FieldName
          AND X1.TemplateCode='template1'
          and ca_filler1 = x1.MasterJsonTag

          OPEN ColumnCursor_N3;
		  FETCH NEXT FROM ColumnCursor_N3 INTO @strTagName
          WHILE @@FETCH_STATUS = 0
          BEGIN
		    SET @StrTempateJson = REPLACE(@StrTempateJson,'##'+@strTagName+'~C##','true')
		    FETCH NEXT FROM ColumnCursor_N3 INTO @strTagName
          END;
		
		  CLOSE ColumnCursor_N3;
          DEALLOCATE ColumnCursor_N3;		
		  
		  SET @strTagName = ''

		  DECLARE ColumnCursor_N4 CURSOR FOR
          SELECT DISTINCT TagName FROM tbl_GenericTemplateDefinition 
		  WHERE TEMPLATENAME = @strEntryName
          OPEN ColumnCursor_N4;
		  FETCH NEXT FROM ColumnCursor_N4 INTO @strTagName
          WHILE @@FETCH_STATUS = 0
          BEGIN
			SET @StrTempateJson = REPLACE(@StrTempateJson,'##'+@strTagName+'~C##','False')
		    FETCH NEXT FROM ColumnCursor_N4 INTO @strTagName
          END;
		  
		  CLOSE ColumnCursor_N4;
          DEALLOCATE ColumnCursor_N4;		   
		  
		  
		  IF EXISTS(SELECT 1 FROM Client_ModifyAttach(NOLOCK) WHERE ma_cmcd = @strUserid AND ma_refno = @i_vcRefNo 
		  AND ma_filename = 'SignedKRAPdf')
		  BEGIN
		    SET @StrTempateJson = REPLACE(@StrTempateJson,'##IsKRAESigned##','true')
		  END
		  ELSE
		  BEGIN
		    SET @StrTempateJson = REPLACE(@StrTempateJson,'##IsKRAESigned##','false')
		  END
		  
		  IF EXISTS(SELECT 1 FROM Client_ModifyAttach(NOLOCK) WHERE ma_cmcd = @strUserid AND ma_refno = @i_vcRefNo 
		  AND ma_filename = 'SignedPdf')
		  BEGIN
		    SET @StrTempateJson = REPLACE(@StrTempateJson,'##IsFinalKRAESigned##','true')
		  END
		  ELSE
		  BEGIN
		    SET @StrTempateJson = REPLACE(@StrTempateJson,'##IsFinalKRAESigned##','false')
		  END
		  
		  
		  IF EXISTS(SELECT 1 FROM Client_ModifyAttach(NOLOCK) WHERE ma_cmcd = @strUserid AND ma_refno = @i_vcRefNo 
		  AND ma_field = 'AadhaarAttachment')
		  BEGIN
		    SET @StrTempateJson = REPLACE(@StrTempateJson,'##existsDigiLockerAPI##','true')
		  END
		  ELSE
		  BEGIN
		    SET @StrTempateJson = REPLACE(@StrTempateJson,'##existsDigiLockerAPI##','false')
		  END
		  
		  
		  IF EXISTS(SELECT 1 FROM Client_ReKycMain(NOLOCK) WHERE rm_cmcd = @strUserid AND rm_refno = @i_vcRefNo
		  AND rm_RequestType = 'REKYC' AND rm_step > 1)
		  BEGIN
		    SET @StrTempateJson = REPLACE(@StrTempateJson,'##viewMode##','true')
		  END
		  ELSE
		  BEGIN
		    SET @StrTempateJson = REPLACE(@StrTempateJson,'##viewMode##','false')
		  END
		  
		 
 		  
		  UPDATE A SET A.ColumnValue = M.ca_newValue
		  FROM #tbl_jsonoutput1 A, Client_ModifyAPI(NOLOCK) M
		  WHERE A.ColumnName = M.ca_desc
		  AND M.ca_cmcd = @strUserid
		  AND A.MasterTag = ca_filler1
		  AND M.ca_Nfiller3 = @i_vcRefNo
		  --AND ISNULL(ca_Tplus,'N') = 'N'
		  AND ca_filler1 = 'PersonalDetails'
		    
		  UPDATE A SET A.ColumnValue = B.ca_newValue
		  FROM #tbl_jsonoutput1 A, (SELECT X1.JSONKEY, X.ca_newValue FROM Client_ModifyAPI(NOLOCK) X,  
		  tbl_ReKycAuditColumnMapping_new(NOLOCK) X1
          WHERE X.ca_cmcd = @strUserid
          AND X.ca_Nfiller3 = @i_vcRefNo
		  AND X.ca_filler1 = 'PersonalDetails'
          AND X.ca_field = X1.FieldName		
          AND TemplateCode = 'TEMPLATE1'
          AND MasterJsonTag = 'PersonalDetails') B
          WHERE A.MasterTag = 'PersonalDetails'
          AND A.COLUMNNAME = B.JSONKEY	
		  
		  
		  
		 DECLARE @strRequestid1 VARCHAR(MAX)='', @strma_filename VARCHAR(50)=''
		 DECLARE @strDanSql11 NVARCHAR(MAX)='', @outputJson VARCHAR(MAX)=''
		 
		 IF EXISTS(SELECT 1 FROM Client_ModifyAttach (NOLOCK) 
		  WHERE ma_cmcd = @strUserid 
          AND ma_filename NOT IN('DigilockerRequest','RPD_Called') 
		  AND ISNULL(Requestid,'') <> '' 
		  AND ma_refno = @i_vcRefNo)
		  BEGIN
            DECLARE ColumnCursor_N1 CURSOR FOR
            SELECT Requestid, ma_filename 
			FROM Client_ModifyAttach(NOLOCK) 
		    WHERE ma_cmcd = @strUserid AND ma_filename NOT IN('DigilockerRequest','RPD_Called') AND ISNULL(Requestid,'') <> ''
			AND ma_refno = @i_vcRefNo
            OPEN ColumnCursor_N1;
		    FETCH NEXT FROM ColumnCursor_N1 INTO @strRequestid1, @strma_filename
            WHILE @@FETCH_STATUS = 0
            BEGIN
			  IF @strEntryName = 'REKYC'
			  BEGIN
			    SET @StrTempateJson = REPLACE(@StrTempateJson,'"~~'+@strma_filename+'~~"', @strRequestid1)
			  END
			  ELSE
			  BEGIN
			    SET @strDanSql11 = 'EXEC '+@strtradeplustempdb+'.DBO.SP_RemoveMasterJsoninArray'+' '''+@strRequestid1+''' ,'''+@strma_filename+''',  @outputJson OUTPUT';
                EXEC sp_executesql @strDanSql11, N'@outputJson VARCHAR(MAX) OUTPUT', @outputJson OUTPUT;
				
				SET @StrTempateJson = REPLACE(@StrTempateJson,'"~~'+@strma_filename+'~~"', ISNULL(@outputJson,''))
			  END
              FETCH NEXT FROM ColumnCursor_N1 INTO @strRequestid1, @strma_filename
            END;
		    
		    CLOSE ColumnCursor_N1;
            DEALLOCATE ColumnCursor_N1;		   
		  END
		END
	    
		SET @StrTempateJson = REPLACE(@StrTempateJson,'##existsDigiLockerAPI##','false')
		SET @StrTempateJson = REPLACE(@StrTempateJson,'##IsKRAESigned##','false')
		SET @StrTempateJson = REPLACE(@StrTempateJson,'##viewMode##','false')
		SET @StrTempateJson = REPLACE(@StrTempateJson,'##IsFinalKRAESigned##','false')
		
		
		
		DECLARE @StrMasterTag VARCHAR(50)=''
		DECLARE ColumnCursor_N CURSOR FOR
        SELECT DISTINCT MasterTag FROM #tbl_jsonoutput1 
		WHERE ((MasterTag <> 'Attachments' and @strEntryName <> 'Rekyc') or @strEntryName = 'Rekyc')
        OPEN ColumnCursor_N;
		FETCH NEXT FROM ColumnCursor_N INTO @StrMasterTag
        WHILE @@FETCH_STATUS = 0
        BEGIN
		   SET @sql1 = N'
              WITH PivotedData AS (SELECT JSONLEVEL, ' + STUFF((
			  SELECT DISTINCT ',MAX(CASE WHEN ColumnName = ''' 
              + ColumnName + ''' THEN ColumnValue END) AS ' + QUOTENAME(ColumnName)
              FROM #tbl_jsonoutput1 where MasterTag = @StrMasterTag
              FOR XML PATH('')), 1, 1, '') + '
              FROM #tbl_jsonoutput1
              WHERE MasterTag = '''+@StrMasterTag+'''
              GROUP BY JSONLEVEL)
           SELECT @json = (
           SELECT ' + STUFF((
           SELECT DISTINCT ',' + QUOTENAME(ColumnName)
           FROM #tbl_jsonoutput1 where MasterTag = @StrMasterTag
           FOR XML PATH('')), 1, 1, '') + ' FROM PivotedData ORDER BY JSONLEVEL FOR JSON PATH);';
           
		   EXEC sp_executesql @sql1, N'@json NVARCHAR(MAX) OUTPUT', @json OUTPUT;
		   
		   IF @StrMasterTag IN('PersonalDetails') 
		   BEGIN
		     SET @StrTempateJson = REPLACE(@StrTempateJson,'"~~Master~~"', ISNULL(@json,'[]'))
		   END
		   SET @StrTempateJson = REPLACE(@StrTempateJson,'"~~'+@StrMasterTag+'~~"', ISNULL(@json,'[]'))
		   
	   
           FETCH NEXT FROM ColumnCursor_N INTO @StrMasterTag
        END;
		
		CLOSE ColumnCursor_N;
        DEALLOCATE ColumnCursor_N;
		
		SET @StrTempateJson = REPLACE(@StrTempateJson,'##ClientCode##',@strUserid)
		SET @StrTempateJson = REPLACE(@StrTempateJson,'##UserId##',@strUserid)
	    
		SET @StrTempateJson = REPLACE(@StrTempateJson,'"~~Attachments~~"', '[]')
		SET @StrTempateJson = REPLACE(@StrTempateJson,'"~~RelatedPersonDetails~~"', '[]')
		
	    DECLARE @Nomjson NVARCHAR(MAX);
	  
	    DECLARE @StrNomSrno INT
	    DECLARE ColumnCursor_NM CURSOR FOR
        SELECT DISTINCT ColumnValue 
	    FROM #tbl_jsonoutput1 WHERE MasterTag = 'NomineeDetails' AND ColumnName = 'NomSerial'
        OPEN ColumnCursor_NM;
	    FETCH NEXT FROM ColumnCursor_NM INTO @StrNomSrno
        WHILE @@FETCH_STATUS = 0
        BEGIN
	      SET @Nomjson =(SELECT NomGuardianSerial = cn_Srno, NomGuardianFirstName = (
	      CASE WHEN CHARINDEX(' ', cn_name) > 0 THEN SUBSTRING(cn_name, 1, CHARINDEX(' ', 
		  cn_name) - 1) ELSE cn_name END), 
		  NomGuardianMiddleName = (CASE WHEN CHARINDEX(' ', cn_name) = 0 THEN '' 
		  ELSE RTRIM(LTRIM(REPLACE(REPLACE(cn_name, SUBSTRING(cn_name, 1, CHARINDEX(' ', 
          cn_name) - 1), ''), REVERSE(LEFT(REVERSE(cn_name), 
		  CHARINDEX(' ',REVERSE(cn_name)) - 1)), ''))) END), 
		  NomGuardianLastName = (CASE WHEN CHARINDEX(' ', cn_name) > 0 THEN 
		  REVERSE(LEFT(REVERSE(cn_name), CHARINDEX(' ', REVERSE(cn_name)) - 1)) ELSE '' END), 
		  NomGuardianCountry = ltrim(rtrim(cn_Country)), 
		  NomGuardianState = ltrim(rtrim(cn_State)), 
		  NomGuardianCity = ltrim(rtrim(cn_City)), 
		  NomGuardianAddress1 = ltrim(rtrim(cn_Add1)), 
		  NomGuardianAddress2 = ltrim(rtrim(cn_Add2)), 
		  NomGuardianAddress3 = ltrim(rtrim(cn_Add3)), 
		  NomGuardianPAN = ltrim(rtrim(cn_PAN)), NomGuardianPincode = ltrim(rtrim(cn_Pin)), 
          NomGuardianUID = cn_UID, NomGuardianRelation = (CASE WHEN ISNULL(cn_Relation, '') ='Spouse' THEN '01'  
		    WHEN ISNULL(cn_Relation, '') ='Son' THEN '02'  
			WHEN ISNULL(cn_Relation, '') ='Daughter' THEN '03'  
			WHEN ISNULL(cn_Relation, '') ='Father' THEN '04'  
			WHEN ISNULL(cn_Relation, '') ='Mother' THEN '05'  
			WHEN ISNULL(cn_Relation, '') ='Brother' THEN '06'  
			WHEN ISNULL(cn_Relation, '') ='Sister' THEN '07'  
			WHEN ISNULL(cn_Relation, '') ='Grandson' THEN '08' 
			WHEN ISNULL(cn_Relation, '') ='Granddaughter' THEN '09'  
			WHEN ISNULL(cn_Relation, '') ='Grandfather' THEN '10'  
			WHEN ISNULL(cn_Relation, '') ='Grandmother' THEN '11'  
			WHEN ISNULL(cn_Relation, '') ='Not Provided' THEN '12'  
			WHEN ISNULL(cn_Relation, '') ='Others' THEN '13' ELSE  ISNULL(cn_Relation, '') END), 
            NomGuardianDOB = cn_DOB, NomGuardianMobile = ltrim(rtrim(cn_Tel)), NomGuardianEmail = ltrim(rtrim(cn_Email)),
			NomGuardianId = 100 + cn_Srno , NomineeId = 1000 + (cn_Srno - 1)
			FROM Client_NomineeDetails(NOLOCK)
			WHERE cn_Cmcd = @strUserid AND cn_Srno = @StrNomSrno + 1 FOR JSON PATH)
		  IF ISNULL(@Nomjson,'') <> ''
          BEGIN		  
	        SET @Nomjson = SUBSTRING(@Nomjson,2,LEN(@Nomjson))
	        SET @Nomjson  = SUBSTRING(@Nomjson,1,LEN(@Nomjson)-1)
		  END	
		
	      SET @StrTempateJson = REPLACE(@StrTempateJson,'"#'+CAST(@StrNomSrno AS VARCHAR)+'#"', ISNULL(@Nomjson,'""')) 
		  SET @StrTempateJson = REPLACE(@StrTempateJson,'"#'+CAST(@StrNomSrno AS VARCHAR)+'#"', '""') 
	    
		  FETCH NEXT FROM ColumnCursor_NM INTO @StrNomSrno
        END;
		
	    CLOSE ColumnCursor_NM;
        DEALLOCATE ColumnCursor_NM;
	  
	  --SET @StrTempateJson = REPLACE(@StrTempateJson,'"~~GuardianDetails~~"', @Nomjson)				
	    SET @StrTempateJson = REPLACE(@StrTempateJson,'##ClientCode##',@strUserid)
	    SET @StrTempateJson = REPLACE(@StrTempateJson,'"~~GuardianDetails~~"', '""')
	    SET @StrTempateJson = REPLACE(@StrTempateJson,'"~~NomineeDetails~~"', '""')
	    SET @StrTempateJson = REPLACE(@StrTempateJson,'"~~BankDetails~~"', '""')
	    SET @StrTempateJson = REPLACE(@StrTempateJson,'"~~DematDetails~~"', '""')
		SET @StrTempateJson = REPLACE(@StrTempateJson,'##UserId##',@strUserid)
	    SELECT @StrTempateJson
	    RETURN 1			
	  END
	  
	  ELSE IF @strEntryName IN('REKYC','REKYCOFFLINE') AND @strOption <> 'Master_Edit'
	  BEGIN
	    DECLARE @Nomjson1 NVARCHAR(MAX);
		SET @Nomjson1 =(SELECT NomGuardianSerial = cn_Srno, NomGuardianFirstName = (
			CASE WHEN CHARINDEX(' ', cn_name) > 0 THEN SUBSTRING(cn_name, 1, CHARINDEX(' ', 
			cn_name) - 1) ELSE cn_name END), 
			NomGuardianMiddleName = (CASE WHEN CHARINDEX(' ', cn_name) = 0 THEN '' 
			ELSE RTRIM(LTRIM(REPLACE(REPLACE(cn_name, SUBSTRING(cn_name, 1, CHARINDEX(' ', 
            cn_name) - 1), ''), REVERSE(LEFT(REVERSE(cn_name), 
			CHARINDEX(' ',REVERSE(cn_name)) - 1)), ''))) END), 
			NomGuardianLastName = (CASE WHEN CHARINDEX(' ', cn_name) > 0 THEN 
			REVERSE(LEFT(REVERSE(cn_name), CHARINDEX(' ', REVERSE(cn_name)) - 1)) ELSE '' END), 
			NomGuardianCountry = ltrim(rtrim(cn_Country)), 
			NomGuardianState = ltrim(rtrim(cn_State)), 
			NomGuardianCity = ltrim(rtrim(cn_City)), 
			NomGuardianAddress1 = ltrim(rtrim(cn_Add1)), 
			NomGuardianAddress2 = ltrim(rtrim(cn_Add2)), 
			NomGuardianAddress3 = ltrim(rtrim(cn_Add3)), 
			NomGuardianPAN = ltrim(rtrim(cn_PAN)), NomGuardianPincode = ltrim(rtrim(cn_Pin)), 
            NomGuardianUID = cn_UID, NomGuardianRelation = (CASE WHEN ISNULL(cn_Relation, '') ='Spouse' THEN '01'  
		    WHEN ISNULL(cn_Relation, '') ='Son' THEN '02'  
			WHEN ISNULL(cn_Relation, '') ='Daughter' THEN '03'  
			WHEN ISNULL(cn_Relation, '') ='Father' THEN '04'  
			WHEN ISNULL(cn_Relation, '') ='Mother' THEN '05'  
			WHEN ISNULL(cn_Relation, '') ='Brother' THEN '06'  
			WHEN ISNULL(cn_Relation, '') ='Sister' THEN '07'  
			WHEN ISNULL(cn_Relation, '') ='Grandson' THEN '08' 
			WHEN ISNULL(cn_Relation, '') ='Granddaughter' THEN '09'  
			WHEN ISNULL(cn_Relation, '') ='Grandfather' THEN '10'  
			WHEN ISNULL(cn_Relation, '') ='Grandmother' THEN '11'  
			WHEN ISNULL(cn_Relation, '') ='Not Provided' THEN '12'  
			WHEN ISNULL(cn_Relation, '') ='Others' THEN '13' ELSE  ISNULL(cn_Relation, '') END), 
            NomGuardianDOB = cn_DOB, NomGuardianMobile = ltrim(rtrim(cn_Tel)), NomGuardianEmail = ltrim(rtrim(cn_Email)),
			NomGuardianId = 100 + cn_Srno , NomineeId = 1000 + (cn_Srno - 1)
			FROM Client_NomineeDetails(NOLOCK)
			WHERE cn_Cmcd = @strUserid AND cn_Srno = @strNomSerial + 1 FOR JSON PATH)
		SET @Nomjson1 = SUBSTRING(@Nomjson1,2,LEN(@Nomjson1))
		SET @Nomjson1  = SUBSTRING(@Nomjson1,1,LEN(@Nomjson1)-1)
		SET @StrTempateJson = REPLACE(@StrTempateJson,'"~~GuardianDetails~~"', @Nomjson1)				
		SET @StrTempateJson = REPLACE(@StrTempateJson,'##ClientCode##',@strUserid)
		SET @StrTempateJson = REPLACE(@StrTempateJson,'"~~GuardianDetails~~"', '')
		SET @StrTempateJson = REPLACE(@StrTempateJson,'"~~NomineeDetails~~"', '')
		SET @StrTempateJson = REPLACE(@StrTempateJson,'"~~BankDetails~~"', '')
		SET @StrTempateJson = REPLACE(@StrTempateJson,'"~~DematDetails~~"', '')
		SET @StrTempateJson = REPLACE(@StrTempateJson,'##UserId##',@strUserid)
		SELECT @StrTempateJson
		RETURN 1			
	  END
    END
    
    SELECT @StrGetFilter = downloadFilters FROM tbl_TradeWebMenu (NOLOCK) WHERE MenuTag = @strEntryName
	
    SET @strDanSql = 'EXEC '+@strtradeplustempdb+'.DBO.sp_JsonCutter'+' '''+@StrGetFilter+''' , @jsonCutterOutput OUTPUT';
    EXEC sp_executesql @strDanSql, N'@jsonCutterOutput VARCHAR(MAX) OUTPUT', @jsonCutterOutput OUTPUT;
	
    SET @JsonCutterXML= CAST(@jsonCutterOutput AS XML)

    INSERT INTO #tbl_jsonoutput1(ColumnName, ColumnValue, MasterTag, JsonLevel, MasterLevel)
    SELECT X1.* FROM(
    SELECT --JsonCutter.value('(SerialNo)[1]', 'int') AS SerialNo ,
    JsonCutter.value('(ColumnName)[1]', 'VARCHAR(1000)') AS ColumnName ,
    JsonCutter.value('(ColumnValue)[1]', 'VARCHAR(max)') AS ColumnValue,
    JsonCutter.value('(MasterTag)[1]', 'VARCHAR(50)') AS MasterTag,
    JsonCutter.value('(JsonLevel)[1]', 'INT') AS JsonLevel,
    JsonCutter.value('(MasterLevel)[1]', 'INT') AS MasterLevel
    FROM @JsonCutterXML.nodes('/JsonCutter') AS XTbl(JsonCutter)) X1

    DECLARE @strwhere VARCHAR(MAX)='', @String NVARCHAR(MAX)=''

    UPDATE A SET A.ColumnValue = B.ParameterValue
    FROM #tbl_jsonoutput1 A, @tbl_InputJSONTable B
    WHERE A.MASTERTAG = 'X_Filter'
    AND B.ParameterName = A.ColumnName

    UPDATE A set A.FieldName = b.FieldName
    FROM #tbl_jsonoutput1 A, tbl_GenericTemplateDefinition(nolock) B
    WHERE B.TemplateNAME = @strEntryName
    AND A.ColumnName = B.TagName
    AND B.ParentTemplateCode = CASE WHEN @strOption= 'Master_Edit' THEN 'Entry' else 'ChildEntry' end
    
 
    
    SELECT @strwhere = @strwhere+' '+ ' AND '+FieldName+' = '''+CAST(ColumnValue AS VARCHAR)+''''
    FROM(
    SELECT DISTINCT COLUMNNAME, ColumnValue, FieldName FROM #tbl_jsonoutput1 
    WHERE MASTERTAG = 'X_Filter'
    AND ISNULL(FieldName,'') <> '') X1

    
    DECLARE @ColumnDefinitions TABLE (ColumnName NVARCHAR(128), TagName NVARCHAR(128));

    INSERT INTO @ColumnDefinitions (ColumnName, TagName)
    SELECT FieldName, TagName
    FROM tbl_GenericTemplateDefinition(NOLOCK)
    WHERE ParentTemplateCode = CASE WHEN @strOption= 'Master_Edit' THEN 'Entry' else 'ChildEntry' end
    AND TemplateName = @strEntryName and ISNULL(FieldName,'') <> ''
    ORDER BY OrderBy;
    --SELECT @StrTempateJson
    DECLARE @TBL_ColumnValue TABLE(ColumnValue VARCHAR(MAX))

    DECLARE @ColumnName NVARCHAR(128);
    DECLARE @TagName NVARCHAR(128);

    DECLARE ColumnCursor CURSOR FOR
    SELECT ColumnName, TagName
    FROM @ColumnDefinitions
    OPEN ColumnCursor;
    FETCH NEXT FROM ColumnCursor INTO @ColumnName, @TagName;
    WHILE @@FETCH_STATUS = 0
    BEGIN
      DELETE FROM @TBL_ColumnValue
	  
	  SET @String = 'SELECT distinct '+@ColumnName+' from '+@strTableName+' WHERE 1 = 1  '+@strwhere
	  
      INSERT INTO @TBL_ColumnValue(ColumnValue)
      EXEC(@String)
      
      SET @StrTempateJson = REPLACE(@StrTempateJson,'~~'+@ColumnName+'~~',ISNULL((SELECT TOP 1 ColumnValue FROM @TBL_ColumnValue),''))

      FETCH NEXT FROM ColumnCursor INTO @ColumnName, @TagName;
    END;

    SET @StrTempateJson = REPLACE(@StrTempateJson,'~~~~','')

    CLOSE ColumnCursor;
    DEALLOCATE ColumnCursor;
	
	DELETE FROM @ColumnDefinitions
	
	DECLARE @Sql NVARCHAR(MAX) = N'SELECT ';
	DECLARE @Delimiter NVARCHAR(2) = ', ';
	DECLARE @strDataType VARCHAR(50)=''	
	
	INSERT INTO @ColumnDefinitions (ColumnName, TagName)
    SELECT FieldName, TagName
    FROM tbl_GenericTemplateDefinition(NOLOCK)
    WHERE ParentTemplateCode = CASE WHEN @strOption= 'Master_Edit' THEN 'ChildEntry' else '' end
    AND TemplateName = @strEntryName and ISNULL(FieldName,'') <> ''
    ORDER BY OrderBy;

	DECLARE ColumnCursor1 CURSOR FOR
	SELECT ColumnName, TagName
	FROM @ColumnDefinitions;

	OPEN ColumnCursor1;

	FETCH NEXT FROM ColumnCursor1 INTO @ColumnName, @TagName;

	WHILE @@FETCH_STATUS = 0
	BEGIN
	  
	  SELECT @strDataType = DATA_TYPE  
      FROM INFORMATION_SCHEMA.COLUMNS 
      WHERE TABLE_NAME = @strChildtableName AND COLUMN_NAME = @ColumnName

	  IF @strDataType IN('varchar','char','DATE','DATETIME')
	  BEGIN
	    SET @Sql = @Sql + 'ISNULL('+QUOTENAME(@ColumnName)+','''')' + ' AS ' + QUOTENAME(@TagName) + @Delimiter;
	  END
      ELSE
      BEGIN
	    SET @Sql = @Sql + 'ISNULL('+QUOTENAME(@ColumnName)+',0)' + ' AS ' + QUOTENAME(@TagName) + @Delimiter;
      END 	  
	  FETCH NEXT FROM ColumnCursor1 INTO @ColumnName, @TagName;
	END;

	CLOSE ColumnCursor1;
    DEALLOCATE ColumnCursor1;
	--SELECT @Sql
    

    UPDATE A set A.FieldName = b.FieldName
    FROM #tbl_jsonoutput1 A, tbl_GenericTemplateDefinition(nolock) B
    WHERE B.TemplateNAME = @strEntryName
    AND A.ColumnName = B.TagName
    AND B.ParentTemplateCode = 'ChildEntry'
	
	--SELECT * FROM #tbl_jsonoutput1

    SET @strwhere = ''
    SELECT @strwhere = @strwhere+' '+ ' AND '+FieldName+' = '''+CAST(ColumnValue AS VARCHAR)+''''
    FROM(
    SELECT DISTINCT COLUMNNAME, ColumnValue, FieldName FROM #tbl_jsonoutput1 
    WHERE MASTERTAG = 'X_Filter'
    AND ISNULL(FieldName,'') <> '' AND ISNULL(ColumnValue,'') NOT LIKE '##%') X1

    
		-- Remove the trailing delimiter
	SET @Sql = LEFT(@Sql, LEN(@Sql) - LEN(@Delimiter));
		-- Append the table name
	SET @Sql = @Sql + ' FROM ' + QUOTENAME(@strChildtableName) + ' WHERE 1=1 '+@strwhere;
	
	SELECT @StrTempateJson
	--SELECT @Sql
	IF @strOption= 'Master_Edit' AND EXISTS(SELECT 1 FROM @ColumnDefinitions)
	BEGIN
	  EXEC sp_executesql @Sql;
	END  
  END    
END 
GO

CREATE PROCEDURE stpr_MobileApplicationMail @strClientCode VARCHAR(50), 
@StrMailType VARCHAR(50), @strFileName VARCHAR(100), @Strbase64Attchment NVARCHAR(MAX), @strParamater VARCHAR(MAX),
@o_errorFlag VARCHAR(1) OUTPUT, @o_errormessage VARCHAR(MAX) OUTPUT WITH ENCRYPTION AS
BEGIN
  DECLARE  @i_vcInputJsonPDF VARCHAR(MAX) = '{"reqestName": "Email","requestObject": {"ToEmailId": "##ToEmailId##","CCEmailId": "##CCEmailId##","BCCEmailId": "##BCCEmailId##",
  "Subject": "##Subject##","Body": "##Body##","Attachment":[{"FileName":"##FileName1##","Base64":"##Base641##"}]}}',
  @o_vcOutputJsonPDF VARCHAR(MAX) = '', @strtradeplustempdb VARCHAR(MAX)='', @strThirdPartyURL VARCHAR(100)=''
  SET @o_errorFlag = 'S'
  SET @o_errormessage = 'Process Completed'

  DECLARE @strBodyText NVARCHAR(MAX)='', @strCCEMailid VARCHAR(100)='', @strBCCEMailid VARCHAR(100)='', 
  @strToEmailid VARCHAR(100)='',@strSubject VARCHAR(MAX)='', @strCompamnyName VARCHAR(100)='', 
  @strFileName1 VARCHAR(100)=''
  
  SELECT @strtradeplustempdb = sp_sysvalue 
  FROM WebParameter(NOLOCK) WHERE sp_parmcd = 'TRADEPLUSTEMPDB' 
  IF ISNULL(@strFileName,'') = '' AND   ISNULL(@Strbase64Attchment,'') <> ''       
  BEGIN
    SET @o_errorFlag = 'E'
    SET @o_errormessage = 'File Name can not be null'  
	RETURN 1
  END
  
  SELECT @strToEmailid = cm_email 
  FROM Client_Master(NOLOCK) WHERE CM_cD = @strClientCode
  --SET @strToEmailid = ''
  
  IF  ISNULL(@strToEmailid,'') <> ''
  BEGIN
    SELECT @strBodyText = BodyText, @strCCEMailid = CCEmail, @strBCCEMailid = BCCEmailid , @strSubject = EmailSubject
    FROM tbl_EmailTemplate(NOLOCK) WHERE RefName = @StrMailType
	
	IF @strBodyText = ''
	BEGIN
	  SELECT @strBodyText = BodyText, @strCCEMailid = CCEmail, @strBCCEMailid = BCCEmailid , @strSubject = EmailSubject
      FROM tbl_EmailTemplate(NOLOCK) WHERE RefName ='CommonFormat'
	END
	
	IF ISNULL(@strBodyText,'') = ''
	BEGIN
	  SET @o_errorFlag = 'E'
      SET @o_errormessage = 'Mail Template Not Define'
	  RETURN 1
	END
	
	SELECT TOP 1 @strCompamnyName = LTRIM(RTRIM(EM_NAME)) from Entity_master(NOLOCK) 
	WHERE em_cd =(select min(em_cd) from Entity_master(NOLOCK))
		   
	DECLARE @StrCompanyCount INT = 0
		   
	SELECT @StrCompanyCount = ISNULL(SUM(ISNULL(cnt,0)),0) 
    FROM ( SELECT COUNT(0) Cnt From Entity_master(NOLOCK) 
    WHERE em_bse <> 'N' and isNull(em_bclearingno,'') in ('189') 
    UNION ALL 
    SELECT count(0) Cnt From Entity_master(NOLOCK) 
    WHERE em_nse <> 'N' and isNull(em_nclearingno,'') in ('07277')) a
	
	IF @StrCompanyCount > 0
	BEGIN
	   SELECT @strCompamnyName= LTRIM(RTRIM(em_Name)) FROM Entity_master(NOLOCK)  
	   WHERE em_cd = 'B'
	END
	
	SET @strBodyText = REPLACE(@strBodyText,'##CompanyName##',@strCompamnyName)
	SET @strBodyText = REPLACE(@strBodyText,'<<ReportName>>',@StrMailType)
	

	
	IF ISNULL(@strParamater,'') <> ''
	BEGIN
	  DECLARE @tbl_jsonoutput TABLE(SerialNo INT, ColumnName VARCHAR(50), ColumnValue VARCHAR(MAX), 
      MasterTag VARCHAR(100), JSONLEVEL INT, MASTERLEVEL INT)
	
	  DECLARE @jsonCutterOutput VARCHAR(MAX)='', @strDanSql NVARCHAR(MAX)=''
      SET @strDanSql = 'EXEC '+@strtradeplustempdb+'.DBO.sp_JsonCutter'+' '''+@strParamater+''' , @jsonCutterOutput OUTPUT';
      EXEC sp_executesql @strDanSql, N'@jsonCutterOutput VARCHAR(MAX) OUTPUT', @jsonCutterOutput OUTPUT;
      DECLARE @JsonCutterXML XML = CAST(@jsonCutterOutput AS XML)
      INSERT INTO @tbl_jsonoutput(SerialNo, ColumnName, ColumnValue, MasterTag, JsonLevel, MasterLevel)
	  SELECT X1.* FROM(
      SELECT JsonCutter.value('(SerialNo)[1]', 'int') AS SerialNo ,
	  JsonCutter.value('(ColumnName)[1]', 'VARCHAR(1000)') AS ColumnName ,
      JsonCutter.value('(ColumnValue)[1]', 'VARCHAR(max)') AS ColumnValue,
	  JsonCutter.value('(MasterTag)[1]', 'VARCHAR(50)') AS MasterTag,
	  JsonCutter.value('(JsonLevel)[1]', 'INT') AS JsonLevel,
	  JsonCutter.value('(MasterLevel)[1]', 'INT') AS MasterLevel
      FROM @JsonCutterXML.nodes('/JsonCutter') AS XTbl(JsonCutter)) X1
	
	  DECLARE @strColumnName VARCHAR(100)='', @StrColumnValue VARCHAR(MAX)=''
	
	  IF EXISTS(SELECT 1 FROM @tbl_jsonoutput) 
	  BEGIN
	    DECLARE Cur1 CURSOR FOR 
        SELECT ColumnName, ColumnValue FROM @tbl_jsonoutput
        OPEN Cur1 
        FETCH NEXT FROM Cur1 INTO @strColumnName, @StrColumnValue
        WHILE @@FETCH_STATUS = 0
        BEGIN 
		  IF @strColumnName LIKE '%Date%' AND ISNULL(@StrColumnValue,'') <> ''
		  BEGIN
		    SET @StrColumnValue = CONVERT(VARCHAR,CAST(@StrColumnValue AS DATE),103)
		  END
		
	      IF CHARINDEX('##'+@strColumnName+'##',@strBodyText) > 0
          BEGIN
	        SET @strBodyText = REPLACE(@strBodyText, '##'+@strColumnName+'##', @StrColumnValue)
		  END
		  
		  IF CHARINDEX('##'+@strColumnName+'##',@strSubject) > 0
          BEGIN
	        SET @strSubject = REPLACE(@strSubject, '##'+@strColumnName+'##', @StrColumnValue)
		  END

	      FETCH NEXT FROM Cur1 INTO @strColumnName, @StrColumnValue
        END 
        CLOSE Cur1 
        DEALLOCATE Cur1 
	  END
	END
	
	SET @strSubject = REPLACE(@strSubject,'##CompanyName##',@strCompamnyName)
	SET @strSubject = REPLACE(@strSubject,'<<ReportName>>',@StrMailType)
	
	IF @strSubject = ''
	BEGIN
	  SET @strSubject = 'Report :- '+@StrMailType+' From -'+@strCompamnyName
	END
	
	SELECT @strThirdPartyURL = sp_sysvalue 
    FROM Sysparameter(NOLOCK) WHERE sp_parmcd = 'ThirdParty'

	SET @strBodyText = REPLACE(@strBodyText,'##CompanyName##',@strCompamnyName)
	
	SET @i_vcInputJsonPDF = REPLACE(@i_vcInputJsonPDF,'##ToEmailId##',@strToEmailid)
    SET @i_vcInputJsonPDF = REPLACE(@i_vcInputJsonPDF,'##CCEmailId##',@strCCEMailid)
    SET @i_vcInputJsonPDF = REPLACE(@i_vcInputJsonPDF,'##BCCEmailId##',@strBCCEMailid)
    SET @i_vcInputJsonPDF = REPLACE(@i_vcInputJsonPDF,'##BCCEmailId##',@strBCCEMailid)
    SET @i_vcInputJsonPDF = REPLACE(@i_vcInputJsonPDF,'##Subject##',@strSubject)
    SET @i_vcInputJsonPDF = REPLACE(@i_vcInputJsonPDF,'##Body##',@strBodyText)
    SET @i_vcInputJsonPDF = REPLACE(@i_vcInputJsonPDF,'##FileName1##',@strFileName)
    SET @i_vcInputJsonPDF = REPLACE(@i_vcInputJsonPDF,'##Base641##',@Strbase64Attchment)
	SET @o_vcOutputJsonPDF = ''
	--SELECT @i_vcInputJsonPDF
	EXEC stpr_APISendEmail @i_vcInputJsonPDF, 'EMAIL', @strThirdPartyURL, @o_vcOutputJsonPDF OUTPUT

    INSERT INTO tbl_EMailLog(Code, ToMailid, CCMailid, BCCMailid, EmailSubject, EmailBodyText,
	AttachmentFile1Name, AttachmentFile1, SendDate,Response,RefName)
	VALUES(@strClientCode,@strToEmailid, @strCCEMailid, @strBCCEMailid, @strSubject, @strBodyText, @strFileName,
	@Strbase64Attchment, GETDATE(), isnull(@o_vcOutputJsonPDF,0), @StrMailType)
  END  
  ELSE 
  BEGIN
    SET @o_errorFlag = 'E'
    SET @o_errormessage = 'Email id Not Define in CLient Master'
	RETURN 1
  END
  SET @o_errorFlag = 'S'
  SET @o_errormessage = @o_vcOutputJsonPDF
  RETURN 1
END
GO

CREATE PROCEDURE stpr_APISendEmail @i_vcInputJson VARCHAR(MAX), @i_OTPType VARCHAR(20) = 'EMAIL',
@CallingAPIURLMain VARCHAR(MAX),
@o_vcOutputJson NVARCHAR(MAX) OUTPUT WITH ENCRYPTION AS
BEGIN
  SET @o_vcOutputJson = ''
  IF ISNULL(@i_OTPType,'') = 'EMAIL'
  BEGIN
    SET @CallingAPIURLMain = @CallingAPIURLMain+'/api/Main/SendEmail'  
  END
  ELSE IF ISNULL(@i_OTPType,'') = 'OTP'
  BEGIN 
    SET @CallingAPIURLMain = @CallingAPIURLMain+'/api/ThirdPartyService/SendOTP'  
  END
  ELSE IF ISNULL(@i_OTPType,'') = 'OTPValidate'
  BEGIN 
    SET @CallingAPIURLMain = @CallingAPIURLMain+'/api/ThirdPartyService/VerifyOTP'  
  END
  DECLARE @Object AS INT;  
  DECLARE @ResponseText AS VARCHAR(8000)='';  
  Declare @tbl_OutputResponse as table(Json_Table nvarchar(max))
  DECLARE @VCOUTPUT VARCHAR(MAX)=''  
  EXEC sp_OACreate 'MSXML2.XMLHTTP', @Object OUT;  
  EXEC sp_OAMethod @Object, 'open', NULL, 'post',@CallingAPIURLMain, 'false' 
  EXEC sp_OAMethod @Object, 'setRequestHeader', null, 'Content-Type', 'application/json'  
  EXEC sp_OAMethod @Object, 'send', null, @i_vcInputJson  
  INSERT INTO @tbl_OutputResponse (Json_Table) EXEC sp_OAMethod @Object, 'responseText'
  SELECT @VCOUTPUT = Json_Table FROM @tbl_OutputResponse
  SET @o_vcOutputJson = @VCOUTPUT  
  
  EXEC sp_OADestroy @Object  
  
  RETURN 1
END
GO

CREATE PROCEDURE stpr_GetLastTradingDate @dsXml VARCHAR(MAX)  
WITH ENCRYPTION AS
BEGIN 
  DECLARE @tbl_InputJSONTable DBO.tb_ParamList ;
  DECLARE @o_ParameterList varchar(max)='', @o_ParameterListxml XML; 
  DECLARE @tbl_UserList dbo.UserAccessList;
  DECLARE @strDT VARCHAR(10)=''
  
  EXEC SP_ParameterXMLRep @dsXml, @o_ParameterList OUTPUT
  
  IF ISNULL(@o_ParameterList,'') <> ''
  BEGIN
	SET @o_ParameterListxml = CAST(@o_ParameterList AS XML)
    INSERT INTO @tbl_InputJSONTable (ParameterName,  ParameterValue, HeaderName, Jsontag) 
    SELECT Parameter.value('(ColumnName)[1]', 'VARCHAR(MAX)') AS Client_Code ,
    Parameter.value('(ColumnValue)[1]', 'VARCHAR(MAX)') AS ColumnValue,
	Parameter.value('(MasterTag)[1]', 'VARCHAR(MAX)') AS MasterTag,
	Parameter.value('(JsonLevel)[1]', 'VARCHAR(MAX)') AS JsonLevel
    FROM @o_ParameterListxml.nodes('/Parameter') AS XTbl(Parameter)
  END	
  SELECT @strDT = MAX(FM_DT) FROM Fmargins(NOLOCK) 
  SELECT @strDT As 'LastTradeDate'
END
GO

CREATE PROCEDURE stpr_MobileMenuProcedure @dsXml VARCHAR(MAX)  
WITH ENCRYPTION AS
BEGIN 
  DECLARE @tbl_InputJSONTable DBO.tb_ParamList ;
  DECLARE @o_ParameterList varchar(max)='', @o_ParameterListxml XML; 
 
  
  EXEC SP_ParameterXMLRep @dsXml, @o_ParameterList OUTPUT
  
  IF ISNULL(@o_ParameterList,'') <> ''
  BEGIN
	SET @o_ParameterListxml = CAST(@o_ParameterList AS XML)
    INSERT INTO @tbl_InputJSONTable (ParameterName,  ParameterValue, HeaderName, Jsontag) 
    SELECT Parameter.value('(ColumnName)[1]', 'VARCHAR(MAX)') AS Client_Code ,
    Parameter.value('(ColumnValue)[1]', 'VARCHAR(MAX)') AS ColumnValue,
	Parameter.value('(MasterTag)[1]', 'VARCHAR(MAX)') AS MasterTag,
	Parameter.value('(JsonLevel)[1]', 'VARCHAR(MAX)') AS JsonLevel
    FROM @o_ParameterListxml.nodes('/Parameter') AS XTbl(Parameter)
  END	  
  
  DECLARE @StrRequestFrom VARCHAR(1)='M', @strJson VARCHAR(MAX)='', @strUserid VARCHAR(50)='', 
  @strUserType VARCHAR(30)
  DECLARE @TBL_json TABLE(SerialNo int, Jsonvalue VARCHAR(MAX), ParentName VARCHAR(MAX), TargetForm VARCHAR(MAX), MenuNameP VARCHAR(50), 
  PMenuCode VARCHAR(50))

  SELECT @strRequestFrom = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'RequestFrom'
  SELECT @strUserid = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Userid'
  SELECT @strUserType = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'UserType'
  
  IF @strUserType = 'branch'
  BEGIN
    SET @strUserType = 'Branch'
  END 
  ELSE IF @strUserType = 'User'
  BEGIN
    SET @strUserType = 'Client'
  END 
  
  IF ISNULL(@strUserType,'') = ''
  BEGIN
    SET @strUserType = 'Client'
  END
  
  DECLARE @TBL_TradeWebMenu TABLE([SrNo] [decimal](18, 0) NOT NULL, [ModuleCode] [int] NOT NULL, 
  [MenuCode] [varchar](20) NOT NULL, [MenuName] [varchar](50) NOT NULL, [MenuTag] [varchar](50) NOT NULL, 
  [ParentMenu] [varchar](50) NOT NULL, [DenyRights] [varchar](50) NOT NULL, [TargetForm] [varchar](50) NOT NULL, 
  [Path] [varchar](50) NOT NULL, [Enable] [char](1) NOT NULL, [Rights] [varchar](max) NULL, 
  [IconPath] [varchar](50) NOT NULL, [MenuType] [char](1) NULL, [Productid] [varchar](10) NOT NULL, [filters] [varchar](max) NOT NULL,
  [downloadFilters] [varchar](max) NOT NULL, [primaryHeaderKey] [varchar](50) NOT NULL, 
  [LevelSetting] [varchar](max) NOT NULL, [Level2Setting] [varchar](max) NOT NULL, 
  [ShowFilter1] [varchar](max) NOT NULL, [ShowFilter2] [varchar](max) NOT NULL,[ShowFilter3] [varchar](max) NOT NULL,
  [BranchFilters] [varchar](max) NOT NULL)
  
  
  INSERT INTO @TBL_TradeWebMenu(SrNo, ModuleCode, MenuCode, MenuName, MenuTag, ParentMenu, DenyRights, TargetForm, Path,
  Enable, Rights, IconPath, MenuType, Productid, filters, downloadFilters, primaryHeaderKey, LevelSetting, Level2Setting,
  ShowFilter1, ShowFilter2, ShowFilter3, BranchFilters)
  SELECT SrNo, ModuleCode, MenuCode, MenuName, MenuTag, ParentMenu, DenyRights, TargetForm, Path,
  Enable, Rights, IconPath, MenuType, Productid, filters, downloadFilters, primaryHeaderKey, LevelSetting, Level2Setting,
  ShowFilter1, ShowFilter2, ShowFilter3, BranchFilters
  FROM TBL_TradeWebMenu(NOLOCK)
  WHERE Enable = 'Y'
  UNION ALL
  SELECT SrNo, ModuleCode, MenuCode, MenuName, MenuTag, ParentMenu, DenyRights, TargetForm, Path,
  Enable, Rights, IconPath, MenuType, Productid, filters, downloadFilters, primaryHeaderKey, LevelSetting, Level2Setting,
  ShowFilter1, ShowFilter2, ShowFilter3, BranchFilters
  FROM tbl_WebAdditionalMenu(NOLOCK)
  WHERE Enable = 'Y'
  

  INSERT INTO @TBL_json(SerialNo, Jsonvalue, ParentName, TargetForm, MenuNameP, PMenuCode)
  SELECT SrNo, Jsonvalue = (SELECT SrNo, SrNo as [id], [title] = MenuName,
  [componentName] = Menutag, 
  [componentType] = CASE WHEN ISNULL(ICONPATH,'') = 'E' THEN 'entry' WHEN ISNULL(ICONPATH,'') = 'M' THEN 'multientry' 
  WHEN ISNULL(ICONPATH,'') = 'I' THEN 'import' 
  WHEN ISNULL(ICONPATH,'') = 'J' THEN 'multireport' 
  WHEN ISNULL(ICONPATH,'') = 'U' THEN 'emailservices'
  WHEN ISNULL(ICONPATH,'') = 'T' THEN 'tradesplit'  
  else 'report' end,
  [icon] = CASE WHEN Menutag = 'Ledger' THEN 'balance-scale-left'
  WHEN Menutag LIKE '%Holding%' THEN 'hand-holding-usd'
  WHEN Menutag = 'OSPosition' THEN 'box-open'
  WHEN Menutag = 'AvailableMargin' THEN 'margin' 
  WHEN Menutag = 'PROFITLOSS' THEN 'bar-graph' 
  WHEN Menutag = 'Transaction' THEN 'memory' 
  WHEN Menutag = 'CGain' THEN 'memory' 
  WHEN Menutag = 'CGainHolding' THEN 'bar-graph' 
  WHEN Menutag = 'CGainDiviend' THEN 'margin' 
  WHEN Menutag = 'CGainListing' THEN 'hand-holding-usd' 
  WHEN Menutag = 'Collateral' THEN 'credit' 
  WHEN Menutag = 'Margin1' THEN 'margin' 
  WHEN Menutag = 'Margin2' THEN 'margin' 
  else '' end,
  [iconType] = CASE WHEN Menutag = 'Ledger' THEN 'fontawesome5'   
   WHEN Menutag LIKE '%Holding%' THEN 'fontawesome5'
   WHEN Menutag = 'AvailableMargin' THEN 'materialcommunityicons' 
   WHEN Menutag = 'OSPosition' THEN 'fontawesome6' 
   WHEN Menutag = 'PROFITLOSS' THEN 'entypo' 
   WHEN Menutag = 'Transaction' THEN 'fontawesome5' 
   WHEN Menutag = 'CGainHolding' THEN 'entypo' 
   WHEN Menutag = 'CGain' THEN 'fontawesome5'  
   WHEN Menutag = 'CGainDiviend' THEN 'materialcommunityicons' 
   WHEN Menutag = 'CGainListing' THEN 'fontawesome5' 
   WHEN Menutag = 'Collateral' THEN 'entypo' 
   WHEN Menutag = 'Margin1' THEN 'materialcommunityicons' 
   WHEN Menutag = 'Margin1' THEN 'materialcommunityicons' 
   else '' end ,
   [pageData] = (SELECT [wPage] = Menutag, [level] = CASE WHEN ISNULL(ParentMenu,'') = 'Reports' then MenuName else MenuName+'('+ParentMenu+')' end,
   [isShortAble] = (CASE WHEN MenuName = 'Ledger' then 'false' else 'true' end),
   [autoFetch] = 'false', --CASE WHEN ISNULL(@strUserType,'Client') = 'Branch' THEN 'false' ELSE  'true' END,
   [gridType] = 'card', [horizontalScroll] = 0,
   [filterType] = CASE WHEN MENUTAG IN('OffLineMarginPledge','FundRequest') THEN 'onPage' ELSE 'modal' END,
   [filters] = '##filters##', --downloadFilters = '##downloadFilters##' ,
   [Entry] = '##Entry##',
   [MasterbuttonConfig] = '##MasterbuttonConfig##',
   [buttonConfig] = '##buttonConfig##',
   levels = (SELECT * FROM(SELECT name = MenuName, primaryHeaderKey, [primaryKey] = primaryHeaderKey, level = 1, 
   [summary] = '##summary##',
   J_Ui = '##J_Ui##',
   [settings] = '##settings##'
   FROM @tbl_TradeWebMenu  XMM WHERE XMM.SrNo = XMAIN.SrNo 
   AND ISNULL(Enable,'N') = 'Y'
   UNION ALL
   SELECT name = 'Details', primaryHeaderKey, [primaryKey] = '', level = 2, [summary] = '##summary2##', J_Ui = '##J_Ui2##',
   [settings] = '##settings2##'
   FROM @tbl_TradeWebMenu  XMM WHERE XMM.SrNo = XMAIN.SrNo
   AND ISNULL(Level2Setting,'') <> ''  --MENUTAG NOT IN('OffLineMarginPledge','BUYBACK','PLEDGEREQ','REKYCVALIDATE','ClientClosure','CLIENTEXPORT','FundRequest')
   ) X1 FOR JSON PATH)
   FROM @tbl_TradeWebMenu  XM WHERE XM.SrNo = XMAIN.SrNo FOR JSON PATH)
   FROM @tbl_TradeWebMenu  XMAIN
   WHERE XMAIN.SrNo = XXX.SrNo AND ISNULL(Enable,'N') = 'Y' FOR JSON PATH), ParentMenu, ISNULL(TargetForm,''), ISNULL(MENUTAG,''), 
   ISNULL(MENUCode,'') 
   FROM @tbl_TradeWebMenu  XXX
   WHERE MenuType = 'C' 
   --AND ((CASE WHEN ISNULL(@strRequestFrom,'') = 'W' THEN  'T' ELSE @strRequestFrom END) = Productid or isnull(Productid,'') = '')
   AND ISNULL(Enable,'N') = 'Y'
   --AND ((@strUserType = 'Client' AND ISNULL(ICONPATH,'') = '') OR @strUserType <> 'Client')
   AND MenuName NOT IN('DashBoard')

   DECLARE @accessjson VARCHAR(MAX)=''      
   IF EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = 'dbo'  AND TABLE_NAME = 'tbl_GroupUserAccessMaster')
   BEGIN
     IF @strUserType = 'Client'	
     BEGIN
       SET @accessjson = (SELECT ButtonText As [ButtonType], [EnabledTag] = CASE WHEN isEnabled ='N' THEN 'false' else 'true' END 
	   FROM tbl_GroupUserAccessMaster(NOLOCK) WHERE GroupCode ='$CLIENT'
       FOR JSON PATH)
     END 	
     ELSE
     BEGIN
       SET @accessjson = (SELECT ButtonText As [ButtonType], [EnabledTag] = CASE WHEN isEnabled ='N' THEN 'false' else 'true' END 
	   FROM tbl_GroupUserAccessMaster(NOLOCK) WHERE GroupCode in(SELECT um_group_id FROM user_master(NOLOCK) WHERE um_user_id = @strUserid)
       FOR JSON PATH)
     END
   END	 
   
   IF ISNULL(@accessjson,'') <> ''
   BEGIN
     UPDATE X SET X.Jsonvalue = REPLACE(X.Jsonvalue,'"##MasterbuttonConfig##"',@accessjson)
     FROM @TBL_json X
   END
   ELSE
   BEGIN
     SET @accessjson = '[{"ButtonType":"Excel","EnabledTag":"true"},{"ButtonType":"Email","EnabledTag":"true"},{"ButtonType":"Download","EnabledTag":"true"},{"ButtonType":"CSV","EnabledTag":"true"},{"ButtonType":"PDF","EnabledTag":"true"}]'
     UPDATE X SET X.Jsonvalue = REPLACE(X.Jsonvalue,'"##MasterbuttonConfig##"',@accessjson)
     FROM @TBL_json X
   END
   
   DECLARE @strPMenuCode VARCHAR(50)=''
   DECLARE CurButtonUpd
   CURSOR FOR SELECT  DISTINCT PMenuCode 
   FROM @TBL_json X
  
   OPEN CurButtonUpd 
   FETCH NEXT FROM CurButtonUpd INTO @strPMenuCode
   WHILE @@FETCH_STATUS = 0
   BEGIN 
     IF NOT EXISTS(SELECT 1 FROM tbl_GroupUserAccessDetail(NOLOCK)  
	 WHERE ((GroupCode in(SELECT um_group_id FROM user_master(NOLOCK) WHERE um_user_id = @strUserid)
	 AND @strUserType <> 'Client') OR (GroupCode = '$CLIENT' AND @strUserType = 'Client'))
	 AND ButtonText ='Visible' AND ISNULL(isEnabled,'N') = 'Y' AND MenuCode = @strPMenuCode)
	 BEGIN
	   DELETE FROM @TBL_json  where PMenuCode = @strPMenuCode
	 END
	 ELSE
	 BEGIN
       SET @accessjson = (SELECT ButtonText As [ButtonType], [EnabledTag] = CASE WHEN isEnabled ='N' THEN 'false' else 'true' END 
	   FROM tbl_GroupUserAccessDetail(NOLOCK) 
	   WHERE ((GroupCode in(SELECT um_group_id FROM user_master(NOLOCK) WHERE um_user_id = @strUserid)
	   AND @strUserType <> 'Client') OR (GroupCode = '$CLIENT' AND @strUserType = 'Client'))
	   and MenuCode = @strPMenuCode
	   AND ButtonText <> 'Visible'
       FOR JSON PATH)
	   UPDATE X SET X.Jsonvalue = REPLACE(X.Jsonvalue,'"##buttonConfig##"',CASE WHEN ISNULL(@accessjson,'') = '' THEN '[]' 
	   ELSE ISNULL(@accessjson,'') END)
       FROM @TBL_json X where PMenuCode = @strPMenuCode
	 END  
     FETCH NEXT FROM CurButtonUpd INTO   @strPMenuCode
   END
   CLOSE CurButtonUpd
   DEALLOCATE CurButtonUpd
   
   UPDATE X SET X.Jsonvalue = REPLACE(X.Jsonvalue,'"##buttonConfig##"','[]')
   FROM @TBL_json X
   
--   SELECT * FROM @TBL_json

   DECLARE @StrCompanyCount INT = 0, @strCompanyCode1 VARCHAR(1)
	
   SELECT @strCompanyCode1 = em_cd FROM Entity_master(NOLOCK) WHERE em_cd IN(SELECT MIN(em_cd) 
   FROM Entity_master(NOLOCK))
		   
   SELECT @StrCompanyCount = ISNULL(SUM(ISNULL(cnt,0)),0) 
    FROM ( SELECT COUNT(0) Cnt From Entity_master(NOLOCK) 
    WHERE em_bse <> 'N' and isNull(em_bclearingno,'') in ('189') 
    UNION ALL 
    SELECT count(0) Cnt From Entity_master(NOLOCK) 
    WHERE em_nse <> 'N' and isNull(em_nclearingno,'') in ('07277')) a
	
	IF @StrCompanyCount > 0
	BEGIN
	   SET @strCompanyCode1 = 'B'
	END
   
   DECLARE @MenuExistsKey VARCHAR(1)='N'
   
   IF EXISTS(SELECT 1 FROM @TBL_json WHERE MenuNameP = 'IPO')
   BEGIN
     SET @MenuExistsKey =  DBO.fn_CheckKeyVal(@strCompanyCode1,'IPO')
	 IF ISNULL(@MenuExistsKey,'') = 'N'
	 BEGIN
	   DELETE FROM @TBL_json WHERE MenuNameP = 'IPO'
	 END
   END
   
   IF NOT EXISTS(SELECT 1 From settlement_type(NOLOCK) Where sy_maptype in ('S','W','V'))
   BEGIN
     DELETE FROM @TBL_json WHERE MenuNameP in('SLBMTRADELISTING','SLBMOPENPOSITION','SLBMPROFITLOSS')
   END

   IF EXISTS(SELECT 1 FROM @TBL_json WHERE MenuNameP = 'REKYC')
   BEGIN
     SET @MenuExistsKey =  DBO.fn_CheckKeyVal(@strCompanyCode1,'RKC')
	 IF ISNULL(@MenuExistsKey,'') = 'N'
	 BEGIN
 
	   DELETE FROM @TBL_json WHERE MenuNameP in('REKYC','ClientClosure')
	 END
   END
   
   IF EXISTS(SELECT 1 FROM @TBL_json WHERE MenuNameP = 'RekycOffLine')
   BEGIN
     SET @MenuExistsKey =  DBO.fn_CheckKeyVal(@strCompanyCode1,'CKC')
	 IF ISNULL(@MenuExistsKey,'') = 'N'
	 BEGIN
 	   DELETE FROM @TBL_json WHERE MenuNameP in('RekycOffLine')
	 END
   END

   IF NOT EXISTS(SELECT 1 FROM @TBL_json WHERE MenuNameP IN('RekycOffLine','REKYC')) 
   BEGIN
      DELETE FROM @TBL_json WHERE MenuNameP in( 'REKYCVALIDATE','CLIENTEXPORT')
   END
   
   
   IF EXISTS(SELECT 1 FROM @TBL_json WHERE MenuNameP = 'CGain')
   BEGIN
     SET @MenuExistsKey =  DBO.fn_CheckKeyVal(@strCompanyCode1,'INP')
	 IF ISNULL(@MenuExistsKey,'') = 'N'
	 BEGIN
	   DELETE FROM @TBL_json WHERE MenuNameP in('CGain','CGainHolding','CGainDividend','CGainListing','TradeListing')
	 END
   END
      
  IF NOT EXISTS(SELECT 1 FROM tbl_VendorAPISetting(NOLOCK) WHERE APIName='BankReceipts')	  
  BEGIN
     DELETE FROM @TBL_json WHERE MenuNameP in('BankReceipts')
  END
  
  IF NOT EXISTS(SELECT 1 FROM tbl_VendorAPISetting(NOLOCK))	  
  BEGIN
     DELETE FROM @TBL_json WHERE MenuNameP in('APISETTING')
  END
	  
  IF @strUserType = 'Client'
  BEGIN
    UPDATE X SET X.Jsonvalue = REPLACE(REPLACE(REPLACE(X.Jsonvalue,'"##filters##"',CASE WHEN ISNULL(XX.filters,'') = '' 
    THEN '[]' ELSE '['+ISNULL(XX.filters,'')+']'  END),
    '##UserId##',@strUserid),'##UserType##',@strUserType)
    FROM @TBL_json X, @tbl_TradeWebMenu xx
    WHERE x.SerialNo = xx.SrNo
    AND ISNULL(XX.filters,'') <> ''
  END
  ELSE IF @strUserType <> 'Client'
  BEGIN
  
    UPDATE X SET X.Jsonvalue = REPLACE(REPLACE(REPLACE(X.Jsonvalue,'"##filters##"',CASE WHEN ISNULL(XX.BranchFilters,'') = '' THEN '[]' ELSE '['+ISNULL(XX.BranchFilters,'')+']'  END),
    '##UserId##',@strUserid),'##UserType##',@strUserType)
    FROM @TBL_json X, @tbl_TradeWebMenu xx
    WHERE x.SerialNo = xx.SrNo
    AND ISNULL(XX.BranchFilters,'') <> ''
	
	UPDATE X SET X.Jsonvalue = REPLACE(REPLACE(REPLACE(X.Jsonvalue,'"##filters##"',CASE WHEN ISNULL(XX.filters,'') = '' 
    THEN '[]' ELSE '['+ISNULL(XX.filters,'')+']'  END),
    '##UserId##',@strUserid),'##UserType##',@strUserType)
    FROM @TBL_json X, @tbl_TradeWebMenu xx
    WHERE x.SerialNo = xx.SrNo
    AND ISNULL(XX.filters,'') <> ''
    
  END	
  
  
  UPDATE X SET X.Jsonvalue = REPLACE(X.Jsonvalue,'##filters##','[]')
  FROM @TBL_json X
  where charindex('##filters##',Jsonvalue) > 0

  
  DECLARE @InputDate DATE = ISNULL((SELECT CAST(MAX(TD_DT) AS DATE) FROM trx(NOLOCK)),GETDATE()), 
  @FinancialYearStart DATE=''
  SET @FinancialYearStart = CASE WHEN MONTH(@InputDate) >= 4 THEN DATEFROMPARTS(YEAR(@InputDate), 4, 1) 
                            ELSE DATEFROMPARTS(YEAR(@InputDate) - 1, 4, 1) END;
  
  
  UPDATE X SET X.Jsonvalue = REPLACE(X.Jsonvalue,'##FromDate##',CONVERT(VARCHAR,@FinancialYearStart,112))
  FROM @TBL_json X
  
  UPDATE X SET X.Jsonvalue = REPLACE(X.Jsonvalue,'##7FromDate##',CONVERT(VARCHAR,DATEADD(DAY,-7,@InputDate),112))
  FROM @TBL_json X
  
  UPDATE X SET X.Jsonvalue = REPLACE(X.Jsonvalue,'##7ToDate##',CONVERT(VARCHAR,DATEADD(DAY,12,@InputDate),112))
  FROM @TBL_json X
  
  
  DECLARE @StrLastDate DATE;
  SELECT @StrLastDate = CASE WHEN MONTH(GETDATE()) >= 4 THEN DATEFROMPARTS(YEAR(GETDATE()) + 1, 3, 31) 
  ELSE DATEFROMPARTS(YEAR(GETDATE()), 3, 31) END
  
  UPDATE X SET X.Jsonvalue = REPLACE(X.Jsonvalue,'##LFinToDate##',CONVERT(VARCHAR,@StrLastDate,112))
  FROM @TBL_json X
      
  UPDATE X SET X.Jsonvalue = REPLACE(X.Jsonvalue,'##TodayDate##',CONVERT(VARCHAR,GETDATE(),112))
  FROM @TBL_json X	  
  
    
  UPDATE X SET X.Jsonvalue = REPLACE(X.Jsonvalue,'##2TodayDate##',CONVERT(VARCHAR,DATEADD(DAY,2,GETDATE()),112))
  FROM @TBL_json X	 
  
  
  UPDATE X SET X.Jsonvalue = REPLACE(X.Jsonvalue,'##ToDate##',CONVERT(VARCHAR,@InputDate,112))
  FROM @TBL_json X
    
  UPDATE X SET X.Jsonvalue = REPLACE(X.Jsonvalue,'##AsOnDate##',CONVERT(VARCHAR,@InputDate,112))
  FROM @TBL_json X
  
  UPDATE X SET X.Jsonvalue = REPLACE(X.Jsonvalue,'##NoFutureData##',CONVERT(VARCHAR,GETDATE(),112))
  FROM @TBL_json X
  	
  DECLARE @LedgerFromMinDate VARCHAR(8)=''	
  SELECT @LedgerFromMinDate = tnc_afterdt FROM tradenetcontrol(NOLOCK) 
  WHERE TNC_optcode='101'	
  
  UPDATE X SET X.Jsonvalue = REPLACE(X.Jsonvalue,'##LedgerFromMinDate##',@LedgerFromMinDate)
  FROM @TBL_json X
	
  UPDATE X SET X.Jsonvalue = REPLACE(X.Jsonvalue,'"##summary##"',CASE WHEN ISNULL(XX.downloadFilters,'') = '' THEN '{}' ELSE +ISNULL(XX.downloadFilters,'')  END)
  FROM @TBL_json X, @tbl_TradeWebMenu xx
  WHERE x.SerialNo = xx.SrNo
  AND ISNULL(XX.IconPath,'') NOT IN ('E','M')
  
  UPDATE X SET X.Jsonvalue = REPLACE(X.Jsonvalue,'"##summary2##"','{"columnsToShowTotal":[{"key": "Net Value","label": "Net Value"}]}')
  FROM @TBL_json X, @tbl_TradeWebMenu xx
  WHERE x.SerialNo = xx.SrNo
  AND xx.menuname IN('Ledger','Bill Summary')
  
  UPDATE X SET X.Jsonvalue = REPLACE(X.Jsonvalue,'"##J_Ui##"','{"ActionName":"TradeWeb","Option":"'+xx.menutag+'","Level":1, "RequestFrom":"'+@strRequestFrom+'"}')
  FROM @TBL_json X, @tbl_TradeWebMenu xx
  WHERE x.SerialNo = xx.SrNo
  
  UPDATE X SET X.Jsonvalue = REPLACE(X.Jsonvalue,'"##J_Ui2##"','{"ActionName":"TradeWeb","Option":"'+xx.menutag+'","Level":2, "RequestFrom":"'+@strRequestFrom+'"}')
  FROM @TBL_json X, @tbl_TradeWebMenu xx
  WHERE x.SerialNo = xx.SrNo

  UPDATE X SET X.Jsonvalue = REPLACE(X.Jsonvalue,'"##settings##"',CASE WHEN ISNULL(XX.LevelSetting,'') = '' THEN '{}' ELSE ISNULL(XX.LevelSetting,'')  END)
  FROM @TBL_json X, @tbl_TradeWebMenu xx
  WHERE x.SerialNo = xx.SrNo

  UPDATE X SET X.Jsonvalue = REPLACE(X.Jsonvalue,'"##settings2##"',CASE WHEN ISNULL(XX.Level2Setting,'') = '' THEN '{}' ELSE ISNULL(XX.Level2Setting,'')  END)
  FROM @TBL_json X, @tbl_TradeWebMenu xx
  WHERE x.SerialNo = xx.SrNo


  DECLARE @tbl_Data TABLE([Value] VARCHAR(MAX), [DisplayName] VARCHAR(100))
  declare @iSerialNo INT, @strdbquery VARCHAR(MAX) ='', @strcolumnname VARCHAR(100)='',
  @ojson VARCHAR(MAX)='', @JsonMain VARCHAR(MAX)='', @o_strJson  VARCHAR(MAX)='',
  @strLedgerJson VARCHAR(MAX)='', @strString NVARCHAR(MAX)='', @strtradeplustempdb VARCHAR(MAX)=ISNULL((SELECT strtradeplustempdb = sp_sysvalue
	FROM WebParameter(NOLOCK)
	WHERE sp_parmcd = 'TRADEPLUSTEMPDB'),'')
	
  DECLARE @strOP_DataBase VARCHAR(50), @strOP_Owner VARCHAR(50) 	
  
  DECLARE CurfilterUpd
  CURSOR FOR SELECT  x.SerialNo, dbquery, columnname
  FROM @TBL_json X, @tbl_TradeWebMenu  xx, tbl_InsertUpdateXMLDropDownQuery(NOLOCK) xq
  WHERE x.SerialNo = xx.SrNo
  and xx.MenuTag = xq.ModuleName AND USERCODE <> 'X'
  and charindex('##'+columnname+'##',CASE WHEN @strUserType <> 'CLIENT' AND ISNULL(XX.BranchFilters,'') <> '' 
  THEN XX.BranchFilters ELSE  xx.filters END)>0 AND DBQueryType ='Q'
  AND dbquery <> ''
  order by xq.SerialNo
  
  OPEN CurfilterUpd 
  FETCH NEXT FROM CurfilterUpd INTO @iSerialNo, @strdbquery, @strcolumnname
  WHILE @@FETCH_STATUS = 0
  BEGIN 
    SET @strLedgerJson = ''
	DELETE FROM @tbl_Data
	IF CHARINDEX('##DPDATABASE##',@strdbquery) >0  
	BEGIN
	  SELECT @strOP_DataBase = RTRIM(LTRIM(OP_DataBase)), 
	  @strOP_Owner = RTRIM(LTRIM(OP_Owner)) 
      FROM Other_Products(NOLOCK) 
      WHERE OP_Product = 'Cross' and OP_Status='A'
   
      IF ISNULL(@strOP_DataBase,'') = ''
      BEGIN
	    SELECT @strOP_DataBase = RTRIM(LTRIM(OP_DataBase)), 
	    @strOP_Owner = RTRIM(LTRIM(OP_Owner)) 
        FROM Other_Products(NOLOCK) 
        WHERE OP_Product = 'Estro' and OP_Status='A'
      END	
	  SET @strdbquery = REPLACE(@strdbquery,'##DPDATABASE##',  @strOP_DataBase)
      SET @strdbquery = REPLACE(@strdbquery,'##DPOWNER##',  @strOP_Owner)	  
	END  
	
	BEGIN TRY
	  INSERT INTO @tbl_Data([Value], [DisplayName])
      EXEC(@strdbquery)
	END TRY
    BEGIN CATCH
	   INSERT INTO @tbl_Data([Value], [DisplayName])
	   VALUES('','')
    END CATCH	
	
    SET @ojson = ''
    IF EXISTS(SELECT 1 FROM @tbl_Data)
    BEGIN
      SET @ojson = (SELECT [label] = [DisplayName], [Value]  FROM @tbl_Data FOR JSON PATH) 
    END
    ELSE
    BEGIN
      SET @ojson = (SELECT [label] = '', [Value] ='' FOR JSON PATH) 
    END
    UPDATE A SET A.Jsonvalue = REPLACE(A.Jsonvalue, '"##'+@strcolumnname+'##"',@ojson)
    FROM @TBL_json A
    WHERE A.SerialNo = @iSerialNo
	
	--SELECT @ojson, @strcolumnname, @strdbquery
    FETCH NEXT FROM CurfilterUpd INTO   @iSerialNo, @strdbquery, @strcolumnname
  END
  CLOSE CurfilterUpd
  DEALLOCATE CurfilterUpd
  
 
  
  DECLARE CurEditUpd
  CURSOR FOR SELECT  x.SerialNo, dbquery, columnname
  FROM @TBL_json X, @tbl_TradeWebMenu  xx, tbl_InsertUpdateXMLDropDownQuery(NOLOCK) xq
  WHERE x.SerialNo = xx.SrNo
  and xx.MenuTag = xq.ModuleName AND USERCODE <> 'X'
  and charindex('~~'+columnname+'~~',xx.LevelSetting)>0 AND DBQueryType ='Q'
  and charindex('EditableColumn',xx.LevelSetting) > 0 AND dbquery <> ''
  order by xq.SerialNo
  
  OPEN CurEditUpd 
  FETCH NEXT FROM CurEditUpd INTO @iSerialNo, @strdbquery, @strcolumnname
  WHILE @@FETCH_STATUS = 0
  BEGIN 
    SET @strLedgerJson = ''
	
	IF CHARINDEX('##DPDATABASE##',@strdbquery) >0
	BEGIN
	  SELECT @strOP_DataBase = RTRIM(LTRIM(OP_DataBase)), 
	  @strOP_Owner = RTRIM(LTRIM(OP_Owner)) 
      FROM Other_Products(NOLOCK) 
      WHERE OP_Product = 'Cross' and OP_Status='A'
   
      IF ISNULL(@strOP_DataBase,'') = ''
      BEGIN
	    SELECT @strOP_DataBase = RTRIM(LTRIM(OP_DataBase)), 
	    @strOP_Owner = RTRIM(LTRIM(OP_Owner)) 
        FROM Other_Products(NOLOCK) 
        WHERE OP_Product = 'Estro' and OP_Status='A'
      END	
	  SET @strdbquery = REPLACE(@strdbquery,'##DPDATABASE##', @strOP_DataBase)
      SET @strdbquery = REPLACE(@strdbquery,'##DPOWNER##', @strOP_Owner)	  
	END  
	
    DELETE FROM @tbl_Data
    BEGIN TRY
	  INSERT INTO @tbl_Data([Value], [DisplayName])
      EXEC(@strdbquery)
	END TRY
    BEGIN CATCH
	   INSERT INTO @tbl_Data([Value], [DisplayName])
	   VALUES('','')
    END CATCH	
	
    SET @ojson = ''
    IF EXISTS(SELECT 1 FROM @tbl_Data)
    BEGIN
      SET @ojson = (SELECT [label] = [DisplayName], [Value]  FROM @tbl_Data FOR JSON PATH) 
    END
    ELSE
    BEGIN
      SET @ojson = (SELECT [label] = '', [Value] ='' FOR JSON PATH) 
    END
    UPDATE A SET A.Jsonvalue = REPLACE(A.Jsonvalue, '"~~'+@strcolumnname+'~~"',@ojson)
    FROM @TBL_json A
    WHERE A.SerialNo = @iSerialNo
	
	--SELECT @ojson, @strcolumnname, @strdbquery
    FETCH NEXT FROM CurEditUpd INTO   @iSerialNo, @strdbquery, @strcolumnname
  END
  CLOSE CurEditUpd
  DEALLOCATE CurEditUpd
  
  DECLARE @strClientJson VARCHAR(MAX)='', @o_strJson2 VARCHAR(MAX)=''
  
 
  UPDATE X SET X.Jsonvalue = REPLACE(X.Jsonvalue,'"##Entry##"',CASE WHEN ISNULL(XX.downloadFilters,'') = '' THEN '{}' ELSE REPLACE(ISNULL(XX.downloadFilters,''), 
 '##ClientCode##',@strUserid) END)
  FROM @TBL_json X, @tbl_TradeWebMenu xx
  WHERE x.SerialNo = xx.SrNo
  AND ISNULL(XX.IconPath,'') in ('E','M')
  
  UPDATE X SET X.Jsonvalue = REPLACE(X.Jsonvalue,'"##Entry##"','{}')
  FROM @TBL_json X, @tbl_TradeWebMenu xx
  WHERE x.SerialNo = xx.SrNo
  AND ISNULL(XX.IconPath,'') NOT IN ('E','M')


  IF EXISTS(SELECT 1 FROM @TBL_json WHERE CHARINDEX('##Selectioncatogery##',Jsonvalue) > 0)
  BEGIN
    
	SET @strClientJson = (select [label] =  [DisplayName], [Value] from(select 'C' as [Value], 'Client' as [DisplayName] 
	union all select 'G' as [Value], 'Group' as [DisplayName] 
	union all select 'F' as [Value], 'Family' as [DisplayName] union all select 'B' as [Value], 'Branch' as [DisplayName] ) x1 
	FOR JSON PATH) 
	
    UPDATE A SET A.Jsonvalue = REPLACE(A.Jsonvalue, '"##Selectioncatogery##"',@strClientJson)
	FROM @TBL_json A
  END
 
  UPDATE X SET X.Jsonvalue = REPLACE(X.Jsonvalue,'##UserId##',@strUserid)
  FROM @TBL_json X
    
  DECLARE @tbl_fn_json_merge table(JsonValue varchar(max))

  DECLARE @strJsonvalue varchar(max)='', @strMenuname VARCHAR(MAX)='', @icount INT = 1,
  @o_strJson1 VARCHAR(MAX)='', @strSubMenuName VARCHAR(MAX)='', @icount1 INT = 1
  
  IF (@strRequestFrom = 'M' OR (@strRequestFrom = 'W' AND @strUserType = 'CLIENT'))
  BEGIN
    DECLARE CurfilterUpd0
    CURSOR FOR SELECT Menuname from @tbl_TradeWebMenu XX
    WHERE MenuType = 'P' AND ISNULL(Enable,'N') = 'Y' 
	AND ((ISNULL(@strRequestFrom,'') = 'W' AND ISNULL(Productid,'') IN('','T','B'))
	  OR (ISNULL(@strRequestFrom,'') = 'M' AND ISNULL(Productid,'') IN('','M')))
    AND ((@strUserType = 'Client' AND ISNULL(ICONPATH,'') = '') OR @strUserType <> 'Client')
	ORDER BY MenuCode
	
    OPEN CurfilterUpd0 
    FETCH NEXT FROM CurfilterUpd0 INTO @strMenuname
    WHILE @@FETCH_STATUS = 0
    BEGIN 
      SET @icount = @icount+1
      SET @o_strJson = '{"id": ##ID##,"title": "##title##",
        "componentName": "##title##",
        "icon": "##icon##","iconType":"##iconType##","submenu":[ '
      SET @o_strJson = REPLACE(@o_strJson,'##ID##',CAST(@icount AS VARCHAR))
	  SET @o_strJson = REPLACE(@o_strJson,'##title##',@strMenuname)
	
	  IF @strMenuname = 'Capital Gain'
	  BEGIN
	    SET @o_strJson = REPLACE(@o_strJson,'##iconType##','entypo')
	    SET @o_strJson = REPLACE(@o_strJson,'##icon##','area-graph')
	  END
	  ELSE IF @strMenuname = 'Reports'
	  BEGIN
	    SET @o_strJson = REPLACE(@o_strJson,'##iconType##','octicons')
	    SET @o_strJson = REPLACE(@o_strJson,'##icon##','report')
	  END
	  
      DECLARE CurfilterUpd1
      CURSOR FOR SELECT Jsonvalue FROM @TBL_json,  @tbl_TradeWebMenu  XX
      WHERE  SerialNo = SrNo
	  AND ISNULL(Enable,'N') = 'Y' 
	  AND ((ISNULL(@strRequestFrom,'') = 'W' AND ISNULL(Productid,'') IN('','T','B'))
	  OR (ISNULL(@strRequestFrom,'') = 'M' AND ISNULL(Productid,'') IN('','M')))
	  AND ISNULL(MENUType,'') = 'C' 
      AND XX.TargetForm = @strMenuname
      ORDER BY SERIALNO
  
      OPEN CurfilterUpd1 
      FETCH NEXT FROM CurfilterUpd1 INTO @strJsonvalue
      WHILE @@FETCH_STATUS = 0
      BEGIN 
        IF ISNULL(@o_strJson,'') <> ''
	    BEGIN
	      --select @o_strJson, @strJsonvalue
	      DELETE FROM @tbl_fn_json_merge
		  
		  --SET @strString = 'EXEC '+@strtradeplustempdb+'.DBO.' + 'SP_json_merge' + ' ''' + @o_strJson + ''', '''+@strJsonvalue+''', @o_strJson OUTPUT';
		  --SELECT @strString
          --EXEC sp_executesql @strString, N'@o_strJson VARCHAR(MAX) OUTPUT', @o_strJson OUTPUT;
	      SET @strString = 'SELECT '+@strtradeplustempdb+'.DBO.fn_json_merge1('''+@o_strJson+''','''+@strJsonvalue+''') '
		  INSERT INTO @tbl_fn_json_merge(JsonValue)
          EXEC(@strString)
		  select @o_strJson = JsonValue from @tbl_fn_json_merge
	      SET @o_strJson = substring(@o_strJson,2,LEN(@o_strJson))
	      SET @o_strJson = substring(@o_strJson,1,LEN(@o_strJson)-1)
	      SET @o_strJson = replace(@o_strJson,'[ ,{','[{')
	    END
        ELSE
        BEGIN
	      SET @o_strJson = @strJsonvalue
	    END
	    --SELECT @o_strJson, @strJsonvalue
        FETCH NEXT FROM CurfilterUpd1 INTO   @strJsonvalue
      END
      CLOSE CurfilterUpd1
      DEALLOCATE CurfilterUpd1
	  
	  
      IF ISNULL(@o_strJson2,'') = ''
      BEGIN
        SET @o_strJson2 = @o_strJson+']}'  
      END
      ELSE
      BEGIN  
        SET @o_strJson2 = @o_strJson2+','+@o_strJson+']}'
      END	
      FETCH NEXT FROM CurfilterUpd0 INTO   @strMenuname
    END
    CLOSE CurfilterUpd0
    DEALLOCATE CurfilterUpd0
  END
  ELSE
  BEGIN
    DECLARE CurfilterUpd2
    CURSOR FOR SELECT Menuname from @tbl_TradeWebMenu 
    WHERE MenuType = 'P' AND ISNULL(Enable,'N') = 'Y' AND isnull(Productid,'') IN('','N','B')
	Order by MenuCode
	
    OPEN CurfilterUpd2 
    FETCH NEXT FROM CurfilterUpd2 INTO @strMenuname
    WHILE @@FETCH_STATUS = 0
    BEGIN 
	  SET @o_strJson1 = ''
      SET @icount = @icount+1
      SET @o_strJson = '{"id": ##ID##,"title": "##title##",
        "componentName": "##title##",
        "icon": "##icon##","iconType":"##iconType##" '
      SET @o_strJson = REPLACE(@o_strJson,'##ID##',CAST(@icount AS VARCHAR))
	  SET @o_strJson = REPLACE(@o_strJson,'##title##',@strMenuname)
	
	  IF @strMenuname = 'Capital Gain'
	  BEGIN
	    SET @o_strJson = REPLACE(@o_strJson,'##iconType##','entypo')
	    SET @o_strJson = REPLACE(@o_strJson,'##icon##','area-graph')
	  END
	  ELSE IF @strMenuname = 'Reports'
	  BEGIN
	    SET @o_strJson = REPLACE(@o_strJson,'##iconType##','octicons')
	    SET @o_strJson = REPLACE(@o_strJson,'##icon##','report')
	  END
      SET @icount1 = 1
      
	  IF EXISTS(SELECT Menuname from @tbl_TradeWebMenu 
      WHERE  ParentMenu = @strMenuname AND ISNULL(MENUType,'') = 'S'
	  AND ISNULL(Enable,'N') = 'Y' AND isnull(Productid,'') IN('','N','B')
	  AND ((Menuname = 're-kyc' AND EXISTS(SELECT 1 from @TBL_json
	  WHERE MenuNameP IN('RekycOffLine','REKYC'))) or  Menuname <> 're-kyc'))
	  BEGIN
        DECLARE CurfilterUpd3
        CURSOR FOR SELECT Menuname from @tbl_TradeWebMenu  XX
        WHERE  ParentMenu = @strMenuname AND ISNULL(MENUType,'') = 'S'
	    AND ISNULL(Enable,'N') = 'Y' AND isnull(Productid,'') IN('','N','B')
		AND ((Menuname = 're-kyc' AND EXISTS(SELECT 1 from @TBL_json
	    WHERE MenuNameP IN('RekycOffLine','REKYC'))) or  Menuname <> 're-kyc')
		Order by CAST(MenuCode AS INT)
	  --AND Menuname='Accounts'
      
	    OPEN CurfilterUpd3 
        FETCH NEXT FROM CurfilterUpd3 INTO @strSubMenuName
        WHILE @@FETCH_STATUS = 0
        BEGIN 
          
		  IF @icount1 = 1
          BEGIN
            SET @o_strJson = @o_strJson+',"submenu":[{"id": ##ID##,"title": "##title##",
            "componentName": "##title##",
            "icon": "##icon##","iconType":"##iconType##","submenu":[ '
          END
          ELSE
          BEGIN  
            SET @o_strJson = @o_strJson+']},{"id": ##ID##,"title": "##title##",
            "componentName": "##title##",
            "icon": "##icon##","iconType":"##iconType##","submenu":[ '
          END
		  
		  SET @icount1 = @icount1+1
		  
          SET @o_strJson = REPLACE(@o_strJson,'##ID##',CAST(@icount1 AS VARCHAR))
	      SET @o_strJson = REPLACE(@o_strJson,'##title##',@strSubMenuName)
		
          DECLARE CurfilterUpd4
          CURSOR FOR SELECT Jsonvalue FROM @TBL_json,  @tbl_TradeWebMenu 
          WHERE  ParentName = @strSubMenuName AND SerialNo = SrNo
		  AND ISNULL(Enable,'N') = 'Y' AND isnull(Productid,'') IN('','N','B')
		  AND ISNULL(MENUType,'') = 'C'
          ORDER BY CAST(menucode AS INT)
  
          OPEN CurfilterUpd4 
          FETCH NEXT FROM CurfilterUpd4 INTO @strJsonvalue
          WHILE @@FETCH_STATUS = 0
          BEGIN 
            IF ISNULL(@o_strJson,'') <> ''
	        BEGIN
	          delete from @tbl_fn_json_merge
	          SET @strString = 'SELECT '+@strtradeplustempdb+'.DBO.fn_json_merge1('''+@o_strJson+''','''+@strJsonvalue+''') '
              INSERT INTO @tbl_fn_json_merge(JsonValue)
              EXEC(@strString)
	          select @o_strJson = JsonValue from @tbl_fn_json_merge
	          SET @o_strJson = substring(@o_strJson,2,LEN(@o_strJson))
	          SET @o_strJson = substring(@o_strJson,1,LEN(@o_strJson)-1)
	          set @o_strJson = replace(@o_strJson,'[ ,{','[{')
	        END
            ELSE
            BEGIN
	          SET @o_strJson = @strJsonvalue
	        END
	      
            FETCH NEXT FROM CurfilterUpd4 INTO   @strJsonvalue
          END
          CLOSE CurfilterUpd4
          DEALLOCATE CurfilterUpd4
	      FETCH NEXT FROM CurfilterUpd3 INTO   @strSubMenuName
        END
        CLOSE CurfilterUpd3
        DEALLOCATE CurfilterUpd3
		IF ISNULL(@o_strJson1,'') = ''
        BEGIN
          SET @o_strJson1 = @o_strJson  
        END
        ELSE
        BEGIN  
          SET @o_strJson1 = @o_strJson1+','+@o_strJson
        END	
		IF @icount1 > 2
        BEGIN		
		  SET @o_strJson1 = @o_strJson1+']}]}'
		END
        ELSE
        BEGIN
		  SET @o_strJson1 = @o_strJson1+']}]}'
        END 		
	  END	
	  ELSE
      BEGIN
	    SET @o_strJson = @o_strJson+',"submenu":['
	    DECLARE CurfilterUpd5
        CURSOR FOR SELECT Jsonvalue FROM @TBL_json,  @tbl_TradeWebMenu 
        WHERE  ParentName = @strMenuname AND SerialNo = SrNo
		AND ISNULL(Enable,'N') = 'Y' AND isnull(Productid,'') IN('','N','B')
		AND ISNULL(MENUType,'') = 'C'
        ORDER BY CAST(MenuCode AS INT)
  
        OPEN CurfilterUpd5 
        FETCH NEXT FROM CurfilterUpd5 INTO @strJsonvalue
        WHILE @@FETCH_STATUS = 0
        BEGIN 
          IF ISNULL(@o_strJson,'') <> ''
	      BEGIN
	        delete from @tbl_fn_json_merge
	        SET @strString = 'SELECT '+@strtradeplustempdb+'.DBO.fn_json_merge1('''+@o_strJson+''','''+@strJsonvalue+''') '
            INSERT INTO @tbl_fn_json_merge(JsonValue)
            EXEC(@strString)
	        select @o_strJson = JsonValue from @tbl_fn_json_merge
	        SET @o_strJson = substring(@o_strJson,2,LEN(@o_strJson))
	        SET @o_strJson = substring(@o_strJson,1,LEN(@o_strJson)-1)
	        set @o_strJson = replace(@o_strJson,'[ ,{','[{')
	      END
          ELSE
          BEGIN
	        SET @o_strJson = @strJsonvalue
	      END
	      
          FETCH NEXT FROM CurfilterUpd5 INTO   @strJsonvalue
        END
        CLOSE CurfilterUpd5
        DEALLOCATE CurfilterUpd5
		
		IF ISNULL(@o_strJson1,'') = ''
        BEGIN
          SET @o_strJson1 = @o_strJson  
        END
        ELSE
        BEGIN  
          SET @o_strJson1 = @o_strJson1+','+@o_strJson
        END	
		SET @o_strJson1 = @o_strJson1+']}'
	  END 	

      IF ISNULL(@o_strJson2,'') = ''
      BEGIN
        SET @o_strJson2 = @o_strJson1  
      END
      ELSE
      BEGIN  
        SET @o_strJson2 = @o_strJson2+','+@o_strJson1
      END	
      FETCH NEXT FROM CurfilterUpd2 INTO   @strMenuname
    END
    CLOSE CurfilterUpd2
    DEALLOCATE CurfilterUpd2
  END  
  SET @o_strJson2 = REPLACE(@o_strJson2,'[,','[')
  
  
  SET @MenuExistsKey =  DBO.fn_CheckKeyVal(@strCompanyCode1,'OPC')
	  
  IF ISNULL(@MenuExistsKey,'') = 'N'
  BEGIN
	SET @MenuExistsKey =  DBO.fn_CheckKeyVal(@strCompanyCode1,'OPN')
  END
  
  
  DECLARE @strAdditionalMenu VARCHAR(MAX)=''
  
  SET @strAdditionalMenu = (SELECT [id] =  12+ROW_NUMBER() OVER (ORDER BY (SELECT 1)),  [title] = AM_Caption, [componentName] = AM_Caption,
  [icon]='',[iconType]='' , submenu =(SELECT AM_SRNO AS [SrNo], AM_SRNO AS [id],[title] = AM_Caption, [componentName] = REPLACE(AM_Caption,' ',''),
  [componentType] = 'URL',[icon]='',[iconType]='', [url] = ISNULL(AM_Link,'')
  FROM Additional_Menus(NOLOCK) 
  WHERE AM_Type = 'I' AND AM_SrNo >= X1.AM_SrNo AND AM_SrNo <= X1.AM_SrNo+90  FOR JSON PATH)
  FROM Additional_Menus(NOLOCK) X1
  WHERE AM_Type = 'M'   FOR JSON PATH)
  
  IF ISNULL(@strAdditionalMenu,'') <> ''
  BEGIN
    SET @strAdditionalMenu = SUBSTRING(@strAdditionalMenu,2,LEN(@strAdditionalMenu))
	SET @strAdditionalMenu = SUBSTRING(@strAdditionalMenu,1,LEN(@strAdditionalMenu)-1)
  END
    
  
  --SELECT @o_strJson1
  IF @strRequestFrom = 'M'
  BEGIN
    SELECT '[{
        "id": 1,
        "title": "Dashboard",
        "componentName": "Dashboard",
        "icon": "home"},'+@o_strJson2+',{
        "id": 20,
        "title": "Change Password",
        "componentName": "ChangePassword",
        "icon": "password",
		"iconType": "materialIcons"
    },
	{
        "id": 21,
        "title": "Fund Request",
        "componentName": "FundRequest",
        "icon": "material-symbols-outlined",
		"iconType": "materialIcons"
    },
    {"id": 22,"title":"Downloads","componentName":"Downloads","icon":"download"},
	{"id": 23,"title":"Theme","componentName":"Theme","icon":"theme-light-dark"},
	{"id": 24,"title": "Exit","componentName": "ExitApp","icon": "Exit"}]'
  END
  ELSE IF ISNULL(@MenuExistsKey,'N') ='Y'
  BEGIN
    SELECT '[{
        "id": 1,
        "title": "Dashboard",
        "componentName": "Dashboard",
        "icon": "home"},'+@o_strJson2+','+CASE WHEN ISNULL(@strAdditionalMenu,'') <>  '' THEN @strAdditionalMenu+','
		ELSE '' END +'{
        "id": 20,
        "title": "Change Password",
        "componentName": "ChangePassword",
        "icon": "password",
		"iconType": "materialIcons"
    },'+CASE WHEN @strUserType = 'Client' THEN '
    {
        "id": 21,
        "title": "Margin Pledge(Online)",
        "componentName": "marginPledge",
        "icon": "material-symbols-outlined",
		"iconType": "materialIcons"
    },' ELSE '' END +'
    {"id": 22,"title":"Downloads","componentName":"Downloads","icon":"download","pageData":{"autoFetch":"false"}},
	{"id": 23,"title":"Theme","componentName":"Theme","icon":"theme-light-dark"},
	{"id": 24,"title": "Logout","componentName": "Logout","icon": "logout"}]'
  END  
  ELSE IF ISNULL(@MenuExistsKey,'N') ='N'
  BEGIN
    SELECT '[{
        "id": 1,
        "title": "Dashboard",
        "componentName": "Dashboard",
        "icon": "home"},'+@o_strJson2+','+CASE WHEN ISNULL(@strAdditionalMenu,'') <>  '' THEN @strAdditionalMenu+','
		 ELSE '' END +'{
        "id": 20,
        "title": "Change Password",
        "componentName": "ChangePassword",
        "icon": "password",
		"iconType": "materialIcons"
    },
    {"id": 22,"title":"Downloads","componentName":"Downloads","icon":"download","pageData":{"autoFetch":"false"}},
	{"id": 23,"title":"Theme","componentName":"Theme","icon":"theme-light-dark"},
	{"id": 24,"title": "Logout","componentName": "Logout","icon": "logout"}]'
  END  
END
GO

CREATE PROCEDURE stpr_Rep_MarginShotFoll @vcXML NVARCHAR(MAX), @o_vcErrorFlag VARCHAR(1) OUTPUT, 
@o_vcErrorMessage VARCHAR(MAX) OUTPUT  
WITH ENCRYPTION
AS
BEGIN
  declare @str NVARCHAR(MAX)='',  
  @dtFromDate VARCHAR(8), @strUserId VARCHAR(50), @strReportName VARCHAR(50), 
  @strOutputType VARCHAR(1)='', @XMLData XML,
  @strSelectTag VARCHAR(1)='', @strSelectUsers VARCHAR(500)='', @StrString VARCHAR(MAX)='', @SQ1 INT = 0,
  @strSplFilter VARCHAR(MAX)='', @strRepType VARCHAR(50)='', @dtToDate VARCHAR(8)='', 
  @strRepSubType VARCHAR(50), @strConsider112A VARCHAR(1)='N', @strProduct VARCHAR(50)='', 
  @strHeader VARCHAR(MAX)='', @strCommmexDB VARCHAR(MAX)='', @strCompany varchar(1), @dtMarginDate VARCHAR(20)='',
  @strRequestFrom VARCHAR(1)='M'
  IF @vcXML = ''
  BEGIN
    SET @o_vcErrorFlag  = 'E'
    SET @o_vcErrorMessage = 'Please Send Input Parameter(s)'
    RETURN 1
  END 
  
  SET @XMLData = CAST('<root>'+@vcXML+'</root>' AS XML)
  
  SELECT @dtMarginDate = ISNULL(x.value('(FromDt)[1]', 'VARCHAR(8)'),''),
  @strProduct = ISNULL(x.value('(Product)[1]', 'VARCHAR(50)'),''),
  @dtToDate = ISNULL(x.value('(ToDt)[1]', 'VARCHAR(8)'),''),
  @strUserId = ISNULL(x.value('(UserId)[1]', 'VARCHAR(500)'),''),
  @strSelectTag = ISNULL(x.value('(SelectTag)[1]', 'VARCHAR(1)'),''),
  @strSelectUsers = ISNULL(x.value('(SelectUsers)[1]', 'VARCHAR(500)'),''),
  @strOutputType = ISNULL(x.value('(OutputType)[1]', 'VARCHAR(1)'),''),
  @strSplFilter = ISNULL(x.value('(SplFilter)[1]', 'VARCHAR(MAX)'),''),
  @strReportName = ISNULL(x.value('(ReportName)[1]', 'VARCHAR(100)'),''),
  @strRepType = ISNULL(x.value('(RepType)[1]', 'VARCHAR(100)'),''),
  @strRepSubType = ISNULL(x.value('(RepSubType)[1]', 'VARCHAR(100)'),''),
  @strCompany = ISNULL(x.value('(CompanyCode)[1]', 'VARCHAR(1)'),''),
  @strRequestFrom = ISNULL(x.value('(RequestFrom)[1]', 'VARCHAR(1)'),'') 
  FROM @XMLData.nodes('/root') AS XTbl(x) 
  
  
  IF OBJECT_ID('tempdb..#TmpPeakColl') IS NOT NULL
	DROP TABLE #TmpPeakColl

  DECLARE @ComexDB VARCHAR(50), @ComexOwner VARCHAR(50)
  SELECT @ComexDB = LTRIM(RTRIM(OP_DataBase)), @ComexOwner = LTRIM(RTRIM(OP_Owner)) 
  FROM Other_Products(nolock) where OP_Product = 'Commex' AND OP_Status ='A'
  
  SET @strHeader = 'DECLARE @tbl_UserList TABLE(Client_Code VARCHAR(50), DPClientCode VARCHAR(50) ) '
  
  SELECT @dtMarginDate = MAX(fm_dt) FROM Fmargins(nolock)
  WHERE fm_companycode = @strCompany
  
  IF @strSplFilter = ''
  BEGIN
    SET @strHeader = @strHeader+' INSERT INTO @tbl_UserList(Client_Code) '
    +' SELECT * FROM DBO.[fn_GetClients]('''+@strUserId+''','''+@strSelectTag+''','''+@strSelectUsers+''')'
  END 	 
  ELSE
  IF @strSplFilter <> ''
  BEGIN
    SET @strHeader = @strHeader+' INSERT INTO @tbl_UserList(Client_Code)  SELECT distinct CM_CD FROM Client_master(NOLOCK) WHERE 1 = 1  AND '+@strSplFilter
  END

  CREATE TABLE #TmpPeakColl (
	Tmp_Clientcd VARCHAR(8), Tmp_CompanyCode VARCHAR(3), Tmp_PeakMargin MONEY, Tmp_PeakColl MONEY, Tmp_Shortfall MONEY, Tmp_exchange CHAR(1), Tmp_segment CHAR(1), 
	Tmp_Nfiller4 MONEY, Tmp_Nfiller5 MONEY, Tmp_Nfiller6 MONEY
	)

  SET @str = @strHeader+' '+'SELECT fm_clientcd, fm_exchange + fm_Segment, isNull(fm_NFiller4, 0), 0, 0, fm_exchange, fm_Segment, '
             +' isNull(fm_NFiller4, 0), isNull(fm_NFiller5, 0), isNull( '
		     +' fm_NFiller6, 0) fm_NFiller6 '
             +' FROM Fmargins(NOLOCK), Client_master(NOLOCK), @tbl_UserList '
             +' WHERE fm_clientcd = cm_cd AND fm_Companycode = '''+@strCompany+''' AND fm_dt = '''+@dtMarginDate+''''
			 +' AND CM_CD = Client_Code '
     IF ISNULL(@ComexDB,'') <> ''
     BEGIN	 
        SET @str =@str+' UNION '

             +' SELECT fm_clientcd, fm_exchange + ''X'', isNull(fm_PeakMargin, 0) + isNull(fm_Filler2, 0), 0, 0, '
			 +' fm_exchange, ''X'' fm_Segment, isNull(fm_PeakMargin, 0) + isNull(fm_Filler2, 0), '
			 +' isNull(fm_Filler1, 0), isNull(fm_Filler3, 0) fm_NFiller6 '
    +' FROM '+@ComexDB+'.'+@ComexOwner+'.Fmargins, Client_master(NOLOCK), @tbl_UserList '
             +' WHERE fm_clientcd = cm_cd AND fm_Companycode = '''+@strCompany+''' AND fm_dt = '''+@dtMarginDate+''''
			 +' AND CM_CD = Client_Code '
      END			 
   
  INSERT INTO #TmpPeakColl
  exec(@str)

  UPDATE #TmpPeakColl
  SET Tmp_PeakMargin = Round(Tmp_PeakMargin * 100 / 100, 2)
  WHERE Right(Tmp_CompanyCode, 2) <> 'MX'

  UPDATE #TmpPeakColl
  SET Tmp_PeakColl = CASE WHEN isNull(fc_FillerN9, 0) > 0 THEN isNull(fc_FillerN9, 0) ELSE 0 END
  FROM Fmargin_clients
  WHERE fc_clientcd = Tmp_clientcd AND fc_Companycode = @strCompany AND fc_Exchange = '' AND fc_dt = @dtMarginDate


  UPDATE #TmpPeakColl
  SET Tmp_PeakMargin = 0, Tmp_PeakColl = 0
  WHERE Tmp_PeakColl >= Tmp_PeakMargin


  INSERT INTO #TmpPeakColl
  SELECT Tmp_Clientcd, '', 0, 0, CASE WHEN Sum(Tmp_PeakMargin - Tmp_PeakColl) > 0 THEN Sum(Tmp_PeakMargin - Tmp_PeakColl) ELSE 0 END, '', '', 0, 0, 0
  FROM #TmpPeakColl
  GROUP BY Tmp_Clientcd


  DELETE #TmpPeakColl
  WHERE Tmp_CompanyCode <> ''

  
  IF OBJECT_ID('tempdb..#FmarginsRpt') IS NOT NULL
	DROP TABLE #FmarginsRpt

  CREATE TABLE [#FmarginsRpt] (
	[fm_companycode] [char](1) NOT NULL, [fm_exchange] [char](1) NOT NULL, [fm_dt] [char](8) NOT NULL, [fm_clientcd] [char](8) NOT NULL, [fm_spanmargin] [money] NOT NULL
	, [fm_buypremmargin] [money] NOT NULL, [fm_initialmargin] [money] NOT NULL, [fm_exposurevalue] [money] NOT NULL, [fm_clienttype] [char](1) NOT NULL, 
	[fm_additionalmargin] [money] NOT NULL, [fm_collected] [money] NOT NULL, [fm_mainbrcd] [char](8) NOT NULL, [mkrid] [char](8) NOT NULL, [mkrdt] [char](8) NOT NULL, 
	[fm_Regmargin] [money] NULL, [fm_Tndmargin] [money] NULL, [fm_Dlvmargin] [money] NULL, [fm_SpreadBen] [money] NULL, [fm_SplMargin] [money] NULL, [fm_collectedT2] 
	[money] NOT NULL, [fm_InitShort] [money] NOT NULL, [fm_MTMAddShort] [money] NOT NULL, [fm_OthShort] [money] NOT NULL, [fm_ConcMargin] [money] NOT NULL, 
	[fm_DelvPMargin] [money] NOT NULL, [fm_MTMLoss] [money] NOT NULL, [fm_Filler3] [money] NOT NULL
	)
   IF ISNULL(@ComexDB,'') <> ''
   BEGIN	 
     SET @str = @strHeader+' '+'SELECT fm_companycode, fm_exchange, fm_dt, fm_clientcd, Sum(fm_spanmargin), Sum(fm_buypremmargin), Sum(fm_initialmargin), '
   +' Sum(fm_exposurevalue), '''' fm_clienttype, Sum(fm_additionalmargin), Sum(fm_collected), '
   +' '''' fm_mainbrcd, '''' mkrid, '''' mkrdt, Sum(fm_Regmargin), Sum(fm_Tndmargin), Sum(fm_Dlvmargin), '
   +' Sum(fm_SpreadBen), Sum(fm_SplMargin), Sum(fm_collectedT2), Sum(fm_InitShort), Sum(fm_MTMAddShort), '
   +' Sum(fm_OthShort), Sum(fm_ConcMargin), Sum(fm_DelvPMargin), Sum(fm_MTMLoss), Sum(fm_Filler3)'
   +' FROM (SELECT fm_companycode, fm_exchange, fm_dt, fm_clientcd, fm_spanmargin, fm_buypremmargin, fm_initialmargin, '
   +' fm_exposurevalue, '''' fm_clienttype, fm_additionalmargin, fm_collected, '''' fm_mainbrcd, '''' mkrid, '
   +' '''' mkrdt, fm_Regmargin, fm_Tndmargin, fm_Dlvmargin, fm_SpreadBen, fm_SplMargin, fm_collectedT2 '
   +' , fm_InitShort, fm_MTMAddShort, fm_OthShort, fm_ConcMargin, fm_DelvPMargin, 0 fm_MTMLoss, isNull(fm_Filler3, 0) fm_Filler3 '
   +' FROM '+@ComexDB+'.'+@ComexOwner+'.Fmargins, '+@ComexDB+'.'+@ComexOwner+'.Client_master, @tbl_UserList '
   +' WHERE fm_clientcd = cm_cd AND fm_Companycode = '''+@strCompany+'''  AND fm_dt = '''+@dtMarginDate+''' AND cm_type <> ''I'''
   +' AND CM_cD = Client_Code '
   +' UNION ALL '
   +' SELECT po_companycode, po_exchange, po_dt, po_clientcd, 0 fm_spanmargin, 0 fm_buypremmargin, 0 fm_initialmargin, '
   +' 0 fm_exposurevalue, 0 fm_clienttype, 0 fm_additionalmargin, 0 fm_collected, '''' fm_mainbrcd, '''' mkrid, '''' mkrdt, '
   +' 0 fm_Regmargin, 0 fm_Tndmargin, 0 fm_Dlvmargin, 0 fm_SpreadBen, 0 fm_SplMargin, 0 fm_collectedT2, 0 fm_InitShort, '
   +' 0 fm_MTMAddShort, 0 fm_OthShort, 0 fm_ConcMargin, 0 fm_DelvPMargin, CASE WHEN - sum(po_futvalue) > 0 THEN - sum(po_futvalue) ELSE 0 '
   +' END MarginReq, 0 fm_Filler3 '
   +' FROM '+@ComexDB+'.'+@ComexOwner+'.Fpositions, '+@ComexDB+'.'+@ComexOwner+'.Client_master, @tbl_UserList  '
   +' WHERE po_companycode = '''+@strCompany+''' AND po_clientcd = cm_cd AND po_dt = '''+@dtMarginDate+''' AND cm_type <> ''I'' '
   +' AND CM_cD = Client_Code '
   +' GROUP BY po_clientcd, po_companycode, po_exchange, po_dt '
   +' HAVING CASE WHEN - sum(po_futvalue) > 0 THEN - sum(po_futvalue) ELSE 0 END > 0 ) a '
   +' GROUP BY fm_companycode, fm_exchange, fm_dt, fm_clientcd '
   
     INSERT INTO #FmarginsRpt
     EXEC(@str)
   END
   
   DECLARE @tbl_CommexClient TABLE(ClientCode VARCHAR(50), Exchange VARCHAR(10))
   IF ISNULL(@ComexDB,'') <> ''
   BEGIN	 
     set @str =' SELECT distinct fm_clientcd, fm_Exchange '
		       +' FROM '+@ComexDB+'.'+@ComexOwner+'.Fmargins '
		       +' WHERE fm_companycode = '''+@strCompany+''' AND fm_dt = '''+@dtMarginDate+''''
   INSERT INTO @tbl_CommexClient
   EXEC(@str)   
   END		

   UPDATE #FmarginsRpt 
   SET fm_collected = fc_collected, fm_collectedT2 = fc_Collected1 
   FROM Fmargin_Clients
   WHERE fc_companycode = @strCompany AND fc_exchange = fm_Exchange AND fc_Segment = 'X' AND fc_dt = @dtMarginDate AND fm_clientcd = fc_clientcd 
   AND NOT EXISTS (SELECT 1 FROM @tbl_CommexClient WHERE ClientCode = fc_clientcd AND Exchange = fC_exchange)


   DECLARE @TBL_MARGIN TABLE(fm_clientcd VARCHAR(50),
   cm_Name VARCHAR(135), PeakShort MONEY,TotalShort MONEY,
   Collected MONEY, TotalMrgnCashNC MONEY, TotalMrgnFoNF MONEY,
   fm_TotalMrgn MONEY,
   EXCESSTDAY MONEY, ShortPenalty MONEY, LedgerBal MONEY)
 
   INSERT INTO @TBL_MARGIN(fm_clientcd, cm_Name, PeakShort, TotalShort, Collected, TotalMrgnCashNC, TotalMrgnFoNF, fm_TotalMrgn,
   EXCESSTDAY, ShortPenalty)
   SELECT *, Convert(DECIMAL(15, 2), Round((
				((CASE WHEN PeakShort > TotalShort THEN PeakShort ELSE TotalShort END)) * (
					CASE WHEN ((CASE WHEN PeakShort > TotalShort THEN PeakShort ELSE TotalShort END)
								) < 100000 AND CASE WHEN fm_TotalMrgn = 0 THEN 0 ELSE (
										(
											(
												(CASE WHEN PeakShort > TotalShort THEN PeakShort ELSE TotalShort END
													)
												) * 100
											) / (fm_TotalMrgn)
										) END < 10 THEN 0.5 ELSE 1 END / 100
					)
				), 2)) ShortPenalty
   FROM (
	SELECT fm_clientcd, isNull(cm_Name, 'Not Found') cm_Name, Tmp_Shortfall PeakShort, sum(TotalShortCashNC) + sum(TotalShortFoNF) TotalShort, sum(CollectedCashNC) + sum(CollectedFoNF) Collected, sum(
			TotalMrgnCashNC) TotalMrgnCashNC, sum(TotalMrgnFoNF) TotalMrgnFoNF, Sum(fm_TotalMrgn) fm_TotalMrgn, sum(fm_NFiller6) fm_NFiller6
	FROM (
		SELECT fm_clientcd, CASE fm_exchange + fm_Segment WHEN 'NC' THEN CASE WHEN (fm_TotalMrgn - (fm_collected + fm_collected1)
									) > 0 THEN (fm_TotalMrgn - (fm_collected + fm_collected1)
										) ELSE 0 END ELSE 0 END TotalShortCashNC, 
				CASE fm_exchange + fm_Segment WHEN 'NC' THEN (fm_collected + fm_collected1
							) ELSE 0 END CollectedCashNC, CASE fm_exchange + fm_Segment WHEN 'NC' THEN fm_TotalMrgn ELSE 0 END TotalMrgnCashNC, CASE fm_exchange + 
				fm_Segment WHEN 'NF' THEN CASE WHEN (fm_TotalMrgn - (fm_collected + fm_collected1)
									) > 0 THEN (fm_TotalMrgn - (fm_collected + fm_collected1)
										) ELSE 0 END ELSE 0 END TotalShortFoNF, CASE fm_exchange + fm_Segment WHEN 'NF' THEN (fm_collected + fm_collected1
							) ELSE 0 END CollectedFoNF, CASE fm_exchange + fm_Segment WHEN 'NF' THEN fm_TotalMrgn ELSE 0 END TotalMrgnFoNF, fm_TotalMrgn, fm_NFiller6
		FROM (
			SELECT fm_clientcd, fm_exchange, fm_Segment, Sum(fm_TotalMrgn) fm_TotalMrgn, Sum(fm_collected) fm_collected, Sum(fm_collected1) fm_collected1, Sum(
					fm_NFiller6) fm_NFiller6
			FROM (
				SELECT fm_clientcd, fm_exchange, fm_Segment, fm_TotalMrgn, fm_collected, fm_collected1, isNull(fm_NFiller6, 0) fm_NFiller6
				FROM Fmargins, Client_master
				WHERE cm_cd = fm_clientcd AND fm_Companycode = @strCompany AND fm_dt = @dtMarginDate
				
				UNION ALL
				
				SELECT fc_Filler1, fc_exchange, fc_Segment, 0 fm_TotalMrgn, fc_collected, fc_collected1, 0 fm_NFiller6
				FROM Fmargin_Clients, Client_master
				WHERE cm_cd = fc_clientcd AND fc_exchange <> '' AND fc_Companycode = @strCompany AND fc_dt = @dtMarginDate
				) a
			GROUP BY fm_clientcd, fm_exchange, fm_Segment
			) z, Client_master, branch_master
		WHERE fm_clientcd = cm_cd AND cm_brboffcode = bm_branchcd AND cm_type <> 'I'
		
	    UNION ALL
		
		SELECT fm_clientcd, 0 TotalShortCashNC, 0 CollectedCashNC, 0 TotalMrgnCashNC, CASE fm_exchange + 'X' WHEN 'NF' THEN CASE WHEN (
									(
										CASE fm_exchange WHEN 'M' THEN fm_Regmargin + fm_exposurevalue + fm_buypremmargin ELSE fm_initialmargin + fm_exposurevalue 
											END
										) + CASE fm_Exchange WHEN 'M' THEN fm_additionalmargin + fm_Tndmargin + fm_Dlvmargin - fm_SpreadBen + fm_ConcMargin + 
												fm_DelvPMargin ELSE fm_additionalmargin + fm_SplMargin END + fm_MTMLoss - (fm_collected + fm_collectedt2
										)
									) > 0 THEN (
										(
											CASE fm_exchange WHEN 'M' THEN fm_Regmargin + fm_exposurevalue + fm_buypremmargin ELSE fm_initialmargin + 
													fm_exposurevalue END
											) + CASE fm_Exchange WHEN 'M' THEN fm_additionalmargin + fm_Tndmargin + fm_Dlvmargin - fm_SpreadBen + fm_ConcMargin + 
													fm_DelvPMargin ELSE fm_additionalmargin + fm_SplMargin END + fm_MTMLoss - (fm_collected + fm_collectedt2
											)
										) ELSE 0 END ELSE 0 END TotalShortFoNF, CASE fm_exchange + 'X' WHEN 'NF' THEN (fm_collected + fm_collectedt2
							) ELSE 0 END CollectedFoNF, CASE fm_exchange + 'X' WHEN 'NF' THEN (CASE fm_exchange WHEN 'M' THEN fm_Regmargin + fm_exposurevalue + fm_buypremmargin ELSE fm_initialmargin + fm_exposurevalue END
							) + CASE fm_Exchange WHEN 'M' THEN fm_additionalmargin + fm_Tndmargin + fm_Dlvmargin - fm_SpreadBen + fm_ConcMargin + fm_DelvPMargin ELSE 
								fm_additionalmargin + fm_SplMargin END + fm_MTMLoss ELSE 0 END TotalMrgnFoNF, (CASE fm_exchange WHEN 'M' THEN fm_Regmargin + fm_exposurevalue + fm_buypremmargin ELSE fm_initialmargin + fm_exposurevalue END
				) + CASE fm_Exchange WHEN 'M' THEN fm_additionalmargin + fm_Tndmargin + fm_Dlvmargin - fm_SpreadBen + fm_ConcMargin + fm_DelvPMargin ELSE 
					fm_additionalmargin + fm_SplMargin END + fm_MTMLoss, fm_Filler3 fm_NFiller6
		FROM #FmarginsRpt, Client_master, branch_master
		WHERE fm_clientcd = cm_cd AND cm_brboffcode = bm_branchcd AND fm_Companycode = @strCompany AND fm_dt = @dtMarginDate
		
		
		) a, Client_master, branch_master, #TmpPeakColl
	WHERE fm_clientcd = cm_cd AND cm_brboffcode = bm_branchcd AND fm_clientcd = Tmp_Clientcd
	GROUP BY fm_clientcd, cm_Name, cm_email, bm_email, cm_brboffcode, bm_branchname, bm_add1, cm_add1, bm_add2, cm_add2, bm_add3, cm_add3, Tmp_Shortfall
	--HAVING Sum(fm_TotalMrgn) > 0 OR Tmp_Shortfall > 0
	) b
   ORDER BY fm_clientcd
   
  UPDATE A SET A.LedgerBal = B.LedgerBal
  FROM @TBL_MARGIN A, (SELECT ld_clientcd, isnull(SUM(ld_amount), 0) LedgerBal
  FROM ledger(NOLOCK)
  WHERE ld_dt <= @dtMarginDate AND left(ld_dpid, 1) = @strCompany
  GROUP BY ld_clientcd
  HAVING isnull(SUM(ld_amount), 0) >0 ) B
  WHERE A.fm_clientcd = B.ld_clientcd
  


  IF @strOutputType = 'X'
  BEGIN
    DECLARE @XMLDATA1 XML
	IF @strRequestFrom = 'W'
	BEGIN
      SET @XMLDATA1 = (SELECT ClientCode = fm_clientcd, 	
      [Name] = cm_Name, Penalty = ShortPenalty, Collection = isnull(LedgerBal,0)+TotalShort,LedgerDebit = ISNULL(LedgerBal,0),
      HighestShort = TotalShort,	PeakShort = PeakShort,EODShort = fm_TotalMrgn,	
      Collected = Collected, ExcessTDay = EXCESSTDAY, TotalMrgn = fm_TotalMrgn, CashMargin = TotalMrgnCashNC, FOMargin = TotalMrgnFoNF
      FROM @TBL_MARGIN FOR XML PATH('Margin'))
	END
	ELSE IF @strRequestFrom = 'M'
	BEGIN
	  SET @XMLDATA1 = (SELECT Penalty = ShortPenalty, Collection = isnull(LedgerBal,0)+TotalShort,LedgerDebit = ISNULL(LedgerBal,0),
      HighestShort = TotalShort,	PeakShort = PeakShort,EODShort = fm_TotalMrgn,	
      Collected = Collected, ExcessTDay = EXCESSTDAY, TotalMrgn = fm_TotalMrgn, CashMargin = TotalMrgnCashNC, FOMargin = TotalMrgnFoNF
      FROM @TBL_MARGIN FOR XML PATH('Margin'))
	END
	SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
  END
   IF @strOutputType = 'G'
   BEGIN
     SELECT ClientCode = fm_clientcd, 	
      [Name] = cm_Name, Penalty = ShortPenalty, Collection = isnull(LedgerBal,0)+TotalShort,LedgerDebit = ISNULL(LedgerBal,0),
      HighestShort = TotalShort,	PeakShort = PeakShort,EODShort = fm_TotalMrgn,	
      Collected = Collected, ExcessTDay = EXCESSTDAY, TotalMrgn = fm_TotalMrgn, CashMargin = TotalMrgnCashNC, FOMargin = TotalMrgnFoNF
      FROM @TBL_MARGIN
   END	
  SET @o_vcErrorFlag  = 'S'
  --SET @o_vcErrorMessage = 'Process Completed'
END
GO

CREATE PROCEDURE stpr_Rpt_BillReport @vcXML NVARCHAR(MAX), @o_vcErrorFlag VARCHAR(1) OUTPUT, 
@o_vcErrorMessage VARCHAR(MAX) OUTPUT 
WITH ENCRYPTION
AS
BEGIN
 /*
 ///////////////////////////////////////////////////////////////////////////////////////////
 // Create By     : VAIBHAV GARG
 // Created Date  : 13-DEC-2023
 // Description   : 
 // Reviewed By   : 
 // Review Date   : 
 //////////////////////////////////////////////////////////////////////////////////////////
*/
 --- Parameter Declaration
 
  DECLARE @dtFromDate VARCHAR(8), @dtToDt VARCHAR(8), @strUserId VARCHAR(500) = '', @strExchSeg VARCHAR(100),
  @XMLData XML, @strAccountType VARCHAR(500)='', @strTable VARCHAR(50)='', @strString VARCHAR(MAX) = '',
  @blnTplusCommex BIT, @StrCommexConn VARCHAR(MAX) = '', @strCommTable VARCHAR(100)='', @strCommClientMaster VARCHAR(100)='',
  @strCommCompanyExchange VARCHAR(100)='', @strsql1 VARCHAR(500)='', @strsqlstart VARCHAR(MAX)='', @strsqlLast VARCHAR(500)='',
  @strsqlHeader VARCHAR(MAX)='', @strSqlMain VARCHAR(MAX)='', @strSqlExecute VARCHAR(MAX)='', @strOutputType VARCHAR(1), 
  @strProduct VARCHAR(50)='', @strSelectTag VARCHAR(1)='', @strSelectUsers VARCHAR(500)='', @ExchSeg VARCHAR(50)='', 
  @strStringMin VARCHAR(MAX)='', @strSplFilter VARCHAR(MAX)='', @strClearingExchange VARCHAR(1) ='' , 
  @strConsiderOptionBF VARCHAR(1)='N'  , @strReportType VARCHAR(50)='', @strSettType VARCHAR(1)='', @strCompanyCode VARCHAR(1),
  @strRepSubType VARCHAR(MAX)='', @strSettNo VARCHAR(20)='', @strLookUp VARCHAR(100)='',@StrBillOpen VARCHAR(100)='', @XMLDATA1 XML;
  
  IF @vcXML = ''
  BEGIN
    SET @o_vcErrorFlag  = 'E'
    SET @o_vcErrorMessage = 'Please Send Input Parameter(s)'
    RETURN 1
  END 
  SET @o_vcErrorFlag = 'S'
  SET @XMLData = CAST('<root>'+@vcXML+'</root>' AS XML)
  
  SELECT @dtFromDate = ISNULL(x.value('(FromDt)[1]', 'VARCHAR(8)'),''),
  @strProduct = ISNULL(x.value('(Product)[1]', 'VARCHAR(50)'),''),
  @dtToDt = ISNULL(x.value('(ToDt)[1]', 'VARCHAR(8)'),''),
  @strUserId = ISNULL(x.value('(UserId)[1]', 'VARCHAR(500)'),''),
  @ExchSeg = ISNULL(x.value('(ExchSeg)[1]', 'VARCHAR(500)'),''),
  @strSelectTag = ISNULL(x.value('(SelectTag)[1]', 'VARCHAR(1)'),''),
  @strSelectUsers = ISNULL(x.value('(SelectUsers)[1]', 'VARCHAR(500)'),''),
  @strOutputType = ISNULL(x.value('(OutputType)[1]', 'VARCHAR(1)'),''),
  @strSplFilter = ISNULL(x.value('(SplFilter)[1]', 'VARCHAR(MAX)'),''),
  @strCompanyCode = ISNULL(x.value('(CompanyCode)[1]', 'VARCHAR(1)'),''),
  @strReportType = ISNULL(x.value('(RepType)[1]', 'VARCHAR(100)'),''),
  @strRepSubType = ISNULL(x.value('(RepSubType)[1]', 'VARCHAR(100)'),''),
  @strSettType = ISNULL(x.value('(SettType)[1]', 'VARCHAR(1)'),''),
  @strSettNo = ISNULL(x.value('(SettNo)[1]', 'VARCHAR(20)'),''),
  @strLookUp = ISNULL(x.value('(LookUp)[1]', 'VARCHAR(100)'),'')
  FROM @XMLData.nodes('/root') AS XTbl(x) 
  

  IF ISNULL(@strLookUp,'') <> ''
  BEGIN  
    IF CHARINDEX('/',@strLookUp) > 3
	BEGIN
	  SET @strUserId = SUBSTRING(@strLookUp,1,CHARINDEX('/',@strLookUp)-1)
	  SET @strLookUp = SUBSTRING(@strLookUp,CHARINDEX('/',@strLookUp)+1,LEN(@strLookUp))
	  SET @strSelectTag = ''
	  SET @strSelectUsers = ''
	END
--SELECT @strLookUp
  
    if SUBSTRING(@strLookUp,3,1)  ='C'
	BEGIN
	  SET @strProduct = 'CASH'
	  SELECT @dtFromDate = se_stdt, @strSettNo = se_stlmnt FROM Settlements(NOLOCK) 
      WHERE se_exchange+'/'+'C'+'/'+se_stlmnt+'/'+se_payoutdt = @strLookUp
	  SET @ExchSeg = ''
	  SET @dtToDt = @dtFromDate
	END
	ELSE IF SUBSTRING(@strLookUp,3,1)  ='F'
	BEGIN
      SET @strProduct = 'DERV'	  
	  SET @dtFromDate = SUBSTRING(@strLookUp,5,8)
	  SET @dtToDt = @dtFromDate
	END
  END
  
  DECLARE @StrSummaryDT VARCHAR(10)=''
  SELECT @StrSummaryDT = sp_sysvalue FROM Sysparameter(NOLOCK) WHERE sp_parmcd = 'SummaryCont'
  
  if isnull(@StrSummaryDT,'') = ''
  begin
    set @StrSummaryDT = '20990101'
  end
  
  --SELECT @dtFromDate, @strSettNo, @strProduct
  	
  IF @strSplFilter = ''
  BEGIN
	SET @strStringMin  = 'DECLARE @tbl_UserList TABLE(Client_Code VARCHAR(50)) '
    +' INSERT INTO @tbl_UserList(Client_Code) '
    +' SELECT * FROM DBO.[fn_GetClients]('''+@strUserId+''','''+@strSelectTag+''','''+@strSelectUsers+''') '
  END  
  ELSE
  IF @strSplFilter <> ''
  BEGIN
    SET @strStringMin  = ' DECLARE @tbl_UserList TABLE (Client_Code VARCHAR(10)) '
	+' INSERT INTO @tbl_UserList(Client_Code) SELECT distinct CM_CD FROM Client_master(NOLOCK) WHERE 1 = 1  AND '+@strSplFilter
		 
  END	
  BEGIN TRY
  IF @strProduct = 'CASH'
  BEGIN
    DECLARE @tbl_CashBill TABLE(BillNo Numeric, BillDate VARCHAR(8), CompanyCode VARCHAR(10), ClientCode VARCHAR(50), 
	ClientName VARCHAR(100), Settlement VARCHAR(20),
	[OrderNo] VARCHAR(30),[TradeNo]  VARCHAR(30) ,
	TIME  VARCHAR(30),Security  VARCHAR(100),Buy INT, Sell INT, [MarketRate]  MONEY, [Brokerage] MONEY,
	BuyValue MONEY,SellValue MONEY, NetValue MONEY)
	
	SELECT @strClearingExchange = (CASE WHEN CH_ClgHs = 'I' THEN 'B' ELSE CH_ClgHs END)
    FROM ClearingHouse
    WHERE CH_CompanyCode = @strCompanyCode AND CH_Segment = 'C' 
	AND CH_EffDt = (SELECT max(CH_EffDt) 
	FROM ClearingHouse WHERE CH_CompanyCode = @strCompanyCode AND CH_Segment = 'C' AND CH_EffDt <= @dtFromDate)
    SET @strString = ''
	--
	
	IF @StrSummaryDT > @dtFromDate
	BEGIN
	  SET @strString  =  @strStringMin+' '+' DECLARE  @se_type VARCHAR(1), @se_stdt VARCHAR(8), '
      +' @se_endt VARCHAR(8), @settlementno VARCHAR(100) = '''', @settPostingSettment VARCHAR(100) = '''' '

	  +' DECLARE @tbl_Settlement TABLE ( '
	  +' SettlementType VARCHAR(1), SettStartDate VARCHAR(8), SettEndDate VARCHAR(8), SettlementNo VARCHAR(100), '
	  +' PostingSettlement VARCHAR(100)) '

	  +' DECLARE CurSettlement CURSOR FOR '
      +' SELECT DISTINCT se_type, se_stdt, se_endt '
      +' FROM SEttlements SE '
      +' WHERE se_stdt >= '''+@dtFromDate+''' AND se_endt <= '''+@dtToDt+''' ' 
	  +' AND EXISTS (SELECT 1 FROM Trx(NOLOCK) WHERE td_clientcd IN(select Client_Code from @tbl_UserList) '
	  +' AND td_dt >= '''+@dtFromDate+''' AND td_dt <= '''+@dtToDt+''' AND td_stlmnt = SE.se_stlmnt ) '
	  +' and se_exchange+se_type not in (select sy_exchange+sy_type from Settlement_type Where sy_maptype in (''S'',''W'',''V'')) '
	

    
	  SET @strString  = @strString+' OPEN CurSettlement '
      +' FETCH NEXT FROM CurSettlement INTO @se_type, @se_stdt, @se_endt '
      +' WHILE @@FETCH_STATUS = 0 '
      +' BEGIN '
	  +'   SET @settlementno = '''' '
	  +'   SET @settPostingSettment = '''' '
	  +'   SELECT @settlementno = @settlementno + ''|'' + se_stlmnt, @settPostingSettment = @settPostingSettment + ''|'' + (CASE WHEN  '
      +'   se_exchange = '''+@strClearingExchange+''' THEN se_stlmnt ELSE '''' END) FROM SEttlements '
	  +'   WHERE se_type = @se_type AND se_stdt >= @se_stdt AND se_endt <= @se_endt '
	  +'   INSERT INTO @tbl_Settlement (SettlementType, SettStartDate, SettEndDate, SettlementNo, PostingSettlement) '
	  +'   VALUES (@se_type, @se_stdt, @se_endt, @settlementno, @settPostingSettment) '
	  +'   FETCH NEXT FROM CurSettlement INTO @se_type, @se_stdt, @se_endt '
      +' END '
      +' CLOSE CurSettlement '
      +' DEALLOCATE CurSettlement '
   
      +' SELECT Client_COde, CompanyCode, Settlement, [Order#], [Trade#], [TIME], [Security], [Buy], [Sell], [Market Rate], [Brokerage], [Buy Value],  '
	  +' [Sell Value], [Net Value] '
      +' FROM (SELECT Client_COde, td_companycode as CompanyCode, Settlement = replace(sett.PostingSettlement, ''|'', ''''), td_orderid AS [Order#], td_tradeid [Trade#], '
      +' CASE td_ssrno WHEN - 1 THEN ''b/f'' ELSE td_time END TIME, rtrim(ss_name) + '' ('' + td_scripcd + '')'' Security, td_bqty  '
      +' Buy, td_sqty Sell, convert(DECIMAL(15, 2), td_marketrate) AS [Market Rate], convert(DECIMAL(15, 2), '
      +' td_brokerage * (td_bqty + td_sqty)) [Brokerage],  '
      +' convert(DECIMAL(15, 2), convert(MONEY,td_rate * td_bqty)) [Buy Value], convert(DECIMAL(15, 2),  '
      +' convert(MONEY,  td_rate  * td_sqty)) [Sell Value], '
      +' convert(MONEY,  td_rate * (td_Sqty - td_Bqty))  [Net Value], '
      +' '''' [_], rtrim(ss_name) + CASE td_ssrno WHEN - 1 THEN ''a'' ELSE ''b'' END [Ordr] FROM trx(NOLOCK) '
	  +' LEFT OUTER JOIN std_rates (NOLOCK) '
	  +' ON td_stlmnt = sr_stlmnt AND td_scripcd = sr_scripcd, securities (NOLOCK), '
	  +' @tbl_Settlement sett, @tbl_UserList X  '
	  +' WHERE td_clientcd = x.Client_Code '
	  +' AND td_stlmnt IN (SELECT value FROM ReturnTable(sett.SettlementNo, ''|'') ) ' 
	  +' AND td_scripcd = ss_cd AND trx.td_dt BETWEEN SettStartDate AND SettendDate '
	  +' AND td_companycode = '''+@strCompanyCode+''' '

      IF ISNULL(@ExchSeg,'') <> ''
      BEGIN
        SET @strString =   @strString+'  AND substring(replace(sett.PostingSettlement, ''|'', ''''),1,1) = SUBSTRING('''+@ExchSeg+''',2,1) '
      END	
 	

	  SET @strString =   @strString+' UNION ALL '
	  +' SELECT Client_COde, CompanyCode, Settlement, ''0'', ''0'', ''Charges'', rtrim(sh_desc), 0, 0, convert(DECIMAL(15, 2), 0), convert(DECIMAL(15, 2), 0), '
	  +' convert(DECIMAL(15, 2), sum(sh_amount)), convert(DECIMAL(15, 2), 0), convert(DECIMAL(15, 2), sum(sh_amount))*-1, '''', ''zzz'' '
	  +' FROM (SELECT Client_COde, sh_companycode As CompanyCode, Settlement = replace(sett.PostingSettlement, ''|'', ''''), rtrim(sh_desc) sh_desc, convert(DECIMAL(15, 2), sh_amount) sh_amount '
	  +' FROM Specialcharges(NOLOCK), @tbl_Settlement sett , @tbl_UserList X '
	  +' WHERE sh_clientcd = x.Client_Code AND sh_stlmnt IN ( SELECT value FROM ReturnTable(sett.SettlementNo, ''|'')) '
	  +' AND sh_companycode = '''+@strCompanyCode+''''
	
      IF ISNULL(@ExchSeg,'') <> ''
      BEGIN
        SET @strString =   @strString+'  AND substring(replace(sett.PostingSettlement, ''|'', ''''),1,1) = SUBSTRING('''+@ExchSeg+''',2,1) '
      END	
	
 
	
	  SET @strString =   @strString+' UNION ALL '
	  +' SELECT Client_COde, sh_companycode, Settlement = replace(sett.PostingSettlement, ''|'', ''''), rtrim(cg_desc), convert(DECIMAL(15, 2), sum( sh_servicetax))*-1' 
	  +' FROM Specialcharges(NOLOCK), Charges_master(NOLOCK), @tbl_Settlement sett , @tbl_UserList X '
	  +' WHERE sh_companycode = cg_companycode AND left(sh_stlmnt, 1) = cg_exchange AND cg_cd = ''01'' AND sh_clientcd = X.Client_COde '
	  +' AND sh_stlmnt IN (SELECT value FROM ReturnTable(sett.SettlementNo, ''|'')) AND sh_servicetax > 0 '
	  +' AND sh_companycode = '''+@strCompanyCode+''''
	
      IF ISNULL(@ExchSeg,'') <> ''
      BEGIN
        SET @strString =   @strString+'  AND substring(replace(sett.PostingSettlement, ''|'', ''''),1,1) = SUBSTRING('''+@ExchSeg+''',2,1) '
      END	
	
	  SET @strString =   @strString+'  GROUP BY Client_COde, sh_companycode, replace(sett.PostingSettlement, ''|'', ''''), rtrim(cg_desc) ) '
      +' a GROUP BY Client_COde, CompanyCode, Settlement, sh_desc ) x11 '
	
	  IF @strSettNo <> ''
	  BEGIN
	    SET @strString  = @strString+' '+' WHERE  Settlement IN(SELECT VALUE FROM ReturnTable('''+@strSettNo+''','','')) '
	  END
      SET @strString  = @strString+' '+' ORDER BY Client_COde, Settlement, ordr, Security '
	  BEGIN TRY
	   -- SELECT @strString
	    INSERT INTO @tbl_CashBill(ClientCode, CompanyCode,  
	    Settlement, [OrderNo], [TradeNo], TIME, 
	    Security, Buy, Sell, [MarketRate], [Brokerage], BuyValue, SellValue, NetValue)
	    EXEC(@strString)
	  END TRY
      BEGIN CATCH
	    SET @o_vcErrorFlag  = 'E'
        SET @o_vcErrorMessage = ERROR_MESSAGE()
        RETURN 1
      END CATCH
    
	  UPDATE A SET A.ClientName = CM.cm_name
      FROM @tbl_CashBill A, Client_Master CM
      WHERE A.ClientCode = CM.cm_cd 
	
	  UPDATE A SET A.BillNo = CM.bl_billno, BillDate = CM.bl_billdt
      FROM @tbl_CashBill A, Bills CM
      WHERE A.ClientCode = CM.bl_clientcd 
	  and a.Settlement = CM.bl_stlmnt
	
	  IF @strOutputType = 'X'
	  BEGIN
	    SET @XMLDATA1 = (SELECT * FROM @tbl_CashBill
	    ORDER BY ClientCode, BillDate, BillNo, Settlement, CAST((CASE WHEN TIME='Charges' THEN 9 ELSE 1 END) AS INT), Security FOR XML PATH('Bill'))
	    SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
	    RETURN 1
	  END
	  ELSE
	  BEGIN
        SELECT * FROM @tbl_CashBill
	    ORDER BY ClientCode, BillDate, BillNo, Settlement, CAST((CASE WHEN TIME='Charges' THEN 9 ELSE 1 END) AS INT), Security
	    RETURN 1
	  END  
	END   
	ELSE
	BEGIN
	  DECLARE @tbl_billNew TABLE(ClientCode VARCHAR(20), ClientName VARCHAR(200), 
	  ScripCode VARCHAR(20), ScripName VARCHAR(200), ISIN VARCHAR(50), Settlement VARCHAR(20), BuyQty MONEY, BuyRate MONEY, BuyValue MONEY,
	  BuyBrokerage MONEY, SellQty MONEY, SellRate MONEY, SellValue MONEY, SellBrokerage MONEY,
	  NetQty MONEY, NetValue MONEY, SerialNO INT)
	 
	  
	  SET @strString = @strStringMin+' SELECT ctx_Clientcd, ctx_Scrip, ss_name,  ctx_ISIN, ctx_Stlmnt, ctx_Bqty, ctx_BRate, ctx_BValue, ctx_BBrokerage, ctx_Sqty,  '
	  +' ctx_sRate, ctx_sValue, ctx_sBrokerage, ctx_Nqty, ctx_NetAmount, ctx_SrNo '
      +' FROM ctrx(NOLOCK), Securities(NOLOCK) X, @tbl_UserList X1 '
      +' WHERE ctx_Company = '''+@strCompanyCode+''''
      +' AND ctx_dt >= '''+@dtFromDate+''''
      +' AND ctx_dt <= '''+@dtToDt+''''
	  +' AND ctx_Scrip = ss_cd AND ctx_Clientcd = CLIENT_CODE '
      +' AND ((ctx_Stlmnt in(SELECT VALUE FROM ReturnTable('''+@strSettNo+''','','')) AND '''+@strSettNo+''' <> '''') OR '''+@strSettNo+''' = '''') '
      +' ORDER BY ctx_Clientcd, ctx_Stlmnt, ctx_srno '
	  
	  INSERT INTO @tbl_billNew(ClientCode, ScripCode, ScripName, ISIN, Settlement, BuyQty, BuyRate, BuyValue, BuyBrokerage, SellQty, 
	  SellRate, SellValue, SellBrokerage, NetQty, NetValue, SerialNO)
	  EXEC(@strString)
	  	  
	  SET @strString = @strStringMin+' SELECT CC_CLIENTCD, cc_desc, ''CHARGES'',  cc_Stlmnt,  cc_amount, SRNO '
	  +' FROM CCharges(NOLOCK), @tbl_UserList X1  '
      +' WHERE cc_CompanyCode = '''+@strCompanyCode+''''
      +' AND CC_DT >= '''+@dtFromDate+''''
      +' AND CC_DT <= '''+@dtToDt+''''
      +' AND LEN(cc_Stlmnt) >2  AND CC_CLIENTCD = CLIENT_CODE '
	  +' AND ((cc_Stlmnt in(SELECT VALUE FROM ReturnTable('''+@strSettNo+''','','')) AND '''+@strSettNo+''' <> '''') OR '''+@strSettNo+''' = '''') '
      +' ORDER BY CC_CLIENTCD, cc_Stlmnt, SRNO '
	  
	  INSERT INTO @tbl_billNew(ClientCode, ScripName, ISIN, Settlement, NetValue, SerialNO)
	  EXEC(@strString)
	  
	  UPDATE A SET CLIENTNAME = B.CM_NAME
	  FROM @tbl_billNew A, CLIENT_MASTER(NOLOCK) B
	  WHERE A.ClientCode = B.CM_cD
	  
	  IF @strOutputType = 'X'
	  BEGIN
	    SET @XMLDATA1 = (SELECT ClientCode, ScripCode = ISNULL(ScripCode,''), ScripName, ISIN, Settlement, BuyQty = ISNULL(BuyQty,0), 
		BuyRate =  ISNULL(BuyRate,0),  BuyValue = ISNULL(BuyValue,0), BuyBrokerage = ISNULL(BuyBrokerage,0), SellQty = ISNULL(SellQty,0), 
	    SellRate = ISNULL(SellRate,0), SellValue = ISNULL(SellValue,0), SellBrokerage = ISNULL(SellBrokerage,0), NetQty = ISNULL(NetQty,0), 
		NetValue = ISNULL(NetValue,0)*-1 FROM @tbl_billNew
	    ORDER BY ClientCode, Settlement, CAST((CASE WHEN ISIN='Charges' THEN 9 ELSE 1 END) AS INT), SerialNO, ScripName FOR XML PATH('Bill'))
	    SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
	    RETURN 1
	  END
	  ELSE
	  BEGIN
        SELECT ClientCode, ScripCode = ISNULL(ScripCode,''), ScripName, ISIN, Settlement, BuyQty = ISNULL(BuyQty,0), 
		BuyRate =  ISNULL(BuyRate,0),  BuyValue = ISNULL(BuyValue,0), BuyBrokerage = ISNULL(BuyBrokerage,0), SellQty = ISNULL(SellQty,0), 
	    SellRate = ISNULL(SellRate,0), SellValue = ISNULL(SellValue,0), SellBrokerage = ISNULL(SellBrokerage,0), NetQty = ISNULL(NetQty,0), 
		NetValue = ISNULL(NetValue,0)*-1 FROM @tbl_billNew
	    ORDER BY ClientCode, Settlement, CAST((CASE WHEN ISIN='Charges' THEN 9 ELSE 1 END) AS INT), SerialNO, ScripName 
	    RETURN 1
	  END 
	END
  END
  ELSE IF @strProduct = 'DERV'
  BEGIN
  
    IF @StrSummaryDT <= @dtFromDate
	BEGIN
	  DECLARE @tbl_billDervNew TABLE(TradeDate VARCHAR(20),
      Exchange VARCHAR(1), Segment VARCHAR(1),
      ClientCode VARCHAR(20), ClientName VARCHAR(200),
      SeriesId VARCHAR(50), ScripName VARCHAR(200),
      BuySellFlag VARCHAR(1), TrxFlag VARCHAR(50), BuyQty money, 
      SellQty MONEY, Rate MONEY, Brokerage MONEY, ClosingRate MONEY, Amount money, NetAmount MONEY, SerialNo INT)
	  
	  SET @strString = @strStringMin+' Select ctd_dt, ctd_Exch, ctd_Seg, ctd_Clientcd, ctd_seriesid,sm_sname, ctd_BSFlag, ctd_Flag, ctd_Bqty, '
      +' ctd_Sqty, ctd_Rate,  ctd_Brokergae, ctd_ClosingRate, ctd_Amount, ctd_NetAmount, ctd_SrNo '
      +' FROM Ctrades(NOLOCK), Series_master(NOLOCK) SM, @tbl_UserList X1 '
      +' WHERE ctd_Company = '''+@strCompanyCode+''''
      +' AND ctd_dt >= '''+@dtFromDate+''''
      +' and ctd_dt <= '''+@dtToDt+''''
      +' AND CTD_CLIENTCD = client_CODE '
      +' AND ctd_seriesid = sm_seriesid '
      +' AND ctd_Exch = sm_exchange '
      +' AND ctd_Seg = sm_Segment '
      +' order by ctd_dt, ctd_Exch, ctd_Seg, ctd_Clientcd, ctd_SrNo '

      INSERT INTO @tbl_billDervNew(TradeDate, Exchange, Segment, ClientCode, SeriesId, ScripName, 
      BuySellFlag, TrxFlag, BuyQty, SellQty, Rate, Brokerage, ClosingRate, Amount,  NetAmount, SerialNo)
	  EXEC(@strString)
    	 
	  SET @strString = @strStringMin+' SELECT CC_DT, SUBSTRING(cc_Stlmnt,1,1), SUBSTRING(cc_Stlmnt,2,1), CC_CLIENTCD, cc_desc, ''CHARGES'', cc_amount, SRNO '
	  +' FROM CCharges(NOLOCK), @tbl_UserList X1  '
      +' WHERE cc_CompanyCode = '''+@strCompanyCode+''''
      +' AND CC_DT >= '''+@dtFromDate+''''
      +' AND CC_DT <= '''+@dtToDt+''''
      +' AND LEN(cc_Stlmnt) <= 2  AND CC_CLIENTCD = CLIENT_CODE '
	  +' ORDER BY CC_CLIENTCD, cc_Stlmnt, SRNO '
	  
      INSERT INTO @tbl_billDervNew(TradeDate, Exchange, Segment, ClientCode, ScripName, 
      TrxFlag,  Amount,  SerialNo)
	  EXEC(@strString)
	  
	  UPDATE A SET CLIENTNAME = B.CM_NAME
	  FROM @tbl_billDervNew A, CLIENT_MASTER(NOLOCK) B
	  WHERE A.ClientCode = B.CM_cD
	  
	  IF @strOutputType = 'X'
	  BEGIN
	    SET @XMLDATA1 = (SELECT ClientCode, CLIENTNAME, Exchange, Segment,  SeriesId = ISNULL(SeriesId,''), ScripName, BuySellFlag = isnull(BuySellFlag,''), TrxFlag, BuyQty = ISNULL(BuyQty,0), 
		SellQty = ISNULL(SellQty,0), Rate = ISNULL(Rate,0), Brokerage = ISNULL(Brokerage,0), ClosingRate = ISNULL(ClosingRate,0), Amount = ISNULL(Amount,0)*-1 
		FROM @tbl_billDervNew
	    ORDER BY ClientCode, Exchange, Segment, CAST((CASE WHEN TrxFlag='Charges' THEN 9 ELSE 1 END) AS INT), SerialNO, ScripName FOR XML PATH('Bill'))
	    SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
	    RETURN 1
	  END
	  ELSE
	  BEGIN
        SELECT ClientCode, CLIENTNAME, Exchange, Segment,  SeriesId = ISNULL(SeriesId,''), ScripName, BuySellFlag = isnull(BuySellFlag,''), TrxFlag, BuyQty = ISNULL(BuyQty,0), 
		SellQty = ISNULL(SellQty,0), Rate = ISNULL(Rate,0), Brokerage = ISNULL(Brokerage,0), ClosingRate = ISNULL(ClosingRate,0), Amount = ISNULL(Amount,0) *-1
		FROM @tbl_billDervNew
	    ORDER BY ClientCode, Exchange, Segment, CAST((CASE WHEN TrxFlag='Charges' THEN 9 ELSE 1 END) AS INT), SerialNO, ScripName
	    RETURN 1
	  END 
    END
	ELSE
	BEGIN
      CREATE TABLE #tbl_ClientPLDETAIL (BillNo Numeric, BillDate VARCHAR(8), CompanyCode VARCHAR(10), Exchange VARCHAR(10), Segment VARCHAR(10),  ClientCode VARCHAR(50), 
	  ClientName VARCHAR(100), 
      Symbol VARCHAR(50), seriesid INT, ExpiryDate VARCHAR(8), Scrip VARCHAR(100), Multiplier INT, 
	  TrxnDate VARCHAR(8), OrderNo VARCHAR(50), TradeNo  VARCHAR(50), TradeTIME  VARCHAR(15), 
	  BuyQty MONEY, SellQty Money, MarketRate MONEY, BuyValue MONEY, SellValue MONEY, NetValue MONEY)
	
	
	  CREATE TABLE #tbl_ClientMainPL (SerialNo INT IDENTITY(1,1), BillNo Numeric, BillDate VARCHAR(8),CompanyCode VARCHAR(10), Exchange VARCHAR(10), Segment VARCHAR(10),  ClientCode VARCHAR(50), 
	  ClientName VARCHAR(100), 
      Symbol VARCHAR(50), seriesid INT, ExpiryDate VARCHAR(8), Scrip VARCHAR(100), Multiplier INT, 
	  TrxnDate VARCHAR(8), OrderNo VARCHAR(50), TradeNo  VARCHAR(50), TradeTIME  VARCHAR(15), 
	  BuyQty MONEY, SellQty Money, MarketRate MONEY, BuyValue MONEY, SellValue MONEY, NetValue MONEY)
	
	  CREATE INDEX indx_ClientPL ON #tbl_ClientPLDETAIL (seriesid)

      DECLARE @tbl_BSClient TABLE(CompanyCode VARCHAR(10), Exchange VARCHAR(10), Segment VARCHAR(10), ClientCode VARCHAR(50), ClientName VARCHAR(100), 
      Symbol VARCHAR(50), seriesid INT, ExpiryDate VARCHAR(8), Scrip VARCHAR(100), Multiplier INT, TrxnDate VARCHAR(8), BOT_QTY MONEY, BOT_VALUE MONEY, 
      SOLD_QTY MONEY, SOLD_VALUE MONEY)

      DECLARE @tbl_CLClient TABLE(CompanyCode VARCHAR(10), Exchange VARCHAR(10), Segment VARCHAR(10),  ClientCode VARCHAR(50), ClientName VARCHAR(100), 
      Symbol VARCHAR(50), seriesid INT, ExpiryDate VARCHAR(8), Scrip VARCHAR(100), Multiplier INT, EX_QTY MONEY, EX_VALUE MONEY, AS_QTY MONEY, AS_VALUE MONEY)
	
	
	 
      DECLARE @tbl_billCharges TABLE(CompanyCode VARCHAR(10), Exchange VARCHAR(10), Segment VARCHAR(10), 
      ClientCode VARCHAR(10) NOT NULL,
      ChargesDescp [char] (40) NOT NULL,
      [bc_amount] [money] NOT NULL)
  
  
      DECLARE @tbl_DervBill TABLE(BillNo Numeric, BillDate VARCHAR(8), Tag INT, Exchange VARCHAR(10),
	  ClientCode VARCHAR(10), ClientName VARCHAR(100), seriesid VARCHAR(20), ExpiryDate VARCHAR(8), Scrip VARCHAR(100), Multiplier INT, BF_QTY MONEY, 
	  BF_CloseRate MONEY, BF_VALUE MONEY, BOT_QTY MONEY, BOT_VALUE MONEY, 
      SOLD_QTY MONEY,SOLD_VALUE MONEY, EX_QTY MONEY, EX_VALUE MONEY, AS_QTY MONEY, AS_VALUE MONEY, 
      NET_QTY MONEY, CMP MONEY, NET_VALUE MONEY, MTM MONEY)
	
  
      DECLARE  @iNoOfDay INT = 7, @dtDate VARCHAR(8)='', @iDateCounter INT = 0
      WHILE @iDateCounter<= @iNoOfDay
      BEGIN
        IF NOT EXISTS(select 1 from Fholiday_master where hm_companycode = @strCompanyCode and hm_exchange = 'N' and hm_segment ='F' 
        and hm_dt = CONVERT(VARCHAR,DATEADD(DAY,@iDateCounter,CAST(@dtFromDate AS DATE)),112))
        BEGIN
	      SET @dtFromDate =  CONVERT(VARCHAR,DATEADD(DAY,@iDateCounter,@dtFromDate),112)
	      GOTO ABC;
        END
	    SET @iDateCounter = @iDateCounter + 1
      END
      ABC:
      SET @iDateCounter = 0
      WHILE @iDateCounter<= @iNoOfDay
      BEGIN
        IF NOT EXISTS(select 1 from Fholiday_master(NOLOCK) 
	    WHERE hm_companycode = @strCompanyCode and hm_exchange = 'N' and hm_segment ='F' 
        AND hm_dt = CONVERT(VARCHAR,DATEADD(DAY,@iDateCounter,CAST(@dtToDt AS DATE)),112))
        BEGIN
	      SET @dtToDt =  CONVERT(VARCHAR,DATEADD(DAY,@iDateCounter,@dtToDt),112)
	      GOTO ABC1;
        END
	    SET @iDateCounter = @iDateCounter + 1
      END
      ABC1:
    
	  SET @iNoOfDay = 0
      SET @iDateCounter = 1
    
	
	
	  DECLARE @tbl_BillDate TABLE(BillDate VARCHAR(8))

      INSERT INTO @tbl_BillDate(BillDate) 
	  SELECT DISTINCT fb_billdt FROM FBILLS(NOLOCK)
	  WHERE fb_billdt>=@dtFromDate AND fb_billdt <= @dtToDt
	
      DECLARE @strBillDate varchar(8)=''
      DECLARE db_CursorBillDate CURSOR FOR         
      SELECT distinct BillDate
      FROM @tbl_BillDate X  
	  OPEN db_CursorBillDate       
      FETCH NEXT FROM db_CursorBillDate INTO @strBillDate
      WHILE @@FETCH_STATUS = 0     
      BEGIN
	    DELETE FROM #tbl_ClientPLDETAIL
	  	
	    SET @strString  = @strStringMin+' SELECT  td_companycode, TD_Exchange, TD_Segment, td_clientcd, sm_sname,sm_underlying, td_seriesid,td_expirydt, '
        +' sm_multiplier, trxnDate = ''B/F'', OrderNo = '''', TradeNo = '''', TradeTIME = '''', '
	    +' CASE WHEN SUM(td_bqty - td_sqty) >= 0 THEN SUM(td_bqty - td_sqty) ELSE 0 END AS BuyQty, '
	    +' ABS(CASE WHEN SUM(td_bqty - td_sqty) < 0 THEN SUM(td_bqty - td_sqty) ELSE 0 END) AS SaleQty, '
	    +' MarketRate = (CASE WHEN sum(td_bqty- td_sqty) <> 0 THEN SUM(CASE WHEN TD_BSFlag=''B'' THEN td_bqty*td_rate ELSE td_sqty*td_rate*-1 END)/sum(td_bqty- td_sqty) ELSE 0 END), '
        +' BuyValue = (CASE WHEN SUM(td_bqty - td_sqty) >= 0 THEN SUM(CASE WHEN TD_BSFlag=''B'' THEN td_bqty*td_rate*-1 ELSE td_sqty*td_rate END) ELSE 0 END),  '
	    +' SaleValue = (CASE WHEN SUM(td_bqty - td_sqty) < 0 THEN abs(SUM(CASE WHEN TD_BSFlag=''B'' THEN td_bqty*td_rate*-1 ELSE td_sqty*td_rate END)) ELSE 0 END),  '
	    +' NetValue = SUM(CASE WHEN TD_BSFlag=''B'' THEN td_bqty*td_rate*-1 ELSE td_sqty*td_rate END)'
	    +' FROM Trades (NOLOCK), Series_master(NOLOCK), @tbl_UserList X  '
        +' WHERE  td_dt < '''+@strBillDate+''' '
        +' AND td_clientcd = X.Client_Code '
	    +' AND td_expirydt >= '''+@strBillDate+''' '
        +' AND td_exchange = sm_exchange and td_segment = sm_segment '
        +' and td_seriesid = sm_seriesid '
        +' and sm_expirydt >= '''+@strBillDate +''''
        +' AND (('''+@strConsiderOptionBF+''' = ''N'' AND sm_prodtype NOT IN(''EO'',''CO'',''IO'')) OR '''+@strConsiderOptionBF+''' = ''Y'')'
        +' AND ltrim(rtrim(td_groupid)) <> ''B'' and td_companycode = '''+@strCompanyCode+''' '
	    IF ISNULL(@ExchSeg,'') <> ''
        BEGIN
          SET @strString =   @strString+'  AND td_companycode+td_exchange+td_segment IN(SELECT VALUE FROM  ReturnTable('''+@ExchSeg+''','',''))'
        END	
	
        SET @strString =   @strString+' GROUP BY td_companycode, TD_Exchange, TD_Segment, td_clientcd, sm_sname,sm_underlying, td_seriesid, td_expirydt, sm_multiplier '
        +' HAVING sum(td_bqty - td_sqty) <> 0 '
	    BEGIN TRY
          INSERT INTO #tbl_ClientPLDETAIL(CompanyCode, Exchange, Segment, ClientCode, Scrip, Symbol, seriesid, ExpiryDate, Multiplier, 
		  TrxnDate, OrderNo, TradeNo, TradeTIME, BuyQty, SellQty, MarketRate, BuyValue, SellValue, NetValue)
	      EXEC(@strString)
	    END TRY
	    BEGIN CATCH
	      SET @o_vcErrorFlag  = 'E'
          SET @o_vcErrorMessage = ERROR_MESSAGE()
          RETURN 1
	    END CATCH
  
    
        UPDATE A SET A.MarketRate = ms_prcloseprice, a.BuyValue = (a.BuyQty*a.Multiplier*ms_prcloseprice),
	    A.SellValue = (a.SellQty*a.Multiplier*ms_prcloseprice), 
	    A.NetValue = (a.SellQty*a.Multiplier*ms_prcloseprice)- (a.BuyQty*a.Multiplier*ms_prcloseprice)
        FROM #tbl_ClientPLDETAIL A, Market_summary(NOLOCK), Series_master SR  
        WHERE ms_seriesid = seriesid 
        and ms_exchange = exchange and ms_segment = Segment
        and ms_dt = @strBillDate
	    AND A.seriesid = SR.sm_seriesid

	    IF @strReportType = 'Detail'
	    BEGIN
	      SET @strString  = @strStringMin+' SELECT td_companycode, TD_Exchange, TD_Segment, td_clientcd, sm_sname, sm_underlying, td_seriesid, '
	      +' td_expirydt, sm_multiplier, trxnDate = '''+@strBillDate+''', OrderNo = td_orderid, TradeNo = td_tradeid, TradeTIME = td_time, td_bqty As BuyQty,'
	      +' td_Sqty As SellQty, td_rate As MarketRate,  BuyValue = td_Bqty * td_rate*sm_multiplier, '
	      +' SellValue = td_sqty * td_rate*sm_multiplier, NetValue = (td_sqty -td_bqty) * td_rate*sm_multiplier '
          +' FROM Trades (NOLOCK), Series_master(NOLOCK) , @tbl_UserList X  '
          +' WHERE  td_dt = '''+@strBillDate+''' '
          +' AND td_clientcd = X.Client_Code '
          +' AND td_expirydt >= '''+@strBillDate+''' '
          +' AND td_exchange = sm_exchange and td_segment = sm_segment  '
          +' and td_seriesid = sm_seriesid and td_companycode = '''+@strCompanyCode+''''
          +' AND ltrim(rtrim(td_groupid)) <> ''B'' '
	   
	      IF ISNULL(@ExchSeg,'') <> ''
          BEGIN
            SET @strString =   @strString+'  AND td_companycode+td_exchange+td_segment IN(SELECT VALUE FROM  ReturnTable('''+@ExchSeg+''','',''))'
          END	
	    END
	    ELSE IF @strReportType = 'Summary'
	    BEGIN
	      SET @strString  = @strStringMin+' SELECT td_companycode, TD_Exchange, TD_Segment, td_clientcd, sm_sname, sm_underlying, td_seriesid, '
	      +' td_expirydt, sm_multiplier, trxnDate = '''+@strBillDate+''', OrderNo = '''', TradeNo = '''', TradeTIME = '''', SUM(td_bqty) As BuyQty,'
	      +' SUM(td_Sqty) As SellQty,  (CASE WHEN (SUM(td_bqty)-SUM(td_Sqty))<>0 '
		  +' THEN ROUND(ABS((sum(td_bqty * td_rate*sm_multiplier)- sum(td_Sqty * td_rate*sm_multiplier))/(SUM(td_bqty)-SUM(td_Sqty))),2) ELSE 0 END) '
		  +' As MarketRate,  BuyValue = sum(td_bqty * td_rate*sm_multiplier), '
	      +' SellValue = sum(td_sqty * td_rate*sm_multiplier), NetValue = SUM((td_sqty -td_bqty) * td_rate*sm_multiplier) '
          +' FROM Trades (NOLOCK), Series_master(NOLOCK) , @tbl_UserList X  '
          +' WHERE  td_dt = '''+@strBillDate+''' '
          +' AND td_clientcd = X.Client_Code '
          +' AND td_expirydt >= '''+@strBillDate+''' '
          +' AND td_exchange = sm_exchange and td_segment = sm_segment  '
          +' and td_seriesid = sm_seriesid '
          +' AND ltrim(rtrim(td_groupid)) <> ''B'' and td_companycode = '''+@strCompanyCode+''''
	   
	      IF ISNULL(@ExchSeg,'') <> ''
          BEGIN
            SET @strString =   @strString+'  AND td_companycode+td_exchange+td_segment IN(SELECT VALUE FROM  ReturnTable('''+@ExchSeg+''','',''))'
          END	
		
          SET @strString =   @strString+' GROUP BY td_companycode, TD_Exchange, TD_Segment, td_clientcd, sm_sname,sm_underlying, td_seriesid,td_expirydt, '
	      +' sm_multiplier '
	    END
	  
	
     
	  BEGIN TRY
	    --SELECT @strString
          INSERT INTO #tbl_ClientPLDETAIL(CompanyCode, Exchange, Segment, ClientCode, Scrip, Symbol, seriesid, ExpiryDate, Multiplier, 
		  TrxnDate, OrderNo, TradeNo, TradeTIME, BuyQty, SellQty, MarketRate, BuyValue, SellValue, NetValue)
	      EXEC(@strString)
	    END TRY
	    BEGIN CATCH
	      SET @o_vcErrorFlag  = 'E'
          SET @o_vcErrorMessage = ERROR_MESSAGE()
          RETURN 1
	    END CATCH
    
	    SET @strString  = @strStringMin+'SELECT ex_companycode, ex_Exchange, ex_segment, ex_clientcd, sm_sname, sm_underlying, ex_seriesid, '
        +'	sm_expirydt, sm_multiplier, trxnDate = CASE WHEN SUM(ex_eqty)>0 THEN ''Exerc.'' ELSE ''Assin'' END, OrderNo = '''', TradeNo = '''', TradeTIME = '''', '
	    +' BuyQty = sum(ex_eqty+ex_aqty), SellQty = 0, MarketRate = ex_diffbrokrate, '
	    +' BuyValue = sum((ex_eqty+ex_aqty)*ex_diffbrokrate*sm_multiplier), SellValue = 0, '
        +' NetValue = sum((ex_eqty+ex_aqty)*ex_diffbrokrate*sm_multiplier) '
        +' From Exercise(NOLOCK), Series_master(NOLOCK), @tbl_UserList X  '
        +' WHERE ex_dt = '''+@strBillDate+''' '
        +' and ex_clientcd = X.Client_Code '
        +' and sm_expirydt >= '''+@strBillDate+''' ' 
        +' and ex_exchange = sm_exchange '
        +' and ex_segment = sm_segment And ex_seriesid = sm_seriesid and ex_companycode = '''+@strCompanyCode+''''
	  
	    IF ISNULL(@ExchSeg,'') <> ''
        BEGIN
          SET @strString =   @strString+'  AND ex_companycode+ex_exchange+ex_segment IN(SELECT VALUE FROM  ReturnTable('''+@ExchSeg+''','',''))'
        END	
        SET @strString =   @strString+' GROUP BY ex_companycode, ex_Exchange, ex_segment, ex_clientcd, sm_sname, sm_underlying, ex_seriesid, sm_expirydt'
	    +' , sm_multiplier, ex_diffbrokrate '
	  
    
	    BEGIN TRY
          INSERT INTO #tbl_ClientPLDETAIL(CompanyCode, Exchange, Segment, ClientCode, Scrip, Symbol, seriesid, ExpiryDate, Multiplier, 
		  TrxnDate, OrderNo, TradeNo, TradeTIME, BuyQty, SellQty, MarketRate, BuyValue, SellValue, NetValue)
	      EXEC(@strString)
	    END TRY
	    BEGIN CATCH
	      SET @o_vcErrorFlag  = 'E'
          SET @o_vcErrorMessage = ERROR_MESSAGE()
          RETURN 1
	    END CATCH
	  
	    INSERT INTO #tbl_ClientPLDETAIL(CompanyCode, Exchange, Segment, ClientCode, Scrip, Symbol, seriesid, ExpiryDate, Multiplier, 
	    TrxnDate, OrderNo, TradeNo, TradeTIME, BuyQty, SellQty, MarketRate, BuyValue, SellValue, NetValue)
	    SELECT CompanyCode, Exchange, Segment, ClientCode, Scrip, Symbol, seriesid, ExpiryDate, Multiplier, 
	    TrxnDate = 'C/F', OrderNo = '', TradeNo = '', TradeTIME = '',
	    BuyQty = CASE WHEN SUM(BuyQty-SellQty)<0 THEN SUM(SellQty-BuyQty) ELSE 0 END,
	    SellQty = ABS(CASE WHEN SUM(BuyQty-SellQty)>=0 THEN SUM(BuyQty-SellQty) ELSE 0 END),
	    MarketRate = 0, BuyValue = 0 , SellValue = 0, NetValue = 0
        FROM #tbl_ClientPLDETAIL A, Series_master SR   where A.seriesid = SR.sm_seriesid
	    AND sm_prodtype NOT IN('EO','CO','IO')
        GROUP BY  CompanyCode, Exchange, Segment, ClientCode, Scrip, Symbol, seriesid, ExpiryDate, Multiplier
        HAVING SUM(BuyQty-SellQty) <> 0

	    UPDATE A SET A.BuyValue = ROUND(BuyQty*ms_lastprice*Multiplier,2),
	    A.SellValue = ROUND(SellQty*ms_lastprice*Multiplier,2),
	    A.NetValue = ROUND((SellQty-BuyQty)*ms_lastprice*Multiplier,2),
        MarketRate = ms_lastprice
        FROM #tbl_ClientPLDETAIL A, Market_summary(NOLOCK) X
        WHERE ms_seriesid = seriesid  AND TrxnDate = 'C/F'
        and ms_exchange = exchange and ms_segment = Segment 
        and ms_dt  = (select  max(ms_dt) from Market_summary(NOLOCK)  
	    WHERE ms_exchange = X.ms_exchange and ms_segment = X.ms_segment and ms_dt<=@strBillDate)
	
     
        INSERT INTO #tbl_ClientPLDETAIL(CompanyCode, Exchange, Segment, ClientCode, Scrip, NetValue, TrxnDate)
	    SELECT fc_companycode, fc_Exchange, fc_segment, fc_clientcd, fc_desc, round(sum(fc_amount),2)*-1, TrxnDate = 'Chrg'  
        FROM Fspecialcharges(NOLOCK), (SELECT DISTINCT Client_Code = ClientCode  FROM #tbl_ClientPLDETAIL) X
        where fc_clientcd = x.Client_COde and fc_dt = @strBillDate 
        AND ((fc_companycode+fc_exchange+fc_segment IN(SELECT VALUE FROM ReturnTable(@ExchSeg,',')) and @ExchSeg <> '') OR @ExchSeg = '')
        GROUP BY fc_clientcd, fc_desc,fc_companycode, fc_Exchange, fc_segment
        HAVING ROUND(SUM(fc_amount),2) <> 0
 
        INSERT INTO #tbl_ClientPLDETAIL(CompanyCode, Exchange, Segment, ClientCode, Scrip, NetValue, TrxnDate)
        SELECT fc_companycode, fc_Exchange, fc_segment, fc_clientcd,'SERVICE TAX', round(sum(fc_servicetax),2)*-1, TrxnDate = 'Chrg'
        FROM Fspecialcharges(NOLOCK), (SELECT DISTINCT Client_Code =ClientCode FROM #tbl_ClientPLDETAIL) X
        WHERE fc_clientcd = x.Client_COde
        AND fc_dt= @strBillDate 
        AND ((fc_companycode+fc_exchange+fc_segment IN(SELECT VALUE FROM ReturnTable(@ExchSeg,',')) and @ExchSeg <> '') OR @ExchSeg = '')
         GROUP BY fc_clientcd,fc_desc,fc_companycode, fc_Exchange, fc_segment 
        HAVING ROUND(SUM(fc_servicetax),2) <> 0
	
	    UPDATE A SET BillNo = fb_billno
        FROM #tbl_ClientPLDETAIL A , Fbills WITH (NOLOCK)
        WHERE fb_clientcd = ClientCode
	    AND fb_Segment = 'F'
	    AND fb_billdt = @strBillDate
	  
	    INSERT INTO #tbl_ClientMainPL(BillNo, BillDate, CompanyCode, Exchange, Segment, ClientCode, Scrip, Symbol, seriesid, ExpiryDate, Multiplier, 
	    TrxnDate, OrderNo, TradeNo, TradeTIME, BuyQty, SellQty, MarketRate, BuyValue, SellValue, NetValue)
	    SELECT BillNo,@strBillDate, CompanyCode, Exchange, Segment, ClientCode, Scrip, Symbol, seriesid, ExpiryDate, Multiplier, 
	    TrxnDate, OrderNo, TradeNo, TradeTIME, BuyQty, SellQty, MarketRate, BuyValue, SellValue, NetValue
        FROM #tbl_ClientPLDETAIL order by CompanyCode, Exchange, Segment, ClientCode, 
	    CAST((CASE WHEN TrxnDate='Chrg' THEN 9 ELSE 1 END) AS INT) , 
	    Scrip, Symbol, seriesid, ExpiryDate,
	    CAST((CASE WHEN TrxnDate='b/f' then 1 when TrxnDate='C/F' then 8 
	    when TrxnDate IN('Exerc.','Assin') then 7 else 2 end) as int)
	  
	    FETCH NEXT FROM db_CursorBillDate INTO @strBillDate
      END  
      CLOSE db_CursorBillDate        
      DEALLOCATE db_CursorBillDate	
	
	  UPDATE A SET A.ClientName = CM.cm_name
      FROM #tbl_ClientMainPL A, Client_Master CM
      WHERE A.ClientCode = CM.cm_cd
	  IF @strReportType = 'Detail'
	  BEGIN
	    SELECT CompanyCode, Exchange, Segment, ClientCode, ClientName, BillNo, BillDate, Scrip = ISNULL(Scrip,''), Symbol = isnull(Symbol,''), 
	    seriesid = ISNULL(seriesid,''), ExpiryDate = ISNULL(ExpiryDate,''), 	  TrxnDate, OrderNo = ISNULL(OrderNo,''), TradeNo  =ISNULL(TradeNo,''), TradeTIME = ISNULL(TradeTIME,''), 
	    BuyQty = ISNULL(BuyQty,0), SellQty = ISNULL(SellQty,0), MarketRate = ISNULL(MarketRate,0), 
	    BuyValue = ISNULL(BuyValue,0), SellValue = ISNULL(SellValue,0), NetValue 
	    FROM #tbl_ClientMainPL 
	    ORDER BY SerialNo
	  END
	  ELSE IF @strReportType = 'SUMMARY'
	  BEGIN
	    IF @strOutputType = 'X'
	    BEGIN
	      SET @XMLDATA1 = (SELECT CompanyCode, Exchange, Segment, LTRIM(RTRIM(CES_Exchange))+'-'+LTRIM(RTRIM(CES_SEGMENT)) AS ExchangeSegment, 
		  ClientCode, ClientName, BillNo, BillDate, Scrip = ISNULL(Scrip,''), Symbol = isnull(Symbol,''), 
	      seriesid = ISNULL(seriesid,''), ExpiryDate = ISNULL(ExpiryDate,''), TrxnDate, 
	      BuyQty = ISNULL(BuyQty,0), SellQty = ISNULL(SellQty,0), MarketRate = ISNULL(MarketRate,0), 
	      BuyValue = ISNULL(BuyValue,0), SellValue = ISNULL(SellValue,0), NetValue 
	      FROM #tbl_ClientMainPL , CompanyExchangeSegments(NOLOCK)
		  WHERE CES_CD = CompanyCode+Exchange+Segment
	      ORDER BY SerialNo FOR XML PATH('Bill'))
	      SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
	     -- RETURN 1
	    END
	    ELSE
	    BEGIN
          SELECT CompanyCode, Exchange, Segment, ClientCode, ClientName, BillNo, BillDate, Scrip = ISNULL(Scrip,''), Symbol = isnull(Symbol,''), 
	      seriesid = ISNULL(seriesid,''), ExpiryDate = ISNULL(ExpiryDate,''), TrxnDate, 
	      BuyQty = ISNULL(BuyQty,0), SellQty = ISNULL(SellQty,0), MarketRate = ISNULL(MarketRate,0), 
	      BuyValue = ISNULL(BuyValue,0), SellValue = ISNULL(SellValue,0), NetValue 
	      FROM #tbl_ClientMainPL 
	      ORDER BY SerialNo
	      --RETURN 1
	    END  
	  END
	
      DROP TABLE #tbl_ClientMainPL
	  DROP TABLE #tbl_ClientPLDETAIL
	END
  END
  END TRY
  BEGIN CATCH
    CLOSE db_CursorBillDate        
    DEALLOCATE db_CursorBillDate
	SET @o_vcErrorFlag  = 'E'
    SET @o_vcErrorMessage = ERROR_MESSAGE()
	RETURN 1
  END CATCH
    
  SET @o_vcErrorFlag  = 'S'
  --SET @o_vcErrorMessage = 'Process Completed'
  RETURN 1
END
GO

CREATE PROCEDURE stpr_TypestHeaderProc @strUserid  VARCHAR(100), @strSelection  VARCHAR(100), @strCode VARCHAR(100), 
@strCompanyCode VARCHAR(1), 
@o_Message VARCHAR(MAX) OUTPUT 
WITH ENCRYPTION
AS
BEGIN
  
  DECLARE @strBLAddress1 VARCHAR(200), @strBLAddress2 VARCHAR(200), @strBLAddress3 VARCHAR(200), @strBLAddress4 VARCHAR(200),
  @strDPCode VARCHAR(20)=''
  
  DECLARE @tbl_UserList dbo.UserAccessList;
  
  IF @strSelection = 'DP' AND ISNULL(@strCode,'') <> ''
  BEGIN
    SET @strDPCode = @strCode
	SET @strSelection = ''
	SET @strCode = ''
  END
  
  INSERT INTO @tbl_UserList(clientcode) 
  SELECT * FROM dbo.fn_GetClients(@strUserid, '','')
  
 
  
  DECLARE @XMLDATA XML, @XMLDATA1 XML
 
	
  SET @XMLDATA = (SELECT ClientCode = CASE WHEN @strDPCode <> '' THEN @strDPCode ELSE CM_cD END, 
  [CompanyName] = ISNULL((SELECT EM_NAME FROM Entity_master(NOLOCK) WHERE EM_cD = @strCompanyCode),''),
  [Address1] = ISNULL((SELECT RTRIM(LTRIM(em_add1)) FROM Entity_master(NOLOCK) WHERE EM_cD = @strCompanyCode),''),
  [Address2] = ISNULL((SELECT RTRIM(LTRIM(em_add2)) FROM Entity_master(NOLOCK) WHERE EM_cD = @strCompanyCode),''),
  [Address3] = ISNULL((SELECT RTRIM(LTRIM(em_add3))+' '+RTRIM(LTRIM(em_add4)) FROM Entity_master(NOLOCK) WHERE EM_cD = @strCompanyCode),''),
  [CINNo] = ISNULL((SELECT sp_sysvalue FROM Sysparameter(NOLOCK) WHERE sp_parmcd ='CINNO'),''),  
  [BillingAddress] = ISNULL((SELECT RTRIM(LTRIM(bm_add1))+' '+RTRIM(LTRIM(bm_add2))+' '+RTRIM(LTRIM(bm_add3))+' '+RTRIM(LTRIM(bm_city))+' '+
  RTRIM(LTRIM(bm_pin))+' '+RTRIM(LTRIM(bm_phone)) 
  FROM Branch_master(NOLOCK) WHERE bm_branchcd = cm_brboffcode),''),
  [ReportName] = '##ReportName##',
  [Client] = LTRIM(RTRIM(CM_NAME)),
  [ClientAddress1] = cm_add1, [ClientAddress2] = cm_add2, [ClientAddress3] = cm_add3,
  [ClientCity] = cm_add4, [Clientpin] = cm_pincode, [Telephone] = cm_mobile, 
  [status] = (CASE WHEN cm_freezeyn in('','N') THEN 'Active'  When cm_freezeyn='Y' Then 'Freeze for Trades' ELSE '' END),  
  [Branch] = cm_brboffcode + ' (' + 
  (SELECT bm_branchname FROM Branch_master(NOLOCK) WHERE bm_branchcd = cm_brboffcode) + ')',
  [GroupCode] = cm_groupcd + ' (' + (SELECT gr_desc FROM Group_master(NOLOCK) WHERE gr_cd = cm_groupcd) + ')' ,
  cm_familycd + ' (' + (SELECT fm_desc FROM Family_master(NOLOCK) WHERE fm_cd = cm_familycd ) + ')' AS [Family],
  [Grid1] = '##Grid1##',
  [Grid2] = '##Grid2##',	
  [Grid3] = '##Grid3##',	
  [Grid4] = '##Grid4##',
  [FormatGrid] = '##FormatGrid##',
  [PageOrientation] = '##PageOrientation##',
  [PageSize] = '##PageSize##',
  [FooterModuleName] = 'TradePlus'
  FROM CLIENT_MASTER C, Client_Info(NOLOCK) I,  @tbl_UserList 
  WHERE CM_cD = ClientCode 
  AND CM_cD = cm2_cd
  FOR XML PATH('ClientDetail'))
  SET @o_Message = ''
  SET @o_Message = CAST(@XMLDATA AS VARCHAR(MAX))

  RETURN 1
END
GO

CREATE PROCEDURE stpr_Rpt_CapitalGain @vcXML NVARCHAR(MAX), @o_vcErrorFlag VARCHAR(1) OUTPUT, @o_vcErrorMessage VARCHAR(MAX) OUTPUT
WITH ENCRYPTION
AS
BEGIN
  /*
 ///////////////////////////////////////////////////////////////////////////////////////////
 // Create By     : VAIBHAV GARG
 // Created Date  : 12-DEC-2023
 // Description   : 
 // Reviewed By   : 
 // Review Date   : 
 //////////////////////////////////////////////////////////////////////////////////////////
*/
  DECLARE @dtFromDate VARCHAR(8), @strUserId VARCHAR(50), @strProduct VARCHAR(50), @strOutputType VARCHAR(1) = '', @XMLData XML, 
    @strSelectTag VARCHAR(1) = '', @strSelectUsers VARCHAR(500) = '', @StrString NVARCHAR(MAX) = '', @SQ1 INT = 0, @strSplFilter VARCHAR(
      MAX) = '', @strRepType VARCHAR(50) = '', @dtToDate VARCHAR(8) = '', @strConsider112A VARCHAR(1) = 'N', @strCompanyCode VARCHAR(1), 
    @strRepSubType VARCHAR(50) = '', @xmldata1 XML, @strShowPos VARCHAR(1) = 'Y', @strScripCode VARCHAR(20) = '', @strShortSale VARCHAR
    (1), @strReportDisplay VARCHAR(1) = 'P'

  IF @vcXML = ''
  BEGIN
    SET @o_vcErrorFlag = 'E'
    SET @o_vcErrorMessage = 'Please Send Input Parameter(s)'

    RETURN 1
  END

  SET @XMLData = CAST('<root>' + @vcXML + '</root>' AS XML)

  SELECT @dtFromDate = ISNULL(x.value('(FromDt)[1]', 'VARCHAR(8)'), ''), @strProduct = ISNULL(x.value('(Product)[1]', 
        'VARCHAR(50)'), ''), @dtToDate = ISNULL(x.value('(ToDt)[1]', 'VARCHAR(8)'), ''), @strUserId = ISNULL(x.value(
        '(UserId)[1]', 'VARCHAR(500)'), ''), @strSelectTag = ISNULL(x.value('(SelectTag)[1]', 'VARCHAR(1)'), ''), 
    @strSelectUsers = ISNULL(x.value('(SelectUsers)[1]', 'VARCHAR(500)'), ''), @strOutputType = ISNULL(x.value(
        '(OutputType)[1]', 'VARCHAR(1)'), ''), @strSplFilter = ISNULL(x.value('(SplFilter)[1]', 'VARCHAR(MAX)'), ''), 
    @strRepType = ISNULL(x.value('(RepType)[1]', 'VARCHAR(100)'), ''), @strRepSubType = ISNULL(x.value('(RepSubType)[1]', 
        'VARCHAR(100)'), ''), @strConsider112A = ISNULL(x.value('(Option112A)[1]', 'VARCHAR(1)'), ''), @strShowPos = ISNULL(x.
      value('(POS)[1]', 'VARCHAR(1)'), ''), @strScripCode = ISNULL(x.value('(ScripCode)[1]', 'VARCHAR(20)'), ''), 
    @strCompanyCode = ISNULL(x.value('(CompanyCode)[1]', 'VARCHAR(1)'), ''), @strShortSale = ISNULL(x.value('(ShortSale)[1]', 
        'VARCHAR(20)'), ''), @strReportDisplay = ISNULL(x.value('(ReportDisplay)[1]', 'VARCHAR(1)'), '')
  FROM @XMLData.nodes('/root') AS XTbl(x)

  IF ISNULL(@strReportDisplay, '') = ''
  BEGIN
    SET @strReportDisplay = 'P'
  END

  IF @strRepType = ''
  BEGIN
    SET @strRepType = 'Actual PL_Detail'
  END

  IF @strReportDisplay IN ('D', 'E', 'A', 'X') AND EXISTS (
      SELECT 1
      FROM CLIENT_MASTER(NOLOCK)
      WHERE CM_cD = @strUserId
      )
  BEGIN
    DECLARE @o_Message NVARCHAR(MAX) = ''

    EXEC stpr_TypestHeaderProc @strUserid, '', '', @strCompanyCode, @o_Message OUTPUT

    SET @o_Message = REPLACE(@o_Message, '##ReportName##', 'Security wise Gain / Loss Report for ' + CONVERT(VARCHAR(30), Cast(
            @dtFromDate AS DATE), 103) + ' to ' + CONVERT(VARCHAR(30), Cast(@dtToDate AS DATE), 103))
    SET @o_Message = REPLACE(@o_Message, '##Grid1##', '')
    SET @o_Message = REPLACE(@o_Message, '##Grid2##', '')
    SET @o_Message = REPLACE(@o_Message, '##Grid3##', '')
    SET @o_Message = REPLACE(@o_Message, '##Grid4##', '')

    --SET @o_Message = REPLACE(@o_Message,'##PageOrientation##','Portrait')
    --SET @o_Message = REPLACE(@o_Message,'##PageSize##','A4')
    --SET @o_Message = REPLACE(@o_Message,'##PageOrientation##','Landscape')
    IF @strRepType = 'Actual PL_Detail'
    BEGIN
      SET @o_Message = REPLACE(@o_Message, '##PageOrientation##', 'Landscape')
    END
    ELSE
    BEGIN
      SET @o_Message = REPLACE(@o_Message, '##PageOrientation##', 'Portrait')
    END

    SET @o_Message = REPLACE(@o_Message, '##PageSize##', 'A4')

    IF @strReportDisplay IN ('E', 'D', 'X')
    BEGIN
      SET @o_Message = REPLACE(@o_Message, '##FormatGrid##', 'Grid1')
      SET @strOutputType = 'G'
    END
    ELSE
    BEGIN
      SET @o_Message = REPLACE(@o_Message, '##FormatGrid##', '')
    END

    SET @o_Message = '<root>' + @o_Message + '</root>';

    DECLARE @xmlData3 XML = CAST(@o_Message AS XML);
    DECLARE @DynamicColumns NVARCHAR(MAX);

    SET @DynamicColumns = '';

    WITH DistinctNodes
    AS (
      SELECT DISTINCT NodeName = X.n.value('local-name(.)', 'NVARCHAR(100)')
      FROM @xmlData3.nodes('/root/ClientDetail/*') AS X(n)
      )
    SELECT @DynamicColumns = @DynamicColumns + ',' + 'LTRIM(RTRIM(X1.value(''(' + XX.NodeName + ')[1]'', ''NVARCHAR(MAX)''))) AS [' 
      + XX.NodeName + ']'
    FROM DistinctNodes XX
    WHERE NodeName NOT IN ('Grid2', 'Grid3', 'Grid4')

    SELECT @DynamicColumns = SUBSTRING(@DynamicColumns, 2, LEN(@DynamicColumns) - 1)

    DECLARE @sql NVARCHAR(MAX);

    SET @sql = '
    SELECT ' + @DynamicColumns + '
    FROM @xmlData3.nodes(''/root/ClientDetail'') AS T(X1)';

    EXEC sp_executesql @sql, N'@xmlData3 XML', @xmlData3;

    IF @strReportDisplay NOT IN ('A')
    BEGIN
      SELECT ColumnName, ColumnHeading, ColumnWidth, ColumnAlignement, ColumnFormat, Columnstyle, DecimalPlace, ColumnTotal, 
        ColumnHide = CASE WHEN Userid = '1' THEN 'Y' ELSE 'N' END
      FROM tbl_ReportGridViewFormat(NOLOCK)
      WHERE ReportCode = 'CaptialGain' AND ReportCategroy = @strRepType AND ColumnVisible = '0'
      ORDER BY Orderby
    END
  END

  IF ISNULL(@strScripCode, '') = ''
  BEGIN
    SET @strScripCode = ''
  END

  IF @strShowPos = ''
  BEGIN
    SET @strShowPos = 'Y'
  END

  IF ISNULL(@strConsider112A, '') = ''
  BEGIN
    SET @strConsider112A = 'N'
  END

  DECLARE @strTakingSTTinCOst VARCHAR(1) = 'N'

  SELECT @strTakingSTTinCOst = isnull(sp_sysvalue, 'N')
  FROM SysParameter
  WHERE SP_ParmCd = 'GAINLOSSTTDL'

  DECLARE @tbl_UserList TABLE (Client_Code VARCHAR(50))

  IF @strSplFilter = ''
  BEGIN
    INSERT INTO @tbl_UserList (Client_Code)
    SELECT *
    FROM DBO.[fn_GetClients](@strUserId, @strSelectTag, @strSelectUsers)
  END
  ELSE IF @strSplFilter <> ''
  BEGIN
    SET @StrString = ' SELECT distinct CM_CD FROM Client_master(NOLOCK) WHERE 1 = 1  AND ' + @strSplFilter

    INSERT INTO @tbl_UserList (Client_Code)
    EXEC (@StrString)
  END

  SET @StrString = ''

  DECLARE @strDT1 VARCHAR(20) = CONVERT(VARCHAR(20), DATEADD(DAY, - 1, @dtFromDate), 112), @xmldata2 XML
  DECLARE @vcXML1 NVARCHAR(MAX) = '<FromDt></FromDt><ToDt>' + @strDT1 + '</ToDt><UserId>' + @strUserId + 
    '</UserId><Product></Product>' + 
    '<SelectTag></SelectTag><SelectUsers></SelectUsers><OutputType>X</OutputType><SplFilter>' + @strSplFilter + 
    '</SplFilter><RepType>Notional_Detail</RepType>' + '<RepSubType></RepSubType><Option112A>' + @strConsider112A + 
    '</Option112A><ScripCode>' + @strScripCode + '</ScripCode>'

  SET @vcXML1 = REPLACE(@vcXML1, '''', '''''')
  SET @strString = 'EXEC DBO.stpr_Rpt_CapitalGainNotional' + ' ''' + @vcXML1 + 
    ''', @o_vcErrorFlag OUTPUT, @o_vcErrorMessage OUTPUT';

  EXEC sp_executesql @strString, N'@o_vcErrorFlag VARCHAR(1) OUTPUT, @o_vcErrorMessage VARCHAR(MAX) OUTPUT', @o_vcErrorFlag 
    OUTPUT, @o_vcErrorMessage OUTPUT;

  DECLARE @tbl_OpenPosition TABLE (
    td_SRNO INT, ClientCode VARCHAR(20), ScripCode VARCHAR(20), TradeDate VARCHAR(20), td_Stlmnt VARCHAR(20), BuyQty MONEY, BuyRate 
    MONEY, BuyValue MONEY, SaleQty MONEY, SaleRate MONEY, SaleValue MONEY, STT MONEY, Tmp_RefNo VARCHAR(20), td_Filler1 VARCHAR(20)
    )

  IF @o_vcErrorFlag = 'S'
  BEGIN
    SET @xmldata2 = CAST(@o_vcErrorMessage AS XML)

    INSERT INTO @tbl_OpenPosition (
      td_SRNO, ClientCode, ScripCode, TradeDate, td_Stlmnt, BuyQty, BuyRate, BuyValue, SaleQty, SaleRate, SaleValue, STT, Tmp_RefNo, 
      td_Filler1
      )
    SELECT CapGain.value('(td_SRNO)[1]', 'INT') AS td_SRNO, CapGain.value('(ClientCode)[1]', 'VARCHAR(50)') AS ClientCode, 
      CapGain.value('(ScripCode)[1]', 'VARCHAR(50)') AS ScripCode, ISNULL(CapGain.value('(TradeDate)[1]', 'VARCHAR(20)'), '') 
      AS TradeDate, ISNULL(CapGain.value('(td_Stlmnt)[1]', 'VARCHAR(20)'), '') AS td_Stlmnt, CapGain.value('(BuyQty)[1]', 
        'MONEY') AS BuyQty, CapGain.value('(BuyRate)[1]', 'MONEY') AS BuyRate, CapGain.value('(BuyValue)[1]', 'MONEY') AS BuyValue
      , CapGain.value('(SaleQty)[1]', 'MONEY') AS SaleQty, CapGain.value('(SaleRate)[1]', 'MONEY') AS SaleRate, CapGain.value(
        '(SaleValue)[1]', 'MONEY') AS SaleValue, CapGain.value('(STT)[1]', 'MONEY') AS SaleValue, CapGain.value('(Tmp_RefNo)[1]'
        , 'VARCHAR(20)') AS Tmp_RefNo, CapGain.value('(td_Filler1)[1]', 'VARCHAR(20)') AS td_Filler1
    FROM @xmldata2.nodes('/CapGain') AS XTbl(CapGain)
  END

  SET @o_vcErrorMessage = ''

  CREATE TABLE #tbl_DelvTrxn (
    td_SRNO INT, td_dt VARCHAR(8), td_Stlmnt VARCHAR(20), td_clientcd VARCHAR(20), td_scripcd VARCHAR(20), td_bsflag VARCHAR(1), 
    Qty_SS NUMERIC(19, 6), VALUES_SS NUMERIC(19, 6), Qty_NS NUMERIC(19, 6), VALUES_NS NUMERIC(19, 6), td_Rate NUMERIC(19, 6), FIFONo INT
    , XTAG11 INT, LONG_TAG VARCHAR(1), SQR_TAG VARCHAR(1), Tmp_RefNo NUMERIC, td_Filler1 VARCHAR(20), td_stt MONEY, td_remarks VARCHAR
    (500)
    )

  CREATE TABLE #tbl_DelvTrxn1 (
    td_SRNO INT, td_dt VARCHAR(8), td_Stlmnt VARCHAR(20), td_clientcd VARCHAR(20), td_scripcd VARCHAR(20), td_bsflag VARCHAR(1), 
    Qty_SS NUMERIC(19, 6), VALUES_SS NUMERIC(19, 6), Qty_NS NUMERIC(19, 6), VALUES_NS NUMERIC(19, 6), td_Rate NUMERIC(19, 6), FIFONo INT
    , XTAG11 INT, LONG_TAG VARCHAR(1), SQR_TAG VARCHAR(1), Tmp_RefNo NUMERIC, td_Filler1 VARCHAR(20), td_stt MONEY, td_remarks VARCHAR
    (500)
    )

  CREATE TABLE #tbl_DelvTrxn2 (
    td_SRNO INT, td_dt VARCHAR(8), td_Stlmnt VARCHAR(20), td_clientcd VARCHAR(20), td_scripcd VARCHAR(20), td_bsflag VARCHAR(1), 
    Qty_SS NUMERIC(19, 6), VALUES_SS NUMERIC(19, 6), Qty_NS NUMERIC(19, 6), VALUES_NS NUMERIC(19, 6), td_Rate NUMERIC(19, 6), FIFONo INT
    , XTAG11 INT, LONG_TAG VARCHAR(1), SQR_TAG VARCHAR(1), Tmp_RefNo NUMERIC, td_Filler1 VARCHAR(20), td_stt MONEY, td_remarks VARCHAR
    (500)
    )

  --- MAIN DATA INSERT INTO TEMP TABLE
  BEGIN TRY
    INSERT INTO #tbl_DelvTrxn (
      td_SRNO, td_dt, td_Stlmnt, td_clientcd, td_scripcd, td_bsflag, Qty_SS, VALUES_SS, Qty_NS, VALUES_NS, td_Rate, Tmp_RefNo, 
      td_Filler1, td_stt, td_remarks, FIFONO
      )
    SELECT X.*, FIFONO = ROW_NUMBER() OVER (
        PARTITION BY td_clientcd ORDER BY td_scripcd, CAST(TD_DT AS DATE), td_SRNO
        )
    FROM (
      SELECT *
      FROM (
        /*
	SELECT td_SRNO, td_dt, td_Stlmnt, td_clientcd, td_scripcd, td_bsflag, 
	Qty_SS = CASE WHEN (td_TRDType <> 'DL' OR td_Filler2  = 'T') THEN td_bqty - td_Sqty ELSE 0 END, 
	VALUES_SS = (CASE WHEN (td_TRDType <> 'DL' OR td_Filler2  = 'T') THEN
	(CASE WHEN td_bsflag = 'B' THEN td_Rate + Round(td_ServiceTax + 
					td_OtherChrgs1 + td_OtherChrgs2, 4) ELSE 
					td_Rate - Round(td_ServiceTax + td_OtherChrgs1 + td_OtherChrgs2, 4) END) ELSE 
			0 END) * ABS(CASE WHEN (td_TRDType <> 'DL' OR td_Filler2  = 'T') THEN td_bqty - td_Sqty ELSE 0 END), 
			Qty_NS = ABS(CASE WHEN td_TRDType = 'DL' AND td_Filler2  <> 'T' THEN td_bqty - td_Sqty ELSE 0 END)
		, VALUES_NS = (CASE WHEN td_TRDType = 'DL'  AND td_Filler2  <> 'T' THEN 
		(CASE WHEN td_bsflag = 'B' THEN td_Rate + Round(td_ServiceTax + td_OtherChrgs1 + 
					td_OtherChrgs2, 4) ELSE td_Rate - Round(td_ServiceTax + td_OtherChrgs1 + td_OtherChrgs2, 4) END) ELSE 0 END) * 
					ABS(CASE WHEN td_TRDType = 'DL'   AND td_Filler2  <> 'T' THEN td_bqty - td_Sqty ELSE 0 END), 
				td_Rate = (CASE WHEN td_bsflag = 'B' THEN td_Rate + Round(td_ServiceTax + 
				td_OtherChrgs1 + td_OtherChrgs2, 4) ELSE td_Rate - Round(td_ServiceTax + td_OtherChrgs1 + td_OtherChrgs2, 4) END), td_NFiller2, td_Filler1,
				td_stt
	FROM TRX_INVPL(NOLOCK), Client_master(NOLOCK), Branch_master(NOLOCK)
	WHERE cm_cd = td_clientcd AND cm_brboffcode = bm_branchcd AND td_dt >= @dtFromDate AND td_dt <= @dtToDate --and td_Filler2 <> 'T'
	AND cm_cd IN(SELECT Client_Code from @tbl_UserList) --AND td_scripcd = '519570'
	AND ((td_scripcd = @strScripCode AND @strScripCode <> '') OR @strScripCode = '')
	*/
        SELECT td_SRNO, td_dt = CASE WHEN ISDATE(td_Filler1) = 0 THEN td_dt ELSE td_Filler1 END, td_Stlmnt, td_clientcd, td_scripcd = 
          LTRIM(RTRIM(td_scripcd)), td_bsflag, Qty_SS = CASE WHEN td_Filler2 = 'T' THEN td_bqty - td_Sqty ELSE 0 END, VALUES_SS = (
            CASE WHEN td_Filler2 = 'T' THEN (
                    CASE WHEN td_bsflag = 'B' THEN td_Rate + Round(td_ServiceTax + td_OtherChrgs1 + td_OtherChrgs2 + (CASE WHEN ISNULL(@strTakingSTTinCOst, 'N') = 'Y' THEN td_stt ELSE 0 END
                              ), 4) ELSE td_Rate - Round(td_ServiceTax + td_OtherChrgs1 + td_OtherChrgs2 + (CASE WHEN ISNULL(@strTakingSTTinCOst, 'N') = 'Y' THEN td_stt ELSE 0 END
                            ), 4) END
                    ) ELSE 0 END
            ) * ABS(CASE WHEN td_Filler2 = 'T' THEN td_bqty - td_Sqty ELSE 0 END), Qty_NS = ABS(CASE WHEN td_Filler2 <> 'T' THEN td_bqty - 
                  td_Sqty ELSE 0 END), VALUES_NS = (
            CASE WHEN td_Filler2 <> 'T' THEN (
                    CASE WHEN td_bsflag = 'B' THEN td_Rate + Round(td_ServiceTax + td_OtherChrgs1 + td_OtherChrgs2 + (CASE WHEN ISNULL(@strTakingSTTinCOst, 'N') = 'Y' THEN td_stt ELSE 0 END
                              ), 4) ELSE td_Rate - Round(td_ServiceTax + td_OtherChrgs1 + td_OtherChrgs2 + (CASE WHEN ISNULL(@strTakingSTTinCOst, 'N') = 'Y' THEN td_stt ELSE 0 END
                            ), 4) END
                    ) ELSE 0 END
            ) * ABS(CASE WHEN td_Filler2 <> 'T' THEN td_bqty - td_Sqty ELSE 0 END), td_Rate = (
            CASE WHEN td_bsflag = 'B' THEN td_Rate + Round(td_ServiceTax + td_OtherChrgs1 + td_OtherChrgs2 + (CASE WHEN ISNULL(@strTakingSTTinCOst, 'N') = 'Y' THEN td_stt ELSE 0 END
                      ), 4) ELSE td_Rate - Round(td_ServiceTax + td_OtherChrgs1 + td_OtherChrgs2 + (CASE WHEN ISNULL(@strTakingSTTinCOst, 'N') = 'Y' THEN td_stt ELSE 0 END
                    ), 4) END
            ), td_NFiller2, td_Filler1, td_stt, td_Remark
        FROM TRX_INVPL(NOLOCK), Client_master(NOLOCK)
        WHERE cm_cd = td_clientcd AND td_dt >= @dtFromDate AND td_dt <= @dtToDate --and td_Filler2 <> 'T'
          AND cm_cd IN (
            SELECT Client_Code
            FROM @tbl_UserList
            ) --AND td_scripcd = '542323'
          AND ((td_scripcd = @strScripCode AND @strScripCode <> '') OR @strScripCode = '')
        
        UNION ALL
        
        SELECT td_SRNO, td_dt = CASE WHEN ISDATE(td_Filler1) = 0 THEN TradeDate ELSE td_Filler1 END, td_Stlmnt, td_clientcd = ClientCode, 
          td_scripcd = LTRIM(RTRIM(ScripCode)), td_bsflag = (CASE WHEN BuyQty <> 0 THEN 'B' WHEN SaleQty <> 0 THEN 'S' ELSE '' END
            ), Qty_SS = 0, VALUES_SS = 0, Qty_NS = (CASE WHEN BuyQty <> 0 THEN BuyQty WHEN SaleQty <> 0 THEN SaleQty ELSE 0 END), 
          VALUES_NS = (CASE WHEN BuyQty <> 0 THEN BuyValue WHEN SaleQty <> 0 THEN SaleValue ELSE 0 END), td_Rate = (CASE WHEN BuyQty <> 0 THEN BuyRate WHEN SaleQty <> 0 THEN SaleRate ELSE 0 END
            ), Tmp_RefNo, td_Filler1, td_stt = CASE WHEN (CASE WHEN BuyQty <> 0 THEN BuyQty WHEN SaleQty <> 0 THEN SaleQty ELSE 0 END
                ) <> 0 THEN ROUND(STT / (CASE WHEN BuyQty <> 0 THEN BuyQty WHEN SaleQty <> 0 THEN SaleQty ELSE 0 END), 4) 
            ELSE 0 END, td_remarks = ''
        FROM @tbl_OpenPosition
        ) X1
      ) X
    ORDER BY td_scripcd, CAST(TD_DT AS DATE), td_SRNO
  END TRY

  BEGIN CATCH
    SELECT ERROR_MESSAGE()

    RETURN 1
  END CATCH

  /*
	
  INSERT INTO #tbl_DelvTrxn (
	td_SRNO, td_dt, td_Stlmnt, td_clientcd, td_scripcd, td_bsflag, Qty_SS, VALUES_SS, Qty_NS, VALUES_NS, td_Rate, Tmp_RefNo, td_Filler1, td_stt, 
	FIFONO
	)
  SELECT td_SRNO, TradeDate, td_Stlmnt,  ClientCode, ScripCode, td_bsflag = (CASE WHEN BuyQty <> 0 THEN 'B' WHEN SaleQty <> 0 THEN 'S' ELSE '' END),
  0,0,Qty_NS = (CASE WHEN BuyQty <> 0 THEN BuyQty WHEN SaleQty <> 0 THEN SaleQty ELSE 0 END),
  VALUES_NS = (CASE WHEN BuyQty <> 0 THEN BuyValue WHEN SaleQty <> 0 THEN SaleValue ELSE 0 END),
  td_Rate = (CASE WHEN BuyQty <> 0 THEN BuyRate WHEN SaleQty <> 0 THEN SaleRate ELSE 0 END), Tmp_RefNo = 0,
  td_Filler1 = '', td_stt = 0, FIFONO = 0
  FROM @tbl_OpenPosition
  */
  DECLARE @UPDtd_SRNO INT, @updTmp_RefNo INT, @updtd_clientcd VARCHAR(20) = '', @updtd_scripcd VARCHAR(20) = ''

  DECLARE CursorUpdatedate CURSOR
  FOR
  SELECT td_SRNO, Tmp_RefNo, td_clientcd, td_scripcd
  FROM #tbl_DelvTrxn x
  WHERE Tmp_RefNo > 0

  OPEN CursorUpdatedate

  FETCH NEXT
  FROM CursorUpdatedate
  INTO @UPDtd_SRNO, @updTmp_RefNo, @updtd_clientcd, @updtd_scripcd

  WHILE @@FETCH_STATUS = 0
  BEGIN
    UPDATE A
    SET a.Qty_NS = a.Qty_NS - b.Qty_NS
    FROM #tbl_DelvTrxn A, #tbl_DelvTrxn B
    WHERE A.td_SRNO = @UPDtd_SRNO AND b.td_SRNO = @updTmp_RefNo AND A.td_clientcd = B.td_clientcd AND A.td_scripcd = B.td_scripcd AND B.
      td_clientcd = @updtd_clientcd AND B.td_scripcd = @updtd_scripcd

    DELETE
    FROM #tbl_DelvTrxn
    WHERE td_SRNO = @updTmp_RefNo AND td_clientcd = @updtd_clientcd AND td_scripcd = @updtd_scripcd

    FETCH NEXT
    FROM CursorUpdatedate
    INTO @UPDtd_SRNO, @updTmp_RefNo, @updtd_clientcd, @updtd_scripcd
  END

  CLOSE CursorUpdatedate

  DEALLOCATE CursorUpdatedate

  DELETE
  FROM #tbl_DelvTrxn
  WHERE ISNULL(Qty_NS, 0) = 0 AND ISNULL(Qty_SS, 0) = 0

  UPDATE #tbl_DelvTrxn
  SET td_dt = td_Filler1
  WHERE td_Filler1 NOT IN ('', '0')

  --  DELETE FROM #tbl_DelvTrxn WHERE td_Filler1 NOT IN('','0') AND td_remarks Like 'Split%' and td_bsflag ='S'
  CREATE INDEX indx_DelvTrxn ON #tbl_DelvTrxn (td_clientcd, td_scripcd, td_SRNO, FIFONO)

  CREATE INDEX indx_DelvTrxn1 ON #tbl_DelvTrxn1 (td_clientcd, td_scripcd, td_SRNO, FIFONO)

  INSERT INTO #tbl_DelvTrxn2 (
    td_SRNO, td_dt, td_Stlmnt, td_clientcd, td_scripcd, td_bsflag, Qty_NS, td_Rate, VALUES_NS, FIFONO, XTAG11, LONG_TAG, SQR_TAG, 
    TD_STT
    )
  SELECT td_SRNO, td_dt, td_Stlmnt, td_clientcd, td_scripcd, td_bsflag, Qty_NS, td_Rate, VALUES_NS, FIFONO, ISNULL(XTAG11, 0), ISNULL
    (LONG_TAG, ''), ISNULL(SQR_TAG, ''), TD_STT
  FROM #tbl_DelvTrxn X
  WHERE TD_DT < (
      SELECT MIN(TD_DT)
      FROM #tbl_DelvTrxn
      WHERE td_clientcd = X.td_clientcd AND td_scripcd = X.td_scripcd AND td_bsflag = 'B' AND Qty_NS <> 0
      ) AND td_bsflag = 'S' AND Qty_NS <> 0

  DELETE
  FROM #tbl_DelvTrxn
  WHERE td_SRNO IN (
      SELECT td_SRNO
      FROM #tbl_DelvTrxn2
      )

  DECLARE @SQR_QTY MONEY = 0, @SQR_QTY1 MONEY = 0, @td_clientcdC1 VARCHAR(10) = '', @td_scripcdC1 VARCHAR(10) = '', @td_BuyQtyC1 MONEY = 0, 
    @td_SaleQtyC1 MONEY = 0, @COUNTER INT = 0, @td_SRNOB INT, @td_dtB VARCHAR(8), @td_StlmntB VARCHAR(20), @td_clientcdB VARCHAR(50), 
    @td_scripcdB VARCHAR(50), @td_bsflagB VARCHAR(1), @QTY_NSB MONEY, @td_RateB NUMERIC(19, 6), @VALUES_NSB NUMERIC(19, 6), 
    @td_SRNOS INT, @td_dtS VARCHAR(8), @td_StlmntS VARCHAR(20) = '', @td_clientcdS VARCHAR(50), @td_scripcdS VARCHAR(50), 
    @td_bsflagS VARCHAR(1), @QTY_NSS MONEY, @td_RateS NUMERIC(19, 6), @buyQty MONEY = 0, @SaleQty MONEY = 0, @BQTY MONEY = 0, @SQTY MONEY = 0, 
    @VALUES_NSS NUMERIC(19, 6), @FIFONOB INT, @FIFONOS INT, @SQ MONEY = 0, @TAG VARCHAR(1) = 'C', @strFlag VARCHAR(1) = 'N', @strsaleflag 
    VARCHAR(1) = '', @TD_STTB MONEY, @TD_STTS MONEY

  DECLARE CursorC1Main CURSOR
  FOR
  SELECT td_clientcd, td_scripcd, SUM(CASE WHEN td_bsflag = 'B' THEN Qty_NS ELSE 0 END) BuyQty, SUM(CASE WHEN td_bsflag = 'S' THEN Qty_NS 
        ELSE 0 END) SaleQty
  FROM #tbl_DelvTrxn x
  GROUP BY td_clientcd, td_scripcd
  HAVING SUM(CASE WHEN td_bsflag = 'B' THEN Qty_NS ELSE 0 END) <> 0 AND SUM(CASE WHEN td_bsflag = 'S' THEN Qty_NS ELSE 0 END) <> 0

  OPEN CursorC1Main

  FETCH NEXT
  FROM CursorC1Main
  INTO @td_clientcdC1, @td_scripcdC1, @td_BuyQtyC1, @td_SaleQtyC1

  WHILE @@FETCH_STATUS = 0
  BEGIN
    IF SIGN(@td_BuyQtyC1 - @td_SaleQtyC1) <> 1
    BEGIN
      SET @SQR_QTY = @td_BuyQtyC1
      SET @SQR_QTY1 = @td_BuyQtyC1
      SET @strsaleflag = 'B'
    END
    ELSE
    BEGIN
      SET @SQR_QTY = @td_SaleQtyC1
      SET @SQR_QTY1 = @td_SaleQtyC1
      SET @strsaleflag = 'S'
    END

    IF @td_BuyQtyC1 = @td_SaleQtyC1
    BEGIN
      SET @strsaleflag = 'S'
    END

    DECLARE CursorBMain CURSOR
    FOR
    SELECT td_SRNO, td_dt, td_Stlmnt, td_clientcd, td_scripcd, td_bsflag, Qty_NS, td_Rate, VALUES_NS, FIFONO, TD_STT
    FROM #tbl_DelvTrxn
    WHERE td_clientcd = @td_clientcdC1 AND td_scripcd = @td_scripcdC1 AND td_bsflag = 'B' AND Qty_NS <> 0 AND isnull(SQR_TAG, '') = ''
    ORDER BY td_clientcd, td_scripcd, FIFONO, td_SRNO

    DECLARE CursorSMain CURSOR
    FOR
    SELECT td_SRNO, td_dt, td_Stlmnt, td_clientcd, td_scripcd, td_bsflag, Qty_NS, td_Rate, VALUES_NS, FIFONO, TD_STT
    FROM #tbl_DelvTrxn
    WHERE td_clientcd = @td_clientcdC1 AND td_scripcd = @td_scripcdC1 AND td_bsflag = 'S' AND Qty_NS <> 0 AND isnull(SQR_TAG, '') = ''
    ORDER BY td_clientcd, td_scripcd, FIFONO, td_SRNO

    OPEN CursorBMain

    OPEN CursorSMain

    WHILE @@FETCH_STATUS = 0
    BEGIN
      SET @COUNTER = @COUNTER + 1

      IF @SQR_QTY <> 0
      BEGIN
        IF @BQTY = 0
        BEGIN
          FETCH NEXT
          FROM CursorBMain
          INTO @td_SRNOB, @td_dtB, @td_StlmntB, @td_clientcdB, @td_scripcdB, @td_bsflagB, @Qty_NSB, @td_RateB, @VALUES_NSB, 
            @FIFONOB, @TD_STTB

          SET @BQTY = @Qty_NSB
        END
      END

      IF @SQR_QTY1 <> 0
      BEGIN
        IF @SQTY = 0 OR (@td_dtS < @td_dtB AND @SQTY > 0)
        BEGIN
          IF @SQTY > 0 --AND @td_dtS < @td_dtB
          BEGIN
            INSERT INTO #tbl_DelvTrxn2 (
              td_SRNO, td_dt, td_Stlmnt, td_clientcd, td_scripcd, td_bsflag, Qty_NS, td_Rate, VALUES_NS, FIFONO, XTAG11, LONG_TAG, 
              SQR_TAG, TD_STT
              )
            VALUES (
              @td_SRNOS, @td_dtS, @td_StlmntS, @td_clientcdS, @td_scripcdS, @td_bsflagS, @SQTY, @td_RateS, @SQTY * @td_RateS, 
              @FIFONOS, @COUNTER, 'X', '', @TD_STTS
              )

            UPDATE #tbl_DelvTrxn
            SET SQR_TAG = @TAG
            WHERE td_clientcd = @td_clientcdS AND FIFONO = @FIFONOS

            IF @strsaleflag = 'S'
            BEGIN
              SET @SQR_QTY1 = @SQR_QTY1 - @SQTY
              SET @SQR_QTY = @SQR_QTY - @SQTY
            END

            SET @SQTY = 0
            SET @strFlag = 'Y'
          END

          FETCH NEXT
          FROM CursorSMain
          INTO @td_SRNOS, @td_dtS, @td_StlmntS, @td_clientcdS, @td_scripcdS, @td_bsflagS, @Qty_NSS, @td_RateS, @VALUES_NSS, 
            @FIFONOS, @TD_STTS

          IF @td_dtS >= @td_dtB
          BEGIN
            SET @SQTY = @Qty_NSS
          END
          ELSE
          BEGIN
            IF @Qty_NSS > 0 --AND @td_dtS < @td_dtB
            BEGIN
              SET @SQTY = @Qty_NSS

              IF @strsaleflag = 'S'
              BEGIN
                SET @SQR_QTY1 = @SQR_QTY1 - @Qty_NSS
                SET @SQR_QTY = @SQR_QTY - @Qty_NSS
              END

              IF @SQR_QTY > 0
              BEGIN
                INSERT INTO #tbl_DelvTrxn2 (
                  td_SRNO, td_dt, td_Stlmnt, td_clientcd, td_scripcd, td_bsflag, Qty_NS, td_Rate, VALUES_NS, FIFONO, XTAG11, 
                  LONG_TAG, SQR_TAG, TD_STT
                  )
                VALUES (
                  @td_SRNOS, @td_dtS, @td_StlmntS, @td_clientcdS, @td_scripcdS, @td_bsflagS, @Qty_NSS, @td_RateS, @Qty_NSS * 
                  @td_RateS, @FIFONOS, @COUNTER, 'L', '', @TD_STTS
                  )
              END

              SET @SQTY = 0
              SET @Qty_NSS = 0

              UPDATE #tbl_DelvTrxn
              SET SQR_TAG = @TAG
              WHERE td_clientcd = @td_clientcdS AND FIFONO = @FIFONOS

              SET @strFlag = 'Y'
            END
          END
        END
      END

      IF @BQTY >= @SQTY
      BEGIN
        IF @BQTY > 0
        BEGIN
          SET @SQ = @SQTY
        END
      END
      ELSE
      BEGIN
        IF @SQTY > 0
        BEGIN
          SET @SQ = @BQTY
        END
      END

      IF @strFlag = 'Y'
      BEGIN
        --SELECT @SQ
        SET @SQ = 0
        SET @strFlag = 'N'
      END

      INSERT INTO #tbl_DelvTrxn1 (
        td_SRNO, td_dt, td_Stlmnt, td_clientcd, td_scripcd, td_bsflag, Qty_NS, td_Rate, VALUES_NS, FIFONO, XTAG11, LONG_TAG, SQR_TAG
        , TD_STT
        )
      VALUES (
        @td_SRNOB, @td_dtB, @td_StlmntB, @td_clientcdB, @td_scripcdB, @td_bsflagB, @SQ, @td_RateB, @SQ * @td_RateB, @FIFONOB, 
        @COUNTER, (CASE WHEN SIGN(ABS(DATEDIFF(DAY, CAST(@td_dtB AS DATE), CAST(@td_dtS AS DATE))) - 365) = 1 THEN 'L' ELSE '' END
          ), 'Y', @TD_STTB
        )

      SET @BQTY = @BQTY - @SQ

      INSERT INTO #tbl_DelvTrxn1 (
        td_SRNO, td_dt, td_Stlmnt, td_clientcd, td_scripcd, td_bsflag, Qty_NS, td_Rate, VALUES_NS, FIFONO, XTAG11, LONG_TAG, SQR_TAG
        , TD_STT
        )
      VALUES (
        @td_SRNOS, @td_dtS, @td_StlmntS, @td_clientcdS, @td_scripcdS, @td_bsflagS, @SQ, @td_RateS, @SQ * @td_RateS, @FIFONOS, 
        @COUNTER, (CASE WHEN SIGN(ABS(DATEDIFF(DAY, CAST(@td_dtB AS DATE), CAST(@td_dtS AS DATE))) - 365) = 1 THEN 'L' ELSE '' END
          ), 'Y', @TD_STTS
        )

      SET @SQTY = @SQTY - @SQ

      --ABD:
      IF @BQTY = 0
      BEGIN
        UPDATE #tbl_DelvTrxn
        SET SQR_TAG = @TAG
        WHERE td_clientcd = @td_clientcdB AND FIFONO = @FIFONOB
      END

      IF @SQTY = 0
      BEGIN
        UPDATE #tbl_DelvTrxn
        SET SQR_TAG = @TAG
        WHERE td_clientcd = @td_clientcdS AND FIFONO = @FIFONOS
      END

      SET @SQR_QTY1 = @SQR_QTY1 - @SQ
      SET @SQR_QTY = @SQR_QTY - @SQ
      SET @strFlag = 'N'

      --SELECT 'VAG',@SQ, @SQR_QTY, @BQTY, @SQTY, @FIFONOB, @FIFONOS
      IF (@SQR_QTY1 = 0 AND @SQR_QTY = 0)
      BEGIN
        BREAK;
      END
    END

    CLOSE CursorBMain;

    CLOSE CursorSMain;

    DEALLOCATE CursorBMain;

    DEALLOCATE CursorSMain;

    IF @BQTY <> 0
    BEGIN
      INSERT INTO #tbl_DelvTrxn1 (
        td_SRNO, td_dt, td_Stlmnt, td_clientcd, td_scripcd, td_bsflag, Qty_NS, td_Rate, VALUES_NS, FIFONO, XTAG11, LONG_TAG, SQR_TAG
        , TD_STT
        )
      VALUES (
        @td_SRNOB, @td_dtB, @td_StlmntB, @td_clientcdB, @td_scripcdB, @td_bsflagB, @BQTY, @td_RateB, @BQTY * @td_RateB, @FIFONOB, 
        @COUNTER, '', '', @TD_STTB
        )

      UPDATE #tbl_DelvTrxn
      SET SQR_TAG = @TAG
      WHERE td_clientcd = @td_clientcdB AND FIFONO = @FIFONOB
    END

    IF @SQTY <> 0
    BEGIN
      INSERT INTO #tbl_DelvTrxn1 (
        td_SRNO, td_dt, td_Stlmnt, td_clientcd, td_scripcd, td_bsflag, Qty_NS, td_Rate, VALUES_NS, FIFONO, XTAG11, LONG_TAG, SQR_TAG
        , TD_STT
        )
      VALUES (
        @td_SRNOS, @td_dtS, @td_StlmntS, @td_clientcdS, @td_scripcdS, @td_bsflagS, @SQTY, @td_RateS, @SQTY * @td_RateS, @FIFONOS, 
        @COUNTER, '', '', @TD_STTS
        )

      UPDATE #tbl_DelvTrxn
      SET SQR_TAG = @TAG
      WHERE td_clientcd = @td_clientcdS AND FIFONO = @FIFONOS
    END

    SET @SQ = 0
    SET @BQTY = 0
    SET @SQTY = 0
    SET @SQR_QTY = 0
    SET @SQR_QTY1 = 0

    FETCH NEXT
    FROM CursorC1Main
    INTO @td_clientcdC1, @td_scripcdC1, @td_BuyQtyC1, @td_SaleQtyC1
  END

  CLOSE CursorC1Main

  DEALLOCATE CursorC1Main

  DELETE
  FROM #tbl_DelvTrxn
  WHERE SQR_TAG = 'C'

  INSERT INTO #tbl_DelvTrxn
  SELECT *
  FROM #tbl_DelvTrxn1
  WHERE ISNULL(Qty_SS, 0) + isnull(Qty_NS, 0) <> 0

  --SELECT * FROM #tbl_DelvTrxn WHERE  td_scripcd = '533326'
  --- INSERT DELIVERY TRXN
  CREATE TABLE #tbl_Rep (
    Tag VARCHAR(50), ClientCode VARCHAR(50), CLientName VARCHAR(100), Scrip_Code VARCHAR(50), ScripName VARCHAR(200), ISIN VARCHAR(
      20), XTAG11 INT, BuyDate VARCHAR(20), BuyQty NUMERIC(19, 6), BuyRate NUMERIC(19, 6), BuyValue NUMERIC(19, 6), SaleDate VARCHAR(20
    ), SaleQty NUMERIC(19, 6), SaleRate NUMERIC(19, 6), SaleValue NUMERIC(19, 6), DAYS INT, S_TERM_PL MONEY, L_TERM_PL MONEY, SP_TERM_PL 
    MONEY, NetQty MONEY, NetValue MONEY, CMP MONEY, NOT_PL MONEY, BuySTT MONEY, SaleSTT MONEY, Tmp_112ARate MONEY, T112AFlag VARCHAR(1) 
    NOT NULL DEFAULT 'N', BuyBackFlag VARCHAR(1)
    )

  INSERT INTO #tbl_Rep (Tag, ClientCode, Scrip_Code, XTAG11, BuyDate, BuyQty, BuyRate, BuyValue, BuySTT)
  SELECT Tag = 'Delivery Trxn', CLIENT_CODE, SCRIP_CODE, XTAG11, CONVERT(VARCHAR, MAX(cast(BOT_TRXN_DATE AS DATE)), 106) 
    BOT_TRXN_DATE, SUM(BOT_QTY) BOT_QTY, cast((CASE WHEN SUM(BOT_QTY) = 0 THEN 0 ELSE ROUND(SUM(BOT_VALUE) / SUM(BOT_QTY), 6) END
        ) AS NUMERIC(19, 6)) AS BOT_MKT_RATE, SUM(BOT_VALUE) BOT_VALUE, SUM(abs(BOT_QTY) * TD_STT) AS BuySTT
  FROM (
    SELECT td_clientcd AS Client_Code, SCRIP_CODE = td_scripcd, XTAG11, td_dt AS BOT_TRXN_DATE, QTY_NS BOT_QTY, td_Rate BOT_MKT_RATE, 
      cast(VALUES_NS AS NUMERIC(19, 6)) BOT_VALUE, TD_STT
    FROM #tbl_DelvTrxn
    WHERE td_bsflag = 'B' AND isnull(SQR_TAG, 'N') = 'Y'
    ) X123
  GROUP BY CLIENT_CODE, SCRIP_CODE, XTAG11

  --- UPDATE SALE TRANSACTION
  UPDATE A
  SET A.SaleQty = B.BOT_QTY, A.SaleRate = B.BOT_MKT_RATE, A.SaleDATE = B.BOT_TRXN_DATE, A.SaleValue = B.BOT_VALUE, A.SaleSTT = B.BuySTT
    , A.BuyBackFlag = B.BuyBackFlag
  FROM #tbl_Rep A, (
      SELECT CLIENT_CODE, SCRIP_CODE, XTAG11, CONVERT(VARCHAR, MAX(cast(BOT_TRXN_DATE AS DATE)), 106) BOT_TRXN_DATE, SUM(BOT_QTY) 
        BOT_QTY, (CASE WHEN SUM(BOT_QTY) = 0 THEN 0 ELSE ROUND(SUM(BOT_VALUE) / SUM(BOT_QTY), 6) END) AS BOT_MKT_RATE, SUM(
          BOT_VALUE) BOT_VALUE, SUM(abs(BOT_QTY) * TD_STT) AS BuySTT, BuyBackFlag
      FROM (
        SELECT td_clientcd AS Client_Code, SCRIP_CODE = td_scripcd, XTAG11, td_dt AS BOT_TRXN_DATE, QTY_NS BOT_QTY, td_Rate 
          BOT_MKT_RATE, VALUES_NS BOT_VALUE, TD_STT, BuyBackFlag = CASE WHEN se_type = 'T' THEN 'Y' ELSE 'N' END
        FROM #tbl_DelvTrxn
        LEFT OUTER JOIN Settlements(NOLOCK) SETT ON (td_Stlmnt = se_stlmnt)
        WHERE td_bsflag = 'S' AND isnull(SQR_TAG, 'N') = 'Y'
        ) X123
      GROUP BY CLIENT_CODE, SCRIP_CODE, XTAG11, BuyBackFlag
      ) b
  WHERE A.ClientCode = b.Client_Code AND a.Scrip_Code = b.SCRIP_CODE AND a.XTAG11 = b.XTAG11

  --- INSERT Spacu TRXN
  INSERT INTO #tbl_Rep (Tag, ClientCode, Scrip_Code, XTAG11, BuyDate, BuyQty, BuyRate, BuyValue, SaleDate, SaleQty, SaleRate, SaleValue, BuySTT, SaleSTT
    )
  SELECT 'Spacu Trxn' XTAG111, CLIENT_CODE = td_clientcd, SCRIP_CODE = td_scripcd, XTAG11, (CASE WHEN td_bsflag = 'B' THEN td_dt ELSE '' END
      ) AS BOT_TRXN_DATE, SUM(CASE WHEN td_bsflag = 'B' THEN QTY_SS ELSE 0 END) BOT_QTY, (
      CASE WHEN SUM(CASE WHEN td_bsflag = 'B' THEN QTY_SS ELSE 0 END) <> 0 THEN ROUND(SUM(CASE WHEN td_bsflag = 'B' THEN VALUES_SS ELSE 0 END) / 
              SUM(CASE WHEN td_bsflag = 'B' THEN QTY_SS ELSE 0 END), 2) ELSE 0 END
      ) BOT_MKT_RATE, SUM(CASE WHEN td_bsflag = 'B' THEN VALUES_SS ELSE 0 END) BOT_VALUE, SaleDate = '01/01/1900', SaleQty = 0, SaleRate = 0, 
    SaleValue = 0, BuySTT = SUM(CASE WHEN td_bsflag = 'B' THEN abs(QTY_SS) * TD_STT ELSE 0 END), SaleSTT = 0
  FROM #tbl_DelvTrxn
  WHERE ISNULL(QTY_SS, 0) <> 0 AND td_bsflag = 'B'
  GROUP BY td_clientcd, td_scripcd, td_bsflag, td_dt, XTAG11

  --- UPDATE SALE TRXN
  UPDATE A
  SET a.SaleQty = B.BOT_QTY, A.SaleRate = B.BOT_MKT_RATE, A.SaleDATE = B.BOT_TRXN_DATE, A.SaleValue = B.BOT_VALUE, A.SaleSTT = B.
    SaleSTT
  FROM #tbl_Rep A, (
      SELECT CLIENT_CODE, SCRIP_CODE, XTAG11, cast(BOT_TRXN_DATE AS DATE) BOT_TRXN_DATE, SUM(BOT_QTY) BOT_QTY, cast((CASE WHEN SUM(BOT_QTY) = 0 THEN 0 ELSE ROUND(SUM(BOT_VALUE) / SUM(BOT_QTY), 6) END
            ) AS NUMERIC(19, 6)) BOT_MKT_RATE, SUM(BOT_VALUE) BOT_VALUE, SaleSTT = SUM(abs(BOT_QTY) * TD_STT)
      FROM (
        SELECT td_clientcd AS Client_Code, SCRIP_CODE = td_scripcd, XTAG11, td_dt AS BOT_TRXN_DATE, QTY_SS BOT_QTY, td_Rate 
          BOT_MKT_RATE, cast(VALUES_SS AS NUMERIC(19, 6)) BOT_VALUE, TD_STT
        FROM #tbl_DelvTrxn
        WHERE td_bsflag = 'S' AND ISNULL(QTY_SS, 0) <> 0
        ) X123
      GROUP BY CLIENT_CODE, SCRIP_CODE, XTAG11, cast(BOT_TRXN_DATE AS DATE)
      ) b
  WHERE A.ClientCode = b.Client_Code AND a.Scrip_Code = b.SCRIP_CODE AND a.BuyDate = b.BOT_TRXN_DATE AND Tag = 'Spacu Trxn'

  --- INSERT DELIVERY NOT SQR UP TRXN 	
  /*	
  INSERT INTO #tbl_Rep (
	Tag, ClientCode, Scrip_Code, XTAG11, BuyDate, BuyQty, BuyRate, BuyValue, SaleDate, SaleQty, SaleRate, 
	SaleValue, BuySTT, SaleSTT
	)
  SELECT XTAG111, CLIENT_CODE, SCRIP_CODE, XTAG11 = 0, convert(VARCHAR, CAST(BOT_TRXN_DATE AS DATE), 106) 
	BOT_TRXN_DATE, SUM(BOT_QTY) BOT_QTY, (CASE WHEN SUM(BOT_QTY) = 0 THEN 0 ELSE ROUND(SUM(BOT_VALUE) / SUM(BOT_QTY), 4) END) 
	BOT_MKT_RATE, SUM(BOT_VALUE) BOT_VALUE, convert(VARCHAR, CAST(SOLD_TRXN_DATE AS DATE), 106) SOLD_TRXN_DATE, 
	SUM(SOLD_QTY) SOLD_QTY, 
	(CASE WHEN SUM(SOLD_QTY) = 0 THEN 0 ELSE ROUND(SUM(SOLD_VALUE) / SUM(SOLD_QTY), 4) END) SOLD_MKT_RATE, 
	SUM(SOLD_VALUE) SOLD_VALUE, SUM(BuySTT) AS BuySTT, SUM(SaleSTT) AS SaleSTT
  FROM (
	SELECT 'Delivery Trxn' XTAG111, CLIENT_CODE = td_clientcd, SCRIP_CODE = td_scripcd, XTAG11, 
	CASE WHEN td_bsflag = 'B' THEN td_dt ELSE '19000101' END BOT_TRXN_DATE, 
		(CASE WHEN td_bsflag = 'B' THEN QTY_NS ELSE 0 END) BOT_QTY, 
		(CASE WHEN td_bsflag = 'B' THEN td_Rate ELSE 0 END) BOT_MKT_RATE, 
		(CASE WHEN td_bsflag = 'B' THEN VALUES_NS ELSE 0 END) BOT_VALUE, 
		(CASE WHEN td_bsflag = 'S' THEN td_dt ELSE '19000101' END) SOLD_TRXN_DATE, 
		(CASE WHEN td_bsflag = 'S' THEN QTY_NS ELSE 0 END) AS SOLD_QTY, 
		(CASE WHEN td_bsflag = 'S' THEN td_Rate ELSE  0 END) AS SOLD_MKT_RATE, 
		(CASE WHEN td_bsflag = 'S' THEN  VALUES_NS ELSE  0 END) AS SOLD_VALUE, 
			BuySTT =  (CASE WHEN td_bsflag = 'B' THEN td_stt ELSE 0 END),
			SaleSTT =  (CASE WHEN td_bsflag = 'S' THEN td_stt ELSE 0 END)
	FROM #tbl_DelvTrxn
	WHERE ISNULL(SQR_TAG, 'N') = 'N' AND ISNULL(QTY_NS, 0) <> 0 AND td_bsflag <> 'S'
	) x1
  GROUP BY XTAG111, CLIENT_CODE, SCRIP_CODE, convert(VARCHAR, cast(BOT_TRXN_DATE AS DATE), 106), convert(VARCHAR
		, cast(SOLD_TRXN_DATE AS DATE), 106)
  ORDER BY CLIENT_CODE, BOT_TRXN_DATE, SOLD_TRXN_DATE
 */
  -- INSERT SHORT SALES
  INSERT INTO #tbl_Rep (Tag, ClientCode, Scrip_Code, XTAG11, BuyDate, BuyQty, BuyRate, BuyValue, SaleDate, SaleQty, SaleRate, SaleValue, BuySTT, SaleSTT
    )
  SELECT XTAG111, CLIENT_CODE, SCRIP_CODE, XTAG11 = 0, convert(VARCHAR, CAST(BOT_TRXN_DATE AS DATE), 106) BOT_TRXN_DATE, SUM(BOT_QTY) 
    BOT_QTY, (CASE WHEN SUM(BOT_QTY) = 0 THEN 0 ELSE round(SUM(BOT_VALUE) / SUM(BOT_QTY), 6) END) AS BOT_MKT_RATE, SUM(BOT_VALUE) 
    BOT_VALUE, convert(VARCHAR, CAST(SOLD_TRXN_DATE AS DATE), 106) SOLD_TRXN_DATE, SUM(SOLD_QTY) SOLD_QTY, (CASE WHEN SUM(SOLD_QTY) = 0 THEN 0 ELSE round(SUM(SOLD_VALUE) / SUM(SOLD_QTY), 6) END
      ) SOLD_MKT_RATE, SUM(SOLD_VALUE) SOLD_VALUE, SUM(BuySTT) AS BuySTT, SUM(SaleSTT) AS SaleSTT
  FROM (
    SELECT 'Short Sale' XTAG111, CLIENT_CODE = td_clientcd, SCRIP_CODE = td_scripcd, XTAG11, (CASE WHEN td_bsflag = 'B' THEN td_dt ELSE '19000101' END
        ) BOT_TRXN_DATE, (CASE WHEN td_bsflag = 'B' THEN QTY_NS ELSE 0 END) BOT_QTY, (CASE WHEN td_bsflag = 'B' THEN td_Rate ELSE 0 END
        ) AS BOT_MKT_RATE, (CASE WHEN td_bsflag = 'B' THEN VALUES_NS ELSE 0 END) AS BOT_VALUE, (CASE WHEN td_bsflag = 'S' THEN td_dt ELSE '19000101' END
        ) AS SOLD_TRXN_DATE, (CASE WHEN td_bsflag = 'S' THEN QTY_NS ELSE 0 END) AS SOLD_QTY, (CASE WHEN td_bsflag = 'S' THEN td_Rate ELSE 0 END
        ) AS SOLD_MKT_RATE, (CASE WHEN td_bsflag = 'S' THEN VALUES_NS ELSE 0 END) AS SOLD_VALUE, BuySTT = (CASE WHEN td_bsflag = 'B' THEN td_stt ELSE 0 END
        ), SaleSTT = (CASE WHEN td_bsflag = 'S' THEN td_stt ELSE 0 END)
    FROM #tbl_DelvTrxn2
    WHERE ISNULL(QTY_NS, 0) <> 0
    ) x1
  GROUP BY XTAG111, CLIENT_CODE, SCRIP_CODE, convert(VARCHAR, cast(BOT_TRXN_DATE AS DATE), 106), convert(VARCHAR, cast(
        SOLD_TRXN_DATE AS DATE), 106)
  ORDER BY CLIENT_CODE, BOT_TRXN_DATE, SOLD_TRXN_DATE

  INSERT INTO #tbl_Rep (
    Tag, ClientCode, Scrip_Code, XTAG11, SaleDate, SaleQty, SaleRate, SaleValue, BuyDate, BuyQty, BuyRate, BuyValue, BuySTT, SaleSTT, 
    BuyBackFlag
    )
  SELECT Tag = 'Short Sale', CLIENT_CODE, SCRIP_CODE, XTAG11, CONVERT(VARCHAR, MAX(cast(BOT_TRXN_DATE AS DATE)), 106) BOT_TRXN_DATE, 
    SUM(BOT_QTY) BOT_QTY, (CASE WHEN SUM(BOT_QTY) = 0 THEN 0 ELSE round(SUM(BOT_VALUE) / SUM(BOT_QTY), 6) END) BOT_MKT_RATE, SUM(
      BOT_VALUE) BOT_VALUE, BuyDate = '01-JAN-1900', BuyQty = 0, BuyRate = 0, BuyValue = 0, BuySTT = 0, SaleSTT = SUM(abs(BOT_QTY) * TD_STT), 
    BuyBackFlag
  FROM (
    SELECT td_clientcd AS Client_Code, SCRIP_CODE = td_scripcd, XTAG11, td_dt AS BOT_TRXN_DATE, QTY_NS BOT_QTY, td_Rate BOT_MKT_RATE, 
      VALUES_NS BOT_VALUE, TD_STT, BuyBackFlag = CASE WHEN se_type = 'T' THEN 'Y' ELSE 'N' END
    FROM #tbl_DelvTrxn
    LEFT OUTER JOIN Settlements(NOLOCK) ON (td_Stlmnt = se_stlmnt)
    WHERE td_bsflag = 'S' AND isnull(SQR_TAG, 'N') IN ('N', '')
    ) X123
  GROUP BY CLIENT_CODE, SCRIP_CODE, XTAG11, BuyBackFlag

  --- COMMENT VAIBHAVGARG
  IF ISNULL(@strShowPos, 'N') = 'Y'
  BEGIN
    INSERT INTO #tbl_Rep (Tag, ClientCode, Scrip_Code, XTAG11, BuyDate, BuyQty, BuyRate, BuyValue, BuySTT)
    SELECT Tag = 'Delivery Trxn', CLIENT_CODE, SCRIP_CODE, XTAG11, CONVERT(VARCHAR, MAX(cast(BOT_TRXN_DATE AS DATE)), 106) 
      BOT_TRXN_DATE, SUM(BOT_QTY) BOT_QTY, (CASE WHEN SUM(BOT_QTY) = 0 THEN 0 ELSE round(SUM(BOT_VALUE) / SUM(BOT_QTY), 6) END) 
      BOT_MKT_RATE, SUM(BOT_VALUE) BOT_VALUE, BuySTT = SUM(abs(BOT_QTY) * TD_STT)
    FROM (
      SELECT td_clientcd AS Client_Code, SCRIP_CODE = td_scripcd, XTAG11, td_dt AS BOT_TRXN_DATE, QTY_NS BOT_QTY, td_Rate BOT_MKT_RATE
        , VALUES_NS BOT_VALUE, TD_STT
      FROM #tbl_DelvTrxn
      WHERE td_bsflag = 'B' AND ISNULL(SQR_TAG, '') = '' AND QTY_NS <> 0
      ) X123
    GROUP BY CLIENT_CODE, SCRIP_CODE, XTAG11
  END

  SET DATEFORMAT DMY

  IF ISNULL(@strConsider112A, 'N') = 'N'
  BEGIN
    /*
    SELECT A.*, A.BuyRate, Round(mk_Rate, 4), Tmp_112ARate, 
	Round(mk_Rate, 4)
     FROM #tbl_Rep A, Market_Rates20180131 ,Securities
     WHERE Scrip_Code = ss_cd
	 AND Scrip_Code = mk_scripcd
	 AND CAST(BuyDate AS DATE) <= '20180131'
	 AND CAST(SaleDate AS DATE) > '20180331'
	 AND DateDiff(d, CAST(BuyDate AS DATE), CAST(SaleDate AS DATE)) >= 365
	 AND Round(mk_Rate, 4) > (BuyRate + (CASE WHEN BuySTT <> 0 and BuyQty <> 0 then round(BuySTT/BuyQty,2) else 0 end ))
	 AND ss_chargestt = 'Y' AND SS_CD='532296'
	 AND (SaleRate) > (BuyRate)	
  */
    UPDATE #tbl_Rep
    SET BuyRate = Round(mk_Rate, 4), Tmp_112ARate = Round(mk_Rate, 4), BuySTT = 0, T112AFlag = 'Y'
    FROM Market_Rates20180131, Securities
    WHERE Scrip_Code = ss_cd AND Scrip_Code = mk_scripcd AND CAST(BuyDate AS DATE) <= '20180131' AND CAST(SaleDate AS DATE) > '20180331' AND 
      DateDiff(d, CAST(BuyDate AS DATE), CAST(SaleDate AS DATE)) >= 365 AND Round(mk_Rate, 4) > (BuyRate + (CASE WHEN BuySTT <> 0 AND BuyQty <> 0 THEN round(BuySTT / BuyQty, 2) ELSE 0 END)
        ) AND ss_chargestt = 'Y' AND SaleRate > BuyRatE

    UPDATE #tbl_Rep
    SET Tmp_112ARate = Round(mk_Rate, 4)
    FROM Market_Rates20180131, Securities
    WHERE Scrip_Code = ss_cd AND Scrip_Code = mk_scripcd
  END
  ELSE
  BEGIN
    UPDATE A
    SET A.BuyBackFlag = 'N', T112AFlag = 'N'
    FROM #tbl_Rep A
  END

  SET DATEFORMAT MDY

  -- UPDATE DAYS
  UPDATE A
  SET A.DAYS = CAST(ISNULL((
          CASE WHEN (cast(isnull(BuyDate, '01-jan-1900') AS DATETIME) < 3 OR Cast(isnull(SaleDate, '01-jan-1900') AS DATETIME) < 3
                ) THEN 0 ELSE DATEDIFF(DAY, CAST(BuyDate AS DATE), CAST(SaleDate AS DATE)) END
          ), 0) AS INT)
  FROM #tbl_Rep A
  WHERE Tag = 'Delivery Trxn'

  UPDATE A
  SET A.CLientName = CM.cm_name, A.ScripName = SC.SS_NAME, A.ISIN = im_isin
  FROM #tbl_Rep A, Client_master CM, Securities SC, isin(NOLOCK)
  WHERE A.ClientCode = CM.CM_CD AND A.Scrip_Code = SC.ss_cd AND im_priority IN (
      SELECT min(im_priority)
      FROM isin(NOLOCK)
      WHERE im_scripcd = SC.ss_cd
      ) AND SC.ss_cd = im_scripcd

  UPDATE A
  SET A.SP_TERM_PL = (
      CASE WHEN ISNULL(A.DAYS, 0) = 0 AND Tag <> 'Delivery Trxn' AND (cast(isnull(BuyDate, '01-jan-1900') AS DATETIME) > 3 AND Cast(isnull(SaleDate, '01-jan-1900') AS DATETIME) > 3
            ) THEN (SaleValue - BuyValue) ELSE 0 END
      ), A.S_TERM_PL = (
      CASE WHEN ISNULL(BuyBackFlag, 'N') = 'Y' THEN 0 ELSE (
            CASE WHEN (ISNULL(A.DAYS, 0) >= 0 AND ISNULL(A.DAYS, 0) < 365 AND TAG = 'Delivery Trxn') THEN (SaleValue - BuyValue
                    ) ELSE 0 END
            ) END
      ), A.L_TERM_PL = (
      CASE WHEN ISNULL(A.DAYS, 0) >= 365 THEN CASE WHEN ((T112AFlag = 'Y') AND (SaleRate) < BuyRate
                  ) THEN 0 ELSE ((SaleRate - BuyRate) * BuyQty) END ELSE 0 END
      ), NetQty = BuyQty - ISNULL(abs(SaleQty), 0), NetValue = CASE WHEN BuyQty - ISNULL(abs(SaleQty), 0) <> 0 THEN isnull(SaleValue, 0) - 
          ISNULL(BUYVALUE, 0) ELSE 0 END
  FROM #tbl_Rep A

  --- UPDATE CMP
  UPDATE #tbl_Rep
  SET CMP = mk_closerate
  FROM Market_rates(NOLOCK)
  WHERE mk_scripcd = Scrip_Code AND mk_exchange = 'N' AND mk_dt = (
      SELECT max(mk_dt)
      FROM Market_rates
      WHERE mk_exchange = 'N' AND mk_scripcd = Scrip_Code AND mk_dt <= @dtToDate
      ) AND NetQty <> 0

  DECLARE @tbl_CapgainMain TABLE (
    SerialNo INT identity(1, 1), Tag VARCHAR(50), ClientCode VARCHAR(50), CLientName VARCHAR(100), Scrip_Code VARCHAR(50), ScripName 
    VARCHAR(100), ISIN VARCHAR(20), BuyDate VARCHAR(15), BuyQty NUMERIC(19, 6), BuyRate NUMERIC(19, 6), BuyValue NUMERIC(19, 6), 
    AcquisitionAmount NUMERIC(19, 6), SaleDate VARCHAR(15), SaleQty NUMERIC(19, 6), SaleRate NUMERIC(19, 6), SaleValue NUMERIC(19, 6)
    , A112A_Rate VARCHAR(20), DAYS INT, SP_TERM_PL MONEY, S_TERM_PL MONEY, L_TERM_PL MONEY, NetQty MONEY, NetValue MONEY, CMP MONEY, 
    NOT_PL MONEY, STT MONEY
    )

  INSERT INTO @tbl_CapgainMain (
    Tag, ClientCode, CLientName, Scrip_Code, ScripName, ISIN, BuyDate, BuyQty, BuyRate, BuyValue, AcquisitionAmount, SaleDate, 
    SaleQty, SaleRate, SaleValue, A112A_Rate, DAYS, SP_TERM_PL, S_TERM_PL, L_TERM_PL, NetQty, NetValue, CMP, NOT_PL, Stt
    )
  SELECT Tag, ClientCode, CLientName, Scrip_Code, ScripName, ISIN, BuyDate = CASE WHEN CONVERT(VARCHAR, CAST(BuyDate AS DATE), 103) = 
        '01/01/1900' THEN '' ELSE CONVERT(VARCHAR, CAST(BuyDate AS DATE), 103) END, BuyQty, BuyRate, 
		(ISNULL(BuyQty, 0) * ISNULL(BuyRate, 0)), BuyValue, SaleDate = ISNULL((
        CASE WHEN CONVERT(VARCHAR, CAST(SaleDate AS DATE), 103) = '01/01/1900' THEN '' ELSE CONVERT(VARCHAR, CAST(SaleDate AS DATE), 103
            ) END
        ), ''), SaleQty = ISNULL(abs(SaleQty), 0), SaleRate = ABS(ISNULL(SaleRate, 0)), SaleValue = ISNULL(SaleValue, 0), A112A_Rate = 
    ISNULL(CAST(Tmp_112ARate AS VARCHAR) + (CASE WHEN ISNULL(BuyBackFlag, 'N') = 'N' THEN (CASE WHEN T112AFlag = 'Y' THEN ' *' ELSE '' END) ELSE ' #' END
        ), ''), DAYS = ISNULL(DAYS, 0), SP_TERM_PL = ISNULL(SP_TERM_PL, 0), S_TERM_PL = ISNULL(S_TERM_PL, 0), L_TERM_PL = ISNULL(
      L_TERM_PL, 0), NetQty, NetValue, CMP = isnull(CMP, 0), NOT_PL = ISNULL(NetValue, 0) + round(isnull(NetQty, 0) * isnull(CMP, 0), 2), 
    STT = ISNULL(BUYSTT, 0) + ISNULL(SaleSTT, 0)
  FROM #tbl_Rep X
  WHERE CONVERT(VARCHAR, CAST(BuyDate AS DATE), 103) <> '01/01/1900'
  ORDER BY CLIENTCODE, Scrip_Code, CAST(BuyDate AS DATE), CAST(SaleDate AS DATE)

  INSERT INTO @tbl_CapgainMain (
    Tag, ClientCode, CLientName, Scrip_Code, ScripName, ISIN, BuyDate, BuyQty, BuyRate, BuyValue, AcquisitionAmount, SaleDate, 
    SaleQty, SaleRate, SaleValue, A112A_Rate, DAYS, SP_TERM_PL, S_TERM_PL, L_TERM_PL, NetQty, NetValue, CMP, NOT_PL, Stt
    )
  SELECT Tag = 'Short Sale', ClientCode, CLientName, Scrip_Code, ScripName, ISIN, BuyDate = CASE WHEN CONVERT(VARCHAR, CAST(BuyDate AS 
            DATE), 103) = '01/01/1900' THEN '' ELSE CONVERT(VARCHAR, CAST(BuyDate AS DATE), 103) END, BuyQty, BuyRate = 0, BuyValue, 
    BuyValue, SaleDate = ISNULL((
        CASE WHEN CONVERT(VARCHAR, CAST(SaleDate AS DATE), 103) = '01/01/1900' THEN '' ELSE CONVERT(VARCHAR, CAST(SaleDate AS DATE), 103
            ) END
        ), ''), SaleQty = ISNULL(abs(SaleQty), 0), SaleRate = abs(ISNULL(SaleRate, 0)), SaleValue = ISNULL(SaleValue, 0), A112A_Rate = 
    '', DAYS = ISNULL(DAYS, 0), SP_TERM_PL = ISNULL(SP_TERM_PL, 0), S_TERM_PL = ISNULL(S_TERM_PL, 0), L_TERM_PL = ISNULL(L_TERM_PL, 0), 
    NetQty, NetValue, CMP = isnull(CMP, 0), NOT_PL = ISNULL(NetValue, 0) + round(isnull(NetQty, 0) * isnull(CMP, 0), 2), BuySTT = BUYSTT + 
    SaleSTT
  FROM #tbl_Rep X
  WHERE CONVERT(VARCHAR, CAST(BuyDate AS DATE), 103) = '01/01/1900' AND abs(SaleQty) > 0
  ORDER BY CLIENTCODE, Scrip_Code, CAST(BuyDate AS DATE), CAST(SaleDate AS DATE)

  DROP TABLE #tbl_DelvTrxn

  DROP TABLE #tbl_DelvTrxn1

  DROP TABLE #tbl_DelvTrxn2

  DROP TABLE #tbl_Rep

  SET @o_vcErrorMessage = ''
  SET @XMLDATA1 = ''

  --SELECT @strRepType, @
  IF @strRepType = 'Actual PL_Detail'
  BEGIN
    IF @strOutputType = 'X'
    BEGIN
      SET @XMLDATA1 = (
          SELECT *
          FROM @tbl_CapgainMain
          ORDER BY SerialNo
          FOR XML PATH('CapGain')
          )
      SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))

      RETURN 1
    END
    ELSE
    BEGIN
      IF ISNULL(@strShortSale, 'N') IN ('N', '')
      BEGIN
        SELECT *
        FROM @tbl_CapgainMain
        ORDER BY SerialNo

        SET @o_vcErrorMessage = ''
      END
      ELSE IF ISNULL(@strShortSale, 'N') = 'Y'
      BEGIN
        SELECT *
        FROM @tbl_CapgainMain
        WHERE Tag <> 'Short Sale'
        ORDER BY SerialNo

        SELECT *, CurrentValue = ISNULL(NetQty, 0) * ISNULL(CMP, 0)
        FROM @tbl_CapgainMain
        WHERE Tag = 'Short Sale'
        ORDER BY SerialNo

        SET @o_vcErrorMessage = ''
      END

      SET @o_vcErrorMessage = ''

      RETURN 1
    END
  END
  ELSE IF @strRepType = 'Actual PL_Summary'
  BEGIN
    SET DATEFORMAT DMY

    IF @strOutputType = 'X'
    BEGIN
      SET @XMLDATA1 = (
          SELECT ClientCode, CLientName, Scrip_Code, ScripName, BuyQty = SUM(BuyQty), BuyRate = ROUND((CASE WHEN SUM(BuyQty) <> 0 THEN SUM(AcquisitionAmount) / SUM(BuyQty) ELSE 0 END
                ), 6), BuyValue = SUM(BuyValue), AcquisitionAmount = SUM(AcquisitionAmount), SaleQty = SUM(SaleQty), SaleRate = ROUND
            ((CASE WHEN SUM(SaleQty) <> 0 THEN SUM(SaleValue) / SUM(SaleQty) ELSE 0 END), 6), SaleValue = SUM(SaleValue
            ), SP_TERM_PL = SUM(SP_TERM_PL), S_TERM_PL = SUM(S_TERM_PL), L_TERM_PL = SUM(L_TERM_PL), NetQty = SUM(NetQty), NetValue = 
            SUM(NetValue), CMP = MAX(CMP), NOT_PL = SUM(NOT_PL), STT = SUM(STT)
          FROM (
            SELECT TAG, ClientCode, CLientName, Scrip_Code, ScripName, BuyDate = CASE WHEN ISNULL(BuyDate, '') = '' THEN '01/01/1900' 
                ELSE BuyDate END, BuyQty = CAST(BuyQty AS NUMERIC(19, 6)), BuyRate = CAST(BuyRate AS NUMERIC(19, 6)), CAST(BuyValue AS 
                NUMERIC(19, 6)) BuyValue, CAST(AcquisitionAmount AS NUMERIC(19, 6)) AcquisitionAmount, SaleDate, SaleQty = CAST(
                SaleQty AS NUMERIC(19, 6)), SaleRate, SaleValue = CAST(SaleValue AS NUMERIC(19, 6)), SP_TERM_PL, S_TERM_PL, L_TERM_PL
              , NetQty = CAST(NetQty AS NUMERIC(19, 6)), NetValue = CAST(NetValue AS NUMERIC(19, 6)), CMP, NOT_PL, STT, FromDate = CONVERT
              (VARCHAR, CAST(@dtFromDate AS DATE), 103)
            FROM @tbl_CapgainMain X
            ) xmain
          GROUP BY ClientCode, CLientName, Scrip_Code, ScripName
          ORDER BY ClientCode, ScripName
          FOR XML PATH('CapGain')
          )
      SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))

      RETURN 1
    END
    ELSE
    BEGIN
      SELECT TAG, ClientCode = LTRIM(RTRIM(ClientCode)), CLientName = LTRIM(RTRIM(CLientName)), Scrip_Code, ScripName, BuyQty = 
        ROUND(SUM(BuyQty), 6), BuyRate = ROUND((CASE WHEN SUM(BuyQty) <> 0 THEN SUM(AcquisitionAmount) / SUM(BuyQty) ELSE 0 END
            ), 6), BuyValue = SUM(BuyValue), AcquisitionAmount = SUM(AcquisitionAmount), SaleQty = SUM(SaleQty), SaleRate = ROUND((CASE WHEN SUM(SaleQty) <> 0 THEN SUM(SaleValue) / SUM(SaleQty) ELSE 0 END
            ), 6), SaleValue = SUM(SaleValue), SP_TERM_PL = SUM(SP_TERM_PL), S_TERM_PL = SUM(S_TERM_PL), L_TERM_PL = SUM(L_TERM_PL), 
        NetQty = SUM(NetQty), NetValue = SUM(NetValue), CMP = MAX(CMP), NOT_PL = SUM(NOT_PL), STT = SUM(STT)
      FROM (
        SELECT TAG, ClientCode, CLientName, Scrip_Code, ScripName, BuyDate = CASE WHEN ISNULL(BuyDate, '') = '' THEN '01/01/1900' ELSE 
              BuyDate END, BuyQty = CAST(BuyQty AS NUMERIC(19, 6)), BuyRate = CAST(BuyRate AS NUMERIC(19, 6)), CAST(BuyValue AS NUMERIC(
              19, 6)) BuyValue, CAST(AcquisitionAmount AS NUMERIC(19, 6)) AcquisitionAmount, SaleDate, SaleQty = CAST(SaleQty AS 
            NUMERIC(19, 6)), SaleRate, SaleValue = CAST(SaleValue AS NUMERIC(19, 6)), SP_TERM_PL, S_TERM_PL, L_TERM_PL, NetQty = CAST(
            NetQty AS NUMERIC(19, 6)), NetValue = CAST(NetValue AS NUMERIC(19, 6)), CMP, NOT_PL, STT, FromDate = CONVERT(VARCHAR, CAST(
              @dtFromDate AS DATE), 103)
        FROM @tbl_CapgainMain X
        ) xmain
      GROUP BY Tag, ClientCode, CLientName, Scrip_Code, ScripName
      ORDER BY ClientCode, CASE WHEN TAG <> 'Short Sale' THEN ScripName ELSE 'zzzz' END

      SET @o_vcErrorMessage = ''

      RETURN 1
    END

    SET DATEFORMAT MDY  END

  SET @o_vcErrorFlag = 'S'

  -- SET @o_vcErrorMessage = 'Process Completed'
  RETURN 1
END
GO

CREATE PROCEDURE stpr_Rpt_CapitalGainNotional @vcXML NVARCHAR(MAX), @o_vcErrorFlag VARCHAR(1) OUTPUT, 
@o_vcErrorMessage VARCHAR(MAX) OUTPUT 
WITH ENCRYPTION
AS
BEGIN
 /*
 ///////////////////////////////////////////////////////////////////////////////////////////
 // Create By     : VAIBHAV GARG
 // Created Date  : 22-FEB-2024
 // Description   : 
 // Reviewed By   : 
 // Review Date   : 
 //////////////////////////////////////////////////////////////////////////////////////////
*/
  DECLARE @dtFromDate VARCHAR(8), @strUserId VARCHAR(50), @strProduct VARCHAR(50), 
  @strOutputType VARCHAR(1)='', @XMLData XML,
  @strSelectTag VARCHAR(1)='', @strSelectUsers VARCHAR(500)='', @StrString VARCHAR(MAX)='', @SQ1 INT = 0,
  @strSplFilter VARCHAR(MAX)='', @strRepType VARCHAR(50)='', @dtToDate VARCHAR(8)='', @strRepSubType VARCHAR(50), @strConsider112A VARCHAR(1)='N',
  @strScripCode VARCHAR(20)='', @strInsertHolding VARCHAR(1)='N',@strCompanyCode VARCHAR(1), @strReportDisplay VARCHAR(1) = 'P'
  IF @vcXML = ''
  BEGIN
    SET @o_vcErrorFlag  = 'E'
    SET @o_vcErrorMessage = 'Please Send Input Parameter(s)'
    RETURN 1
  END 

  SET @XMLData = CAST('<root>'+@vcXML+'</root>' AS XML)
  
  SELECT @dtFromDate = ISNULL(x.value('(FromDt)[1]', 'VARCHAR(8)'),''),
  @strProduct = ISNULL(x.value('(Product)[1]', 'VARCHAR(50)'),''),
  @dtToDate = ISNULL(x.value('(ToDt)[1]', 'VARCHAR(8)'),''),
  @strUserId = ISNULL(x.value('(UserId)[1]', 'VARCHAR(500)'),''),
  @strSelectTag = ISNULL(x.value('(SelectTag)[1]', 'VARCHAR(1)'),''),
  @strSelectUsers = ISNULL(x.value('(SelectUsers)[1]', 'VARCHAR(500)'),''),
  @strOutputType = ISNULL(x.value('(OutputType)[1]', 'VARCHAR(1)'),''),
  @strSplFilter = ISNULL(x.value('(SplFilter)[1]', 'VARCHAR(MAX)'),''),
  @strRepType = ISNULL(x.value('(RepType)[1]', 'VARCHAR(100)'),''),
  @strRepSubType = ISNULL(x.value('(RepSubType)[1]', 'VARCHAR(100)'),''),
  @strConsider112A = ISNULL(x.value('(Option112A)[1]', 'VARCHAR(1)'),''),
  @strScripCode = ISNULL(x.value('(ScripCode)[1]', 'VARCHAR(20)'),''),
  @strInsertHolding = ISNULL(x.value('(HoldingFlag)[1]', 'VARCHAR(2)'),''),
  @strCompanyCode = ISNULL(x.value('(CompanyCode)[1]', 'VARCHAR(1)'),''),
  @strReportDisplay  = ISNULL(x.value('(ReportDisplay)[1]', 'VARCHAR(1)'),'')
  FROM @XMLData.nodes('/root') AS XTbl(x) 
  
  IF ISNULL(@strReportDisplay,'') = ''
  BEGIN
    SET @strReportDisplay = 'P'
  END  
 

  IF @strRepType = ''
  begin
    SET @strRepType = 'Notional_Detail'
  END
   
  
  IF @strReportDisplay IN('D','E','A','X') AND EXISTS(SELECT 1 FROM CLIENT_MASTER(NOLOCK) WHERE CM_cD = @strUserId)
  BEGIN
    DECLARE @o_Message NVARCHAR(MAX)=''
    EXEC stpr_TypestHeaderProc @strUserid, '', '', @strCompanyCode,  @o_Message OUTPUT
	  
    IF @strRepType LIKE '%Summary%'
	BEGIN
	  SET @o_Message = REPLACE(@o_Message,'##ReportName##','Notional Gain / Loss (Summary) Report as on '  + CONVERT(VARCHAR(30), Cast(getdate() as date), 103))
	END
    ELSE
    BEGIN
	  SET @o_Message = REPLACE(@o_Message,'##ReportName##','Notional Gain / Loss (Detail) Report as on '  + CONVERT(VARCHAR(30), Cast(getdate() as date), 103))
    END	
    SET @o_Message = REPLACE(@o_Message,'##Grid1##','')
    SET @o_Message = REPLACE(@o_Message,'##Grid2##','')
    SET @o_Message = REPLACE(@o_Message,'##Grid3##','')
    SET @o_Message = REPLACE(@o_Message,'##Grid4##','')
	SET @o_Message = REPLACE(@o_Message,'##PageOrientation##','Portrait')
	SET @o_Message = REPLACE(@o_Message,'##PageSize##','A4')
	--SET @o_Message = REPLACE(@o_Message,'##PageOrientation##','Landscape')
	IF @strReportDisplay IN('E','D','X')
	BEGIN
	  SET @o_Message = REPLACE(@o_Message,'##FormatGrid##','Grid1')
	  SET @strOutputType = 'G'
	END 
    ELSE 
	BEGIN
	  SET @o_Message = REPLACE(@o_Message,'##FormatGrid##','')
	END 
	
    SET @o_Message = '<root>' + @o_Message + '</root>';
  
    DECLARE @xmlData3 XML = CAST(@o_Message AS XML);
	
	DECLARE @DynamicColumns NVARCHAR(MAX);
    
	SET  @DynamicColumns = '';
  
	
    WITH DistinctNodes AS (
    SELECT DISTINCT
       NodeName = X.n.value('local-name(.)', 'NVARCHAR(100)')
    FROM @xmlData3.nodes('/root/ClientDetail/*') AS X(n))
    
    SELECT @DynamicColumns = @DynamicColumns+','+
        'LTRIM(RTRIM(X1.value(''(' + XX.NodeName + ')[1]'', ''NVARCHAR(MAX)''))) AS [' + XX.NodeName + ']'
    FROM DistinctNodes XX
	WHERE NodeName NOT IN('Grid2','Grid3','Grid4')
   
    SELECT @DynamicColumns = SUBSTRING(@DynamicColumns,2,LEN(@DynamicColumns)-1) 
  
    DECLARE @sql NVARCHAR(MAX);
    SET @sql = '
    SELECT ' + @DynamicColumns + '
    FROM @xmlData3.nodes(''/root/ClientDetail'') AS T(X1)';
  
    EXEC sp_executesql @sql, N'@xmlData3 XML', @xmlData3;
	
	IF @strReportDisplay NOT IN('A')
	BEGIN
	  SELECT ColumnName, ColumnHeading, ColumnWidth, ColumnAlignement, ColumnFormat, Columnstyle, DecimalPlace, ColumnTotal,
      ColumnHide = CASE WHEN Userid = '1' THEN 'Y' ELSE 'N'	END   
      FROM tbl_ReportGridViewFormat(NOLOCK) 
	  WHERE ReportCode='CaptialGain'
      and ReportCategroy = @strRepType AND ColumnVisible = '0'
      Order By Orderby
    END
  END	

  IF ISNULL(@strInsertHolding,'N') = 'N'
  BEGIN
   SET @strInsertHolding = 'N'
  END
  
  DECLARE @strTakingSTTinCOst VARCHAR(1)='N'
  SELECT @strTakingSTTinCOst = isnull(sp_sysvalue,'N') from SysParameter where SP_ParmCd = 'GAINLOSSTTDL'
 
  if ISNULL(@strConsider112A,'') = ''
  BEGIN
    SET @strConsider112A ='N'
  END
  
  DECLARE @tbl_UserList TABLE(Client_Code VARCHAR(50)) 
  
  	
  IF @strSplFilter = ''
  BEGIN
    INSERT INTO @tbl_UserList(Client_Code) 
    SELECT * FROM DBO.[fn_GetClients](@strUserId,@strSelectTag,@strSelectUsers)
  END 	 
  ELSE
  IF @strSplFilter <> ''
  BEGIN
    SET @StrString  = ' SELECT distinct CM_CD FROM Client_master(NOLOCK) WHERE 1 = 1  AND '+@strSplFilter
	INSERT INTO @tbl_UserList(Client_Code) 
	EXEC(@StrString)
  END	
  
  SET @StrString = ''
  
  IF OBJECT_ID('tempdb..#tbl_DelvTrxn') IS NOT NULL
    DROP TABLE #tbl_DelvTrxn
  IF OBJECT_ID('tempdb..#tbl_DelvTrxn1') IS NOT NULL
    DROP TABLE #tbl_DelvTrxn1
  IF OBJECT_ID('tempdb..#TrxSummaryDLV1') IS NOT NULL
    DROP TABLE #TrxSummaryDLV1
  IF OBJECT_ID('tempdb..#TrxDLV1') IS NOT NULL
    DROP TABLE #TrxDLV1
  IF OBJECT_ID('tempdb..#tbl_CloseRate') IS NOT NULL
    DROP TABLE #tbl_CloseRate

  CREATE TABLE #tbl_DelvTrxn1 (
	td_SRNO INT, td_dt VARCHAR(8), td_Stlmnt VARCHAR(20), td_clientcd VARCHAR(20), td_scripcd VARCHAR(20), 
	td_bsflag VARCHAR(1), Qty_NS numeric(19,6), VALUES_NS numeric(19,6), td_Rate numeric(19,6),
	XTAG11 INT, LONG_TAG VARCHAR(1), SQR_TAG VARCHAR(1), Tmp_RefNo numeric, td_Filler1 VARCHAR(8), td_stt MONEY, TD_Charges MONEY
  )

  CREATE TABLE #tbl_DelvTrxn (
  SerialNo int identity(1,1), td_SRNO INT, td_dt VARCHAR(8), td_Stlmnt VARCHAR(20), td_clientcd VARCHAR(20), td_scripcd VARCHAR(20), 
	td_bsflag VARCHAR(1), Qty_NS numeric(19,6), VALUES_NS numeric(19,6), td_Rate numeric(19,6), 
	XTAG11 INT, LONG_TAG VARCHAR(1), SQR_TAG VARCHAR(1), Tmp_RefNo numeric, td_Filler1 VARCHAR(8), td_stt MONEY, TD_Charges MONEY
  )
	  
  	  
  INSERT INTO #tbl_DelvTrxn1 (
	td_SRNO, td_dt, td_Stlmnt, td_clientcd, td_scripcd, td_bsflag, Qty_NS, VALUES_NS, td_Rate, Tmp_RefNo, td_Filler1, td_stt,
	TD_Charges)
    SELECT X.*
    FROM (
    SELECT td_SRNO, td_dt = CASE WHEN ISDATE(td_Filler1) = 0 THEN td_dt ELSE td_Filler1 END, td_Stlmnt, td_clientcd, td_scripcd, td_bsflag, 
	Qty_NS = ABS(CASE WHEN ISNULL(td_Filler2,'')  <> 'T' THEN td_bqty - td_Sqty ELSE 0 END), 
	VALUES_NS = (CASE WHEN ISNULL(td_Filler2,'')  <> 'T' THEN (CASE WHEN td_bsflag = 'B' THEN 
	td_Rate + Round(td_ServiceTax + td_OtherChrgs1 + td_OtherChrgs2 + (CASE WHEN ISNULL(@strTakingSTTinCOst,'N') = 'Y' THEN 
	td_stt ELSE 0 END), 6) ELSE 
	td_Rate - Round(td_ServiceTax + td_OtherChrgs1 + td_OtherChrgs2 + (CASE WHEN ISNULL(@strTakingSTTinCOst,'N') = 'Y' THEN 
	td_stt ELSE 0 END), 6) END) ELSE 0 END) * 
			ABS(CASE WHEN ISNULL(td_Filler2,'')  <> 'T' THEN  td_bqty - td_Sqty ELSE 0 END), 
		td_Rate = (CASE WHEN td_bsflag = 'B' THEN td_Rate + Round(td_ServiceTax + 
		td_OtherChrgs1 + td_OtherChrgs2 + (CASE WHEN ISNULL(@strTakingSTTinCOst,'N') = 'Y' THEN 
	td_stt ELSE 0 END), 6) ELSE td_Rate - Round(td_ServiceTax + td_OtherChrgs1 + td_OtherChrgs2 + (CASE WHEN ISNULL(@strTakingSTTinCOst,'N') = 'Y' THEN 
	td_stt ELSE 0 END), 6) END), 
		td_NFiller2, td_Filler1, td_stt, TD_Charges = Round(td_ServiceTax + 
		td_OtherChrgs1 + td_OtherChrgs2, 4)
    FROM TRX_INVPL(NOLOCK), Client_master(NOLOCK), @tbl_UserList X
    WHERE cm_cd = td_clientcd AND td_dt <= @dtToDate --and ISNULL(td_Filler2,'') <> 'T'
	AND ((td_bsflag = 'B' AND td_bqty > 0) OR (td_bsflag = 'S' AND td_Sqty > 0))
    AND cm_cd  = X.CLIENT_CODE AND ISNULL(td_Filler2,'')  <> 'T') X
	WHERE ((td_scripcd = @strScripCode AND @strScripCode <> '') OR @strScripCode = '')
	--AND td_clientcd='S11054' AND td_scripcd='524444'
	--AND td_scripcd = '590096'
	
	
    CREATE INDEX indx_DelvTrxntd_SRNO ON #tbl_DelvTrxn1 (td_SRNO, td_Filler1) 
	CREATE INDEX indx_DelvTrxntd_SRNO1 ON #tbl_DelvTrxn1 (Tmp_RefNo) 
	
	 
	DECLARE @UPDtd_SRNO INT, @updTmp_RefNo INT, @updtd_scripcd VARCHAR(20)='', @updtd_clientcd VARCHAR(20)=''
    DECLARE CursorUpdatedate CURSOR
    FOR
    SELECT td_SRNO, Tmp_RefNo, td_clientcd, td_scripcd
    FROM #tbl_DelvTrxn1 x where Tmp_RefNo > 0
  
    OPEN CursorUpdatedate
    FETCH NEXT
    FROM CursorUpdatedate
    INTO @UPDtd_SRNO, @updTmp_RefNo, @updtd_clientcd, @updtd_scripcd
    WHILE @@FETCH_STATUS = 0
    BEGIN 
      UPDATE A SET a.Qty_NS = a.Qty_NS - b.Qty_NS
	  FROM #tbl_DelvTrxn1 A, #tbl_DelvTrxn1 B  
      WHERE A.td_SRNO = @UPDtd_SRNO and b.td_SRNO  = @updTmp_RefNo
	  AND A.td_clientcd = B.td_clientcd
	  AND A.td_scripcd = B.td_scripcd
	  AND B.td_clientcd = @updtd_clientcd AND B.td_scripcd = @updtd_scripcd
	
	  DELETE FROM #tbl_DelvTrxn1 WHERE td_SRNO = @updTmp_RefNo
	  AND td_clientcd =  @updtd_clientcd AND  td_scripcd = @updtd_scripcd
	
      FETCH NEXT FROM CursorUpdatedate
	  INTO @UPDtd_SRNO, @updTmp_RefNo, @updtd_clientcd, @updtd_scripcd
    END
    CLOSE CursorUpdatedate
    DEALLOCATE CursorUpdatedate
  
    DELETE FROM #tbl_DelvTrxn1 WHERE ISNULL(Qty_NS,0) = 0
  
    UPDATE #tbl_DelvTrxn1 SET td_dt = td_Filler1 WHERE td_Filler1 NOT IN('','0')
	

    CREATE INDEX indx_DelvTrxn1 ON #tbl_DelvTrxn1 (td_clientcd, td_scripcd, td_SRNO) 
	CREATE INDEX indx_DelvTrxn ON #tbl_DelvTrxn (td_clientcd, td_scripcd, td_SRNO) 
	CREATE INDEX indx_DelvTrxnS ON #tbl_DelvTrxn (td_scripcd) 
	CREATE INDEX indx_DelvTrxnSR ON #tbl_DelvTrxn (SerialNo) 


    insert into #tbl_DelvTrxn(td_SRNO, td_dt, td_Stlmnt, td_clientcd, td_scripcd, td_bsflag, Qty_NS, VALUES_NS, td_Rate, td_stt, Tmp_RefNo, td_Filler1, TD_Charges)
    SELECT td_SRNO, td_dt, td_Stlmnt, td_clientcd, td_scripcd, td_bsflag, Qty_NS, VALUES_NS, td_Rate, td_stt,
	Tmp_RefNo, td_Filler1, TD_Charges
	FROM #tbl_DelvTrxn1 xmain 
	WHERE EXISTS(
    SELECT 1 FROM(
    SELECT td_clientcd, td_scripcd, Qty_NS = SUM(CASE WHEN td_bsflag='B' THEN Qty_NS ELSE Qty_NS*-1 END)  
    FROM #tbl_DelvTrxn1
    GROUP BY td_clientcd, td_scripcd
    HAVING SUM(CASE WHEN td_bsflag='B' THEN Qty_NS ELSE Qty_NS*-1 END) <> 0) x1 
    where x1.td_clientcd = xmain.td_clientcd
    and x1.td_scripcd = xmain.td_scripcd)

    
	CREATE TABLE #TrxSummaryDLV1 (clientcd VARCHAR(8) NOT NULL, scripcd VARCHAR(6) NOT NULL, Buys MONEY, Sells MONEY)
	
	INSERT INTO #TrxSummaryDLV1
	SELECT td_clientcd, td_scripcd, Buys, Sells
    FROM (SELECT td_clientcd, cm_name, td_scripcd, ss_name, 
    ss_nsymbol, ss_nseries, sum(CASE WHEN td_bsflag='B' THEN Qty_ns ELSE 0.00 END) AS 'Buys', 
	sum(CASE WHEN td_bsflag='S' THEN Qty_ns ELSE 0.00 END) 'Sells', 
	sum(CASE WHEN td_bsflag='B' THEN Qty_ns ELSE 0.00 END) - sum(CASE WHEN td_bsflag='S' THEN Qty_ns ELSE 0.00 END) AS 'Delivery', 
    count(*) Totalrec, ss_group, cm_type
    FROM #tbl_DelvTrxn, Client_master, Securities
    WHERE cm_cd = td_clientcd AND td_scripcd = ss_cd
    GROUP BY td_clientcd, cm_name, td_scripcd, ss_cd, ss_name, ss_nsymbol, ss_nseries, ss_group, cm_type
    HAVING sum(CASE WHEN td_bsflag='B' THEN Qty_ns ELSE 0.00 END) - sum(CASE WHEN td_bsflag='S' THEN Qty_ns ELSE 0.00 END) <> 0.00) a

    

	CREATE TABLE #TrxDLV1 (SrNo NUMERIC, Qty NUMERIC(19,6), FinalQty NUMERIC(19,6))
    CREATE INDEX indx_SrNo ON #TrxDLV1 (SrNo) 
	
	INSERT INTO #TrxDLV1
	SELECT SerialNo, Qty, CASE WHEN NetQty >= Running THEN Qty ELSE NetQty - isNull(PrevRunning, 0) END FinalQty
    FROM (
    SELECT SerialNo, td_clientcd, td_scripcd, td_marketrate,  NetQty, Qty, Running, LAG(
		Running) OVER (
		PARTITION BY td_clientcd, td_scripcd ORDER BY td_dt DESC,  SerialNo DESC
		) PrevRunning
    FROM (
	SELECT SerialNo, td_dt, td_clientcd, td_scripcd, Qty_ns Qty, td_marketrate = td_Rate,  abs(Buys - Sells) NetQty, Sum(Qty_ns) OVER (
			PARTITION BY td_clientcd, td_scripcd ORDER BY td_dt DESC,  SerialNo DESC
			) Running
	FROM #tbl_DelvTrxn, Client_master, Securities, #TrxSummaryDLV1
	WHERE cm_cd = td_clientcd AND td_scripcd = ss_cd
		AND td_clientcd = clientcd AND td_scripcd = scripcd AND td_bsflag = CASE WHEN Buys > Sells THEN 'B' ELSE 'S' END) a
    ) b
    WHERE CASE WHEN NetQty >= Running THEN Qty ELSE NetQty - isNull(PrevRunning, 0) END > 0

   ALTER TABLE #tbl_DelvTrxn ADD Tmp_112ARate MONEY, T112AFlag VARCHAR(1) NOT NULL DEFAULT 'N', ActualBuyRate MONEY NOT NULL DEFAULT 0
   
   INSERT INTO #tbl_DelvTrxn(td_SRNO, td_dt, td_Stlmnt, td_clientcd, td_scripcd, td_bsflag, Qty_NS, VALUES_NS, td_Rate, td_stt, Tmp_RefNo, td_Filler1)
   SELECT td_SRNO, td_dt, td_Stlmnt, td_clientcd, td_scripcd, td_bsflag, 
   Qty - FinalQty, VALUES_NS = (Qty - FinalQty)*td_Rate, td_Rate, td_stt, Tmp_RefNo, td_Filler1
   FROM #tbl_DelvTrxn , #TrxDLV1
   WHERE SerialNo = srno AND (Qty - FinalQty) > 0


   UPDATE #tbl_DelvTrxn
   SET Qty_NS = FinalQty, VALUES_NS = FinalQty*td_Rate, SQR_TAG = 'Y' 
   FROM #TrxDLV1
   WHERE SerialNo = srno  AND td_bsflag = 'B'

   UPDATE #tbl_DelvTrxn
   SET Qty_NS = FinalQty, VALUES_NS = FinalQty*td_Rate, SQR_TAG = 'Y' 
   FROM #TrxDLV1
   WHERE SerialNo = srno and td_bsflag = 'S'

   DELETE #tbl_DelvTrxn
   WHERE Qty_NS = 0
   
   UPDATE #tbl_DelvTrxn SET ActualBuyRate = td_Rate
   
   IF ISNULL(@strInsertHolding,'N') = 'Y'
   BEGIN
     TRUNCATE TABLE INVPL_Holding_VAG
     INSERT INTO INVPL_Holding_VAG(IH_Clientcd, IH_Scripcd, IH_Qty, IH_BDt, IH_BRate, IH_BChrg, IH_BStt, IH_SDT, IH_SRate, IH_SChrg, IH_SStt, IH_Flag, 
     IH_MarketRate, IH_BSFlag, IH_Remark, IH_Stlmnt, IH_MKRID, IH_MKRDT)
     SELECT IH_Clientcd = td_clientcd, 
     IH_Scripcd = td_scripcd, IH_Qty = Qty_NS,
     IH_BDt = CASE WHEN  td_bsflag ='B' THEN td_dt ELSE '' END,
     IH_BRate = CASE WHEN  td_bsflag ='B' THEN TD_RATE ELSE 0 END,
     IH_BChrg = CASE WHEN  td_bsflag ='B' THEN td_charges ELSE 0 END , 
	 IH_BStt = CASE WHEN  td_bsflag ='B' THEN TD_STT ELSE 0 END, 
     IH_SD = CASE WHEN  td_bsflag ='S' THEN td_dt ELSE '' END,
     IH_SRate = CASE WHEN  td_bsflag ='S' THEN TD_RATE ELSE 0 END,
     IH_SChrg = CASE WHEN  td_bsflag ='S' THEN td_charges ELSE 0 END,
     IH_SStt = CASE WHEN  td_bsflag ='S' THEN TD_STT ELSE 0 END ,
     IH_Flag = td_bsflag,IH_MarketRate = 0,IH_BSFlag = td_bsflag,
     IH_Remark = '',IH_Stlmnt = td_stlmnt,IH_MKRID = 'API',IH_MKRDT = CONVERT(VARCHAR,GETDATE(),112)
     FROM #tbl_DelvTrxn WHERE ISNULL(SQR_TAG,'N') = 'Y'
     ORDER BY td_clientcd, td_scripcd
	 SET @o_vcErrorFlag  = 'S'
	 RETURN 1
   END	 
   
   
   SET DATEFORMAT DMY
  
   IF ISNULL(@strConsider112A,'N') = 'N'
   BEGIN
     UPDATE #tbl_DelvTrxn
     SET td_Rate = Round(mk_Rate, 4)
	  ,Tmp_112ARate = Round(mk_Rate, 4),
	  T112AFlag = 'Y'
     FROM Market_Rates20180131
	 ,Securities
     WHERE td_scripcd = ss_cd
	 AND td_scripcd = mk_scripcd
	 AND CAST(td_dt AS DATE) <= '20180131'
	 AND CAST(@dtToDate AS DATE) > '20180331'
	 AND DateDiff(d, CAST(td_dt AS DATE), CAST(@dtToDate AS DATE)) >= 365
	 AND Round(mk_Rate, 4) > (td_Rate)
	 AND ss_chargestt = 'Y'
	 
	 UPDATE #tbl_DelvTrxn
     SET Tmp_112ARate = Round(mk_Rate , 4)
     FROM Market_Rates20180131 ,Securities
     WHERE td_scripcd = ss_cd
	 AND td_scripcd = mk_scripcd	
  END	  
  ELSE
  BEGIN
    UPDATE A SET T112AFlag = 'N'
	FROM #tbl_DelvTrxn A
  END
  
  SET DATEFORMAT MDY


   declare @tbl_HoldingRep TABLE(td_SRNO INT, ClientCode VARCHAR(50), TradeDate VARCHAR(8), td_Stlmnt VARCHAR(20),
   ScripCode VARCHAR(10), BuyQty MONEY, BuyRate MONEY,
   BuyValue MONEY, SaleQty MONEY, SaleRate MONEY,
   SaleValue MONEY, CloseRate MONEY, CurrentValue MONEY, ShortTerm MONEY, LongTerm MONEY, PositionDays INT, Tmp_112ARate MONEY, 
   T112AFlag VARCHAR(1), ActualBuyRate MONEY, SqrTag VARCHAR(1), td_stt MONEY, 
   Tmp_RefNo VARCHAR(20), td_Filler1  VARCHAR(20))

   INSERT INTO @tbl_HoldingRep(td_SRNO, ClientCode, TradeDate, td_Stlmnt, ScripCode, BuyQty, BuyRate, BuyValue, SaleQty, SaleRate, 
   SaleValue, Tmp_112ARate, T112AFlag, ActualBuyRate, SqrTag, td_stt, Tmp_RefNo, td_Filler1)
   
   SELECT td_SRNO, td_clientcd, td_dt, td_Stlmnt, td_scripcd, BuyQty = CASE WHEN td_bsflag='B' THEN Qty_NS ELSE 0 END, 
   Rate = td_rate,  Cost = (CASE WHEN td_bsflag='B' THEN td_rate*Qty_NS ELSE 0.00 END), 
   SaleQty = CASE WHEN td_bsflag = 'S' THEN Qty_NS ELSE 0 END, 
   Rate = td_rate,  Cost = (CASE WHEN td_bsflag='S' THEN td_rate*Qty_NS ELSE 0.00 END),
   ISNULL(Tmp_112ARate,0), T112AFlag, ActualBuyRate, ISNULL(SQR_TAG,'N'), td_stt, Tmp_RefNo, td_Filler1
   FROM #tbl_DelvTrxn WHERE ISNULL(SQR_TAG,'N')='Y' and CASE WHEN td_bsflag='B' THEN Qty_NS ELSE 0 END > 0
   order by td_scripcd
   
   
   DECLARE @CH_ClgHs VARCHAR(1)=''

   SELECT @CH_ClgHs = (CASE WHEN CH_ClgHs = 'I' THEN 'B' ELSE CH_ClgHs END) FROM ClearingHouse(NOLOCK)
   WHERE CH_CompanyCode = @strCompanyCode AND CH_Segment = 'C' 
   AND CH_EffDt = (SELECT Min(CH_EffDt) FROM ClearingHouse
   WHERE CH_CompanyCode = @strCompanyCode AND CH_Segment = 'C' AND CH_EffDt <= @dtToDate) 

   CREATE TABLE #tbl_CloseRate (Scrip VARCHAR(20), CloseRate MONEY)
   
   CREATE INDEX INDX_CloseRate ON #tbl_CloseRate (Scrip) 
	
   INSERT INTO #tbl_CloseRate(Scrip, CloseRate)
   SELECT DISTINCT ScripCode, '' AS CloseRate FROM @tbl_HoldingRep

   IF @CH_ClgHs = 'N'
   BEGIN
	 UPDATE A SET A.CloseRate = B.mk_closerate
	 FROM #tbl_CloseRate A, Market_rates(NOLOCK) B 
	 WHERE A.Scrip = B.mk_scripcd AND mk_dt = (select  max(mk_dt) from Market_rates(NOLOCK)  
	 WHERE mk_dt<=@dtToDate AND  mk_exchange = 'B' ) AND  mk_exchange = 'B'
	  
	 UPDATE A SET A.CloseRate = B.mk_closerate
	 FROM #tbl_CloseRate A, Market_rates(NOLOCK) B 
	 WHERE A.Scrip = B.mk_scripcd 
	 AND mk_dt = (select  max(mk_dt) from Market_rates(NOLOCK)  
	 WHERE mk_dt<=@dtToDate  AND  mk_exchange = 'N' ) AND  mk_exchange = 'N'
   END  
   ELSE
   IF @CH_ClgHs = 'B'
   BEGIN
	 UPDATE A SET A.CloseRate = B.mk_closerate
	 FROM #tbl_CloseRate A, Market_rates(NOLOCK) B 
	 WHERE A.Scrip = B.mk_scripcd AND mk_dt = (select  max(mk_dt) from Market_rates(NOLOCK)  
	 WHERE mk_dt<=@dtToDate  AND  mk_exchange = 'N' ) AND  mk_exchange = 'N'
	  
	 UPDATE A SET A.CloseRate = B.mk_closerate
	 FROM #tbl_CloseRate A, Market_rates(NOLOCK) B 
	 WHERE A.Scrip = B.mk_scripcd 
	 AND mk_dt = (select  max(mk_dt) from Market_rates(NOLOCK)  
	 WHERE  mk_dt<=@dtToDate AND  mk_exchange = 'B' ) AND  mk_exchange = 'B'
   END  
   
   UPDATE A SET A.CloseRate = B.mk_closerate
   FROM #tbl_CloseRate A, Market_rates B
   WHERE mk_dt = (select  max(mk_dt) from Market_rates(NOLOCK)  
   WHERE mk_scripcd = B.mk_scripcd and mk_dt<=@dtToDate)
   AND A.Scrip = B.mk_scripcd	
   AND A.CloseRate = 0
   AND EXISTS(SELECT 1 FROM Securities(NOLOCK) 
   WHERE ss_cd = A.Scrip and ss_group in ('F','G','GC'))
   

   UPDATE A SET A.CloseRate = B.CloseRate, CurrentValue = BuyQty*B.CloseRate
   FROM @tbl_HoldingRep A, #tbl_CloseRate B
   WHERE A.ScripCode = B.Scrip
   DECLARE @XMLDATA1 XML
   IF @strRepType = 'Notional_Summary'
   BEGIN
     IF @strOutputType = 'X'
	 BEGIN
       SET @XMLDATA1 = (SELECT ClientCode, CLientName = M.cm_name, ScripCode, ScripName = SC.SS_NAME, BuyQty = SUM(BuyQty), 
	   BuyRate = ROUND((CASE WHEN SUM(BuyQty)<>0 THEN SUM(BuyValue)/SUM(BuyQty) ELSE 0 END),4), 
	   BuyValue = SUM(BuyValue), 
	   SaleQty = SUM(SaleQty), 
	   SaleRate = ROUND((CASE WHEN SUM(SaleQty)<>0 THEN SUM(SaleValue)/SUM(SaleQty) ELSE 0 END),2), 
	   SaleValue = SUM(SaleValue), 
	   CloseRate = MAX(CloseRate), CurrentValue = SUM(CurrentValue),
       ShortTerm = SUM(CASE WHEN SIGN(ABS(DATEDIFF(DAY, CAST(TradeDate AS DATE), CAST(getdate() AS DATE))) - 365) = 1 THEN '' ELSE CurrentValue - BuyValue
       END), 
	   LongTerm = SUM(CASE WHEN SIGN(ABS(DATEDIFF(DAY, CAST(TradeDate AS DATE), CAST(getdate() AS DATE))) - 365) = 1 THEN 
       CASE WHEN ((T112AFlag = 'Y') AND CloseRate < BuyRate) THEN 0 
       ELSE ((CloseRate - BuyRate) * BuyQty) END ELSE 0 END), T112AFlag, [A112A_Rate] = ISNULL(CAST(MAX(Tmp_112ARate) AS VARCHAR)+
	   (CASE WHEN T112AFlag='Y' THEN ' *' ELSE '' END),''),
	   [STT] = SUM((SaleQty+BuyQty)*td_stt)
       FROM @tbl_HoldingRep A, Client_master(NOLOCK) M, Securities(NOLOCK) SC  
       WHERE A.ClientCode = M.CM_CD AND A.ScripCode = SC.ss_cd
	   GROUP BY ClientCode, M.cm_name, ScripCode, SC.SS_NAME, T112AFlag
       ORDER BY ClientCode, SC.SS_NAME FOR XML PATH('CapGain'))
	   SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
	 END
     ELSE
     BEGIN
	   SELECT ClientCode, CLientName = M.cm_name, ScripCode, ScripName = SC.SS_NAME, BuyQty = SUM(BuyQty), 
	   BuyRate = ROUND((CASE WHEN SUM(BuyQty)<>0 THEN SUM(BuyValue)/SUM(BuyQty) ELSE 0 END),4), 
	   BuyValue = SUM(BuyValue), 
	   SaleQty = SUM(SaleQty), 
	   SaleRate = ROUND((CASE WHEN SUM(SaleQty)<>0 THEN SUM(SaleValue)/SUM(SaleQty) ELSE 0 END),2), 
	   SaleValue = SUM(SaleValue), 
	   CloseRate = MAX(CloseRate), CurrentValue = SUM(CurrentValue),
       ShortTerm = SUM(CASE WHEN SIGN(ABS(DATEDIFF(DAY, CAST(TradeDate AS DATE), CAST(getdate() AS DATE))) - 365) = 1 THEN '' ELSE CurrentValue - BuyValue
       END), 
	   LongTerm = SUM(CASE WHEN SIGN(ABS(DATEDIFF(DAY, CAST(TradeDate AS DATE), CAST(getdate() AS DATE))) - 365) = 1 THEN 
       CASE WHEN ((T112AFlag = 'Y') AND CloseRate < BuyRate) THEN 0 
       ELSE ((CloseRate - BuyRate) * BuyQty) END ELSE 0 END), T112AFlag, [A112A_Rate] = ISNULL(CAST(MAX(Tmp_112ARate) AS VARCHAR)+
	   (CASE WHEN T112AFlag='Y' THEN ' *' ELSE '' END),''),
	   [STT] = SUM((SaleQty+BuyQty)*td_stt)
       FROM @tbl_HoldingRep A, Client_master(NOLOCK) M, Securities(NOLOCK) SC  
       WHERE A.ClientCode = M.CM_CD AND A.ScripCode = SC.ss_cd
	   GROUP BY ClientCode, M.cm_name, ScripCode,  SC.SS_NAME, T112AFlag 
       ORDER BY ClientCode, ScripCode 
     END  	 
   END
   ELSE
   IF @strRepType = 'Notional_Detail'
   BEGIN
     IF @strOutputType = 'X'
	 BEGIN
       SET @XMLDATA1 = ( SELECT ClientCode, CLientName = M.cm_name, ScripCode, ScripName = SC.SS_NAME, TradeDate, td_SRNO, td_Stlmnt = isnull(td_Stlmnt,''), BuyQty, 
	   ActualBuyRate AS BuyRate, BuyValue, CloseRate, CurrentValue,
       ShortTerm = (CASE WHEN SIGN(ABS(DATEDIFF(DAY, CAST(TradeDate AS DATE), CAST(getdate() AS DATE))) - 365) = 1 
	   THEN '' ELSE CurrentValue - BuyValue
       END), 
	 --LongTerm = (CASE WHEN SIGN(ABS(DATEDIFF(DAY, CAST(TradeDate AS DATE), CAST(getdate() AS DATE))) - 365) = 1 
	 --THEN CurrentValue - BuyValue ELSE '' 
     --END), 
	   LongTerm = (CASE WHEN SIGN(ABS(DATEDIFF(DAY, CAST(TradeDate AS DATE), CAST(getdate() AS DATE))) - 365) = 1 THEN 
       CASE WHEN ((T112AFlag = 'Y') AND CloseRate < BuyRate) THEN 0 
       ELSE ((CloseRate - BuyRate) * BuyQty) END ELSE 0 END), 
	   PositionDays = ABS(DATEDIFF(DAY, CAST(TradeDate AS DATE), CAST(getdate() AS DATE))),
	   T112AFlag, [A112A_Rate] = ISNULL(CAST(Tmp_112ARate AS VARCHAR)+
	   (CASE WHEN T112AFlag='Y' THEN ' *' ELSE '' END),''), [STT] = (SaleQty+BuyQty)*td_stt, Tmp_RefNo, td_Filler1 , ISIN = im_isin
       FROM @tbl_HoldingRep A, Client_master(NOLOCK) M, Securities(NOLOCK) SC , Isin (NoLock)  
       WHERE A.ClientCode = M.CM_CD AND A.ScripCode = SC.ss_cd AND ISNULL(BuyQty,0) <> 0 AND SC.ss_cd = im_scripcd
       AND im_priority in (select min(im_priority) from isin(NOLOCK) where im_scripcd = SC.ss_cd)
       ORDER BY ClientCode, ScripCode, TradeDate FOR XML PATH('CapGain'))
	   SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
     END  
     ELSE
	 Begin
	  SELECT ClientCode, CLientName = M.cm_name, ScripCode, ScripName = SC.SS_NAME, TradeDate, BuyQty, 
	   ActualBuyRate AS BuyRate, BuyValue, CloseRate, CurrentValue,
       ShortTerm = (CASE WHEN SIGN(ABS(DATEDIFF(DAY, CAST(TradeDate AS DATE), CAST(getdate() AS DATE))) - 365) = 1 
	   THEN '' ELSE CurrentValue - BuyValue
       END), 
	 --LongTerm = (CASE WHEN SIGN(ABS(DATEDIFF(DAY, CAST(TradeDate AS DATE), CAST(getdate() AS DATE))) - 365) = 1 
	 --THEN CurrentValue - BuyValue ELSE '' 
     --END), 
	   LongTerm = (CASE WHEN SIGN(ABS(DATEDIFF(DAY, CAST(TradeDate AS DATE), CAST(getdate() AS DATE))) - 365) = 1 THEN 
       CASE WHEN ((T112AFlag = 'Y') AND CloseRate < BuyRate) THEN 0       ELSE ((CloseRate - BuyRate) * BuyQty) END ELSE 0 END), 
	   PositionDays = ABS(DATEDIFF(DAY, CAST(TradeDate AS DATE), CAST(getdate() AS DATE))),
	   T112AFlag, [A112A_Rate] = ISNULL(CAST(Tmp_112ARate AS VARCHAR)+
	   (CASE WHEN T112AFlag='Y' THEN ' *' ELSE '' END),''), [STT] = (SaleQty+BuyQty)*td_stt, ISIN = im_isin
       FROM @tbl_HoldingRep A, Client_master(NOLOCK) M, Securities(NOLOCK) SC  , Isin (NoLock) 
       WHERE A.ClientCode = M.CM_CD AND A.ScripCode = SC.ss_cd AND ISNULL(BuyQty,0) <> 0 AND SC.ss_cd = im_scripcd
       AND im_priority in (select min(im_priority) from isin(NOLOCK) where im_scripcd = SC.ss_cd)
       ORDER BY ClientCode, ScripCode, TradeDate
     END	 
    
	 --SET @o_vcErrorMessage = 'Process Completed'
   END	
   SET @o_vcErrorFlag  = 'S'
   RETURN 1   
END
GO

CREATE PROCEDURE stpr_Rpt_OtherReports @vcXML NVARCHAR(MAX), @o_vcErrorFlag VARCHAR(1) OUTPUT, 
@o_vcErrorMessage VARCHAR(MAX) OUTPUT 
WITH ENCRYPTION
AS
BEGIN
   /*
   ///////////////////////////////////////////////////////////////////////////////////////////
   // Create By     : VAIBHAV GARG
   // Created Date  : 22-FEB-2024
   // Description   : 
   // Reviewed By   : 
   // Review Date   : 
   //////////////////////////////////////////////////////////////////////////////////////////
   */
  DECLARE @dtFromDate VARCHAR(8), @strUserId VARCHAR(50), @strReportName VARCHAR(50), 
  @strOutputType VARCHAR(1)='', @XMLData XML,
  @strSelectTag VARCHAR(1)='', @strSelectUsers VARCHAR(500)='', @StrString VARCHAR(MAX)='', @SQ1 INT = 0,
  @strSplFilter VARCHAR(MAX)='', @strRepType VARCHAR(50)='', @dtToDate VARCHAR(8)='', 
  @strRepSubType VARCHAR(50), @strConsider112A VARCHAR(1)='N', @strProduct VARCHAR(50)='', 
  @strHeader VARCHAR(MAX)='', @strCommmexDB VARCHAR(MAX)='', @strDocType VARCHAR(100)='', @strDocNO VARCHAR(50) ,
  @XMLDATA1 NVARCHAR(MAX)='', @strScrip VARCHAR(20)='', @dtAsDate VARCHAR(20)='',@strCompanyCode varchar(1)  ,@strReportDisplay varchar(1) = 'P',
  @strProductcd VARCHAR(20)=''
  IF @vcXML = ''
  BEGIN
    SET @o_vcErrorFlag  = 'E'
    SET @o_vcErrorMessage = 'Please Send Input Parameter(s)'
    RETURN 1
  END 
  
  SET @XMLData = CAST('<root>'+@vcXML+'</root>' AS XML)
  
  SELECT @dtFromDate = ISNULL(x.value('(FromDt)[1]', 'VARCHAR(8)'),''),
  @strProduct = ISNULL(x.value('(Product)[1]', 'VARCHAR(50)'),''),
  @dtToDate = ISNULL(x.value('(ToDt)[1]', 'VARCHAR(8)'),''),
  @strUserId = ISNULL(x.value('(UserId)[1]', 'VARCHAR(500)'),''),
  @strSelectTag = ISNULL(x.value('(SelectTag)[1]', 'VARCHAR(1)'),''),
  @strSelectUsers = ISNULL(x.value('(SelectUsers)[1]', 'VARCHAR(500)'),''),
  @strOutputType = ISNULL(x.value('(OutputType)[1]', 'VARCHAR(1)'),''),
  @strSplFilter = ISNULL(x.value('(SplFilter)[1]', 'VARCHAR(MAX)'),''),
  @strReportName = ISNULL(x.value('(ReportName)[1]', 'VARCHAR(100)'),''),
  @strRepType = ISNULL(x.value('(RepType)[1]', 'VARCHAR(100)'),''),
  @strRepSubType = ISNULL(x.value('(RepSubType)[1]', 'VARCHAR(100)'),''),
  @strDocType = ISNULL(x.value('(DocumentType)[1]', 'VARCHAR(100)'),''),
  @strDocNO = ISNULL(x.value('(DocumentNo)[1]', 'VARCHAR(50)'),''),
  @strScrip = ISNULL(x.value('(ScripCode)[1]', 'VARCHAR(20)'),''),
  @dtAsDate = ISNULL(x.value('(AsDate)[1]', 'VARCHAR(8)'),''),
  @strCompanyCode = ISNULL(x.value('(CompanyCode)[1]', 'VARCHAR(1)'),''),
  @strReportDisplay  = ISNULL(x.value('(ReportDisplay)[1]', 'VARCHAR(1)'),''),
  @strProductcd  = ISNULL(x.value('(Productcd)[1]', 'VARCHAR(20)'),'')
  
  FROM @XMLData.nodes('/root') AS XTbl(x) 
  
  IF ISNULL(@strReportDisplay,'') = ''
  BEGIN
    SET @strReportDisplay = 'P'
  END  
  
  if ISNULL(@strScrip,'') = 'undefined'
  BEGIN
    SET @strScrip = ''
  END
  
  
  IF @strReportDisplay IN('D','E','A','X') AND EXISTS(SELECT 1 FROM CLIENT_MASTER(NOLOCK) WHERE CM_cD = @strUserId)
  BEGIN
    DECLARE @o_Message NVARCHAR(MAX)=''
    EXEC stpr_TypestHeaderProc @strUserid, '', '', @strCompanyCode,  @o_Message OUTPUT
	  
    SET @o_Message = REPLACE(@o_Message,'##ReportName##','Dividend Report for '  + CONVERT(VARCHAR(30), Cast(@dtFromDate as date), 103) + ' To ' + CONVERT(VARCHAR(30), Cast(@dtToDate as date), 103))
    SET @o_Message = REPLACE(@o_Message,'##Grid1##','')
    SET @o_Message = REPLACE(@o_Message,'##Grid2##','')
    SET @o_Message = REPLACE(@o_Message,'##Grid3##','')
    SET @o_Message = REPLACE(@o_Message,'##Grid4##','')
	SET @o_Message = REPLACE(@o_Message,'##PageOrientation##','Portrait')
	SET @o_Message = REPLACE(@o_Message,'##PageSize##','A4')
	--SET @o_Message = REPLACE(@o_Message,'##PageOrientation##','Landscape')
	IF @strReportDisplay IN('E','D','X')
	BEGIN
	  SET @o_Message = REPLACE(@o_Message,'##FormatGrid##','Grid1')
	  SET @strOutputType = 'G'
	END 
    ELSE 
	BEGIN
	  SET @o_Message = REPLACE(@o_Message,'##FormatGrid##','')
	END 
	
    SET @o_Message = '<root>' + @o_Message + '</root>';
  
    DECLARE @xmlData3 XML = CAST(@o_Message AS XML);
	
	DECLARE @DynamicColumns NVARCHAR(MAX);
    
	SET  @DynamicColumns = '';
  
	
    WITH DistinctNodes AS (
    SELECT DISTINCT
       NodeName = X.n.value('local-name(.)', 'NVARCHAR(100)')
    FROM @xmlData3.nodes('/root/ClientDetail/*') AS X(n))
    
    SELECT @DynamicColumns = @DynamicColumns+','+
        'LTRIM(RTRIM(X1.value(''(' + XX.NodeName + ')[1]'', ''NVARCHAR(MAX)''))) AS [' + XX.NodeName + ']'
    FROM DistinctNodes XX
	WHERE NodeName NOT IN('Grid2','Grid3','Grid4')
   
    SELECT @DynamicColumns = SUBSTRING(@DynamicColumns,2,LEN(@DynamicColumns)-1) 
  
    DECLARE @sql NVARCHAR(MAX);
    SET @sql = '
    SELECT ' + @DynamicColumns + '
    FROM @xmlData3.nodes(''/root/ClientDetail'') AS T(X1)';
  
    EXEC sp_executesql @sql, N'@xmlData3 XML', @xmlData3;
	
	IF @strReportDisplay NOT IN('A')
	BEGIN
	  SELECT ColumnName, ColumnHeading, ColumnWidth, ColumnAlignement, ColumnFormat, Columnstyle, DecimalPlace, ColumnTotal,
      ColumnHide = CASE WHEN Userid = '1' THEN 'Y' ELSE 'N'	END   
      FROM tbl_ReportGridViewFormat(NOLOCK) 
	  WHERE ReportCode='CapitalGain'
      and ReportCategroy = 'Dividend' AND ColumnVisible = '0'
      Order By Orderby
    END
  END	

  

  DECLARE @tbl_UserList TABLE(Client_Code VARCHAR(50), DPClientCode VARCHAR(50) )
  INSERT INTO @tbl_UserList(Client_Code) 
  SELECT * FROM DBO.[fn_GetClients](@strUserId,@strSelectTag,@strSelectUsers)
  
  IF ISNULL(@strProduct,'') =''
  BEGIN
    SET @strProduct = ''
  END
    
  SET @strHeader = 'DECLARE @tbl_UserList TABLE(Client_Code VARCHAR(50), DPClientCode VARCHAR(50) ) '

  
  SELECT @strCommmexDB = LTRIM(RTRIM(OP_DataBase)) FROM Other_Products(NOLOCK) WHERE OP_Product = 'Commex'
  and OP_Status = 'A'	
	
	
  DECLARE @strCrossCon VARCHAR(50)='', @strEstroCon VARCHAR(50)='', @strDefaultConn VARCHAR(50)='', 
  @strCrossServer VARCHAR(50), @strEstroServer VARCHAR(50),
  @strDefaultServer VARCHAR(50)=''
  
  SELECT @strCrossCon = RTRIM(LTRIM(OP_DataBase)), @strCrossServer = RTRIM(LTRIM(OP_Server))  
  FROM Other_Products(NOLOCK) where OP_Product = 'Cross' and RTRIM(LTRIM(op_status)) = 'A'
  
  SELECT @strEstroCon = RTRIM(LTRIM(OP_DataBase)), @strEstroServer = RTRIM(LTRIM(OP_Server))  
  FROM Other_Products(NOLOCK) where OP_Product = 'Estro' and RTRIM(LTRIM(op_status)) = 'A'
  
  IF @strCrossCon = ''
  BEGIN
    SET @strDefaultConn = @strEstroCon
	SET @strDefaultServer = @strEstroServer
  END
  ELSE
  BEGIN
    SET @strDefaultConn = @strCrossCon
	SET @strDefaultServer = @strCrossServer
  END
 
  IF @strSplFilter = ''
  BEGIN
    SET @strHeader = @strHeader+' INSERT INTO @tbl_UserList(Client_Code) '
    +' SELECT * FROM DBO.[fn_GetClients]('''+@strUserId+''','''+@strSelectTag+''','''+@strSelectUsers+''')'
  END 	 
  ELSE
  IF @strSplFilter <> ''
  BEGIN
    SET @strHeader = @strHeader+' INSERT INTO @tbl_UserList(Client_Code)  SELECT distinct CM_CD FROM Client_master(NOLOCK) WHERE 1 = 1  AND '+@strSplFilter
  END	
  SET @strHeader = @strHeader +' UPDATE A SET A.DPClientCode = B.da_actno FROM @tbl_UserList A, Dematact B WHERE A.Client_Code = B.da_clientcd AND da_defaultyn=''Y'' '
  SET @strHeader = @strHeader +' UPDATE A SET A.DPClientCode = A.Client_code FROM @tbl_UserList A WHERE  ISNULL(DPClientCode,'''') = '''''
  
  
  IF @strReportName = 'IPO_GETDATA'
  BEGIN
    SELECT IPO_Category, IPO_NSE_Symbol, IPO_Company_Name, convert(CHAR, convert(DATE, IPO_Start_Date), 103) AS start_date, convert(CHAR, convert
    (DATE, IPO_end_date), 103) AS end_date, convert(VARCHAR, IPO_min_price) + ' - ' + convert(VARCHAR, IPO_max_price) AS price_range, 
    IPO_min_order AS min_order, IPO_Size AS size, IPO_Tick_Size AS tick_size, IPO_RHP_Link AS rhp, IPO_Upi_Link AS upi, CASE WHEN convert(DATE, 
    IPO_Start_Date, 103) > CONVERT(DATE, getdate()) THEN 'Upcoming' WHEN convert(DATE, IPO_Start_Date, 103) <= CONVERT(DATE, getdate()) AND 
    convert(DATE, IPO_End_Date, 103) >= CONVERT(DATE, getdate()) THEN 'Apply' ELSE '' END AS 'status',
	IPO_Category_Descp = CASE WHEN IPO_Category = 'IND' THEN 'Individual Investor'
	                          WHEN IPO_Category = 'SHA' THEN 'Shareholder'
							  WHEN IPO_Category = 'CO' THEN 'Bodies Corporate'
							  WHEN IPO_Category = 'POL' THEN 'Policy Holder'
							  ELSE 'Individual Investor' END, IPO_Discount,
    [DPRemarks] = CASE WHEN ISNULL(AP.IPA_AppNo,'') <>'' THEN CASE ISNULL(IPA_DpStatus,'') WHEN 'P' THEN 'Pending' WHEN 'S' THEN 'Success' WHEN 'R' THEN 'Rejected </br> <b>Reason :</b> ' + ISNULL(IPA_DpRemark,'') ELSE '' END ELSE '' END,
    [BankRemarks] = CASE WHEN ISNULL(AP.IPA_AppNo,'') <>'' THEN CASE ISNULL(IPA_BnkPayStatus,'') WHEN '10' THEN '10- Request sent to UPI for acceptance' ELSE ISNULL(IPA_BnkRejectReason,'') END ELSE '' END,
	[ApplyFlag] = CASE WHEN ISNULL(AP.IPA_AppNo,'') <>'' THEN CASE WHEN (ISNULL(IPA_DpStatus,'') = 'R' OR 
	ISNULL(IPA_BnkPayStatus,'') in ('11','12','21','22','31') OR (ISNULL(IPA_DpStatus,'') = 'S' 
	AND ISNULL(IPA_BnkPayStatus,'') = '' AND ISNULL(IPA_BnkRejectReason,'') = 'PENDING SUBMISSION')) THEN 'Y' ELSE 'N' END ELSE 'Y' END,
	[StatusFlag] = CASE WHEN ISNULL(AP.IPA_AppNo,'') <>'' THEN CASE WHEN (ISNULL(IPA_DpStatus,'') = 'R' 
	OR ISNULL(IPA_BnkPayStatus,'') in ('11','12','21','22','31') OR (ISNULL(IPA_DpStatus,'') = 'S' AND ISNULL(IPA_BnkPayStatus,'') = '' 
	AND ISNULL(IPA_BnkRejectReason,'') = 'PENDING SUBMISSION')) THEN 'N' ELSE 'Y' END ELSE 'N' END,
	[DeleteFlag] = CASE WHEN ISNULL(AP.IPA_AppNo,'') <>'' THEN CASE WHEN ISNULL(IPA_BnkPayStatus,'') = '10' THEN 'Y' ELSE 'N' END ELSE 'N' END
    FROM IPOS(NOLOCK) x LEFT OUTER JOIN IPO_Application(NOLOCK) AP ON(X.IPO_NSE_Symbol = AP.IPA_ScripID AND IPA_Filler1 = IPO_Category
	AND IPA_AppNo <> '' AND IPA_ClientCd = @strUserId)
    WHERE CONVERT(DATE, getdate()) <= IPO_End_Date
    ORDER BY IPO_Start_Date ASC
  END
  ELSE
  IF @strReportName = 'OPENPOS'
  BEGIN
     IF @strProductcd <> 'CASH'
	 BEGIN
	   DECLARE @TBL_OPENPOS TABLE(ClientCode VARCHAR(50), sm_desc VARCHAR(100), po_posqty VARCHAR(100) ,  po_posValue VARCHAR(100), po_settleprice MONEY, po_futvalue MONEY, 
	   po_posActualValue MONEY)
       SET @StrString = @strHeader+' '+'SELECT po_clientcd, SS.sm_desc, po_posqty = CAST(CAST(ISNULL(po_postlongqty,0)-ISNULL(po_postshortqty,0) AS INT) AS VARCHAR)+'' ''+'
	   +' CASE WHEN ISNULL(po_postlongqty,0)-ISNULL(po_postshortqty,0) >0 THEN ''(Long Qty)'' else ''(Short Qty)'' end, '
	   +' po_posValue = CAST(CAST(ISNULL(po_postlongqty,0)-ISNULL(po_postshortqty,0) AS INT)*po_settleprice AS VARCHAR)+'' ''+ '
	   +' CASE WHEN ISNULL(po_postlongqty,0)-ISNULL(po_postshortqty,0) >0 THEN ''(Long Value)'' else ''(Short Value)'' end, '
	   +' po_settleprice, po_futvalue = ISNULL(po_futvalue,0)+ISNULL(po_Diffvalue,0)+ISNULL(po_netpremium,0), CAST(CAST(ISNULL(po_postlongqty,0)-ISNULL(po_postshortqty,0) AS INT)*po_settleprice AS MONEY)'
       +' FROM Fpositions(NOLOCK) X, Series_master SS , @tbl_UserList X1 '
       +' WHERE po_clientcd = X1.Client_Code and sm_expirydt >= '''+@dtAsDate+''''
       +' AND ((po_dt IN(SELECT MAX(po_dt) FROM Fpositions(NOLOCK) WHERE po_companycode = X.po_companycode '
       +' AND po_exchange = X.po_exchange AND po_Segment = X.po_Segment) AND '''+ISNULL(@dtAsDate,'')+''' = '''') '
	   +' OR ('''+ISNULL(@dtAsDate,'')+''' <> '''' AND po_dt IN(SELECT MAX(po_dt) FROM Fpositions(NOLOCK) WHERE po_companycode = X.po_companycode '
       +' AND po_exchange = X.po_exchange AND po_Segment = X.po_Segment AND po_dt <= '''+@dtAsDate+''') ))'
       +' AND X.po_seriesid = SS.sm_seriesid AND X.po_exchange = SS.sm_exchange AND X.po_Segment = SS.sm_Segment '
	   
       --+' AND po_postlongqty+po_postshortqty <> 0 '
	   BEGIN TRY
	     IF @strProductcd = 'DERV'
		 BEGIN
		   INSERT INTO @TBL_OPENPOS
	       EXEC(@StrString)
		 END
		 IF  @strProductcd ='COMM'
		 BEGIN
	       IF ISNULL(@strCommmexDB,'') <> ''
		   BEGIN
	         SET @StrString = @strHeader+' '+'SELECT po_clientcd, SS.sm_desc, po_posqty = CAST(CAST(ISNULL(po_postlongqty,0)-ISNULL(po_postshortqty,0) AS INT) AS VARCHAR)+'' ''+'
	         +' CASE WHEN ISNULL(po_postlongqty,0)-ISNULL(po_postshortqty,0) >0 THEN ''(Long Qty)'' else ''(Short Qty)'' end, '
	         +' po_posValue = CAST(CAST(ISNULL(po_postlongqty,0)-ISNULL(po_postshortqty,0) AS INT)*ISNULL(sm_multiplier,1)*po_settleprice AS VARCHAR)+'' ''+ '
	         +' CASE WHEN ISNULL(po_postlongqty,0)-ISNULL(po_postshortqty,0) >0 THEN ''(Long Value)'' else ''(Short Value)'' end, '
	         +' po_settleprice, po_futvalue = ISNULL(po_futvalue,0)+ISNULL(po_Diffvalue,0)+ISNULL(po_netpremium,0), CAST(CAST(ISNULL(po_postlongqty,0)-ISNULL(po_postshortqty,0) AS INT)*ISNULL(sm_multiplier,1)*po_settleprice AS MONEY)'
             +' FROM '+@strCommmexDB+'.DBO.Fpositions(NOLOCK) X, '+@strCommmexDB+'.DBO.Series_master SS , @tbl_UserList X1 '
             +' WHERE po_clientcd = X1.Client_Code and sm_expirydt >= '''+@dtAsDate+''''
             +' AND ((po_dt IN(SELECT MAX(po_dt) FROM '+@strCommmexDB+'.DBO.Fpositions(NOLOCK) WHERE po_companycode = X.po_companycode '
             +' AND po_exchange = X.po_exchange) AND '''+ISNULL(@dtAsDate,'')+''' = '''') '
	         +' OR ('''+ISNULL(@dtAsDate,'')+''' <> '''' AND po_dt IN(SELECT MAX(po_dt) FROM '+@strCommmexDB+'.DBO.Fpositions(NOLOCK) WHERE po_companycode = X.po_companycode '
             +' AND po_exchange = X.po_exchange  AND po_dt <= '''+@dtAsDate+''') ))'
             +' AND X.po_seriesid = SS.sm_seriesid AND X.po_exchange = SS.sm_exchange  '
		    INSERT INTO @TBL_OPENPOS
	        EXEC(@StrString)
		  END
		 END

		 IF @strOutputType = 'X'
		  BEGIN
		    SET @XMLDATA1 = 
		   (SELECT A.*, CM_NAME AS CLIENTNAME FROM @TBL_OPENPOS A, CLIENT_MASTER M
            WHERE A.ClientCode = M.CM_CD 		   
		    order by sm_desc  
		    FOR XML PATH('OSPosition'))
	        SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
			RETURN 1
		  END
		  ELSE
		  BEGIN
		    SELECT * FROM @TBL_OPENPOS  
		    ORDER BY sm_desc  
		  END 
	     SET @o_vcErrorFlag  = 'S'
         SET @o_vcErrorMessage = 'Process Executed'
	     RETURN 1
	   END TRY
	   BEGIN CATCH
	     SET @o_vcErrorFlag  = 'E'
         SET @o_vcErrorMessage = ERROR_MESSAGE()
         RETURN 1
	   END CATCH
    END
  END	
  ELSE
  IF @strReportName = 'MARGIN_NEW'
  BEGIN
	 DECLARE @TBL_COLLPOSMARGIN TABLE(ClientCode VARCHAR(50), ClientName VARCHAR(100),
	 CashMargin MONEY NOT NULL DEFAULT 0, FnoMarin MONEY NOT NULL DEFAULT 0, CurrencyMargin MONEY NOT NULL DEFAULT 0, 
	 CommodityMargin  MONEY NOT NULL DEFAULT 0, 
	 TotalMargin MONEY NOT NULL DEFAULT 0, CashColl MONEY NOT NULL DEFAULT 0, Pledge MONEY NOT NULL DEFAULT 0, 
	 TotalColl MONEY NOT NULL DEFAULT 0, ExcessShortage MONEY NOT NULL DEFAULT 0)
	 
	 
	 
	 INSERT INTO @TBL_COLLPOSMARGIN(ClientCode)
	 SELECT Client_Code FROM @tbl_UserList
	 
 
	 UPDATE A SET A.Pledge = B.Pledge
	 FROM @TBL_COLLPOSMARGIN A, (SELECT Client_Code, Pledge = SUM(ROUND(((FOCOLL*ClosingPrice) * (100-Haircut))/100,2))
	 FROM tbl_DBHoldingDtl(NOLOCK) x, Securities S, @tbl_UserList X1  WHERE  FOCOLL <> 0 
	 AND X.ScripCode = S.ss_cd AND ClientCode  = X1.Client_Code 
	 GROUP BY Client_Code) B
	 WHERE A.ClientCode = B.Client_Code
	 
	 UPDATE A SET A.CashColl = B.Amount
	 FROM @TBL_COLLPOSMARGIN A,(
     SELECT ld_clientcd, Amount = SUM(LD_AMOUNT)*-1 FROM ledger(NOLOCK)
     WHERE ld_clientcd = @strUserId
     Group By ld_clientcd
     --HAVING SUM(LD_AMOUNT) <= 0
	 ) B
     WHERE A.ClientCode = B.ld_clientcd
	 
	 
	 UPDATE A SET A.CashMargin = B.fm_TotalMrgn
	 FROM @TBL_COLLPOSMARGIN A, (Select * from Fmargins(NOLOCK)
     WHERE fm_dt IN(SELECT MAX(fm_dt) FROM Fmargins)
     and fm_Segment = 'C') B
	 WHERE A.ClientCode = B.fm_clientcd
	 
	 UPDATE A SET A.FnoMarin = B.fm_TotalMrgn
	 FROM @TBL_COLLPOSMARGIN A, (Select * from Fmargins(NOLOCK)
     WHERE fm_dt IN(SELECT MAX(fm_dt) FROM Fmargins)
     and fm_Segment = 'F') B
	 WHERE A.ClientCode = B.fm_clientcd
	 
	 UPDATE A SET A.CurrencyMargin = B.fm_TotalMrgn
	 FROM @TBL_COLLPOSMARGIN A, (Select * from Fmargins(NOLOCK)
     WHERE fm_dt IN(SELECT MAX(fm_dt) FROM Fmargins)
     and fm_Segment = 'K') B
	 WHERE A.ClientCode = B.fm_clientcd
	 
	 IF ISNULL(@strCommmexDB,'') <> ''
	 BEGIN
	   DECLARE @strStringCOmm NVARCHAR(MAX)=''
	   DECLARE @tbl_CommodityMargin TABLE(ClientCode VARCHAR(50), InitialMargin MONEY, MTMLOSS MONEY)
	   
	   DECLARE @tbl_CommodityMTMMargin TABLE(ClientCode VARCHAR(50), MTMLOSS MONEY)
	   
	   SET @strStringCOmm = 'SELECT fm_clientcd, (case fm_exchange When ''M'' Then fm_Regmargin + fm_exposurevalue + fm_buypremmargin else fm_initialmargin + fm_exposurevalue end) '
       +' fm_initialmargin,   case fm_Exchange When ''M'' Then fm_additionalmargin + fm_Tndmargin + fm_Dlvmargin - fm_SpreadBen + fm_ConcMargin + fm_DelvPMargin '
       +' else fm_additionalmargin + fm_SplMargin end+0 fm_MTMLoss '
       +' from '+@strCommmexDB+'.DBO.fmargins '
       +' Where fm_dt IN(SELECT MAX(fm_dt) FROM '+@strCommmexDB+'.DBO.fmargins) '
       
	   INSERT INTO @tbl_CommodityMargin(ClientCode, InitialMargin, MTMLOSS)
	   EXEC(@strStringCOmm)
	   
       SET @strStringCOmm = ' Select po_clientcd, case When -sum(po_futvalue) > 0 Then -sum(po_futvalue) else 0 end fm_MTMLoss '
	   +' FROM '+@strCommmexDB+'.DBO.Fpositions '
       +' Where po_dt IN(SELECT MAX(po_dt) FROM '+@strCommmexDB+'.DBO.Fpositions) '
       +' Group by po_clientcd '
	   
	   INSERT INTO @tbl_CommodityMTMMargin(ClientCode, MTMLOSS)
	   EXEC(@strStringCOmm)
	   
	   UPDATE A SET A.MTMLOSS = ISNULL(A.MTMLOSS,0) + ISNULL(B.MTMLOSS,0)
	   FROM @tbl_CommodityMargin A, @tbl_CommodityMTMMargin B
	   WHERE A.ClientCode = B.ClientCode
	   
	 END
	 
	 UPDATE A SET A.CommodityMargin = ISNULL(B.InitialMargin,0)+ISNULL(B.MTMLOSS,0)
	 FROM @TBL_COLLPOSMARGIN A, @tbl_CommodityMargin B
	 WHERE A.ClientCode = B.ClientCode
	 
	 UPDATE A SET A.TotalMargin = ISNULL(A.CashMargin,0)+ISNULL(A.FnoMarin,0)+ISNULL(A.CurrencyMargin,0)+ISNULL(A.CommodityMargin,0),
	 ExcessShortage = (ISNULL(CashColl,0)+ISNULL(Pledge,0)) - (ISNULL(A.CashMargin,0)+ISNULL(A.FnoMarin,0)+ISNULL(A.CurrencyMargin,0)+ISNULL(A.CommodityMargin,0)),
	 A.TotalColl = ISNULL(CashColl,0)+ISNULL(Pledge,0)
	 FROM @TBL_COLLPOSMARGIN A
	 
	 UPDATE A SET A.ClientName = M.CM_NAME
	 FROM @TBL_COLLPOSMARGIN A, CLIENT_MASTER(NOLOCK) M
	 WHERE A.ClientCode = M.CM_cD
	 
	 /*
	 DELETE FROM @TBL_COLLPOSMARGIN WHERE ClientCode NOT IN(
	 Select fm_clientcd from Fmargins(NOLOCK)
     WHERE fm_dt IN(SELECT MAX(fm_dt) FROM Fmargins))
	 */
	 
	 IF @strOutputType = 'X'
	 BEGIN
	   SET @XMLDATA1 = (SELECT * FROM @TBL_COLLPOSMARGIN 
		                FOR XML PATH('MARGIN'))
	    SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
		RETURN 1
	  END
	  ELSE
	  BEGIN
		SELECT * FROM @TBL_COLLPOSMARGIN  
	  END 
	  SET @o_vcErrorFlag  = 'S'
      SET @o_vcErrorMessage = 'Process Executed'
	  RETURN 1
  END	
  ELSE
  IF @strReportName = 'MARGIN2'
  BEGIN
     DECLARE @TBL_COLLPOSMARGIN2 TABLE(ClientCode VARCHAR(50), ClientName VARCHAR(100),
	 CashColl MONEY NOT NULL DEFAULT 0, Pledge MONEY NOT NULL DEFAULT 0,
	 TotalColl MONEY NOT NULL DEFAULT 0)
	 
	 INSERT INTO @TBL_COLLPOSMARGIN2(ClientCode)
	 SELECT Client_Code FROM @tbl_UserList
	 
	 
	 UPDATE A SET A.Pledge = B.Pledge
	 FROM @TBL_COLLPOSMARGIN2 A, (SELECT Client_Code, Pledge = SUM(ROUND(((FOCOLL*ClosingPrice) * (100-Haircut))/100,2))
	 FROM tbl_DBHoldingDtl(NOLOCK) x, Securities S, @tbl_UserList X1  WHERE  FOCOLL <> 0 
	 AND X.ScripCode = S.ss_cd AND ClientCode  = X1.Client_Code 
	 GROUP BY Client_Code) B
	 WHERE A.ClientCode = B.Client_Code
	 
	 UPDATE A SET A.CashColl = B.Amount
	 FROM @TBL_COLLPOSMARGIN2 A,(
     SELECT ld_clientcd, Amount = SUM(LD_AMOUNT)*-1 FROM ledger(NOLOCK)
     WHERE ld_clientcd = @strUserId
     Group By ld_clientcd
     --HAVING SUM(LD_AMOUNT) <= 0
	 ) B
     WHERE A.ClientCode = B.ld_clientcd
 	 
	 UPDATE A SET A.TotalColl = ISNULL(A.Pledge,0)+ISNULL(A.CashColl,0)
	 FROM @TBL_COLLPOSMARGIN2 A
	 
	  UPDATE A SET A.ClientName = M.CM_NAME
	 FROM @TBL_COLLPOSMARGIN2 A, CLIENT_MASTER(NOLOCK) M
	 WHERE A.ClientCode = M.CM_cD
	 
	  DELETE FROM @TBL_COLLPOSMARGIN2 WHERE ClientCode NOT IN(
	 Select fm_clientcd from Fmargins(NOLOCK)
     WHERE fm_dt IN(SELECT MAX(fm_dt) FROM Fmargins))
	 
	 IF @strOutputType = 'X'
	 BEGIN
	   SET @XMLDATA1 = (SELECT * FROM @TBL_COLLPOSMARGIN2 
		                FOR XML PATH('MARGIN'))
	    SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
		RETURN 1
	  END
	  ELSE
	  BEGIN
		SELECT * FROM @TBL_COLLPOSMARGIN2  
	  END 
	  SET @o_vcErrorFlag  = 'S'
      SET @o_vcErrorMessage = 'Process Executed'
	  RETURN 1
  END	
  ELSE
  IF @strReportName = 'MARGIN1'
  BEGIN
	 DECLARE @TBL_COLLPOSMARGIN1 TABLE(ClientCode VARCHAR(50), ClientName VARCHAR(100),
	 CashMargin MONEY NOT NULL DEFAULT 0, FnoMarin MONEY NOT NULL DEFAULT 0, CurrencyMargin MONEY NOT NULL DEFAULT 0, 
	 TotalMargin MONEY NOT NULL DEFAULT 0)
	 
	 INSERT INTO @TBL_COLLPOSMARGIN1(ClientCode)
	 SELECT Client_Code FROM @tbl_UserList
	 
	 /*
	 UPDATE A SET A.Pledge = B.Pledge
	 FROM @TBL_COLLPOSMARGIN A, (SELECT Client_Code, Pledge = SUM(ROUND(((FOCOLL*ClosingPrice) * (100-Haircut))/100,2))
	 FROM tbl_DBHoldingDtl(NOLOCK) x, Securities S, @tbl_UserList X1  WHERE  FOCOLL <> 0 
	 AND X.ScripCode = S.ss_cd AND ClientCode  = X1.Client_Code 
	 GROUP BY Client_Code) B
	 WHERE A.ClientCode = B.Client_Code
	 
	 UPDATE A SET A.CashColl = B.Amount
	 FROM @TBL_COLLPOSMARGIN A,(
     SELECT ld_clientcd, Amount = SUM(LD_AMOUNT)*-1 FROM ledger(NOLOCK)
     WHERE ld_clientcd = @strUserId
     Group By ld_clientcd
     --HAVING SUM(LD_AMOUNT) <= 0
	 ) B
     WHERE A.ClientCode = B.ld_clientcd
	 */
	 
	 UPDATE A SET A.CashMargin = B.fm_TotalMrgn
	 FROM @TBL_COLLPOSMARGIN1 A, (Select * from Fmargins(NOLOCK)
     WHERE fm_dt IN(SELECT MAX(fm_dt) FROM Fmargins)
     and fm_Segment = 'C') B
	 WHERE A.ClientCode = B.fm_clientcd
	 
	 UPDATE A SET A.FnoMarin = B.fm_TotalMrgn
	 FROM @TBL_COLLPOSMARGIN1 A, (Select * from Fmargins(NOLOCK)
     WHERE fm_dt IN(SELECT MAX(fm_dt) FROM Fmargins)
     and fm_Segment = 'F') B
	 WHERE A.ClientCode = B.fm_clientcd
	 
	 UPDATE A SET A.CurrencyMargin = B.fm_TotalMrgn
	 FROM @TBL_COLLPOSMARGIN1 A, (Select * from Fmargins(NOLOCK)
     WHERE fm_dt IN(SELECT MAX(fm_dt) FROM Fmargins)
     and fm_Segment = 'K') B
	 WHERE A.ClientCode = B.fm_clientcd
	 
	 UPDATE A SET A.TotalMargin = ISNULL(A.CashMargin,0)+ISNULL(A.FnoMarin,0)+ISNULL(A.CurrencyMargin,0)
	 FROM @TBL_COLLPOSMARGIN1 A
	 
	UPDATE A SET A.ClientName = M.CM_NAME
	 FROM @TBL_COLLPOSMARGIN1 A, CLIENT_MASTER(NOLOCK) M
	 WHERE A.ClientCode = M.CM_cD
	 
	   DELETE FROM @TBL_COLLPOSMARGIN1 WHERE ClientCode NOT IN(
	 Select fm_clientcd from Fmargins(NOLOCK)
     WHERE fm_dt IN(SELECT MAX(fm_dt) FROM Fmargins))
	 
	 IF @strOutputType = 'X'
	 BEGIN
	   SET @XMLDATA1 = (SELECT * FROM @TBL_COLLPOSMARGIN1 
		                FOR XML PATH('MARGIN'))
	    SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
		RETURN 1
	  END
	  ELSE
	  BEGIN
		SELECT * FROM @TBL_COLLPOSMARGIN1  
	  END 
	  SET @o_vcErrorFlag  = 'S'
      SET @o_vcErrorMessage = 'Process Executed'
	  RETURN 1
  END	
  ELSE
  IF @strReportName = 'COLLPOS'
  BEGIN
     DECLARE @TBL_COLLPOS TABLE(ClientCode VARCHAR(50),
	 ScripCode VARCHAR(20), ScripName VARCHAR(100), ISIN VARCHAR(20), CashEqFlag VARCHAR(10),
	 PledgeQty MONEY, ClosingPrice MONEY, MarketValue MONEY, Haircut MONEY, HaricutValue MONEY)
     
	 
	 SET @StrString = @strHeader+' '+'SELECT ClientCode, ScripCode, ss_name AS ScripName, ISIN, '
	 +' CASE WHEN (SELECT COUNT(*) FROM SecurityCashEq(NOLOCK) WHERE isnull(sce_filler1,'''') = '''' and sce_scripcd =X.ScripCode) > 0 '
	 +' THEN ''Yes'' else ''No'' end as CashEqFlag, FOCOLL As PledgeQty, ClosingPrice = ROUND(ClosingPrice,2) ,'
	 +' ROUND(FOCOLL*ClosingPrice,2) As MarketValue, Haircut, '
	 +' ROUND(((FOCOLL*ClosingPrice) * (100-Haircut))/100,2) as HaricutValue '
	 +' FROM tbl_DBHoldingDtl(NOLOCK) x, Securities S, @tbl_UserList X1  WHERE  FOCOLL <> 0 '
	 +' AND X.ScripCode = S.ss_cd AND ClientCode  = X1.Client_Code '
	 +' Order By ScripName '
	 BEGIN TRY
	   --SELECT @StrString
	   INSERT INTO @TBL_COLLPOS
	   EXEC(@StrString)
		 
	  IF @strOutputType = 'X'
	  BEGIN
		SET @XMLDATA1 = (SELECT A.*, CLIENTNAME = CM_NAME 
		                   FROM @TBL_COLLPOS A, CLIENT_MASTER(NOLOCK) M
                          WHERE A.ClientCode = M.CM_cD		
		               ORDER BY ClientCode, ScripName FOR XML PATH('COLLPOS'))
	    SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
		RETURN 1
	  END
	  ELSE
	  BEGIN
		SELECT * FROM @TBL_COLLPOS  
		ORDER BY ScripName  
	  END 
	  SET @o_vcErrorFlag  = 'S'
      SET @o_vcErrorMessage = 'Process Executed'
	  RETURN 1
	END TRY
	BEGIN CATCH
	  SET @o_vcErrorFlag  = 'E'
      SET @o_vcErrorMessage = ERROR_MESSAGE()
      RETURN 1
	END CATCH
  END	
  ELSE
  IF @strReportName = 'TradeListing'
  BEGIN
    IF @strRepType = 'SUMMARY'
	BEGIN
      SET @StrString = @strHeader+' '+'SELECT td_scripcd ,Rtrim(ss_lname) AS ScripName ,convert(DECIMAL(15, 0), sum(td_bqty)) Bqty, '
	  +' convert(DECIMAL(15, 2), '
	  +' CASE WHEN sum(td_rate * td_bqty) > 0 THEN sum(td_rate * td_bqty) / sum(td_bqty) ELSE 0 END) BRate '
	  +' ,convert(DECIMAL(15, 2), sum(td_bqty * td_rate)) BAmt ,convert(DECIMAL(15, 0), sum(td_sqty)) sqty '
	  +' ,convert(DECIMAL(15, 2), '
	  +' CASE WHEN sum(td_rate * td_sqty) > 0 THEN sum(td_rate * td_sqty) / sum(td_sqty) ELSE 0 END) SRate '
	  +' ,convert(DECIMAL(15, 2), sum(td_sqty * td_rate)) SAmt ' 
	  +' ,convert(DECIMAL(15, 0), sum(td_bqty - td_sqty)) NetQty '
	  +' ,convert(DECIMAL(15, 2), sum((td_bqty - td_sqty) * td_rate)) NAmt '
      +' FROM TRX_INVPL(NOLOCK) ,Securities(NOLOCK), @tbl_UserList X '
      +' WHERE td_clientcd = X.Client_Code '
	  +' AND td_scripcd = ss_cd '
	  +' AND td_dt BETWEEN '''+@dtFromDate+''''
	  +' AND '''+@dtToDate+''' GROUP BY td_scripcd ,Rtrim(ss_lname) ORDER BY Rtrim(ss_lname) '
	  BEGIN TRY
	    EXEC(@StrString)
		SET @o_vcErrorFlag  = 'S'
        SET @o_vcErrorMessage = 'Process Executed'
		RETURN 1
	  END TRY
	  BEGIN CATCH
	    SET @o_vcErrorFlag  = 'E'
        SET @o_vcErrorMessage = ERROR_MESSAGE()
        RETURN 1
	  END CATCH
    END
	ELSE IF @strRepType = 'DETAIL'
	BEGIN
	  SET @StrString = @strHeader+' '+'select td_srno, td_TRXFlag, case td_TRDType when '
	  +' ''DL'' then ''Delivery'' When ''SQ'' then ''Jobbing'' else '''' end  td_TRDType , '
      +' ltrim(rtrim(convert(char,convert(datetime,td_dt),103))) as td_dt,td_scripcd, Rtrim(ss_lname) AS ScripName, td_stlmnt , '
      +' case td_bsflag when ''B'' then ''Buy'' when ''S'' then ''Sell'' else '''' end td_bsflag , '
      +' convert(decimal(15,0) , td_bqty+td_sqty) as Qty,  '
      +' convert(decimal(15,2) ,td_Rate) td_Rate,convert(decimal(15,2) ,td_Rate*(td_bqty+td_sqty)) Value , '
	  +' convert(decimal(15,2) ,td_ServiceTax*(td_bqty+td_sqty)) td_ServiceTax, '
      +' convert(decimal(15,2) ,td_STT *(td_bqty+td_sqty)) td_STT,convert(decimal(15,2) ,td_OtherChrgs1*(td_bqty+td_sqty)) td_OtherChrgs1,'
	  +' convert(decimal(15,2) ,td_OtherChrgs2*(td_bqty+td_sqty)) td_OtherChrgs2  '
      +' FROM TRX_INVPL(NOLOCK),Securities(NOLOCK), @tbl_UserList X '
      +' WHERE td_clientcd = X.Client_Code '
	  +' and td_scripcd = ss_cd '
      +' and ((td_scripcd = '''+@strScrip+''' AND ISNULL('''+@strScrip+''','''') <> '''') OR ISNULL('''+@strScrip+''','''') = '''')' 
	  +' AND td_dt BETWEEN '''+@dtFromDate+''''
	  +' AND '''+@dtToDate+''' order by  CONVERT (char,convert(datetime,td_dt),112) '
	  BEGIN TRY
	    --SELECT @StrString
	    EXEC(@StrString)
		SET @o_vcErrorFlag  = 'S'
        SET @o_vcErrorMessage = 'Process Executed'
		RETURN 1
	  END TRY
	  BEGIN CATCH
	    SET @o_vcErrorFlag  = 'E'
        SET @o_vcErrorMessage = ERROR_MESSAGE()
        RETURN 1
	  END CATCH
	END
  END	
  ELSE
  IF @strReportName = 'Confirmation'
  BEGIN
    IF @strRepType = 'Cumulative'
	BEGIN
	  SET @StrString = @strHeader+' '+'SELECT * FROM (
	  SELECT 1 AS SortOrder, ''Equity : '' + td_stlmnt AS type, td_stlmnt stlmnt, td_scripcd scripcode, replace(rtrim
				(ss_Name) + '' ('' + td_scripcd + '')'', ''&'', '''') scripname, sum(td_bqty) ''Buy'', sum(convert(DECIMAL(15, 2), 
				convert(MONEY, td_bqty * td_rate))) ''BuyAmount'', sum(td_sqty) ''Sell'', 
				sum(convert(DECIMAL(15, 4), convert(MONEY, td_sqty * td_rate))) ''SellAmount'', sum(td_bqty - td_sqty) ''Net''
			, sum(convert(DECIMAL(15, 4), convert(MONEY, (td_sqty - td_bqty) * td_rate))
			) ''NetAmount'', cast(convert(MONEY, CASE WHEN sum(td_bqty - td_sqty) = 0 THEN 0 ELSE sum((td_bqty - td_sqty) 
			* td_rate) / sum(td_bqty - td_sqty) END) AS DECIMAL(15, 2)) ''AvgRate'', cast(
				sum(td_brokerage * (td_bqty + td_sqty)) AS DECIMAL(15, 4)) Brokerage, left(
				td_stlmnt, 1) + ''/C/'' + td_scripcd ''Lookup''
	  FROM trx(NOLOCK), securities(NOLOCK), Settlements(NOLOCK), @tbl_UserList X
	  WHERE td_clientcd = X.Client_Code AND td_stlmnt = se_stlmnt AND td_scripcd = ss_cd AND td_dt >= '''+@dtFromDate+'''
	  AND td_dt <= '''+@dtToDate+'''
	  GROUP BY ''Equity : '' + td_stlmnt, td_stlmnt, td_scripcd, ss_Name, td_dt
	  UNION ALL
	  SELECT CASE right(sm_prodtype, 1) WHEN ''F'' THEN 2 ELSE 3 END, ''Equity '' + CASE right(sm_prodtype, 1) WHEN ''F'' THEN 
						''Future'' ELSE ''Option'' END td_type, ''Exp: '' + convert(CHAR(10), convert(DATETIME, 
					sm_expirydt), 105), td_seriesid scripcode, replace(rtrim(sm_symbol) + CASE right(
						sm_prodtype, 1) WHEN ''F'' THEN '''' ELSE '' ('' + ltrim(convert(CHAR(8), sm_strikeprice)) + 
						sm_callput + sm_optionstyle + '')'' END, ''&'', ''''), sum(td_bqty) ''bqty'', sum(convert(DECIMAL(
						15, 2), convert(MONEY, td_bqty * td_rate))) ''bvalue'', sum(td_sqty) ''sqty'', sum(convert(
					DECIMAL(15, 4), convert(MONEY, td_sqty * td_rate))) ''svalue'', sum(td_bqty - td_sqty) ''netqty'', 
			sum(convert(DECIMAL(15, 4), convert(MONEY, (td_sqty - td_bqty) * td_rate))) 
			''netvalue'', cast(convert(MONEY, CASE WHEN sum(td_bqty - td_sqty) = 0 THEN 0 ELSE sum((td_bqty - td_sqty
									) * td_rate) / sum(td_bqty - td_sqty) END) AS DECIMAL(15, 2)) ''average'', cast(
				sum(td_brokerage * (td_bqty + td_sqty)) AS DECIMAL(15, 4)) td_brokerage, 
			td_Exchange + ''/'' + td_Segment + ''/'' + Ltrim(convert(CHAR, td_seriesid))
	  FROM trades(NOLOCK), series_master WITH (NOLOCK), @tbl_UserList X
	  WHERE td_clientcd = X.Client_Code AND td_seriesid = sm_seriesid AND td_Exchange = sm_exchange AND td_Segment = 
			sm_Segment AND td_dt >= '''+@dtFromDate+''' AND td_dt <= '''+@dtToDate+''' AND td_segment IN (''F'') 
	  GROUP BY sm_prodtype, sm_symbol, sm_desc, sm_expirydt, sm_strikeprice, sm_callput, sm_optionstyle, td_dt, 
			td_Exchange, td_Segment, td_seriesid
	  UNION ALL
	  SELECT CASE ex_eaflag WHEN ''E'' THEN 4 ELSE 5 END, CASE ex_eaflag WHEN ''E'' THEN ''Exercise'' ELSE ''Assignment'' END 
			Td_Type, ''Exp: '' + convert(CHAR(10), convert(DATETIME, sm_expirydt), 105), ltrim(convert(CHAR(8), 
					sm_strikeprice)) + sm_callput, replace(rtrim(sm_symbol) + '' ('' + ltrim(convert(CHAR(8), 
						sm_strikeprice)) + sm_callput + sm_optionstyle + '')'', ''&'', ''''), sum(ex_aqty) Bqty, sum(
				ex_aqty * ex_diffrate) BAmt, sum(ex_eqty) Sqty, sum(ex_eqty * ex_diffrate) SAmt, sum(ex_aqty - 
				ex_eqty) NQty, sum((ex_aqty - ex_eqty) * ex_diffrate) NAmt, cast(convert(MONEY, 
					CASE WHEN sum(ex_aqty - ex_eqty) = 0 THEN 0 ELSE sum((ex_aqty - ex_eqty
									) * ex_diffrate) / sum(ex_aqty - ex_eqty) END) AS DECIMAL(15, 2)) ''average'', 
			cast(sum(ex_brokerage * (ex_eqty + ex_aqty)) AS DECIMAL(15, 4)) td_Brokerage, 
			ex_exchange + ''/'' + ex_Segment + ''/'' + Ltrim(convert(CHAR, ex_seriesid))
	  FROM exercise (NOLOCK), series_master (NOLOCK), @tbl_UserList X
	  WHERE ex_clientcd = X.Client_Code AND ex_exchange = sm_exchange AND ex_Segment = sm_Segment AND ex_seriesid = 
			sm_seriesid AND ex_dt >= '''+@dtFromDate+''' 
	  GROUP BY ex_eaflag, sm_symbol, sm_desc, sm_expirydt, sm_strikeprice, sm_callput, sm_optionstyle, 
			ex_exchange, ex_Segment, ex_dt, sm_prodtype, ex_seriesid
	  UNION ALL
	  SELECT CASE right(sm_prodtype, 1) WHEN ''F'' THEN 6 ELSE 7 END, CASE right(sm_prodtype, 1) WHEN ''F'' THEN 
						''Currency Future'' ELSE ''Currency Option'' END td_type, ''Exp: '' + convert(CHAR(10), 
				convert(DATETIME, sm_expirydt), 105), td_seriesid scripcode, replace(sm_symbol, ''&'', ''''), sum(
				td_bqty), sum(round(convert(MONEY, td_bqty * td_rate * sm_multiplier), 2)), sum(td_sqty), sum(
				round(convert(MONEY, td_sqty * td_rate * sm_multiplier), 2)), sum(td_bqty - td_sqty), sum(round(
					convert(MONEY, (td_sqty - td_bqty) * td_rate * sm_multiplier), 4)), 
			cast(convert(MONEY, CASE WHEN sum(td_bqty - td_sqty) = 0 THEN 0 ELSE sum((td_sqty - td_bqty
									) * td_rate * sm_multiplier) / sum(td_bqty - td_sqty) END) AS DECIMAL(15, 2)), 
			cast(sum(td_brokerage * (td_bqty + td_sqty)) AS DECIMAL(15, 4)) td_brokerage, 
			td_Exchange + ''/'' + td_Segment + ''/'' + Ltrim(convert(CHAR, td_seriesid))
	  FROM trades (NOLOCK), series_master(NOLOCK),  @tbl_UserList X
	  WHERE td_clientcd = X.Client_Code AND td_seriesid = sm_seriesid AND td_Exchange = sm_exchange AND td_Segment = 
			sm_Segment AND td_dt >= '''+@dtFromDate+''' AND td_dt <= '''+@dtToDate+''' AND td_Segment IN (''K'')
	  GROUP BY sm_prodtype, sm_symbol, sm_desc, sm_expirydt, sm_callput, sm_strikeprice, td_exchange, 
			td_Segment, td_dt, td_seriesid'
	  
	  IF @strCommmexDB <> ''
	  BEGIN
	    SET @StrString = @StrString +' UNION ALL SELECT CASE right(sm_prodtype, 1) WHEN ''F'' THEN 8 ELSE 9 END, CASE right(sm_prodtype, 1) WHEN ''F'' THEN 
						''Commodity Future'' ELSE ''Commodity Option'' END td_type, ''Exp: '' + convert(CHAR(10), 
				convert(DATETIME, sm_expirydt), 105), CASE right(sm_prodtype, 1) WHEN ''F'' THEN '''' ELSE convert(CHAR
						(8), sm_strikeprice) + sm_callput END, replace(sm_symbol, ''&'', ''''), sum(td_bqty), sum(
				round(convert(MONEY, td_bqty * td_rate), 4)), sum(td_sqty), sum(round(convert(MONEY, td_sqty * 
						td_rate), 4)), sum(td_bqty - td_sqty), sum(round(convert(MONEY, (td_sqty - td_bqty
							) * td_rate), 4)), cast(convert(MONEY, CASE WHEN sum(td_bqty - td_sqty) = 0 THEN 0 ELSE sum
							((td_sqty - td_bqty) * td_rate) / sum(td_bqty - 
								td_sqty) END) AS DECIMAL(15, 4)), cast(sum(td_brokerage * (td_bqty + td_sqty
						) * sm_multiplier) AS DECIMAL(15, 4)), td_Exchange + ''/'' + ''X'' + ''/'' + Ltrim(convert(CHAR, 
					td_seriesid))
	    FROM '+@strCommmexDB+'.DBO.Trades, '+@strCommmexDB+'.DBO.Series_master,  @tbl_UserList X
	    WHERE td_clientcd = X.Client_Code AND td_seriesid = sm_seriesid AND td_Exchange = sm_exchange AND td_dt =  '''+@dtFromDate+'''
	    GROUP BY sm_prodtype, sm_symbol, sm_desc, sm_expirydt, sm_callput, sm_strikeprice, td_exchange, td_dt, 
	    td_seriesid '
	  END	 
	  SET @StrString = @StrString +' ) a ORDER BY SortORder, stlmnt, scripname '
	  BEGIN TRY
	    
	    EXEC(@StrString)
		SET @o_vcErrorFlag  = 'S'
        SET @o_vcErrorMessage = 'Process Executed'
		RETURN 1
	  END TRY
	  BEGIN CATCH
	    SET @o_vcErrorFlag  = 'E'
        SET @o_vcErrorMessage = ERROR_MESSAGE()
        RETURN 1
	  END CATCH
	END
	ELSE IF @strRepType = 'Confirmation'
	BEGIN
	  SET @StrString = @strHeader+' '+'SELECT * FROM ( SELECT 1 AS orderid, 1 AS SortOrder, 
	  ''Equity : '' + td_stlmnt AS type, td_stlmnt stlmnt, td_scripcd scripcode, 
	  replace(ss_name, ''&'', '''') AS scripname, td_bqty AS buy, td_sqty AS sell, 
	  cast((td_marketrate) AS DECIMAL(15, 4)) AS marketrate, cast((td_rate) AS DECIMAL(15, 4)) AS 
		netrate, cast((((td_bqty + td_sqty) * td_rate)
				) * (CASE td_bsflag WHEN ''S'' THEN ''1'' ELSE ''-1'' END) AS DECIMAL(15, 2)) netamount, 
		cast((td_brokerage) AS DECIMAL(15, 4)) brokerage, left(td_stlmnt, 1) + ''/C/'' + 
		td_scripcd AS lookup
	  FROM trx WITH (INDEX (idx_trx_clientcd), NOLOCK), Settlements WITH (NOLOCK
			), securities WITH (NOLOCK),  @tbl_UserList X
	  WHERE td_clientcd = X.Client_Code AND td_stlmnt = se_stlmnt AND td_dt >= '''+@dtFromDate+''' AND td_dt <= '''+@dtToDate+''' AND td_scripcd = ss_cd 
	  UNION ALL
	  SELECT 3, 2 AS td_order, CASE td_segment WHEN ''F'' THEN CASE TD_EXCHANGE WHEN ''N'' THEN ''NSE F&O'' WHEN ''B'' THEN 
								''BSE F&O'' END WHEN ''K'' THEN CASE TD_EXCHANGE WHEN ''M'' THEN ''MCX FX'' WHEN ''N'' THEN 
								''NSE FX'' END END td_type, '''', sm_symbol, replace(sm_desc, ''&'', ''''), td_bqty AS 
		bqty, td_sqty AS sqty, cast((td_marketrate) AS DECIMAL(15, 4)) AS diffrate, cast((td_rate
				) AS DECIMAL(15, 4)) AS netrate, convert(DECIMAL(15, 2), (td_sqty-td_bqty) * 
			td_rate * sm_multiplier) AS amount, cast((td_brokerage) AS DECIMAL(15, 4)), 
		td_exchange + ''/'' + td_Segment + ''/'' + convert(CHAR, td_seriesid) AS td_lookup
	  FROM trades WITH (INDEX (idx_trades_clientcd), NOLOCK), series_master WITH (NOLOCK
			),  @tbl_UserList X
	  WHERE td_seriesid = sm_seriesid AND td_Exchange = sm_exchange AND td_Segment = sm_Segment AND td_clientcd = X.Client_Code 
	  AND td_dt >= '''+@dtFromDate+''' AND td_dt <= '''+@dtToDate+''' AND td_trxflag = ''N''  AND 
      td_trxflag = ''N'') a
      ORDER BY type, orderid, SortOrder, stlmnt, scripname '
      BEGIN TRY
	    EXEC(@StrString)
		SET @o_vcErrorFlag  = 'S'
        SET @o_vcErrorMessage = 'Process Executed'
		RETURN 1
	  END TRY
	  BEGIN CATCH
	    SET @o_vcErrorFlag  = 'E'
        SET @o_vcErrorMessage = ERROR_MESSAGE()
        RETURN 1
	  END CATCH
	END  
  END
  ELSE IF @strReportName = 'LedgerSummary'
  BEGIN
   SET @StrString = @strHeader+' '+'SELECT * FROM ( 
   SELECT 1 AS Ord, ''Trading'' AS [Type], ld_clientcd AS [ClientCode], sum(CASE sign(datediff(d, '''+@dtFromDate+''', 
						ld_dt)) WHEN - 1 THEN ld_amount ELSE 0 END) OpeningBalance, sum(CASE sign(datediff(d, 
						'''+@dtFromDate+''', ld_dt)) WHEN - 1 THEN 0 ELSE CASE ld_debitflag WHEN ''D'' THEN ld_amount ELSE 0 
						END END) Debit, sum(CASE sign(datediff(d, '''+@dtFromDate+''', ld_dt)) WHEN - 1 THEN 0 ELSE CASE 
						ld_debitflag WHEN ''D'' THEN 0 ELSE ld_amount END END) Credit, sum(ld_amount) Balance, 
		Rtrim(CES_Exchange) + ''-'' + CES_Segment [ExchSeg], LD_DPID AS CESCD, 1 AS TypeCode
	FROM ledger WITH (NOLOCK), Companyexchangesegments WITH (NOLOCK), @tbl_UserList X
	WHERE LD_DPID = CES_Cd AND ld_clientcd = X.Client_Code AND ld_dt <= '''+@dtToDate+'''
	GROUP BY ld_dpid, ld_clientcd, CES_Exchange, CES_Segment '
	IF @strRepType IN('MTF','ALL') AND EXISTS(SELECT 1 FROM SYS.TABLES WHERE NAME= 'MrgTdgFin_Clients')
	BEGIN
	  SET @StrString = @StrString+' '+' UNION ALL
	  SELECT 2 AS Ord, ''MTF'' AS [Type], ld_clientcd AS [ClientCode], sum(CASE sign(datediff(d, '''+@dtFromDate+''', 
						ld_dt)) WHEN - 1 THEN ld_amount ELSE 0 END) OpeningBalance, sum(CASE sign(datediff(d, 
						'''+@dtFromDate+''', ld_dt)) WHEN - 1 THEN 0 ELSE CASE ld_debitflag WHEN ''D'' THEN ld_amount ELSE 0 
						END END) Debit, sum(CASE sign(datediff(d, '''+@dtFromDate+''', ld_dt)) WHEN - 1 THEN 0 ELSE CASE 
						ld_debitflag WHEN ''D'' THEN 0 ELSE ld_amount END END) Credit, sum(ld_amount) Balance, 
		Rtrim(CES_Exchange) + ''-'' + CES_Segment [ExchSeg], LD_DPID AS CESCD, 1 AS TypeCode
	  FROM ledger WITH (NOLOCK), Companyexchangesegments WITH (NOLOCK), MrgTdgFin_Clients(NOLOCK), @tbl_UserList X
	  WHERE LD_DPID = CES_Cd AND ld_dt <= '''+@dtToDate+'''
	  AND ld_clientcd = MTFC_FillerB AND MTFC_CMCD = X.Client_Code AND MTFC_FillerB <> ''''
	  GROUP BY ld_dpid, ld_clientcd, CES_Exchange, CES_Segment '
	END
	IF @strRepType IN('Trading-Margin','ALL') 
	BEGIN
	  SET @StrString = @StrString+' '+' UNION ALL
	  SELECT 3 AS Ord, ''Trading-Margin'' AS [Type], ld_clientcd AS [ClientCode], sum(CASE sign(datediff(d, '''+@dtFromDate+''', 
						ld_dt)) WHEN - 1 THEN ld_amount ELSE 0 END) OpeningBalance, sum(CASE sign(datediff(d, 
						'''+@dtFromDate+''', ld_dt)) WHEN - 1 THEN 0 ELSE CASE ld_debitflag WHEN ''D'' THEN ld_amount ELSE 0 
						END END) Debit, sum(CASE sign(datediff(d, '''+@dtFromDate+''', ld_dt)) WHEN - 1 THEN 0 ELSE CASE 
						ld_debitflag WHEN ''D'' THEN 0 ELSE ld_amount END END) Credit, sum(ld_amount) Balance, 
		Rtrim(CES_Exchange) + ''-'' + CES_Segment [ExchSeg], LD_DPID AS CESCD, 1 AS TypeCode
	  FROM ledger WITH (NOLOCK), Companyexchangesegments WITH (NOLOCK), Client_master(NOLOCK), @tbl_UserList X
	  WHERE LD_DPID = CES_Cd AND ld_dt <= '''+@dtToDate+'''
	  and ld_clientcd = cm_brkggroup and cm_cd = X.Client_Code
	  GROUP BY ld_dpid, ld_clientcd, CES_Exchange, CES_Segment '
	END
	IF @strRepType IN('Commodity','ALL') AND @strCommmexDB <> ''
	BEGIN
	  SET @StrString = @StrString+' '+' UNION ALL
	  SELECT 4 AS Ord, ''Commodity'' AS [Type], ld_clientcd AS [ClientCode], sum(CASE sign(datediff(d, '''+@dtFromDate+''', 
						ld_dt)) WHEN - 1 THEN ld_amount ELSE 0 END) OpeningBalance, sum(CASE sign(datediff(d, 
						'''+@dtFromDate+''', ld_dt)) WHEN - 1 THEN 0 ELSE CASE ld_debitflag WHEN ''D'' THEN ld_amount ELSE 0 
						END END) Debit, sum(CASE sign(datediff(d, '''+@dtFromDate+''', ld_dt)) WHEN - 1 THEN 0 ELSE CASE 
						ld_debitflag WHEN ''D'' THEN 0 ELSE ld_amount END END) Credit, sum(ld_amount) Balance, 
	  Rtrim(CES_Exchange) + ''-'' + CES_Segment [ExchSeg], LD_DPID AS CESCD, 1 AS TypeCode
	  FROM '+@strCommmexDB+'.dbo.ledger WITH (NOLOCK), '+@strCommmexDB+'.dbo.Companyexchangesegments WITH (NOLOCK), @tbl_UserList X
	  WHERE LD_DPID = CES_Cd AND ld_dt <= '''+@dtToDate+'''
	  and ld_clientcd = X.Client_Code
	  GROUP BY ld_dpid, ld_clientcd, CES_Exchange, CES_Segment '
	END
	IF @strRepType IN('Commodity-Margin','ALL') AND @strCommmexDB <> ''
	BEGIN
	  SET @StrString = @StrString+' '+' UNION ALL 
	  SELECT 5 AS Ord, ''Commodity-Margin'' AS [Type], ld_clientcd AS [ClientCode], sum(CASE sign(datediff(d, '''+@dtFromDate+''', 
						ld_dt)) WHEN - 1 THEN ld_amount ELSE 0 END) OpeningBalance, sum(CASE sign(datediff(d, 
						'''+@dtFromDate+''', ld_dt)) WHEN - 1 THEN 0 ELSE CASE ld_debitflag WHEN ''D'' THEN ld_amount ELSE 0 
						END END) Debit, sum(CASE sign(datediff(d, '''+@dtFromDate+''', ld_dt)) WHEN - 1 THEN 0 ELSE CASE 
						ld_debitflag WHEN ''D'' THEN 0 ELSE ld_amount END END) Credit, sum(ld_amount) Balance, 
	  Rtrim(CES_Exchange) + ''-'' + CES_Segment [ExchSeg], LD_DPID AS CESCD, 1 AS TypeCode
	  FROM commex.dbo.ledger WITH (NOLOCK), commex.dbo.Companyexchangesegments WITH (NOLOCK), commex.dbo.Client_master(NOLOCK), @tbl_UserList X
	  WHERE LD_DPID = CES_Cd AND ld_dt <= '''+@dtToDate+'''
	  and ld_clientcd = cm_brkggroup and cm_cd = X.Client_Code
	  GROUP BY ld_dpid, ld_clientcd, CES_Exchange, CES_Segment '
	END  
	IF @strRepType IN('NBFC','ALL') AND EXISTS(SELECT 1 FROM SYS.TABLES WHERE NAME= 'NBFC_Ledger')
	BEGIN
	  SET @StrString = @StrString+' '+' UNION ALL
	  SELECT 6 AS Ord, ''NBFC'' AS [Type], ld_clientcd [ClientCode], sum(CASE sign(datediff(d, '''+@dtFromDate+''', ld_dt)) 
				WHEN - 1 THEN ld_amount ELSE 0 END) OpeningBalance, sum(CASE sign(datediff(d, '''+@dtFromDate+''', ld_dt)
				) WHEN - 1 THEN 0 ELSE CASE ld_debitflag WHEN ''D'' THEN ld_amount ELSE 0 END END) Debit, sum(CASE sign(
					datediff(d, '''+@dtFromDate+''', ld_dt)) WHEN - 1 THEN 0 ELSE CASE ld_debitflag WHEN ''D'' THEN 0 ELSE 
							ld_amount END END) Credit, sum(ld_amount) Balance, ''NBFC'' [ExchSeg], ''NBFC'' AS 
		CESCD, 6 AS TypeCode
	  FROM NBFC_Ledger WITH (NOLOCK), @tbl_UserList X
	  WHERE ld_clientcd = X.Client_Code AND ld_dt <= '''+@dtToDate+'''
	  GROUP BY ld_dpid, ld_clientcd '
	END 
	IF @strRepType IN('DP','ALL') AND @strDefaultConn <> ''
	BEGIN
	  SET @StrString = @StrString+' '+' UNION ALL
	  SELECT 7 AS Ord, ''DP'' AS [Type], ld_clientcd [ClientCode], sum(CASE sign(datediff(d, '''+@dtFromDate+''', ld_dt)) 
				WHEN - 1 THEN ld_amount ELSE 0 END) OpeningBalance, sum(CASE sign(datediff(d, '''+@dtFromDate+''', ld_dt)
				) WHEN - 1 THEN 0 ELSE CASE ld_debitflag WHEN ''D'' THEN ld_amount ELSE 0 END END) Debit, sum(CASE sign(
					datediff(d, '''+@dtFromDate+''', ld_dt)) WHEN - 1 THEN 0 ELSE CASE ld_debitflag WHEN ''D'' THEN 0 ELSE 
							ld_amount END END) Credit, sum(ld_amount) Balance, ''DP'' [ExchSeg], ''DP'' AS 
		CESCD, 6 AS TypeCode
	  FROM '+@strDefaultConn+'.DBO.ledger WITH (NOLOCK), @tbl_UserList X
	  WHERE ld_clientcd = X.DPClientCode AND ld_dt <= '''+@dtToDate+'''
	  GROUP BY ld_dpid, ld_clientcd '
	END 
	SET @StrString = @StrString+' '+') a ORDER BY Ord, [Type], ClientCode, CESCD '
	BEGIN TRY
	  EXEC(@StrString)
	  SET @o_vcErrorFlag  = 'S'
      SET @o_vcErrorMessage = 'Process Executed'
	  RETURN 1
	END TRY
	BEGIN CATCH
	  SET @o_vcErrorFlag  = 'E'
      SET @o_vcErrorMessage = ERROR_MESSAGE()
      RETURN 1
	END CATCH
  END
  ELSE IF @strReportName = 'Transaction'
  BEGIN
    IF @strRepType = 'TradeSummary'
	BEGIN
	  if @strRepSubType = 'DateWise' 
	  BEGIN
	    DECLARE @tbl_TradeSummaryDateWise TABLE(SerialNo INT IDENTITY(1,1), td_clientcd VARCHAR(50),
		ListOrder INT, [type] VARCHAR(100), DATE VARCHAR(20), Scrip varchar(20), ScripName varchar(100), Stlmnt VARCHAR(100),
		Buy MONEY, BuyAmount MONEY, Sell MONEY, SellAmount money, Net MONEY, NetAmount MONEY, LinkCode VARCHAR(200),
		Date2 VARCHAR(20), LookUp VARCHAR(200))
	
	  
	    SET @StrString = @strHeader+' '+'SELECT td_clientcd, Td_order ListOrder, Td_Type type, Dt DATE, Scrip, ScripName, td_stlmnt Stlmnt, Bqty Buy, BAmt BuyAmount, Sqty Sell, SAmt  '
	    +' SellAmount, NQty Net, NAmt NetAmount, LinkCode, Dt1 Date2, LookUp '
	    +' FROM (SELECT td_clientcd, 1 Td_order, ''Equity ['' + CASE WHEN left(td_stlmnt, 1) = ''B'' THEN ''BSE'' ELSE ''NSE'' END + '']'' Td_Type, td_scripcd Scrip, ss_name as ScripName, ltrim( '
	    +' rtrim(convert(CHAR, convert(DATETIME, td_dt), 103))) Dt, rtrim(td_stlmnt) td_stlmnt, '
	    +' sum(td_bqty) Bqty, convert(DECIMAL(15, 2), sum(td_bqty * td_rate)) BAmt, sum(td_sqty) Sqty, convert( '
	    +' DECIMAL(15, 2), sum(td_sqty * td_rate)) SAmt, sum(td_bqty - td_sqty) NQty, convert(DECIMAL(15, 2), '
	    +' sum((td_bqty - td_sqty) * td_rate)) NAmt, ''Equity|'' + Left(td_Stlmnt, 1) + ''|''' 
	    +' LinkCode, td_dt Dt1, left(td_stlmnt, 1) + ''/C/'' + Max(td_scripcd) AS LookUp '
	    +' FROM trx WITH (INDEX (idx_trx_clientcd), NOLOCK), Securities(nolock), @tbl_UserList X '
	    +' WHERE td_clientcd = X.Client_COde AND td_dt BETWEEN '''+@dtFromDate+''' AND '''+@dtToDate+''' '
		+' AND td_scripcd = ss_cd  AND '''+@strProduct+''' IN(''CASH'','''')' 
	    +' GROUP BY td_clientcd, td_stlmnt, td_dt, td_scripcd, ss_name '
	    +' UNION ALL '
	    +' SELECT td_clientcd, CASE sm_prodtype WHEN ''CF'' THEN 4 ELSE CASE left(sm_productcd, 1) WHEN ''F'' THEN 2 ELSE 3 END END, CASE WHEN '
	    +' td_segment = ''K'' THEN ''Currency '' ELSE ''Equity '' END + CASE left(sm_productcd, 1) WHEN ''F'' THEN '
	    +' ''Future '' ELSE ''Option '' END + ''['' + CASE left(td_exchange, 1) WHEN ''B'' THEN ''BSE'' WHEN ''N'' THEN '
	    +' ''NSE'' ELSE ''MCX'' END + '']'' Td_Type, td_seriesid Scrip, sm_sname ScripName,  ltrim(rtrim(convert(CHAR, convert(DATETIME, td_dt), '
	    +' 103))) Dt, CASE left(sm_prodtype, 1) WHEN ''I'' THEN ''Index'' WHEN ''E'' THEN ''Stock'' ELSE '
	    +' ''Currency'' END + CASE right(sm_prodtype, 1) WHEN ''F'' THEN '' Future'' ELSE '' Option'' END, sum( '
	    +' td_bqty) Bqty, convert(DECIMAL(15, 2), sum(td_bqty * td_rate * sm_multiplier)) BAmt, sum(td_sqty) '
	    +' Sqty, convert(DECIMAL(15, 2), sum(td_sqty * td_rate * sm_multiplier)) SAmt, sum(td_bqty - td_sqty) NQty, '
	    +' convert(DECIMAL(15, 2), sum((td_bqty - td_sqty) * td_rate * sm_multiplier)) NAmt, '
	    +' CASE WHEN td_segment = ''K'' THEN ''Currency'' ELSE ''Equity'' END + CASE left(sm_productcd, 1) WHEN ''F'' THEN '
	    +' ''Future'' ELSE ''Option'' END + ''|'' + td_exchange + ''|'' +'' '' + ''|'' +'' ''+ ''|'' +'' ''+ ''|'' + '''' + ''|'' + sm_optionstyle +'
	    + '''|'' + td_segment LinkCode, td_dt Dt1, td_exchange + ''/'' + td_Segment + ''/'' + convert(CHAR, Max(td_seriesid '
	    +' )) AS Lookup FROM trades '
	    +' WITH (INDEX (idx_trades_clientcd), NOLOCK), series_master WITH (NOLOCK),  @tbl_UserList X '
	    +' WHERE td_clientcd = X.Client_COde AND sm_exchange = td_exchange AND sm_Segment = td_Segment AND td_seriesid = '
	    +' sm_seriesid AND td_dt BETWEEN '''+@dtFromDate+''' AND '''+@dtToDate+'''  AND td_trxflag <> ''O''  AND '''+@strProduct+''' IN(''FO'','''',''FX'') '
	    +' GROUP BY td_clientcd, td_Dt, td_seriesid, sm_sname, sm_productcd, td_exchange, td_Segment, sm_prodtype, td_exchange, sm_optionstyle, sm_prodtype '
 	
	    +' UNION ALL '
	
	    +' SELECT ex_clientcd AS td_clientcd, 5, CASE WHEN ex_segment = ''K'' THEN ''Currency '' ELSE ''Equity '' END + CASE ex_eaflag WHEN ''E'' THEN '
	    +' ''Exercise '' ELSE ''Assignment '' END + ''['' + CASE left(ex_exchange, 1) WHEN ''B'' THEN ''BSE'' WHEN '
	    +' ''N'' THEN ''NSE'' ELSE ''MCX'' END + '']'' Td_Type, ex_seriesid Scrip, sm_sname as ScripName, ltrim(rtrim(convert(CHAR, convert(DATETIME, ex_Dt) '
	    +' , 103))) Dt, ( '
	    +' CASE left(sm_prodtype, 1) WHEN ''I'' THEN ''Index'' WHEN ''E'' THEN ''Stock'' ELSE ''Currency'' END + CASE right( '
	    +' sm_prodtype, 1) WHEN ''F'' THEN '' Future'' ELSE '' Option'' END '
	    +' ),  sum(ex_aqty) Bqty, convert(DECIMAL(15, 2), sum(ex_aqty * ex_diffrate * CASE ex_eaflag WHEN ''A''  '
	    +' THEN - 1 ELSE 1 END * sm_multiplier)) BAmt, sum(ex_eqty) Sqty, convert(DECIMAL(15, 2), '
	    +' sum(ex_eqty * ex_diffrate * CASE ex_eaflag WHEN ''A'' THEN - 1 ELSE 1 END * sm_multiplier)) SAmt, sum( '
	    +' ex_aqty - ex_eqty) NQty, convert(DECIMAL(15, 2), sum((ex_aqty - ex_eqty) * '
	    +' ex_diffrate * CASE ex_eaflag WHEN ''A'' THEN - 1 ELSE 1 END * sm_multiplier)) NAmt, CASE WHEN  '
	    +' ex_segment = ''K'' THEN ''Currency'' ELSE ''Equity'' END + CASE ex_eaflag WHEN ''E'' THEN ''Exercise'' ELSE '
	    +' ''Assignment'' END + ''|'' + ex_exchange + ''|'' + ex_segment + ''|'' LinkCode, ex_Dt Dt1, ex_exchange + ''/'' + '
	    +' ex_Segment + ''/'' + Ltrim(convert(CHAR, Max(ex_seriesid))) AS Lookup '
	    +' FROM exercise WITH (NOLOCK), series_master WITH (NOLOCK) ,  @tbl_UserList X '
	    +' WHERE ex_clientcd = X.Client_COde AND ex_exchange = sm_exchange AND ex_Segment = sm_Segment AND ex_seriesid = '
	    +' sm_seriesid AND ex_dt BETWEEN '''+@dtFromDate+''' AND '''+@dtToDate+'''  AND '''+@strProduct+''' IN(''FO'','''',''FX'') '
	    +' GROUP BY ex_clientcd, ex_Dt, ex_seriesid,sm_sname, ex_eaflag, ex_exchange, ex_Segment, sm_prodtype '
		IF @strCommmexDB <> ''
		BEGIN
		  SET @StrString = @StrString +' '+' UNION ALL '
		  +' SELECT td_clientcd, 7, '
	      +' ''Commodity''  + ''['' + CASE left(td_exchange, 1) WHEN ''M'' THEN ''MCX'' WHEN ''S'' THEN '
		  +' ''NSEL'' ELSE ''NCDEX'' END + '']'' Td_Type, td_seriesid Scrip, sm_sname as ScripName, ltrim(rtrim(convert(CHAR, convert(DATETIME, td_dt), '
		  +' 103))) Dt, ''Commodity'' , sum(td_bqty) Bqty, convert(DECIMAL(15, 2), sum(td_bqty * td_rate * sm_multiplier)) BAmt, sum(td_sqty) '
		  +' Sqty, convert(DECIMAL(15, 2), sum(td_sqty * td_rate * sm_multiplier)) SAmt, sum(td_bqty - td_sqty) NQty, '
		  +' convert(DECIMAL(15, 2), sum((td_bqty - td_sqty) * td_rate * sm_multiplier)) NAmt, '
		  +' ''Commodity''  + ''|'' + td_exchange   LinkCode, td_dt Dt1, td_exchange + ''/''  + convert(CHAR, Max(td_seriesid)) AS Lookup '
	      +' FROM '+@strCommmexDB+'.dbo.trades(NOLOCK), '+@strCommmexDB+'.dbo.series_master(NOLOCK), @tbl_UserList X '
	      +' WHERE td_clientcd = X.Client_COde AND sm_exchange = td_exchange  AND td_seriesid = sm_seriesid AND'
          +' td_dt BETWEEN '''+@dtFromDate+''' AND '''+@dtToDate+'''   AND td_trxflag <> ''O'' '
	      +' GROUP BY td_clientcd, td_Dt, sm_productcd, sm_sname, td_exchange, td_seriesid, sm_prodtype, td_exchange, sm_optionstyle, sm_prodtype '
	      +' UNION ALL '
	      +' SELECT ex_clientcd AS td_clientcd, 8, ''Commodity'' + CASE ex_eaflag WHEN ''E'' THEN  '
		  +' ''Exercise '' ELSE ''Assignment '' END + ''['' + CASE left(ex_exchange, 1) WHEN ''M'' THEN ''MCX'' WHEN ''S'' THEN '
		  +' ''NSEL'' ELSE ''NCDEX'' END + '']'' Td_Type,ex_seriesid,  sm_sname as ScripName, ltrim(rtrim(convert(CHAR, convert(DATETIME, ex_Dt) '
		  +' , 103))) Dt, ''Commodity'' ,  sum(ex_aqty) Bqty, convert(DECIMAL(15, 2), sum(ex_aqty * ex_diffrate * CASE ex_eaflag WHEN ''A'' '
		  +' THEN - 1 ELSE 1 END * sm_multiplier)) BAmt, sum(ex_eqty) Sqty, convert(DECIMAL(15, 2), '
		  +' sum(ex_eqty * ex_diffrate * CASE ex_eaflag WHEN ''A'' THEN - 1 ELSE 1 END * sm_multiplier)) SAmt, sum( '
		  +' ex_aqty - ex_eqty) NQty, convert(DECIMAL(15, 2), sum((ex_aqty - ex_eqty) * '
		  +' ex_diffrate * CASE ex_eaflag WHEN ''A'' THEN - 1 ELSE 1 END * sm_multiplier)) NAmt, '
		  +' ''Commodity'' + CASE ex_eaflag WHEN ''E'' THEN ''Exercise'' ELSE '
		  +' ''Assignment'' END + ''|'' + ex_exchange  LinkCode, ex_Dt Dt1, ex_exchange + ''/'' + Ltrim(convert(CHAR, Max(ex_seriesid))) AS Lookup '
	      +' FROM '+@strCommmexDB+'.dbo.exercise WITH (NOLOCK), '+@strCommmexDB+'.dbo.series_master WITH (NOLOCK), @tbl_UserList X '
	      +' WHERE ex_clientcd = X.Client_COde AND ex_exchange = sm_exchange  AND ex_seriesid =  '
		  +' sm_seriesid AND ex_dt BETWEEN '''+@dtFromDate+''' AND '''+@dtToDate+''' AND '''+@strProduct+''' IN(''COMM'','''',''CO'') '
	      +' GROUP BY ex_clientcd, ex_Dt, ex_eaflag, ex_seriesid, sm_sname, ex_exchange, sm_prodtype '
        END
		SET @StrString = @StrString +' ) a '
		
		if ISNULL(@strScrip,'') <> ''
		BEGIN
		  SET @StrString = @StrString +' WHERE Scrip  = '''+@strScrip+'''' 
		END
		
		SET @StrString = @StrString +' ORDER BY Dt, Td_Type, ScripName'
		BEGIN TRY
		  --SELECT @StrString
		  INSERT INTO @tbl_TradeSummaryDateWise (td_clientcd, ListOrder, 
		  [type], DATE, Scrip, ScripName, Stlmnt, Buy, BuyAmount, Sell, SellAmount, Net, NetAmount, 
		  LinkCode, Date2, LookUp)
	      EXEC(@StrString)
		  IF @strOutputType = 'X'
		  BEGIN
		    SET @XMLDATA1 = 
		    (SELECT td_clientcd, ListOrder, 
			 [type], DATE, Scrip, ScripName, Stlmnt, Buy, BuyAmount, BuyRate = ABS(CASE WHEN Buy <> 0 THEN 
			 CAST(NetAmount AS MONEY)/ CAST(Buy AS MONEY) ELSE 0 END),
			 Sell, SellAmount, SellRate = ABS(CASE WHEN Sell <> 0 THEN 
			 CAST(SellAmount AS MONEY)/ CAST(Sell AS MONEY) ELSE 0 END), Net, NetAmount, 
			 NetRate = ABS(CASE WHEN Net <> 0 THEN 
			 CAST(NetAmount AS MONEY)/ CAST(Net AS MONEY) ELSE 0 END),
			 LinkCode, Date2, LookUp, ClientName = cm_name 
			 FROM @tbl_TradeSummaryDateWise a, client_master(NOLOCK) B
             WHERE A.td_clientcd = B.CM_cD 			
		    order by td_clientcd, SerialNo  
		    FOR XML PATH('CapGain'))
	        SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
			RETURN 1
		  END
		  ELSE
		  BEGIN
		    SELECT * FROM @tbl_TradeSummaryDateWise  
		    ORDER BY SerialNo  
		  END 
	      SET @o_vcErrorFlag  = 'S'
          --SET @o_vcErrorMessage = 'Process Executed'
	      RETURN 1
	    END TRY
	    BEGIN CATCH
	      SET @o_vcErrorFlag  = 'E'
          SET @o_vcErrorMessage = ERROR_MESSAGE()
          RETURN 1
	    END CATCH
      END
	  if @strRepSubType = 'ItemWise' 
	  BEGIN
	  
	    DECLARE @TBL_TradedItemWise TABLE(SerialNo INT IDENTITY(1,1),
		td_clientcd VARCHAR(50), ListOrder INT, [Type] VARCHAR(100),
		ScripCode VARCHAR(20), ScripName VARCHAR(100), Buy MONEY, BuyAmount MONEY, 
		Sell MONEY, SellAmount MONEY, Net MONEY, NetAmount MONEY,
		AvgRate MONEY, LinkCode VARCHAR(200), LookUp VARCHAR(100))
		
		
	    SET @StrString = @strHeader+' '+'SELECT td_clientcd, ListOrder, Td_Type Type, td_scripnm ScripCode, snm ScripName, Bqty Buy, BAmt BuyAmount, Sqty Sell, SAmt '
	    +' SellAmount, NQty Net, NAmt NetAmount, rate AvgRate, LinkCode, LookUp '
        +' FROM ( SELECT td_clientcd, 1 ListOrder, '''' AS td_ac_type, '''' AS td_trxdate, '''' AS td_isin_code, '''' AS sc_company_name, '
		+' cast(( CASE WHEN sum(td_bqty - td_sqty) = 0 THEN 0 ELSE sum((td_bqty - td_sqty) * td_rate) / sum(td_bqty - td_sqty) END '
		+' ) AS DECIMAL(15, 4)) AS rate, ''Equity'' Td_Type, '''' AS FScripNm, '''' AS FExDt, rtrim(td_scripcd) '
		+' td_scripnm, rtrim(ss_name) snm, sum(td_bqty) Bqty, convert(DECIMAL(15, 2), sum(td_bqty * td_rate)) '
		+' BAmt, sum(td_sqty) Sqty, convert(DECIMAL(15, 2), sum(td_sqty * td_rate)) SAmt, sum(td_bqty - td_sqty) '
		+' NQty, convert(DECIMAL(15, 2), sum((td_bqty - td_sqty) * td_rate)) NAmt, '''' AS '
		+' td_debit_credit, 0 AS sm_strikeprice, '''' AS sm_callput, ''Equity|'' + '''' + ''|'' + td_scripcd LinkCode, ''/C/'' + td_scripcd AS lookup '
	    +' FROM Trx WITH (INDEX (idx_trx_clientcd), NOLOCK), securities WITH (NOLOCK), @tbl_UserList X '
	    +' WHERE td_clientcd = x.client_code AND td_dt BETWEEN '''+@dtFromDate+''' AND '''+@dtToDate+''' AND '''+@strProduct+''' IN(''CASH'','''') AND td_Scripcd = ss_cd '
	    +' GROUP BY td_clientcd, td_scripcd, ss_name, ''Equity|'' + '''' + ''|'' + td_scripcd, ''/C/'' + td_scripcd, rtrim(td_scripcd) '
	
	    +' UNION ALL '
	
	    +' SELECT td_clientcd, CASE left(sm_productcd, 1) WHEN ''F'' THEN 2 ELSE 3 END, '''', '''', '''' AS td_isin_code, '''' AS sc_company_name,  '
		+' cast((CASE WHEN sum(td_bqty - td_sqty) = 0 THEN 0 ELSE sum((td_bqty - td_sqty) * td_rate) / sum(td_bqty - td_sqty) END '
		+' ) AS DECIMAL(15, 4)) AS rate, CASE WHEN td_segment = ''K'' THEN ''Currency '' ELSE ''Equity '' END + CASE '
		+' left(sm_productcd, 1) WHEN ''F'' THEN ''Future '' ELSE ''Option '' END Td_Type, rtrim(sm_symbol), '
		+' sm_expirydt, rtrim(td_seriesid), CASE left(sm_productcd, 1) WHEN ''F'' THEN ''Fut '' ELSE ''Opt '' END + rtrim( '
		+' sm_symbol) + ''  Exp: '' + ltrim(rtrim(convert(CHAR, convert(DATETIME, sm_expirydt), 103))) + CASE '
		+' left(sm_productcd, 1) WHEN ''F'' THEN '''' ELSE '''' + rtrim(convert(CHAR(9), sm_strikeprice)) + '
		+' sm_callput + sm_optionstyle END, sum(td_bqty) Bqty, convert(DECIMAL(15, 2), sum(td_bqty * '
		+' td_rate * sm_multiplier)) BAmt, sum(td_sqty) Sqty, convert(DECIMAL(15, 2), sum(td_sqty * '
		+' td_rate * sm_multiplier)) SAmt, sum(td_bqty - td_sqty) NQty, convert(DECIMAL(15, 2), sum((td_bqty - td_sqty '
		+' ) * td_rate * sm_multiplier)) NAmt, '''' AS td_debit_credit, sm_strikeprice, sm_callput, CASE '
		+' WHEN td_segment = ''K'' THEN ''Currency'' ELSE ''Equity'' END + CASE left(sm_productcd, 1) WHEN ''F'' THEN '
		+' ''Future'' ELSE ''Option'' END + ''|'' + '''' + ''|'' + replace(sm_symbol, ''&'', ''-'') + ''|'' + left( '
		+' sm_productcd, 1) + ''|'' + sm_expirydt + ''|'' + Rtrim(Ltrim(Convert(CHAR, sm_strikeprice))) + ''|'' + '
		+' sm_callput + ''|'' + sm_optionstyle + ''|'' + td_Segment LinkCode, ''/'' + td_Segment + ''/'' + convert( '
		+' CHAR, td_seriesid) AS Lookup FROM trades WITH (INDEX (idx_trades_clientcd), NOLOCK), series_master WITH (NOLOCK) '
		+', @tbl_UserList X '
	    +' WHERE td_clientcd = x.Client_code AND sm_exchange = td_exchange AND sm_Segment = td_Segment AND td_seriesid = '
		+' sm_seriesid AND td_dt BETWEEN '''+@dtFromDate+''' AND '''+@dtToDate+''' AND td_trxflag <> ''O''  AND '''+@strProduct+''' IN(''FO'','''',''FX'') '
	    +' GROUP BY td_clientcd, sm_symbol, sm_productcd,  td_Segment, sm_expirydt, sm_strikeprice, sm_callput,  '
		+' sm_optionstyle, ''/'' + td_Segment + ''/'' + convert(CHAR, td_seriesid), rtrim(td_seriesid) '
	    +' UNION ALL '
	    +' SELECT ex_clientcd, 4, '''', '''' AS td_trxdate, '''' AS td_isin_code, '''' AS sc_company_name, cast(( '
		+' CASE WHEN sum(ex_aqty - ex_eqty) = 0 THEN 0 ELSE sum((ex_aqty - ex_eqty '
	    +' ) * ex_diffrate * CASE ex_eaflag WHEN ''A'' THEN - 1 ELSE 1 END) / sum(ex_aqty - '
		+' ex_eqty) END) AS DECIMAL(15, 2)) AS rate, CASE WHEN ex_Segment = ''K'' THEN ''Currency '' ELSE ''Equity '' END + CASE '
		+' ex_eaflag WHEN ''E'' THEN ''Exercise '' ELSE ''Assignment '' END Td_Type, '''', '''', rtrim(ex_seriesid), CASE '
		+' left(sm_productcd, 1) WHEN ''F'' THEN ''Fut '' ELSE ''Opt '' END + rtrim(sm_symbol) + ''  Exp: '' + ltrim( '
		+' rtrim(convert(CHAR, convert(DATETIME, sm_expirydt), 103))) + CASE left(sm_productcd, 1) WHEN ''F'' ' 
		+' THEN '''' ELSE '''' + rtrim(convert(CHAR(9), sm_strikeprice)) + sm_callput + sm_optionstyle END, sum '
		+' (ex_aqty) Bqty, convert(DECIMAL(15, 2), sum(ex_aqty * ex_diffrate * CASE ex_eaflag WHEN ''A'' THEN - 1 ELSE 1 '
		+' END * sm_multiplier)) BAmt, sum(ex_eqty) Sqty, convert(DECIMAL(15, 2), sum(ex_eqty * '
		+' ex_diffrate * CASE ex_eaflag WHEN ''A'' THEN - 1 ELSE 1 END * sm_multiplier)) SAmt, sum(ex_aqty - '
		+' ex_eqty) NQty, convert(DECIMAL(15, 2), sum((ex_aqty - ex_eqty) * ex_diffrate '
		+' * CASE ex_eaflag WHEN ''A'' THEN - 1 ELSE 1 END * sm_multiplier)) NAmt, '''' AS td_debit_credit, 0, '''', '
		+' CASE WHEN ex_segment = ''K'' THEN ''Currency'' ELSE ''Equity'' END + CASE ex_eaflag WHEN ''E'' THEN ''Exercise'' ELSE '
		+' ''Assignment'' END + ''|'' + '''' + ''|'' + replace(sm_symbol, ''&'', ''-'') + ''|'' + left(sm_productcd, 1) + ''|'' + '
		+' sm_expirydt + ''|'' + Rtrim(Ltrim(Convert(CHAR, sm_strikeprice))) + ''|'' + sm_callput + ''|'' + sm_optionstyle '
		+' + ''|'' + ex_Segment LinkCode, ''/'' + ex_Segment + ''/'' + Ltrim(convert(CHAR, ex_seriesid)) AS Lookup '
	    +' FROM exercise WITH (NOLOCK), series_master WITH (NOLOCK), @tbl_UserList X'
	    +' WHERE ex_clientcd = x.Client_code AND ex_exchange = sm_exchange AND ex_Segment = sm_Segment AND ex_seriesid = '
		+' sm_seriesid AND ex_dt BETWEEN '''+@dtFromDate+''' AND '''+@dtToDate+'''  AND '''+@strProduct+''' IN(''FO'','''',''FX'') '
	    +' GROUP BY ex_clientcd, ex_eaflag, sm_symbol, ex_Segment, sm_productcd, sm_expirydt, sm_strikeprice, sm_callput, '
		+' sm_optionstyle, ''/'' + ex_Segment + ''/'' + Ltrim(convert(CHAR, ex_seriesid)), rtrim(ex_seriesid) '
		IF @strCommmexDB <> ''
		BEGIN
		  SET @StrString = @StrString +' '+' UNION ALL '
		  +' SELECT td_clientcd, 7, '''', '''', '''' AS td_isin_code, '''' AS ListOrder, '
		  +' cast((CASE WHEN sum(td_bqty - td_sqty) = 0 THEN 0 ELSE sum((td_bqty - td_sqty ) * td_rate) / sum(td_bqty - td_sqty) END'
		  +' ) AS DECIMAL(15, 4)) AS rate, ''Commodity'' Td_Type, rtrim(sm_symbol), '
		  +' sm_expirydt, rtrim(td_seriesid), CASE left(sm_productcd, 1) WHEN ''F'' THEN ''Fut '' ELSE ''Opt '' END + rtrim( '
		  +' sm_symbol) + ''  Exp: '' + ltrim(rtrim(convert(CHAR, convert(DATETIME, sm_expirydt), 103))) + CASE '
		  +' left(sm_productcd, 1) WHEN ''F'' THEN '''' ELSE '''' + rtrim(convert(CHAR(9), sm_strikeprice)) + '
		  +' sm_callput + sm_optionstyle END, sum(td_bqty) Bqty, convert(DECIMAL(15, 2), sum(td_bqty * '
		  +' td_rate * sm_multiplier)) BAmt, sum(td_sqty) Sqty, convert(DECIMAL(15, 2), sum(td_sqty * '
		  +' td_rate * sm_multiplier)) SAmt, sum(td_bqty - td_sqty) NQty, convert(DECIMAL(15, 2), sum((td_bqty - td_sqty '
		  +' ) * td_rate * sm_multiplier)) NAmt, '''' AS td_debit_credit, sm_strikeprice, sm_callput, '
		  +' ''Commodity'' + ''|'' + '''' + ''|'' + replace(sm_symbol, ''&'', ''-'') + ''|'' + left( '
		  +' sm_productcd, 1) + ''|'' + sm_expirydt + ''|'' + Rtrim(Ltrim(Convert(CHAR, sm_strikeprice))) + ''|'' + '
		  +' sm_callput + ''|'' + sm_optionstyle  LinkCode,  ''/'' + convert(CHAR, td_seriesid) AS Lookup '
	      +' FROM '+@strCommmexDB+'.dbo.trades (NOLOCK), '+@strCommmexDB+'.dbo.series_master(NOLOCK),  @tbl_UserList X '
	      +' WHERE td_clientcd = X.Client_COde AND sm_exchange = td_exchange AND  td_seriesid = '
		  +' sm_seriesid AND td_dt BETWEEN '''+@dtFromDate+''' AND '''+@dtToDate+''' AND td_trxflag <> ''O'' '
	      +' GROUP BY td_clientcd, sm_symbol, sm_productcd,  sm_expirydt, sm_strikeprice, sm_callput, '
		  +' sm_optionstyle, ''/'' + convert(CHAR, td_seriesid), rtrim(td_seriesid) '
		  +' UNION ALL '
	      +' SELECT ex_clientcd AS td_clientcd, 8, '''', '''' AS td_trxdate, '''' AS td_isin_code, '''' AS sc_company_name, '
		  +' cast((CASE WHEN sum(ex_aqty - ex_eqty) = 0 THEN 0 ELSE sum((ex_aqty - ex_eqty) * ex_diffrate * '
		  +' CASE ex_eaflag WHEN ''A'' THEN - 1 ELSE 1 END) / sum(ex_aqty - ex_eqty) END) AS DECIMAL(15, 2)) AS rate, '
		  +' ''Commodity'' + CASE ex_eaflag WHEN ''E'' THEN ''Exercise '' ELSE ''Assignment '' END Td_Type, '''', '''','
          +' rtrim(ex_seriesid), CASE left(sm_productcd, 1) WHEN ''F'' THEN ''Fut '' ELSE ''Opt '' END + rtrim(sm_symbol) + ''  Exp: '' + ltrim('
		  +' rtrim(convert(CHAR, convert(DATETIME, sm_expirydt), 103))) + CASE left(sm_productcd, 1) WHEN ''F'' '
		  +' THEN '''' ELSE '''' + rtrim(convert(CHAR(9), sm_strikeprice)) + sm_callput + sm_optionstyle END, sum '
		  +' (ex_aqty) Bqty, convert(DECIMAL(15, 2), sum(ex_aqty * ex_diffrate * CASE ex_eaflag WHEN ''A'' THEN - 1 ELSE 1 '
		  +' END * sm_multiplier)) BAmt, sum(ex_eqty) Sqty, convert(DECIMAL(15, 2), sum(ex_eqty * '
		  +' ex_diffrate * CASE ex_eaflag WHEN ''A'' THEN - 1 ELSE 1 END * sm_multiplier)) SAmt, '
		  +' sum(ex_aqty - ex_eqty) NQty, convert(DECIMAL(15, 2), sum((ex_aqty - ex_eqty) * ex_diffrate '
		  +' * CASE ex_eaflag WHEN ''A'' THEN - 1 ELSE 1 END * sm_multiplier)) NAmt, '''' AS td_debit_credit, 0, '''', '
		  +' ''Commodity'' + CASE ex_eaflag WHEN ''E'' THEN ''Exercise'' ELSE '
		  +' ''Assignment'' END + ''|'' + '''' + ''|'' + replace(sm_symbol, ''&'', ''-'') + ''|'' + left(sm_productcd, 1) + ''|'' + '
		  +' sm_expirydt + ''|'' + Rtrim(Ltrim(Convert(CHAR, sm_strikeprice))) + ''|'' + sm_callput + ''|'' + sm_optionstyle as '
		  +' LinkCode, ''/'' + Ltrim(convert(CHAR, ex_seriesid)) AS Lookup '
	      +' FROM '+@strCommmexDB+'.dbo.exercise WITH (NOLOCK), '+@strCommmexDB+'.dbo.series_master WITH (NOLOCK),  @tbl_UserList X '
	      +' WHERE ex_clientcd = X.Client_COde AND ex_exchange = sm_exchange AND ex_seriesid = '
		  +' sm_seriesid AND ex_dt BETWEEN '''+@dtFromDate+''' AND '''+@dtToDate+''''
	      +' GROUP BY ex_clientcd, ex_eaflag, sm_symbol, sm_productcd, sm_expirydt, sm_strikeprice, sm_callput, '
		  +' sm_optionstyle, ''/'' + Ltrim(convert(CHAR, ex_seriesid)), rtrim(ex_seriesid) '
        END
		SET @StrString = @StrString +' ) a ORDER BY ListOrder, td_type, snm, td_scripnm '
		BEGIN TRY
		 INSERT INTO @TBL_TradedItemWise(td_clientcd, ListOrder, Type,
		 ScripCode, ScripName, Buy, BuyAmount, Sell, SellAmount, Net, NetAmount,
		 AvgRate, LinkCode, LookUp )
		 EXEC(@StrString) 
		 IF @strOutputType = 'X'
		 BEGIN
		   SET @XMLDATA1 = 
		   (SELECT td_clientcd, ListOrder, Type,
		   ScripCode, ScripName, Buy, BuyAmount, BuyRate = ABS(CASE WHEN Buy <> 0 THEN 
			CAST(NetAmount AS MONEY)/ CAST(Buy AS MONEY) ELSE 0 END),
			Sell, SellAmount, SellRate = ABS(CASE WHEN Sell <> 0 THEN 
			CAST(SellAmount AS MONEY)/ CAST(Sell AS MONEY) ELSE 0 END), Net, NetAmount, 
		    AvgRate, LinkCode, LookUp, CLIENTNAME = CM_NAME 
		   FROM @TBL_TradedItemWise  a, client_master(NOLOCK) B
            where A.td_clientcd = B.CM_cD		   
		   order by td_clientcd, SerialNo  
		   FOR XML PATH('CapGain'))
	       SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
			   return 1
		 END
		 ELSE
		 BEGIN
		   SELECT * FROM @TBL_TradedItemWise  
		   ORDER BY SerialNo  
		 END 
	     SET @o_vcErrorFlag  = 'S'
         SET @o_vcErrorMessage = 'Process Executed'
	     RETURN 1
	    END TRY
	    BEGIN CATCH
	      SET @o_vcErrorFlag  = 'E'
          SET @o_vcErrorMessage = ERROR_MESSAGE()
          RETURN 1
	    END CATCH
      END
	  Else if @strRepSubType = 'Details' 
	  BEGIN

	    DECLARE @TBL_TradedDetails TABLE(
		SerialNo INT IDENTITY(1,1), --td_clientcd VARCHAR(50), ListOrder INT, [Type] VARCHAR(100),
		SecurityCode VARCHAR(20), Security VARCHAR(100), ClientCode Varchar(20), ClientName Varchar(50), TradeDate Varchar(20), 
		Flag Varchar(10), Qty Varchar(10), MainBroker Varchar(50), CTCL_Id Varchar(50), ParticipantCode Varchar(50), MarketRate MONEY,
		NetRate MONEY, Brokerage MONEY, TerminalNo Varchar(50),BrokerageAmt MONEY, TradeID Varchar(50), TradeTime Varchar(10), 
		OrderId Varchar(50), OrderTime Varchar(10), STT Varchar(50), ExpiryDate Varchar(18), BankThru Varchar(50), 
		Segment Varchar(50), BrokerageType Varchar(50), Settelment Varchar(50))		

	  If @strProduct = 'FO'
		 Begin
		  DECLARE @TBL_TradedDetailsFO TABLE(SerialNo INT IDENTITY(1,1), --td_clientcd VARCHAR(50), ListOrder INT, [Type] VARCHAR(100),
			SeriesCode VARCHAR(20), SeriesName VARCHAR(100), ClientCode Varchar(20), ClientName Varchar(50), TradeDate Varchar(50), 
			Qty Varchar(10), Flag Varchar(50),  CM Varchar(50), MarketRate MONEY, Brokerage MONEY, NetRate MONEY, OrderId Varchar(50), 
			OrderTime Varchar(10), TradeID Varchar(50), TradeTime Varchar(10), TerminalNo Varchar(50), ClientType Varchar(50),
			CTCL Varchar(50), Participant Varchar(50), ExpiryDate Varchar(18), BankThru Varchar(50), Segment Varchar(50))		
		  SET @StrString = @strHeader+' '+'  SELECT * FROM ( SELECT '
			  +'  td_seriesid As SeriesCode, sm_sname as SeriesName,   td_clientcd as ClientCode,cm_name ClientName,  td_dt as TradeDate '
			  +'  ,(td_bqty + td_sqty) as Qty, Case when td_bsflag=''B'' then ''Buy'' else ''Sell'' End as Flag '
		      +'  , td_mainbrcd as CM,   td_marketrate as MarketRate  ,td_brokerage as Brokerage, td_rate as NetRate    '
			  +'  , Cast(td_orderid as Varchar(50)) as OrderId, td_ordertime as OrderTime, td_tradeid as TradeID,td_time as TradeTime '
			  +'  , td_terminalcd as TerminalNo, '''' as ClientType, td_ctclid as CTCL, td_participantcode as Participant '
			  +'  ,td_expirydt as ExpiryDate,    '''' BankThru, td_Segment Segment '
			  +'  FROM trades WITH (INDEX (idx_trades_clientcd), NOLOCK), series_master WITH (NOLOCK), Client_master (NoLock)  , @tbl_UserList X  '
			  +'  WHERE td_clientcd = x.Client_code AND   td_clientcd = cm_cd And  '
			  +'  sm_exchange = td_exchange AND sm_Segment = td_Segment ' 
			  +'  AND td_seriesid =  sm_seriesid AND td_dt BETWEEN '''+@dtFromDate+''' AND '''+@dtToDate+''' AND td_trxflag <> ''O'' '
		  End
       Else
	     Begin
			SET @StrString = @strHeader+' '+' SELECT * FROM ( SELECT '
					+'  td_scripcd As SecurityCode, ss_name as Security,   td_clientcd as ClientCode,cm_name ClientName,  td_dt as TradeDate, '
					+'  Case when td_bsflag = ''B'' then ''Buy'' else ''Sell'' End as Flag '
					+' ,(td_bqty + td_sqty) as Qty, td_mainbrcd as MainBroker, td_CtclId as CTCL_Id, td_participantCode as ParticipantCode, td_marketrate as MarketRate, td_rate as NetRate '
					+' ,td_brokerage as Brokerage, td_terminalcd as TerminalNo, td_turnoverTax as BrokerageAmt  , td_tradeid as TradeID '
					+' ,td_time as TradeTime, Cast(td_orderid as Varchar(50)) as OrderId, td_ordertime as OrderTime, td_SttWaived as STT '
					+' ,td_filler2 as ExpiryDate,    '''' BankThru, ''CASH'' Segment, td_brokeragetype as BrokerageType  ,td_stlmnt as Settelment  '
					+' FROM Trx WITH (INDEX (idx_trx_clientcd), NOLOCK), securities WITH (NOLOCK), Client_master with(Nolock) , @tbl_UserList X   '
					+'  WHERE td_clientcd = x.client_code AND   td_clientcd = cm_cd And '
					+'  td_dt BETWEEN '''+@dtFromDate+''' AND '''+@dtToDate+''' And td_Scripcd = ss_cd   '				 
		 End	 
		SET @StrString = @StrString +' ) a ORDER BY TradeDate'
	
	 If @strProduct = 'FO'
	   Begin
		 BEGIN TRY
		 INSERT INTO @TBL_TradedDetailsFO 
		 EXEC(@StrString) 
		 IF @strOutputType = 'X'
			 BEGIN
			   SET @XMLDATA1 = 
			   (SELECT * FROM @TBL_TradedDetailsFO order by ClientCode, SerialNo  
			     FOR XML PATH('CapGain')
			   )
			   SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
				   return 1
			 END
		 ELSE
			 BEGIN
			   SELECT * FROM @TBL_TradedDetailsFO  
			   ORDER BY SerialNo  
			 END 
	     SET @o_vcErrorFlag  = 'S'
         SET @o_vcErrorMessage = 'Process Executed'
	     RETURN 1
	    END TRY
	    BEGIN CATCH
	      SET @o_vcErrorFlag  = 'E'
          SET @o_vcErrorMessage = ERROR_MESSAGE()
          RETURN 1
	    END CATCH
       End

      ELSE
	   Begin
		BEGIN TRY
		 INSERT INTO @TBL_TradedDetails
		 EXEC(@StrString) 
		 IF @strOutputType = 'X'
			 BEGIN
			   SET @XMLDATA1 = 
			   (SELECT * FROM @TBL_TradedDetails order by ClientCode, SerialNo  
			     FOR XML PATH('CapGain')
			   )
			   SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
				   return 1
			 END
		 ELSE
			 BEGIN
			   SELECT * FROM @TBL_TradedDetails  
			   ORDER BY SerialNo  
			 END 
	     SET @o_vcErrorFlag  = 'S'
         SET @o_vcErrorMessage = 'Process Executed'
	     RETURN 1
	    END TRY
	    BEGIN CATCH
	      SET @o_vcErrorFlag  = 'E'
          SET @o_vcErrorMessage = ERROR_MESSAGE()
          RETURN 1
	    END CATCH
       End
      END
	END
	ELSE
    IF @strRepType = 'Receipts'
    BEGIN
	  DECLARE @tbl_JReceipts TABLE(SerialNo INT IDENTITY(1,1), Type VARCHAR(20), 
	  ClientCode VARCHAR(20), DocumentNo VARCHAR(20), DATE VARCHAR(20),
	  Particular VARCHAR(500), Debit MONEY, Credit MONEY)
	  
	  SET @StrString = @strHeader+' '+' SELECT ''1'' Type, ld_clientcd as ClientCode, ld_documentno DocumentNo, '
	  +' ltrim(rtrim(convert(CHAR, convert(DATETIME, ld_dt), 103))) DATE, '
	                   +' ld_Particular Particular, 0 Chequeno, convert(DECIMAL(15, 2), '
					   +' CASE ld_documenttype WHEN ''R'' THEN (- 1) ELSE 1 END * ld_amount) Amount '
                       +' FROM ledger WITH (NOLOCK), @tbl_UserList X '
                       +' WHERE ld_documenttype = ''R'' AND ld_clientcd = X.Client_COde '
					   +' AND ld_dt BETWEEN '''+@dtFromDate+''' AND '''+@dtToDate+''''  
                       +' ORDER BY ld_dt DESC '
	   BEGIN TRY
	    INSERT INTO @tbl_JReceipts (Type, ClientCode, DocumentNo, DATE,
	    Particular, Debit, Credit)
		EXEC(@StrString) 
  
		IF @strOutputType = 'X'
		BEGIN
		  SET @XMLDATA1 = (SELECT A.*, CLIENTNAME =  CM_NAME  
		  FROM @tbl_JReceipts a, client_master(NOLOCK) B
		  WHERE A.ClientCode = B.CM_CD
		  order by ClientCode, SerialNo  
		  FOR XML PATH('CapGain'))
	      SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
		  RETURN 1
		END
		ELSE
		BEGIN
		  SELECT * FROM @tbl_JReceipts  
		  ORDER BY SerialNo  
		END 
	    SET @o_vcErrorFlag  = 'S'
        --SET @o_vcErrorMessage = 'Process Executed'
	    RETURN 1
	  END TRY
	  BEGIN CATCH
	    SET @o_vcErrorFlag  = 'E'
        SET @o_vcErrorMessage = ERROR_MESSAGE()
        RETURN 1
	  END CATCH			
	END
	ELSE
    IF @strRepType in('Payments','GSTInvoice','GSTReversal')
    BEGIN
	  DECLARE @tbl_JPayments TABLE(SerialNo INT IDENTITY(1,1), Type VARCHAR(20), 
	  ClientCode VARCHAR(20), DocumentNo VARCHAR(20), DATE VARCHAR(20),
	  Particular VARCHAR(500), Debit MONEY, Credit MONEY)
	  
	  SET @StrString = @strHeader+' '+' SELECT ''2'' Type,ld_clientcd as ClientCode,  ld_documentno DocumentNo, ld_dt DATE, '
	            +' ld_Particular Particular, 0 Chequeno, convert(DECIMAL(15, 2), CASE ld_documenttype WHEN ''R'' THEN '
				+' (- 1) ELSE 1 END * ld_amount) Amount '
                +' FROM ledger WITH (NOLOCK), @tbl_UserList X '
                +' WHERE ld_documenttype = CASE WHEN '''+@strRepType+''' = ''Payments'' THEN ''P'' WHEN '''+@strRepType+''' = ''GSTInvoice'' THEN ''G'' '
				+' WHEN '''+@strRepType+''' = ''GSTReversal'' THEN ''F'' ELSE '''' END '
				+' AND ld_clientcd = X.Client_COde '
				+' AND ld_dt BETWEEN '''+@dtFromDate+''' AND '''+@dtToDate+''''  
                +' ORDER BY ld_dt DESC '
	  BEGIN TRY
	    
		INSERT INTO @tbl_JPayments (Type, ClientCode, DocumentNo, DATE,
	    Particular, Debit, Credit)
		EXEC(@StrString) 
		
		IF @strOutputType = 'X'
		BEGIN
		  SET @XMLDATA1 = (SELECT A.*, CLIENTNAME =  CM_NAME  FROM @tbl_JPayments a, client_master(NOLOCK) B
		  WHERE A.ClientCode = B.CM_CD
		  order by ClientCode, SerialNo  
		  FOR XML PATH('CapGain'))
	      SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
		  RETURN 1
		END
		ELSE
		BEGIN
		  SELECT * FROM @tbl_JPayments  
		  ORDER BY SerialNo  
		END 
	    SET @o_vcErrorFlag  = 'S'
        --SET @o_vcErrorMessage = 'Process Executed'
	    RETURN 1
	  END TRY
	  BEGIN CATCH
	    SET @o_vcErrorFlag  = 'E'
        SET @o_vcErrorMessage = ERROR_MESSAGE()
        RETURN 1
	  END CATCH			
	END
	ELSE
    IF @strRepType = 'Journals'
    BEGIN
	  DECLARE @tbl_Journals TABLE(SerialNo INT IDENTITY(1,1), Type VARCHAR(20), 
	  ClientCode VARCHAR(20), DocumentNo VARCHAR(20), DATE VARCHAR(20),
	  Particular VARCHAR(100), Debit MONEY, Credit MONEY)
	  
	  SET @StrString = @strHeader+' '+' SELECT ''3'' Type, ld_clientcd as ClientCode, ld_documentno DocumentNo,  ld_dt DATE, '
	       +' ld_Particular Particular, CASE ld_debitflag WHEN ''D'' THEN convert(DECIMAL(15, 2), ld_amount) ELSE 0 END Debit '
	       +' , CASE ld_debitflag WHEN ''D'' THEN 0 ELSE convert(DECIMAL(15, 2), - ld_amount) END Credit '
           +' FROM ledger WITH (NOLOCK) , @tbl_UserList X '
           +' WHERE ld_documenttype = ''J'' AND ld_clientcd = X.Client_COde  AND ld_dt BETWEEN '''+@dtFromDate+''' AND '''+@dtToDate+''''  
           +' ORDER BY ld_dt DESC'
	  BEGIN TRY
	    
		INSERT INTO @tbl_Journals (Type, ClientCode, DocumentNo, DATE,
	    Particular, Debit, Credit)
		EXEC(@StrString) 
		
		IF @strOutputType = 'X'
		BEGIN
		  SET @XMLDATA1 = (SELECT A.*, CLIENTNAME =  CM_NAME  FROM @tbl_Journals A , client_master(NOLOCK) B
		  WHERE A.ClientCode = B.CM_CD
		  order by ClientCode, SerialNo   
		  FOR XML PATH('CapGain'))
	      SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
		  RETURN 1
		END
		ELSE
		BEGIN
		  SELECT * FROM @tbl_Journals  
		  ORDER BY SerialNo  
		END 
	    SET @o_vcErrorFlag  = 'S'
        --SET @o_vcErrorMessage = 'Process Executed'
	    RETURN 1
	  END TRY
	  BEGIN CATCH
	    SET @o_vcErrorFlag  = 'E'
        SET @o_vcErrorMessage = ERROR_MESSAGE()
        RETURN 1
	  END CATCH			
	END
	ELSE
    IF @strRepType = 'Bills'
    BEGIN
	  DECLARE @tbl_bills TABLE(SerialNo INT IDENTITY(1,1), Type VARCHAR(20), 
	  ClientCode VARCHAR(20), DocumentNo VARCHAR(20), DATE VARCHAR(20),
	  Particular VARCHAR(100), Debit MONEY, Credit MONEY)
	
	  SET @StrString = @strHeader+' '+' SELECT ''4'' Type, ld_clientcd as ClientCode, ld_documentno DocumentNo, ld_dt DATE, '
	      +' ld_Particular Particular, CASE ld_debitflag WHEN ''D'' THEN convert(DECIMAL(15, 2), ld_amount) ELSE 0 END Debit '
	      +' , CASE ld_debitflag WHEN ''D'' THEN 0 ELSE convert(DECIMAL(15, 2), - ld_amount) END Credit '
          +' FROM ledger WITH (NOLOCK), @tbl_UserList X '
          +' WHERE ld_documenttype = ''B'' AND ld_clientcd = X.Client_COde AND ld_dt BETWEEN '''+@dtFromDate+''' AND '''+@dtToDate+''''  
          +' ORDER BY ld_dt DESC '
	  BEGIN TRY
	    INSERT INTO @tbl_bills (Type, ClientCode, DocumentNo, DATE,
	    Particular, Debit, Credit)
		EXEC(@StrString) 
		
		IF @strOutputType = 'X'
		BEGIN
		  SET @XMLDATA1 = (SELECT A.*, CLIENTNAME =  CM_NAME FROM @tbl_bills A, client_master(NOLOCK) B
		  WHERE A.ClientCode = B.CM_CD
		  order by ClientCode, SerialNo   
		  FOR XML PATH('CapGain'))
	      SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
		  RETURN 1
		END
		ELSE
		BEGIN
		  SELECT * FROM @tbl_bills  
		  ORDER BY SerialNo  
		END 
	    SET @o_vcErrorFlag  = 'S'
        --SET @o_vcErrorMessage = 'Process Executed'
	    RETURN 1
	  END TRY
	  BEGIN CATCH
	    SET @o_vcErrorFlag  = 'E'
        SET @o_vcErrorMessage = ERROR_MESSAGE()
        RETURN 1
	  END CATCH			
	END
	ELSE
    IF @strRepType = 'AGTS'
    BEGIN
	  IF @strProduct LIKE 'Cash' 
	  BEGIN
	    DECLARE @tbl_AGTScash table(SerialNo INT IDENTITY(1,1), td_clientcd VARCHAR(50), ClientName VARCHAR(100), td_scripcd VARCHAR(20), 
		ScripName VARCHAR(100), td_stlmnt VARCHAR(50), td_dt VARCHAR(11), td_bsflag VARCHAR(1),
		Qty MONEY, MarketRate MONEY, Brokerage MONEY, TradeRate MONEY, TradeValue MONEY,
		SEBITO MONEY, GST MONEY, ExchTrxnChrg MONEY, STT MONEY, StampDuty MONEY, OtherCharges MONEY)
	         
	    SET @StrString = @strHeader+' '+' Select td_clientcd, ClientName = CM_NAME, td_scripcd, ss_name AS ScripName, td_stlmnt, td_dt, td_bsflag, '
		   +' CASE td_bsflag WHEN ''B'' THEN td_bqty WHEN ''S'' THEN td_sqty ELSE 0 END Qty, '
           +' td_marketrate as MarketRate, td_brokerage as Brokerage, td_rate as TradeRate, '
           +' TradeValue = cast(round((CASE td_bsflag WHEN ''B'' THEN td_bqty WHEN ''S'' THEN td_sqty ELSE 0 END)*td_rate,2) as money), '
           +' SEBITO = dbo.fnDecryptN(td_Chrg3), '
           +' GST = dbo.fnDecryptN(td_Chrg6), ExchTrxnChrg = dbo.fnDecryptN(td_Chrg7), '
           +' STT = dbo.fnDecryptN(td_Chrg5), StampDuty = dbo.fnDecryptN(td_Chrg2), OtherCharges = dbo.fnDecryptN(td_Chrg4) '
           +' From GLOBAL_TRX(NOLOCK), Client_master(NOLOCK), Securities(NOLOCK), @tbl_UserList X  '
           +' Where td_clientcd = cm_cd and td_dt between '''+@dtFromDate+''' AND '''+@dtToDate+''' and td_clientcd = x.Client_Code '
           +' AND td_scripcd = ss_cd '
		   IF @strRepSubType LIKE '%DateWise' 
		   BEGIN
		     SET @StrString = @StrString +' ORDER BY td_clientcd, td_dt, td_stlmnt, ss_name'
		   END
		   ELSE IF @strRepSubType LIKE '%ItemWise' 
		   BEGIN
		     SET @StrString = @StrString +' ORDER BY td_clientcd, ss_name, td_dt, td_stlmnt'
		   END
	      BEGIN TRY
		    INSERT INTO @tbl_AGTScash(td_clientcd, ClientName, td_scripcd, 
		    ScripName, td_stlmnt, td_dt, td_bsflag, 
			Qty, MarketRate, Brokerage, TradeRate, TradeValue,
		    SEBITO, GST, ExchTrxnChrg, STT, StampDuty, OtherCharges)
		    EXEC(@StrString) 
			
			IF @strOutputType = 'X'
		    BEGIN
		      SET @XMLDATA1 = (SELECT * FROM @tbl_AGTScash  
		      order by SerialNo  
		      FOR XML PATH('CapGain'))
	          SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
			  RETURN 1
		    END
		    ELSE
		    BEGIN
		       SELECT * FROM @tbl_AGTScash  
		       ORDER BY SerialNo  
		    END 
	        SET @o_vcErrorFlag  = 'S'
            --SET @o_vcErrorMessage = 'Process Executed'
	        RETURN 1
	      END TRY
	      BEGIN CATCH
	        SET @o_vcErrorFlag  = 'E'
            SET @o_vcErrorMessage = ERROR_MESSAGE()
            RETURN 1
	    END CATCH			
	  END
	  ELSE IF (@strProduct LIKE 'FO%' OR @strProduct LIKE 'FX%') 
	  BEGIN
	    DECLARE @tbl_AGTSFO TABLE(SerialNo INT IDENTITY(1,1), td_clientcd VARCHAR(20), ClientName VARCHAR(100),
        td_dt VARCHAR(11), 	td_seriesid NUMERIC(11), sm_symbol VARCHAR(50),
		sm_sname VARCHAR(200), td_bsflag VARCHAR(1), Qty money,
		MarketRate MONEY, Brokerage MONEY, TradeRate MONEY, TradeValue MONEY,
		TrxnChrg MONEY, StampDuty MONEY, SEBITO MONEY, Other MONEY, STT MONEY, GST MONEY)
		
	    SET @StrString = @strHeader+' '+' SELECT td_clientcd, CM_NAME, td_dt, td_seriesid, sm_symbol, sm_sname, td_bsflag, CASE td_bsflag '
		+' WHEN ''B'' THEN td_bqty WHEN ''S'' THEN td_sqty ELSE 0 END AS Qty, '
        +' td_marketrate as MarketRate, Brokerage = td_brokerage, td_rate as TradeRate, '
        +' cast(Round((td_bqty * td_rate * sm_multiplier), 2) AS MONEY) TardeValue, '
        +' TrxnChrg = dbo.fnDecryptN(td_Chrg1), StampDuty = dbo.fnDecryptN(td_Chrg2), SEBITO = dbo.fnDecryptN(td_Chrg3),  '
        +' Other = dbo.fnDecryptN(td_Chrg4), STT = dbo.fnDecryptN(td_Chrg5), GST= dbo.fnDecryptN(td_Chrg6) '
        +' FROM Global_Trades(NOLOCK), client_master(NOLOCK), Series_Master(NOLOCK), @tbl_UserList X   '
        +' WHERE td_seriesId = sm_seriesid AND td_exchange = SM_exchange AND td_Segment = sm_Segment AND td_clientcd = cm_cd  '
        +' AND td_dt BETWEEN '''+@dtFromDate+''' AND '''+@dtToDate+''' AND td_Segment = IIF('''+@strProduct+'''=''FO'',''F'',''X'') '
		+' AND td_clientcd = x.Client_Code '
		 IF @strRepSubType LIKE '%DateWise' 
		   BEGIN
		     SET @StrString = @StrString +' ORDER BY td_clientcd, td_dt, sm_sname'
		   END
		   ELSE IF @strRepSubType LIKE '%ItemWise' 
		   BEGIN
		     SET @StrString = @StrString +' ORDER BY td_clientcd, sm_sname, td_dt'
		   END
	    BEGIN TRY
		   --SELECT @StrString
		   INSERT INTO @tbl_AGTSFO (td_clientcd, ClientName, td_dt, td_seriesid, sm_symbol,
		   sm_sname, td_bsflag,Qty, MarketRate, Brokerage, TradeRate, TradeValue,
		   TrxnChrg, StampDuty, SEBITO, Other, STT, GST)
		   EXEC(@StrString) 
		   IF @strOutputType = 'X'
		    BEGIN
		      SET @XMLDATA1 = (SELECT * FROM @tbl_AGTSFO  
		      order by SerialNo  
		      FOR XML PATH('CapGain'))
	          SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
			  RETURN 1
		    END
		    ELSE
		    BEGIN
		       SELECT * FROM @tbl_AGTSFO  
		       ORDER BY SerialNo  
		    END 
		   
	       SET @o_vcErrorFlag  = 'S'
           --SET @o_vcErrorMessage = 'Process Executed'
	       RETURN 1
	    END TRY
	    BEGIN CATCH
	      SET @o_vcErrorFlag  = 'E'
          SET @o_vcErrorMessage = ERROR_MESSAGE()
          RETURN 1
	    END CATCH			
	  END
	END  
	ELSE IF @strRepType = 'Deliveries'
	BEGIN
	  IF @strRepSubType = 'ItemWise' 
	  BEGIN
	    SET @StrString = @strHeader+' '+' SELECT ClientCode,  DATE, TrxNo, Description, Debit, Credit, SUM(Debit-Credit) '
		+' OVER(PARTITION  BY ClientCode  ORDER BY RowNumber) AS Balance, Beneficiery, Settlment FROM('
		+' SELECT x.Client_Code as ClientCode, td_trxdate AS DATE, td_reference AS TrxNo, CASE td_debit_credit WHEN ''D'''
		                               +' THEN cast((td_qty ) AS DECIMAL(15, 0)) ELSE 0 END ''Debit'', '
									   +' CASE td_debit_credit WHEN ''C'' THEN cast((td_qty) AS DECIMAL(15, 0)) '
									   +' ELSE 0 END ''Credit'', 0 ''Balance'', td_description AS Description, '
	                                   +' td_beneficiery AS Beneficiery, td_settlement AS Settlment, ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) AS RowNumber '
                        +' FROM ['+@strDefaultServer+'].'+@strDefaultConn+'.[dbo].TrxDetail a WITH (NOLOCK), ' 
						+' ['+@strDefaultServer+'].'+@strDefaultConn+'.[dbo].Security WITH (NOLOCK), Client_master WITH (NOLOCK), '
						+' ['+@strDefaultServer+'].'+@strDefaultConn+'.[dbo].Beneficiary_type WITH (NOLOCK), DematAct WITH (NOLOCK), @tbl_UserList X '
                        +' WHERE td_isin_code = sc_isincode AND td_ac_type = bt_code AND '
						+' td_trxdate BETWEEN '''+@dtFromDate+''' AND '''+@dtToDate+'''' 
						+' AND td_ac_code = da_actno AND da_clientcd = cm_cd AND cm_cd = x.Client_Code) X1  '
		BEGIN TRY
		  EXEC(@StrString) 
	      SET @o_vcErrorFlag  = 'S'
          SET @o_vcErrorMessage = 'Process Executed'
	      RETURN 1
	    END TRY
	    BEGIN CATCH
	      SET @o_vcErrorFlag  = 'E'
          SET @o_vcErrorMessage = ERROR_MESSAGE()
          RETURN 1
	    END CATCH			
	  END
	  ELSE IF @strRepSubType = 'DateWise' 
	  BEGIN
	    SET @StrString = @strHeader+' '+' SELECT  ClientCode, DATE, ISIN, SecurityDescription, Debit, Credit, SUM(Debit-Credit) '
		+' OVER(PARTITION  BY ClientCode  ORDER BY RowNumber) AS Balance FROM( '
		+' SELECT X.Client_code as ClientCode, td_trxdate AS DATE, td_isin_code AS ISIN, sc_isinname AS SecurityDescription, CASE td_debit_credit WHEN '
			+' ''D'' THEN cast((td_qty) AS DECIMAL(15, 0)) ELSE 0 END ''Debit'', CASE '
		+' td_debit_credit WHEN ''C'' THEN cast((td_qty) AS DECIMAL(15, 0)) ELSE 0 END ''Credit'', ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) AS RowNumber  '
        +' FROM ['+@strDefaultServer+'].'+@strDefaultConn+'.DBO.TrxDetail a WITH (NOLOCK), '
		+' ['+@strDefaultServer+'].'+@strDefaultConn+'.[dbo].Security WITH (NOLOCK), Client_master WITH (NOLOCK), '
		+' ['+@strDefaultServer+'].'+@strDefaultConn+'.[dbo].Beneficiary_type WITH (NOLOCK), DematAct WITH (NOLOCK), @tbl_UserList X '
        +' WHERE td_isin_code = sc_isincode AND td_ac_type = bt_code '
		+' AND td_trxdate BETWEEN '''+@dtFromDate+''' AND '''+@dtToDate+''''  
		+' AND td_ac_code = da_actno AND da_clientcd = cm_cd AND cm_cd  = x.Client_Code) x123 '
		BEGIN TRY
		  EXEC(@StrString) 
	      SET @o_vcErrorFlag  = 'S'
          SET @o_vcErrorMessage = 'Process Executed'
	      RETURN 1
	    END TRY
	    BEGIN CATCH
	      SET @o_vcErrorFlag  = 'E'
          SET @o_vcErrorMessage = ERROR_MESSAGE()
          RETURN 1
	    END CATCH	
	  END
	END
  END
  ELSE if @strReportName = 'CapitalGain'
  BEGIN
    IF @strRepType = 'Dividend'
    BEGIN
	  DECLARE @tbl_CapitalGainDividend TABLE(SerialNo int identity(1,1),
	  ClientCode VARCHAR(50), ClientName VARCHAR(50),
	  DividendDate VARCHAR(11), ScripCode VARCHAR(20), ScripName VARCHAR(100), 
	  NoOfShare MONEY, DivRate MONEY, Amount MONEY)
	  
	  SET @StrString = @strHeader+' '+'SELECT DV_Clientcd ClientCode, cm_name As ClientName,  DV_Dt DividendDate, DV_Scripcd ScripCode, ss_lname ScripName, '
      +' DV_NoOfShare NoOfShare, cast(DV_Amount / DV_NoOfShare AS MONEY) DivRate, DV_Amount Amount '
      +' FROM INVPL_DIVIDEND(NOLOCK), Securities(NOLOCK), Client_Master(NOLOCK), Branch_master(NOLOCK),  @tbl_UserList X '
      +' WHERE DV_Clientcd = cm_cd AND CM_CD = X.CLIENT_cODE AND cm_brboffcode = bm_branchcd '
	  +' AND DV_scripcd = ss_cd AND DV_Amount > 0 '
	  +' AND DV_Dt BETWEEN '''+@dtFromDate+''' AND '''+@dtToDate+'''' 
      +' ORDER BY DV_Clientcd, DV_Dt, ss_lname '
      BEGIN TRY
	     INSERT INTO @tbl_CapitalGainDividend(ClientCode, ClientName, DividendDate, ScripCode,
		 ScripName, NoOfShare, DivRate, Amount)
		 EXEC(@StrString) 
	     SET @o_vcErrorFlag  = 'S'
         SET @o_vcErrorMessage = 'Process Executed'
		 IF @strOutputType = 'X'
		 BEGIN
		   SET @XMLDATA1 = (SELECT * FROM @tbl_CapitalGainDividend order by SerialNo  FOR XML PATH('CapGain'))
	       SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
		 END
		 ELSE
		 BEGIN
		   SELECT * FROM @tbl_CapitalGainDividend order by SerialNo
		 END
	     RETURN 1
	  END TRY
	  BEGIN CATCH
	    SET @o_vcErrorFlag  = 'E'
        SET @o_vcErrorMessage = ERROR_MESSAGE()
        RETURN 1
	  END CATCH
	END
	ELSE IF @strRepType = 'TradeListing'
	BEGIN
	  DECLARE @tbl_CapitalGainTradeListing TABLE(SerialNo INT IDENTITY(1,1), 
	  td_clientcd VARCHAR(50), ClientName VARCHAR(165),
	  td_scripcd VARCHAR(20), ScripName VARCHAR(100), Bqty MONEY, BRate MONEY, BAmt MONEY,
	  sqty MONEY, SRate MONEY, SAmt MONEY, NetQty MONEY, Nrate MONEY, NAmt MONEY)
	  
	  SET @StrString = @strHeader+' '+'SELECT Rtrim(td_clientcd) td_clientcd, CM_NAME AS ClientName, td_scripcd, Rtrim(ss_lname) AS ScripName, convert(DECIMAL(15, 0), sum( '
			+' td_bqty)) Bqty, convert(DECIMAL(15, 2), CASE WHEN sum(td_rate * td_bqty) > 0 THEN sum(td_rate * '
						+' td_bqty) / sum(td_bqty) ELSE 0 END) BRate, convert(DECIMAL(15, 2), sum(td_bqty * '
			+' td_rate)) BAmt, convert(DECIMAL(15, 0), sum(td_sqty)) sqty, convert(DECIMAL(15, 2), CASE WHEN sum('
					+' td_rate * td_sqty) > 0 THEN sum(td_rate * td_sqty) / sum(td_sqty) ELSE 0 END) SRate, convert('
		+' DECIMAL(15, 2), sum(td_sqty * td_rate)) SAmt, convert(DECIMAL(15, 0), sum(td_bqty - td_sqty)) NetQty, '
		+' CASE WHEN convert(DECIMAL(15, 0), sum(td_bqty - td_sqty))<> 0 THEN round(sum((td_bqty - td_sqty) * td_rate)/ '
      +' sum(td_bqty - td_sqty),2) ELSE 0 END NetRate, '
	  +' convert(DECIMAL(15, 2), sum((td_bqty - td_sqty) * td_rate)) NAmt '
      +' FROM TRX_INVPL(NOLOCK), Securities(NOLOCK), Client_master(NOLOCK), @tbl_UserList X '
      +' WHERE td_clientcd = cm_cd AND CM_CD = X.CLIENT_cODE AND td_scripcd = ss_cd AND td_dt '
	  +' BETWEEN '''+@dtFromDate+''' AND '''+@dtToDate+''''
      +' GROUP BY td_clientcd, CM_NAME, td_scripcd, Rtrim(ss_lname) '
      +' ORDER BY Rtrim(td_clientcd), Rtrim(ss_lname) '
	  BEGIN TRY
	     
	     INSERT INTO @tbl_CapitalGainTradeListing(td_clientcd, ClientName,
	     td_scripcd, ScripName, Bqty, BRate, BAmt, sqty, 
		 SRate, SAmt, NetQty, Nrate, NAmt)
		 EXEC(@StrString) 
	     SET @o_vcErrorFlag  = 'S'
         SET @o_vcErrorMessage = 'Process Executed'
		 IF @strOutputType = 'X'
		 BEGIN
		   SET @XMLDATA1 = (SELECT * FROM @tbl_CapitalGainTradeListing order by SerialNo  FOR XML PATH('CapGain'))
	       SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
		 END
		 ELSE
		 BEGIN
		   SELECT * FROM @tbl_CapitalGainTradeListing order by SerialNo
		 END
	     RETURN 1
	  END TRY
	  BEGIN CATCH
	    SET @o_vcErrorFlag  = 'E'
        SET @o_vcErrorMessage = ERROR_MESSAGE()
        RETURN 1
	  END CATCH
	END
  END
  ELSE if @strReportName = 'Download'
  BEGIN
    DECLARE @Eop_Owner VARCHAR(50)='', @EOP_DataBase VARCHAR(50)='', @strEServer VARCHAR(50)='',
	@Cop_Owner VARCHAR(50)='', @COP_DataBase VARCHAR(50)='', @strCServer VARCHAR(50)='', @CommexES VARCHAR(MAx)=''
   
    SELECT @strEServer = LTRIM(RTRIM(OP_SERVER)), @eop_Owner = LTRIM(RTRIM(OP_OWNER)), @eOP_DataBase = LTRIM(RTRIM(OP_DataBase)) 
    FROM Other_Products(NOLOCK) WHERE OP_Product = 'ESIGN-TRADEPLUS'
    AND OP_Status='A'
	
	
    SELECT @CommexES = sp_sysvalue FROM WebParameter(NOLOCK) 
	WHERE sp_parmcd='CommexES'
	
	SELECT @strCServer = VALUE FROM (
    SELECT * FROM  dbo.fn_SplitString(@CommexES,'/')) X1
    WHERE X1.Position=1
	
	SELECT @COP_DataBase = VALUE FROM (
    SELECT * FROM  dbo.fn_SplitString(@CommexES,'/')) X1
    WHERE X1.Position=2
	
	SELECT @Cop_Owner = VALUE FROM (
    SELECT * FROM  dbo.fn_SplitString(@CommexES,'/')) X1
    WHERE X1.Position=3
	
		
   -- select @strRepType 
    IF @strRepType = 'LIST'
	BEGIN
      if ISNULL(@EOP_DataBase,'') <> ''
	  BEGIN
	    
	    DECLARE @TBL_DOWNLOAD TABLE(SerialNo int identity(1,1), ClientCode VARCHAR(50), ClientName VARCHAR(200), 
		Doctype VARCHAR(50), Download VARCHAR(50), DocumentNo VARCHAR(100), DocumentDesc VARCHAR(500),
		DocumentDate VARCHAR(20),SettlementNo VARCHAR(20), ContractNo VARCHAR(20))
       
        IF ISNULL(@strEServer,'') = ''
	    BEGIN
	      SET @StrString = @strHeader+' select  ''Equity/Derivative'' Doctype, ''Download'' as download, dd_srno = cast(dd_srno as VARCHAR(50))+''/Equity/Derivative'', '
              +' do_desc, dd_dt as dd_dt,dd_stlmnt, '
              +' dd_contractno, dd_clientcd as [ClientCode]'
              +' from '+@EOP_DataBase+'.'+@Eop_Owner+'.'+'digital_details, '+@EOP_DataBase+'.'+@Eop_Owner+'.'+'DocumentType_master ,  @tbl_UserList X '
              +' where dd_clientcd =  X.CLIENT_cODE '
              +' and dd_dt between '''+@dtFromDate+''' and '''+@dtToDate+''''
              +' and dd_filetype = do_cd  '
              +' and ((dd_filetype = DBO.fn_GetEsignDocType('''+@strDocType+'''' 
			  + ','''','''','''','''') and '''+@strDocType+''' <> '''') OR '''+@strDocType+''' = '''' )' 
             +' Order by convert(datetime,dd_dt) desc '
     	END
        ELSE 
        BEGIN
		  SET @StrString = @strHeader+' select ''Equity/Derivative'' Doctype, ''Download'' as download, dd_srno = cast(dd_srno as VARCHAR(50))+''/Equity/Derivative'', '
              +' do_desc, dd_dt as dd_dt,dd_stlmnt, '
              +' dd_contractno, dd_clientcd as [ClientCode]'
              +' from ['+@strEServer+'].'+@EOP_DataBase+'.'+@Eop_Owner+'.'+'digital_details'+', ['+@strEServer+'].'+@EOP_DataBase+'.'+@Eop_Owner+'.'+'DocumentType_master ,  @tbl_UserList X '
              +' where dd_clientcd =  X.CLIENT_cODE '
              +' and dd_dt between '''+@dtFromDate+''' and '''+@dtToDate+''''
              +' and dd_filetype = do_cd  '
              +' and ((dd_filetype = DBO.fn_GetEsignDocType('''+@strDocType+'''' 
			  + ','''','''','''','''') and '''+@strDocType+''' <> '''') OR '''+@strDocType+''' = '''' )' 
             +' Order by convert(datetime,dd_dt) desc '
		END		
        BEGIN TRY
		 -- select @StrString
		  INSERT INTO @TBL_DOWNLOAD(Doctype, Download, DocumentNo, DocumentDesc, DocumentDate, SettlementNo, ContractNo, [ClientCode])
		  EXEC(@StrString)
		  

		  BEGIN TRY
		  SET @strEServer = ''
		  SET @Eop_Owner = '' 
		  SET @EOP_DataBase = ''
		  
          DECLARE CurfilterLastFinYear
		  CURSOR FOR SELECT EServer = LTRIM(RTRIM(OP_SERVER)), eop_Owner = LTRIM(RTRIM(OP_OWNER)), 
		  eOP_DataBase = LTRIM(RTRIM(OP_DataBase)) 
          FROM Other_Products(NOLOCK) WHERE OP_Product LIKE 'TPLUSESIGN%'
          AND OP_Status='A'
	      
		  OPEN CurfilterLastFinYear 
          FETCH NEXT FROM CurfilterLastFinYear INTO @strEServer, @Eop_Owner, @EOP_DataBase
          WHILE @@FETCH_STATUS = 0
          BEGIN 
		    IF ISNULL(@strEServer,'') = ''
	        BEGIN
	          SET @StrString = @strHeader+' select  ''Equity/Derivative'' Doctype, ''Download'' as download, dd_srno = cast(dd_srno as VARCHAR(50))+''/Equity/Derivative'', '
              +' do_desc, dd_dt as dd_dt,dd_stlmnt, '
              +' dd_contractno, dd_clientcd as [ClientCode]'
              +' from '+@EOP_DataBase+'.'+@Eop_Owner+'.'+'digital_details, '+@EOP_DataBase+'.'+@Eop_Owner+'.'+'DocumentType_master ,  @tbl_UserList X '
              +' where dd_clientcd =  X.CLIENT_cODE '
              +' and dd_dt between '''+@dtFromDate+''' and '''+@dtToDate+''''
              +' and dd_filetype = do_cd  '
              +' and ((dd_filetype = DBO.fn_GetEsignDocType('''+@strDocType+'''' 
			  + ','''','''','''','''') and '''+@strDocType+''' <> '''') OR '''+@strDocType+''' = '''' )' 
             +' Order by convert(datetime,dd_dt) desc '
     	    END
            ELSE 
            BEGIN
		      SET @StrString = @strHeader+' select ''Equity/Derivative'' Doctype, ''Download'' as download, dd_srno = cast(dd_srno as VARCHAR(50))+''/Equity/Derivative'', '
              +' do_desc, dd_dt as dd_dt,dd_stlmnt, '
              +' dd_contractno, dd_clientcd as [ClientCode]'
              +' from ['+@strEServer+'].'+@EOP_DataBase+'.'+@Eop_Owner+'.'+'digital_details'+', ['+@strEServer+'].'+@EOP_DataBase+'.'+@Eop_Owner+'.'+'DocumentType_master ,  @tbl_UserList X '
              +' where dd_clientcd =  X.CLIENT_cODE '
              +' and dd_dt between '''+@dtFromDate+''' and '''+@dtToDate+''''
              +' and dd_filetype = do_cd  '
              +' and ((dd_filetype = DBO.fn_GetEsignDocType('''+@strDocType+'''' 
			  + ','''','''','''','''') and '''+@strDocType+''' <> '''') OR '''+@strDocType+''' = '''' )' 
             +' Order by convert(datetime,dd_dt) desc '
		    END		
			
			INSERT INTO @TBL_DOWNLOAD(Doctype, Download, DocumentNo, DocumentDesc, DocumentDate, SettlementNo, ContractNo, [ClientCode])
		    EXEC(@StrString)
		  
            FETCH NEXT FROM CurfilterLastFinYear INTO @strEServer, @Eop_Owner, @EOP_DataBase
          END
          CLOSE CurfilterLastFinYear
          DEALLOCATE CurfilterLastFinYear
		  END TRY
		  BEGIN CATCH
		    SET @o_vcErrorFlag  = 'E'
            SET @o_vcErrorMessage = ERROR_MESSAGE()
		  END CATCH
		
		  IF ISNULL(@COP_DataBase,'') <> '' AND ISNULL(@strCServer,'') = ''
		  BEGIN
		     SET @StrString = @strHeader+' select  ''Commodity/Derivative'' Doctype, ''Download'' as download, dd_srno = cast(dd_srno as VARCHAR(50))+''/Commodity/Derivative'', '
              +' do_desc, dd_dt as dd_dt,dd_stlmnt, '
              +' dd_contractno, dd_clientcd as [ClientCode]'
              +' from '+@COP_DataBase+'.'+@Cop_Owner+'.'+'digital_details, '+@COP_DataBase+'.'+@cop_Owner+'.'+'DocumentType_master ,  @tbl_UserList X '
              +' where dd_clientcd =  X.CLIENT_cODE '
              +' and dd_dt between '''+@dtFromDate+''' and '''+@dtToDate+''''
              +' and dd_filetype = do_cd  '
              +' and ((dd_filetype = DBO.fn_GetEsignDocType('''+@strDocType+'''' 
			  + ','''','''','''','''') and '''+@strDocType+''' <> '''') OR '''+@strDocType+''' = '''' )' 
              +' Order by convert(datetime,dd_dt) desc '
			  INSERT INTO @TBL_DOWNLOAD(Doctype, Download, DocumentNo, DocumentDesc, DocumentDate, SettlementNo, ContractNo, [ClientCode])
		      EXEC(@StrString)
		  END
		  
		  IF ISNULL(@strCServer,'') <> '' AND ISNULL(@COP_DataBase,'') <> ''
		  BEGIN
		     SET @StrString = @strHeader+' select  ''Commodity/Derivative'' Doctype, ''Download'' as download, dd_srno = cast(dd_srno as VARCHAR(50))+''/Commodity/Derivative'', '
              +' do_desc, dd_dt as dd_dt,dd_stlmnt, '
              +' dd_contractno, dd_clientcd as [ClientCode]'
              +' from ['+@strCServer+'].'+@COP_DataBase+'.'+@Cop_Owner+'.'+'digital_details, ['+@strCServer+'].'+@COP_DataBase+'.'+@cop_Owner+'.'+'DocumentType_master ,  @tbl_UserList X '
              +' where dd_clientcd =  X.CLIENT_cODE '
              +' and dd_dt between '''+@dtFromDate+''' and '''+@dtToDate+''''
              +' and dd_filetype = do_cd  '
              +' and ((dd_filetype = DBO.fn_GetEsignDocType('''+@strDocType+'''' 
			  + ','''','''','''','''') and '''+@strDocType+''' <> '''') OR '''+@strDocType+''' = '''' )' 
              +' Order by convert(datetime,dd_dt) desc '
			  INSERT INTO @TBL_DOWNLOAD(Doctype, Download, DocumentNo, DocumentDesc, DocumentDate, SettlementNo, ContractNo, [ClientCode])
		      EXEC(@StrString)
		  END
		  
		 UPDATE A SET A.[ClientName] = CM_NAME
         FROM @TBL_DOWNLOAD A, Client_Master M
         WHERE A.[ClientCode] = M.CM_cD		
		 
		 
		 IF @strOutputType = 'X'
		 BEGIN
		   SET @XMLDATA1 = (SELECT * FROM @TBL_DOWNLOAD order by SerialNo  FOR XML PATH('Download'))
	       SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
		 END
		 ELSE
		 BEGIN
		   SELECT * FROM @TBL_DOWNLOAD order by SerialNo
		 END
 	     SET @o_vcErrorFlag  = 'S'
          --SET @o_vcErrorMessage = 'Process Executed'
	      RETURN 1
		END TRY
        BEGIN CATCH
		  SELECT ERROR_MESSAGE()
		  SET @o_vcErrorFlag  = 'E'
          SET @o_vcErrorMessage = ERROR_MESSAGE()
          RETURN 1
        END CATCH		
	  END
	  else
	  BEGIN
	    SELECT ERROR_MESSAGE()
		SET @o_vcErrorFlag  = 'E'
        SET @o_vcErrorMessage = 'Connection Error'
        RETURN 1
      END	  
	END  
	ELSE IF @strRepType = 'DOCUMENT'
	BEGIN
	  
	  DECLARE @TBL_BASE64 TABLE (Base64 VARCHAR(MAX),FileName VARCHAR(MAX))
      IF ISNULL(@EOP_DataBase,'') <> ''
	  BEGIN
	    IF ISNULL(@strEServer,'') = ''
	    BEGIN
		  SET @strString = @strHeader+' SELECT Base64 = DBO.fnBinaryToBase64(dd_signature), FileName = replace(DD_FileName,''\\'','''') '
          +' FROM  '+@EOP_DataBase+'.DBO.Digital_details(NOLOCK), @tbl_UserList X  ' 
		  +' WHERE CAST(dd_srno AS VARCHAR)+''/Equity/Derivative'' = '''+CAST(@strDocNO AS VARCHAR(MAX))+''' and dd_clientcd =  X.CLIENT_cODE  '
		END
		Else
		BEGIN
		  SET @strString = @strHeader+' SELECT Base64 = DBO.fnBinaryToBase64(dd_signature), FileName = replace(DD_FileName,''\\'','''') '
          +' FROM  ['+@strEServer+'].'+@EOP_DataBase+'.DBO.Digital_details , @tbl_UserList X  ' 
		  +' WHERE CAST(dd_srno AS VARCHAR)+''/Equity/Derivative''  = '''+CAST(@strDocNO AS VARCHAR(MAX))+''' and dd_clientcd =  X.CLIENT_cODE  '
		END
         		
        BEGIN TRY
		  --SELECT @StrString
		  INSERT INTO @TBL_BASE64(Base64, FileName)
		  EXEC(@StrString)
		  
		  SET @strEServer = ''
		  SET @Eop_Owner = '' 
		  SET @EOP_DataBase = ''
		  
		  BEGIN TRY
          DECLARE CurfilterLastFinYearF
		  CURSOR FOR SELECT EServer = LTRIM(RTRIM(OP_SERVER)), eop_Owner = LTRIM(RTRIM(OP_OWNER)), 
		  eOP_DataBase = LTRIM(RTRIM(OP_DataBase)) 
          FROM Other_Products(NOLOCK) WHERE OP_Product LIKE 'TPLUSESIGN%'
          AND OP_Status='A'
	      
		  OPEN CurfilterLastFinYearF 
          FETCH NEXT FROM CurfilterLastFinYearF INTO @strEServer, @Eop_Owner, @EOP_DataBase
          WHILE @@FETCH_STATUS = 0
          BEGIN 
		    IF ISNULL(@strEServer,'') = ''
	        BEGIN
		      SET @strString = @strHeader+' SELECT Base64 = DBO.fnBinaryToBase64(dd_signature), FileName = replace(DD_FileName,''\\'','''') '
              +' FROM  '+@EOP_DataBase+'.DBO.Digital_details(NOLOCK), @tbl_UserList X  '
			  +' WHERE CAST(dd_srno AS VARCHAR)+''/Equity/Derivative'' = '''+CAST(@strDocNO AS VARCHAR(MAX))+''' and dd_clientcd =  X.CLIENT_cODE  '
		    END
		    Else
		    BEGIN
		      SET @strString = @strHeader+' SELECT Base64 = DBO.fnBinaryToBase64(dd_signature), FileName = replace(DD_FileName,''\\'','''') '
              +' FROM  ['+@strEServer+'].'+@EOP_DataBase+'.DBO.Digital_details, @tbl_UserList X  '
			  +' WHERE CAST(dd_srno AS VARCHAR)+''/Equity/Derivative''  = '''+CAST(@strDocNO AS VARCHAR(MAX))+''' and dd_clientcd =  X.CLIENT_cODE  '
		    END
            
			INSERT INTO @TBL_BASE64(Base64, FileName)
		    EXEC(@StrString)
		  
            FETCH NEXT FROM CurfilterLastFinYearF INTO  @strEServer, @Eop_Owner, @EOP_DataBase
          END
          CLOSE CurfilterLastFinYearF
          DEALLOCATE CurfilterLastFinYearF
		  END TRY
		  BEGIN CATCH
		    SET @o_vcErrorFlag  = 'E'
            SET @o_vcErrorMessage = ERROR_MESSAGE()
		  END CATCH
		  
		  IF EXISTS(SELECT 1 FROM @TBL_BASE64)
		  BEGIN
		    SELECT Base64, FileName FROM @TBL_BASE64
			SET @o_vcErrorFlag  = 'S'
            SET @o_vcErrorMessage = 'Process Executed'
	        RETURN 1
		  END	
		END TRY
        BEGIN CATCH
		  SET @o_vcErrorFlag  = 'E'
          SET @o_vcErrorMessage = ERROR_MESSAGE()
          RETURN 1
        END CATCH	
	  END	
	  
	  IF ISNULL(@COP_DataBase,'') <> '' AND ISNULL(@strCServer,'') = ''
	  BEGIN
	    SET @strString = @strHeader+' SELECT Base64 = DBO.fnBinaryToBase64(dd_signature), FileName = replace(DD_FileName,''\\'','''') '
          +' FROM  '+@COP_DataBase+'.DBO.Digital_details(NOLOCK), @tbl_UserList X  '
		  +' WHERE CAST(dd_srno AS VARCHAR(20))+''/Commodity/Derivative''  = '''+CAST(@strDocNO AS VARCHAR(MAX))+''' and dd_clientcd =  X.CLIENT_cODE  '
		DELETE FROM @TBL_BASE64  
	    INSERT INTO @TBL_BASE64(Base64, FileName)
		EXEC(@StrString)
		IF EXISTS(SELECT 1 FROM @TBL_BASE64)
		BEGIN
		  SELECT Base64, FileName FROM @TBL_BASE64
		  SET @o_vcErrorFlag  = 'S'
          SET @o_vcErrorMessage = 'Process Executed'
	      RETURN 1
		END   
	  END	
	  
	  IF ISNULL(@COP_DataBase,'') <> '' AND ISNULL(@strCServer,'') <> ''
	  BEGIN
	    SET @strString = @strHeader+' SELECT Base64 = DBO.fnBinaryToBase64(dd_signature), FileName = replace(DD_FileName,''\\'','''') '
          +' FROM  ['+@strCServer+'].'+@COP_DataBase+'.DBO.Digital_details(NOLOCK), @tbl_UserList X  '
		  +' WHERE CAST(dd_srno AS VARCHAR(20))+''/Commodity/Derivative''  = '''+CAST(@strDocNO AS VARCHAR(MAX))+''' and dd_clientcd =  X.CLIENT_cODE  '
		DELETE FROM @TBL_BASE64  
	    INSERT INTO @TBL_BASE64(Base64, FileName)
		EXEC(@StrString)
		IF EXISTS(SELECT 1 FROM @TBL_BASE64)
		BEGIN
		  SELECT Base64, FileName FROM @TBL_BASE64
		  SET @o_vcErrorFlag  = 'S'
          SET @o_vcErrorMessage = 'Process Executed'
	      RETURN 1
		END   
	  END	
	  
	  ELSE 
	  BEGIN
	    SET @o_vcErrorFlag  = 'E'
        SET @o_vcErrorMessage = 'Connection Error'
        RETURN 1
      END	

	  
	END  
  END
END
GO

CREATE PROCEDURE stpr_Rpt_ProfitLossMTF @vcXML NVARCHAR(MAX), @o_vcErrorFlag VARCHAR(1) OUTPUT, @o_vcErrorMessage VARCHAR(MAX) OUTPUT 
WITH ENCRYPTION  
AS
BEGIN
 /*
 ///////////////////////////////////////////////////////////////////////////////////////////
 // Create By     : VAIBHAV GARG
 // Created Date  : XX-DEC-2023
 // Description   : 
 // Reviewed By   : 
 // Review Date   : 
 //////////////////////////////////////////////////////////////////////////////////////////
*/
 --- Parameter Declaration
 
  DECLARE @dtFromDate VARCHAR(8)='', @dtToDt VARCHAR(8)='', @ExchSeg VARCHAR(50)='', 
  @strStringMin VARCHAR(MAX)='', @strSplFilter VARCHAR(MAX)='', @strReportType VARCHAR(50)='', 
  @strRateType VARCHAR(50)='',
  @strConsiderOptionBF VARCHAR(1)='Y', @String VARCHAR(MAX)='', 
  @XMLData XML, @strOptionType VARCHAR(MAX)='', @strCompanyCode VARCHAR(1)=''
  
  IF @vcXML = ''
  BEGIN
    SET @o_vcErrorFlag  = 'E'
    SET @o_vcErrorMessage = 'Please Send Input Parameter(s)'
    RETURN 1
  END 

  SET @XMLData = CAST(@vcXML AS XML)
   
  SELECT @dtFromDate =  Isnull(@XMLData.value('(FromDt)[1]', 'VARCHAR(8)'),''),
  @dtToDt =    Isnull(@XMLData.value('(ToDt)[1]', 'VARCHAR(8)'),''),
  @ExchSeg = Isnull(@XMLData.value('(ExchSeg)[1]', 'VARCHAR(100)'),''),
  @strSplFilter = Isnull(@XMLData.value('(SplFilter)[1]', 'VARCHAR(MAX)'),''), -- spl filtter
  @strReportType = Isnull(@XMLData.value('(RepType)[1]', 'VARCHAR(MAX)'),''),
  @strRateType = Isnull(@XMLData.value('(RepSubType)[1]', 'VARCHAR(MAX)'),''),
  @strOptionType = Isnull(@XMLData.value('(OptionType)[1]', 'VARCHAR(MAX)'),''),
  @strCompanyCode = Isnull(@XMLData.value('(CompanyCode)[1]', 'VARCHAR(1)'),'')
  
  IF @strRateType = ''
  BEGIN
    SET @strRateType = 'Market Rate'
  END
  
  DECLARE @SehmentCH_ClgHs VARCHAR(1)='', @ch_EffDt VARCHAR(8)=''
  
  SELECT @SehmentCH_ClgHs = CH_ClgHs FROM ClearingHouse(NOLOCK)
  WHERE CH_CompanyCode = @strCompanyCode AND CH_Segment = 'C' 
  AND CH_EffDt = (SELECT Min(CH_EffDt) FROM ClearingHouse
  WHERE CH_CompanyCode = @strCompanyCode AND CH_Segment = 'C' AND CH_EffDt <= @dtToDt)
  
  DECLARE @tbl_ClientPL TABLE(CompanyCode VARCHAR(10), Exchange VARCHAR(10), Segment VARCHAR(10),  ClientCode VARCHAR(50), ClientName VARCHAR(100), 
  Symbol VARCHAR(50), seriesid INT, ExpiryDate VARCHAR(8), Scrip VARCHAR(100), Multiplier INT, TrxnDate VARCHAR(8), BF_QTY MONEY, BF_CloseRate MONEY, BF_VALUE MONEY, BOT_QTY MONEY, BOT_VALUE MONEY, 
  SOLD_QTY MONEY,SOLD_VALUE MONEY, EX_QTY MONEY, EX_VALUE MONEY, AS_QTY MONEY, AS_VALUE MONEY, MTM MONEY,
  NET_QTY MONEY, CMP MONEY, NET_VALUE MONEY)

  DECLARE @tbl_BSClient TABLE(CompanyCode VARCHAR(10), Exchange VARCHAR(10), Segment VARCHAR(10), ClientCode VARCHAR(50), ClientName VARCHAR(100), 
  Symbol VARCHAR(50), seriesid INT, ExpiryDate VARCHAR(8), Scrip VARCHAR(100), Multiplier INT, TrxnDate VARCHAR(8), BOT_QTY MONEY, BOT_VALUE MONEY, 
  SOLD_QTY MONEY, SOLD_VALUE MONEY)

  DECLARE @tbl_CLClient TABLE(CompanyCode VARCHAR(10), Exchange VARCHAR(10), Segment VARCHAR(10),  ClientCode VARCHAR(50), ClientName VARCHAR(100), 
  Symbol VARCHAR(50), seriesid INT, ExpiryDate VARCHAR(8), Scrip VARCHAR(100), Multiplier INT, TrxnDate VARCHAR(8), EX_QTY MONEY, EX_VALUE MONEY, AS_QTY MONEY, AS_VALUE MONEY)
  
 
  IF OBJECT_ID('tempdb..#tbl_TradeSqrup') IS NOT NULL
  DROP TABLE #tbl_TradeSqrup

  CREATE TABLE #tbl_TradeSqrup (SerialNo INT identity(1, 1), td_companycode VARCHAR(1) ,td_stlmnt VARCHAR(15)
  ,td_clientcd VARCHAR(10) ,td_scripcd VARCHAR(10) ,td_dt VARCHAR(8) ,td_bsflag VARCHAR(1) ,td_bqty MONEY ,td_sqty MONEY
  ,td_rate MONEY ,td_BrokerageType VARCHAR(5))

  IF @strSplFilter = ''
  BEGIN
    SET @strSplFilter = ' 1 = 1'
  END	
  
  IF @strSplFilter <> ''
  BEGIN
    SET @strStringMin  = ' DECLARE @tbl_UserList TABLE (Client_Code VARCHAR(10)) '
	                     +' INSERT INTO @tbl_UserList(Client_Code) SELECT distinct CM_CD FROM Client_master(NOLOCK) CM WHERE '
                         +'	 EXISTS(SELECT 1 FROM MrgTdgFin_Clients(NOLOCK) WHERE  MTFC_CMCD = CM.CM_CD) AND '+@strSplFilter
  END	
  

  CREATE INDEX indx_TradeSqrup ON #tbl_TradeSqrup (td_dt,td_stlmnt)

  CREATE INDEX indx_TradeSqrup1 ON #tbl_TradeSqrup (SerialNo)

    
  SET @string = @strStringMin+' SELECT MTtd_companycode, MTtd_stlmnt, MTtd_clientcd, MTtd_scripcd, MTtd_dt, MTtd_bsflag, '
	+' sum(MTtd_bqty), sum(MTtd_sqty),  '
    +' SUM(MTtd_rate * (MTtd_bqty + MTtd_sqty)), '
    +' IIF(MTtd_TrxFlag =''X'',''SD1'',''DLV'') AS td_BrokerageType  FROM(    '
    +' SELECT MTtd_companycode, MTtd_stlmnt, MTtd_clientcd, MTtd_scripcd, MTtd_dt, MTtd_srno,  '
    +' MTtd_bsflag, MTtd_bqty, MTtd_sqty, MTtd_rate = CAST(MTtd_rate AS MONEY), MTtd_TrxFlag '
    +' FROM MrgTdgFin_TRX(NOLOCK), Settlements(NOLOCK) SETT, @tbl_UserList   '
    +' WHERE MTtd_clientcd = Client_Code  AND MTtd_stlmnt = se_stlmnt  AND MTtd_dt BETWEEN '''+@dtFromDate+''' AND '''+@dtToDt+''''
  IF ISNULL(@ExchSeg,'') <> ''
  BEGIN
    SET @string =   @string+'  AND se_exchange IN(SELECT SUBSTRING(VALUE,2,1) FROM  ReturnTable('''+@ExchSeg+''','','')) '
  END	
	
  SET @string =   @string+') X12 '
    +' GROUP BY MTtd_companycode, MTtd_stlmnt, MTtd_clientcd, MTtd_scripcd, MTtd_dt, MTtd_bsflag , IIF(MTtd_TrxFlag=''X'',''SD1'',''DLV'') '
    +' ORDER BY MTtd_dt'
   
  BEGIN TRY
    INSERT INTO #tbl_TradeSqrup(td_companycode, td_stlmnt, td_clientcd, td_scripcd, td_dt, td_bsflag, td_bqty, td_sqty, td_rate, td_BrokerageType)
	EXEC(@string)
  END TRY
  BEGIN CATCH
    SELECT ERROR_MESSAGE()
  END CATCH  
  
  UPDATE A SET A.td_rate = B.SaleAVGRate*(A.td_bqty + A.td_sqty)
  FROM #tbl_TradeSqrup A, (SELECT td_companycode, td_stlmnt, td_clientcd, td_scripcd, td_dt, td_bsflag,  
  SaleAVGRate = SUM(td_rate * (td_bqty + td_sqty))/SUM(td_bqty + td_sqty)
  FROM TRx(NOLOCK), Settlements(NOLOCK) SETT   
  WHERE td_stlmnt = se_stlmnt  AND td_dt BETWEEN @dtFromDate AND @dtToDt and td_bsflag = 'S'
  Group By td_companycode, td_stlmnt, td_clientcd, td_scripcd, td_dt, td_bsflag ) B
  WHERE A.td_stlmnt = B.td_stlmnt
  AND A.td_clientcd = B.td_clientcd
  AND A.td_scripcd = B.td_scripcd
  AND A.td_dt = B.td_dt
  AND A.td_bsflag = B.td_bsflag
  
  UPDATE #tbl_TradeSqrup
  SET td_rate = CASE WHEN (td_bqty + td_sqty) > 0 THEN td_rate / (td_bqty + td_sqty) ELSE 0 END
	
       
  DECLARE @tbl_ProfileLOss TABLE(ClientCode VARCHAR(50), SettEndDate VARCHAR(8), 
  SettlementNo VARCHAR(50),
  ScripCode VARCHAR(20), ScripTag VARCHAR(1), TradingFlag VARCHAR(1), BuyQty MONEY, BuyRate MONEY, 
  BuyValue MONEY, SaleQty MONEY,  SaleRate MONEY, SaleValue MONEY,
  NetQty MONEY, NetValue MONEY, AvgRate MONEY, CMP MONEY, NotionalPL MONEY)
	
	
  IF @strReportType <> 'Settlementwise Summary'
  BEGIN
	INSERT INTO @tbl_ProfileLOss(ClientCode, ScripCode, ScripTag, BuyQty, BuyRate, BuyValue, SaleQty,SaleRate, SaleValue, NetQty, NetValue, AvgRate)
	SELECT td_clientcd, td_scripcd, IIF(td_brokeragetype = 'DLV','N','Y') AS td_flag,  
	td_bqty = SUM(td_bqty), BuyRate = iif(SUM(td_bqty)>0,round(SUM(td_bqty*td_rate)/SUM(td_bqty),2),0),
    BuyValue = SUM(td_bqty*td_rate), td_sqty = SUM(td_sqty), SaleRate = iif(SUM(td_sqty)>0,round(SUM(td_sqty*td_rate)/SUM(td_sqty),2),0),
    saleValue = SUM(td_sqty*td_rate),  NetQty = SUM(td_bqty)-SUM(td_sqty), NetValue = round(SUM(td_sqty*td_rate) - SUM(td_bqty*td_rate),2),
    AvgRate = abs(iif(SUM(td_bqty)-SUM(td_sqty)<>0,round(SUM(td_sqty*td_rate) - SUM(td_bqty*td_rate),2)/(SUM(td_bqty)-SUM(td_sqty)),0))
    FROM #tbl_TradeSqrup
    Group by td_clientcd, td_scripcd, IIF(td_brokeragetype = 'DLV','N','Y')
  END
  ELSE
  IF @strReportType = 'Settlementwise Summary' 	
  BEGIN
	INSERT INTO @tbl_ProfileLOss(ClientCode, SettEndDate, SettlementNo, ScripCode, ScripTag,  BuyQty, 
	BuyRate, BuyValue, SaleQty,SaleRate, SaleValue, NetQty, NetValue, AvgRate)
	SELECT td_clientcd, se_endt, td_stlmnt, td_scripcd, IIF(td_brokeragetype = 'DLV','N','Y') AS td_flag,  
	td_bqty = SUM(td_bqty), BuyRate = iif(SUM(td_bqty)>0,round(SUM(td_bqty*td_rate)/SUM(td_bqty),2),0),
    BuyValue = SUM(td_bqty*td_rate), td_sqty = SUM(td_sqty), SaleRate = iif(SUM(td_sqty)>0,round(SUM(td_sqty*td_rate)/SUM(td_sqty),2),0),
    saleValue = SUM(td_sqty*td_rate),  NetQty = SUM(td_bqty)-SUM(td_sqty), NetValue = round(SUM(td_sqty*td_rate) - SUM(td_bqty*td_rate),2),
    AvgRate = abs(iif(SUM(td_bqty)-SUM(td_sqty)<>0,round(SUM(td_sqty*td_rate) - SUM(td_bqty*td_rate),2)/(SUM(td_bqty)-SUM(td_sqty)),0))
	FROM #tbl_TradeSqrup X, Settlements(NOLOCK) SETT
	WHERE X.td_stlmnt = SETT.se_stlmnt
    Group by td_clientcd, td_scripcd,  se_endt, td_stlmnt, IIF(td_brokeragetype = 'DLV','N','Y')
  END
	
  DECLARE @CH_ClgHs VARCHAR(1)=@SehmentCH_ClgHs
    
  DECLARE @tbl_CloseRate TABLE(Scrip VARCHAR(20), CloseRate MONEY)
	
  IF @strRateType IN('Market Rate' ,'Average Rate')
  BEGIN 
	INSERT INTO @tbl_CloseRate(Scrip, CloseRate)
	SELECT DISTINCT ScripCode, '' AS CloseRate FROM @tbl_ProfileLOss
	
	IF @CH_ClgHs = 'N'
	BEGIN
	  UPDATE A SET A.CloseRate = B.mk_closerate
	  FROM @tbl_CloseRate A, Market_rates(NOLOCK) B 
      WHERE A.Scrip = B.mk_scripcd AND mk_dt = (select  max(mk_dt) from Market_rates(NOLOCK)  
	  WHERE mk_exchange = 'B' and mk_dt<=@dtToDt) AND  mk_exchange = 'B'
	  	  
	  UPDATE A SET A.CloseRate = B.mk_closerate
	  FROM @tbl_CloseRate A, Market_rates(NOLOCK) B 
      WHERE A.Scrip = B.mk_scripcd 
	  AND mk_dt = (select  max(mk_dt) from Market_rates(NOLOCK)  
	  WHERE mk_exchange = 'N'
	  and mk_dt<=@dtToDt) AND  mk_exchange = 'N'
	END  
	ELSE
	IF @CH_ClgHs = 'B'
	BEGIN
	  UPDATE A SET A.CloseRate = B.mk_closerate
	  FROM @tbl_CloseRate A, Market_rates(NOLOCK) B 
      WHERE A.Scrip = B.mk_scripcd AND mk_dt = (select  max(mk_dt) from Market_rates(NOLOCK)  
	  WHERE mk_exchange = 'N' and mk_dt<=@dtToDt) AND  mk_exchange = 'N'
	  	  
	  UPDATE A SET A.CloseRate = B.mk_closerate
	  FROM @tbl_CloseRate A, Market_rates(NOLOCK) B 
      WHERE A.Scrip = B.mk_scripcd 
	  AND mk_dt = (select  max(mk_dt) from Market_rates(NOLOCK)  
	  WHERE mk_exchange = 'B'
	  and mk_dt<=@dtToDt) AND  mk_exchange = 'B'
	END  
	
	UPDATE A SET A.CloseRate = B.mk_closerate
	FROM @tbl_CloseRate A, Market_rates B
	WHERE mk_dt = (select  max(mk_dt) from Market_rates(NOLOCK)  
	WHERE mk_scripcd = B.mk_scripcd and mk_dt<=@dtToDt)
    AND A.Scrip = B.mk_scripcd	
	AND A.CloseRate = 0
	and EXISTS(SELECT 1 FROM Securities(NOLOCK) 
    WHERE ss_cd = A.Scrip and ss_group in ('F','G','GC'))
	
 	UPDATE A SET A.CMP = CloseRate, A.NotionalPL = (A.NetQty * CloseRate)+ISNULL(NetValue,0)
    FROM @tbl_ProfileLOss A, @tbl_CloseRate B  
	WHERE A.ScripCode = B.Scrip
    AND NetQty <> 0
	
    UPDATE A SET A.NotionalPL = ISNULL(NetValue,0)
    FROM @tbl_ProfileLOss A  
    WHERE NetQty = 0
			
	UPDATE A SET A.NetValue = case when @strRateType IN('Market Rate','Average Rate') 
	then abs(isnull(A.NetQty,0)*isnull(A.CMP,0)) else A.NetValue end 
    FROM @tbl_ProfileLOss A
  END
  
  ELSE IF @strRateType IN('COST')
  BEGIN  
	IF OBJECT_ID('tempdb..#TrxDLV1') IS NOT NULL
	  DROP TABLE #TrxDLV1
    IF OBJECT_ID('tempdb..#TrxSummaryDLV1') IS NOT NULL
	  DROP TABLE #TrxSummaryDLV1
    IF OBJECT_ID('tempdb..#tbl_TradeSqrup1') IS NOT NULL
	  DROP TABLE #tbl_TradeSqrup1
	
    CREATE TABLE  #tbl_TradeSqrup1(SerialNo int identity(1,1), td_companycode VARCHAR(1), td_stlmnt VARCHAR(15), 
	td_clientcd VARCHAR(10), td_scripcd VARCHAR(10), 
    td_dt VARCHAR(8), td_bsflag VARCHAR(1), td_bqty MONEY, td_sqty MONEY, td_rate MONEY, td_marketrate MONEY, td_BrokerageType VARCHAR(5))
	
	CREATE INDEX indx_TradeSqrup1 ON #tbl_TradeSqrup1 (td_dt, td_stlmnt)
    CREATE INDEX indx_TradeSqrup11 ON #tbl_TradeSqrup1 (SerialNo)
	
    INSERT INTO #tbl_TradeSqrup1(td_companycode, td_stlmnt, td_clientcd, td_scripcd, td_dt, td_bsflag, td_bqty, td_sqty, td_rate,
    td_BrokerageType)
	SELECT td_companycode, td_stlmnt, td_clientcd, td_scripcd, td_dt, td_bsflag, td_bqty, td_sqty, td_rate,
    td_BrokerageType ='SD1'
	FROM #tbl_TradeSqrup
	WHERE td_brokeragetype = 'DLV'
      
	
    
    CREATE TABLE #TrxSummaryDLV1 (clientcd VARCHAR(8) NOT NULL, scripcd VARCHAR(6) NOT NULL, Buys MONEY, Sells MONEY)

    INSERT INTO #TrxSummaryDLV1
	SELECT td_clientcd, td_scripcd, Buys, Sells
    FROM (SELECT MAX(td_companycode + left(td_stlmnt, 2)) td_companycode, td_clientcd, cm_name, td_scripcd, ss_name, 
    ss_nsymbol, ss_nseries, sum(td_bqty) AS 'Buys', sum(td_sqty) 'Sells', sum(td_bqty - td_sqty) 'Delivery', 
    count(*) Totalrec, ss_group, cm_type
    FROM #tbl_TradeSqrup1, Client_master, Securities
    WHERE cm_cd = td_clientcd AND td_scripcd = ss_cd
    GROUP BY td_clientcd, cm_name, td_scripcd, ss_cd, ss_name, ss_nsymbol, ss_nseries, ss_group, cm_type
    HAVING sum(td_bqty - td_sqty) <> 0) a

    CREATE TABLE #TrxDLV1 (SrNo NUMERIC, Qty NUMERIC, FinalQty NUMERIC)

    INSERT INTO #TrxDLV1
	SELECT SerialNo, Qty, CASE WHEN NetQty >= Running THEN Qty ELSE NetQty - isNull(PrevRunning, 0) END FinalQty
    FROM (
	SELECT SerialNo, td_clientcd, td_scripcd, td_marketrate,  NetQty, Qty, Running, LAG(
	Running) OVER (
	PARTITION BY td_clientcd, td_scripcd ORDER BY td_dt DESC,  SerialNo DESC) PrevRunning
	FROM (SELECT SerialNo, td_dt, td_clientcd, td_scripcd, td_bqty + td_sqty Qty, td_marketrate,  
	abs(Buys - Sells) NetQty, Sum(td_bqty + td_sqty) 
	OVER (PARTITION BY td_clientcd, td_scripcd ORDER BY td_dt DESC,  SerialNo DESC) Running
	FROM #tbl_TradeSqrup1, Client_master, Securities, #TrxSummaryDLV1
	WHERE cm_cd = td_clientcd AND td_scripcd = ss_cd
	AND td_clientcd = clientcd AND td_scripcd = scripcd AND td_bsflag = CASE WHEN Buys > Sells THEN 'B' ELSE 'S' END) a) b
    WHERE CASE WHEN NetQty >= Running THEN Qty ELSE NetQty - isNull(PrevRunning, 0) END > 0

    INSERT INTO #tbl_TradeSqrup1(td_companycode, td_stlmnt, td_clientcd, td_scripcd, td_dt, td_bsflag, td_bqty, td_sqty, td_rate,
    td_marketrate, td_BrokerageType)
    SELECT td_companycode, td_stlmnt, td_clientcd, td_scripcd, td_dt,
    td_bsflag, CASE td_bsflag WHEN 'B' THEN Qty - FinalQty ELSE 0 END, CASE td_bsflag WHEN 'S' THEN Qty - FinalQty ELSE 0 END
    ,TD_RATE , td_marketrate, td_brokeragetype ='SD1'
    FROM #tbl_TradeSqrup1 , #TrxDLV1
    WHERE SerialNo = srno AND (Qty - FinalQty) > 0

 
    UPDATE #tbl_TradeSqrup1
    SET td_bqty = FinalQty, td_brokeragetype = 'DLV' 
    FROM #TrxDLV1
    WHERE SerialNo = srno  AND td_bsflag = 'B'

    UPDATE #tbl_TradeSqrup1
    SET td_sqty = FinalQty, td_brokeragetype = 'DLV' 
    FROM #TrxDLV1
    WHERE SerialNo = srno and td_bsflag = 'S'

    DELETE #tbl_TradeSqrup1
    WHERE td_bqty + td_sqty = 0


    UPDATE A SET A.CMP = B.AugRate, A.AvgRate = B.AugRate, A.NetValue = ABS(B.NetValue), A.NetQty = B.NetQty
	FROM @tbl_ProfileLOss A, (select td_clientcd, td_scripcd, SUM(td_bqty-td_sqty) As NetQty, 
	Sum((td_sqty*td_rate)-(td_Bqty*td_rate)) As NetValue,
	AugRate = ABS(IIF(SUM(td_bqty-td_sqty)<>0,Sum((td_sqty*td_rate)-(td_Bqty*td_rate))/SUM(td_bqty-td_sqty),0))
	FROM #tbl_TradeSqrup1
	WHERE td_brokeragetype = 'DLV'
	GROUP BY td_clientcd, td_scripcd) B
	where A.ClientCode = B.td_clientcd
	AND A.ScripCode = B.td_scripcd
	AND ScripTag = 'N'
	
	UPDATE A SET NotionalPL = SaleValue-BuyValue
	FROM @tbl_ProfileLOss A
	WHERE buyqty = saleQty
	
	UPDATE A SET NotionalPL = (SaleValue-BuyValue)+(ROUND(NetQty*AvgRate,2))
	FROM @tbl_ProfileLOss A
	WHERE buyqty <> saleQty and buyqty > 0 and saleQty > 0
	  
	UPDATE A SET NotionalPL = 0
	FROM @tbl_ProfileLOss A
	WHERE buyqty <> saleQty and (buyqty = 0 or saleQty = 0)
  END
  
	
  DECLARE @tbl_CashBill TABLE (Tag INT identity(1,1), ClientCode VARCHAR(50), ClientName VARCHAR(50),  SettEndDate varchar(8),
  SettlementNo VARCHAR(50),
  ScripCode VARCHAR(20), 
  ScripName VARCHAR(100), ScripTag VARCHAR(1), TradingFlag VARCHAR(1),
  BuyQty MONEY, BuyRate Money, BuyValue MONEY, SaleQty MONEY,  SaleRate MONEY, SaleValue MONEY, NetQty MONEY, NetValue MONEY, 
  AvgRate MONEY, Cmp MONEY, NotPL MONEY)
	
  IF @strReportType <> 'Settlementwise Summary'
  BEGIN
	INSERT INTO @tbl_CashBill(ClientCode, ClientName,  ScripCode, ScripName,ScripTag, TradingFlag,
	BuyQty, BuyRate, BuyValue, SaleQty, SaleRate, SaleValue, NetQty, NetValue, AvgRate, Cmp, NotPL)
    SELECT ClientCode, ClientName = CM.cm_name,  ScripCode, ScripName = ss_name, ScripTag, TradingFlag, BuyQty, BuyRate, BuyValue, SaleQty, SaleRate, SaleValue, 
	NetQty, NetValue, AvgRate = ABS(AvgRate), 
	CMP =ISNULL(cmp,0) , 
    NotPL  = ISNULL(NotionalPL ,0)
    FROM @tbl_ProfileLOss A, Securities(NOLOCK) S, Client_Master(NOLOCK) cm
    WHERE A.ScripCode = S.ss_cd
	and a.ClientCode = CM.CM_CD
    ORDER BY  ClientCode, ss_name, ScripTag desc
  END
  ELSE	
  IF @strReportType = 'Settlementwise Summary'
  BEGIN
    INSERT INTO @tbl_CashBill(ClientCode, ClientName, SettEndDate, SettlementNo, ScripCode, ScripName,ScripTag, TradingFlag, 
	BuyQty, BuyRate, BuyValue, SaleQty, SaleRate, SaleValue, NetQty, NetValue, AvgRate, Cmp, NotPL)
    SELECT ClientCode, ClientName = CM.cm_name, SettEndDate,SettlementNo,  
	ScripCode, ScripName = ss_name, ScripTag, TradingFlag, BuyQty, BuyRate, BuyValue, SaleQty, SaleRate, SaleValue, NetQty, NetValue, AvgRate = ABS(AvgRate), 
	CMP =ISNULL(cmp,0) , 
    NotPL  = ISNULL(NotionalPL ,0)
    FROM @tbl_ProfileLOss A, Securities(NOLOCK) S, Client_Master(NOLOCK) cm
    WHERE A.ScripCode = S.ss_cd
	and a.ClientCode = CM.CM_CD
    ORDER BY  ClientCode, ss_name, ScripTag desc
  END
  SET @o_vcErrorMessage = 'Process Completed'	
  IF @strOptionType = 'X'
  BEGIN
    DECLARE @XMLDATA1 XML
    IF @strReportType not in( 'Settlementwise Summary','Stock Position Only')
	BEGIN
      
      SET @XMLDATA1 = (select ClientCode, ClientName,  ScripCode, ScripName, ScripTag,  
	  BuyQty, BuyRate, BuyValue, SaleQty, SaleRate, SaleValue, NetQty, NetValue, AvgRate, Cmp, NotPL 
	  from  @tbl_CashBill order by ClientCode, Tag FOR XML PATH('ProfitLoss'))
	  SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
	END
    IF @strReportType = 'Stock Position Only'
    BEGIN    
      SET @XMLDATA1 = (SELECT ClientCode, ClientName,  ScripCode, ScripName, ScripTag,  
	  BuyQty, BuyRate, BuyValue, SaleQty, SaleRate, SaleValue, NetQty, NetValue, AvgRate, Cmp, NotPL 
	  from  @tbl_CashBill where ISNULL(NetQty,0) <> 0 order by ClientCode, Tag FOR XML PATH('ProfitLoss'))
	  SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
	END
  END 
  ELSE
  BEGIN
    IF @strReportType not in( 'Settlementwise Summary','Stock Position Only')
    BEGIN
	  SELECT ClientCode, ClientName,  ScripCode, ScripName, ScripTag,  
	  BuyQty, BuyRate, BuyValue, SaleQty, SaleRate, SaleValue, NetQty, NetValue, AvgRate, Cmp, NotPL 
	  from  @tbl_CashBill order by ClientCode, Tag
    end  
    else IF @strReportType = 'Settlementwise Summary'
    BEGIN
	  select ClientCode, ClientName, SettEndDate = isnull(SettEndDate,''), SettlementNo = isnull(SettlementNo,''), ScripCode, ScripName, ScripTag,  
	  BuyQty, BuyRate, BuyValue, SaleQty, SaleRate, SaleValue, NetQty, NetValue, AvgRate, Cmp, NotPL 
	  from  @tbl_CashBill order by ClientCode, Tag
    end	  
    IF @strReportType = 'Stock Position Only'
    BEGIN
	  select ClientCode, ClientName,  ScripCode, ScripName, ScripTag,  
	  BuyQty, BuyRate, BuyValue, SaleQty, SaleRate, SaleValue, NetQty, NetValue, AvgRate, Cmp, NotPL 
	  from  @tbl_CashBill where ISNULL(NetQty,0) <> 0
	  order by ClientCode, Tag
    END
  END
  SET @o_vcErrorFlag  = 'S'
  
  RETURN 1
END  
GO

CREATE PROCEDURE stpr_Rpt_ProfitLossNewDerv @vcXML NVARCHAR(MAX), @o_vcErrorFlag VARCHAR(1) OUTPUT, @o_vcErrorMessage VARCHAR(MAX) OUTPUT 
WITH ENCRYPTION
AS
BEGIN
 /*
 ///////////////////////////////////////////////////////////////////////////////////////////
 // Create By     : VAIBHAV GARG
 // Created Date  : 05-DEC-2023
 // Description   : 
 // Reviewed By   : 
 // Review Date   : 
 //////////////////////////////////////////////////////////////////////////////////////////
*/
 --- Parameter Declaration
 
  DECLARE @dtFromDate VARCHAR(8), @dtToDt VARCHAR(8), @strUserId VARCHAR(500) = '', @strExchSeg VARCHAR(100),
  @XMLData XML, @strAccountType VARCHAR(500)='', @strTable VARCHAR(50)='', @strString VARCHAR(MAX) = '',
  @blnTplusCommex BIT, @StrCommexConn VARCHAR(MAX) = '', @strCommTable VARCHAR(100)='', @strCommClientMaster VARCHAR(100)='',
  @strCommCompanyExchange VARCHAR(100)='', @strsql1 VARCHAR(500)='', @strsqlstart VARCHAR(MAX)='', @strsqlLast VARCHAR(500)='',
  @strsqlHeader VARCHAR(MAX)='', @strSqlMain VARCHAR(MAX)='', @strSqlExecute VARCHAR(MAX)='', @strOutputType VARCHAR(1), 
  @strProduct VARCHAR(50)='', @strSelectTag VARCHAR(1)='', @strSelectUsers VARCHAR(500)='', @ExchSeg VARCHAR(50)='', 
  @strStringMin VARCHAR(MAX)='', @strSplFilter VARCHAR(MAX)='', @strReportType VARCHAR(50)='', @strRateType VARCHAR(50)='',
  @strConsiderOptionBF VARCHAR(1)='Y', @strStringMinC VARCHAR(MAX)='', @strFIFO VARCHAR(1)='N', @strRequestFrom VARCHAR(1)='W',
  @StrLookup VARCHAR(50)='', @StrSummary VARCHAR(1)='', @strReportDisplay VARCHAR(1)='P', @strCompanyCode VARCHAR(1)='P';
  
  DECLARE @SehmentCH_ClgHs VARCHAR(1)='', @ch_EffDt VARCHAR(8)=''
  
  IF @vcXML = ''
  BEGIN
    SET @o_vcErrorFlag  = 'E'
    SET @o_vcErrorMessage = 'Please Send Input Parameter(s)'
    RETURN 1
  END 

  SET @XMLData = CAST('<root>'+@vcXML+'</root>' AS XML)
  BEGIN TRY
  
  SELECT @dtFromDate = ISNULL(x.value('(FromDt)[1]', 'VARCHAR(8)'),''),
  @strProduct = ISNULL(x.value('(Product)[1]', 'VARCHAR(50)'),'') ,
  @dtToDt =    ISNULL(x.value('(ToDt)[1]', 'VARCHAR(8)'),''),
  @strUserId =  ISNULL(x.value('(UserId)[1]', 'VARCHAR(500)'),''),
  @ExchSeg =  ISNULL(x.value('(ExchSeg)[1]', 'VARCHAR(500)'),''),
  @strSelectTag = ISNULL(x.value('(SelectTag)[1]', 'VARCHAR(1)'),''),
  @strSelectUsers = ISNULL(x.value('(SelectUsers)[1]', 'VARCHAR(500)'),''),
  @strOutputType = ISNULL(x.value('(OutputType)[1]', 'VARCHAR(1)'),''),
  @strSplFilter = ISNULL(x.value('(SplFilter)[1]', 'VARCHAR(MAX)'),''),
  @strReportType = ISNULL(x.value('(RepType)[1]', 'VARCHAR(100)'),''),
  @strRateType = ISNULL(x.value('(RepSubType)[1]', 'VARCHAR(100)'),''),
  @strConsiderOptionBF = ISNULL(x.value('(OptionBF)[1]', 'VARCHAR(100)'),''),
  @strFIFO = ISNULL(x.value('(FIFOTag)[1]', 'VARCHAR(1)'),''),
  @strRequestFrom = ISNULL(x.value('(RequestFrom)[1]', 'VARCHAR(1)'),''),
  @StrLookup = ISNULL(x.value('(ScripCode)[1]', 'VARCHAR(50)'),''),
  @StrSummary = ISNULL(x.value('(RequestSummary)[1]', 'VARCHAR(1)'),''),
  @strReportDisplay = ISNULL(x.value('(ReportDisplay)[1]', 'VARCHAR(1)'),''),
  @strCompanyCode = ISNULL(x.value('(CompanyCode)[1]', 'VARCHAR(1)'),'')
  FROM @XMLData.nodes('/root') AS XTbl(x) 
  
  
  IF @strReportDisplay IN('D','E','A','X') AND EXISTS(SELECT 1 FROM CLIENT_MASTER(NOLOCK) WHERE CM_cD = @strUserId)
  BEGIN
    DECLARE @o_Message NVARCHAR(MAX)=''
    EXEC stpr_TypestHeaderProc @strUserid, '', '', @strCompanyCode,  @o_Message OUTPUT
	  
    SET @o_Message = REPLACE(@o_Message,'##ReportName##','Profit and Loss Report (Derv) for '  + CONVERT(VARCHAR(30), Cast(@dtFromDate as date), 103) + ' To ' + CONVERT(VARCHAR(30), Cast(@dtToDt as date), 103))
    SET @o_Message = REPLACE(@o_Message,'##Grid1##','')
    SET @o_Message = REPLACE(@o_Message,'##Grid2##','')
    SET @o_Message = REPLACE(@o_Message,'##Grid3##','')
    SET @o_Message = REPLACE(@o_Message,'##Grid4##','')
	SET @o_Message = REPLACE(@o_Message,'##PageOrientation##','Landscape')
	SET @o_Message = REPLACE(@o_Message,'##PageSize##','A4')
	--SET @o_Message = REPLACE(@o_Message,'##PageOrientation##','Landscape')
	IF @strReportDisplay IN('E','D','X')
	BEGIN
	  SET @o_Message = REPLACE(@o_Message,'##FormatGrid##','Grid1')
	  SET @strOutputType = 'G'
	END 
    ELSE 
	BEGIN
	  SET @o_Message = REPLACE(@o_Message,'##FormatGrid##','')
	END 
	
    SET @o_Message = '<root>' + @o_Message + '</root>';
  
    DECLARE @xmlData3 XML = CAST(@o_Message AS XML);
	
	DECLARE @DynamicColumns NVARCHAR(MAX);
    
	SET  @DynamicColumns = '';
  
    WITH DistinctNodes AS (
    SELECT DISTINCT
       NodeName = X.n.value('local-name(.)', 'NVARCHAR(100)')
    FROM @xmlData3.nodes('/root/ClientDetail/*') AS X(n))
    
    SELECT @DynamicColumns = @DynamicColumns+','+
        'LTRIM(RTRIM(X1.value(''(' + XX.NodeName + ')[1]'', ''NVARCHAR(MAX)''))) AS [' + XX.NodeName + ']'
    FROM DistinctNodes XX
	WHERE NodeName NOT IN('Grid2','Grid3','Grid4')
   
    SELECT @DynamicColumns = SUBSTRING(@DynamicColumns,2,LEN(@DynamicColumns)-1) 
  
    DECLARE @sql NVARCHAR(MAX);
    SET @sql = '
    SELECT ' + @DynamicColumns + '
    FROM @xmlData3.nodes(''/root/ClientDetail'') AS T(X1)';
  
    EXEC sp_executesql @sql, N'@xmlData3 XML', @xmlData3;
	
 
	IF @strReportDisplay NOT IN('A')
	BEGIN
	  SELECT ColumnName, ColumnHeading, ColumnWidth, ColumnAlignement, ColumnFormat, Columnstyle, DecimalPlace, ColumnTotal,
      ColumnHide = CASE WHEN Userid = '1' THEN 'Y' ELSE 'N'	END   
      FROM tbl_ReportGridViewFormat(NOLOCK) 
	  WHERE ReportCode='InvestorReport'
      and ReportCategroy = 'DERV_Series Wise' AND ColumnVisible = '0'
      Order By Orderby
    END
  END	

  
  IF LEN(ISNULL(@StrLookup,'')) <= 2  
  BEGIN
    SET @StrLookup = ''
  END
  
  if ISNULL(@StrSummary,'') =''
  Begin
    SET @StrSummary = 'N'
  END
  
  IF ISNULL(@strRequestFrom,'') =''
  BEGIN
    SET @strRequestFrom = 'W'
  END
  
  if isnull(@strFIFO,'') = ''
  begin
    SET @strFIFO = 'N'
  END
  
  if ISNULL(@strConsiderOptionBF,'')=''
  BEGIN
    SET @strConsiderOptionBF = 'Y'
  END
  
  IF @strRateType = ''
  BEGIN
    SET @strRateType = 'Market Rate'
  END
  
  DECLARE @tbl_Exchange TABLE(ExchangeCode VARCHAR(20))
  
  IF ISNULL(@ExchSeg,'') <> ''
  BEGIN
    IF CHARINDEX('AF',@ExchSeg) > 0
	BEGIN
	  DECLARE @ExchClearHS VARCHAR(1)=''
	  SELECT @ExchClearHS = CH_ClgHs  
	  FROM ClearingHouse Where CH_Segment= 'F' 
	  AND CH_EffDt = (select MAX(CH_EffDt) from ClearingHouse Where CH_Segment= 'F'
	  AND CH_EffDt <= @dtFromDate) 
	  IF ISNULL(@ExchClearHS,'') = 'N'
	  BEGIN
	    INSERT INTO @tbl_Exchange 
		SELECT CES_CD FROM CompanyExchangeSegments(NOLOCK) 
        WHERE CES_Segment = 'F&O'       
		UNION ALL
		SELECT CES_CD from CompanyExchangeSegments(NOLOCK) 
        WHERE CES_CD IN(SELECT VALUE FROM  ReturnTable(@ExchSeg,','))  
	  END
	END
	ELSE
	BEGIN
	  INSERT INTO @tbl_Exchange 
	  SELECT CES_CD from CompanyExchangeSegments(NOLOCK) 
      WHERE CES_CD IN(SELECT VALUE FROM ReturnTable(@ExchSeg,','))  
	END
	SELECT @ExchSeg = @ExchSeg+','+ExchangeCode from @tbl_Exchange
  END
   
  
  CREATE TABLE #tbl_ClientPL (CompanyCode VARCHAR(10), Exchange VARCHAR(10), Segment VARCHAR(10),  ClientCode VARCHAR(50), ClientName VARCHAR(100), 
  Symbol VARCHAR(50), seriesid INT, ExpiryDate VARCHAR(8), Scrip VARCHAR(100), Multiplier INT, TrxnDate VARCHAR(8), 
  BF_QTY numeric, BF_CloseRate MONEY, BF_VALUE MONEY, BOT_QTY numeric, BOT_VALUE MONEY, 
  SOLD_QTY numeric,SOLD_VALUE MONEY, EX_QTY numeric, EX_VALUE MONEY, AS_QTY numeric, AS_VALUE MONEY, MTM MONEY,
  NET_QTY numeric, CMP MONEY, NET_VALUE MONEY, AccountType VARCHAR(1))
  
  CREATE INDEX indx_ClientPL ON #tbl_ClientPL (seriesid)
    

  DECLARE @tbl_BSClient TABLE(CompanyCode VARCHAR(10), Exchange VARCHAR(10), Segment VARCHAR(10), ClientCode VARCHAR(50), ClientName VARCHAR(100), 
  Symbol VARCHAR(50), seriesid INT, ExpiryDate VARCHAR(8), Scrip VARCHAR(100), Multiplier INT, TrxnDate VARCHAR(8), BOT_QTY numeric, BOT_VALUE MONEY, 
  SOLD_QTY numeric, SOLD_VALUE MONEY)

  DECLARE @tbl_CLClient TABLE(CompanyCode VARCHAR(10), Exchange VARCHAR(10), Segment VARCHAR(10),  ClientCode VARCHAR(50), ClientName VARCHAR(100), 
  Symbol VARCHAR(50), seriesid INT, ExpiryDate VARCHAR(8), Scrip VARCHAR(100), Multiplier INT, TrxnDate VARCHAR(8), EX_QTY numeric, EX_VALUE MONEY, AS_QTY numeric, AS_VALUE MONEY)
  

  SET @strStringMin  = 'DECLARE @tbl_UserList TABLE(Client_Code VARCHAR(50)) '
  +' INSERT INTO @tbl_UserList(Client_Code) '
  +' SELECT * FROM DBO.[fn_GetClients]('''+@strUserId+''','''+@strSelectTag+''','''+@strSelectUsers+''') '
  
 
 
  IF @strProduct = 'DERV'
  BEGIN 
    
    DECLARE  @iNoOfDay INT = 7, @dtDate VARCHAR(8)='', @iDateCounter INT = 0
    
    WHILE @iDateCounter<= @iNoOfDay
    BEGIN
      IF NOT EXISTS(select 1 from Fholiday_master where hm_companycode = @strCompanyCode and hm_exchange = 'N' and hm_segment ='F' 
      and hm_dt = CONVERT(VARCHAR,DATEADD(DAY,@iDateCounter,CAST(@dtFromDate AS DATE)),112))
      BEGIN
	    SET @dtFromDate =  CONVERT(VARCHAR,DATEADD(DAY,@iDateCounter,@dtFromDate),112)
	    GOTO ABC;
      END
	  SET @iDateCounter = @iDateCounter + 1
    END
    ABC:
	
	/*
    SET @iDateCounter = 0
    
	WHILE @iDateCounter<= @iNoOfDay
    BEGIN
      IF NOT EXISTS(select 1 from Fholiday_master where hm_companycode = 'A' and hm_exchange = 'N' and hm_segment ='F' 
      and hm_dt = CONVERT(VARCHAR,DATEADD(DAY,@iDateCounter,CAST(@dtToDt AS DATE)),112))
      BEGIN
	    SET @dtToDt =  CONVERT(VARCHAR,DATEADD(DAY,@iDateCounter*-1,@dtToDt),112)
	    GOTO ABC1;
      END
	  SET @iDateCounter = @iDateCounter + 1
    END
    ABC1:
	*/
	
	
	IF @strSplFilter = ''
	BEGIN
	  SET @strStringMin  = 'DECLARE @tbl_UserList TABLE(Client_Code VARCHAR(50)) '
      +' INSERT INTO @tbl_UserList(Client_Code) '
      +' SELECT * FROM DBO.[fn_GetClients]('''+@strUserId+''','''+@strSelectTag+''','''+@strSelectUsers+''') '
	END  
	ELSE
    IF @strSplFilter <> ''
    BEGIN
      SET @strStringMinC  = ' DECLARE @tbl_UserList TABLE (Client_Code VARCHAR(10)) '
	                     +' INSERT INTO @tbl_UserList(Client_Code) SELECT distinct CM_CD FROM Client_master(NOLOCK) WHERE 1 = 1  AND '+@strSplFilter
      SET @strStringMin = @strStringMinC					 
    END	

    IF ISNULL(@strFIFO,'N') = 'N'
	BEGIN
	  SET @strString  = @strStringMin+' SELECT  td_companycode, TD_Exchange, TD_Segment, td_clientcd, SM_DESC, sm_underlying, td_seriesid,td_expirydt, '
      +' sm_multiplier, td_dt = '''+@dtFromDate+''', SUM(td_bqty - td_sqty) AS BFQty, '
	  +' BF_CloseRate = (CASE WHEN sum(td_bqty- td_sqty) <> 0 THEN SUM(CASE WHEN TD_BSFlag=''B'' THEN td_bqty*CAST(td_rate AS numeric(19,6)) '
	  +' ELSE td_sqty*CAST(td_rate AS numeric(19,6))*-1 END)'
	  +' /sum(td_bqty- td_sqty) ELSE 0 END), '
      +' BF_VALUE = SUM(CASE WHEN TD_BSFlag=''B'' THEN td_bqty*CAST(td_rate AS numeric(19,6))*-1 ELSE td_sqty*CAST(td_rate AS numeric(19,6)) END) '
	  +' FROM Trades (NOLOCK), Series_master(NOLOCK), @tbl_UserList X  '
      +' WHERE  td_dt < '''+@dtFromDate+''' '
      +' AND td_clientcd = X.Client_Code '
      +' AND td_expirydt >= '''+@dtFromDate+''' '
      +' AND td_exchange = sm_exchange and td_segment = sm_segment '
      +' and td_seriesid = sm_seriesid '
      +' and sm_expirydt >= '''+@dtFromDate +''''
      +' AND (('''+@strConsiderOptionBF+''' = ''N'' AND sm_prodtype NOT IN(''EO'',''CO'',''IO'')) OR '''+@strConsiderOptionBF+''' = ''Y'')'
      +' AND ltrim(rtrim(td_groupid)) <> ''B'' '
	
	  IF ISNULL(@ExchSeg,'') <> ''
      BEGIN
        SET @strString =   @strString+'  AND td_companycode+td_exchange+td_segment IN(SELECT VALUE FROM  ReturnTable('''+@ExchSeg+''','',''))'
      END	
	  
	  IF ISNULL(@StrLookup,'') <> ''
      BEGIN
        SET @strString =   @strString+'  AND TD_Exchange+TD_Segment+cast(td_seriesid as varchar)  = '''+@StrLookup+''''
      END	
	  
	
      SET @strString =   @strString+' GROUP BY td_companycode, TD_Exchange, TD_Segment, td_clientcd, SM_DESC,sm_underlying, td_seriesid, td_expirydt, sm_multiplier '
      +' HAVING sum(td_bqty - td_sqty) <> 0 '
	  BEGIN TRY
        INSERT INTO #tbl_ClientPL(CompanyCode, Exchange, Segment, ClientCode, Scrip, Symbol, seriesid, ExpiryDate, Multiplier, TrxnDate,  BF_QTY, BF_CloseRate, BF_VALUE)
	    EXEC(@strString)
	  END TRY
	  BEGIN CATCH
	    SET @o_vcErrorFlag  = 'E'
        SET @o_vcErrorMessage = ERROR_MESSAGE()
        RETURN 1
	  END CATCH
	  
	  UPDATE A SET A.BF_CloseRate = ms_prcloseprice, a.BF_VALUE = (a.BF_QTY*a.Multiplier*ms_prcloseprice)*-1
      FROM #tbl_ClientPL A, Market_summary(NOLOCK) X, Series_master SR  
      WHERE ms_seriesid = seriesid 
      and ms_exchange = exchange and ms_segment = Segment
      and ms_dt = (select  max(ms_dt) from Market_summary(NOLOCK)  
	  WHERE ms_exchange = X.ms_exchange and ms_segment = X.ms_segment and ms_dt <= @dtFromDate)
	  AND A.exchange = SR.sm_exchange
	  AND A.Segment  = sm_Segment
	  AND A.seriesid = SR.sm_seriesid
	  AND ((sm_prodtype NOT IN('EO','CO','IO') AND @strRateType in('Underlying Close Price')) 
	  OR @strRateType not in('Underlying Close Price'))
	
	
      UPDATE A SET A.BF_CloseRate = ms_prcloseprice, a.BF_VALUE = 0
      FROM #tbl_ClientPL A, Market_summary(NOLOCK) X, Series_master SR  
      WHERE ms_seriesid = seriesid 
      and ms_exchange = exchange and ms_segment = Segment
      and ms_dt = (select  max(ms_dt) from Market_summary(NOLOCK)  
	  WHERE ms_exchange = X.ms_exchange and ms_segment = X.ms_segment and ms_dt <= @dtFromDate)
	  AND A.exchange = SR.sm_exchange
	  AND A.Segment  = sm_Segment
	  AND A.seriesid = SR.sm_seriesid
	  AND sm_prodtype IN('EO','CO','IO') 
	  AND @strRateType = 'Do not Valuate' 
	
	  IF @strRateType = 'Underlying Close Price'
	  BEGIN
	    declare @BFseriesid INT, @spotCloseRate MONEY=0, @strExchange VARCHAR(1)='',
		@strSegment VARCHAR(1)=''
	    DECLARE db_CursorRateBF CURSOR FOR         
        SELECT distinct seriesid, Exchange,  Segment
        FROM #tbl_ClientPL A 
	    where BF_QTY <> 0 and EXISTS(SELECT 1 FROM Series_master(NOLOCK)
	    WHERE sm_Segment =  A.Segment AND sm_exchange = A.Exchange AND sm_seriesid = A.seriesid   
		AND sm_productcd = 'OPTSTK')
        OPEN db_CursorRateBF       
        FETCH NEXT FROM db_CursorRateBF INTO @BFseriesid, @strExchange, @strSegment
        WHILE @@FETCH_STATUS = 0     
        BEGIN
	      SELECT TOP 1 @spotCloseRate = mk_closerate FROM Market_Rates(NOLOCK) X WHERE mk_scripcd IN(
          SELECT SS_cD FROM Securities WHERE ss_bsymbol IN(
          SELECT sm_symbol FROM Series_master(NOLOCK) WHERE sm_exchange = @strExchange 
		  AND sm_Segment = @strSegment AND sm_seriesid = @BFseriesid))
          AND mk_dt   IN(SELECT MAX(mk_dt) FROM Market_Rates(NOLOCK) WHERE mk_dt < @dtFromDate)
          ORDER BY CASE WHEN mk_exchange='N' THEN 1 ELSE 2 END
	  
	      UPDATE A SET A.BF_CloseRate = @spotCloseRate, a.BF_VALUE =(a.BF_QTY*@spotCloseRate)*-1
	      FROM #tbl_ClientPL A
	      WHERE A.seriesid = @BFseriesid
		  AND A.Exchange = @strExchange
		  AND A.Segment = @strSegment
		  
	      FETCH NEXT FROM db_CursorRateBF INTO @BFseriesid, @strExchange, @strSegment
        END        
        CLOSE db_CursorRateBF        
        DEALLOCATE db_CursorRateBF	
	  END 
	  
	  SET @strString  = @strStringMin+' SELECT td_companycode, TD_Exchange, TD_Segment, td_clientcd, SM_DESC, sm_underlying, td_seriesid, '
	  +' td_expirydt, sm_multiplier, TrxnDate = CASE WHEN ISNULL('''+@strReportType+''','''')  = ''Series Wise Detail'' THEN  td_dt ELSE '''+@dtFromDate+''' END,'
      +' SUM(td_bqty) BQty, '
      +' sum(td_bqty * cast(td_rate as money)*sm_multiplier) BuyValue, '
      +' SUM(td_Sqty) SQty, '
      +' sum(td_sqty * cast(td_rate as money)*sm_multiplier) SaleValue '
      +' FROM Trades (NOLOCK), Series_master(NOLOCK) , @tbl_UserList X  '
      +' WHERE  td_dt >= '''+@dtFromDate+''' '
      +' and td_dt <= '''+@dtToDt+''' '
      +' AND td_clientcd = X.Client_Code '
      +' AND td_expirydt >= '''+@dtFromDate+''' '
      +' AND td_exchange = sm_exchange and td_segment = sm_segment  '
      +' and td_seriesid = sm_seriesid '
	  
	  /*
      +' AND ltrim(rtrim(td_groupid)) <> ''B'' '
 	  */
      IF ISNULL(@ExchSeg,'') <> ''
      BEGIN
        SET @strString =   @strString+'  AND td_companycode+td_exchange+td_segment IN(SELECT VALUE FROM  ReturnTable('''+@ExchSeg+''','',''))'
      END	
	  
	  IF ISNULL(@StrLookup,'') <> ''
      BEGIN
        SET @strString =   @strString+'  AND TD_Exchange+TD_Segment+cast(td_seriesid as varchar)  = '''+@StrLookup+''''
      END	
	
      SET @strString =   @strString+' GROUP BY td_companycode, TD_Exchange, TD_Segment, td_clientcd, SM_DESC,sm_underlying, td_seriesid,td_expirydt, sm_multiplier'
	  +',  CASE WHEN ISNULL('''+@strReportType+''','''') = ''Series Wise Detail'' THEN  td_dt ELSE  '''+@dtFromDate+''' END '
      
	  BEGIN TRY
        INSERT INTO @tbl_BSClient (CompanyCode, Exchange, Segment,  ClientCode, Scrip, Symbol, seriesid, 
        ExpiryDate, Multiplier, TrxnDate, BOT_QTY, BOT_VALUE, SOLD_QTY,SOLD_VALUE)
	    EXEC(@strString)
	  END TRY
	  BEGIN CATCH
	    SET @o_vcErrorFlag  = 'E'
        SET @o_vcErrorMessage = ERROR_MESSAGE()
        RETURN 1
	  END CATCH
      

      SET @strString  = @strStringMin+'SELECT ex_companycode, ex_Exchange, ex_segment, ex_clientcd, SM_DESC, sm_underlying, ex_seriesid, '
       +'	sm_expirydt, sm_multiplier, CASE WHEN ISNULL('''+@strReportType+''','''') = ''Series Wise Detail'' THEN  ex_dt ELSE '''+@dtFromDate+''' END'
      +'	 ,  ex_eqty = sum(ex_eqty) , '
      +' EX_VALUE = sum((ex_eqty)*ex_diffbrokrate*sm_multiplier*-1), ex_aqty = sum(ex_aqty), '
      +' AS_VALUE = sum((ex_aqty)*ex_diffbrokrate*sm_multiplier*-1) '
      +' From Exercise(NOLOCK), Series_master(NOLOCK), @tbl_UserList X  '
      +' WHERE ex_dt between '''+@dtFromDate+''' and '''+@dtToDt+''' '
      +' and ex_clientcd = X.Client_Code '
      +' and sm_expirydt >= '''+@dtFromDate+''' ' 
      +' and ex_exchange = sm_exchange '
      +' and ex_segment = sm_segment And ex_seriesid = sm_seriesid '
	
	
      IF ISNULL(@ExchSeg,'') <> ''
      BEGIN
        SET @strString =   @strString+'  AND ex_companycode+ex_exchange+ex_segment IN(SELECT VALUE FROM  ReturnTable('''+@ExchSeg+''','',''))'
		
      END	
	    
	  IF ISNULL(@StrLookup,'') <> ''
      BEGIN
        SET @strString =   @strString+'  AND ex_Exchange+ex_segment+cast(ex_seriesid as varchar)  = '''+@StrLookup+''''
      END	
	  
      SET @strString =   @strString+' GROUP BY ex_companycode, ex_Exchange, ex_segment, ex_clientcd, SM_DESC, sm_underlying, ex_seriesid, sm_expirydt, sm_multiplier '
	  +', CASE WHEN ISNULL('''+@strReportType+''','''') = ''Series Wise Detail'' THEN ex_dt ELSE '''+@dtFromDate+''' END '
    
	  BEGIN TRY
        INSERT INTO @tbl_CLClient(CompanyCode, Exchange, Segment, ClientCode, Scrip, Symbol, seriesid, ExpiryDate, Multiplier, TrxnDate, EX_QTY, EX_VALUE,
        AS_QTY, AS_VALUE)
	    EXEC(@strString)
	  END TRY
	  BEGIN CATCH
	    SET @o_vcErrorFlag  = 'E'
        SET @o_vcErrorMessage = ERROR_MESSAGE()
        RETURN 1
	  END CATCH
	
      UPDATE A SET A.BOT_QTY = B.BOT_QTY, A.BOT_VALUE = B.BOT_VALUE, A.SOLD_QTY = B.SOLD_QTY,
      A.SOLD_VALUE = B.SOLD_VALUE
      FROM #tbl_ClientPL A, @tbl_BSClient B
      WHERE A.ClientCode = B.ClientCode
      AND A.Scrip = B.Scrip
      AND A.Exchange = B.Exchange
      AND A.seriesid = B.seriesid
	  AND A.Segment = B.Segment
	  AND CASE WHEN A.TrxnDate='' THEN @dtFromDate ELSE A.TrxnDate END = 
	  CASE WHEN B.TrxnDate='' THEN @dtFromDate ELSE B.TrxnDate END

      INSERT INTO #tbl_ClientPL(CompanyCode, Exchange, Segment, ClientCode, Scrip, Symbol, seriesid, ExpiryDate, Multiplier, TrxnDate, BF_QTY, BF_CloseRate, BF_VALUE,
      BOT_QTY, BOT_VALUE, SOLD_QTY, SOLD_VALUE)
      SELECT CompanyCode, Exchange, Segment, ClientCode, Scrip, Symbol, seriesid, ExpiryDate, Multiplier, TrxnDate, BF_QTY = 0, BF_CloseRate= 0, BF_VALUE = 0,
      BOT_QTY, BOT_VALUE, SOLD_QTY, SOLD_VALUE
      FROM @tbl_BSClient B
      WHERE NOT EXISTS(SELECT 1 FROM #tbl_ClientPL A WHERE A.ClientCode = B.ClientCode
      AND A.Scrip = B.Scrip
      AND A.Exchange = B.Exchange
      AND A.seriesid = B.seriesid
	  AND A.Segment = B.Segment
	  and CASE WHEN A.TrxnDate='' THEN @dtFromDate ELSE A.TrxnDate END 
	  = CASE WHEN B.TrxnDate='' THEN @dtFromDate ELSE B.TrxnDate END)
	  
	  
      UPDATE A SET A.EX_QTY = B.EX_QTY, A.EX_VALUE = B.EX_VALUE, A.AS_QTY = B.AS_QTY,
      A.AS_VALUE = B.AS_VALUE
      FROM #tbl_ClientPL A, @tbl_CLClient B
      WHERE A.ClientCode = B.ClientCode
      AND A.Scrip = B.Scrip
      AND A.Exchange = B.Exchange
      AND A.seriesid = B.seriesid
	  AND A.Segment = B.Segment
	  and CASE WHEN A.TrxnDate='' THEN @dtFromDate ELSE A.TrxnDate END = 
	  CASE WHEN B.TrxnDate='' THEN @dtFromDate ELSE B.TrxnDate END
	  
	  INSERT INTO #tbl_ClientPL(CompanyCode, Exchange, Segment, ClientCode, Scrip, Symbol, seriesid, ExpiryDate, Multiplier, TrxnDate, BF_QTY, BF_CloseRate, BF_VALUE,
      BOT_QTY, BOT_VALUE, SOLD_QTY, SOLD_VALUE, EX_QTY, EX_VALUE, AS_QTY, AS_VALUE)
      SELECT CompanyCode, Exchange, Segment, ClientCode, Scrip, Symbol, seriesid, ExpiryDate, Multiplier, 
	  TrxnDate, BF_QTY = 0, BF_CloseRate= 0, BF_VALUE = 0,
      BOT_QTY = 0, BOT_VALUE = 0, SOLD_QTY = 0, SOLD_VALUE = 0, EX_QTY, EX_VALUE, AS_QTY, AS_VALUE
      FROM @tbl_CLClient B
      WHERE NOT EXISTS(SELECT 1 FROM #tbl_ClientPL A WHERE A.ClientCode = B.ClientCode
      AND A.Scrip = B.Scrip
      AND A.Exchange = B.Exchange
      AND A.seriesid = B.seriesid
	  AND A.Segment = B.Segment
	  and CASE WHEN A.TrxnDate='' THEN @dtFromDate ELSE A.TrxnDate END 
	  = CASE WHEN B.TrxnDate='' THEN @dtFromDate ELSE B.TrxnDate END)
  
    END
	
	ELSE IF ISNULL(@strFIFO,'N') = 'Y'
	BEGIN
	  IF OBJECT_ID('tempdb..#tbl_ClientPLFIFO') IS NOT NULL
      DROP TABLE #tbl_ClientPLFIFO

      CREATE TABLE #tbl_ClientPLFIFO (CompanyCode VARCHAR(10), Exchange VARCHAR(10), Segment VARCHAR(10),  ClientCode VARCHAR(50), 
      ClientName VARCHAR(100), 
      Symbol VARCHAR(50), seriesid INT, ExpiryDate VARCHAR(8), Scrip VARCHAR(100), Multiplier INT, TrxnDate VARCHAR(8), 
      td_SRNO INT,  td_bsflag VARCHAR(1), Qty_NS MONEY, VALUES_NS MONEY, td_Rate MONEY)
    
	  CREATE INDEX indx_ClientPLFIFO ON #tbl_ClientPLFIFO (seriesid)

      IF OBJECT_ID('tempdb..#tbl_DelvTrxn') IS NOT NULL
        DROP TABLE #tbl_DelvTrxn
      IF OBJECT_ID('tempdb..#tbl_DelvTrxn1') IS NOT NULL
        DROP TABLE #tbl_DelvTrxn1
      IF OBJECT_ID('tempdb..#TrxSummaryDLV1') IS NOT NULL
        DROP TABLE #TrxSummaryDLV1
      IF OBJECT_ID('tempdb..#TrxDLV1') IS NOT NULL
        DROP TABLE #TrxDLV1
      IF OBJECT_ID('tempdb..#tbl_CloseRate') IS NOT NULL
        DROP TABLE #tbl_CloseRate
      IF OBJECT_ID('tempdb..#tbl_DelvTrxnN') IS NOT NULL
        DROP TABLE #tbl_DelvTrxnN
	  IF OBJECT_ID('tempdb..#tbl_DelvTrxnN1') IS NOT NULL
        DROP TABLE #tbl_DelvTrxnN1
	  IF OBJECT_ID('tempdb..#tbl_DelvTrxnN2') IS NOT NULL
        DROP TABLE #tbl_DelvTrxnN2
      IF OBJECT_ID('tempdb..#tbl_Rep') IS NOT NULL
        DROP TABLE #tbl_Rep
	
	  DECLARE @tbl_UserList TABLE(Client_Code VARCHAR(50))
	  IF @strSplFilter = ''
	  BEGIN
	    INSERT INTO @tbl_UserList(Client_Code) 
        SELECT * FROM DBO.[fn_GetClients](@strUserId,@strSelectTag,@strSelectUsers) 
	  END  
	  ELSE
      IF @strSplFilter <> ''
      BEGIN
        SET @strStringMinC  = 'SELECT distinct CM_CD FROM Client_master(NOLOCK) WHERE 1 = 1  AND '+@strSplFilter
		INSERT INTO @tbl_UserList(Client_Code) 
		EXEC(@strStringMinC)
      END	
  
      CREATE TABLE #tbl_DelvTrxn (
      SerialNo int identity(1,1), td_companycode VARCHAR(1), TD_Exchange VARCHAR(1), 
	  TD_Segment VARCHAR(1), td_SRNO INT, td_dt VARCHAR(8), td_clientcd VARCHAR(20), 
	  td_scripcd VARCHAR(20), td_expirydt VARCHAR(8), SM_DESC VARCHAR(500), sm_underlying VARCHAR(50),
      sm_multiplier INT, td_bsflag VARCHAR(1), Qty_NS MONEY, VALUES_NS MONEY, td_Rate MONEY, 
	  XTAG11 INT, LONG_TAG VARCHAR(1), SQR_TAG VARCHAR(1), Tmp_RefNo numeric, td_Filler1 VARCHAR(8))

      INSERT INTO #tbl_DelvTrxn(td_SRNO, td_companycode, TD_Exchange, TD_Segment, 
	  td_dt, td_clientcd, td_scripcd, td_expirydt, SM_DESC, sm_underlying,
	  sm_multiplier, td_bsflag, Qty_NS, VALUES_NS, td_Rate)
      SELECT  td_SRNO, td_companycode, TD_Exchange, TD_Segment, td_dt, td_clientcd, td_seriesid,  td_expirydt, SM_DESC, sm_underlying,
	  sm_multiplier, td_bsflag, Qty_NS = ISNULL(td_bqty,0)+ISNULL(td_sqty,0), 
      VALUES_NS = (ISNULL(td_bqty,0)+ISNULL(td_sqty,0))*td_rate*sm_multiplier, td_rate
      FROM Trades (NOLOCK), Series_master(NOLOCK), @tbl_UserList X
      WHERE  td_clientcd = X.Client_Code
      AND td_dt < @dtFromDate
      AND td_expirydt >= @dtFromDate
      AND td_exchange = sm_exchange and td_segment = sm_segment 
      AND td_seriesid = sm_seriesid 
      AND ltrim(rtrim(td_groupid)) <> 'B'
	  AND ((TD_Exchange+TD_Segment+cast(td_seriesid as varchar) = @StrLookup AND ISNULL(@StrLookup,'') <> '')
	  OR ISNULL(@StrLookup,'') = '')
      ORDER BY td_seriesid, td_dt

      CREATE TABLE #TrxSummaryDLV1 (clientcd VARCHAR(8) NOT NULL, scripcd VARCHAR(6) NOT NULL, td_expirydt VARCHAR(8), 
	  Buys MONEY, Sells MONEY)
  
      INSERT INTO #TrxSummaryDLV1
      SELECT td_clientcd, td_scripcd, td_expirydt, Buys, Sells
      FROM (SELECT td_clientcd, td_scripcd, td_expirydt, sum(CASE WHEN td_bsflag='B' THEN Qty_ns ELSE 0 END) AS 'Buys', 
      SUM(CASE WHEN td_bsflag='S' THEN Qty_ns ELSE 0 END) 'Sells', 
      SUM(CASE WHEN td_bsflag='B' THEN Qty_ns ELSE 0 END) - sum(CASE WHEN td_bsflag='S' THEN Qty_ns ELSE 0 END) AS 'Delivery', 
      COUNT(*) Totalrec
      FROM #tbl_DelvTrxn
      GROUP BY td_clientcd, td_scripcd, td_expirydt
      HAVING sum(CASE WHEN td_bsflag='B' THEN Qty_ns ELSE 0 END) - sum(CASE WHEN td_bsflag='S' THEN Qty_ns ELSE 0 END) <> 0) a

      CREATE TABLE #TrxDLV1 (SrNo NUMERIC, Qty NUMERIC, FinalQty NUMERIC)
      CREATE INDEX indx_SrNo ON #TrxDLV1 (SrNo) 

      INSERT INTO #TrxDLV1
      SELECT SerialNo, Qty, CASE WHEN NetQty >= Running THEN Qty ELSE NetQty - isNull(PrevRunning, 0) END FinalQty
      FROM (
      SELECT SerialNo, td_clientcd, td_scripcd, td_marketrate,  NetQty, Qty, Running, LAG(Running) OVER (
      PARTITION BY td_clientcd, td_scripcd ORDER BY td_dt DESC,  SerialNo DESC) PrevRunning
      FROM (SELECT SerialNo, td_dt, td_clientcd, td_scripcd, Qty_ns Qty, td_marketrate = td_Rate,  abs(Buys - Sells) NetQty, Sum(Qty_ns) OVER (
			PARTITION BY td_clientcd, td_scripcd ORDER BY td_dt DESC,  SerialNo DESC) Running
      FROM #tbl_DelvTrxn,  #TrxSummaryDLV1 
      WHERE td_clientcd = clientcd AND td_scripcd = scripcd AND td_bsflag = CASE WHEN Buys > Sells THEN 'B' ELSE 'S' END) a) b
      WHERE CASE WHEN NetQty >= Running THEN Qty ELSE NetQty - isNull(PrevRunning, 0) END > 0


      INSERT INTO #tbl_DelvTrxn(td_SRNO, td_companycode, TD_Exchange, TD_Segment, td_dt, td_clientcd, td_scripcd, td_expirydt,  
	  SM_DESC, sm_underlying, 
	  sm_multiplier, td_bsflag, Qty_NS, VALUES_NS, td_Rate)
      SELECT td_SRNO, td_companycode, TD_Exchange, TD_Segment, td_dt, td_clientcd, 
	  td_scripcd, td_expirydt, SM_DESC, sm_underlying, sm_multiplier, td_bsflag,
      Qty - FinalQty, VALUES_NS = (Qty - FinalQty)*td_Rate, td_Rate
      FROM #tbl_DelvTrxn , #TrxDLV1
      WHERE SerialNo = srno AND (Qty - FinalQty) > 0

      UPDATE #tbl_DelvTrxn
      SET Qty_NS = FinalQty, VALUES_NS = FinalQty*td_Rate, SQR_TAG = 'Y' 
      FROM #TrxDLV1
      WHERE SerialNo = srno  AND td_bsflag = 'B'

      UPDATE #tbl_DelvTrxn
      SET Qty_NS = FinalQty, VALUES_NS = FinalQty*td_Rate, SQR_TAG = 'Y' 
      FROM #TrxDLV1
      WHERE SerialNo = srno and td_bsflag = 'S'

      DELETE #tbl_DelvTrxn
      WHERE Qty_NS = 0

	  INSERT INTO #tbl_ClientPLFIFO(CompanyCode, Exchange, Segment, ClientCode, Symbol, 
	  seriesid, ExpiryDate, Scrip, Multiplier, TrxnDate,  td_SRNO,  td_bsflag, Qty_NS, VALUES_NS, td_Rate)
      SELECT td_companycode, TD_Exchange, TD_Segment, td_clientcd, sm_underlying ,td_scripcd, td_expirydt, SM_DESC, sm_multiplier, td_dt,
	  td_SRNO,  td_bsflag, Qty_NS, VALUES_NS, td_Rate
	  FROM #tbl_DelvTrxn WHERE ISNULL(SQR_TAG,'N') = 'Y'
      ORDER BY td_scripcd, td_expirydt
  
      CREATE TABLE #tbl_DelvTrxnN (CompanyCode VARCHAR(10), Exchange VARCHAR(10), Segment VARCHAR(10),
	  td_SRNO INT, td_dt VARCHAR(8), td_clientcd VARCHAR(20), td_seriesid VARCHAR(20), 
	  td_expirydt VARCHAR(8), td_bsflag VARCHAR(1), Qty_NS MONEY, VALUES_NS MONEY, td_Rate MONEY, FIFONo INT, 
	  XTAG11 INT, LONG_TAG VARCHAR(1), SQR_TAG VARCHAR(1))

	  CREATE TABLE #tbl_DelvTrxnN1 (CompanyCode VARCHAR(10), Exchange VARCHAR(10), Segment VARCHAR(10),
	  td_SRNO INT, td_dt VARCHAR(8), td_clientcd VARCHAR(20), td_seriesid VARCHAR(20), 
	  td_expirydt VARCHAR(8), td_bsflag VARCHAR(1), Qty_NS MONEY, VALUES_NS MONEY, td_Rate MONEY, FIFONo INT, 
	  XTAG11 INT, LONG_TAG VARCHAR(1), SQR_TAG VARCHAR(1))

	  CREATE TABLE #tbl_DelvTrxnN2 (CompanyCode VARCHAR(10), Exchange VARCHAR(10), Segment VARCHAR(10),
	  td_SRNO INT, td_dt VARCHAR(8), td_clientcd VARCHAR(20), td_seriesid VARCHAR(20), 
	  td_expirydt VARCHAR(8), td_bsflag VARCHAR(1), Qty_NS MONEY, VALUES_NS MONEY, td_Rate MONEY, FIFONo INT, 
	  XTAG11 INT, LONG_TAG VARCHAR(1), SQR_TAG VARCHAR(1))

	 
	  CREATE INDEX indx_DelvTrxnN1 ON #tbl_DelvTrxnN1 (td_clientcd, td_seriesid, td_SRNO, FIFONO)
      CREATE INDEX indx_DelvTrxnN ON #tbl_DelvTrxnN (td_clientcd, td_seriesid, td_SRNO, FIFONO)
	  CREATE INDEX indx_DelvTrxnN2 ON #tbl_DelvTrxnN2 (td_clientcd, td_seriesid, td_SRNO, FIFONO)
      CREATE INDEX indx_DelvTrxn1N ON #tbl_DelvTrxnN (td_clientcd, FIFONO)

      INSERT INTO #tbl_DelvTrxnN (CompanyCode, Exchange,  Segment, td_SRNO, td_dt,  
	  td_clientcd, td_seriesid, td_bsflag, Qty_NS, VALUES_NS, td_Rate, FIFONO)

      SELECT X.*, FIFONO = ROW_NUMBER() OVER (
		PARTITION BY td_clientcd ORDER BY td_seriesid, TD_DT, td_SRNO)
      FROM (
	  
	  SELECT CompanyCode, Exchange, Segment, 
	  td_SRNO, td_dt = TrxnDate, td_clientcd =  ClientCode, td_seriesid = seriesid,  td_bsflag, 
      Qty_NS  , VALUES_NS, td_Rate
	  FROM #tbl_ClientPLFIFO
	  UNION ALL
	  SELECT td_companycode as CompanyCode, TD_Exchange as Exchange, TD_Segment as Segment, 
	  td_SRNO, td_dt, td_clientcd, td_seriesid, td_bsflag, 
      Qty_NS = ABS(td_bqty - td_Sqty),
	  VALUES_NS = td_Rate * ABS(td_bqty - td_Sqty), td_Rate
	  FROM Trades(NOLOCK), Series_master(NOLOCK), @tbl_UserList X
      WHERE  td_clientcd = x.Client_Code
      AND td_dt >= @dtFromDate
      AND td_dt <= @dtToDt
      AND td_exchange = sm_exchange and td_segment = sm_segment 
      AND td_seriesid = sm_seriesid 
	  AND ((TD_Exchange+TD_Segment+cast(td_seriesid as varchar) = @StrLookup AND ISNULL(@StrLookup,'') <> '')
	  OR ISNULL(@StrLookup,'') = '')
      AND ltrim(rtrim(td_groupid)) <> 'B' ) X --WHERE X.td_seriesid='219504'


	  DECLARE @SQR_QTY MONEY = 0, @SQR_QTY1 MONEY = 0, @td_clientcdC1 VARCHAR(10) = '', @td_scripcdC1 VARCHAR(10) = '', 
	  @td_BuyQtyC1 MONEY = 0, @td_SaleQtyC1 MONEY = 0, @COUNTER INT = 0, @td_SRNOB INT, 
	  @td_dtB VARCHAR(8),  @td_clientcdB VARCHAR(50), @td_scripcdB VARCHAR(50), 
	  @td_bsflagB VARCHAR(1), @QTY_NSB MONEY, @td_RateB MONEY, @VALUES_NSB MONEY, 
	  @td_SRNOS INT, @td_dtS VARCHAR(8), @td_clientcdS VARCHAR(50), @td_scripcdS 
	  VARCHAR(50), @td_bsflagS VARCHAR(1), @QTY_NSS MONEY, @td_RateS MONEY, @buyQty MONEY = 0, @SaleQty MONEY = 0, 
	  @BQTY MONEY = 0, @SQTY MONEY = 0, @VALUES_NSS MONEY, @FIFONOB INT, @FIFONOS INT, @SQ MONEY = 0, @TAG VARCHAR(1) = 'C', 
	  @strFlag VARCHAR(1)='N', @strsaleflag VARCHAR(1)='', @TD_STTB MONEY, 
	  @TD_STTS MONEY, @BDATE varchar(8), @SDATE VARCHAR(8), @CompanyCodeb VARCHAR(10), @Exchangeb VARCHAR(10), 
	  @Segmentb VARCHAR(10), @CompanyCodeS VARCHAR(10), @ExchangeS VARCHAR(10), 
	  @SegmentS VARCHAR(10)

	
      DECLARE CursorC1Main CURSOR
      FOR
      SELECT td_clientcd, td_seriesid, SUM(CASE WHEN td_bsflag = 'B' THEN Qty_NS ELSE 0 END) BuyQty, 
      SUM(CASE WHEN td_bsflag = 'S' THEN Qty_NS ELSE 0 END) SaleQty
      FROM #tbl_DelvTrxnN x
      GROUP BY td_clientcd, td_seriesid
      HAVING SUM(CASE WHEN td_bsflag = 'B' THEN Qty_NS ELSE 0 END) <> 0 
      AND SUM(CASE WHEN td_bsflag = 'S' THEN Qty_NS ELSE 0 END) <> 0

      OPEN CursorC1Main
      FETCH NEXT
      FROM CursorC1Main
      INTO @td_clientcdC1, @td_scripcdC1, @td_BuyQtyC1, @td_SaleQtyC1
      WHILE @@FETCH_STATUS = 0
      BEGIN
	    IF SIGN(@td_BuyQtyC1 - @td_SaleQtyC1) <> 1
	    BEGIN
		  SET @SQR_QTY = @td_BuyQtyC1
		  SET @SQR_QTY1 = @td_BuyQtyC1
		  set @strsaleflag = 'B'
	    END
	    ELSE
	    BEGIN
		  SET @SQR_QTY = @td_SaleQtyC1
		  SET @SQR_QTY1 = @td_SaleQtyC1
		  set @strsaleflag = 'S'
	    END
	
	
	    DECLARE CursorBMain CURSOR
	    FOR SELECT CompanyCode, Exchange,  Segment, td_SRNO, td_dt, td_clientcd, td_seriesid, td_bsflag, 
		Qty_NS, td_Rate, VALUES_NS, FIFONO
	    FROM #tbl_DelvTrxnN
	    WHERE td_clientcd = @td_clientcdC1 AND td_seriesid = @td_scripcdC1 AND td_bsflag = 'B' AND Qty_NS <> 0
	    ORDER BY td_clientcd, td_seriesid, FIFONO, td_SRNO
	
	    DECLARE CursorSMain CURSOR
	    FOR
	    SELECT CompanyCode, Exchange,  Segment, td_SRNO, td_dt, td_clientcd, td_seriesid, td_bsflag, Qty_NS, td_Rate, VALUES_NS, FIFONO
	    FROM #tbl_DelvTrxnN
	    WHERE td_clientcd = @td_clientcdC1 AND td_seriesid = @td_scripcdC1 AND td_bsflag = 'S' AND Qty_NS <> 0
	    ORDER BY td_clientcd, td_seriesid, FIFONO, td_SRNO
	    OPEN CursorBMain
	    OPEN CursorSMain
	    WHILE @@FETCH_STATUS = 0
	    BEGIN
	      SET @COUNTER = @COUNTER + 1
          IF @SQR_QTY <> 0
          BEGIN
            IF @BQTY = 0
            BEGIN
              FETCH NEXT FROM CursorBMain
			  INTO @CompanyCodeb, @Exchangeb, @Segmentb, @td_SRNOB, @td_dtB,  @td_clientcdB, @td_scripcdB, @td_bsflagB, @Qty_NSB, @td_RateB, 
					@VALUES_NSB, @FIFONOB
              SET @BQTY = @QTY_NSB
              SET @BDATE = @td_dtB
            END
          END
          IF @SQR_QTY1 <> 0
          BEGIN
            IF @SQTY = 0
            BEGIN
              FETCH NEXT FROM CursorSMain 
			  INTO @CompanyCodes, @Exchanges, @SegmentS, @td_SRNOS, @td_dtS, @td_clientcdS, @td_scripcdS, @td_bsflagS, @Qty_NSS, @td_RateS, 
			       @VALUES_NSS, @FIFONOS
              SET @SQTY = @QTY_NSS
              SET @SDATE  =  @td_dtS
            END
          END
		  IF @BQTY >= @SQTY 
		  BEGIN
		    IF @BQTY > 0
		    BEGIN
		      SET @SQ = @SQTY
		    END	
		  END
		  ELSE
		  BEGIN
		    IF @SQTY > 0
		    BEGIN
		      SET @SQ = @BQTY
		    END	
		  END
		  INSERT INTO #tbl_DelvTrxnN2 (
			CompanyCode, Exchange,  Segment, td_SRNO, td_dt, td_clientcd, td_seriesid, td_bsflag, Qty_NS, td_Rate, VALUES_NS, FIFONO, XTAG11, 
			LONG_TAG, SQR_TAG
			)
		  VALUES (
			@CompanyCodeb, @Exchangeb, @Segmentb, @td_SRNOB, @td_dtB, @td_clientcdB, @td_scripcdB, @td_bsflagB, @SQ, @td_RateB, @SQ * @td_RateB, 
			@FIFONOB, @COUNTER, (CASE WHEN SIGN(ABS(DATEDIFF(DAY, CAST(@td_dtB AS DATE), CAST(@td_dtS AS DATE))) - 365) = 1 THEN 'L' ELSE '' END
				), 'Y')

		  SET @BQTY = @BQTY - @SQ
     
         		
		  INSERT INTO #tbl_DelvTrxnN2 (
			CompanyCode, Exchange,  Segment, td_SRNO, td_dt, td_clientcd, td_seriesid, td_bsflag, Qty_NS, td_Rate, VALUES_NS, FIFONO, XTAG11, 
			LONG_TAG, SQR_TAG
			)
		  VALUES (
			@CompanyCodes, @Exchanges, @Segments, @td_SRNOS, @td_dtS, @td_clientcdS, @td_scripcdS, @td_bsflagS, @SQ, @td_RateS, @SQ * @td_RateS, 
			@FIFONOS, @COUNTER, (CASE WHEN SIGN(ABS(DATEDIFF(DAY, CAST(@td_dtB AS DATE), CAST(@td_dtS AS DATE))) - 365) = 1 THEN 'L' ELSE '' END
				), 'Y'
			)
		  SET @SQTY = @SQTY - @SQ
    	  IF @BQTY = 0
		  BEGIN
			UPDATE #tbl_DelvTrxnN
			SET SQR_TAG = @TAG
			WHERE td_clientcd = @td_clientcdB AND FIFONO = @FIFONOB
		  END
		
		  IF @SQTY = 0
		  BEGIN
			UPDATE #tbl_DelvTrxnn
			SET SQR_TAG = @TAG
			WHERE td_clientcd = @td_clientcdS AND FIFONO = @FIFONOS
		  END

		  SET @SQR_QTY1 = @SQR_QTY1 - @SQ 
		  SET @SQR_QTY = @SQR_QTY - @SQ
		  SET @strFlag = 'N'

		  IF (@SQR_QTY1 = 0 AND @SQR_QTY = 0)
		  BEGIN
			BREAK;
		  END
 	    END
	    CLOSE CursorBMain;
	    CLOSE CursorSMain;
	    DEALLOCATE CursorBMain;
	    DEALLOCATE CursorSMain;
	    IF @BQTY <> 0
	    BEGIN
		  INSERT INTO #tbl_DelvTrxnN2 (
			CompanyCode, Exchange,  Segment, td_SRNO, td_dt, td_clientcd, td_seriesid, td_bsflag, Qty_NS, td_Rate, VALUES_NS, FIFONO, XTAG11, 
			LONG_TAG, SQR_TAG
			)
		  VALUES (
			@CompanyCodeb, @Exchangeb, @Segmentb, @td_SRNOB, @td_dtB,  @td_clientcdB, @td_scripcdB, @td_bsflagB, @BQTY, @td_RateB, @BQTY * 
			@td_RateB, @FIFONOB, @COUNTER, '', ''
			)
		  UPDATE #tbl_DelvTrxnn
		  SET SQR_TAG = @TAG
		  WHERE td_clientcd = @td_clientcdB AND FIFONO = @FIFONOB
	    END
	
	    IF @SQTY <> 0
	    BEGIN
		  INSERT INTO #tbl_DelvTrxnN2 (
			CompanyCode, Exchange,  Segment, td_SRNO, td_dt, td_clientcd, td_seriesid, td_bsflag, Qty_NS, td_Rate, VALUES_NS, FIFONO, XTAG11, 
			LONG_TAG, SQR_TAG
			)
		  VALUES (
			@CompanyCodeb, @Exchangeb, @Segmentb, @td_SRNOS, @td_dtS, @td_clientcdS, @td_scripcdS, @td_bsflagS, @SQTY, @td_RateS, @SQTY * 
			@td_RateB, @FIFONOS, @COUNTER, '', ''
			)
		  UPDATE #tbl_DelvTrxnN
		  SET SQR_TAG = @TAG
		  WHERE td_clientcd = @td_clientcdS AND FIFONO = @FIFONOS
	    END
	    SET @SQ = 0
	    SET @BQTY = 0
	    SET @SQTY = 0
	    SET @SQR_QTY = 0
	    SET @SQR_QTY1 = 0
	    FETCH NEXT
	    FROM CursorC1Main
	    INTO @td_clientcdC1, @td_scripcdC1, @td_BuyQtyC1, @td_SaleQtyC1
      END
      CLOSE CursorC1Main
      DEALLOCATE CursorC1Main
	
      DELETE FROM #tbl_DelvTrxnN WHERE SQR_TAG = 'C'
  
      INSERT INTO #tbl_DelvTrxnN 
      SELECT * FROM #tbl_DelvTrxnN2 WHERE isnull(Qty_NS,0) <> 0 

      DECLARE @tbl_CLClientAS TABLE(CompanyCode VARCHAR(10), Exchange VARCHAR(10), Segment VARCHAR(10),  ClientCode VARCHAR(50), ClientName VARCHAR(100), 
      Symbol VARCHAR(50), seriesid INT, ExpiryDate VARCHAR(8), Scrip VARCHAR(100), Multiplier INT, TrxnDate VARCHAR(8), EX_QTY MONEY, EX_VALUE MONEY, AS_QTY MONEY, AS_VALUE MONEY)
  
      INSERT INTO @tbl_CLClientAS(CompanyCode, Exchange, Segment, ClientCode, Scrip, Symbol, seriesid, ExpiryDate, 
	  Multiplier, TrxnDate, EX_QTY, EX_VALUE,
      AS_QTY, AS_VALUE)

      SELECT ex_companycode, ex_Exchange, ex_segment, ex_clientcd, SM_DESC, sm_underlying, ex_seriesid, 
      sm_expirydt, sm_multiplier,  ex_dt,  ex_eqty = sum(ex_eqty) ,
      EX_VALUE = sum((ex_eqty)*ex_diffbrokrate*sm_multiplier*-1), ex_aqty = sum(ex_aqty), 
      AS_VALUE = sum((ex_aqty)*ex_diffbrokrate*sm_multiplier*-1) 
      FROM Exercise(NOLOCK), Series_master(NOLOCK), @tbl_UserList X  
      WHERE ex_dt between @dtFromDate and @dtToDt 
      AND ex_clientcd = X.Client_Code 
      and sm_expirydt >= @dtFromDate
      and ex_exchange = sm_exchange 
      and ex_segment = sm_segment And ex_seriesid = sm_seriesid 
	  GROUP BY ex_companycode, ex_Exchange, ex_segment, ex_clientcd, SM_DESC, sm_underlying, ex_seriesid, 
      sm_expirydt, sm_multiplier,  ex_dt

      
      INSERT INTO #tbl_ClientPL(CompanyCode, Exchange, Segment, ClientCode, seriesid, Scrip, 
	  ExpiryDate, Symbol, Multiplier, TrxnDate, BF_QTY, BF_CloseRate, BF_VALUE,
      BOT_QTY, BOT_VALUE, SOLD_QTY, SOLD_VALUE, EX_QTY, EX_VALUE,
      AS_QTY, AS_VALUE, AccountType)
      SELECT CompanyCode, Exchange,  Segment, td_clientcd, td_seriesid, ScripName, ExpriryDate, sm_underlying,
	  sm_multiplier, td_dt,
      BF_Qty, BF_RATE = ABS(CASE WHEN BF_Qty <> 0 THEN ROUND(BF_Value/BF_Qty,2) ELSE 0 END),
      BF_Value,
      BuyQty, BuyValue, SaleQty, SaleValue, 
      EX_QTY = ISNULL(ex_eqty,0),
      EX_VALUE = ISNULL(EX_VALUE,0),
      AS_QTY = ISNULL(ex_aqty,0),
      AS_VALUE = ISNULL(AS_VALUE,0), SQR_TAG
      FROM(
      SELECT CompanyCode, Exchange,  Segment, td_clientcd, td_seriesid, ScripName = SR.SM_DESC,  
	  ExpriryDate =   SR.sm_expirydt, sm_underlying, sm_multiplier, 
	  td_dt = CASE WHEN ISNULL(@strReportType,'')  = 'Series Wise Detail' THEN  td_dt ELSE @dtFromDate END,
      BF_Qty = SUM(CASE WHEN td_dt < @dtFromDate THEN (CASE WHEN td_bsflag = 'B' THEN  
      Qty_NS ELSE Qty_NS*-1 END) else 0 end), 
      BF_Value = ROUND(SUM(CASE WHEN td_dt < @dtFromDate AND Qty_NS <> 0 THEN (CASE WHEN td_bsflag = 'B' THEN  
      (Qty_NS*TD_RATE)*-1 ELSE (Qty_NS*TD_RATE) END) else 0 end),2), 
      BuyQty = SUM(CASE WHEN td_dt >= @dtFromDate THEN (CASE WHEN td_bsflag = 'B' THEN  
      Qty_NS ELSE 0 END) else 0 end),
      BuyValue = SUM(CASE WHEN td_dt >= @dtFromDate THEN (CASE WHEN td_bsflag = 'B' THEN  
      Qty_NS*td_rate ELSE 0 END) else 0 end),
      SaleQty = SUM(CASE WHEN td_dt >= @dtFromDate THEN (CASE WHEN td_bsflag = 'S' THEN  
      Qty_NS ELSE 0 END) else 0 end),
      SaleValue = SUM(CASE WHEN td_dt >= @dtFromDate THEN (CASE WHEN td_bsflag = 'S' THEN  
      Qty_NS*td_rate ELSE 0 END) else 0 end), SQR_TAG = ISNULL(SQR_TAG,'')
      FROM #tbl_DelvTrxnN X, Series_master(NOLOCK) SR
      where x.td_seriesid = sr.sm_seriesid
	  AND x.exchange = SR.sm_exchange
	  AND X.Segment  = SR.sm_Segment
      Group By CompanyCode, Exchange,  Segment, td_clientcd, td_seriesid, SR.SM_DESC, SR.sm_expirydt, ISNULL(SQR_TAG,''), 
	  sm_multiplier, sm_underlying, CASE WHEN ISNULL(@strReportType,'')  = 'Series Wise Detail' THEN  td_dt ELSE @dtFromDate END) X123 LEFT OUTER JOIN ( select ClientCode, seriesid, 
	  TrxnDate = CASE WHEN ISNULL(@strReportType,'')  = 'Series Wise Detail' THEN  TrxnDate ELSE @dtFromDate END, 
	  ex_eqty = sum(EX_QTY) ,
      EX_VALUE = sum(EX_VALUE), ex_aqty = sum(AS_QTY), 
      AS_VALUE = sum(AS_VALUE) 
      FROM @tbl_CLClientAS
      GROUP BY ClientCode, seriesid, CASE WHEN ISNULL(@strReportType,'')  = 'Series Wise Detail' 
	  THEN  TrxnDate ELSE @dtFromDate END) EXAS 
	  ON( td_clientcd = EXAS.ClientCode AND td_seriesid = EXAS.seriesid and ISNULL(SQR_TAG,'') = ''
      AND td_dt = TrxnDate)
      ORDER BY ScripName
    END
	
	

	IF @strRateType NOT IN('Underlying Close Price','Do not Valuate')
	BEGIN
	  ---@@VAIBHAV/03-JUL-2024 START
	  if @strRateType = 'Average price' 
	  BEGIN
	    
		UPDATE A SET A.NET_QTY = (ISNULL(A.BF_QTY,0)+ISNULL(A.BOT_QTY,0))-ISNULL(A.SOLD_QTY,0)-ISNULL(A.AS_QTY,0)- ISNULL(A.EX_QTY,0),
        A.NET_VALUE = ROUND(((ISNULL(A.BF_QTY,0)+ISNULL(A.BOT_QTY,0))-ISNULL(A.SOLD_QTY,0)-ISNULL(A.AS_QTY,0)- ISNULL(A.EX_QTY,0))*ms_lastprice*isnull(Multiplier,1),2),
        cmp = ms_lastprice
        FROM #tbl_ClientPL A , Market_summary(NOLOCK) X
        WHERE ms_seriesid = seriesid 
        and ms_exchange = exchange and ms_segment = Segment 
        and ms_dt  = (select  max(ms_dt) from Market_summary(NOLOCK)  
	    WHERE ms_exchange = X.ms_exchange and ms_segment = X.ms_segment and ms_dt<=@dtToDt)
		
		UPDATE A SET A.MTM = ((ISNULL(A.SOLD_VALUE,0)-isnull(A.BOT_VALUE,0))+ISNULL(A.BF_VALUE,0)-ISNULL(A.AS_VALUE,0)-ISNULL(A.EX_VALUE,0))+isnull(NET_VALUE,0)
        FROM #tbl_ClientPL A	  
	  		
	  	UPDATE A SET A.MTM =((ISNULL(A.SOLD_VALUE,0)-isnull(A.BOT_VALUE,0))+ISNULL(A.BF_VALUE,0)-ISNULL(A.AS_VALUE,0)-ISNULL(A.EX_VALUE,0)),
	    A.NET_VALUE = 0 
	    FROM #tbl_ClientPL A
	    WHERE  EXISTS(SELECT 1 FROM Series_master(NOLOCK)
	    WHERE sm_Segment =  A.Segment AND sm_exchange = A.Exchange AND sm_seriesid = A.seriesid   
		AND sm_prodtype IN('EO','CO','IO'))
	    AND A.NET_QTY <> 0	
	    AND ExpiryDate <= @dtToDt
	  
	    UPDATE A SET A.MTM = case WHEN NET_QTY > 0 THEN 
		((ABS(ISNULL(A.BOT_QTY,0)*ROUND((ISNULL(A.BOT_VALUE,0)/ISNULL(A.BOT_QTY,0)),2))-isnull(A.BOT_VALUE,0))+ISNULL(A.BF_VALUE,0)-ISNULL(A.AS_VALUE,0)-ISNULL(A.EX_VALUE,0))
		ELSE ((ISNULL(A.SOLD_VALUE,0)-ABS(ISNULL(A.SOLD_QTY,0)*ROUND((ISNULL(A.SOLD_VALUE,0)/ISNULL(A.SOLD_QTY,0)),2)))+ISNULL(A.BF_VALUE,0)-ISNULL(A.AS_VALUE,0)-ISNULL(A.EX_VALUE,0)) END,
	    A.NET_VALUE = 0 
	    FROM #tbl_ClientPL A
	    WHERE EXISTS(SELECT 1 FROM Series_master(NOLOCK)
	    WHERE sm_Segment =  A.Segment AND sm_exchange = A.Exchange AND sm_seriesid = A.seriesid   
		AND sm_prodtype IN('EO','CO','IO'))
		AND A.NET_QTY <> 0	
	    AND ExpiryDate > @dtToDt
			
      END
	  ELSE
	  BEGIN
	     
	    UPDATE A SET A.NET_QTY = (ISNULL(A.BF_QTY,0)+ISNULL(A.BOT_QTY,0))-ISNULL(A.SOLD_QTY,0)-ISNULL(A.AS_QTY,0)- ISNULL(A.EX_QTY,0),
        A.NET_VALUE = ROUND(((ISNULL(A.BF_QTY,0)+ISNULL(A.BOT_QTY,0))-ISNULL(A.SOLD_QTY,0)-ISNULL(A.AS_QTY,0)- ISNULL(A.EX_QTY,0))*ms_lastprice*isnull(Multiplier,1),2),
        cmp = ms_lastprice
        FROM #tbl_ClientPL A , Market_summary(NOLOCK) X
        WHERE ms_seriesid = seriesid 
        and ms_exchange = exchange and ms_segment = Segment 
        and ms_dt  = (select  max(ms_dt) from Market_summary(NOLOCK)  
	    WHERE ms_exchange = X.ms_exchange and ms_segment = X.ms_segment and ms_dt<=@dtToDt )
		
		UPDATE A SET A.MTM = ((ISNULL(A.SOLD_VALUE,0)-isnull(A.BOT_VALUE,0))+ISNULL(A.BF_VALUE,0)-ISNULL(A.AS_VALUE,0)-ISNULL(A.EX_VALUE,0))+isnull(NET_VALUE,0)
        FROM #tbl_ClientPL A	  
	  
	    UPDATE A SET A.MTM = ((ISNULL(A.SOLD_VALUE,0)-isnull(A.BOT_VALUE,0))+ISNULL(A.BF_VALUE,0)-ISNULL(A.AS_VALUE,0)-ISNULL(A.EX_VALUE,0)),
	    A.NET_VALUE = 0 
	    FROM #tbl_ClientPL A
	    WHERE  EXISTS(SELECT 1 FROM Series_master(NOLOCK)
	    WHERE sm_Segment =  A.Segment AND sm_exchange = A.Exchange AND sm_seriesid = A.seriesid   
		AND sm_prodtype IN('EO','CO','IO'))
	    AND A.NET_QTY <> 0	
	    AND ExpiryDate <= @dtToDt
		
		UPDATE A SET A.NET_QTY = (ISNULL(A.BF_QTY,0)+ISNULL(A.BOT_QTY,0))-ISNULL(A.SOLD_QTY,0)-ISNULL(A.AS_QTY,0)- ISNULL(A.EX_QTY,0)
        FROM #tbl_ClientPL A
	    WHERE  EXISTS(SELECT 1 FROM Series_master(NOLOCK)
	    WHERE sm_Segment =  A.Segment AND sm_exchange = A.Exchange AND sm_seriesid = A.seriesid   
		AND sm_prodtype IN('EO','CO','IO'))
		and (ISNULL(A.BF_QTY,0)+ISNULL(A.BOT_QTY,0))-ISNULL(A.SOLD_QTY,0)-ISNULL(A.AS_QTY,0)- ISNULL(A.EX_QTY,0) <> 0
		AND ExpiryDate >= @dtToDt
		and ISNULL(A.NET_QTY,0) = 0
		
	  END
      ---@@VAIBHAV/03-JUL-2024 END	  
	END  
	IF @strRateType = 'Do not Valuate'
	BEGIN
	  UPDATE A SET A.NET_QTY = (ISNULL(A.BF_QTY,0)+ISNULL(A.BOT_QTY,0))-ISNULL(A.SOLD_QTY,0)-ISNULL(A.AS_QTY,0)- ISNULL(A.EX_QTY,0),
      A.NET_VALUE = ROUND(((ISNULL(A.BF_QTY,0)+ISNULL(A.BOT_QTY,0))-ISNULL(A.SOLD_QTY,0)-ISNULL(A.AS_QTY,0)- ISNULL(A.EX_QTY,0))*ms_lastprice*Multiplier,2),
      cmp = ms_lastprice
      FROM #tbl_ClientPL A, Market_summary(NOLOCK) X
      WHERE ms_seriesid = seriesid 
      and ms_exchange = exchange and ms_segment = Segment 
      and ms_dt  = (select  max(ms_dt) from Market_summary(NOLOCK)  
	  WHERE ms_exchange = X.ms_exchange and ms_segment = X.ms_segment and ms_dt<=@dtToDt )
	  
	  UPDATE A SET A.NET_VALUE = 0 
	  FROM #tbl_ClientPL A
	  WHERE EXISTS(SELECT 1
	  FROM Series_master(NOLOCK) WHERE sm_Segment =  A.Segment AND sm_exchange = A.Exchange 
	  AND sm_seriesid = A.seriesid  AND sm_prodtype IN('EO','CO','IO')) 
	  AND A.NET_QTY <> 0
	  
	  UPDATE A SET A.MTM = ((ISNULL(A.SOLD_VALUE,0)-isnull(A.BOT_VALUE,0))+ISNULL(A.BF_VALUE,0)-ISNULL(A.AS_VALUE,0)-ISNULL(A.EX_VALUE,0))+isnull(NET_VALUE,0)
      FROM #tbl_ClientPL A
	  
	END
	IF @strRateType = 'Underlying Close Price'
	BEGIN
	  UPDATE A SET A.NET_QTY = (ISNULL(A.BF_QTY,0)+ISNULL(A.BOT_QTY,0))-ISNULL(A.SOLD_QTY,0)-ISNULL(A.AS_QTY,0)- ISNULL(A.EX_QTY,0),
      A.NET_VALUE = ROUND(((ISNULL(A.BF_QTY,0)+ISNULL(A.BOT_QTY,0))-ISNULL(A.SOLD_QTY,0)-ISNULL(A.AS_QTY,0)- ISNULL(A.EX_QTY,0))*ms_lastprice*Multiplier,2),
      cmp = ms_lastprice
      FROM #tbl_ClientPL A, Market_summary(NOLOCK) X
      WHERE ms_seriesid = seriesid 
      and ms_exchange = exchange and ms_segment = Segment 
      and ms_dt  = (select  max(ms_dt) from Market_summary(NOLOCK)  
	  WHERE ms_exchange = X.ms_exchange and ms_segment = X.ms_segment and ms_dt<=@dtToDt )
	  AND NOT EXISTS(SELECT 1
	  FROM Series_master(NOLOCK) WHERE sm_Segment =  A.Segment AND sm_exchange = A.Exchange 
	  AND sm_seriesid = A.seriesid  AND sm_prodtype IN('EO','CO','IO'))  

	  SET @BFseriesid = 0 
	  SET @spotCloseRate =0
	  SET @strSegment = ''
	  SET @strExchange = ''

	  DECLARE db_CursorRateCF CURSOR FOR         
      SELECT distinct seriesid, Exchange, Segment
      FROM #tbl_ClientPL A 
	  where NET_QTY <> 0 and EXISTS(SELECT 1 FROM Series_master(NOLOCK)
	  WHERE sm_Segment =  A.Segment AND sm_exchange = A.Exchange  AND sm_seriesid = A.seriesid AND sm_productcd in('OPTSTK'))
      OPEN db_CursorRateCF       
      FETCH NEXT FROM db_CursorRateCF INTO @BFseriesid, @strExchange, @strSegment
      WHILE @@FETCH_STATUS = 0     
      BEGIN
	    SELECT TOP 1 @spotCloseRate = mk_closerate FROM Market_Rates(NOLOCK) X WHERE mk_scripcd IN(
        SELECT SS_cD FROM Securities WHERE ss_bsymbol IN(
        SELECT sm_symbol FROM Series_master(NOLOCK) WHERE sm_Segment = @strSegment and sm_exchange = @strExchange 
		AND sm_seriesid = @BFseriesid))
        AND mk_dt   IN(SELECT MAX(mk_dt) FROM Market_Rates(NOLOCK) WHERE mk_dt <= @dtToDt)
        ORDER BY CASE WHEN mk_exchange='N' THEN 1 ELSE 2 END
	  
	    UPDATE A SET A.cmp = @spotCloseRate, a.NET_VALUE =(a.NET_QTY*@spotCloseRate)*-1
	    FROM #tbl_ClientPL A
	    WHERE A.seriesid = @BFseriesid
		AND A.Exchange = @strExchange
		AND A.Segment = @strSegment
	   FETCH NEXT FROM db_CursorRateCF INTO @BFseriesid, @strExchange, @strSegment
      END        
      CLOSE db_CursorRateCF        
      DEALLOCATE db_CursorRateCF	

	  UPDATE A SET A.MTM = ((ISNULL(A.SOLD_VALUE,0)-isnull(A.BOT_VALUE,0))+ISNULL(A.BF_VALUE,0)-ISNULL(A.AS_VALUE,0)-ISNULL(A.EX_VALUE,0))+isnull(NET_VALUE,0)
      FROM #tbl_ClientPL A
	  
	  UPDATE A SET A.MTM = ((ISNULL(A.SOLD_VALUE,0)-isnull(A.BOT_VALUE,0))+ISNULL(A.BF_VALUE,0)-ISNULL(A.AS_VALUE,0)-ISNULL(A.EX_VALUE,0)),
	  A.NET_VALUE = 0 
	  FROM #tbl_ClientPL A
	  WHERE  EXISTS(SELECT 1 FROM Series_master(NOLOCK)
	  WHERE sm_Segment =  A.Segment AND sm_exchange = A.Exchange AND sm_seriesid = A.seriesid   
	  AND sm_prodtype IN('EO','CO','IO'))
	  AND A.NET_QTY <> 0	
	  AND ExpiryDate <= @dtToDt
	  
	  /*(UPDATE A SET A.MTM = ((ISNULL(A.SOLD_VALUE,0)-isnull(A.BOT_VALUE,0))+ISNULL(A.BF_VALUE,0)-ISNULL(A.AS_VALUE,0)-ISNULL(A.EX_VALUE,0)),
	  A.NET_VALUE = 0 
	  FROM #tbl_ClientPL A
	  WHERE EXISTS(SELECT 1
	  FROM Series_master(NOLOCK) WHERE sm_seriesid = A.seriesid  AND sm_prodtype IN('EO','CO','IO')) 
	  AND A.NET_QTY > 0	
	  */
	END    
	
    UPDATE A SET A.ClientName = CM.cm_name
    FROM #tbl_ClientPL A, Client_Master CM
    WHERE A.ClientCode = CM.cm_cd

  
    declare @tbl_billCharges TABLE(CompanyCode VARCHAR(10), Exchange VARCHAR(10), Segment VARCHAR(10), 
    ClientCode VARCHAR(10) NOT NULL,
    ChargesDescp [char] (40) NOT NULL,
    [bc_amount] [money] NOT NULL)
  
    INSERT INTO @tbl_billCharges (CompanyCode, Exchange, Segment, ClientCode, ChargesDescp, [bc_amount])
    SELECT fc_companycode, fc_Exchange, fc_segment, fc_clientcd, fc_desc, round(sum(fc_amount),2)  
    FROM Fspecialcharges(NOLOCK), (SELECT DISTINCT Client_Code = ClientCode  FROM #tbl_ClientPL) X
    where fc_clientcd = x.Client_COde and fc_dt >= @dtFromDate and fc_dt<= @dtToDt 
    AND ((fc_companycode+fc_exchange+fc_segment IN(SELECT ExchangeCode FROM @tbl_Exchange) and @ExchSeg <> '') OR @ExchSeg = '')
    GROUP BY fc_clientcd, fc_desc,fc_companycode, fc_Exchange, fc_segment
    HAVING ROUND(SUM(fc_amount),2) <> 0
 
    INSERT INTO @tbl_billCharges (CompanyCode, Exchange, Segment, ClientCode, ChargesDescp, [bc_amount])
    SELECT fc_companycode, fc_Exchange, fc_segment, fc_clientcd,'SERVICE TAX', round(sum(fc_servicetax),2)
    FROM Fspecialcharges(NOLOCK), (SELECT DISTINCT Client_Code =ClientCode FROM #tbl_ClientPL) X
    WHERE fc_clientcd = x.Client_COde
    AND fc_dt >= @dtFromDate and fc_dt<= @dtToDt 
    AND ((fc_companycode+fc_exchange+fc_segment IN(SELECT ExchangeCode FROM @tbl_Exchange) and @ExchSeg <> '') OR @ExchSeg = '')
    GROUP BY fc_clientcd,fc_desc,fc_companycode, fc_Exchange, fc_segment 
    HAVING ROUND(SUM(fc_servicetax),2) <> 0
    DECLARE @XMLDATA1 XML=''
	IF ISNULL(@strReportType,'') in('Series Wise','')
	BEGIN
	  IF @strOutputType = 'X'
	  BEGIN
	    IF ISNULL(@StrSummary,'N') = 'N'
		BEGIN
	      SET @XMLDATA1 = (SELECT * FROM (
	      SELECT TAG = '1', Exchange, Segment, ClientCode, ClientName, 
          seriesid, ExpiryDate, Scrip, Multiplier,  BF_QTY = ISNULL(BF_QTY,0), BF_CloseRate = ISNULL(BF_CloseRate,0), 
          BF_VALUE = ISNULL(BF_VALUE,0), BOT_QTY = ISNULL(BOT_QTY,0), 
	      BOT_RATE = CAST(round((CASE WHEN ISNULL(BOT_QTY,0) <> 0 THEN ISNULL(BOT_VALUE,0)/ISNULL(BOT_QTY,0) ELSE 0 END),4) AS MONEY),
	      BOT_VALUE = ISNULL(BOT_VALUE,0), 
          SOLD_QTY = ISNULL(SOLD_QTY,0), 
	      SOLD_RATE = CAST(round((CASE WHEN ISNULL(SOLD_QTY,0) <> 0 THEN ISNULL(SOLD_VALUE,0)/ISNULL(SOLD_QTY,0) ELSE 0 END),4) AS MONEY),
	      SOLD_VALUE = ISNULL(SOLD_VALUE,0), EX_QTY = ISNULL(EX_QTY,0), EX_VALUE = ISNULL(EX_VALUE,0), 
	      AS_QTY = ISNULL(AS_QTY,0), 
          AS_VALUE = ISNULL(AS_VALUE,0), NET_QTY = ISNULL(NET_QTY,0),
          CMP =  ISNULL(CMP,0), NET_VALUE = ISNULL(NET_VALUE,0), MTM = ISNULL(MTM ,0), 
	      AccountType = ISNULL(AccountType,'N'),
          RelPL = CASE WHEN (ISNULL(AccountType,'N') ='Y' OR ISNULL(NET_QTY,0) = 0 OR ExpiryDate <=  @dtToDt) 
	      THEN ISNULL(MTM ,0) ELSE 0 END,
	      UnRelPL = CASE WHEN ISNULL(AccountType,'') ='' AND ISNULL(NET_QTY,0) <> 0 AND  ExpiryDate > @dtToDt THEN  ISNULL(MTM ,0) ELSE 0 END,
		  Lookup = Exchange+Segment+CAST(seriesid AS VARCHAR), Charges = 0
          FROM #tbl_ClientPL
          UNION ALL
          SELECT TAG = 2, Exchange, Segment, ClientCode, ClientName = '', seriesid = '', ExpiryDate= '', Scrip = ChargesDescp, 
	      Multiplier = 0,BF_QTY = 0, BF_CloseRate = 0, BF_VALUE = 0, BOT_QTY = 0, BOT_RATE = 0, BOT_VALUE = 0,
	      SOLD_QTY = 0, SOLD_RATE = 0, SOLD_VALUE = 0, EX_QTY = 0, EX_VALUE = 0, AS_QTY = 0, AS_VALUE = 0, NET_QTY = 0, CMP = 0, NET_VALUE = 0, 
	      MTM = (bc_amount)*-1, AccountType = '', RelPL = (ISNULL(bc_amount,0))*-1, UnRelPL = 0, Lookup = Exchange+Segment, Charges = ISNULL(bc_amount,0)*-1
	      FROM @tbl_billCharges) X1 --WHERE ((@strRequestFrom = 'M' AND TAG <> 2) OR  @strRequestFrom <> 'M')
		  WHERE ((seriesid <> '' and @StrLookup <> '') or isnull(@StrLookup,'') = '')
		  ORDER BY ClientCode, TAG, Scrip FOR XML PATH('ProfitLoss'))
	      SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
	    END
	    ELSE
	    IF ISNULL(@StrSummary,'N') = 'Y'
		BEGIN
		  SET @XMLDATA1 = (SELECT TotalCharges = SUM(CASE WHEN ISNULL(seriesid,'') = '' THEN round(isnull(MTM,0),2) ELSE 0 END),
		  RelPl = SUM(CASE WHEN ISNULL(seriesid,'') <> '' THEN round(isnull(RelPl,0),2) ELSE 0 END), 
		  UnRelPL = SUM(CASE WHEN seriesid <> '' THEN round(UnRelPL,2) ELSE 0 END)  FROM (
	      SELECT TAG = '1', Exchange, Segment, ClientCode, ClientName, 
          seriesid, ExpiryDate, Scrip, Multiplier,  BF_QTY = ISNULL(BF_QTY,0), BF_CloseRate = ISNULL(BF_CloseRate,0), 
          BF_VALUE = ISNULL(BF_VALUE,0), BOT_QTY = ISNULL(BOT_QTY,0), 
	      BOT_RATE = CAST(round((CASE WHEN ISNULL(BOT_QTY,0) <> 0 THEN ISNULL(BOT_VALUE,0)/ISNULL(BOT_QTY,0) ELSE 0 END),4) AS MONEY),
	      BOT_VALUE = ISNULL(BOT_VALUE,0), 
          SOLD_QTY = ISNULL(SOLD_QTY,0), 
	      SOLD_RATE = CAST(round((CASE WHEN ISNULL(SOLD_QTY,0) <> 0 THEN ISNULL(SOLD_VALUE,0)/ISNULL(SOLD_QTY,0) ELSE 0 END),4) AS MONEY),
	      SOLD_VALUE = ISNULL(SOLD_VALUE,0), EX_QTY = ISNULL(EX_QTY,0), EX_VALUE = ISNULL(EX_VALUE,0), 
	      AS_QTY = ISNULL(AS_QTY,0), 
          AS_VALUE = ISNULL(AS_VALUE,0), NET_QTY = ISNULL(NET_QTY,0),
          CMP =  ISNULL(CMP,0), NET_VALUE = ISNULL(NET_VALUE,0), MTM = ISNULL(MTM ,0), 
	      AccountType = ISNULL(AccountType,'N'),
          RelPL = CASE WHEN (ISNULL(AccountType,'N') ='Y' OR ISNULL(NET_QTY,0) = 0 OR ExpiryDate <=  @dtToDt) 
	      THEN ISNULL(MTM ,0) ELSE 0 END,
	      UnRelPL = CASE WHEN ISNULL(AccountType,'') ='' AND ISNULL(NET_QTY,0) <> 0 AND  ExpiryDate > @dtToDt THEN  ISNULL(MTM ,0) ELSE 0 END,
		  Lookup = Exchange+Segment+CAST(seriesid AS VARCHAR)
          FROM #tbl_ClientPL
          UNION ALL
          SELECT TAG = 2, Exchange, Segment, ClientCode, ClientName = '', seriesid = '', ExpiryDate= '', Scrip = ChargesDescp, 
	      Multiplier = 0,BF_QTY = 0, BF_CloseRate = 0, BF_VALUE = 0, BOT_QTY = 0, BOT_RATE = 0, BOT_VALUE = 0,
	      SOLD_QTY = 0, SOLD_RATE = 0, SOLD_VALUE = 0, EX_QTY = 0, EX_VALUE = 0, AS_QTY = 0, AS_VALUE = 0, NET_QTY = 0, CMP = 0, NET_VALUE = 0, 
	      MTM = (bc_amount)*-1, AccountType = '', RelPL = (ISNULL(bc_amount,0))*-1, UnRelPL = 0, Lookup = Exchange+Segment
	      FROM @tbl_billCharges) X1 
		  FOR XML PATH('ProfitLoss'))
	      SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
	    END
      END		
	  ELSE
	  BEGIN
		SELECT * FROM (
	    SELECT TAG = '1', Exchange, ClientCode, ClientName, 
        seriesid, ExpiryDate, Scrip, Multiplier,  BF_QTY = ISNULL(BF_QTY,0), BF_CloseRate = ISNULL(BF_CloseRate,0), 
        BF_VALUE = ISNULL(BF_VALUE,0), BOT_QTY = ISNULL(BOT_QTY,0), 
	    BOT_RATE = CAST(round((CASE WHEN ISNULL(BOT_QTY,0) <> 0 THEN ISNULL(BOT_VALUE,0)/ISNULL(BOT_QTY,0) ELSE 0 END),4) AS MONEY),
	    BOT_VALUE = ISNULL(BOT_VALUE,0), 
        SOLD_QTY = ISNULL(SOLD_QTY,0), 
	    SOLD_RATE = CAST(round((CASE WHEN ISNULL(SOLD_QTY,0) <> 0 THEN ISNULL(SOLD_VALUE,0)/ISNULL(SOLD_QTY,0) ELSE 0 END),4) AS MONEY),
	    SOLD_VALUE = ISNULL(SOLD_VALUE,0), EX_QTY = ISNULL(EX_QTY,0), EX_VALUE = ISNULL(EX_VALUE,0), 
	    AS_QTY = ISNULL(AS_QTY,0), 
        AS_VALUE = ISNULL(AS_VALUE,0), NET_QTY = ISNULL(NET_QTY,0),
        CMP =  ISNULL(CMP,0), NET_VALUE = ISNULL(NET_VALUE,0), MTM = ISNULL(MTM ,0), 
	    AccountType = ISNULL(AccountType,'N'),
        RelPL = CASE WHEN (ISNULL(AccountType,'N') ='Y' OR ISNULL(NET_QTY,0) = 0 OR ExpiryDate <=  @dtToDt ) 
	    THEN ISNULL(MTM ,0) ELSE 0 END,
	    UnRelPL = CASE WHEN ISNULL(AccountType,'') ='' AND ISNULL(NET_QTY,0) <> 0 AND ExpiryDate >  @dtToDt THEN  ISNULL(MTM ,0) ELSE 0 END,
		Lookup = CAST(seriesid AS VARCHAR)
        FROM #tbl_ClientPL
        UNION ALL
        SELECT TAG = 2, Exchange, ClientCode, ClientName = '', seriesid = '', ExpiryDate= '', Scrip = ChargesDescp, 
	    Multiplier = 0,BF_QTY = 0, BF_CloseRate = 0, BF_VALUE = 0, BOT_QTY = 0, BOT_RATE = 0, BOT_VALUE = 0,
	    SOLD_QTY = 0, SOLD_RATE = 0, SOLD_VALUE = 0, EX_QTY = 0, EX_VALUE = 0, AS_QTY = 0, AS_VALUE = 0, NET_QTY = 0, CMP = 0, NET_VALUE = 0, 
	    MTM = (bc_amount)*-1, AccountType = '', RelPL = (ISNULL(bc_amount,0))*-1, UnRelPL = 0, Lookup = Exchange+Segment
	    FROM @tbl_billCharges) X1 ORDER BY ClientCode, TAG, Scrip
		
	  END  
	  
	END
    ELSE IF ISNULL(@strReportType,'') in('Underlying wise')	
	BEGIN
	  SELECT * FROM (
	  select TAG = '1', Exchange, ClientCode, ClientName, Symbol, BOT_QTY = sum(BOT_QTY), 
	  SOLD_QTY = sum(SOLD_QTY), 
	  NET_VALUE = Sum(NET_VALUE), MTM = sum(MTM)
	  from(
	  SELECT Exchange, ClientCode, ClientName, 
      Symbol, seriesid, ExpiryDate, Scrip, Multiplier,  BF_QTY = ISNULL(BF_QTY,0), BF_CloseRate = ISNULL(BF_CloseRate,0), 
      BF_VALUE = ISNULL(BF_VALUE,0), BOT_QTY = ISNULL(BOT_QTY,0), BOT_VALUE = ISNULL(BOT_VALUE,0), 
      SOLD_QTY = ISNULL(SOLD_QTY,0), 
	  SOLD_VALUE = ISNULL(SOLD_VALUE,0), EX_QTY = ISNULL(EX_QTY,0), EX_VALUE = ISNULL(EX_VALUE,0), AS_QTY = ISNULL(AS_QTY,0), 
      AS_VALUE = ISNULL(AS_VALUE,0), NET_QTY = ISNULL(NET_QTY,0),
      CMP =  ISNULL(CMP,0), NET_VALUE = ISNULL(NET_VALUE,0), MTM = ISNULL(MTM ,0)
      FROM #tbl_ClientPL X) x12 GROUP BY Exchange, ClientCode, ClientName, Symbol
      UNION ALL
      SELECT TAG = 2, Exchange, ClientCode, ClientName = '', Symbol = ChargesDescp, BOT_QTY = 0, SOLD_QTY = 0,
	  NET_VALUE = 0, 
	  MTM = (ISNULL(bc_amount,0))*-1
	  FROM @tbl_billCharges) X1 ORDER BY ClientCode, TAG, Symbol
	END
	ELSE IF ISNULL(@strReportType,'') in('Series Wise Detail','')
	BEGIN
	  IF @strOutputType <> 'X'
	  BEGIN
	    SELECT * FROM (
	    SELECT TAG = '1', Exchange, ClientCode, ClientName, 
        seriesid, ExpiryDate, Scrip, Multiplier,  TrxnDate, BF_QTY = ISNULL(BF_QTY,0), BF_CloseRate = ISNULL(BF_CloseRate,0), 
        BF_VALUE = ISNULL(BF_VALUE,0), BOT_QTY = ISNULL(BOT_QTY,0), 
	    BOT_RATE = CAST(ROUND((CASE WHEN ISNULL(BOT_QTY,0) <> 0 THEN ISNULL(BOT_VALUE,0)/ISNULL(BOT_QTY,0) ELSE 0 END),4) AS MONEY),
	    BOT_VALUE = ISNULL(BOT_VALUE,0), 
        SOLD_QTY = ISNULL(SOLD_QTY,0), 
	    SOLD_RATE = CAST(ROUND((CASE WHEN ISNULL(SOLD_QTY,0) <> 0 THEN ISNULL(SOLD_VALUE,0)/ISNULL(SOLD_QTY,0) ELSE 0 END),4) AS MONEY),
	    SOLD_VALUE = ISNULL(SOLD_VALUE,0), EX_QTY = ISNULL(EX_QTY,0), EX_VALUE = ISNULL(EX_VALUE,0), AS_QTY = ISNULL(AS_QTY,0), 
        AS_VALUE = ISNULL(AS_VALUE,0), NET_QTY = ISNULL(NET_QTY,0),
        CMP =  ISNULL(CMP,0), NET_VALUE = ISNULL(NET_VALUE,0), MTM = ISNULL(MTM ,0), 
	    AccountType = ISNULL(AccountType,'N'),
        RelPL = CASE WHEN (ISNULL(AccountType,'N') ='Y' OR ISNULL(NET_QTY,0) = 0 OR ExpiryDate <=  @dtToDt) 
	    THEN ISNULL(MTM ,0) ELSE 0 END,
	    UnRelPL = CASE WHEN ISNULL(AccountType,'') ='' AND ISNULL(NET_QTY,0) <> 0 AND ExpiryDate >  @dtToDt THEN  ISNULL(MTM ,0) ELSE 0 END
        FROM #tbl_ClientPL
        UNION ALL
        SELECT TAG = 2, Exchange, ClientCode, ClientName = '', seriesid = '', ExpiryDate= '', Scrip = ChargesDescp, 
	    Multiplier = 0,TrxnDate = @dtToDt , BF_QTY = 0, BF_CloseRate = 0, BF_VALUE = 0, BOT_QTY = 0, BOT_RATE = 0, 
	    BOT_VALUE = 0,
	    SOLD_QTY = 0, SOLD_RATE = 0, SOLD_VALUE = 0, EX_QTY = 0, EX_VALUE = 0, AS_QTY = 0, AS_VALUE = 0, NET_QTY = 0, CMP = 0, NET_VALUE = 0, 
	    MTM = (bc_amount)*-1, AccountType = '', RelPL = (ISNULL(bc_amount,0))*-1, UnRelPL = 0
	    FROM @tbl_billCharges) X1 ORDER BY ClientCode, TAG, Scrip, TrxnDate
	  END
	  ELSE IF @strOutputType = 'X'
	  BEGIN
		SET @XMLDATA1 = (SELECT * FROM (
	    SELECT TAG = '1', Exchange, ClientCode, ClientName, 
        seriesid, ExpiryDate, Scrip, Multiplier,  TrxnDate, BF_QTY = ISNULL(BF_QTY,0), BF_CloseRate = ISNULL(BF_CloseRate,0), 
        BF_VALUE = ISNULL(BF_VALUE,0), BOT_QTY = ISNULL(BOT_QTY,0), 
	    BOT_RATE = CAST(ROUND((CASE WHEN ISNULL(BOT_QTY,0) <> 0 THEN ISNULL(BOT_VALUE,0)/ISNULL(BOT_QTY,0) ELSE 0 END),4) AS MONEY),
	    BOT_VALUE = ISNULL(BOT_VALUE,0), 
        SOLD_QTY = ISNULL(SOLD_QTY,0), 
	    SOLD_RATE = CAST(ROUND((CASE WHEN ISNULL(SOLD_QTY,0) <> 0 THEN ISNULL(SOLD_VALUE,0)/ISNULL(SOLD_QTY,0) ELSE 0 END),4) AS MONEY),
	    SOLD_VALUE = ISNULL(SOLD_VALUE,0), EX_QTY = ISNULL(EX_QTY,0), EX_VALUE = ISNULL(EX_VALUE,0), AS_QTY = ISNULL(AS_QTY,0), 
        AS_VALUE = ISNULL(AS_VALUE,0), NET_QTY = ISNULL(NET_QTY,0),
        CMP =  ISNULL(CMP,0), NET_VALUE = ISNULL(NET_VALUE,0), MTM = ISNULL(MTM ,0), 
	    AccountType = ISNULL(AccountType,'N'),
        RelPL = CASE WHEN (ISNULL(AccountType,'N') ='Y' OR ISNULL(NET_QTY,0) = 0 OR ExpiryDate <=  @dtToDt) 
	    THEN ISNULL(MTM ,0) ELSE 0 END,
	    UnRelPL = CASE WHEN ISNULL(AccountType,'') ='' AND ISNULL(NET_QTY,0) <> 0 AND ExpiryDate >  @dtToDt THEN  ISNULL(MTM ,0) ELSE 0 END
        FROM #tbl_ClientPL
        UNION ALL
        SELECT TAG = 2, Exchange, ClientCode, ClientName = '', seriesid = '', ExpiryDate= '', Scrip = ChargesDescp, 
	    Multiplier = 0,TrxnDate = @dtToDt , BF_QTY = 0, BF_CloseRate = 0, BF_VALUE = 0, BOT_QTY = 0, BOT_RATE = 0, 
	    BOT_VALUE = 0,
	    SOLD_QTY = 0, SOLD_RATE = 0, SOLD_VALUE = 0, EX_QTY = 0, EX_VALUE = 0, AS_QTY = 0, AS_VALUE = 0, NET_QTY = 0, CMP = 0, NET_VALUE = 0, 
	    MTM = (bc_amount)*-1, AccountType = '', RelPL = (ISNULL(bc_amount,0))*-1, UnRelPL = 0
	    FROM @tbl_billCharges) X1 
		WHERE ((seriesid <> '' and @StrLookup <> '') or isnull(@StrLookup,'') = '')
		ORDER BY ClientCode, TAG, Scrip, TrxnDate 
		FOR XML PATH('ProfitLoss'))
	    SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
	  END
	END
  END
  DROP TABLE #tbl_ClientPL
  END TRY
  BEGIN CATCH
    SET @o_vcErrorFlag  = 'E'
    SET @o_vcErrorMessage = ERROR_MESSAGE()
    RETURN 1
  END CATCH
  SET @o_vcErrorFlag  = 'S'
  --SET @o_vcErrorMessage = 'Process Completed'
  RETURN 1
END  
GO

CREATE PROCEDURE stpr_Rpt_ProfitLossNewCash @vcXML NVARCHAR(MAX), @o_vcErrorFlag VARCHAR(1) OUTPUT, @o_vcErrorMessage VARCHAR(MAX) OUTPUT 
WITH ENCRYPTION
AS
BEGIN
 /*
 ///////////////////////////////////////////////////////////////////////////////////////////
 // Create By     : VAIBHAV GARG
 // Created Date  : 05-DEC-2023
 // Description   : 
 // Reviewed By   : 
 // Review Date   : 
 //////////////////////////////////////////////////////////////////////////////////////////
*/
 --- Parameter Declaration
 
  DECLARE @dtFromDate VARCHAR(8), @dtToDt VARCHAR(8), @strUserId VARCHAR(500) = '', @strExchSeg VARCHAR(100),
  @XMLData XML, @strAccountType VARCHAR(500)='', @strTable VARCHAR(50)='', @strString VARCHAR(MAX) = '',
  @blnTplusCommex BIT, @StrCommexConn VARCHAR(MAX) = '', @strCommTable VARCHAR(100)='', @strCommClientMaster VARCHAR(100)='',
  @strCommCompanyExchange VARCHAR(100)='', @strsql1 VARCHAR(500)='', @strsqlstart VARCHAR(MAX)='', @strsqlLast VARCHAR(500)='',
  @strsqlHeader VARCHAR(MAX)='', @strSqlMain VARCHAR(MAX)='', @strSqlExecute VARCHAR(MAX)='', @strOutputType VARCHAR(1), 
  @strProduct VARCHAR(50)='', @strSelectTag VARCHAR(1)='', @strSelectUsers VARCHAR(500)='', @ExchSeg VARCHAR(50)='', 
  @strStringMin VARCHAR(MAX)='', @strSplFilter VARCHAR(MAX)='', @strReportType VARCHAR(50)='', @strRateType VARCHAR(50)='',
  @strConsiderOptionBF VARCHAR(1)='Y', @String VARCHAR(MAX)='', @strClientCode VARCHAR(50)='', @strScripCode VARCHAR(50)='',
  @strDetailReportCode VARCHAR(50)='', @strDetailReportCategroy VARCHAR(100), @strRequestFrom VARCHAR(1)='W', @strSummary VARCHAR(1)='',
  @strCompanyCode VARCHAR(1), @strReportDisplay VARCHAR(1)='P'
  
  
  IF @vcXML = ''
  BEGIN
    SET @o_vcErrorFlag  = 'E'
    SET @o_vcErrorMessage = 'Please Send Input Parameter(s)'
    RETURN 1
  END 

  SET @XMLData = CAST('<root>'+@vcXML+'</root>' AS XML)
  BEGIN TRY
  
  SELECT @dtFromDate = ISNULL(x.value('(FromDt)[1]', 'VARCHAR(8)'),''),
  @strProduct = ISNULL(x.value('(Product)[1]', 'VARCHAR(50)'),''),
  @dtToDt = ISNULL(x.value('(ToDt)[1]', 'VARCHAR(8)'),''),
  @strUserId = ISNULL(x.value('(UserId)[1]', 'VARCHAR(500)'),''),
  @ExchSeg = ISNULL(x.value('(ExchSeg)[1]', 'VARCHAR(500)'),''),
  @strSelectTag = ISNULL(x.value('(SelectTag)[1]', 'VARCHAR(1)'),''),
  @strSelectUsers = ISNULL(x.value('(SelectUsers)[1]', 'VARCHAR(500)'),''),
  @strOutputType = ISNULL(x.value('(OutputType)[1]', 'VARCHAR(1)'),''),
  @strSplFilter = ISNULL(x.value('(SplFilter)[1]', 'VARCHAR(MAX)'),''),
  @strReportType = ISNULL(x.value('(RepType)[1]', 'VARCHAR(100)'),''),
  @strRateType = ISNULL(x.value('(RepSubType)[1]', 'VARCHAR(100)'),''),
  @strConsiderOptionBF = ISNULL(x.value('(OptionBF)[1]', 'VARCHAR(100)'),''),
  @strClientCode = ISNULL(x.value('(ClientCode)[1]', 'VARCHAR(100)'),''),
  @strScripCode = ISNULL(x.value('(ScripCode)[1]', 'VARCHAR(100)'),''),
  @strDetailReportCode = ISNULL(x.value('(DetailReportCode)[1]', 'VARCHAR(100)'),''),
  @strDetailReportCategroy = ISNULL(x.value('(DetailReportCategroy)[1]', 'VARCHAR(100)'),''),
  @strRequestFrom = ISNULL(x.value('(RequestFrom)[1]', 'VARCHAR(1)'),''),
  @strSummary = ISNULL(x.value('(RequestSummary)[1]', 'VARCHAR(1)'),''),
  @strCompanyCode = ISNULL(x.value('(CompanyCode)[1]', 'VARCHAR(1)'),''),
  @strReportDisplay = ISNULL(x.value('(ReportDisplay)[1]', 'VARCHAR(1)'),'')
  FROM @XMLData.nodes('/root') AS XTbl(x) 



  IF ISNULL(@strRequestFrom,'') = '' 
  begin
    SET @strRequestFrom = 'W'
  END
  IF @strRateType = ''
  BEGIN
    SET @strRateType = 'Market Rate'
  END
  
  if ISNULL(@strScripCode,'') = ''
  BEGIN
    SET @strScripCode = ''
  END 
  
  IF ISNULL(@strSummary,'') =''
  BEGIN
    SET @strSummary  = 'N'
  END
  
  IF ISNULL(@strClientCode,'') <> ''
  BEGIN
    SET @strUserId = @strClientCode
  END
  
  
   IF ISNULL(@strReportDisplay,'') = ''
  BEGIN
    SET @strReportDisplay = 'P'
  END  
  
  
  IF @strReportDisplay IN('D','E','A','X') AND EXISTS(SELECT 1 FROM CLIENT_MASTER(NOLOCK) WHERE CM_cD = @strUserId)
  BEGIN
    DECLARE @o_Message NVARCHAR(MAX)=''
    EXEC stpr_TypestHeaderProc @strUserid, '', '', @strCompanyCode,  @o_Message OUTPUT
	  
    SET @o_Message = REPLACE(@o_Message,'##ReportName##','Profit and Loss Report for '  + CONVERT(VARCHAR(30), Cast(@dtFromDate as date), 103) + ' To ' + CONVERT(VARCHAR(30), Cast(@dtToDt as date), 103))
    SET @o_Message = REPLACE(@o_Message,'##Grid1##','')
    SET @o_Message = REPLACE(@o_Message,'##Grid2##','')
    SET @o_Message = REPLACE(@o_Message,'##Grid3##','')
    SET @o_Message = REPLACE(@o_Message,'##Grid4##','')
	SET @o_Message = REPLACE(@o_Message,'##PageOrientation##','Landscape')
	SET @o_Message = REPLACE(@o_Message,'##PageSize##','A4')
	--SET @o_Message = REPLACE(@o_Message,'##PageOrientation##','Landscape')
	IF @strReportDisplay IN('E','D','X')
	BEGIN
	  SET @o_Message = REPLACE(@o_Message,'##FormatGrid##','Grid1')
	  SET @strOutputType = 'G'
	END 
    ELSE 
	BEGIN
	  SET @o_Message = REPLACE(@o_Message,'##FormatGrid##','')
	END 
	
    SET @o_Message = '<root>' + @o_Message + '</root>';
  
    DECLARE @xmlData3 XML = CAST(@o_Message AS XML);
	
	DECLARE @DynamicColumns NVARCHAR(MAX);
    
	SET  @DynamicColumns = '';
  
    WITH DistinctNodes AS (
    SELECT DISTINCT
       NodeName = X.n.value('local-name(.)', 'NVARCHAR(100)')
    FROM @xmlData3.nodes('/root/ClientDetail/*') AS X(n))
    
    SELECT @DynamicColumns = @DynamicColumns+','+
        'LTRIM(RTRIM(X1.value(''(' + XX.NodeName + ')[1]'', ''NVARCHAR(MAX)''))) AS [' + XX.NodeName + ']'
    FROM DistinctNodes XX
	WHERE NodeName NOT IN('Grid2','Grid3','Grid4')
   
    SELECT @DynamicColumns = SUBSTRING(@DynamicColumns,2,LEN(@DynamicColumns)-1) 
  
    DECLARE @sql NVARCHAR(MAX);
    SET @sql = '
    SELECT ' + @DynamicColumns + '
    FROM @xmlData3.nodes(''/root/ClientDetail'') AS T(X1)';
  
    EXEC sp_executesql @sql, N'@xmlData3 XML', @xmlData3;
	
	IF @strReportDisplay NOT IN('A')
	BEGIN
	  SELECT ColumnName, ColumnHeading, ColumnWidth, ColumnAlignement, ColumnFormat, Columnstyle, DecimalPlace, ColumnTotal,
      ColumnHide = CASE WHEN Userid = '1' THEN 'Y' ELSE 'N'	END   
      FROM tbl_ReportGridViewFormat(NOLOCK) 
	  WHERE ReportCode='InvestorReport'
      and ReportCategroy = @strReportType AND ColumnVisible = '0'
      Order By Orderby
    END
  END	

  
  IF @strDetailReportCategroy <> ''
  BEGIN
    SET @strReportType = @strDetailReportCategroy
  END
  
  IF @strReportType = 'Cash_Settlementwise Summary'
  BEGIN
    SET @strReportType = 'Settlementwise Summary'
  END
  ELSE IF @strReportType = 'Cash_ScripWise Summary'
  BEGIN
    SET @strReportType = 'ScripWise Summary'
  END
  ELSE IF @strReportType = 'Cash_Stock Position Only'
  BEGIN
    SET @strReportType = 'Stock Position Only'
  END
  
  
  
  DECLARE @SehmentCH_ClgHs VARCHAR(1)='', @ch_EffDt VARCHAR(8)=''
  
  SELECT @SehmentCH_ClgHs = (CASE WHEN CH_ClgHs = 'I' THEN 'B' ELSE CH_ClgHs END) ,
  @CH_EffDt = CH_EffDt
  FROM ClearingHouse(NOLOCK)
  WHERE CH_CompanyCode = @strCompanyCode AND CH_Segment = 'C' 
  AND CH_EffDt = (SELECT Min(CH_EffDt) FROM ClearingHouse
  WHERE CH_CompanyCode = @strCompanyCode AND CH_Segment = 'C' AND CH_EffDt <= @dtToDt)
  
  
  DECLARE @tbl_ClientPL TABLE(CompanyCode VARCHAR(10), Exchange VARCHAR(10), Segment VARCHAR(10),  ClientCode VARCHAR(50), ClientName VARCHAR(100), 
  Symbol VARCHAR(50), seriesid INT, ExpiryDate VARCHAR(8), Scrip VARCHAR(100), Multiplier INT, TrxnDate VARCHAR(8), BF_QTY MONEY, BF_CloseRate MONEY, BF_VALUE MONEY, BOT_QTY MONEY, BOT_VALUE MONEY, 
  SOLD_QTY MONEY,SOLD_VALUE MONEY, EX_QTY MONEY, EX_VALUE MONEY, AS_QTY MONEY, AS_VALUE MONEY, MTM MONEY,
  NET_QTY MONEY, CMP MONEY, NET_VALUE MONEY)

  DECLARE @tbl_BSClient TABLE(CompanyCode VARCHAR(10), Exchange VARCHAR(10), Segment VARCHAR(10), ClientCode VARCHAR(50), ClientName VARCHAR(100), 
  Symbol VARCHAR(50), seriesid INT, ExpiryDate VARCHAR(8), Scrip VARCHAR(100), Multiplier INT, TrxnDate VARCHAR(8), BOT_QTY MONEY, BOT_VALUE MONEY, 
  SOLD_QTY MONEY, SOLD_VALUE MONEY)

  DECLARE @tbl_CLClient TABLE(CompanyCode VARCHAR(10), Exchange VARCHAR(10), Segment VARCHAR(10),  ClientCode VARCHAR(50), ClientName VARCHAR(100), 
  Symbol VARCHAR(50), seriesid INT, ExpiryDate VARCHAR(8), Scrip VARCHAR(100), Multiplier INT, TrxnDate VARCHAR(8), EX_QTY MONEY, EX_VALUE MONEY, AS_QTY MONEY, AS_VALUE MONEY)

  IF @strSplFilter = ''
  BEGIN
	SET @strStringMin  = 'DECLARE @tbl_UserList TABLE(Client_Code VARCHAR(50)) '
    +' INSERT INTO @tbl_UserList(Client_Code) '
    +' SELECT * FROM DBO.[fn_GetClients]('''+@strUserId+''','''+@strSelectTag+''','''+@strSelectUsers+''') '
  END  
  ELSE
  IF @strSplFilter <> ''
  BEGIN
    SET @strStringMin  = ' DECLARE @tbl_UserList TABLE (Client_Code VARCHAR(10)) '
	                     +' INSERT INTO @tbl_UserList(Client_Code) SELECT distinct CM_CD FROM Client_master(NOLOCK) WHERE 1 = 1  AND '+@strSplFilter
  END	
  
	
  IF @strProduct = 'CASH'
  BEGIN 
    IF OBJECT_ID('tempdb..#tbl_TradeSqrup') IS NOT NULL
      DROP TABLE #tbl_TradeSqrup
    IF OBJECT_ID('tempdb..#TrxSummaryDLV') IS NOT NULL
      DROP TABLE #TrxSummaryDLV
    IF OBJECT_ID('tempdb..#TrxDLV') IS NOT NULL
      DROP TABLE #TrxDLV


    CREATE TABLE #tbl_TradeSqrup (SerialNo INT identity(1, 1), td_companycode VARCHAR(1) ,td_stlmnt VARCHAR(15)
	,td_clientcd VARCHAR(10) ,td_scripcd VARCHAR(10) ,td_dt VARCHAR(8) ,td_bsflag VARCHAR(1) ,td_bqty MONEY ,td_sqty MONEY
	,td_rate MONEY ,td_marketrate MONEY ,td_BrokerageType VARCHAR(5))

    CREATE INDEX indx_TradeSqrup ON #tbl_TradeSqrup (td_dt,td_stlmnt)

    CREATE INDEX indx_TradeSqrup1 ON #tbl_TradeSqrup (SerialNo)

    
	SET @string = @strStringMin+' SELECT td_companycode, td_stlmnt, td_clientcd, td_scripcd, td_dt, td_bsflag, sum(td_bqty), sum(td_sqty), '
    +' SUM(td_rate * (td_bqty + td_sqty)), sum(td_marketrate * (td_bqty + td_sqty)), '
    +' ''SD1'' AS td_BrokerageType  FROM( ' 
    +' SELECT td_companycode, td_stlmnt, td_clientcd, td_scripcd, td_tradeid, td_subtradeid, td_dt, td_srno, '
    +' td_ssrno, td_bsflag, td_bqty, td_sqty, td_rate = CAST(td_rate AS MONEY), td_time, td_orderid, td_brokerage = '
    +' CAST(td_brokerage AS MONEY), td_brokeragetype = ''SD1'', td_servicetax, td_turnoverTax, td_marginyn, td_marketrate = '
    +' CAST(td_marketrate AS MONEY), td_terminalcd, td_ParticipantCode, td_cfflag, td_CtclId, td_SttWaived, '
    +' trx.mkrdt, td_ordertime, td_acckey, td_filler1, td_filler2  '
    +' FROM TRx(NOLOCK) , @tbl_UserList X, Settlements(NOLOCK) SETT  '
    +' WHERE td_clientcd = X.Client_Code  AND td_stlmnt = se_stlmnt  AND td_dt BETWEEN '''+@dtFromDate+''' AND '''+@dtToDt+''' '
    +' and NOT EXISTS(SELECT 1 FROM Settlement_type(NOLOCK) WHERE sy_maptype IN(''S'', ''W'', ''V'',''C'',''A'') and sy_exchange = SETT.se_exchange '
    +' and sy_type = SETT.se_type)  /*AND td_scripcd = ''534392'' */ '

	
    IF ISNULL(@ExchSeg,'') <> ''
    BEGIN
      SET @string =   @string+'  AND se_exchange IN(SELECT SUBSTRING(VALUE,2,1) FROM  ReturnTable('''+@ExchSeg+''','','')) '
    END	
	
	IF ISNULL(@strScripCode,'') <> ''
	BEGIN
	  SET @string =   @string+'  AND  td_scripcd = '''+@strScripCode+''''
	END
	
	SET @string =   @string+' ) X12 '
    +' GROUP BY td_companycode, td_stlmnt, td_clientcd, td_scripcd, td_dt, td_bsflag '
    +' order by td_clientcd, td_scripcd, td_dt, td_stlmnt '
	
   
    BEGIN TRY
      INSERT INTO #tbl_TradeSqrup(td_companycode, td_stlmnt, td_clientcd, td_scripcd, td_dt, td_bsflag, td_bqty, td_sqty, td_rate,
      td_marketrate, td_BrokerageType)
	  EXEC(@string)
    END TRY
    BEGIN CATCH
      SET @o_vcErrorMessage = error_message()
	  SET @o_vcErrorFlag = 'E'
	  RETURN 1  
    END CATCH  
   
   IF @SehmentCH_ClgHs = 'N'
   BEGIN   
	 UPDATE X
     SET td_stlmnt = b.se_stlmnt
     FROM #tbl_TradeSqrup X, Settlements a, Settlements b
     WHERE td_dt >= @CH_EffDt AND left(td_stlmnt, 2) IN ('BW', 'NN') AND td_stlmnt = a.se_stlmnt AND a.se_stdt = 
	 b.se_stdt AND left(a.se_stlmnt, 2) = 'BW' AND left(b.se_stlmnt, 2) = 'NN'


     UPDATE X
     SET td_stlmnt = b.se_stlmnt
     FROM #tbl_TradeSqrup X, Settlements a, Settlements b
     WHERE td_dt >= @CH_EffDt AND left(td_stlmnt, 2) IN ('BQ', 'NQ') AND td_stlmnt = a.se_stlmnt AND a.se_stdt = 
	 b.se_stdt AND left(a.se_stlmnt, 2) = 'BQ' AND left(b.se_stlmnt, 2) = 'NQ'
   END	 
   ELSE IF @SehmentCH_ClgHs = 'B'
   BEGIN   
     UPDATE X
     SET td_stlmnt = b.se_stlmnt
     FROM #tbl_TradeSqrup X, Settlements a, Settlements b
     WHERE td_dt >= @CH_EffDt AND left(td_stlmnt, 2) IN ('BW', 'NN') AND td_stlmnt = a.se_stlmnt AND a.se_stdt = 
	 b.se_stdt AND left(a.se_stlmnt, 2) = 'NN' AND left(b.se_stlmnt, 2) = 'BW'


     UPDATE X
     SET td_stlmnt = b.se_stlmnt
     FROM #tbl_TradeSqrup X, Settlements a, Settlements b
     WHERE td_dt >= @CH_EffDt AND left(td_stlmnt, 2) IN ('BQ', 'NQ') AND td_stlmnt = a.se_stlmnt AND a.se_stdt = 
	 b.se_stdt AND left(a.se_stlmnt, 2) = 'NQ' AND left(b.se_stlmnt, 2) = 'BQ'
   END	
    
	
	UPDATE #tbl_TradeSqrup
    SET td_rate = CASE WHEN (td_bqty + td_sqty) > 0 THEN td_rate / (td_bqty + td_sqty) ELSE 0 END, td_marketrate = 
    CASE WHEN (td_bqty + td_sqty) > 0 THEN td_marketrate / (td_bqty + td_sqty) ELSE 0 END
	
       
    CREATE TABLE #TrxSummaryDLV (clientcd VARCHAR(8) NOT NULL, SettlementNo VARCHAR(9), scripcd VARCHAR(6) NOT NULL, 
    Buys MONEY, Sells MONEY)

    INSERT INTO #TrxSummaryDLV
    SELECT td_clientcd, td_stlmnt, td_scripcd, Buys, Sells
    FROM (SELECT MAX(td_companycode + left(td_stlmnt, 2)) td_companycode, td_clientcd, cm_name, td_scripcd, ss_name, 
    ss_nsymbol, ss_nseries, td_stlmnt, sum(td_bqty) AS 'Buys', sum(td_sqty) 'Sells', sum(td_bqty - td_sqty) 'Delivery', 
    count(*) Totalrec, ss_group, cm_type
    FROM #tbl_TradeSqrup, Client_master, Securities
    WHERE cm_cd = td_clientcd AND td_scripcd = ss_cd
    GROUP BY td_clientcd, cm_name, td_scripcd, ss_cd, ss_name, ss_nsymbol, ss_nseries, ss_group, cm_type, td_stlmnt
    HAVING sum(td_bqty - td_sqty) <> 0) a

    CREATE TABLE #TrxDLV (SrNo NUMERIC, td_SettlementNo varchar(9), Qty NUMERIC, FinalQty NUMERIC)

    INSERT INTO #TrxDLV
    SELECT SerialNo, td_stlmnt,  Qty, CASE WHEN NetQty >= Running THEN Qty ELSE NetQty - isNull(PrevRunning, 0) END FinalQty
    FROM (SELECT SerialNo, td_clientcd, td_scripcd,td_stlmnt, td_marketrate,  NetQty, Qty, Running, LAG(
    Running) OVER (
    PARTITION BY td_clientcd, td_scripcd, td_stlmnt ORDER BY td_stlmnt DESC, SerialNo DESC) PrevRunning
    FROM (
    SELECT SerialNo, td_stlmnt, td_clientcd, td_scripcd, td_bqty + td_sqty Qty, td_marketrate,  
    abs(Buys - Sells) NetQty, Sum(td_bqty + td_sqty) OVER (
    PARTITION BY td_clientcd, td_scripcd, td_stlmnt ORDER BY td_stlmnt DESC, SerialNo DESC) Running
    FROM #tbl_TradeSqrup, Client_master, Securities, #TrxSummaryDLV
    WHERE cm_cd = td_clientcd AND td_scripcd = ss_cd
    AND td_clientcd = clientcd AND td_scripcd = scripcd  and td_stlmnt = SettlementNo
    AND td_bsflag = CASE WHEN Buys > Sells THEN 'B' ELSE 'S' END) a) b
    WHERE CASE WHEN NetQty >= Running THEN Qty ELSE NetQty - isNull(PrevRunning,0) END > 0


    INSERT INTO #tbl_TradeSqrup(td_companycode, td_stlmnt, td_clientcd, td_scripcd, td_dt, td_bsflag, td_bqty, td_sqty, td_rate,
    td_marketrate, td_BrokerageType)
    SELECT td_companycode, td_stlmnt, td_clientcd, td_scripcd, td_dt,
    td_bsflag, CASE td_bsflag WHEN 'B' THEN Qty - FinalQty ELSE 0 END, CASE td_bsflag WHEN 'S' THEN Qty - FinalQty ELSE 0 END, 
	TD_RATE, td_marketrate, td_brokeragetype ='SD1'
    FROM #tbl_TradeSqrup , #TrxDLV
    WHERE SerialNo = srno and td_stlmnt = td_SettlementNo 
	AND (Qty - FinalQty) > 0


    UPDATE #tbl_TradeSqrup
    SET td_bqty = FinalQty, td_brokeragetype = 'DLV' 
    FROM #TrxDLV
    WHERE SerialNo = srno and td_stlmnt = td_SettlementNo  AND td_bsflag = 'B'

    UPDATE #tbl_TradeSqrup
    SET td_sqty = FinalQty, td_brokeragetype = 'DLV'
    FROM #TrxDLV
    WHERE SerialNo = srno and td_stlmnt = td_SettlementNo and td_bsflag = 'S'

    DELETE #tbl_TradeSqrup
    WHERE td_bqty + td_sqty = 0
    	

    SET @string = @strStringMin+' SELECT td_companycode, td_stlmnt, td_clientcd, td_scripcd, td_dt, td_bsflag, sum(td_bqty), sum(td_sqty), '
    +' round((CASE WHEN sum(td_bqty + td_sqty) <> 0 THEN SUM(td_rate * (td_bqty + td_sqty))/sum(td_bqty + td_sqty) ELSE 0 END),4), '
	+' round((CASE WHEN sum(td_bqty + td_sqty) <> 0 THEN SUM(td_marketrate * (td_bqty + td_sqty))/sum(td_bqty + td_sqty) ELSE 0 END),4), '
    +' ''DLV'' AS td_BrokerageType  FROM( ' 
    +' SELECT td_companycode, td_stlmnt, td_clientcd, td_scripcd, td_tradeid, td_subtradeid, td_dt, td_srno, '
    +' td_ssrno, td_bsflag, td_bqty, td_sqty, td_rate, td_time, td_orderid, td_brokerage = '
    +' CAST(td_brokerage AS MONEY), td_brokeragetype = ''DLV'', td_servicetax, td_turnoverTax, td_marginyn, td_marketrate, '
	+' td_terminalcd, td_ParticipantCode, td_cfflag, td_CtclId, td_SttWaived, '
    +' trx.mkrdt, td_ordertime, td_acckey, td_filler1, td_filler2  '
    +' FROM TRx(NOLOCK) , @tbl_UserList X, Settlements(NOLOCK) SETT '
    +' WHERE td_clientcd = X.Client_Code  AND td_stlmnt = se_stlmnt  AND td_dt BETWEEN '''+@dtFromDate+''' AND '''+@dtToDt+''' '
    +' and EXISTS(SELECT 1 FROM Settlement_type(NOLOCK) WHERE ISNULL(sy_maptype,'''') IN(''C'',''A'') and sy_exchange = SETT.se_exchange '
    +' and sy_type = SETT.se_type) /*AND td_scripcd = ''534392'' */'
	

    IF ISNULL(@ExchSeg,'') <> ''
    BEGIN
      SET @string =   @string+'  AND se_exchange IN(SELECT SUBSTRING(VALUE,2,1) FROM  ReturnTable('''+@ExchSeg+''','','')) '
    END	
	
	IF ISNULL(@strScripCode,'') <> ''
	BEGIN
	  SET @string =   @string+'  AND  td_scripcd = '''+@strScripCode+''''
	END
	
	
	SET @string =   @string+' ) X12 '
    +' GROUP BY td_companycode, td_stlmnt, td_clientcd, td_scripcd, td_dt, td_bsflag '
    +' order by td_clientcd, td_scripcd, td_dt, td_stlmnt '
	
   
    BEGIN TRY
      INSERT INTO #tbl_TradeSqrup(td_companycode, td_stlmnt, td_clientcd, td_scripcd, td_dt, td_bsflag, td_bqty, td_sqty, td_rate,
      td_marketrate, td_BrokerageType)
	  EXEC(@string)
    END TRY
    BEGIN CATCH
      SET @o_vcErrorMessage = error_message()
	  SET @o_vcErrorFlag = 'E'
	  RETURN 1  
    END CATCH  


	DECLARE @tbl_ProfileLOss TABLE(ClientCode VARCHAR(50), SettEndDate VARCHAR(8), 
	SettlementNo VARCHAR(50),
	ScripCode VARCHAR(20), ScripTag VARCHAR(1), TradingFlag VARCHAR(1), BuyQty MONEY, BuyRate MONEY, 
	BuyValue MONEY, SaleQty MONEY,  SaleRate MONEY, SaleValue MONEY,
    NetQty MONEY, NetValue MONEY, AvgRate MONEY, CMP MONEY, NotionalPL MONEY, RelPl MONEY)
	
	
	IF @strReportType <> 'Settlementwise Summary'
	BEGIN
	  INSERT INTO @tbl_ProfileLOss(ClientCode, ScripCode, ScripTag, BuyQty, BuyRate, BuyValue, SaleQty,SaleRate, SaleValue, NetQty, NetValue, AvgRate)
	  SELECT td_clientcd, td_scripcd, CASE WHEN td_brokeragetype = 'DLV' THEN 'N' ELSE 'Y' END AS td_flag,  
	  td_bqty = SUM(td_bqty), BuyRate = CASE WHEN SUM(td_bqty)>0 THEN round(SUM(td_bqty*td_rate)/SUM(td_bqty),2) ELSE 0 END,
      BuyValue = SUM(td_bqty*td_rate), td_sqty = SUM(td_sqty), SaleRate = CASE WHEN SUM(td_sqty)>0 THEN round(SUM(td_sqty*td_rate)/SUM(td_sqty),2) ELSE 0 END,
      saleValue = SUM(td_sqty*td_rate),  NetQty = SUM(td_bqty)-SUM(td_sqty), NetValue = round(SUM(td_sqty*td_rate) - SUM(td_bqty*td_rate),2),
      AvgRate = abs(CASE WHEN SUM(td_bqty)-SUM(td_sqty)<>0 THEN round(SUM(td_sqty*td_rate) - SUM(td_bqty*td_rate),2)/(SUM(td_bqty)-SUM(td_sqty)) ELSE 0 END)
      FROM #tbl_TradeSqrup
      Group by td_clientcd, td_scripcd, CASE WHEN td_brokeragetype = 'DLV' THEN 'N' ELSE 'Y' END
	END
    ELSE
    IF @strReportType = 'Settlementwise Summary' 	
	BEGIN
	  INSERT INTO @tbl_ProfileLOss(ClientCode, SettEndDate, SettlementNo, ScripCode, ScripTag,  BuyQty, 
	  BuyRate, BuyValue, SaleQty,SaleRate, SaleValue, NetQty, NetValue, AvgRate)
	  SELECT td_clientcd, se_endt, td_stlmnt, td_scripcd, CASE WHEN td_brokeragetype = 'DLV' THEN 'N' ELSE 'Y' END AS td_flag,  
	  td_bqty = SUM(td_bqty), BuyRate = CASE WHEN SUM(td_bqty)>0 THEN round(SUM(td_bqty*td_rate)/SUM(td_bqty),2) ELSE 0 END,
      BuyValue = SUM(td_bqty*td_rate), td_sqty = SUM(td_sqty), 
	  SaleRate = CASE WHEN SUM(td_sqty)>0 THEN ROUND(SUM(td_sqty*td_rate)/SUM(td_sqty),2) ELSE 0 END,
      saleValue = SUM(td_sqty*td_rate),  NetQty = SUM(td_bqty)-SUM(td_sqty), NetValue = round(SUM(td_sqty*td_rate) - SUM(td_bqty*td_rate),2),
      AvgRate = abs(CASE WHEN SUM(td_bqty)-SUM(td_sqty)<>0 THEN round(SUM(td_sqty*td_rate) - SUM(td_bqty*td_rate),2)/(SUM(td_bqty)-SUM(td_sqty)) ELSE 0 END)
	  FROM #tbl_TradeSqrup X, Settlements(NOLOCK) SETT
	  WHERE X.td_stlmnt = SETT.se_stlmnt
      Group by td_clientcd, td_scripcd,  se_endt, td_stlmnt, 
	  CASE WHEN td_brokeragetype = 'DLV' THEN 'N' ELSE 'Y' END
	END
	
	IF OBJECT_ID('tempdb..#TrxDLV1') IS NOT NULL
	  DROP TABLE #TrxDLV1
    IF OBJECT_ID('tempdb..#TrxSummaryDLV1') IS NOT NULL
	  DROP TABLE #TrxSummaryDLV1
    IF OBJECT_ID('tempdb..#tbl_TradeSqrup1') IS NOT NULL
	  DROP TABLE #tbl_TradeSqrup1
	
    CREATE TABLE  #tbl_TradeSqrup1(SerialNo int identity(1,1), td_companycode VARCHAR(1), td_stlmnt VARCHAR(15), 
	td_clientcd VARCHAR(10), td_scripcd VARCHAR(10), 
    td_dt VARCHAR(8), td_bsflag VARCHAR(1), td_bqty MONEY, td_sqty MONEY, td_rate MONEY, td_marketrate MONEY, td_BrokerageType VARCHAR(5))
	
	CREATE INDEX indx_TradeSqrup1 ON #tbl_TradeSqrup1 (td_dt, td_stlmnt)
    CREATE INDEX indx_TradeSqrup11 ON #tbl_TradeSqrup1 (SerialNo)
	
    INSERT INTO #tbl_TradeSqrup1(td_companycode, td_stlmnt, td_clientcd, td_scripcd, td_dt, td_bsflag, td_bqty, td_sqty, td_rate,
    td_marketrate, td_BrokerageType)
	SELECT td_companycode, td_stlmnt, td_clientcd, td_scripcd, td_dt, td_bsflag, td_bqty, td_sqty, td_rate,
    td_marketrate, td_BrokerageType ='SD1'
	FROM #tbl_TradeSqrup
	WHERE td_brokeragetype = 'DLV'
    
    
    CREATE TABLE #TrxSummaryDLV1 (clientcd VARCHAR(8) NOT NULL, scripcd VARCHAR(6) NOT NULL, Buys MONEY, Sells MONEY)

    INSERT INTO #TrxSummaryDLV1
	SELECT td_clientcd, td_scripcd, Buys, Sells
    FROM (SELECT MAX(td_companycode + left(td_stlmnt, 2)) td_companycode, td_clientcd, cm_name, td_scripcd, ss_name, 
    ss_nsymbol, ss_nseries, sum(td_bqty) AS 'Buys', sum(td_sqty) 'Sells', sum(td_bqty - td_sqty) 'Delivery', 
    count(*) Totalrec, ss_group, cm_type
    FROM #tbl_TradeSqrup1, Client_master, Securities
    WHERE cm_cd = td_clientcd AND td_scripcd = ss_cd
    GROUP BY td_clientcd, cm_name, td_scripcd, ss_cd, ss_name, ss_nsymbol, ss_nseries, ss_group, cm_type
    HAVING sum(td_bqty - td_sqty) <> 0) a

    CREATE TABLE #TrxDLV1 (SrNo NUMERIC, Qty NUMERIC, FinalQty NUMERIC)

    INSERT INTO #TrxDLV1
	SELECT SerialNo, Qty, CASE WHEN NetQty >= Running THEN Qty ELSE NetQty - isNull(PrevRunning, 0) END FinalQty
    FROM (
	SELECT SerialNo, td_clientcd, td_scripcd, td_marketrate,  NetQty, Qty, Running, LAG(
			Running) OVER (
			PARTITION BY td_clientcd, td_scripcd ORDER BY td_dt DESC,  SerialNo DESC
			) PrevRunning
	FROM (
		SELECT SerialNo, td_dt, td_clientcd, td_scripcd, td_bqty + td_sqty Qty, td_marketrate,  abs(Buys - Sells) NetQty, Sum(td_bqty + td_sqty) OVER (
				PARTITION BY td_clientcd, td_scripcd ORDER BY td_dt DESC,  SerialNo DESC
				) Running
	FROM #tbl_TradeSqrup1, Client_master, Securities, #TrxSummaryDLV1
		WHERE cm_cd = td_clientcd AND td_scripcd = ss_cd
			AND td_clientcd = clientcd AND td_scripcd = scripcd AND td_bsflag = CASE WHEN Buys > Sells THEN 'B' ELSE 'S' END
		) a
	  ) b
    WHERE CASE WHEN NetQty >= Running THEN Qty ELSE NetQty - isNull(PrevRunning, 0) END > 0

	INSERT INTO #tbl_TradeSqrup1(td_companycode, td_stlmnt, td_clientcd, td_scripcd, td_dt, td_bsflag, td_bqty, td_sqty, td_rate,
    td_marketrate, td_BrokerageType)
    SELECT td_companycode, td_stlmnt, td_clientcd, td_scripcd, td_dt,
    td_bsflag, CASE td_bsflag WHEN 'B' THEN Qty - FinalQty ELSE 0 END, CASE td_bsflag WHEN 'S' THEN Qty - FinalQty ELSE 0 END
    ,TD_RATE , td_marketrate, td_brokeragetype ='SD1'
    FROM #tbl_TradeSqrup1, #TrxDLV1
    WHERE SerialNo = srno 
	AND (Qty - FinalQty) > 0

 
    UPDATE #tbl_TradeSqrup1
    SET td_bqty = FinalQty, td_brokeragetype = 'DLV' 
    FROM #TrxDLV1
    WHERE SerialNo = srno  AND td_bsflag = 'B'

    UPDATE #tbl_TradeSqrup1
    SET td_sqty = FinalQty, td_brokeragetype = 'DLV' 
    FROM #TrxDLV1
    WHERE SerialNo = srno and td_bsflag = 'S'

    DELETE #tbl_TradeSqrup1
    WHERE td_bqty + td_sqty = 0
	
	
    DECLARE @CH_ClgHs VARCHAR(1)=@SehmentCH_ClgHs
    
    DECLARE @tbl_CloseRate TABLE(Scrip VARCHAR(20), CloseRate MONEY)
	
	IF @strRateType IN('Market Rate' ,'Average Rate')
    BEGIN 
	
	  INSERT INTO @tbl_CloseRate(Scrip, CloseRate)
	  SELECT DISTINCT ScripCode, '' AS CloseRate FROM @tbl_ProfileLOss
	
	  IF @CH_ClgHs = 'N'
	  BEGIN
	    UPDATE A SET A.CloseRate = B.mk_closerate
	    FROM @tbl_CloseRate A, Market_rates(NOLOCK) B 
        WHERE A.Scrip = B.mk_scripcd AND mk_dt = (select  max(mk_dt) from Market_rates(NOLOCK)  
	    WHERE mk_exchange = 'B' and mk_dt<=@dtToDt) AND  mk_exchange = 'B'
	  	  
	    UPDATE A SET A.CloseRate = B.mk_closerate
	    FROM @tbl_CloseRate A, Market_rates(NOLOCK) B 
        WHERE A.Scrip = B.mk_scripcd 
	    AND mk_dt = (select  max(mk_dt) from Market_rates(NOLOCK)  
	    WHERE mk_exchange = 'N'
	    and mk_dt<=@dtToDt) AND  mk_exchange = 'N'
		
	  END  
	  ELSE
	  IF @CH_ClgHs = 'B'
	  BEGIN
	    UPDATE A SET A.CloseRate = B.mk_closerate
	    FROM @tbl_CloseRate A, Market_rates(NOLOCK) B 
        WHERE A.Scrip = B.mk_scripcd AND mk_dt = (select  max(mk_dt) from Market_rates(NOLOCK)  
	    WHERE mk_exchange = 'N' and mk_dt<=@dtToDt) AND  mk_exchange = 'N'
	  	  
	    UPDATE A SET A.CloseRate = B.mk_closerate
	    FROM @tbl_CloseRate A, Market_rates(NOLOCK) B 
        WHERE A.Scrip = B.mk_scripcd 
	    AND mk_dt = (select  max(mk_dt) from Market_rates(NOLOCK)  
	    WHERE mk_exchange = 'B'
	    and mk_dt<=@dtToDt) AND  mk_exchange = 'B'
	  END  
	
	  UPDATE A SET A.CloseRate = B.mk_closerate
	  FROM @tbl_CloseRate A, Market_rates B
	  WHERE mk_dt = (select  max(mk_dt) from Market_rates(NOLOCK)  
	  WHERE mk_scripcd = B.mk_scripcd and mk_dt<=@dtToDt)
      AND A.Scrip = B.mk_scripcd	
	  AND ISNULL(A.CloseRate,0) = 0
	  and EXISTS(SELECT 1 FROM Securities(NOLOCK) 
      WHERE ss_cd = A.Scrip and ss_group in ('F','G','GC'))
			
 	  UPDATE A SET A.CMP = CloseRate, A.NotionalPL = (A.NetQty * CloseRate)+ISNULL(NetValue,0)
      FROM @tbl_ProfileLOss A, @tbl_CloseRate B  
	  WHERE A.ScripCode = B.Scrip
      AND NetQty <> 0
	
      UPDATE A SET A.NotionalPL = ISNULL(NetValue,0)
      FROM @tbl_ProfileLOss A  
      WHERE NetQty = 0
			
	  UPDATE A SET A.NetValue = case when @strRateType IN('Market Rate','Average Rate') 
	  then abs(isnull(A.NetQty,0)*isnull(A.CMP,0)) else A.NetValue end 
      FROM @tbl_ProfileLOss A
	  
	  UPDATE A SET A.RelPl =  (SaleValue-BuyValue)+(ROUND(B.NetQty*B.AugRate,2))
	  FROM @tbl_ProfileLOss A,(
	  select td_clientcd, td_scripcd, SUM(td_bqty-td_sqty) As NetQty, 
	  Sum((td_sqty*td_rate)-(td_Bqty*td_rate)) As NetValue,
	  AugRate = ABS(CASE WHEN SUM(td_bqty-td_sqty)<>0 THEN Sum((td_sqty*td_rate)-(td_Bqty*td_rate))/SUM(td_bqty-td_sqty) ELSE 0 END)
	  FROM #tbl_TradeSqrup1
	  WHERE td_brokeragetype = 'DLV'
	  GROUP BY td_clientcd, td_scripcd) B
	  WHERE  A.ClientCode = B.td_clientcd
	  AND A.ScripCode = B.td_scripcd
	  AND ScripTag = 'N' and buyqty <> saleQty and buyqty > 0 and saleQty > 0
	  
	  UPDATE A SET A.RelPl =  (SaleValue-BuyValue)
	  FROM @tbl_ProfileLOss A
	  WHERE buyqty = saleQty
	  
	  UPDATE A SET RelPl = 0
	  FROM @tbl_ProfileLOss A
	  WHERE buyqty <> saleQty and (buyqty = 0 or saleQty = 0)
	  
	END
	
	ELSE IF @strRateType IN('COST')
	BEGIN  
	  
	  UPDATE A SET A.CMP = B.AugRate, A.AvgRate = B.AugRate, A.NetValue = ABS(B.NetValue), A.NetQty = B.NetQty
	  FROM @tbl_ProfileLOss A, (select td_clientcd, td_scripcd, SUM(td_bqty-td_sqty) As NetQty, 
	  Sum((td_sqty*td_rate)-(td_Bqty*td_rate)) As NetValue,
	  AugRate = ABS(CASE WHEN SUM(td_bqty-td_sqty)<>0 THEN Sum((td_sqty*td_rate)-(td_Bqty*td_rate))/SUM(td_bqty-td_sqty) ELSE 0 END)
	  FROM #tbl_TradeSqrup1
	  WHERE td_brokeragetype = 'DLV'
	  GROUP BY td_clientcd, td_scripcd) B
	  where A.ClientCode = B.td_clientcd
	  AND A.ScripCode = B.td_scripcd
	  AND ScripTag = 'N'
	
	  UPDATE A SET NotionalPL = SaleValue-BuyValue
	  FROM @tbl_ProfileLOss A
	  WHERE buyqty = saleQty
	
	  UPDATE A SET NotionalPL = (SaleValue-BuyValue)+(ROUND(NetQty*AvgRate,2))
	  FROM @tbl_ProfileLOss A
	  WHERE buyqty <> saleQty and buyqty > 0 and saleQty > 0
	  
	  UPDATE A SET NotionalPL = 0
	  FROM @tbl_ProfileLOss A
	  WHERE buyqty <> saleQty and (buyqty = 0 or saleQty = 0)
	  
	END
  
 	DECLARE @tbl_CashBill TABLE (Tag INT identity(1,1), ClientCode VARCHAR(50), ClientName VARCHAR(50),  SettEndDate varchar(8),
	SettlementNo VARCHAR(50),
	ScripCode VARCHAR(20), 
	ScripName VARCHAR(100), ScripTag VARCHAR(1), TradingFlag VARCHAR(1),
	BuyQty MONEY, BuyRate Money, BuyValue MONEY, SaleQty MONEY,  SaleRate MONEY, SaleValue MONEY, NetQty MONEY, NetValue MONEY, 
	AvgRate MONEY, Cmp MONEY, NotPL MONEY, RelPl MONEY)
	
	IF @strReportType <> 'Settlementwise Summary'
	BEGIN
	  INSERT INTO @tbl_CashBill(ClientCode, ClientName,  ScripCode, ScripName, ScripTag, TradingFlag,
	  BuyQty, BuyRate, BuyValue, SaleQty, SaleRate, SaleValue, NetQty, NetValue, AvgRate, Cmp, NotPL, RelPl)
      SELECT ClientCode, ClientName = CM.cm_name,  ScripCode, ScripName = ss_lname, ScripTag, TradingFlag, 
	  BuyQty, BuyRate, BuyValue, SaleQty, SaleRate, SaleValue, 
	  NetQty, NetValue, AvgRate = ABS(AvgRate), 
	  CMP =ISNULL(cmp,0) , 
      NotPL  = ISNULL(NotionalPL ,0), RelPl = ISNULL(RelPl,0)
      FROM @tbl_ProfileLOss A, Securities(NOLOCK) S, Client_Master(NOLOCK) cm
      WHERE A.ScripCode = S.ss_cd
	  and a.ClientCode = CM.CM_CD
      ORDER BY  ClientCode, ss_lname, ScripTag desc
	END
    ELSE	
	IF @strReportType = 'Settlementwise Summary'
	BEGIN
      INSERT INTO @tbl_CashBill(ClientCode, ClientName, SettEndDate, SettlementNo, ScripCode, ScripName,ScripTag, TradingFlag, 
	  BuyQty, BuyRate, BuyValue, SaleQty, SaleRate, SaleValue, NetQty, NetValue, AvgRate, Cmp, NotPL)
      SELECT ClientCode, ClientName = CM.cm_name, SettEndDate,SettlementNo,  
	  ScripCode, ScripName = ss_lname, 
	  ScripTag , 
	  TradingFlag, BuyQty, BuyRate, BuyValue, SaleQty, SaleRate, SaleValue, NetQty, NetValue, AvgRate = ABS(AvgRate), 
	  CMP =ISNULL(cmp,0) , 
      NotPL  = ISNULL(NotionalPL ,0)
      FROM @tbl_ProfileLOss A, Securities(NOLOCK) S, Client_Master(NOLOCK) cm
      WHERE A.ScripCode = S.ss_cd
	  and a.ClientCode = CM.CM_CD
      ORDER BY  ClientCode, ss_lname, ScripTag desc
	END
	IF ISNULL(@strScripCode,'') = ''
	BEGIN
	  INSERT INTO @tbl_CashBill(ClientCode, ClientName,  ScripCode, ScripName, ScripTag,
	  BuyQty, BuyRate, BuyValue, SaleQty, SaleRate, SaleValue, NetQty, NetValue, AvgRate, Cmp, NotPL, RelPl)
    
	  SELECT ClientCode = sh_clientcd, ClientName = '',  ScripCode = '', ScripName = sh_desc, ScripTag = '',
	  BuyQty = 0, BuyRate = 0, BuyValue = 0, SaleQty = 0, SaleRate = 0, SaleValue = 0, NetQty = 0, NetValue = 0, AvgRate = 0, 
	  Cmp = 0, isnull(round(sum(sh_amount),2),0)*-1, isnull(round(sum(sh_amount),2),0)*-1
	  FROM Specialcharges(NOLOCK) X, Settlements(NOLOCK)  SC, 
	  (SELECT DISTINCT Client_Code = ClientCode  FROM @tbl_ProfileLOss) X1
      WHERE SH_clientcd = x1.Client_code and sh_stlmnt = se_stlmnt
      AND ((se_exchange IN(SELECT SUBSTRING(VALUE,2,1) FROM ReturnTable(@ExchSeg,',')) and @ExchSeg <> '') OR @ExchSeg = '')
      AND se_stdt >= @dtFromDate AND se_stdt<= @dtToDt
      group by sh_companycode, sh_clientcd, sh_desc
      UNION ALL
      SELECT ClientCode = sh_clientcd, ClientName = '',  ScripCode = '', ScripName = 'SERVICE TAX', ScripTag = '',
	  BuyQty = 0, BuyRate = 0, BuyValue = 0, SaleQty = 0, SaleRate = 0, SaleValue = 0, NetQty = 0, NetValue = 0, AvgRate = 0, Cmp = 0, isnull(round(sum(sh_servicetax),2),0)*-1,
	  isnull(round(sum(sh_servicetax),2),0)*-1
	  FROM Specialcharges(NOLOCK) X, Settlements(NOLOCK)  SC, (SELECT DISTINCT Client_Code = ClientCode  FROM @tbl_ProfileLOss)  X1
      WHERE sh_clientcd = x1.Client_code
      AND sh_stlmnt = se_stlmnt
      AND ((se_exchange IN(SELECT SUBSTRING(VALUE,2,1) FROM ReturnTable(@ExchSeg,',')) and @ExchSeg <> '') OR @ExchSeg = '')
      AND se_stdt >= @dtFromDate AND se_stdt<= @dtToDt
      GROUP BY sh_companycode, se_Exchange, sh_clientcd, sh_desc
      HAVING ROUND(SUM(sh_servicetax),2) <> 0
	  ORDER BY sh_clientcd, sh_desc
	END   
	DECLARE @XMLDATA1 VARCHAR(MAX)=''
	IF @strReportType not in( 'Settlementwise Summary','Stock Position Only')
	BEGIN
	  IF @strOutputType = 'X'
	  BEGIN
	    IF ISNULL(@strSummary,'N') = 'N'
		BEGIN
	      SET @XMLDATA1 = (SELECT ClientCode, ClientName,  ScripCode, ScripName, 
		  ScripTag = CASE WHEN ScripTag = 'N' THEN 'Delivery' WHEN ScripTag = 'Y' THEN 'Square off' else ScripTag END, 
	      TradingFlag, BuyQty, BuyRate, BuyValue, SaleQty, SaleRate, SaleValue, NetQty, NetValue = isnull(NetValue,0)*-1, 
		  AvgRate, Cmp, NotPL, RelPl = round(isnull(RelPl,0),2), 
		  UnRel = CASE WHEN ScripCode <> '' THEN round(NotPL,2) - round(isnull(RelPl,0),2) ELSE 0 END,
		  Charges =  CASE WHEN ISNULL(ScripCode,'') = '' THEN round(NotPL,2)  else 0 end
	      FROM @tbl_CashBill --WHERE ((@strRequestFrom = 'M' AND ISNULL(ScripCode,'') <> '') OR  @strRequestFrom <> 'M') 
		  ORDER BY ClientCode, Tag FOR XML PATH('ProfitLoss'))
	      SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
		  RETURN 1
		END
		ELSE
	    IF ISNULL(@strSummary,'N') = 'Y'
		BEGIN
		  SET @XMLDATA1 = (SELECT TotalCharges = SUM(CASE WHEN ISNULL(ScripCode,'') = '' THEN round(isnull(NotPL,0),2) ELSE 0 END),
		  RelPl = SUM(CASE WHEN ISNULL(ScripCode,'') <> '' THEN round(isnull(RelPl,0),2) ELSE 0 END), 
		  UnRel = SUM(CASE WHEN ScripCode <> '' THEN round(NotPL,2) - round(isnull(RelPl,0),2) ELSE 0 END)
	      FROM @tbl_CashBill FOR XML PATH('ProfitLoss'))
	      SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
		  RETURN 1
		END
	  END
      ELSE
      BEGIN	  
	    SELECT ClientCode, ClientName,  ScripCode, ScripName, ScripTag = CASE WHEN ScripTag = 'N' THEN 'Delivery' 
	    WHEN ScripTag = 'Y' THEN 'Square off' else ScripTag END, 
	    TradingFlag, 
	    BuyQty, BuyRate, BuyValue, SaleQty, SaleRate, SaleValue, NetQty, NetValue, AvgRate, Cmp, NotPL, RelPl = round(isnull(RelPl,0),2),
	    UnRel = CASE WHEN ScripCode <> '' THEN round(NotPL,2) - round(isnull(RelPl,0),2) ELSE 0 END
	    FROM @tbl_CashBill order by ClientCode, Tag
	  END	
	END  
	ELSE IF @strReportType = 'Settlementwise Summary'
	BEGIN
	  IF @strOutputType = 'X'
	  BEGIN
	    SET @XMLDATA1 = (SELECT ClientCode, ClientName, SettEndDate = isnull(SettEndDate,''), 
		SettlementNo = isnull(SettlementNo,''), ScripCode, ScripName, ScripTag, TradingFlag, 
	    BuyQty, BuyRate, BuyValue, SaleQty, SaleRate, SaleValue, NetQty, NetValue, AvgRate, Cmp, NotPL 
	    FROM  @tbl_CashBill order by ClientCode, Tag FOR XML PATH('ProfitLoss'))
	    SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
		RETURN 1
	  END
	  ELSE
	  BEGIN
	    SELECT ClientCode, ClientName, SettEndDate = isnull(SettEndDate,''), SettlementNo = isnull(SettlementNo,''), ScripCode, 
		ScripName, ScripTag = CASE WHEN ScripTag = 'N' THEN 'Delivery' WHEN ScripTag = 'Y' THEN 'Square off' else ScripTag END, TradingFlag, 
	    BuyQty, BuyRate, BuyValue, SaleQty, SaleRate, SaleValue, NetQty, NetValue, AvgRate, Cmp, NotPL 
	    from  @tbl_CashBill order by ClientCode, Tag
	  END	
    end	  
	IF @strReportType = 'Stock Position Only'
	BEGIN
	  IF @strOutputType = 'X'
	  BEGIN
	    SET @XMLDATA1 = (SELECT ClientCode, ClientName,  ScripCode, ScripName, 
		ScripTag = CASE WHEN ScripTag = 'N' THEN 'Delivery' 
	    WHEN ScripTag = 'Y' THEN 'Square off' else ScripTag END, TradingFlag, 
	    BuyQty, BuyRate, BuyValue, SaleQty, SaleRate, SaleValue, NetQty, NetValue, AvgRate, Cmp, NotPL 
	    from  @tbl_CashBill where ISNULL(NetQty,0) <> 0
	    order by ClientCode, Tag FOR XML PATH('ProfitLoss'))
	    SET @o_vcErrorMessage = CAST(@XMLDATA1 AS VARCHAR(MAX))
		RETURN 1
	  END
	  ELSE
	  BEGIN 
	    select ClientCode, ClientName,  ScripCode, ScripName, ScripTag = CASE WHEN ScripTag = 'N' THEN 'Delivery' 
	    WHEN ScripTag = 'Y' THEN 'Square off' else ScripTag END, TradingFlag, 
	    BuyQty, BuyRate, BuyValue, SaleQty, SaleRate, SaleValue, NetQty, NetValue, AvgRate, Cmp, NotPL 
	    from  @tbl_CashBill where ISNULL(NetQty,0) <> 0
	    order by ClientCode, Tag
	  END	
	END
  END
  END TRY
  BEGIN CATCH
    SET @o_vcErrorFlag  = 'E'
    SET @o_vcErrorMessage = ERROR_MESSAGE()
    RETURN 1
  END CATCH
  SET @o_vcErrorFlag  = 'S'
  SET @o_vcErrorMessage = 'Process Completed'
  RETURN 1
END  
GO

CREATE PROCEDURE [dbo].[stpr_InsertUpdateXMLDropDown] @dsXml XML 
WITH ENCRYPTION
AS
BEGIN
  DECLARE @tbl_InputJSONTable DBO.tb_ParamList ;
  DECLARE @o_ParameterList varchar(max)='', @o_ParameterListxml XML; 
  DECLARE @tbl_UserList dbo.UserAccessList;
  
  
  EXEC SP_ParameterXMLRep @dsXml, @o_ParameterList OUTPUT
  
  IF ISNULL(@o_ParameterList,'') <> ''
  BEGIN
    SET @o_ParameterListxml = CAST(@o_ParameterList AS XML)
   
    INSERT INTO @tbl_InputJSONTable (ParameterName,  ParameterValue, HeaderName, Jsontag) 
    SELECT Parameter.value('(ColumnName)[1]', 'VARCHAR(MAX)') AS Client_Code ,
    Parameter.value('(ColumnValue)[1]', 'VARCHAR(MAX)') AS ColumnValue,
	Parameter.value('(MasterTag)[1]', 'VARCHAR(MAX)') AS MasterTag,
	Parameter.value('(JsonLevel)[1]', 'VARCHAR(MAX)') AS JsonLevel
    FROM @o_ParameterListxml.nodes('/Parameter') AS XTbl(Parameter)
  END 
  
  
     --- USER ACCESS RIGHTS
	 
  DECLARE @strUserid VARCHAR(500)='', @StrClientCode VARCHAR(50)='', @strString NVARCHAR(MAX)='',
  @strHeaderString VARCHAR(MAX)='', @strxml VARCHAR(MAX)= CAST(@dsXml AS VARCHAR(MAX))
  SELECT @strUserid = ParameterValue From @tbl_InputJSONTable where ParameterName = 'UserId'
   
  IF @StrClientCode <> ''
  BEGIN
    SET @strUserid = @StrClientCode
  END
  
  DECLARE @companyCount INT = 0, @strCompanyCode VARCHAR(3)=''
  SELECT @companyCount = ISNULL(SUM(ISNULL(cnt,0)),0)  
  FROM ( SELECT COUNT(0) Cnt From Entity_master with (NoLock) 
  WHERE em_bse <> 'N' and isNull(em_bclearingno,'') in ('189') 
  UNION ALL 
  SELECT COUNT(0) Cnt From Entity_master with (NoLock) 
  WHERE em_nse <> 'N' and isNull(em_nclearingno,'') in ('07277') ) a
	 
  IF @companyCount = 0
  BEGIN
	SELECT @strCompanyCode = em_cd 
	FROM Entity_Master with (nolock) where em_cd =(select min(em_cd) from Entity_master)
  END
  ELSE
  BEGIN
	SELECT @strCompanyCode = em_cd 
	FROM Entity_Master with (nolock) where em_cd = 'B'
  END
  
  SET @strHeaderString = 'DECLARE @tbl_UserList TABLE(CLIENTCODE VARCHAR(50)) '
  +' INSERT INTO @tbl_UserList '
  +' SELECT * FROM dbo.fn_GetClients('''+@strUserid+''','''','''')'
  
  DECLARE @strModuleName VARCHAR(100)='', @strOption VARCHAR(50)='', @strQuery NVARCHAR(MAX), @strQueryType VARCHAR(1)='Q',
  @o_vcFlag VARCHAR(1)='S', @o_vcMessage VARCHAR(MAX)='', @strUserCode1 VARCHAR(20)=''
  SELECT @strModuleName = ParameterValue FROM @tbl_InputJSONTable where ParameterName = 'ActionName'
  SELECT @strOption = ParameterValue FROM @tbl_InputJSONTable where ParameterName = 'Option'
  
  IF ISNULL(@strModuleName,'') <> ''
  BEGIN
    
    SELECT @strQuery = DBQuery, @strQueryType = DBQueryType, @strUserCode1 = UserCode 
	FROM tbl_InsertUpdateXMLDropDownQuery(NOLOCK) 
	WHERE ModuleName = @strModuleName AND ColumnName = @strOption
	
	SET @strQuery = REPLACE(@strQuery,'<<Userid>>',@strUserid)
	SET @strQuery = REPLACE(@strQuery,'<<CompanyCode>>',@strCompanyCode)
	
	IF CHARINDEX('##DPDATABASE##',@strQuery) >0
	BEGIN
	  DECLARE @strOP_DataBase VARCHAR(50), @strOP_Owner VARCHAR(50)
	
	  SELECT @strOP_DataBase = RTRIM(LTRIM(OP_DataBase)), 
	  @strOP_Owner = RTRIM(LTRIM(OP_Owner)) 
      FROM Other_Products(NOLOCK) 
      WHERE OP_Product = 'Cross' and OP_Status='A'
   
      IF ISNULL(@strOP_DataBase,'') = ''
      BEGIN
	    SELECT @strOP_DataBase = RTRIM(LTRIM(OP_DataBase)), 
	    @strOP_Owner = RTRIM(LTRIM(OP_Owner)) 
        FROM Other_Products(NOLOCK) 
        WHERE OP_Product = 'Estro' and OP_Status='A'
      END	
	  SET @strQuery = REPLACE(@strQuery,'##DPDATABASE##',  @strOP_DataBase)
      SET @strQuery = REPLACE(@strQuery,'##DPOWNER##',  @strOP_Owner)	  
	END  
	
	IF ISNULL(@strQuery,'') <> '' AND ISNULL(@strQueryType,'Q') = 'Q'
	BEGIN
	  IF @strUserid <> '' AND UPPER(@strQuery) LIKE '%CLIENT_MASTER%' AND @strUserCode1 <> 'X11'
	  BEGIN
	    SET @strString = @strHeaderString+' '+@strQuery 
	    SET @strString = @strString+' '+ ' AND EXISTS(SELECT 1 FROM @tbl_UserList WHERE ClientCode = CM_CD) '
	  END
	  ELSE
	  BEGIN
	    SET @strString = @strQuery 
	  END
	 -- SELECT @strString

	  --REPLACE CHANGES
	  
	  DECLARE @curParameterValue VARCHAR(MAX)='', @curParameterName VARCHAR(50)=''
	  IF CHARINDEX('<<FILTER>>', @strString) > 0
	  BEGIN
		SET @strString = REPLACE(@strString, '<<FILTER>>', (SELECT TOP 1 ParameterValue FROM @tbl_InputJSONTable where ParameterName = 'X_Filter' and HeaderName = 'X_Filter'))
	  END
	  
	  IF EXISTS(SELECT 1 FROM @tbl_InputJSONTable 
	  WHERE HeaderName = 'X_Filter_Multiple' AND ISNULL(ParameterValue,'') <> '')
	  BEGIN
	    DECLARE Cur12 CURSOR FOR 
        SELECT ParameterValue, ParameterName FROM @tbl_InputJSONTable 
	    WHERE HeaderName = 'X_Filter_Multiple' AND ISNULL(ParameterValue,'') <> ''
        OPEN Cur12 
        FETCH NEXT FROM Cur12 INTO @curParameterValue, @curParameterName
        WHILE @@FETCH_STATUS = 0
        BEGIN 
		  SET @strString = REPLACE(@strString,'<<'+@curParameterName+'>>',@curParameterValue)
		  FETCH NEXT FROM Cur12 INTO @curParameterValue, @curParameterName
        END 
        CLOSE Cur12 
        DEALLOCATE Cur12 
	  END
	  --select @strString
	  --END REPLACE CHANGES

	  EXEC(@strString)
	END
	ELSE IF ISNULL(@strQuery,'') <> '' AND ISNULL(@strQueryType,'Q') = 'P'
	BEGIN
	   SET @strString = 'EXEC DBO.' + @strQuery + ' ''' + @strxml + ''', @o_vcFlag OUTPUT, @o_vcMessage OUTPUT';
	   --SELECT @strString
	   BEGIN TRY
	     EXEC sp_executesql @strString, N'@o_vcFlag VARCHAR(1) OUTPUT, @o_vcMessage VARCHAR(500) OUTPUT', @o_vcFlag OUTPUT, @o_vcMessage OUTPUT;
	   END TRY
       BEGIN CATCH
	      SELECT '<Flag>E</Flag><Message>'+ERROR_MESSAGE()+'</Message>'
		  RETURN 1
       END CATCH	   
	   SELECT '<Flag>'+@o_vcFlag+'</Flag>'+@o_vcMessage
	   RETURN 1
	END
  END
END
GO

CREATE PROCEDURE [dbo].[stpr_TradeWebMenu] @dsXml AS XML = NULL 
WITH ENCRYPTION
AS
BEGIN

   DECLARE @tbl_Variable dbo.tb_ParamList;
   DECLARE @tbl_UserList dbo.UserAccessList;
   DECLARE @o_ParameterList varchar(max)='', @o_ParameterListxml XML;
   DECLARE @tb_ParamListDetail DBO.tb_ParamList ;
   
   --- PARAMETER LIST
   
   EXEC SP_ParameterXMLRep @dsXml, @o_ParameterList output
   IF ISNULL(@o_ParameterList,'') <> ''
   BEGIN
     SET @o_ParameterListxml = CAST(@o_ParameterList AS XML)
   
     INSERT INTO @tb_ParamListDetail (ParameterName,  ParameterValue, HeaderName)
     SELECT Parameter.value('(ColumnName)[1]', 'VARCHAR(MAX)') AS Client_Code ,
     Parameter.value('(ColumnValue)[1]', 'VARCHAR(MAX)') AS ColumnValue,
	 Parameter.value('(MasterTag)[1]', 'VARCHAR(MAX)') AS MasterTag
     FROM @o_ParameterListxml.nodes('/Parameter') AS XTbl(Parameter)
   END 

   DECLARE @strUserid VARCHAR(500)='', @strLevel INT = 0, @dtFromDate DATE, @dtToDate DATE,
   @StrClientCode VARCHAR(50)='', @strOption VARCHAR(50) = '', @strRequestFrom varchar(10)=''
   SELECT @strUserid = ParameterValue From @tb_ParamListDetail where ParameterName = 'UserId'
   SELECT @strOption = ParameterValue From @tb_ParamListDetail where ParameterName = 'Option'
   SELECT @strRequestFrom = ParameterValue From @tb_ParamListDetail where ParameterName = 'RequestFrom'

   IF @strOption = 'AccessRights'
   BEGIN
   
     Select ModuleId = ModuleCode, MenuName = MenuName, MenuCode = MenuCode, MenuTag = MenuTag, DenyRights = DenyRights, 
     TargetForm = TargetForm, [Path] = [Path],
     [Enable] = CASE [Enable] WHEN 'Y' then 'true' else 'false' end, 
     [Add] = CASE SUBSTRING(Rights, 1, 1) WHEN 'Y' then 'true' else 'false' end, 
     [Edit] = CASE SUBSTRING(Rights, 2, 1) WHEN 'Y' then 'true' else 'false' end, 
     [Delete] = CASE SUBSTRING(Rights, 3, 1) WHEN 'Y' then 'true' else 'false' end, 
     [View] = CASE SUBSTRING(Rights, 4, 1) WHEN 'Y' then 'true' else 'false' end
     FROM tbl_TradeWebMenu(NOLOCK) WHERE MenuType = 'C'
	 AND isnull(Enable,'N') = 'Y'
     AND ((Productid in('','T') AND @strRequestFrom = 'W') OR (Productid in('','M') AND @strRequestFrom = 'M'))
     ORDER BY MenuType, CAST(SrNo AS INT)
   RETURN
   END
   ELSE IF @strOption = 'Routes'
   BEGIN
     Select [name] = MenuName, [path] = [Path], element = MenuTag from tbl_TradeWebMenu(NOLOCK)
     WHERE ((Productid in('','T') AND @strRequestFrom = 'W') OR (Productid in('','M') AND @strRequestFrom = 'M'))
	 AND isnull(Enable,'N') = 'Y'
     ORDER BY  CAST(SrNo AS INT)
     return
   END
   ELSE IF @strOption = 'List'
   BEGIN
     SELECT ModuleCode as 'id', MenuName as 'title', '' as 'path', '' as 'icon',
     submenu=(Select REPLACE((select ModuleCode as 'id', MenuName as 'title', [Path] as 'path', '' as 'icon' 
     FROM tbl_TradeWebMenu(NOLOCK) b WHERE b.ParentMenu=a.MenuName 
     AND ((Productid in('','T') AND @strRequestFrom = 'W') OR (Productid in('','M') AND @strRequestFrom = 'M'))
	 AND isnull(Enable,'N') = 'Y'
     ORDER BY  CAST(SrNo AS INT)
     FOR JSON PATH),'\\',''))
     FROM tbl_TradeWebMenu(NOLOCK) a 
     WHERE a.MenuType = 'P' 
     AND ((Productid in('','T') AND @strRequestFrom = 'W') OR (Productid in('','M') AND @strRequestFrom = 'M'))
	  AND isnull(Enable,'N') = 'Y'
     ORDER BY CAST(SrNo AS INT)
   END
END 
GO

CREATE PROCEDURE stpr_APIFundsPayout @dsXml VARCHAR(MAX)
WITH ENCRYPTION  
AS
BEGIN
  DECLARE @o_vcErrorFlag VARCHAR(1)='', @o_vcErrorMessage VARCHAR(MAX)='',
  @strActionName VARCHAR(50), @strOption VARCHAR(50),@strUserid VARCHAR(50)='', 
  @strRequestFrom VARCHAR(1), @strCompanyCode VARCHAR(1), @strLevel VARCHAR(1)='1',
  @StrRMSAmount MONEY = 0, @strBranchPayout MONEY = 0, @strClientCode VARCHAR(20)=''
  
  DECLARE @tbl_InputJSONTable DBO.tb_ParamList ;
  DECLARE @o_ParameterList varchar(max)='', @o_ParameterListxml XML; 
  DECLARE @tbl_UserList dbo.UserAccessList;
  
  EXEC SP_ParameterXMLRep @dsXml, @o_ParameterList OUTPUT
  
  IF ISNULL(@o_ParameterList,'') <> ''
  BEGIN
	 SET @o_ParameterListxml = CAST(@o_ParameterList AS XML)
     INSERT INTO @tbl_InputJSONTable (ParameterName,  ParameterValue, HeaderName, Jsontag) 
     SELECT Parameter.value('(ColumnName)[1]', 'VARCHAR(MAX)') AS Client_Code ,
     Parameter.value('(ColumnValue)[1]', 'VARCHAR(MAX)') AS ColumnValue,
	 Parameter.value('(MasterTag)[1]', 'VARCHAR(MAX)') AS MasterTag,
	 Parameter.value('(JsonLevel)[1]', 'VARCHAR(MAX)') AS JsonLevel
     FROM @o_ParameterListxml.nodes('/Parameter') AS XTbl(Parameter)
  END
 
  SELECT @strActionName = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'ActionName'
  SELECT @strOption = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Option'
  
  SELECT @strRequestFrom = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'RequestFrom'
  SELECT @strLevel = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Level'
  SELECT TOP 1 @strUserid = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Userid' 
  SELECT @strClientCode = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'ClientCode'
  
  IF @strActionName = 'Tradeweb' AND @strOption = 'FundRequest'
  BEGIN
    DECLARE @userla_Group VARCHAR(1)=''
	
    SELECT @userla_Group = LA_grouping from LoginAccess(NOLOCK) 
    WHERE LA_UserId = @strUserid

  
    DECLARE @tb_clientFundPayout TABLE(ClientCode VARCHAR(50), ClientName VARCHAR(200),
    RMSAmount MONEY, LedgerAmount MONEY, RequestedAmount MONEY, RMSTAG VARCHAR(1))
  
  
    IF ISNULL(@userla_Group,'') <> 'A'
    BEGIN
	  
	  INSERT INTO @tbl_UserList(ClientCode) 
      SELECT * FROM DBO.[fn_GetClients](@strUserId,'C',@strClientCode)
	
	  INSERT INTO @tb_clientFundPayout(ClientCode, ClientName, LedgerAmount, RMSAmount, RequestedAmount)
	  SELECT CM_cD, CM_NAME, LedgerAmount = CAST((-1*sum(ld_amount)) AS DECIMAL(15,2)), 0, 0
	  FROM CLIENT_MASTER(NOLOCK), Ledger(NOLOCK), @tbl_UserList X
	  WHERE CM_cD = ld_clientcd
	  AND cm_schedule = '49843750'
	  AND ld_clientcd = ClientCode
	  --AND CM_cD IN('BA007','BA090','BA1032','BA1088')
	  GROUP BY CM_cD, CM_NAME
	  HAVING abs(sum(ld_amount)) > 0
	
    END
    ELSE 
    BEGIN
      INSERT INTO @tb_clientFundPayout(ClientCode, ClientName, LedgerAmount, RMSAmount, RequestedAmount)
	  SELECT CM_cD, CM_NAME, LedgerAmount = CAST((-1*sum(ld_amount)) AS DECIMAL(15,2)), 0, 0 
	  FROM CLIENT_MASTER(NOLOCK), Ledger(NOLOCK)
	  WHERE CM_cD = ld_clientcd
	  AND cm_schedule = '49843750'
	  AND ((CM_CD = @strClientCode AND ISNULL(@strClientCode,'') <> '') OR ISNULL(@strClientCode,'') = '')
	  --AND CM_cD IN('BA007','BA090','BA1032','BA1088')
	  GROUP BY CM_cD, CM_NAME
	  HAVING abs(sum(ld_amount)) > 0
    END  
  
    
	IF EXISTS(SELECT 1 FROM Sysparameter(NOLOCK) WHERE sp_parmcd Like 'RMSHEAD%' AND sp_sysvalue = 'FUNDPAYOUT')
    BEGIN
      UPDATE A SET A.RMSAmount = B.RMSAmount, A.RMSTAG = 'Y'
	  FROM @tb_clientFundPayout A, 
	  (SELECT rs_clientcd, RMSAmount = ISNULL(CAST((-1 * sum(rs_fundpayout)) as decimal(15,2)),0)
      FROM Rms_summary(NOLOCK)
      WHERE rs_Dt = (select MAX(rs_Dt) From RMS_Summary(NOLOCK))
	  GROUP BY rs_clientcd) B  
	  WHERE A.ClientCode = B.rs_clientcd
    END
    
	UPDATE A SET A.LedgerAmount = B.LedgerAmount
	FROM @tb_clientFundPayout A, 
	(SELECT ld_clientcd, LedgerAmount = CAST((-1*sum(ld_amount)) AS DECIMAL(15,2))
     FROM Ledger(NOLOCK)
     GROUP BY ld_clientcd
	HAVING abs(sum(ld_amount)) > 0) B  
	WHERE A.ClientCode = B.ld_clientcd
	
	UPDATE A SET A.RequestedAmount = B.RequestedAmount
	FROM @tb_clientFundPayout A, 
	(SELECT rq_clientcd, RequestedAmount = ISNULL(CAST(SUM(Rq_Amount) AS DECIMAL(15,2)),0) 
    FROM FundsRequest(NOLOCK) WHERE RQ_SATUS1 = 'P'
    GROUP BY rq_clientcd) B  
	WHERE A.ClientCode = B.rq_clientcd
	
	IF @strRequestFrom = 'M'
	BEGIN
	  SELECT [Amount] = CASE WHEN ISNULL(RMSTAG,'N') ='Y' AND ISNULL(RMSAmount,0) < 0 THEN 0
	  WHEN ISNULL(RMSTAG,'N') = 'Y' AND ISNULL(RMSAmount,0) > 0 AND ISNULL(LedgerAmount,0) < 0 THEN 0
	  WHEN ISNULL(RMSTAG,'N') = 'Y' AND ISNULL(RMSAmount,0) < ISNULL(LedgerAmount,0) AND ISNULL(LedgerAmount,0) > 0 
	  AND ISNULL(RMSAmount,0) > 0 THEN ISNULL(RMSAmount,0) WHEN ISNULL(RMSTAG,'N') ='N' THEN ISNULL(LedgerAmount,0)
	  ELSE ISNULL(LedgerAmount,0) END, 
	  [Text] = CASE WHEN ISNULL(RMSTAG,'N') ='Y' THEN 'Max Payable Amount(Ledger/RMS Amount)'
	  ELSE 'Max Payable Amount(Ledger)' END, [RequestedAmount] = ISNULL(RequestedAmount,0), [CheckRMSAmountFlag] = ISNULL(RMStag,'N')
	  FROM @tb_clientFundPayout
	  where CASE WHEN ISNULL(RMSTAG,'N') ='Y' AND ISNULL(RMSAmount,0) < 0 THEN 0
	  WHEN ISNULL(RMSTAG,'N') = 'Y' AND ISNULL(RMSAmount,0) > 0 AND ISNULL(LedgerAmount,0) < 0 THEN 0
	  WHEN ISNULL(RMSTAG,'N') = 'Y' AND ISNULL(RMSAmount,0) < ISNULL(LedgerAmount,0) AND ISNULL(LedgerAmount,0) > 0 
	  AND ISNULL(RMSAmount,0) > 0 THEN ISNULL(RMSAmount,0) WHEN ISNULL(RMSTAG,'N') ='N' THEN ISNULL(LedgerAmount,0)
	  ELSE ISNULL(LedgerAmount,0) END > 0
	END
    ELSE
    BEGIN
	  SELECT * FROM(
	  SELECT ClientCode, ClientName, PayableAmount = CASE WHEN ISNULL(RMSTAG,'N') ='Y' AND ISNULL(RMSAmount,0) < 0 THEN 0
	  WHEN ISNULL(RMSTAG,'N') = 'Y' AND ISNULL(RMSAmount,0) > 0 AND ISNULL(LedgerAmount,0) < 0 THEN 0
	  WHEN ISNULL(RMSTAG,'N') = 'Y' AND ISNULL(RMSAmount,0) < ISNULL(LedgerAmount,0) AND ISNULL(LedgerAmount,0) > 0 
	  AND ISNULL(RMSAmount,0) > 0 THEN ISNULL(RMSAmount,0) WHEN ISNULL(RMSTAG,'N') ='N' THEN ISNULL(LedgerAmount,0)
	  ELSE ISNULL(LedgerAmount,0) END, [RequestedAmount] = ISNULL(RequestedAmount,0)--, [Selection] = '', [Client] = ''
	  FROM @tb_clientFundPayout) X1
	  WHERE ISNULL(X1.PayableAmount,0) > 0
    END 	
	 /* 
	
	DECLARE @strPayoutAmount MONEY = 0 
	IF ISNULL(@RMStag,'N') = 'Y'
	BEGIN
	  
	  IF @StrRMSAmount < 0  
	  BEGIN
	    SELECT [Amount] = 0, [Text] = 'Max Payable Amount(Ledger/RMS Amount)', [RequestedAmount] = @strAllreadyRequest, [CheckRMSAmountFlag] = @RMStag
	  END
	  ELSE 
	  IF @StrRMSAmount > 0 AND @StrLedgerAmt <= 0 
	  BEGIN
	    SELECT [Amount] = 0, [Text] = 'Max Payable Amount(Ledger/RMS Amount)', [RequestedAmount] = @strAllreadyRequest, [CheckRMSAmountFlag] = @RMStag
	  END
	  ELSE IF @StrRMSAmount < @StrLedgerAmt AND @StrLedgerAmt > 0 AND @StrRMSAmount > 0
	  BEGIN
	    SELECT [Amount] = @StrRMSAmount, [Text] = 'Max Payable Amount(Ledger/RMS Amount)', [RequestedAmount] = @strAllreadyRequest, [CheckRMSAmountFlag] = @RMStag
	  END
	  ELSE
      BEGIN
	    SELECT [Amount] = @StrLedgerAmt, [Text] = 'Max Payable Amount(Ledger/RMS Amount)', [RequestedAmount] = @strAllreadyRequest, [CheckRMSAmountFlag] = @RMStag
      END 	  
	END
    ELSE
    BEGIN
	   SELECT [Amount] = @StrLedgerAmt, [Text] =  'Max Payable Amount(Ledger)', [RequestedAmount] = @strAllreadyRequest, [CheckRMSAmountFlag] = @RMStag
    END  
    */	
	
  END
END	 
GO

CREATE PROCEDURE [stpr_GenericInsertUpdateTable] @xmlInput VARCHAR(MAX), @strTableName VARCHAR(100), @i_vcmode VARCHAR(10),
@i_vcUserCode VARCHAR(50), @strPrimaryKeyName VARCHAR(200), @o_iReturnMainSlNo INT OUTPUT,   
  @o_vcFlag VARCHAR(1) OUTPUT,   
  @o_vcMessage VARCHAR(1000) OUTPUT 
WITH ENCRYPTION  
AS
BEGIN

  DECLARE @XMLDATA1 XML = CAST(@xmlInput AS XML)
  DECLARE @tbl_InputJSONTable DBO.tb_ParamList ;
  
  declare @loginsertno INT=0
  
  DELETE FROM  @tbl_InputJSONTable 
  
  INSERT INTO @tbl_InputJSONTable (ParameterName,  ParameterValue, HeaderName) 
  SELECT DATA1.value('(ParameterName)[1]', 'VARCHAR(MAX)') AS Client_Code ,
  LTRIM(RTRIM(ISNULL(DATA1.value('(ParameterValue)[1]', 'VARCHAR(MAX)'),''))) AS ColumnValue,
  ISNULL(DATA1.value('(HeaderName)[1]', 'VARCHAR(MAX)'),'') AS MasterTag
  FROM @XMLDATA1.nodes('/DATA1') AS XTbl(DATA1)
  
  IF EXISTS(SELECT 1 FROM @tbl_InputJSONTable WHERE ParameterName = 'IsInserted' AND ParameterValue = 'true')
  BEGIN
    SET @i_vcmode = 'add'
  END

  DECLARE @iPrimaryTableColumnExists INT = 0,    
   @iColumnID INT = 0, 
   @strColumnDataType VARCHAR(20), @iColumnDataLength INT = 0, @strMainColumnvalue NVARCHAR(MAX),    
   @strInsertStringValue NVARCHAR(MAX) = '', @strInsertStringHeader NVARCHAR(MAX) = '',     
   @strUpdateStringValue NVARCHAR(MAX)='', @strMainString NVARCHAR(MAX) ='',    
   @iReturnSerialNo INT = 0, @strIdentityColumnName VARCHAR(50)='',  
   @i_vcColumnList NVARCHAR(MAX) = '',   
   @i_vcColumnValueList NVARCHAR(MAX) = '', @strColumnName NVARCHAR(MAX) = '', 
   @strColumnValue NVARCHAR(MAX) = '',  @strTempColumnName NVARCHAR(MAX) = '', @strTempColumnValue NVARCHAR(MAX) = ''
  
  IF @strTableName <> ''
  BEGIN
    DECLARE @tbl_PrimaryKey TABLE(KeyName VARCHAR(100), KeyValue VARCHAR(100))
	
	    
	IF @i_vcmode <> 'add' and @i_vcmode <> ''
	BEGIN
	  --SELECT @strPrimaryKeyName
      INSERT INTO @tbl_PrimaryKey(KeyName)
	  SELECT VALUE FROM DBO.RETURNTABLE(@strPrimaryKeyName,'|')
	  	 
      UPDATE A SET A.KeyValue = B.ParameterValue
      FROM @tbl_PrimaryKey A, @tbl_InputJSONTable B
      WHERE A.KeyName = B.ParameterName	
      
	  DECLARE @strwhere VARCHAR(MAX)=''
      SELECT @strwhere = @strwhere+' '+ ' AND '+KeyName+' = '''+CAST(KeyValue AS VARCHAR)+''''
      FROM  @tbl_PrimaryKey		 

	  DELETE FROM @tbl_InputJSONTable WHERE ParameterName in(select KeyName from @tbl_PrimaryKey)
	  
	  IF ISNULL(@strPrimaryKeyName,'') = '' OR ISNULL(@strwhere,'') = ''
	  BEGIN
	    SET @o_vcFlag = 'F'  
        SET @o_vcMessage = '<Message>'+'Unique Key not Define in Master Table'
		RETURN 1
	  END

    END
 
    DECLARE CURSOR_BIND CURSOR FOR  
    SELECT ParameterName, ParameterValue = LTRIM(RTRIM(IIF(ParameterValue='',' ',ParameterValue)))   
    FROM @tbl_InputJSONTable
	
  
    OPEN CURSOR_BIND   
    FETCH NEXT FROM CURSOR_BIND INTO @strTempColumnName, @strTempColumnValue  
    WHILE @@FETCH_STATUS = 0   
    BEGIN  
      IF @strColumnName <> ''  
      BEGIN  
        SET @strColumnName = @strColumnName+'|'+@strTempColumnName  
        SET @strColumnValue = @strColumnValue+'|'+@strTempColumnValue  
      END  
      ELSE IF @strColumnName = ''  
      BEGIN  
        SET @strColumnName = @strTempColumnName  
        SET @strColumnValue = @strTempColumnValue  
      END  
      FETCH NEXT FROM CURSOR_BIND INTO @strTempColumnName, @strTempColumnValue  
    END   
    CLOSE CURSOR_BIND   
    DEALLOCATE CURSOR_BIND   

    DECLARE @sColumn_Name VARCHAR(100)='', @sdata_type VARCHAR(20)=''
	DECLARE Cur31Main
    CURSOR FOR SELECT Column_Name, data_type FROM INFORMATION_SCHEMA.COLUMNS 
	WHERE TABLE_NAME = @strTableName
	AND column_name NOT IN(SELECT ParameterName FROM @tbl_InputJSONTable)
	AND column_name NOT IN(SELECT KeyName FROM @tbl_PrimaryKey)
	AND column_name NOT IN (select COLUMN_NAME from( SELECT COLUMN_NAME, 
    COLUMNPROPERTY(OBJECT_ID(TABLE_SCHEMA + '.' + TABLE_NAME), COLUMN_NAME, 'IsIdentity') AS IsIdentity
    FROM INFORMATION_SCHEMA.COLUMNS
    WHERE TABLE_NAME = @strTableName) x1 where IsIdentity =  1)

    OPEN Cur31Main 
    FETCH NEXT FROM Cur31Main INTO @sColumn_Name, @sdata_type  
    WHILE @@FETCH_STATUS = 0
    BEGIN 
      IF EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = @strTableName 
	  and COLUMN_NAME = @sColumn_Name) 
      BEGIN
        SET @strColumnName = @strColumnName +'|'+@sColumn_Name
        SET @strColumnValue = @strColumnValue +'|'+CAST((CASE WHEN @sdata_type IN('int','money','numeric') THEN '0' ELSE '' END) AS VARCHAR)
      END
      FETCH NEXT FROM Cur31Main INTO @sColumn_Name, @sdata_type  
    END
    CLOSE Cur31Main
    DEALLOCATE Cur31Main
	
    IF @strColumnValue = ''  
    BEGIN  
      SET @o_vcFlag ='F'    
      SET @o_vcMessage = '<Message>'+@o_vcMessage+'</Message>'
      RETURN 1    
    END  
    
	SET @i_vcColumnList = @strColumnName   
    SET @i_vcColumnValueList = @strColumnValue    
	
	SET @o_vcFlag =''    
    SET @o_vcMessage =''    
    SET @strMainString = ''   
	
	DECLARE @strCompCode VARCHAR(1), @strUsercode VARCHAR(10)=''
	SELECT @strCompCode = em_cd from Entity_Master with (nolock) 
	WHERE em_cd =(select min(em_cd) from Entity_master)
	
	SELECT TOP 1 @strUsercode = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Userid' 
	
	SET @i_vcColumnValueList = REPLACE(@i_vcColumnValueList,'##COMP##',@strCompCode)
	SET @i_vcColumnValueList = REPLACE(@i_vcColumnValueList,'##USERID##',@strUsercode)
	
	-------- VAIBHAV
	
	
	DECLARE CURSOR_TABLE_COLUMNS CURSOR FOR           
    SELECT  Position, ColumnName = Value FROM dbo.fn_SplitString(@i_vcColumnList,'|')     
    WHERE VALUE NOT IN ('UpdateTimeStamp', 'UserCode','mkrid','mkrdt','CreatedDate')  
    ORDER BY Position    
  
    OPEN CURSOR_TABLE_COLUMNS     
    FETCH NEXT FROM CURSOR_TABLE_COLUMNS INTO @iColumnID, @strColumnName    
    WHILE @@FETCH_STATUS = 0   
    BEGIN     
      SET @strColumnDataType = ''    
      SET @iColumnDataLength = ''    
      SET @strMainColumnvalue = ''    
      SET @iPrimaryTableColumnExists= 0    
         
      SELECT @strMainColumnValue = VALUE FROM dbo.fn_SplitString(@i_vcColumnValueList,'|')   
      WHERE Position = @iColumnID   
    
      IF @iColumnID > 0    
      BEGIN    
        SELECT @iPrimaryTableColumnExists = 1, @strColumnDataType = DATA_TYPE,   
        @iColumnDataLength = CHARACTER_MAXIMUM_LENGTH  
        FROM INFORMATION_SCHEMA.COLUMNS   
        WHERE TABLE_NAME = @strTableName    
        AND COLUMN_NAME = @strColumnName    
    
        IF @strColumnDataType <> 'VARBINARY'  
        BEGIN  
          IF @iPrimaryTableColumnExists > 0  
          BEGIN  
            SET @strInsertStringHeader = @strInsertStringHeader + @strColumnName+','  
          END  
        END  
        
		--Checking the Column Data Type For VARCHAR/NVARCHAR/CHAR,   
      
        IF @strColumnDataType IN ('VARCHAR', 'CHAR','NVARCHAR')   
        BEGIN   
          IF LEN(@strMainColumnvalue) > @iColumnDataLength AND @iColumnDataLength <> -1   
          BEGIN  
            SET @o_vcFlag = 'F'  
            SET @o_vcMessage = '<Message>'+'Column: '+@strColumnName+' Data Length is more than the Table Column Length'+'</Message>'  
            CLOSE CURSOR_TABLE_COLUMNS      
            DEALLOCATE CURSOR_TABLE_COLUMNS     
            RETURN 1    
          END    
          IF @iPrimaryTableColumnExists > 0    
          BEGIN    
            SET @strInsertStringValue = @strInsertStringValue     
            + ''''+@strMainColumnvalue+''''+','    
            SET @strUpdateStringValue = @strUpdateStringValue      
            + @strColumnName+' = '+''''+@strMainColumnvalue+''''+','    
          END    
        END       
        ELSE    
        --Checking the Column Data Type For DATETIME/DATE,   
        -- then Preparing the Insert/Update String accordingly  
        IF @strColumnDataType IN ('DATETIME', 'DATE')    
        BEGIN    
          IF @strMainColumnvalue IN ('','0')    
          BEGIN    
            SET @strMainColumnvalue = '01-JAN-1900' 
		  END    
          IF ISDATE(@strMainColumnvalue) = 0 --If it Returns 1- Valid Date , 0 - invalid date    
          BEGIN    
            SET @o_vcFlag ='F'    
            SET @o_vcMessage = '<Message>'+'Column: '+ @strColumnName+' Value ' +      
           @strMainColumnvalue+ ' Is Not a Valid Date.'+'</Message>'  
            CLOSE CURSOR_TABLE_COLUMNS      
            DEALLOCATE CURSOR_TABLE_COLUMNS     
            RETURN 1    
          END    
          IF @iPrimaryTableColumnExists > 0    
          BEGIN   
         SET @strInsertStringValue =  @strInsertStringValue     
              + ''''+@strMainColumnvalue+''''+','    
            SET @strUpdateStringValue = @strUpdateStringValue      
            + @strColumnName+' = '+''''+@strMainColumnvalue+''''+','    
          END    
        END     
        ELSE  
        --Checking the Column Data Type Other than   
        -- VARBINARY/VARCHAR/CHAR/DATETIME/DATE   
        -- then Preparing the Insert/Update String accordingly  
        IF @strColumnDataType NOT IN ('VARBINARY', 'VARCHAR', 'CHAR', 'DATETIME', 'DATE')   
        BEGIN    
          IF ISNULL(@strMainColumnvalue,'0') = ''     
          BEGIN    
            SET @strMainColumnvalue = '0'    
          END    
          IF @iPrimaryTableColumnExists > 0    
          BEGIN    
            SET @strInsertStringValue =  @strInsertStringValue + @strMainColumnvalue+','    
            SET @strUpdateStringValue = @strUpdateStringValue      
            + @strColumnName+' = '+ @strMainColumnvalue+','    
          END    
        END     
      END    
      FETCH NEXT FROM CURSOR_TABLE_COLUMNS INTO @iColumnID, @strColumnName    
    END      
    CLOSE CURSOR_TABLE_COLUMNS      
    DEALLOCATE CURSOR_TABLE_COLUMNS  


    IF EXISTS(SELECT 1 from INFORMATION_SCHEMA.COLUMNS   
        WHERE TABLE_NAME = @strTableName    
        AND COLUMN_NAME IN('mkrid','mkrdt'))
	BEGIN	
      SET @strInsertStringHeader = @strInsertStringHeader + ' mkrid, mkrdt '    
      SET @strInsertStringValue = @strInsertStringValue   
      +  ''''+@i_vcUserCode+''''+' , '+''''+CONVERT(VARCHAR,GETDATE(),112)+''''+' '    
    END
	ELSE IF EXISTS(SELECT 1 from INFORMATION_SCHEMA.COLUMNS   
        WHERE TABLE_NAME = @strTableName    
        AND COLUMN_NAME IN('UserCode','UpdateTimeStamp'))
	BEGIN
	  SET @strInsertStringHeader = @strInsertStringHeader + ' UserCode, UpdateTimeStamp '    
      SET @strInsertStringValue = @strInsertStringValue   
      +  ''''+@i_vcUserCode+''''+' , '+''''+CAST(GETDATE() AS VARCHAR)+''''+' '   
	END
	ELSE
	BEGIN
	  SET @strInsertStringHeader = @strInsertStringHeader + ' CreatedDate '    
      SET @strInsertStringValue = @strInsertStringValue +''''+CONVERT(VARCHAR,GETDATE(),112)+''''+' '   
	END
    
	IF @i_vcmode = 'add'
	BEGIN
	  SET @strMainString = ''  
  
      SET @strMainString = 'INSERT INTO ' +@strTableName+'('  
      +@strInsertStringHeader +') VALUES ( '+@strInsertStringValue+' )'    
      BEGIN TRY  
	    
		INSERT INTO tbl_GenericAPIDebugLog(ParentSerialNo, RequestSource, RequestUniqueID, RequestString, ResponseString, ExceptionMessage, UpdateBy, UpdateTimeStamp)
        VALUES(0,@strTableName, 'Insert',@strMainString, '','SP Execute',@i_vcUserCode,GETDATE())	  
		SELECT @loginsertno =  IDENT_CURRENT('tbl_GenericAPIDebugLog')  
		
        EXEC(@strMainString)     
		
		UPDATE A SET ResponseString = 'Record Inserted'
		FROM tbl_GenericAPIDebugLog A
		WHERE A.SerialNo = @loginsertno
		
        SELECT @iReturnSerialNo =  IDENT_CURRENT(@strTableName)    
		SET @o_iReturnMainSlNo = ISNULL(@iReturnSerialNo,0)
      END TRY    
      BEGIN CATCH    
	    UPDATE A SET ResponseString = ERROR_MESSAGE()
		FROM tbl_GenericAPIDebugLog A
		WHERE A.SerialNo = @loginsertno
		
        SET @o_vcFlag ='F'    
        SET @o_vcMessage ='<Message>'+'Insertion Failed: '+ERROR_MESSAGE()+'</Message>'
        RETURN 1    
      END CATCH    
	END
	ELSE IF @i_vcmode <> 'add' AND @i_vcmode <> ''
	BEGIN
	   IF @strPrimaryKeyName <> ''
	   BEGIN
	     IF EXISTS(SELECT 1 FROM @tbl_InputJSONTable WHERE ParameterName = 'IsDeleted' AND ParameterValue = 'true')
		 BEGIN
		   SET @strMainString = 'DELETE FROM '+@strTableName  + ' WHERE 1 = 1 '+@strwhere  
		   --SELECT @strMainString
		 END
		 ELSE
		 BEGIN
		   IF EXISTS(SELECT 1 from INFORMATION_SCHEMA.COLUMNS   
           WHERE TABLE_NAME = @strTableName    
           AND COLUMN_NAME IN('mkrid','mkrdt'))
		   BEGIN
	         SET @strMainString = 'UPDATE '+@strTableName   
             +' SET '+@strUpdateStringValue+ ' mkrid= '''  
             + @i_vcUserCode+''', mkrdt = '''+CONVERT(VARCHAR,GETDATE(),112)+''' '    
             + ' WHERE 1 = 1 '+@strwhere    
		   END	  
		   ELSE IF EXISTS(SELECT 1 from INFORMATION_SCHEMA.COLUMNS   
           WHERE TABLE_NAME = @strTableName    
            AND COLUMN_NAME IN('UserCode','UpdateTimeStamp'))
		   BEGIN
		     SET @strMainString = 'UPDATE '+@strTableName   
             +' SET '+@strUpdateStringValue+ ' UserCode= '''  
             + @i_vcUserCode+''', UpdateTimeStamp = '''+CAST(GETDATE() AS VARCHAR)+''' '     
             + ' WHERE 1 = 1 '+@strwhere    
		   END
		   ELSE
		   BEGIN
		     SET @strMainString = 'UPDATE '+@strTableName   
             +' SET '+@strUpdateStringValue+ ' CreatedDate = '''+CONVERT(VARCHAR,GETDATE(),112)+''' '     
             + ' WHERE 1 = 1 '+@strwhere    
		   END
		 END   
         BEGIN TRY  
		  --SELECT @strMainString, @strTableName, @strUpdateStringValue, @i_vcUserCode, @strwhere
		  
		   INSERT INTO tbl_GenericAPIDebugLog(ParentSerialNo, RequestSource, RequestUniqueID, RequestString, ResponseString, ExceptionMessage, UpdateBy, UpdateTimeStamp)
           VALUES(0,@strTableName, @i_vcmode,@strMainString, '','SP Execute',@i_vcUserCode,GETDATE())	  
		   SELECT @loginsertno =  IDENT_CURRENT('tbl_GenericAPIDebugLog')  
		  
           EXEC(@strMainString)   

           UPDATE A SET ResponseString = 'Record Inserted'
		   FROM tbl_GenericAPIDebugLog A
		   WHERE A.SerialNo = @loginsertno
		
		   
           SELECT @iReturnSerialNo = 0    
         END TRY    
         BEGIN CATCH    
		   UPDATE A SET ResponseString = ERROR_MESSAGE()
		   FROM tbl_GenericAPIDebugLog A
		   WHERE A.SerialNo = @loginsertno
		
           SET @o_vcFlag ='F'    
           SET @o_vcMessage ='<Message>'+'UPDATE '+ERROR_MESSAGE()+'</Message>'    
           RETURN 1    
         END CATCH    
	   END   
       ELSE
       BEGIN
	     SET @o_vcFlag ='F'    
         SET @o_vcMessage ='<Message>'+'Primary key not define'+'</Message>'    
         RETURN 1    
       END	   
	END
	
	IF ISNULL(@o_iReturnMainSlNo,0)  = 0
	BEGIN
	
	  DECLARE @strMasterAutoGenColumnName VARCHAR(100)='' 
      SELECT top 1 @strMasterAutoGenColumnName = MasterAutoGenColumnName 
      FROM tbl_InsertUpdateConfig(NOLOCK)
      WHERE MasterTableName = @strTableName 
	  
	  IF ISNULL(@strMasterAutoGenColumnName,'') = ''
	  BEGIN
	    SELECT top 1 @strMasterAutoGenColumnName = DetailAutoGenColumnName
        FROM tbl_InsertUpdateConfig(NOLOCK)
        WHERE detailTableName = @strTableName
	  END	
	  
	  IF ISNULL(@strMasterAutoGenColumnName,'') = ''
	  BEGIN
	    SELECT top 1 @strMasterAutoGenColumnName = MasterAutoGenColumnName
        FROM tbl_InsertUpdateConfig(NOLOCK)
        WHERE detailTableName = @strTableName
	  END
	  
	  --SELECT @strMasterAutoGenColumnName, @strTableName
 	  SELECT @o_iReturnMainSlNo = ParameterValue 
	  FROM @tbl_InputJSONTable WHERE ParameterName = @strMasterAutoGenColumnName
	  
	END
	
	SET @o_vcFlag ='S'    
	IF @i_vcmode = 'add'
	BEGIN
      SET @o_vcMessage ='<Message>'+'Inserted into '+@strTableName+'</Message>'
	END
    ELSE
    BEGIN
	  SET @o_vcMessage ='<Message>'+'Update Data into '+@strTableName+'</Message>'
    END  	
    RETURN 1    
  END
  ELSE 
  BEGIN
   SET @o_vcFlag ='F'    
   SET @o_vcMessage ='<Message>'+'Table Name not found'+'</Message>'
   RETURN 1   
  END
END
GO

CREATE PROCEDURE stpr_GenerateAPIMailAlerts @vcProcess VARCHAR(50), @i_vcAPICallingUrl VARCHAR(100), @strSubjectAddon VARCHAR(100), @StrBodyText1 VARCHAR(MAX), 
@strRequest VARCHAR(MAX), @strResponse VARCHAR(MAX) WITH ENCRYPTION AS
BEGIN
  DECLARE @i_vcInputJsonEMAIL VARCHAR(MAX)='', @o_vcOutputJsonEMAIL VARCHAR(MAX)='',
  @strToEmailid VARCHAR(MAX) = '', @strBCCEMailid VARCHAR(MAX)='', @i_MainInputJsonEMAIL VARCHAR(MAX)='', @strSubject VARCHAR(MAX)='',
  @strCCEMailid VARCHAR(200), @StrBodyText VARCHAR(MAX)=''
  
  SET @i_MainInputJsonEMAIL = '{"reqestName":"Email","requestObject":{"ToEmailId":"##ToEmailId##","CCEmailId":"##CCEmailId##","BCCEmailId":"##BCCEmailId##",
  "Subject":"##Subject##","Body":"##Body##","Attachment":[]}}'
  SET @o_vcOutputJsonEMAIL = ''
      
  SELECT @StrBodyText = BodyText, @strToEmailid = CCEmail, 
  @strBCCEMailid = BCCEmailid, @strSubject = EmailSubject
  FROM tbl_EmailTemplate(NOLOCK) WHERE RefName = @vcProcess
  
  SET @strSubject = @strSubject+' '+ISNULL(@strSubjectAddon,'')
  
  DECLARE @o_vcOutputJson1 VARCHAR(MAX)=''
  IF @strToEmailid <> '' 
  BEGIN 
	SET  @i_vcInputJsonEMAIL = @i_MainInputJsonEMAIL
	SET  @StrBodyText = REPLACE(@StrBodyText,'<<Request>>', REPLACE(ISNULL(@strRequest,''),'"',''))
	SET  @StrBodyText = REPLACE(@StrBodyText,'<<Response>>', REPLACE(ISNULL(@strResponse,''),'"',''))
 	SET  @i_vcInputJsonEMAIL = REPLACE(@i_vcInputJsonEMAIL,'##ToEmailId##',ISNULL(@strToEmailid,''))
    SET  @i_vcInputJsonEMAIL = REPLACE(@i_vcInputJsonEMAIL,'##CCEmailId##',ISNULL(@strCCEMailid,''))
    SET  @i_vcInputJsonEMAIL = REPLACE(@i_vcInputJsonEMAIL,'##BCCEmailId##',ISNULL(@strBCCEMailid,''))
    SET  @i_vcInputJsonEMAIL = REPLACE(@i_vcInputJsonEMAIL,'##Subject##',ISNULL(@strSubject,''))
	
    IF @StrBodyText1 <> ''
	BEGIN
	  SET @StrBodyText = REPLACE(@StrBodyText1,'"','')
	END
	
    SET  @i_vcInputJsonEMAIL = REPLACE(@i_vcInputJsonEMAIL,'##Body##',REPLACE(ISNULL(@StrBodyText,''),'"',''))
	
           
	SET @o_vcOutputJsonEMAIL = ''

	EXEC stpr_APISendEmail @i_vcInputJsonEMAIL, 'EMAIL', @i_vcAPICallingUrl, @o_vcOutputJsonEMAIL OUTPUT
			
    INSERT INTO tbl_EMailLog(Code, ToMailid, CCMailid, BCCMailid, EmailSubject, EmailBodyText,
	AttachmentFile1Name, AttachmentFile1, SendDate,Response,RefName)
	VALUES(@vcProcess ,@strToEmailid, ISNULL(@strCCEMailid,''), ISNULL(@strBCCEMailid,''), @strSubject, ISNULL(@i_vcInputJsonEMAIL,''), '',
	'', GETDATE(), isnull(@o_vcOutputJsonEMAIL,''), @vcProcess)
  END	  
END	
GO

CREATE PROCEDURE [stpr_InsertUpdateXMLData] @dsXml XML, @o_iReturnMainSlNo INT OUTPUT, @o_vcFlag VARCHAR(1) OUTPUT, @o_vcMessage VARCHAR(MAX) OUTPUT 
WITH ENCRYPTION
AS
BEGIN
	/*      
///////////////////////////////////////////////////////////////////////////////////////////      
// Create By     : VAIBHAV GARG      
// Created Date  :       
// CCT NO        :     
// Version No    :       
// Description   :     
// Reviewed By   :      
// Review Date   :     
//////////////////////////////////////////////////////////////////////////////////////////      
*/
  DECLARE @tbl_InputJSONTable DBO.tb_ParamList;
  DECLARE @o_ParameterList VARCHAR(max) = '', @o_ParameterListxml XML;
  DECLARE @strXMl VARCHAR(MAX) = CAST(@dsXml AS VARCHAR(MAX))
  DECLARE @strSecondLevelData VARCHAR(50) = 'SecondLevelData'
  set @o_iReturnMainSlNo = 0
  SET @o_vcFlag = 'S'
  SET @o_vcMessage = ''

  DECLARE @tbl_PrimaryKey TABLE (KeyName VARCHAR(100), KeyValue VARCHAR(100))
  DECLARE @DeleteMasterPrimaryKey VARCHAR(MAX) = '', @DeleteDetailPrimaryKey VARCHAR(MAX) = '' 
		--- PARAMETER LIST   

  EXEC SP_ParameterXMLRep @dsXml, @o_ParameterList OUTPUT

  IF ISNULL(@o_ParameterList, '') <> ''
  BEGIN
	SET @o_ParameterListxml = CAST(@o_ParameterList AS XML)

	INSERT INTO @tbl_InputJSONTable (ParameterName, ParameterValue, HeaderName, Jsontag)
	SELECT Parameter.value('(ColumnName)[1]', 'VARCHAR(MAX)') AS Client_Code, REPLACE(Parameter.value(
					'(ColumnValue)[1]', 'VARCHAR(MAX)'), 'null', '') AS ColumnValue, Parameter.value(
				'(MasterTag)[1]', 'VARCHAR(MAX)') AS MasterTag, Parameter.value('(JsonLevel)[1]', 'VARCHAR(MAX)') 
	AS JsonLevel
	FROM @o_ParameterListxml.nodes('/Parameter') AS XTbl(Parameter)
  END

  DECLARE @strModuleName VARCHAR(100) = '', @strString NVARCHAR(MAX), @i_vcUserUserType VARCHAR(50)=''

  SELECT @strModuleName = ParameterValue
  FROM @tbl_InputJSONTable
  WHERE ParameterName = 'ActionName'

  IF ISNULL(@strModuleName, '') = ''
  BEGIN
	SET @o_vcFlag = 'F'
	SET @o_vcMessage = '<Message>Module Name can not be blank</Message>'
	RETURN 1
  END
	
  DECLARE @i_vcUserCode VARCHAR(50) = '', @i_vcmode VARCHAR(50) = ''

  SELECT top 1 @i_vcUserCode = ParameterValue
  FROM @tbl_InputJSONTable
  WHERE ParameterName = 'UserId'
  
  SELECT top 1 @i_vcUserUserType = ParameterValue
  FROM @tbl_InputJSONTable
  WHERE ParameterName = 'UserType'

  SELECT @i_vcmode = ParameterValue
  FROM @tbl_InputJSONTable
  WHERE ParameterName = 'Option'

  DECLARE @StrRMSAmount MONEY = 0, @strBranchPayout MONEY = 0
  
  IF @strModuleName = 'BankReceipts' AND @i_vcmode IN('ADD' ,'EDIT')
  BEGIN
    DECLARE @strBankAPIUrl VARCHAR(100), @strBankRequestJson VARCHAR(MAX)='', @StrRemitterAccount VARCHAR(100)='',
	@StrRemitterIfsc VARCHAR(20)='', @StrBank VARCHAR(100)='', @strJSONBank VARCHAR(MAX)='',  @strRandomNoFinal VARCHAR(50) = ''
	DECLARE @strRandomNo INT = 0, @strRClientCode VARCHAR(20)='', @strRBankAccountNo VARCHAR(100)='',
	@strBankAccNoN VARCHAR(100)='', @strBankMICRN VARCHAR(12)='', @strBankIFSCN VARCHAR(20)='',
	@strReceiveAmount MONEY = 0, @strBankUTRNo VARCHAR(50)='', @strBCM_NAME VARCHAR(200)='',
	@strThirdPartyURL VARCHAR(MAX)='', @o_vcOutputJsonapi VARCHAR(MAX)='',
	@strspStatus VARCHAR(500)='', @strtradeplustempdb VARCHAR(100)=''
	
	      
    SELECT @strtradeplustempdb = sp_sysvalue FROM WebParameter(NOLOCK) WHERE sp_parmcd = 'TRADEPLUSTEMPDB' 	  
         
	
	DECLARE @jsonCutterOutput VARCHAR(MAX)='', @strDanSql NVARCHAR(MAX)='', @StrLedgerCode VARCHAR(20)=''
    DECLARE @JsonCutterXML XML
  
    
	SELECT @strBankAPIUrl = APIUrl, @strBankRequestJson = RequestJson 
    FROM tbl_VendorAPISetting(NOLOCK) 
	WHERE APIVendorName='SECMARK' AND APIName = 'BankReceipts'
	
	SELECT @StrRemitterAccount  = VALUE
    FROM (SELECT * FROM DBO.fn_SplitString(@strBankRequestJson, '~')) X1
    WHERE X1.Position = 1
	
	SELECT @StrRemitterIfsc  = VALUE
    FROM (SELECT * FROM DBO.fn_SplitString(@strBankRequestJson, '~')) X1
    WHERE X1.Position = 2
	
	SELECT @StrBank  = VALUE
    FROM (SELECT * FROM DBO.fn_SplitString(@strBankRequestJson, '~')) X1
    WHERE X1.Position = 3
	
	SELECT @StrLedgerCode  = VALUE
    FROM (SELECT * FROM DBO.fn_SplitString(@strBankRequestJson, '~')) X1
    WHERE X1.Position = 4
	
	SET @strRandomNo =  ABS(CHECKSUM(NEWID())) % 1000000;
	SELECT @strRandomNoFinal = RIGHT(REPLICATE('0', '6') + CAST(@strRandomNo AS VARCHAR), '6')
	
	--2025-07-01  MOB/TPFT/CHANDRAMOHAN R./911010038512964/  2025-07-01T08:04:09.747
	
	SET @strJSONBank = '{"Id": "##Id##","Bank":"##Bank##","LedgerCode": "##LedgerCode##",
	"AccountNumber": "##AccountNumber##", "ValueDate": "##ValueDate##","Indicator": "Credit",
	"Mode": "MSC","Amount": ##Amount##,"Utr": "##Utr##","RemitterAccount": "##RemitterAccount##",
    "RemitterName": "##RemitterName##","RemitterIfsc": "##RemitterIfsc##","Narration": "##Narration##",
    "TransactionDateTime": "##TransactionDateTime##"}'
	
	
	SELECT @strRClientCode = ltrim(rtrim(ParameterValue))
	FROM @tbl_InputJSONTable WHERE ParameterName = 'Client' 
	
    SELECT @strBCM_NAME = ltrim(rtrim(CM_NAME)) FROM CLIENT_MASTER(NOLOCK) 
	WHERE CM_cD = @strRClientCode
    
	DECLARE @tbl_jsonoutput TABLE(SerialNo INT, ColumnName VARCHAR(50), ColumnValue VARCHAR(MAX), 
    MasterTag VARCHAR(100), JSONLEVEL INT, MASTERLEVEL INT)
    
	
	SET @strJSONBank = REPLACE(@strJSONBank, '##Id##',@strRandomNoFinal)
	SET @strJSONBank = REPLACE(@strJSONBank, '##Bank##',@StrBank)
	SET @strJSONBank = REPLACE(@strJSONBank, '##LedgerCode##',@StrLedgerCode)
	
	SET @strJSONBank = REPLACE(@strJSONBank, '##RemitterName##',@strBCM_NAME)
	
	SET @strJSONBank = REPLACE(@strJSONBank, '##Narration##','Receive Fund Offline-TradePlus-'+SUBSTRING(@strBCM_NAME,1,20))
	SET @strJSONBank = REPLACE(@strJSONBank, '##TransactionDateTime##',CONVERT(VARCHAR(23), GETDATE(), 126))
	
	SELECT @strRBankAccountNo = ParameterValue 
	FROM @tbl_InputJSONTable WHERE ParameterName = 'BankAccountNo' 
	
	SELECT @strBankAccNoN  = VALUE
    FROM (SELECT * FROM DBO.fn_SplitString(@strRBankAccountNo, '-')) X1
    WHERE X1.Position = 1
    
	SELECT @strBankMICRN  = VALUE
    FROM (SELECT * FROM DBO.fn_SplitString(@strRBankAccountNo, '-')) X1
    WHERE X1.Position = 2
	
	SELECT TOP 1 @strBankIFSCN  = bk_IFCCode 
	FROM BANK_MASTER(NOLOCK) WHERE BK_MICR = @strBankMICRN
	
    SET @strJSONBank = REPLACE(@strJSONBank, '##RemitterIfsc##',@strBankIFSCN)	
	
	SELECT @strRBankAccountNo = ParameterValue 
	FROM @tbl_InputJSONTable WHERE ParameterName = 'BankAccountNo' 
	
	SELECT @strReceiveAmount = ParameterValue 
	FROM @tbl_InputJSONTable WHERE ParameterName = 'ReceiveAmount' 
	
	SELECT @strBankUTRNo = ParameterValue 
	FROM @tbl_InputJSONTable WHERE ParameterName = 'BankUTRNo' 
	
	SET @strJSONBank = REPLACE(@strJSONBank, '##AccountNumber##',@StrRemitterAccount)
	SET @strJSONBank = REPLACE(@strJSONBank, '##ValueDate##',CONVERT(VARCHAR(10), GETDATE(), 23))
	SET @strJSONBank = REPLACE(@strJSONBank, '##Amount##',@strReceiveAmount)
	SET @strJSONBank = REPLACE(@strJSONBank, '##Utr##',@strBankUTRNo)
	SET @strJSONBank = REPLACE(@strJSONBank, '##RemitterAccount##',@strBankAccNoN)
	
	SELECT @strThirdPartyURL = sp_sysvalue 
    FROM Sysparameter(NOLOCK) WHERE sp_parmcd = 'ThirdParty'
	 
    
	EXEC stpr_CallThirdPartyAPI 'SecMark','SecMark','BankReceipts', 'N',@strJSONBank, '',@strThirdPartyURL, @i_vcUserCode, @o_vcOutputJsonapi  OUTPUT	
	
	IF @o_vcOutputJsonapi <> ''
	BEGIN
	  DELETE from @tbl_jsonoutput
	  BEGIN TRY
        SET @strDanSql = 'EXEC '+@strtradeplustempdb+'.DBO.sp_JsonCutter'+' '''+@o_vcOutputJsonapi+''' , @jsonCutterOutput OUTPUT';
        EXEC sp_executesql @strDanSql, N'@jsonCutterOutput VARCHAR(MAX) OUTPUT', @jsonCutterOutput OUTPUT;
        SET @JsonCutterXML = CAST(@jsonCutterOutput AS XML)
        INSERT INTO @tbl_jsonoutput(SerialNo, ColumnName, ColumnValue,  MasterTag, JSONLEVEL, MASTERLEVEL)
 	    SELECT X1.* FROM(
        SELECT JsonCutter.value('(SerialNo)[1]', 'int') AS SerialNo ,
	    JsonCutter.value('(ColumnName)[1]', 'VARCHAR(1000)') AS ColumnName ,
        JsonCutter.value('(ColumnValue)[1]', 'VARCHAR(max)') AS ColumnValue,
	    JsonCutter.value('(MasterTag)[1]', 'VARCHAR(50)') AS MasterTag,
	    JsonCutter.value('(JsonLevel)[1]', 'INT') AS JsonLevel,
	    JsonCutter.value('(MasterLevel)[1]', 'INT') AS MasterLevel
        FROM @JsonCutterXML.nodes('/JsonCutter') AS XTbl(JsonCutter)) X1
	  END TRY
      BEGIN CATCH
		 SET @o_vcFlag = 'F'
	     SET @o_vcMessage = ERROR_MESSAGE()+@o_vcOutputJsonapi
	     SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
	     RETURN 1
      END CATCH 
	  
	  SELECT TOP 1 @strspStatus = ColumnValue FROM @tbl_jsonoutput WHERE ColumnName = 'Status' 
	  
      IF EXISTS(SELECT 1 FROM @tbl_jsonoutput WHERE ColumnName = 'Code' AND ColumnValue ='100')
	  BEGIN 	  
	    SET @o_vcFlag = 'S'
	    SET @o_vcMessage = @strspStatus
	    SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
	    RETURN 1
	  END
      ELSE
      BEGIN
	    SET @o_vcFlag = 'E'
	    SET @o_vcMessage = @strspStatus
	    SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
	    RETURN 1
      END 	  
	END
	ELSE
	BEGIN
	  SET @o_vcFlag = 'F'
	  SET @o_vcMessage = @o_vcOutputJsonapi
	  SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
	  RETURN 1
	END
  END
  IF @strModuleName = 'FundRequest' AND @i_vcmode IN('ADD' ,'EDIT')
  BEGIN
    
	DECLARE @strFromTime VARCHAR(20)='', @strTOTime VARCHAR(20)=''
	SELECT @strFromTime =  CAST(SUBSTRING(sp_sysvalue,1,CHARINDEX(',',sp_sysvalue)-1) AS TIME), 
    @strTOTime =  CAST(SUBSTRING(sp_sysvalue,CHARINDEX(',',sp_sysvalue)+1,10) AS TIME) 
    FROM WebParameter(NOLOCK) WHERE sp_parmcd = 'FP_CL_RQ_TM' AND ISNULL(sp_sysvalue,'') <> ''
	
    IF CAST(GETDATE() AS TIME) NOT BETWEEN @strFromTime AND  @strTOTime
    BEGIN
      SET @o_vcFlag = 'F'
	  SET @o_vcMessage = 'Payout Request can be made between ' + CAST(@strFromTime AS VARCHAR(5)) + ' and '+ CAST(@strTOTime AS VARCHAR(5)) + ' hours'
	  SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
	  RETURN 1
    END	  
	
	DECLARE @srno INT = 0, @strIP VARCHAR(20) = ''
	DECLARE @strRequestedAmount MONEY = 0, @strLedgerAmount  MONEY=0
	DECLARE @strAmount MONEY = 0, @strFund MONEY = 0, @strLeastAmount MONEY = 0, @strPClientCode VARCHAR(20)=''
	
	SELECT TOP 1 @strIP = ParameterValue 
	FROM @tbl_InputJSONTable WHERE ParameterName = 'IPAddress'
	
	
	DECLARE @strMinex VARCHAR(3)='', @strdpid VARCHAR(3)=''
	SELECT @strMinex = MIN(CES_CD) FROM CompanyExchangeSegments

	SELECT @strdpid = CH_CompanyCode+CH_ClgHs+CH_Segment FROM ClearingHouse(NOLOCK) X WHERE CH_CompanyCode =  SUBSTRING(@strMinex,1,1) 
	AND CH_Segment =  SUBSTRING(@strMinex,3,1)
	AND CH_EffDt IN (SELECT Min(CH_EffDt) FROM ClearingHouse(NOLOCK)
    WHERE CH_CompanyCode = X.CH_CompanyCode AND CH_Segment = X.CH_Segment AND CH_EffDt <= CONVERT(VARCHAR,GETDATE(),112))
	
    IF EXISTS(SELECT 1 FROM @tbl_InputJSONTable WHERE HeaderName = 'SecondLevelData' AND ParameterName = 'ClientCode' 
	AND ISNULL(ParameterValue,'') <> '')
    BEGIN
      DECLARE @FundJsonTag VARCHAR(10) = ''

	  DECLARE CURSOR_FundRequest
	  CURSOR FOR SELECT DISTINCT JsonTag
	  FROM @tbl_InputJSONTable
	  WHERE HeaderName = 'SecondLevelData'

	  OPEN CURSOR_FundRequest
      FETCH NEXT FROM CURSOR_FundRequest INTO @FundJsonTag
     
	  WHILE @@FETCH_STATUS = 0
	  BEGIN
	    SELECT @strRequestedAmount = CAST(ParameterValue AS MONEY)
        FROM @tbl_InputJSONTable
        WHERE ParameterName = 'RequestedAmount'
	    and HeaderName = 'SecondLevelData'
	    and jsontag = @FundJsonTag
  
        SELECT @strLedgerAmount = CAST(ParameterValue AS MONEY)
        FROM @tbl_InputJSONTable
        WHERE ParameterName = 'PayableAmount'
	    and HeaderName = 'SecondLevelData'
	    and jsontag = @FundJsonTag
  
        SELECT @strPClientCode = ParameterValue
        FROM @tbl_InputJSONTable
        WHERE ParameterName = 'ClientCode'
	    and HeaderName = 'SecondLevelData'
	    and jsontag = @FundJsonTag
  
  
	    IF ISNULL(@strLedgerAmount,0) >  ISNULL(@strRequestedAmount,0) and ISNULL(@strRequestedAmount,0)  > 0
	    BEGIN
	      DELETE FROM FundsRequest WHERE rq_clientcd = @strPClientCode AND Rq_Satus1 = 'P'

          SELECT @strAmount = CAST((- 1 * sum(ld_amount)) AS DECIMAL(15, 2)), 
          @strFund = ISNULL((SELECT CAST(SUM(Rq_Amount) AS DECIMAL(15, 2))
          FROM FundsRequest(NOLOCK) WHERE rq_clientcd = @strPClientCode AND Rq_Satus1 = 'P'), 0)
          FROM Client_Master(NOLOCK), Ledger(NOLOCK)
          WHERE ld_clientcd = cm_cd and ld_clientcd = @strPClientCode
      
	      SET @strFund = ISNULL(@strFund,0) + ISNULL(@strRequestedAmount,0)
	      
		  IF (ISNULL(@strAmount, 0) - ISNULL(@strFund, 0)) > 0
          BEGIN
	        IF EXISTS (SELECT 1 FROM Sysparameter(NOLOCK) WHERE sp_parmcd LIKE 'RMSHEAD%' AND sp_sysvalue = 'FUNDPAYOUT')
            BEGIN
	          SET @StrRMSAmount = 0
	          SELECT @StrRMSAmount = isnull(CAST((- 1 * sum(rs_fundpayout)) AS DECIMAL(15, 2)), 0)
	          FROM Rms_summary(NOLOCK)
	          WHERE rs_Dt = (SELECT MAX(rs_Dt) FROM RMS_Summary(NOLOCK) ) 
	          AND rs_clientcd = @strPClientCode

	          IF ISNULL(@StrRMSAmount, 0) > ISNULL(@strFund, 0)
	          BEGIN
			  
			    IF NOT EXISTS(SELECT 1 FROM  sys.columns c JOIN  sys.tables t ON c.object_id = t.object_id 
			    WHERE t.name = 'FundsRequest' AND c.name = 'Rq_SrNo' and c.is_identity = 1)
                BEGIN
	              SELECT @srno = ISNULL(MAX(Rq_SrNo),0)+1 FROM FundsRequest(NOLOCK)	
			  
		          INSERT INTO FundsRequest (Rq_SrNo, Rq_Clientcd, Rq_Type, Rq_Amount, Rq_IpAddress, Rq_Date, Rq_Time, 
                  Rq_Satus1, Rq_Satus2, Rq_Satus3, Rq_Satus4, Rq_Note)
                  SELECT @srno, @strPClientCode, 'A', @strRequestedAmount, @strIP, convert(VARCHAR, GETDATE(), 112), CONVERT(VARCHAR, 
                  GETDATE(), 108), 'P', '', '', '', @strdpid	     
			    END	
				ELSE
				BEGIN
				  INSERT INTO FundsRequest (Rq_Clientcd, Rq_Type, Rq_Amount, Rq_IpAddress, Rq_Date, Rq_Time, 
                  Rq_Satus1, Rq_Satus2, Rq_Satus3, Rq_Satus4, Rq_Note)
                  SELECT @strPClientCode, 'A', @strRequestedAmount, @strIP, convert(VARCHAR, GETDATE(), 112), CONVERT(VARCHAR, 
                  GETDATE(), 108), 'P', '', '', '', @strdpid	     
				END
			  END
		    END	
		    ELSE
		    BEGIN
			  IF NOT EXISTS(SELECT 1 FROM  sys.columns c JOIN  sys.tables t ON c.object_id = t.object_id 
			  WHERE t.name = 'FundsRequest' AND c.name = 'Rq_SrNo' and c.is_identity = 1)
              BEGIN
	            SELECT @srno = ISNULL(MAX(Rq_SrNo),0)+1 FROM FundsRequest(NOLOCK)	
			  
		        INSERT INTO FundsRequest (Rq_SrNo, Rq_Clientcd, Rq_Type, Rq_Amount, Rq_IpAddress, Rq_Date, Rq_Time, 
                Rq_Satus1, Rq_Satus2, Rq_Satus3, Rq_Satus4, Rq_Note)
                SELECT @srno, @strPClientCode, 'A', @strRequestedAmount, @strIP, convert(VARCHAR, GETDATE(), 112), CONVERT(VARCHAR, 
                GETDATE(), 108), 'P', '', '', '', @strdpid	     
			  END	
		      ELSE
			  BEGIN
				INSERT INTO FundsRequest (Rq_Clientcd, Rq_Type, Rq_Amount, Rq_IpAddress, Rq_Date, Rq_Time, 
                Rq_Satus1, Rq_Satus2, Rq_Satus3, Rq_Satus4, Rq_Note)
                SELECT @strPClientCode, 'A', @strRequestedAmount, @strIP, convert(VARCHAR, GETDATE(), 112), CONVERT(VARCHAR, 
                GETDATE(), 108), 'P', '', '', '', @strdpid	     
			  END
		    END
	      END
        END
	    FETCH NEXT FROM CURSOR_FundRequest INTO @FundJsonTag
	  END;

	  CLOSE CURSOR_FundRequest;
	  DEALLOCATE CURSOR_FundRequest;
	  SET @o_vcFlag = 'S'
      SET @o_vcMessage = 'Insert Sucessfully'
      SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
      RETURN 1  
    END	
	ELSE 
	BEGIN  
      SELECT @strRequestedAmount = CAST(ParameterValue AS MONEY)
      FROM @tbl_InputJSONTable
      WHERE ParameterName = 'RequestedAmount'
  
      SELECT @strLedgerAmount = CAST(ParameterValue AS MONEY)
      FROM @tbl_InputJSONTable
      WHERE ParameterName = 'Amount'
  
	
	  IF ISNULL(@strLedgerAmount,0) <  ISNULL(@strRequestedAmount,0)
	  BEGIN
	    SET @o_vcFlag = 'F'
	    SET @o_vcMessage = 'Payout Amount should not be greater then Availabe Amount'
	    SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
	    RETURN 1
	  END
	  IF ISNULL(@strRequestedAmount,0) <= 0
      BEGIN	
	    SET @o_vcFlag = 'F'
	    SET @o_vcMessage = 'Payout Amount should not be zero or less then zero'
	    SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
	    RETURN 1
	  END
	  IF ISNULL(@strRequestedAmount,0) > 0
      BEGIN	
  	    DELETE FROM FundsRequest WHERE rq_clientcd = @i_vcUserCode AND Rq_Satus1 = 'P'

        SELECT @strAmount = CAST((- 1 * sum(ld_amount)) AS DECIMAL(15, 2)), 
        @strFund = ISNULL((SELECT CAST(SUM(Rq_Amount) AS DECIMAL(15, 2))
        FROM FundsRequest(NOLOCK) WHERE rq_clientcd = @i_vcUserCode AND Rq_Satus1 = 'P'), 0)
        FROM Client_Master(NOLOCK), Ledger(NOLOCK)
        WHERE ld_clientcd = cm_cd and ld_clientcd = @i_vcUserCode
     
	    SET @strFund = ISNULL(@strFund,0) + ISNULL(@strRequestedAmount,0)
	  
	  	
        IF (ISNULL(@strAmount, 0) - ISNULL(@strFund, 0)) < 0
        BEGIN
	      SET @o_vcFlag = 'F'
	      SET @o_vcMessage = 'Payout Amount should not be greater then Availabe Amount'
	      SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
	      RETURN 1
        END
	
        IF EXISTS (SELECT 1 FROM Sysparameter(NOLOCK) WHERE sp_parmcd LIKE 'RMSHEAD%' AND sp_sysvalue = 'FUNDPAYOUT')
        BEGIN
	      SET @StrRMSAmount = 0
	      SELECT @StrRMSAmount = isnull(CAST((- 1 * sum(rs_fundpayout)) AS DECIMAL(15, 2)), 0)
	      FROM Rms_summary(NOLOCK)
	      WHERE rs_Dt = (SELECT MAX(rs_Dt) FROM RMS_Summary(NOLOCK) ) 
	      AND rs_clientcd = @i_vcUserCode

	      IF ISNULL(@StrRMSAmount, 0) < ISNULL(@strFund, 0)
	      BEGIN
	        SET @o_vcFlag = 'F'
	        SET @o_vcMessage = 'Payout Amount should not be greater then RMS Amount'
	        SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
	        RETURN 1
	      END
        END
	    
	    IF NOT EXISTS(SELECT 1 FROM  sys.columns c JOIN  sys.tables t ON c.object_id = t.object_id 
		WHERE t.name = 'FundsRequest' AND c.name = 'Rq_SrNo' and c.is_identity = 1)
        BEGIN
	      SELECT @srno = ISNULL(MAX(Rq_SrNo),0)+1 FROM FundsRequest(NOLOCK)	     
	      INSERT INTO FundsRequest (Rq_SrNo, Rq_Clientcd, Rq_Type, Rq_Amount, Rq_IpAddress, Rq_Date, Rq_Time, 
          Rq_Satus1, Rq_Satus2, Rq_Satus3, Rq_Satus4, Rq_Note)
          SELECT @srno, @i_vcUserCode, 'A', @strRequestedAmount, @strIP, convert(VARCHAR, GETDATE(), 112), CONVERT(VARCHAR, 
          GETDATE(), 108), 'P', '', '', '', @strdpid
		END
        ELSE
        BEGIN
	      INSERT INTO FundsRequest ( Rq_Clientcd, Rq_Type, Rq_Amount, Rq_IpAddress, Rq_Date, Rq_Time, 
          Rq_Satus1, Rq_Satus2, Rq_Satus3, Rq_Satus4, Rq_Note)
          SELECT @i_vcUserCode, 'A', @strRequestedAmount, @strIP, convert(VARCHAR, GETDATE(), 112), CONVERT(VARCHAR, 
          GETDATE(), 108), 'P', '', '', '', @strdpid
        END 		

        SET @o_vcFlag = 'S'
        SET @o_vcMessage = 'Insert Sucessfully'
        SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
        RETURN 1  
	  END 
	END  
  END
  
  IF @strModuleName = 'FamilyMapping' AND @i_vcmode IN('ADD' ,'EDIT')
  BEGIN
    DECLARE @strUccCode VARCHAR(50)='', @strpassword VARCHAR(50)='', @strFamilyIP VARCHAR(50)=''
	
	SELECT @strUccCode = ParameterValue FROM @tbl_InputJSONTable 
	WHERE ParameterName = 'UccCode' 
	
	SELECT @strpassword = ParameterValue FROM @tbl_InputJSONTable 
	WHERE ParameterName = 'Password' 
	
   SELECT TOP 1 @strFamilyIP = ParameterValue 
	FROM @tbl_InputJSONTable WHERE ParameterName = 'IPAddress'
	
	IF EXISTS(SELECT 1 FROM CLIENT_MASTER(NOLOCK) WHERE CM_cD = @strUccCode)
	BEGIN
	  IF EXISTS(SELECT 1 FROM Client_Family(NOLOCK) WHERE CF_CD = @strUccCode AND CF_FamilyCd = @i_vcUserCode)
	  BEGIN 
	    SET @o_vcFlag = 'E'
	    SET @o_vcMessage = '<Message>Already Map with Client :- '+@strUccCode+' '+'</Message>'
	    RETURN 1
	  END
	  DECLARE @strAleadyFamily VARCHAR(50)=''
	  SELECT @strAleadyFamily = CF_FamilyCd FROM Client_Family(NOLOCK) WHERE CF_CD = @strUccCode
	  
	  IF ISNULL(@strAleadyFamily,'') <> ''
	  BEGIN 
	    SET @o_vcFlag = 'E'
	    SET @o_vcMessage = '<Message>Already Map with Client :- '+@strAleadyFamily+' '+'</Message>'
	    RETURN 1
	  END
	  
	  INSERT INTO Client_Family(CF_CD,CF_FamilyCd,CF_MkrDt,CF_MkrTm,CF_IP)
	  VALUES(@strUccCode, @i_vcUserCode, CONVERT(VARCHAR,GETDATE(),112),CONVERT(VARCHAR,GETDATE(),108),ISNULL(@strFamilyIP,''))
	  
	  IF NOT EXISTS(SELECT 1 FROM Client_Family(NOLOCK) WHERE CF_CD = @i_vcUserCode AND CF_FamilyCd = @i_vcUserCode)
	  BEGIN
	    INSERT INTO Client_Family(CF_CD,CF_FamilyCd,CF_MkrDt,CF_MkrTm,CF_IP)
	    VALUES(@i_vcUserCode, @i_vcUserCode, CONVERT(VARCHAR,GETDATE(),112),CONVERT(VARCHAR,GETDATE(),108),ISNULL(@strFamilyIP,''))
	  END
	  
      SET @o_vcFlag = 'S'
      SET @o_vcMessage = 'Insert Sucessfully'
      SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
      RETURN 1  
	END
	ELSE
	BEGIN
	 SET @o_vcFlag = 'E'
	 SET @o_vcMessage = '<Message>Invalid UCC Code</Message>'
	 RETURN 1
	END
  END	

  IF @strModuleName = 'FamilyMapping' AND @i_vcmode IN('DELETE')
  BEGIN
    DECLARE @strDelUccCode VARCHAR(50)=''
	
	SELECT @strDelUccCode = ParameterValue FROM @tbl_InputJSONTable 
	WHERE ParameterName = 'UccCode'

	IF EXISTS(SELECT 1 FROM Client_Family(NOLOCK) WHERE CF_CD = CF_FamilyCd and CF_CD = @strDelUccCode)
	BEGIN
	  DELETE FROM Client_Family WHERE CF_FamilyCd = @strDelUccCode
	END
	ELSE
	BEGIN
	  DELETE FROM Client_Family WHERE CF_CD = @strDelUccCode
	END

	SET @o_vcFlag = 'S'
    SET @o_vcMessage = 'Deleted Sucessfully'
    SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
    RETURN 1
  END
  

  IF @strModuleName = 'APISETTING' AND @i_vcmode IN('ADD' ,'EDIT')
  BEGIN
    IF EXISTS(SELECT 1 FROM @tbl_InputJSONTable WHERE ParameterName = 'ServiceName' 
	AND ISNULL(ParameterValue,'') <> '')
    BEGIN
	  Declare @strAPIVendorName VARCHAR(50)='', @strServiceName VARCHAR(50)='', @StrAPIUrl VARCHAR(100)='',
	  @strAPIAuthToken NVARCHAR(MAX)='', @strHeaderParameter VARCHAR(MAX)='', 
	  @strParameterSetting VARCHAR(MAX)='', @strCallBackUrl VARCHAR(MAX)='', @strAPIActiveFlag VARCHAR(1),
	  @strLoginUserid VARCHAR(MAX)='',@strLoginPassword VARCHAR(MAX)='', @strAutoAPIStartTime VARCHAR(10)='', @strAutoAPIEndTime VARCHAR(10)=''
	  
	  SELECT TOP 1 @strAPIVendorName = ParameterValue FROM @tbl_InputJSONTable
      WHERE ParameterName = 'VendorName'
	  
	  SELECT TOP 1 @strServiceName = ParameterValue FROM @tbl_InputJSONTable
      WHERE ParameterName = 'ServiceName'
	  
	  SELECT TOP 1 @StrAPIUrl = ParameterValue FROM @tbl_InputJSONTable
      WHERE ParameterName = 'APIUrl'
	  
	  SELECT TOP 1 @strAPIAuthToken = ParameterValue FROM @tbl_InputJSONTable
      WHERE ParameterName = 'APIAuthToken'
	  
	  SELECT TOP 1 @strHeaderParameter = ParameterValue FROM @tbl_InputJSONTable
      WHERE ParameterName = 'HeaderParameter'
	  
	  SELECT TOP 1 @strParameterSetting = ParameterValue FROM @tbl_InputJSONTable
      WHERE ParameterName = 'ParameterSetting'
	  
	  SELECT TOP 1 @strCallBackUrl = ParameterValue FROM @tbl_InputJSONTable
      WHERE ParameterName = 'CallBackUrl'
	  
	  SELECT TOP 1 @strAPIActiveFlag = ParameterValue FROM @tbl_InputJSONTable
      WHERE ParameterName = 'ActiveFlag'
	  
	  SELECT TOP 1 @strLoginUserid = ParameterValue FROM @tbl_InputJSONTable
      WHERE ParameterName = 'LoginUserid'
	  
	  SELECT TOP 1 @strLoginPassword = ParameterValue FROM @tbl_InputJSONTable
      WHERE ParameterName = 'LoginPassword'
	  
	  SELECT TOP 1 @strAutoAPIStartTime = ParameterValue FROM @tbl_InputJSONTable
      WHERE ParameterName = 'AutoAPIStartTime'
	  
	  SELECT TOP 1 @strAutoAPIEndTime = ParameterValue FROM @tbl_InputJSONTable
      WHERE ParameterName = 'AutoAPIEndTime'
	  
	  UPDATE A SET A.APIUrl =  REPLACE(REPLACE(@StrAPIUrl,'~~','<<'),'!!','>>') , A.APIAuthToken = @strAPIAuthToken, 
	  A.FieldsForHeader = @strHeaderParameter, A.RequestJson = @strParameterSetting,
	  A.CallBackUrl = REPLACE(REPLACE(@strCallBackUrl,'~~','<<'),'!!','>>'), A.IsActive = @strAPIActiveFlag, 
	  A.LoginUserid = @strLoginUserid, A.LoginPassword = @strLoginPassword,
	  A.StartTime = @strAutoAPIStartTime, A.EndTime = @strAutoAPIEndTime
	  FROM tbl_VendorAPISetting A
	  WHERE A.APIVendorName = @strAPIVendorName
	  AND A.APIName = @strServiceName
      
      SET @o_vcFlag = 'S'
      SET @o_vcMessage = 'Update Sucessfully'
      SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
      RETURN 1 	  
	END
  END

  
  IF @strModuleName = 'BUYBACK' AND @i_vcmode IN('ADD' ,'EDIT')
  BEGIN
    DECLARE @BuyBackJsonTag VARCHAR(10)='',
	@strBuyBackClient VARCHAR(50), @strBuyBackDemat VARCHAR(20)='', @strOffersQty INT = 0, @strBBScripCode VARCHAR(20)='',
	@strBSettlementNo VARCHAR(20)=''
    
	SELECT @strBBScripCode = ParameterValue FROM @tbl_InputJSONTable 
	WHERE ParameterName = 'ScripCode' 
	
	IF EXISTS(SELECT 1 FROM @tbl_InputJSONTable WHERE HeaderName = 'SecondLevelData' AND ParameterName = 'ClientCode' 
	AND ISNULL(ParameterValue,'') <> '')
    BEGIN
	  DECLARE CURSOR_BUYBACKRequest
	  CURSOR FOR SELECT DISTINCT JsonTag
	  FROM @tbl_InputJSONTable
	  WHERE HeaderName = 'SecondLevelData'

	  OPEN CURSOR_BUYBACKRequest
      FETCH NEXT FROM CURSOR_BUYBACKRequest INTO @BuyBackJsonTag
     
	  WHILE @@FETCH_STATUS = 0
	  BEGIN
	    SET @strOffersQty = 0
		
		SET @strBuyBackClient = ''
		SET @strBuyBackDemat = ''
		SET @strBSettlementNo = ''
		
		SELECT @strBuyBackClient = ParameterValue
        FROM @tbl_InputJSONTable
        WHERE ParameterName = 'ClientCode'
	    and HeaderName = 'SecondLevelData'
	    and jsontag = @BuyBackJsonTag
		
		SELECT @strBuyBackDemat = ParameterValue
        FROM @tbl_InputJSONTable
        WHERE ParameterName = 'DematAccountNo'
	    and HeaderName = 'SecondLevelData'
	    and jsontag = @BuyBackJsonTag
		
		SELECT @strOffersQty = ParameterValue
        FROM @tbl_InputJSONTable
        WHERE ParameterName = 'Offers'
	    AND HeaderName = 'SecondLevelData'
	    AND jsontag = @BuyBackJsonTag
		
		SELECT @strBSettlementNo = ParameterValue
        FROM @tbl_InputJSONTable
        WHERE ParameterName = 'SettlementNo'
	    AND HeaderName = 'SecondLevelData'
	    AND jsontag = @BuyBackJsonTag
		
		
		DELETE FROM BUYBACKS 
		WHERE BB_ClientCd = @strBuyBackClient 
		AND BB_Stlmnt  = @strBSettlementNo 
		AND BB_ScripCd = @strBBScripCode 
		AND BB_Status in ('C','T')
		
		INSERT INTO BuyBacks(BB_ApplNo,BB_ScripCd,BB_Stlmnt,BB_ClientCd,BB_Qty,BB_Rate,BB_DematAct,BB_Dt,BB_PayInDt,
		BB_PayInBatch, BB_Status, BB_CustodianCd, BB_BidID, BB_Actioncd, BB_mkrID, BB_mkrDt)
        SELECT '', BB_ScripCd, BB_Stlmnt, @strBuyBackClient, @strOffersQty, BB_Rate, @strBuyBackDemat, CONVERT(VARCHAR,GETDATE(),112),
		se_payoutdt,0,(CASE WHEN @i_vcUserUserType = 'User' THEN 'C' ELSE 'T' END),0,0,'N',@i_vcUserCode, CONVERT(VARCHAR,GETDATE(),112)
		FROM BuyBacks(NOLOCK), Settlements(NOLOCK), Securities(NOLOCK)
        WHERE ss_cd = BB_ScripCd AND BB_Stlmnt = se_stlmnt 
		AND se_endt >= CONVERT(VARCHAR,GETDATE(),112) AND BB_clientcd = 'BUYBACK!'
		AND ss_cd = @strBBScripCode
		
	    FETCH NEXT FROM CURSOR_BUYBACKRequest INTO @BuyBackJsonTag
	  END;

	  CLOSE CURSOR_BUYBACKRequest;
	  DEALLOCATE CURSOR_BUYBACKRequest;
	  
	  SET @o_vcFlag = 'S'
      SET @o_vcMessage = 'Insert Sucessfully'
      SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
      RETURN 1  
    END	
  
  END

  IF @strModuleName = 'REKYCVALIDATE' AND @i_vcmode IN('ADD' ,'EDIT')
  BEGIN
	DECLARE @strRekycClientCode VARCHAR(50)='', @strRekycFormNo VARCHAR(20)='', @strRekycReplTag INT,
	@strRekycStatus1 VARCHAR(MAX)='', @strReKycReason VARCHAR(MAX)='', @o_vcErrorFlag VARCHAR(1), @o_vcErrorMessage VARCHAR(MAX), @o_vcJsonOutput  VARCHAR(MAX)
	IF EXISTS(SELECT 1 FROM @tbl_InputJSONTable WHERE HeaderName = 'SecondLevelData' AND ParameterName = 'ClientCode' 
	AND ISNULL(ParameterValue,'') <> '')
    BEGIN
	  
	  DECLARE CURSOR_ReKycQRequest
	  CURSOR FOR SELECT DISTINCT JsonTag
	  FROM @tbl_InputJSONTable
	  WHERE HeaderName = 'SecondLevelData'

	  OPEN CURSOR_ReKycQRequest
      FETCH NEXT FROM CURSOR_ReKycQRequest INTO @strRekycReplTag
     
	  WHILE @@FETCH_STATUS = 0
	  BEGIN
	    SET @strRekycClientCode  = ''
		SET @strRekycFormNo = ''
		
		SELECT @strRekycClientCode = ParameterValue
        FROM @tbl_InputJSONTable
        WHERE ParameterName = 'ClientCode'
	    and HeaderName = 'SecondLevelData'
	    and jsontag = @strRekycReplTag
		
		SELECT @strRekycFormNo = ParameterValue
        FROM @tbl_InputJSONTable
        WHERE ParameterName = 'FormNo'
	    and HeaderName = 'SecondLevelData'
	    and jsontag = @strRekycReplTag
		
		SELECT @strRekycStatus1 = ParameterValue
        FROM @tbl_InputJSONTable
        WHERE ParameterName = 'Status'
	    and HeaderName = 'SecondLevelData'
	    and jsontag = @strRekycReplTag
		
		
		SELECT @strReKycReason = ParameterValue
        FROM @tbl_InputJSONTable
        WHERE ParameterName = 'Reason'
	    AND HeaderName = 'SecondLevelData'
	    AND jsontag = @strRekycReplTag
		
		DECLARE @strtemplatetype VARCHAR(50)='', @StrEntryName11 VARCHAR(50)=''
		
		SELECT @strtemplatetype = rm_RequestType 
		FROM Client_ReKycMain(nolock) where rm_cmcd = @strRekycClientCode 
        AND  rm_refno = @strRekycFormNo and rm_status = 'Pending' and rm_rekyc = 'N'
		
		SET @StrEntryName11 = @strtemplatetype
            
		IF @strtemplatetype  IN('REKYC','REKYCOFFLINE')
		BEGIN
		  SET @strtemplatetype = 'Template1'
		END
		ELSE IF @strtemplatetype  = 'Account Closure'
		BEGIN
		  SET @strtemplatetype = 'ONLYCLOSURE'
		END
		
		IF NOT EXISTS(select 1 from Client_ReKycMain(nolock) where rm_cmcd = @strRekycClientCode 
        and  rm_refno = @strRekycFormNo and rm_status = 'Pending' and rm_rekyc = 'N') AND ISNULL(@strRekycStatus1,'') <> ''
	    BEGIN
	      SET @o_vcFlag = 'E'
	      SET @o_vcMessage = '<Message>Invalid Request</Message>'
	      RETURN 1
	    END
	    
	    IF NOT EXISTS(SELECT 1 FROM Client_ModifyAttach  WHERE ma_cmcd = @strRekycClientCode 
	    AND ma_refno = @strRekycFormNo AND ma_filename = 'SignedKRAPdf' AND ma_proof IS NOT NULL) AND ISNULL(@strRekycStatus1,'') = 'A'
		AND @strtemplatetype NOT IN('ONLYCLOSURE') AND ISNULL(@StrEntryName11,'') <> 'REKYCOFFLINE' 
		
	    BEGIN
	      SET @o_vcFlag = 'E'
	      SET @o_vcMessage = '<Message>KRA SIGN PDF NOT GENERATED</Message>'
	      RETURN 1
	    END
	
        IF NOT EXISTS(SELECT 1 FROM Client_ModifyAttach  WHERE ma_cmcd = @strRekycClientCode 
	    AND ma_refno = @strRekycFormNo AND ma_filename = 'SignedPdf' AND ma_proof IS NOT NULL)  AND ISNULL(@strRekycStatus1,'') = 'A'
		AND ISNULL(@StrEntryName11,'')  <> 'REKYCOFFLINE' 
	    BEGIN
	      SET @o_vcFlag = 'E'
	      SET @o_vcMessage = '<Message>FINAL SIGN PDF NOT GENERATED</Message>'
	      RETURN 1
	    END
	
		IF ISNULL(@strRekycStatus1,'') <> ''
		BEGIN
          BEGIN TRY
		    
			BEGIN TRY
			DECLARE @xstring11 VARCHAR(MAX)=''
			
			SELECT @xstring11 = Requestid FROM Client_ModifyAttach(NOLOCK) WHERE ma_cmcd = @strRekycClientCode 
	        AND ma_refno = @strRekycFormNo AND ma_filename = 'FinalJSON'
			
		    EXEC [dbo].[SP_ReKyc_CheckValidation] @xstring11, @strRekycClientCode, @strRekycFormNo, 'CHECKER', @o_vcErrorFlag OUTPUT, 
            @o_vcErrorMessage OUTPUT, @o_vcJsonOutput OUTPUT,'U', 'JSON', @strtemplatetype
			
	        IF @o_vcErrorFlag  = 'E'
	        BEGIN
	          SET @o_vcFlag = @o_vcErrorFlag
              SET @o_vcMessage = @o_vcErrorMessage+' '+@o_vcJsonOutput
              SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
			  CLOSE CURSOR_ReKycQRequest;
	          DEALLOCATE CURSOR_ReKycQRequest;
	          RETURN 1
	        END
            END TRY
	        BEGIN CATCH
	          SET @o_vcFlag = @o_vcErrorFlag
              SET @o_vcMessage = ERROR_MESSAGE()
              SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
			   CLOSE CURSOR_ReKycQRequest;
	           DEALLOCATE CURSOR_ReKycQRequest;
	          RETURN 1
	        END CATCH 
        		
			SET @o_vcErrorFlag = ''
			SET @o_vcErrorMessage = ''
			SET @o_vcJsonOutput = ''
			--SELECT @o_vcJsonOutput, @strRekycClientCode, @strRekycFormNo, @strRekycStatus1, @strReKycReason
			
			EXEC [dbo].[SP_ReKyc_CheckerApprove] @strRekycClientCode, @strRekycFormNo, @strRekycStatus1,@strReKycReason, 
            @o_vcErrorFlag OUTPUT, @o_vcErrorMessage OUTPUT, @o_vcJsonOutput OUTPUT, @strtemplatetype
			
            IF @o_vcErrorFlag  = 'E'
	        BEGIN
	          SET @o_vcFlag = @o_vcErrorFlag
              SET @o_vcMessage = @o_vcErrorMessage+' '+@o_vcJsonOutput
              SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
			  CLOSE CURSOR_ReKycQRequest;
	          DEALLOCATE CURSOR_ReKycQRequest;
              RETURN 1  
		    END	
		 END TRY
	     BEGIN CATCH
		    SET @o_vcFlag = 'E'
            SET @o_vcMessage = ERROR_MESSAGE()
            SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
			CLOSE CURSOR_ReKycQRequest;
	        DEALLOCATE CURSOR_ReKycQRequest;
	  
            RETURN 1  
	        END CATCH 		  
		 END  
	    FETCH NEXT FROM CURSOR_ReKycQRequest INTO @strRekycReplTag
	  END;
	  CLOSE CURSOR_ReKycQRequest;
	  DEALLOCATE CURSOR_ReKycQRequest;
	  
	  SET @o_vcFlag = 'S'
      SET @o_vcMessage = 'Process Completed'
      SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
      RETURN 1  
    END	
  END

  IF @strModuleName = 'PLEDGEREQ' AND @i_vcmode IN('ADD' ,'EDIT')
  BEGIN
    DECLARE @strPLClientCode1 VARCHAR(50)='', @strPLScripCode1 VARCHAR(50)='', @strPleReplTag INT = 0, 
	@strReqQty INT = 0, @strPLPledgeType VARCHAR(50)=''
	
	
	IF EXISTS(SELECT 1 FROM @tbl_InputJSONTable WHERE HeaderName = 'SecondLevelData' AND ParameterName = 'ClientCode' 
	AND ISNULL(ParameterValue,'') <> '')
    BEGIN
	
	  DECLARE CURSOR_PledgeQRequest
	  CURSOR FOR SELECT DISTINCT JsonTag
	  FROM @tbl_InputJSONTable
	  WHERE HeaderName = 'SecondLevelData'

	  OPEN CURSOR_PledgeQRequest
      FETCH NEXT FROM CURSOR_PledgeQRequest INTO @strPleReplTag
     
	  WHILE @@FETCH_STATUS = 0
	  BEGIN
	    SET @strPLClientCode1  = ''
		SET @strPLScripCode1 = ''
		SET @strReqQty  = 0
		SET @strPLPledgeType = ''
		
		SELECT @strPLClientCode1 = ParameterValue
        FROM @tbl_InputJSONTable
        WHERE ParameterName = 'ClientCode'
	    and HeaderName = 'SecondLevelData'
	    and jsontag = @strPleReplTag
		
		SELECT @strPLScripCode1 = ParameterValue
        FROM @tbl_InputJSONTable
        WHERE ParameterName = 'ScripCode'
	    and HeaderName = 'SecondLevelData'
	    and jsontag = @strPleReplTag
		
		SELECT @strPLPledgeType = ParameterValue
        FROM @tbl_InputJSONTable
        WHERE ParameterName = 'PledgeType'
	    and HeaderName = 'SecondLevelData'
	    and jsontag = @strPleReplTag
		
		
		SELECT @strReqQty = ParameterValue
        FROM @tbl_InputJSONTable
        WHERE ParameterName = 'RequestQty'
	    AND HeaderName = 'SecondLevelData'
	    AND jsontag = @strPleReplTag
		
		
		
		IF isnull(@strReqQty,0) > 0
		BEGIN
		  
		  DELETE FROM PledgeRequest WHERE Rq_Clientcd = @strPLClientCode1 AND Rq_Scripcd = @strPLScripCode1
		  AND Rq_Date = CONVERT(VARCHAR,GETDATE(),112) AND Rq_Status1 = 'X' AND Rq_Status2 = 'B' AND 
		  Rq_Status3 = CASE WHEN @strPLPledgeType = 'Pledge' THEN 'P' ELSE 'R' END
		  
		  INSERT INTO PledgeRequest(Rq_Clientcd, Rq_DematActNo, Rq_Scripcd, Rq_Qty, Rq_IpAddress, 
          Rq_Date, Rq_Time, Rq_Status1, Rq_Status2, Rq_Status3, Rq_Status4, Rq_Note)
          VALUES(@strPLClientCode1,'', @strPLScripCode1, @strReqQty, @i_vcUserCode, CONVERT(VARCHAR,GETDATE(),112),
		  REPLACE(CONVERT(VARCHAR,GETDATE(),108),':',''), 'X','B',CASE WHEN @strPLPledgeType = 'Pledge' THEN 'P' ELSE 'R' END,
		  DBO.fn_EncryptStringTW(CONVERT(VARCHAR,GETDATE(),112)),'')
		END  
		
	    FETCH NEXT FROM CURSOR_PledgeQRequest INTO @strPleReplTag
	  END;

	  CLOSE CURSOR_PledgeQRequest;
	  DEALLOCATE CURSOR_PledgeQRequest;
	  
	  SET @o_vcFlag = 'S'
      SET @o_vcMessage = 'Insert Sucessfully'
      SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
      RETURN 1  
    END	
  END
  IF @strModuleName = 'GetDataUserAccess' AND @i_vcmode IN('ADD' ,'EDIT')
  BEGIN
    DECLARE @Masterxml XML,  @Detailxml XML
    SELECT @Masterxml = @dsXml.query('/dsXml/X_Data/Master');
    SET @Detailxml = @dsXml.query('/dsXml/X_Data/items');
    DECLARE @GroupCode VARCHAR(50);
    SET @GroupCode = @Masterxml.value('(//GroupCode/text())[1]', 'VARCHAR(50)');
    
	DECLARE @tbl_MasterTable TABLE(GroupCode VARCHAR(50),  ButtonText VARCHAR(100), isEnabled VARCHAR(1), Mkrid VARCHAR(50), Mkrdt VARCHAR(10))
    
	INSERT INTO @tbl_MasterTable(GroupCode, ButtonText, isEnabled, Mkrid, Mkrdt)
    SELECT  @GroupCode, n.value('local-name(.)', 'VARCHAR(100)') AS ButtonText,
    CASE n.value('.', 'VARCHAR(10)')
        WHEN 'True' THEN 'Y'
        ELSE 'N'
    END AS isEnabled,
    SYSTEM_USER,
    CONVERT(VARCHAR(8), GETDATE(), 112)
    FROM @Masterxml.nodes('/Master/*') AS x(n); 
    
	--SELECT * FROM @tbl_MasterTable

    UPDATE A SET A.isEnabled = B.isEnabled
    FROM tbl_GroupUserAccessMaster A, @tbl_MasterTable B
    WHERE A.GroupCode = B.GroupCode
    AND B.ButtonText <> 'GroupCode'
    and A.ButtonText = B.ButtonText

    INSERT INTO tbl_GroupUserAccessMaster(GroupCode, ButtonText, isEnabled, Mkrid, Mkrdt)
    SELECT GroupCode, ButtonText, isEnabled, Mkrid, Mkrdt
    FROM @tbl_MasterTable X
    WHERE NOT EXISTS(SELECT 1 FROM tbl_GroupUserAccessMaster(NOLOCK)
    WHERE GroupCode = X.GroupCode AND ButtonText= X.ButtonText)
    and x.ButtonText  <> 'GroupCode'


    DECLARE @tbl_GroupUserAccessDetail TABLE (MenuCode VARCHAR(50), GroupCode VARCHAR(50), ButtonText VARCHAR(50), isEnabled VARCHAR(1), 
    Mkrid VARCHAR(50), Mkrdt VARCHAR(8))

    INSERT INTO @tbl_GroupUserAccessDetail (MenuCode, GroupCode, ButtonText, isEnabled, Mkrid, Mkrdt)
    SELECT  
    i.value('(MenuCode/text())[1]', 'VARCHAR(60)') AS MenuCode,
    i.value('(GroupCode/text())[1]', 'VARCHAR(50)') AS GroupCode,
    n.value('local-name(.)', 'VARCHAR(100)') AS ButtonText,
    CASE n.value('.', 'VARCHAR(10)')
        WHEN 'True' THEN 'Y'
        WHEN 'false' THEN 'N'
		ELSE 'X'
    END AS isEnabled,
    SYSTEM_USER,
    CONVERT(VARCHAR(8), GETDATE(), 112)
    FROM  @Detailxml.nodes('/items/item') AS x(i)
    CROSS APPLY i.nodes('*') AS t(n)


    DELETE FROM @tbl_GroupUserAccessDetail WHERE isEnabled = 'X'

    UPDATE A SET A.isEnabled = B.isEnabled
    FROM tbl_GroupUserAccessDetail A, @tbl_GroupUserAccessDetail B
    WHERE A.GroupCode = B.GroupCode
    AND B.ButtonText Not in ('GroupCode','MenuCode','MenuName','MenuTag','ParentMenu')
    AND A.MenuCode = B.MENUCODE
    and A.ButtonText = B.ButtonText


    INSERT INTO tbl_GroupUserAccessDetail(GroupCode, MenuCode, ButtonText, isEnabled, Mkrid, Mkrdt)
    SELECT GroupCode, MenuCode, ButtonText, isEnabled, Mkrid, Mkrdt
    FROM @tbl_GroupUserAccessDetail X
    WHERE NOT EXISTS(SELECT 1 FROM tbl_GroupUserAccessDetail(NOLOCK)
    WHERE GroupCode = X.GroupCode AND ButtonText= X.ButtonText AND MenuCode = X.MENUCODE)
    AND x.ButtonText Not in ('GroupCode','MenuCode','MenuName','MenuTag','ParentMenu')
    and ISNULL(x.MenuCode,'') <> ''
	
	SET @o_vcFlag = 'S'
    SET @o_vcMessage = 'Insert Sucessfully'
    SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
    RETURN 1  
  END
  IF @strModuleName = 'OffLineMarginPledge' AND @i_vcmode IN('ADD' ,'EDIT')
  BEGIN
    IF EXISTS(SELECT 1 FROM @tbl_InputJSONTable WHERE HeaderName = 'SecondLevelData' AND ParameterName = 'ScripCode' 
	AND ISNULL(ParameterValue,'') <> '')
    BEGIN
      DECLARE @PledgeJsonTag VARCHAR(10) = '', @strRetain INT = 0, @strTotalQty INT = 0, @strPLBenefCode VARCHAR(20)='',
	  @strPLClientCode VARCHAR(20)='', @strPLScripCode VARCHAR(20)='', @strPIP VARCHAR(100)=''


	  SELECT TOP 1 @strPIP = ParameterValue 
	  FROM @tbl_InputJSONTable WHERE ParameterName = 'IPAddress'
	

	  DECLARE CURSOR_PledgeRequest
	  CURSOR FOR SELECT DISTINCT JsonTag
	  FROM @tbl_InputJSONTable
	  WHERE HeaderName = 'SecondLevelData'

	  OPEN CURSOR_PledgeRequest
      FETCH NEXT FROM CURSOR_PledgeRequest INTO @PledgeJsonTag
     
	  WHILE @@FETCH_STATUS = 0
	  BEGIN
	    SET @strRetain = 0
		SET @strTotalQty = 0
		SET @strPLBenefCode = ''
		SET @strPLClientCode = ''
		SET @strPLScripCode = ''
		
	    SELECT @strRetain = CAST(ParameterValue AS INT)
        FROM @tbl_InputJSONTable
        WHERE ParameterName = 'Retain'
	    and HeaderName = 'SecondLevelData'
	    and jsontag = @PledgeJsonTag
  
        SELECT @strTotalQty = CAST(ParameterValue AS INT)
        FROM @tbl_InputJSONTable
        WHERE ParameterName = 'TotalQty'
	    and HeaderName = 'SecondLevelData'
	    and jsontag = @PledgeJsonTag
  
          
        SELECT @strPLClientCode = ParameterValue
        FROM @tbl_InputJSONTable
        WHERE ParameterName = 'ClientCode'
	    and HeaderName = 'SecondLevelData'
	    and jsontag = @PledgeJsonTag
  
        SELECT @strPLBenefCode = ParameterValue
        FROM @tbl_InputJSONTable
        WHERE ParameterName = 'BenefCode'
	    and HeaderName = 'SecondLevelData'
	    and jsontag = @PledgeJsonTag
    
        SELECT @strPLScripCode = ParameterValue
        FROM @tbl_InputJSONTable
        WHERE ParameterName = 'ScripCode'
	    and HeaderName = 'SecondLevelData'
	    and jsontag = @PledgeJsonTag
        
		IF ISNULL(@strTotalQty,0) < ISNULL(@strRetain,0)
		BEGIN
		  SET @o_vcFlag = 'F'
	      SET @o_vcMessage = 'Total Qty should not be less then Retain Qty'
	      SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
	      RETURN 1
        END
		
		IF ISNULL(@strRetain,0) <= 0
		BEGIN
		  SET @o_vcFlag = 'F'
	      SET @o_vcMessage = 'Retain Qty should not be less then or equal to Zero'
	      SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
	      RETURN 1
        END
		
	    IF ISNULL(@strTotalQty,0) >=  ISNULL(@strRetain,0) and ISNULL(@strRetain,0)  > 0
	    BEGIN
	      DELETE FROM PledgeRequest WHERE Rq_Clientcd = @strPLClientCode
		  AND Rq_Scripcd = @strPLScripCode AND Rq_DematActNo = @strPLBenefCode
          AND Rq_Status1 = 'P' 

          INSERT INTO PledgeRequest(Rq_Clientcd, Rq_DematActNo, Rq_Scripcd, Rq_Qty, Rq_IpAddress, 
          Rq_Date, Rq_Time, Rq_Status1, Rq_Status2, Rq_Status3, Rq_Status4, Rq_Note)
          VALUES(@strPLClientCode, @strPLBenefCode, @strPLScripCode, @strRetain, @strPIP, CONVERT(VARCHAR,GETDATE(),112),
		   REPLACE(CONVERT(VARCHAR,GETDATE(),108),':',''), 'P','C','P','', DBO.fn_EncryptStringTW(CONVERT(VARCHAR,GETDATE(),112)))
        END
	    FETCH NEXT FROM CURSOR_PledgeRequest INTO @PledgeJsonTag
	  END;

	  CLOSE CURSOR_PledgeRequest;
	  DEALLOCATE CURSOR_PledgeRequest;
	  SET @o_vcFlag = 'S'
      SET @o_vcMessage = 'Insert Sucessfully'
      SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
      RETURN 1  
    END	
  END
  
  IF @strModuleName NOT IN('FundRequest','OffLineMarginPledge','PLEDGEREQ')
  BEGIN
	DECLARE @strMasterTableName VARCHAR(100), @strMasterAutoGenColumnName VARCHAR(500), 
	@strMasterPrimaryKeyName VARCHAR(500), @strDetailTableName VARCHAR(500), 
	@strDetailAutoGenColumnName VARCHAR(500), @strDetailPrimaryKeyName VARCHAR(500), 
	@strValidationSPName VARCHAR(100), @strDefaultMasterXML VARCHAR(MAX) = '', 
	@strDefaultDetailXML VARCHAR(MAX) = ''

	SELECT @strMasterTableName = MasterTableName, @strMasterAutoGenColumnName = MasterAutoGenColumnName, 
	@strMasterPrimaryKeyName = MasterPrimaryKeyName, @strDetailTableName = DetailTableName, 
	@strDetailAutoGenColumnName = DetailAutoGenColumnName, @strDetailPrimaryKeyName = 
	DetailPrimaryKeyName, @strValidationSPName = ValidationSPName, @strDefaultMasterXML = 
	DefaultMasterXML, @strDefaultDetailXML = DefaultDetailXML, @DeleteMasterPrimaryKey = 
	DeleteMasterPrimaryKey, @DeleteDetailPrimaryKey = DeleteDetailPrimaryKey
	FROM tbl_InsertUpdateConfig(NOLOCK)
	WHERE ModuleName = @strModuleName
	

	UPDATE A
	SET A.ParameterName = B.FieldName
	FROM @tbl_InputJSONTable A, tbl_GenericTemplateDefinition(NOLOCK) B
	WHERE B.TemplateName = @strModuleName AND A.ParameterName = B.TagName

	IF ISNULL(@strValidationSPName, '') <> ''
	BEGIN
	  SET @strString = 'EXEC DBO.' + @strValidationSPName + ' ''' + @strXMl + ''', @o_vcFlag OUTPUT, @o_vcMessage OUTPUT';
      BEGIN TRY
		EXEC sp_executesql @strString, N'@o_vcFlag VARCHAR(1) OUTPUT, @o_vcMessage VARCHAR(500) OUTPUT', @o_vcFlag OUTPUT, @o_vcMessage OUTPUT;
	  END TRY

	  BEGIN CATCH
		SELECT @strString
        SET @o_vcFlag = 'F'
		SET @o_vcMessage = '<Message>' + @o_vcMessage + '</Message>'
        RETURN 1
	  END CATCH
	END

	IF @o_vcFlag <> 'S'
	BEGIN
	  RETURN 1
	END

	DECLARE @tbl_DataValidate TABLE (ColumnName VARCHAR(100), ColumnValue VARCHAR(MAX), MasterTag VARCHAR(100), JsonLevel VARCHAR(10), 
			ColumnDescp VARCHAR(100), ValidationValue VARCHAR(MAX), ValidationMessage VARCHAR(MAX), 
			ValidationQuery VARCHAR(MAX))

	INSERT INTO @tbl_DataValidate (ColumnName, ColumnValue, MasterTag, JsonLevel)
	SELECT ParameterName, ParameterValue, HeaderName, Jsontag
	FROM @tbl_InputJSONTable

	UPDATE A 
	SET A.ColumnDescp = B.TagName, A.ValidationValue = B.ValidationValue, 
	A.ValidationMessage = B.ValidationMessage, A.ValidationQuery = B.ValidationQuery
	FROM @tbl_DataValidate A, tbl_GenericTemplateDefinition(NOLOCK) B
	WHERE B.TemplateName = @strModuleName AND A.ColumnName = B.FieldName

	DECLARE @TBL_OutputJSON TABLE (ErrorTag VARCHAR(100), ErrorMessage VARCHAR(MAX))
	DECLARE @strColumnValue VARCHAR(MAX) = '', @strColumnName VARCHAR(100) = '', 
	@strValidationValue VARCHAR(500), @strValidationmessage VARCHAR(MAX) = ''

	DECLARE CurValidation CURSOR
	FOR SELECT ColumnValue = (CASE WHEN ColumnValue = 'True' THEN 'Y' WHEN ColumnValue = 'False' THEN 'N' ELSE ColumnValue END), 
	ColumnName = ColumnDescp, ValidationValue, ValidationMessage 
	FROM @tbl_DataValidate m
	WHERE ValidationValue <> '' AND ColumnValue <> '' AND ValidationValue NOT IN ('GETDATE', 'GETDATE,FUTUREDATE', 'GETDATE,PASTDATE')

	OPEN CurValidation;

	FETCH NEXT FROM CurValidation
	INTO @strColumnValue, @strColumnName, @strValidationValue, @strValidationmessage

	WHILE @@FETCH_STATUS = 0
	BEGIN
	  IF NOT EXISTS (SELECT 1 FROM ( SELECT VALUE AS ColumnValue 
	  FROM dbo.ReturnTable(@strValidationValue, '|')) x1 WHERE x1.ColumnValue = @strColumnValue)
	  BEGIN
		INSERT INTO @TBL_OutputJSON (ErrorTag, ErrorMessage)
		VALUES ('E', ISNULL(@strColumnName, '') + ' Value Should be ' + iif(@strValidationmessage = '', 
						@strValidationValue, @strValidationmessage))
	  END

	  FETCH NEXT FROM CurValidation
	  INTO @strColumnValue, @strColumnName, @strValidationValue, @strValidationmessage
	END;

	CLOSE CurValidation;
	DEALLOCATE CurValidation;
	
	DECLARE CurDateValidation 
	CURSOR FOR
	SELECT ColumnValue = (CASE WHEN ColumnValue = 'True' THEN 'Y' WHEN ColumnValue = 'False' THEN 'N' ELSE ColumnValue END), 
	ColumnName = ColumnDescp, ValidationValue, ValidationMessage 
	FROM @tbl_DataValidate m 
	WHERE ValidationValue <> '' AND ColumnValue <> '' AND ValidationValue IN ('GETDATE', 'GETDATE,FUTUREDATE', 'GETDATE,PASTDATE')

	OPEN CurDateValidation;

	FETCH NEXT FROM CurDateValidation
	INTO @strColumnValue, @strColumnName, @strValidationValue, @strValidationmessage

	WHILE @@FETCH_STATUS = 0
	BEGIN
	  IF ISDATE(@strColumnValue) = 0
	  BEGIN
		INSERT INTO @TBL_OutputJSON (ErrorTag, ErrorMessage)
		VALUES ('E', ISNULL(@strColumnName, '') + ' Value Should be in Date Format')
	  END

	  IF @strValidationValue = 'GETDATE' AND ISDATE(@strColumnValue) > 0
	  BEGIN
		IF CONVERT(VARCHAR, CAST(@strColumnValue AS DATE), 112) <> CONVERT(VARCHAR, GETDATE(), 112)
		BEGIN
		  INSERT INTO @TBL_OutputJSON (ErrorTag, ErrorMessage)
		  VALUES ('E', ISNULL(@strColumnName, '') + ' Value Should be in Todays Date')
	    END
	  END

	  IF @strValidationValue = 'GETDATE,FUTUREDATE' AND ISDATE(@strColumnValue) > 0
	  BEGIN
		IF CONVERT(VARCHAR, CAST(@strColumnValue AS DATE), 112) < CONVERT(VARCHAR, GETDATE(), 112)
		BEGIN
		  INSERT INTO @TBL_OutputJSON (ErrorTag, ErrorMessage)
		  VALUES ('E', ISNULL(@strColumnName, '') + ' Value Should be in Todays Date or Future Date')
		END
	  END

	  IF @strValidationValue = 'GETDATE,PASTDATE' AND ISDATE(@strColumnValue) > 0
	  BEGIN
		IF CONVERT(VARCHAR, CAST(@strColumnValue AS DATE), 112) > CONVERT(VARCHAR, GETDATE(), 112)
		BEGIN
		  INSERT INTO @TBL_OutputJSON (ErrorTag, ErrorMessage)
          VALUES ('E', ISNULL(@strColumnName, '') + ' Value Should be in Todays Date or Previous Date')
		 END
	  END

	  FETCH NEXT FROM CurDateValidation
	  INTO @strColumnValue, @strColumnName, @strValidationValue, @strValidationmessage
	END;

	CLOSE CurDateValidation;
	DEALLOCATE CurDateValidation;
	
 	DECLARE @StrAutoKeyName VARCHAR(100) = '', @strAutoKeyValue VARCHAR(10) = ''
	DECLARE @tbl_AutoIncrement TABLE (ColumnValue VARCHAR(100))

	IF ISNULL(@strMasterAutoGenColumnName, '') <> '' AND @i_vcmode = 'add'
	BEGIN
	  DECLARE CURSOR_MasterAuto CURSOR
	  FOR 
	  SELECT VALUE AS KeyName 
	  FROM DBO.RETURNTABLE(@strMasterAutoGenColumnName, '|');

	  OPEN CURSOR_MasterAuto
	  FETCH NEXT FROM CURSOR_MasterAuto INTO @strAutoKeyName
	  WHILE @@FETCH_STATUS = 0
  	  BEGIN
		DELETE FROM @tbl_AutoIncrement
        SET @strString = 'SELECT MAX(' + @StrAutoKeyName + ')+1 FROM ' + @strMasterTableName + ' '
		
		INSERT INTO @tbl_AutoIncrement (ColumnValue)
		EXEC (@strString)

		SELECT @strAutoKeyValue = ColumnValue
		FROM @tbl_AutoIncrement

		INSERT INTO @tbl_InputJSONTable (ParameterName, ParameterValue, HeaderName, Jsontag)
		SELECT @strAutoKeyName, @strAutoKeyValue, 'MasterLevelData', '1'

		FETCH NEXT FROM CURSOR_MasterAuto INTO @StrAutoKeyName
	  END
      CLOSE CURSOR_MasterAuto
      DEALLOCATE CURSOR_MasterAuto
	END

	DECLARE @strTempColumnName NVARCHAR(MAX) = '', @strTempColumnValue NVARCHAR(MAX) = ''

	SET @strColumnValue = ''
	SET @strColumnName = ''

	IF CURSOR_STATUS('global', 'CURSOR_BIND') >= - 1
	BEGIN
	  CLOSE CURSOR_BIND
   	  DEALLOCATE CURSOR_BIND
	END

		--- MASTER DATA INSERT / UPDATE   
	DECLARE @strUsercode VARCHAR(10) = ''

	SELECT TOP 1 @strUsercode = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'Userid'

	DECLARE @DefaultXML XML

	IF ISNULL(@strDefaultMasterXML, '') <> ''
	BEGIN
	  SET @DefaultXML = CAST(@strDefaultMasterXML AS XML)

	  INSERT INTO @tbl_InputJSONTable (HeaderName, ParameterName, ParameterValue, Jsontag)
	  SELECT * FROM (
	  SELECT 'MasterLevelData' AS MasterTag, c.value('local-name(.)', 'NVARCHAR(MAX)') AS ColumnName, 
	  REPLACE(c.value('(./text())[1]', 'NVARCHAR(MAX)'), '##USERID##', @strUsercode) AS ColumnValue, 
	  JsonLevel = '1'
	  FROM @DefaultXML.nodes('/DefaultXml/*') AS t(c)) X1
	  WHERE X1.ColumnName NOT IN (SELECT ParameterName FROM @tbl_InputJSONTable)
	END

	DECLARE @o_iReturnMasterSlNo INT = 0
	DECLARE @strwhere VARCHAR(MAX) = '', @strSQLString VARCHAR(MAX) = ''
	DECLARE @xmlOutput1 XML, @o_vcDataOutput1 VARCHAR(MAX) = ''
	DECLARE @MasterDeleteQuery VARCHAR(MAX) = '', @PreDetailDeleteQuery VARCHAR(MAX) = '', 
	@PostDetailDeleteQuery VARCHAR(MAX) = '', @DeleteUserid VARCHAR(50) = ''

	IF @strMasterTableName <> ''
	BEGIN
	  UPDATE A
	  SET A.ParameterName = B.FieldName
	  FROM @tbl_InputJSONTable A, tbl_GenericTemplateDefinition(NOLOCK) B
	  WHERE B.TemplateName = @strModuleName AND A.ParameterName = B.TagName

	  IF @i_vcmode = 'Delete'
	  BEGIN
		DELETE FROM @tbl_PrimaryKey
        INSERT INTO @tbl_PrimaryKey (KeyName)
		SELECT VALUE FROM DBO.RETURNTABLE(@DeleteMasterPrimaryKey, '|')

		UPDATE A
		SET A.KeyValue = B.ParameterValue
		FROM @tbl_PrimaryKey A, @tbl_InputJSONTable B
		WHERE A.KeyName = B.ParameterName

		SET @strwhere = ''

		SELECT @strwhere = @strwhere + ' ' + ' AND ' + KeyName + ' = ''' + CAST(KeyValue AS VARCHAR) + ''''
		FROM @tbl_PrimaryKey
		WHERE isnull(KeyValue, '') <> ''

		IF EXISTS (SELECT 1 FROM @tbl_PrimaryKey WHERE isnull(KeyValue, '') = '')
		BEGIN
		  SET @o_vcFlag = 'F'
		  SET @o_vcMessage = '<Message>Primary Key Value Not Avaiable in XML</Message>'

		  RETURN 1
		END
		IF EXISTS (SELECT 1 FROM tbl_InsertUpdateXMLDropDownQuery(NOLOCK)
		WHERE ModuleName = @strModuleName AND ColumnName = 'MasterDeleteEvent')
		BEGIN
		  SELECT @MasterDeleteQuery = DBQUERY
		  FROM tbl_InsertUpdateXMLDropDownQuery
		  WHERE ModuleName = @strModuleName AND ColumnName = 'MasterDeleteEvent'

		  SELECT @DeleteUserid = ParameterValue
		  FROM @tbl_InputJSONTable
		  WHERE ParameterName = 'UserId' AND HeaderName = ''

		  SET @MasterDeleteQuery = REPLACE(@MasterDeleteQuery, '<<Userid>>', @DeleteUserid)
		  SET @MasterDeleteQuery = REPLACE(@MasterDeleteQuery, '<<XWHERE>>', @strwhere)
	    END

		SET @strSQLString = 'Delete from ' + @strMasterTableName + ' WHERE 1 = 1 ' + @strwhere
		BEGIN TRANSACTION
        BEGIN TRY
		  EXEC (@MasterDeleteQuery)
          EXEC (@strSQLString)
          COMMIT;
		END TRY

		BEGIN CATCH
			ROLLBACK;
			SET @o_vcFlag = 'F'
			SET @o_vcMessage = '<Message>' + error_message() + '</Message>'
			RETURN 1
		END CATCH

		SET @o_vcFlag = 'S'
		SET @o_vcMessage = '<Message>Record Deleted</Message>'
		RETURN 1
	  END

	  IF @strModuleName IN ('TradeListing') AND UPPER(@i_vcmode) in('edit','add')
	  BEGIN
		DECLARE @td_marketrate MONEY = (
		SELECT ParameterValue
		FROM @tbl_InputJSONTable X1
		WHERE HeaderName = 'MasterLevelData' AND ParameterName = 'td_marketrate')
		
		DECLARE @td_brokerage MONEY = (SELECT ParameterValue
		FROM @tbl_InputJSONTable X1
		WHERE HeaderName = 'MasterLevelData' AND ParameterName = 'td_brokerage')
						
		DECLARE @td_Bqty MONEY = (
		SELECT ParameterValue
		FROM @tbl_InputJSONTable X1
		WHERE HeaderName = 'MasterLevelData' AND ParameterName = 'td_Bqty')	
	    
		DECLARE @td_Sqty MONEY = 
		(SELECT ParameterValue
		FROM @tbl_InputJSONTable X1
		WHERE HeaderName = 'MasterLevelData' AND ParameterName = 'td_Sqty')							

		INSERT INTO @tbl_InputJSONTable (ParameterName, ParameterValue, HeaderName, Jsontag)
		VALUES ('td_Rate', (ISNULL(@td_marketrate, 0) + (ISNULL(@td_brokerage, 0)/(ISNULL(@td_Bqty,0)+ISNULL(@td_Sqty,0)))), 'MasterLevelData', '1')
	 END
	 ELSE IF @strModuleName IN ('ReceiptsEntry') AND UPPER(@i_vcmode) in('edit','add')
	  BEGIN
	   DECLARE @strrc_accyear VARCHAR(8) = '', @Strrc_receiptdt VARCHAR(15)='',@rc_dpid VARCHAR(8)=''

	    SELECT @Strrc_receiptdt = ParameterValue  FROM @tbl_InputJSONTable X1
		WHERE HeaderName = 'MasterLevelData' AND ParameterName = 'rc_receiptdt'
	
		SELECT @Strrc_receiptdt = cast(FORMAT(CAST(@Strrc_receiptdt AS DATE),'dd-MM-yyyy') as varchar)
	
		SELECT @strrc_accyear = dbo.fnGetAccYearFromDate(@Strrc_receiptdt)
		INSERT INTO @tbl_InputJSONTable(ParameterName, ParameterValue, HeaderName, Jsontag)
		VALUES('rc_accyear',@strrc_accyear, 'MasterLevelData', '1')
	
		INSERT INTO @tbl_InputJSONTable(ParameterName, ParameterValue, HeaderName, Jsontag)
		VALUES('mkrtm', CONVERT(VARCHAR,GETDATE(),108), 'MasterLevelData', '1')				

		  UPDATE A SET A.ParameterValue = CAST(A.ParameterValue AS MONEY) * -1
		  FROM @tbl_InputJSONTable A  WHERE ParameterName = 'rc_amount'

		  Set @rc_dpid = (Select  ParameterValue FROM @tbl_InputJSONTable A  WHERE ParameterName = 'rc_dpid')
	 END

	 SET @xmlOutput1 = (SELECT ParameterName, ParameterValue, HeaderName
	 FROM @tbl_InputJSONTable X1
	 WHERE HeaderName = 'MasterLevelData' FOR XML PATH('DATA1'))
	 SET @o_vcDataOutput1 = CAST(@xmlOutput1 AS VARCHAR(MAX))
	 SET @o_vcMessage = ''

     

	 EXEC stpr_GenericInsertUpdateTable @o_vcDataOutput1, @strMasterTableName, @i_vcmode, @i_vcUserCode, 
	 @strMasterPrimaryKeyName, @o_iReturnMasterSlNo OUTPUT, @o_vcFlag OUTPUT, @o_vcMessage OUTPUT

	 IF @o_vcFlag = 'S' AND @strModuleName = 'ReceiptsEntry' and UPPER(@i_vcmode) = 'ADD'
      BEGIN
	    Set @srNo = (Select  ParameterValue FROM @tbl_InputJSONTable A  WHERE ParameterName = 'rc_srno')
	    SET @o_vcMessage = 'Serial No for Receipts Entry is ' + CAST(Isnull(@srNo,0) AS VARCHAR)
		Declare  @clientCd varchar(20) = (Select  ParameterValue FROM @tbl_InputJSONTable A  WHERE ParameterName = 'rc_clientcd')
		  
		IF @strModuleName IN ('ReceiptsEntry') AND UPPER(@i_vcmode) = 'ADD' AND @o_vcFlag = 'S' 
        BEGIN
	      IF NOT EXISTS (SELECT 1 FROM Auth_accounts(NOLOCK) WHERE aa_documenttype = 'R' 
	      AND aa_amount <= (SELECT SUM(abs(rc_amount)) FROM RECEIPTS(NOLOCK) 
	      WHERE rc_debitflag = 'C' AND rc_srno = @srNo AND rc_accyear = @strrc_accyear and rc_dpid = @rc_dpid))
	      BEGIN
	        UPDATE RECEIPTS SET rc_status = 'Y', rc_authid1 = '', rc_authid2 = '' , rc_commondt = rc_receiptdt
	        WHERE rc_srno = @srNo AND rc_accyear = @strrc_accyear
            AND rc_dpid = @rc_dpid
		  		 
	        INSERT INTO Ledger (
				ld_documentno, ld_clientcd, ld_amount, ld_documenttype, ld_debitflag, ld_chequeno, 
				ld_particular, ld_dt, ld_entryno, ld_accyear, ld_dpid, mkrid, ld_commondt, ld_common, 
				ld_costcenter, Mkrdt
				)
            SELECT rc_srno, rc_clientcd, rc_amount, 'R', rc_debitflag, rc_chequeno, rc_particular, rc_receiptdt, rc_entryno, 
				rc_accyear, rc_dpid, @i_vcUserCode, rc_commondt, rc_common, rc_costcenter, CONVERT(VARCHAR,GETDATE(),112)
	        FROM RECEIPTS(NOLOCK)
	        WHERE rc_accyear = @strrc_accyear AND rc_srno = @srNo AND rc_dpid = @rc_dpid AND rc_status = 'Y'
	      END
	      ELSE
	      BEGIN
	        UPDATE RECEIPTS SET rc_status = 'N', rc_authid1 = '', rc_authid2 = '' 
	        WHERE rc_srno = @srNo AND rc_accyear = @strrc_accyear
            AND rc_dpid = @rc_dpid
	      END
		  -------- For Image saving ------
		   Declare  @imageFile nvarchar(max) = (Select  ParameterValue FROM @tbl_InputJSONTable A  WHERE ParameterName = 'ImageFile')
		   If Isnull(@imageFile,'') <> ''
		   Begin
			   DECLARE @BinaryData VARBINARY(MAX) = CAST('' AS XML).value('xs:base64Binary(sql:variable("@imageFile"))', 'VARBINARY(MAX)');
			   Insert into ImageReceipts Values (@srNo,@rc_dpid,@clientCd,@BinaryData,@Strrc_receiptdt)
		  End
        END
      END

   END

   IF @strDetailTableName <> ''
   BEGIN
	 UPDATE A
	 SET A.ParameterName = B.FieldName
	 FROM @tbl_InputJSONTable A, tbl_GenericTemplateDefinition(NOLOCK) B
	 WHERE B.TemplateName = @strModuleName AND A.ParameterName = B.TagName

	 IF @i_vcmode = 'Delete'
	 BEGIN
	   DELETE FROM @tbl_PrimaryKey
 	   INSERT INTO @tbl_PrimaryKey (KeyName)
	   SELECT VALUE FROM DBO.RETURNTABLE(@DeleteDetailPrimaryKey, '|')

	   UPDATE A
	   SET A.KeyValue = ISNULL(B.ParameterValue, '')
	   FROM @tbl_PrimaryKey A, @tbl_InputJSONTable B
	   WHERE A.KeyName = B.ParameterName

	   SET @strwhere = ''

	   SELECT @strwhere = @strwhere + ' ' + ' AND ' + KeyName + ' = ''' + CAST(KeyValue AS VARCHAR) + ''''
	   FROM @tbl_PrimaryKey
	   WHERE isnull(KeyValue, '') <> ''

	   IF EXISTS (SELECT 1
	   FROM @tbl_PrimaryKey
	   WHERE isnull(KeyValue, '') = '')
	   BEGIN
		 SET @o_vcFlag = 'F'
		 SET @o_vcMessage = '<Message>Primary Key Value Not Avaiable in XML</Message>'
 		 RETURN 1
	   END
       DECLARE @tb_instcd VARCHAR(20) = '', @tb_internal_refno VARCHAR(50) = ''
       
	   IF EXISTS (SELECT 1
	   FROM tbl_InsertUpdateXMLDropDownQuery(NOLOCK)
	   WHERE ModuleName = @strModuleName AND ColumnName LIKE '%DetailDeleteEvent')
	   BEGIN
		 SELECT @PreDetailDeleteQuery = DBQUERY
		 FROM tbl_InsertUpdateXMLDropDownQuery
         WHERE ModuleName = @strModuleName AND ColumnName = 'PREDetailDeleteEvent'

		 SELECT @PostDetailDeleteQuery = DBQUERY
		 FROM tbl_InsertUpdateXMLDropDownQuery
		 WHERE ModuleName = @strModuleName AND ColumnName = 'PostDetailDeleteEvent'

		 SET @PreDetailDeleteQuery = REPLACE(@PreDetailDeleteQuery, '<<XWHERE>>', @strwhere)
		 SET @PostDetailDeleteQuery = REPLACE(@PostDetailDeleteQuery, '<<XWHERE>>', @strwhere)

		 SELECT @DeleteUserid = ParameterValue
		 FROM @tbl_InputJSONTable
		 WHERE ParameterName = 'UserId' AND HeaderName = ''

		 SET @PreDetailDeleteQuery = REPLACE(@PreDetailDeleteQuery, '<<Userid>>', @DeleteUserid)
		 SET @PostDetailDeleteQuery = REPLACE(@PostDetailDeleteQuery, '<<Userid>>', @DeleteUserid)
	   END
   	   SET @strSQLString = 'Delete from ' + @strDetailTableName + ' WHERE 1 = 1 ' + @strwhere
   	   BEGIN TRANSACTION
   	   BEGIN TRY
		 EXEC (@PreDetailDeleteQuery)
  		 EXEC (@strSQLString)
 		 EXEC (@PostDetailDeleteQuery)
		 COMMIT;
	   END TRY
  	   BEGIN CATCH
		  ROLLBACK;
  		  SET @o_vcFlag = 'F'
		  SET @o_vcMessage = '<Message>' + error_message() + '</Message>'
          RETURN 1
	   END CATCH
       SET @o_vcFlag = 'S'
	   SET @o_vcMessage = '<Message>Record Deleted</Message>'
	   RETURN 1
	 END

	 DECLARE @icurJsonTag VARCHAR(10) = ''

	 DECLARE CURSOR_DetailInsert 
	 CURSOR 
	 FOR 
	 SELECT DISTINCT JsonTag
	 FROM @tbl_InputJSONTable
	 WHERE HeaderName = @strSecondLevelData

	 OPEN CURSOR_DetailInsert
     FETCH NEXT FROM CURSOR_DetailInsert INTO @icurJsonTag
     
	 WHILE @@FETCH_STATUS = 0
	 BEGIN
	   IF ISNULL(@strDefaultDetailXML, '') <> ''
	   BEGIN
		 SET @DefaultXML = CAST(@strDefaultDetailXML AS XML)
 		 INSERT INTO @tbl_InputJSONTable (HeaderName, ParameterName, ParameterValue, Jsontag)
		 SELECT * 
		 FROM (SELECT @strSecondLevelData AS MasterTag, c.value('local-name(.)', 'NVARCHAR(MAX)') AS 
		 ColumnName, c.value('(./text())[1]', 'NVARCHAR(MAX)') AS ColumnValue, 
		 JsonLevel = @icurJsonTag
		 FROM @DefaultXML.nodes('/DefaultXml/*') AS t(c)) X1
		 WHERE X1.ColumnName NOT IN (SELECT ParameterName
		 FROM @tbl_InputJSONTable
		 WHERE Jsontag = @icurJsonTag)
	   END
	   UPDATE A
	   SET A.ParameterName = B.FieldName
	   FROM @tbl_InputJSONTable A, tbl_GenericTemplateDefinition(NOLOCK) B
	   WHERE B.TemplateName = @strModuleName AND A.ParameterName = B.TagName

	   DECLARE @Jsontag VARCHAR(10) = ''

	   IF ISNULL(@strDetailAutoGenColumnName, '') <> '' AND (@i_vcmode = 'add' OR 
	   EXISTS (SELECT 1 
	   FROM @tbl_InputJSONTable
	   WHERE ParameterName = 'IsInserted' AND ParameterValue = 'true' AND Jsontag = @icurJsonTag))
	   BEGIN
		 DECLARE CURSOR_DetailAuto CURSOR
		 FOR
		 SELECT Jsontag, KeyName 
		 FROM (SELECT DISTINCT Jsontag
		 FROM @tbl_InputJSONTable
		 WHERE HeaderName = @strSecondLevelData 
		 AND Jsontag = @icurJsonTag) A, 
		 (SELECT VALUE AS KeyName
		 FROM DBO.RETURNTABLE(@strDetailAutoGenColumnName, '|')) B;
         
		 OPEN CURSOR_DetailAuto
         FETCH NEXT FROM CURSOR_DetailAuto
		 INTO @Jsontag, @strAutoKeyName

	  	 WHILE @@FETCH_STATUS = 0
		 BEGIN
		   DELETE FROM @tbl_AutoIncrement
           SET @strString = 'SELECT MAX(' + @StrAutoKeyName + ')+' + @Jsontag + ' FROM ' + @strDetailTableName + ' '
		   
		   INSERT INTO @tbl_AutoIncrement (ColumnValue)
		   EXEC (@strString)

		   SELECT @strAutoKeyValue = ColumnValue
		   FROM @tbl_AutoIncrement

		   INSERT INTO @tbl_InputJSONTable (ParameterName, ParameterValue, HeaderName, Jsontag)
		   SELECT @strAutoKeyName, @strAutoKeyValue, @strSecondLevelData, @Jsontag

		   FETCH NEXT FROM CURSOR_DetailAuto
		   INTO @Jsontag, @StrAutoKeyName
		  END
          CLOSE CURSOR_DetailAuto
          DEALLOCATE CURSOR_DetailAuto
		END
		
		SET @xmlOutput1 = (SELECT DISTINCT ParameterName, ParameterValue = ltrim(rtrim(ParameterValue)), HeaderName
	    FROM (SELECT ParameterName, ParameterValue, HeaderName
        FROM @tbl_InputJSONTable X
		WHERE HeaderName = @strSecondLevelData 
		AND JSONTAG = @icurJsonTag
		UNION ALL
		SELECT ParameterName, ParameterValue, HeaderName = @strSecondLevelData
		FROM @tbl_InputJSONTable
		WHERE HeaderName = 'MasterLevelData' 
		AND ISNULL(@strMasterTableName, '') = '') X1
		FOR XML PATH('DATA1'))
		SET @o_vcDataOutput1 = CAST(@xmlOutput1 AS VARCHAR(MAX))

		BEGIN TRANSACTION;
		BEGIN TRY
		  EXEC stpr_GenericInsertUpdateTable @o_vcDataOutput1, @strDetailTableName, @i_vcmode, 
		  @i_vcUserCode, @strDetailPrimaryKeyName, @o_iReturnMasterSlNo OUTPUT, @o_vcFlag OUTPUT, 
		  @o_vcMessage OUTPUT

		  COMMIT TRANSACTION;
		END TRY

		BEGIN CATCH
			ROLLBACK TRANSACTION;
			SET @o_vcMessage = ERROR_MESSAGE();
			RETURN
		END CATCH

		FETCH NEXT FROM CURSOR_DetailInsert
		INTO @icurJsonTag
	  END

	  CLOSE CURSOR_DetailInsert
      DEALLOCATE CURSOR_DetailInsert
	END

	RETURN 1
  END
END
GO

CREATE PROCEDURE stpr_GetXMLExceldata @i_vcReportCode VARCHAR(50), @i_vcReportCategory VARCHAR(50), @MenuTag VARCHAR(50),
@settUserType VARCHAR(50), 
@o_XMLData VARCHAR(MAX) OUTPUT AS
BEGIN

  DECLARE  @MenuName VARCHAR(100)=''
   SELECT TOP 1 @MenuName = MenuName
      FROM tbl_TradeWebMenu(NOLOCK) WHERE  MenuTag = @MenuTag

  DECLARE @TotalList VARCHAR(MAX)='', @RightList VARCHAR(MAX)='',@HideList VARCHAR(MAX)='',
  @DateFormat VARCHAR(50)='DD-MMM-YYYY',@DateFormatList VARCHAR(MAX)='', @Dec2List VARCHAR(MAX)='', @Dec4List VARCHAR(MAX)='',
  @DrCRColorList VARCHAR(MAX)='', @PnLColorList VARCHAR(MAX)='', @PrimaryKey VARCHAR(MAX)='', @strReportHeader VARCHAR(500)=''
	 
  SELECT @TotalList = @TotalList+','+ColumnHeading
  FROM tbl_ReportGridViewFormat(NOLOCK) 
  WHERE ReportCode = @i_vcReportCode
  AND ReportCategroy = @i_vcReportCategory
  and ColumnTotal ='Y' 
  AND ISNULL(ProductCode,'') = ''
	  
  SELECT @RightList = @RightList+','+ColumnHeading
  FROM tbl_ReportGridViewFormat(NOLOCK) 
  WHERE ReportCode = @i_vcReportCode
   AND ReportCategroy = @i_vcReportCategory
   and ColumnAlignement ='R'
   AND ISNULL(ProductCode,'') = ''
	  
  SELECT @DateFormatList = @DateFormatList+','+ColumnHeading
  FROM tbl_ReportGridViewFormat(NOLOCK) 
  WHERE ReportCode = @i_vcReportCode
   AND ReportCategroy = @i_vcReportCategory
   and ColumnFormat <> ''
   AND ISNULL(ProductCode,'') = ''
	  
  SELECT @Dec2List = @Dec2List+','+ColumnHeading
  FROM tbl_ReportGridViewFormat(NOLOCK) 
  WHERE ReportCode = @i_vcReportCode
   AND ReportCategroy = @i_vcReportCategory
   and DecimalPlace = 2
   AND ISNULL(ProductCode,'') = ''
	  
  SELECT @HIDEList = @HIDEList+','+ColumnHeading
   FROM tbl_ReportGridViewFormat(NOLOCK) 
  WHERE ReportCode = @i_vcReportCode
	AND ReportCategroy = @i_vcReportCategory
	and ColumnVisible = 1
	AND ISNULL(ProductCode,'') = ''
	  
	  
  SELECT @DrCRColorList = @DrCRColorList+','+ColumnHeading
   FROM tbl_ReportGridViewFormat(NOLOCK) 
  WHERE ReportCode = @i_vcReportCode
    AND ReportCategroy = @i_vcReportCategory
	and ColumnStyle = 'B'
	AND ISNULL(ProductCode,'') = ''
	  

  DECLARE @MobileColumns VARCHAR(MAX)='', @TabletColumns VARCHAR(MAX)='',@WebColumns VARCHAR(MAX)=''
	 
  SELECT @MobileColumns = @MobileColumns+','+ CASE WHEN ColumnType <> 'DPGRID' then ColumnHeading else ColumnName end
	FROM tbl_ReportGridViewFormat(NOLOCK) 
	WHERE ReportCode = @i_vcReportCode
	  AND ReportCategroy = @i_vcReportCategory
	  AND Productid = 'M'
	  and ColumnVisible = 0
	  AND ISNULL(ProductCode,'') = ''
	  and ((@settUserType = 'Client' and CASE WHEN ColumnType <> 'DPGRID' then ColumnHeading else ColumnName end not in('Client Code','Client Name'))
	  or @settUserType <> 'Client')
	  ORDER BY ORDERBY
	 
  SET @MobileColumns = SUBSTRING(@MobileColumns,2,LEN(@MobileColumns))
	 
  SELECT @TabletColumns = @TabletColumns+','+ CASE WHEN ColumnType <> 'DPGRID' then ColumnHeading else ColumnName end
	FROM tbl_ReportGridViewFormat(NOLOCK) 
   WHERE ReportCode = @i_vcReportCode
	 AND ReportCategroy = @i_vcReportCategory
	 AND Productid IN('T','M')
	 and ColumnVisible = 0
	 AND ISNULL(ProductCode,'') = ''
	 and ((@settUserType = 'Client' and CASE WHEN ColumnType <> 'DPGRID' then ColumnHeading else ColumnName end not in('Client Code','Client Name'))
	 or @settUserType <> 'Client')
	 ORDER BY ORDERBY
	 
   SET @TabletColumns = SUBSTRING(@TabletColumns,2,LEN(@TabletColumns))
	 
  SELECT @WebColumns = @WebColumns+','+CASE WHEN ColumnType <> 'DPGRID' then ColumnHeading else ColumnName end
	FROM tbl_ReportGridViewFormat(NOLOCK) 
   WHERE ReportCode = @i_vcReportCode
	 AND ReportCategroy = @i_vcReportCategory
	 and ColumnVisible = 0
	 AND ISNULL(ProductCode,'') = ''
	 and ((@settUserType = 'Client' and CASE WHEN ColumnType <> 'DPGRID' then ColumnHeading else ColumnName end not in('Client Code','Client Name'))
	 or @settUserType <> 'Client')
	 --AND Productid NOT IN('T','M')
	 ORDER BY ORDERBY
	 
   SET @WebColumns = SUBSTRING(@WebColumns,2,LEN(@WebColumns))
		  
   DECLARE @CompanyName VARCHAR(100) = Isnull((select em_name from Entity_Master with (nolock) 
   where em_cd =(select min(em_cd) from Entity_master)),'')
   DECLARE @CompanyAdd1 VARCHAR(1000) = '', @CompanyAdd2 VARCHAR(1000) = '', @CompanyAdd3 VARCHAR(1000) = ''

   SELECT @CompanyName = em_name, @CompanyAdd1 = '', @CompanyAdd2 = '', @CompanyAdd3 = ''
   FROM Entity_Master(NOLOCK) 
   WHERE em_cd = (select min(em_cd) from Entity_master(NOLOCK))
     
   SET @o_XMLData = '<TotalList>'+ISNULL(@TotalList,'')+'</TotalList>'
						+' <RightList>'+ISNULL(@RightList,'')+'</RightList>' 
						+' <HideList>'+ISNULL(@HIDEList,'')+'</HideList>'
						+' <DateFormat>'+ISNULL(@DateFormat,'')+'</DateFormat>'
						+' <DateFormatList>'+ISNULL(@DateFormatList,'')+'</DateFormatList>'
						+' <Dec2List>'+ISNULL(@Dec2List,'')+'</Dec2List>'
						+' <Dec4List></Dec4List>'
						+' <DrCRColorList>'+ISNULL(@DrCRColorList,'')+'</DrCRColorList>'
						+' <PnLColorList></PnLColorList>'
						+' <PrimaryKey></PrimaryKey>'
						+' <CompanyName>' + ISNULL(@CompanyName,'') + '</CompanyName>'
						+' <CompanyAdd1>' + ISNULL(@CompanyAdd1,'') +'</CompanyAdd1>'
						+' <CompanyAdd2>' + ISNULL(@CompanyAdd2,'') + '</CompanyAdd2>'
						+' <CompanyAdd3>' + ISNULL(@CompanyAdd3,'') + '</CompanyAdd3>'
						--+' <ReportHeader>'+ISNULL(@strReportHeader,'')+'</ReportHeader>'
						+' <PDFWidth>520</PDFWidth>'
						+' <PDFHeight>269</PDFHeight>'
						+' <MobileColumns>'+ISNULL(@MobileColumns,'')+'</MobileColumns>'
						+' <TabletColumns>'+ISNULL(@TabletColumns,'')+'</TabletColumns>'
						--+' <WebColumns>'+ISNULL(@WebColumns,'')+'</WebColumns>'
  RETURN 1
END	
GO

CREATE PROCEDURE [stpr_FetchEntryData] @dsXml XML
WITH ENCRYPTION
AS
BEGIN
	DECLARE @tbl_InputJSONTable DBO.tb_ParamList;
	DECLARE @o_ParameterList VARCHAR(max) = '', @o_ParameterListxml XML;
	DECLARE @strXMl VARCHAR(MAX) = CAST(@dsXml AS VARCHAR(MAX))
	EXEC SP_ParameterXMLRep @dsXml, @o_ParameterList OUTPUT
	IF ISNULL(@o_ParameterList, '') <> ''
	BEGIN
		SET @o_ParameterListxml = CAST(@o_ParameterList AS XML)
		INSERT INTO @tbl_InputJSONTable (ParameterName, ParameterValue, HeaderName, Jsontag)
		SELECT Parameter.value('(ColumnName)[1]', 'VARCHAR(MAX)') AS Client_Code, Parameter.value(
				'(ColumnValue)[1]', 'VARCHAR(MAX)') AS ColumnValue, Parameter.value('(MasterTag)[1]', 
				'VARCHAR(MAX)') AS MasterTag, Parameter.value('(JsonLevel)[1]', 'VARCHAR(MAX)') AS JsonLevel
		FROM @o_ParameterListxml.nodes('/Parameter') AS XTbl(Parameter)
	END
	DECLARE @strModuleName VARCHAR(100) = '', @strString NVARCHAR(MAX), @strOption VARCHAR(100) = '',
	@strUserid VARCHAR(20)='', @strCompCode VARCHAR(1)='', @strClientCode VARCHAR(50)='', @strScripCode VARCHAR(20)='',
	@strFromDate VARCHAR(12)='', @strSettlementNo VARCHAR(40)='', @strToDate VARCHAR(12)='', @strBankUTRNo VARCHAR(100)='',
	@strSelection VARCHAR(10), @StrCode VARCHAR(500)
	
	SELECT @strModuleName = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'ActionName'
	
	SELECT @strOption = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'Option'
	
	SELECT TOP 1 @strUserid = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'Userid'
	
	SELECT TOP 1 @strClientCode = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'ClientCode'
	
	SELECT TOP 1 @strScripCode = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'ScripCode'
	
	SELECT TOP 1 @strFromDate = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'FromDate'
	
	SELECT TOP 1 @strToDate = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'ToDate'
	
    SELECT @strSelection = LTRIM(RTRIM(ParameterValue)) FROM @tbl_InputJSONTable WHERE ParameterName = 'Selection'
	SELECT @StrCode = LTRIM(RTRIM(ParameterValue)) FROM @tbl_InputJSONTable WHERE ParameterName in('Code','ClientCode')
	
	
	SELECT TOP 1 @strSettlementNo = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'SettlementNo'
	
	
	SELECT @strCompCode = em_cd from Entity_Master with (nolock) 
	WHERE em_cd =(select min(em_cd) from Entity_master)

    IF @strModuleName = 'TRADEWEB' 
	BEGIN
	  SET @strModuleName = @strOption
	  SET @strOption = 'FIND'
	END
	
	DECLARE @strClientString VARCHAR(MAX)=''
    SELECT @strClientString = DBO.fn_ReturnQueryAccess(@strUserid,@strSelection,@StrCode)
    IF ISNULL(@strClientString,'') = ''
    BEGIN  
	  SET @strClientString = ''
    END	
	
	
	DECLARE @strHeader VARCHAR(MAX)=''
	SET @strHeader = 'DECLARE @tbl_UserList TABLE(Client_Code VARCHAR(50)) '
  
    SET @strHeader = @strHeader+' INSERT INTO @tbl_UserList(Client_Code) '
    +' SELECT * FROM DBO.[fn_GetClients]('''+@strUserId+''','''','''')'
  
    IF @strModuleName = 'REKYCVALIDATE' AND @strOption = 'FIND'
	BEGIN
	  DECLARE @strRekycStatus VARCHAR(1)=''
	  
	  SELECT TOP 1 @strRekycStatus = ParameterValue
	  FROM @tbl_InputJSONTable
	  WHERE ParameterName = 'RekycStatus'
	
      SELECT rm_refno AS FormNo, rm_cmcd as ClientCode, cm_name AS ClientName, CONVERT(VARCHAR,rm_cdate,112) as EntryDate, 
      rm_ctime as EntryTime, rm_status as CurrentStatus, EntryName = rm_RequestType, 
	  FormType = CASE WHEN rm_RequestType = 'REKYCOFFLINE' THEN 'multientry'
	  WHEN rm_RequestType = 'REKYC' THEN 'rekyc'
	  WHEN rm_RequestType = 'ONLYCLOSURE' THEN 'ClientClosure'
	  ELSE 'entry' end,
	  Status = CASE WHEN rm_rekyc = 'Y' THEN 'Approved' 
      WHEN rm_rekyc = 'R' THEN 'Rejected' ELSE 'Pending'END, 
	  '' AS RekycDocumentType, rm_desc as Reason
	  
      FROM Client_ReKycMain(NOLOCK) X, CLIENT_MASTER(NOLOCK) CM
      WHERE 
	  ((@strRekycStatus = 'P' AND ((EXISTS(SELECT 1 FROM 
	  Client_ModifyAttach(NOLOCK) WHERE MA_cmcd = X.rm_cmcd AND ma_refno = X.rm_refno
	  AND ma_filename ='SignedPdf' AND ma_field IS NOT NULL) AND rm_rekyc = 'N' AND rm_RequestType <> 'REKYCOFFLINE')
	  OR (rm_RequestType ='REKYCOFFLINE' AND rm_step > 1 AND rm_rekyc = 'N' )))
	  
	  OR (@strRekycStatus = 'T' AND rm_rekyc = 'N' AND ((NOT EXISTS(SELECT 1 FROM 
	  Client_ModifyAttach(NOLOCK) WHERE MA_cmcd = X.rm_cmcd AND ma_refno = X.rm_refno
	  AND ma_filename ='SignedPdf' AND ma_field IS NOT NULL) AND rm_RequestType <> 'REKYCOFFLINE')
	  OR (rm_RequestType ='REKYCOFFLINE' AND rm_step = 1))) 
	  
	  OR (@strRekycStatus = 'R' AND rm_rekyc = 'R') 
	  OR (@strRekycStatus = 'A' AND rm_rekyc = 'Y'
	  AND X.mkrdt >= @strFromDate
	  AND X.mkrdt <= @strToDate) )
	  AND X.rm_cmcd = CM.CM_cD
	  AND ((CM.CM_cD = @strClientCode AND @strClientCode <> '') OR @strClientCode = '')
      Order By rm_cdate desc, rm_ctime desc
    END
	ELSE IF UPPER(@strModuleName) = 'RekycOffLine' AND @strOption = 'FIND'
	BEGIN
	  DECLARE @StrMulClientPANNo VARCHAR(20)='', @StrMulClientCode VARCHAR(20)=''
	  
	  SELECT @StrMulClientPANNo = ParameterValue
	  FROM @tbl_InputJSONTable
	  WHERE ParameterName = 'ClientPANNo'
		  
	  SELECT @StrMulClientCode = ParameterValue
	  FROM @tbl_InputJSONTable
	  WHERE ParameterName = 'ClientCode'
	  
	  SELECT CM_cd as [ClientCode],  cm_name as [Client Name], rm_refno as [FormNo],
	  CONVERT(VARCHAR,rm_cdate,112) as [Entry Date],  rm_ctime as [Entry Time],
	  @strModuleName as [EntryName],
	  CASE WHEN rm_step > 1 THEN 'true' else 'false' end as isUpdated, 
	  'true' isDeleted
	  from Client_Master(NOLOCK) LEFT OUTER JOIN Client_ReKycMain(NOLOCK) ON(CM_cd = rm_cmcd AND rm_rekyc = 'N' AND rm_status = 'Pending')
	  WHERE CM_cD = @StrMulClientCode
	   AND ((cm_panno = @StrMulClientPANNo OR ISNULL(@StrMulClientPANNo,'') <> '')
	   OR ISNULL(@StrMulClientPANNo,'') = '')
	  RETURN 1;
	END  
	ELSE
	IF @strModuleName = 'BankReceipts' AND @strOption = 'FIND'
	BEGIN
	  
	  SELECT TOP 1 @strBankUTRNo = ParameterValue
	  FROM @tbl_InputJSONTable
	  WHERE ParameterName = 'BankUTRNo'
	
      SELECT hrc_WebID as [Uniqueid] , rc_clientcd as [Client Code], cm_name as [Client Name], [Transaction Id] =  ''''+hrc_transactionId,
      [UTR No] = ''''+hrc_utr, [Credit Time] = hrc_creditTime ,hrc_Amount As [Receive Amount], 
      hrc_Status as [Status], AllocatedAmount = isnull(AllocatedAmount,0),  
      AllocateResponse = isnull(AllocateResponse,''), 
	  PGAllocatedAmount = isnull(PGAllocatedAmount,0),  PGAllocatedResponse = isnull(PGAllocatedResponse,''),
	  'true' as isUpdated, 'true'as isDeleted
      FROM API_Receipts(NOLOCK) XXX left outer join 
      (SELECT Refhrc_Webid, ReceiveDate, ClientCode, SUM(case when processtype =  'ALLOCATION' AND ResponseStatus IN('Y','X') 
	  THEN AllocationAmount ELSE 0 END) AllocatedAmount,
	  MAX(CASE WHEN processtype =  'ALLOCATION' then ResponseMessage else '' end) as AllocateResponse,
      SUM(CASE WHEN processtype =  'PG_LIMIT' AND ResponseStatus IN('Y') then ReceiveAmount ELSE 0 END) PGAllocatedAmount, 
      MAX(CASE WHEN processtype =  'PG_LIMIT' then ResponseMessage else '' end ) as PGAllocatedResponse
      FROM tbl_FundReceiptsLog_PGLIMIT(NOLOCK) xxx
      WHERE  serialno in(select max(serialno) from tbl_FundReceiptsLog_PGLIMIT(NOLOCK) 
      WHERE ReceiveDate = XXX.ReceiveDate  and Refhrc_Webid = xxx.Refhrc_Webid and ClientCode = xxx.ClientCode 
	  AND processtype = xxx.processtype AND VenderCode = XXX.VenderCode)
      GROUP BY Refhrc_Webid, ReceiveDate, ClientCode) x1 on(Refhrc_Webid = hrc_WebID AND hrc_creditDate = ReceiveDate), 
	  Receipts(nolock) , Client_Master(nolock) CM
      WHERE hrc_RecSrno = rc_srno 
      AND rc_receiptdt = hrc_creditDate
      AND hrc_dpid = rc_dpid
      --AND hrc_Status = 'S'
      AND rc_debitflag = 'C'
      AND hrc_creditDate >= CONVERT(VARCHAR,GETDATE(),112)
      and cm_schedule = 49843750
      AND rc_clientcd = CM.CM_cD
	  AND ((@strBankUTRNo <> '' AND hrc_utr = @strBankUTRNo ) OR @strBankUTRNo = '')
      ORDER BY hrc_WebID
    END
	
    ELSE IF @strModuleName = 'BUYBACK' AND @strOption = 'FIND'
	BEGIN
      DECLARE @dt VARCHAR(12)=CONVERT(VARCHAR,GETDATE(),112)
	
      DECLARE @dbdatabase VARCHAR(50)='', @dbOwner VARCHAR(50)='', @strOP_Product VARCHAR(20)=''
      SELECT @dbdatabase = LTRIM(RTRIM(OP_DataBase)), @dbOwner = LTRIM(RTRIM(OP_Owner)), @strOP_Product = LTRIM(RTRIM(OP_Product)) 
      FROM Other_Products(NOLOCK) WHERE OP_Product='Cross' AND OP_Status = 'A'
      IF ISNULL(@dbdatabase,'') = ''
	  BEGIN
	    SELECT @dbdatabase = LTRIM(RTRIM(OP_DataBase)), @dbOwner = LTRIM(RTRIM(OP_Owner)) , @strOP_Product = LTRIM(RTRIM(OP_Product)) 
        FROM Other_Products(NOLOCK) WHERE OP_Product='Estro' AND OP_Status = 'A'
      
	  END

      SET @strString = 'DECLARE @tbl_UserList TABLE(Client_Code VARCHAR(50)) '
      +' INSERT INTO @tbl_UserList(Client_Code) '
      +' SELECT * FROM DBO.[fn_GetClients]('''+@strUserId+''','''','''') '
      +' CREATE TABLE #TblHolding (ClientCode VARCHAR(50), ScripCode VARCHAR(10), ScripName VARCHAR(50), Exchange CHAR(5), '
      +' DematAccountNo VARCHAR(16), SettlementNo CHAR(9), CMP MONEY, Symbol CHAR(25), OfferDate VARCHAR(10), ExpiryDate VARCHAR(10), '
      +' TradeDate VARCHAR(10), SettlementDate VARCHAR(10), ISIN CHAR(12), Offers NUMERIC, Qty NUMERIC, TotalValue MONEY) '


      +' INSERT INTO #TblHolding '
      +' SELECT Client_Code, BB_ScripCd, ss_name, CASE WHEN se_exchange = ''N'' THEN ''NSE'' WHEN se_exchange = ''B'' THEN ''BSE'' ELSE ''''  '
      +' END, BB_DematAct, BB_Stlmnt, BB_Rate, ss_bsymbol + ''/'' + ss_nsymbol, ltrim(rtrim(convert(CHAR, convert(DATETIME, left(BB_DematAct, 8)), 103))),'
      +' ltrim(rtrim(convert(CHAR, convert(DATETIME, right(BB_DematAct, 8)), 103))), ltrim(rtrim(convert(CHAR, convert(DATETIME, '
      +' se_payoutdt), 103))), ltrim(rtrim(convert(CHAR, convert(DATETIME, se_payoutdt), 103)) ), im_isin, 0, 0, 0 '
      +' FROM BuyBacks(NOLOCK), Settlements(NOLOCK), Securities(NOLOCK), isin(NOLOCK), @tbl_UserList '
      +' WHERE ss_cd = BB_ScripCd AND BB_Stlmnt = se_stlmnt AND im_scripcd = BB_ScripCd  '
      +' AND im_active = ''Y'' AND im_priority = (SELECT min(im_priority) '
      +' FROM Isin(NOLOCK) WHERE im_active = ''Y'' AND im_scripcd = BB_ScripCd '
		+' ) AND se_endt >= '''+@dt+''' AND BB_clientcd = ''BUYBACK!'' and BB_ScripCd = '''+@strScripCode+''' ORDER BY se_stdt DESC, BB_ScripCd '

      +' UPDATE #TblHolding '
      +' SET Offers = BB_Qty '
      +' FROM Buybacks(NOLOCK) WHERE SettlementNo = BB_Stlmnt AND BB_status IN(''C'',''T'') AND ClientCode = BB_ClientCd '

      +' UPDATE A SET A.DematAccountNo = da_actno '
      +' FROM #TblHolding A, Dematact (NOLOCK) WHERE da_clientcd = ClientCode AND da_defaultyn = ''Y'' ' 

      IF @strOP_Product = 'CROSS'
      BEGIN	  
        SET @strString = @strString +' UPDATE #TblHolding '
        +' SET DematAccountNo = hld_ac_code, Qty = hld_ac_pos '
        +' FROM '+@dbdatabase+'.'+@dbOwner+'.Holding, '+@dbdatabase+'.'+@dbOwner+'.Client_master CM1, Dematact '
        +' WHERE hld_ac_code = da_actno AND da_defaultyn = ''Y'' AND hld_ac_type = ''11'' AND hld_isin_code = ISIN AND  '
        +' da_clientcd =ClientCode AND CM1.cm_cd = hld_ac_code '
      END
	  ELSE IF @strOP_Product = 'ESTRO'
	  BEGIN
	    SET @strString = @strString +' UPDATE #TblHolding '
        +' SET DematAccountNo = da_dpid+hld_ac_code, Qty = hld_ac_pos '
        +' FROM '+@dbdatabase+'.'+@dbOwner+'.Holding, '+@dbdatabase+'.'+@dbOwner+'.Client_master CM1, Dematact '
        +' WHERE hld_ac_code = da_actno AND da_defaultyn = ''Y'' AND hld_ac_type = ''22'' AND hld_isin_code = ISIN AND  '
        +' da_clientcd =ClientCode AND CM1.cm_cd = hld_ac_code '
	  END
	  
      SET @strString = @strString +' UPDATE #TblHolding '
      +' SET TotalValue = CMP * Offers '

      +' DELETE FROM #TblHolding WHERE Qty <= 0 '

      +' SELECT ClientCode, cm_name as ClientName, DematAccountNo, ScripCode, SettlementNo, convert(DECIMAL(15, 2), CMP) BuyBackRate, '
	  +' Qty As HoldingQty, Offers,  convert(DECIMAL(15, 2), TotalValue) TotalValue'
      +' FROM #TblHolding, CLIENT_MASTER(NOLOCK) CM WHERE ClientCode = CM_CD '
      +' DROP TABLE #TblHolding'
      EXEC(@strString)
	  
	  declare @strReportHeader VARCHAR(MAX)=''
	  SELECT @strReportHeader = 'Scrip :- '+ss_name+' / Exchange:- '+CASE WHEN se_exchange = 'N' THEN 'NSE' WHEN se_exchange = 'B' THEN 'BSE' ELSE ''  
	  END+' / Settlement:- '+BB_Stlmnt+' / Buy Back Rate:- '+CAST(BB_Rate AS VARCHAR)+' / Offer Date :- '+ltrim(rtrim(convert(CHAR, convert(DATETIME, left(BB_DematAct, 8)), 103))) +
	  ' / Expiry Date :- '+ltrim(rtrim(convert(CHAR, convert(DATETIME, right(BB_DematAct, 8)), 103)))
	  +' /Settlement  Date :- '+ltrim(rtrim(convert(CHAR, convert(DATETIME, se_payoutdt), 103)))+' / ISIN :- '+im_isin
      FROM BuyBacks(NOLOCK), Settlements(NOLOCK), Securities(NOLOCK), isin(NOLOCK)
      WHERE ss_cd = BB_ScripCd AND BB_Stlmnt = se_stlmnt AND im_scripcd = BB_ScripCd  
      AND im_active = 'Y' AND im_priority = (SELECT min(im_priority) 
      FROM Isin(NOLOCK) WHERE im_active = 'Y' AND im_scripcd = BB_ScripCd) 
	  AND se_endt >= CONVERT(VARCHAR,GETDATE(),112)   AND BB_clientcd = 'BUYBACK!' 
	  AND BB_ScripCd = @strScripCode
	  
      DECLARE @XMLStringFilter VARCHAR(MAX)=''
      SET @XMLStringFilter = '<XmlData>'
	  SET @XMLStringFilter = @XMLStringFilter+'<ReportHeader>'+ISNULL(@strReportHeader,'')+'</ReportHeader> '
	  SET @XMLStringFilter = @XMLStringFilter+'<Headings>'
      IF ISNULL(@strReportHeader,'') <> ''
      BEGIN
	    SET @XMLStringFilter = @XMLStringFilter+'<Heading>'+@strReportHeader+'</Heading>'				
      END                        
      SET @XMLStringFilter = @XMLStringFilter+'</Headings></XmlData>' 
      SELECT [Settings] = @XMLStringFilter
	  RETURN 1
    END 
	ELSE IF @strOption = 'Find' AND @strModuleName IN('FamilyMapping')
	BEGIN
	  SELECT CASE WHEN CF_cD = CF_FamilyCd THEN 'MAIN' ELSE '' END AS FamilyHead,
      CF_cD AS ClientCode, CM_NAME AS ClientName
      FROM  Client_Family(NOLOCK) x, client_master(NOLOCK) 
      WHERE CF_FamilyCd  = @strUserid
      AND CF_cD = CM_cD
      ORDER BY CASE WHEN CF_cD = CF_FamilyCd THEN 'MAIN' ELSE '' END DESC
	  RETURN 1
	END
	ELSE 
	IF @strOption = 'Find' AND @strModuleName NOT IN('BUYBACK','REKYCVALIDATE','FamilyMapping')
	BEGIN
		DECLARE @TargetTableName VARCHAR(100) = (
				SELECT TOP 1 TableName
				FROM tbl_GenericTemplateDefinition
				WHERE TemplateName = @strModuleName
				)
		DECLARE @Sql NVARCHAR(MAX) = N'SELECT ';
		DECLARE @Delimiter NVARCHAR(2) = ', ';
		DECLARE @DefaultXml XML = (
				SELECT TOP 1 DefaultMasterXML
				FROM tbl_InsertUpdateConfig
				WHERE ModuleName = @strModuleName 
				
				);
		DECLARE @ColumnDefinitions TABLE (ColumnName NVARCHAR(128), TagName NVARCHAR(128), OrderBy INT);
		INSERT INTO @ColumnDefinitions (ColumnName, TagName, OrderBy)
		SELECT FieldName, TagName, OrderBy
		FROM tbl_GenericTemplateDefinition
		WHERE TableName = @TargetTableName AND TemplateName = @strModuleName
		AND ISNULL(FieldName,'') <> '' AND ISNULL(DisplayLendingPage,'N') = 'Y'
		ORDER BY OrderBy;
		DECLARE @ColumnName NVARCHAR(128);
		DECLARE @TagName NVARCHAR(128);
		DECLARE ColumnCursor CURSOR
		FOR
		SELECT ColumnName, TagName
		FROM @ColumnDefinitions
		ORDER BY OrderBy;
		OPEN ColumnCursor;
		FETCH NEXT
		FROM ColumnCursor
		INTO @ColumnName, @TagName;
		WHILE @@FETCH_STATUS = 0
		BEGIN
			SET @Sql = @Sql + QUOTENAME(@ColumnName) + ' AS ' + QUOTENAME(@TagName) + @Delimiter;
			FETCH NEXT
			FROM ColumnCursor
			INTO @ColumnName, @TagName;
		END;
		CLOSE ColumnCursor;
		DEALLOCATE ColumnCursor;
		
		IF UPPER(@strModuleName) in('TradeListing')
		BEGIN
		   SET @Sql = @Sql +' CASE WHEN td_TRXFlag IN(''M'') AND td_TRDType = ''DL'' THEN ''false'' else ''true'' end as isUpdated, '
		   +' CASE WHEN td_TRXFlag IN(''M'') AND td_TRDType = ''DL'' THEN ''false'' else ''true'' end as isDeleted' +@Delimiter; 
        END   
	    ELSE IF UPPER(@strModuleName) in('ReceiptsEntry')
		BEGIN
		      SET @Sql = @Sql +' CASE WHEN rc_status IN(''N'',''Y'', '''') and Isnull(rc_authdt1,'''')<>'''' THEN ''false''  else ''false'' end as isUpdated, '
				  +' CASE WHEN rc_status IN(''N'',''Y'', '''') and Isnull(rc_authdt1,'''')<>'''' THEN ''false''  else ''false'' end as isDeleted' +@Delimiter;		
        END   

		SET @Sql = LEFT(@Sql, LEN(@Sql) - LEN(@Delimiter));
		SET @Sql = @Sql + ' FROM ' + QUOTENAME(@TargetTableName) + ' (NoLock)  ';
		DECLARE @SQL1 NVARCHAR(MAX) = '';
		
		
		IF UPPER(@strModuleName) in('TradeListing')
		BEGIN
		  SET @SQL1 = @SQL1 + ' , CLIENT_MASTER(NOLOCK) WHERE td_clientcd = CM_CD AND '+@strClientString
		  IF ISNULL(@strFromDate,'') <> ''
		  BEGIN
		     SET @SQL1 = @SQL1 + ' AND td_dt = '''+@strFromDate+''' '
		  END
		  IF ISNULL(@strScripCode,'') <> ''
		  BEGIN
		    SET @SQL1 = @SQL1 + ' AND td_Scripcd = '''+@strScripCode+''' '
		  END
		  
		  IF ISNULL(@strClientCode,'') <> ''
		  BEGIN
		    SET @SQL1 = @SQL1 + ' AND td_clientcd = '''+@strClientCode+''' '
		  END
		  IF ISNULL(@strSettlementNo,'') <> ''
		  BEGIN
		    SET @SQL1 = @SQL1 + ' AND td_stlmnt = '''+@strSettlementNo+''' '
		  END
		END			
		ELSE  IF UPPER(@strModuleName) in('ReceiptsEntry')
			BEGIN
			  SET @SQL1 = @SQL1 + ' , CLIENT_MASTER(NOLOCK) WHERE rc_clientcd = CM_CD AND '+@strClientString
			  SET @SQL1 = @SQL1 + '  AND rc_debitflag = ''C'' '
			  IF ISNULL(@strFromDate,'') <> ''
			  BEGIN
				 SET @SQL1 = @SQL1 + ' AND rc_receiptdt >= '''+@strFromDate+''' AND  rc_receiptdt <= '''+ISNULL(@strtoDate,@strFromDate)+''' '
			  END
			END
		ELSE
		BEGIN
		  SET @SQL1 = @SQL1 + ' where 1 = 1 '
		END
		
		DECLARE @param NVARCHAR(100), @value NVARCHAR(100);
		DECLARE @Cursor CURSOR;SET @Cursor = CURSOR
		FOR
		SELECT (
				SELECT FieldName
				FROM tbl_GenericTemplateDefinition
				WHERE TableName = @TargetTableName AND TemplateName = @strModuleName AND TagName = x.value(
						'local-name(.)', 'NVARCHAR(100)')
				) AS ParamName, x.value('(text())[1]', 'NVARCHAR(100)') AS ParamValue
		FROM @dsXml.nodes('/dsXml/X_Filter/*') AS T(x)
		
		UNION ALL
		
		SELECT y.value('local-name(.)', 'NVARCHAR(100)') AS ParamName, REPLACE(REPLACE(y.value('(text())[1]', 'NVARCHAR(100)'),'##USERID##',
		@strUserid),'##COMP##', @strCompCode)
			AS ParamValue
		FROM @DefaultXml.nodes('/DefaultXml/*') AS U(y);
		
		OPEN @Cursor;
		FETCH NEXT
		FROM @Cursor
		INTO @param, @value;
		WHILE @@FETCH_STATUS = 0
		BEGIN
			IF @param IS NOT NULL AND @value IS NOT NULL
			BEGIN
				SET @SQL1 = @SQL1 + ' AND ' + QUOTENAME(@param) + ' = ' + QUOTENAME(@value, '''');
			END
			FETCH NEXT
			FROM @Cursor
			INTO @param, @value;
		END
		CLOSE @Cursor;
		DEALLOCATE @Cursor;
		
		SET @Sql = @Sql + @SQL1
		--select @Sql
		EXEC sp_executesql @Sql;
		RETURN 1;
	END
	ELSE IF @strOption = 'Delete'
	BEGIN
		DECLARE @TargetTableName1 VARCHAR(100) = (
				SELECT TOP 1 TableName
				FROM tbl_GenericTemplateDefinition
				WHERE TemplateName = @strModuleName
				)
		DECLARE @strAutoGenColumnName VARCHAR(100) = (
				SELECT DetailAutoGenColumnName
				FROM tbl_InsertUpdateConfig
				WHERE ModuleName = @strModuleName
				)
		DECLARE @Sql2 NVARCHAR(MAX) = N'Delete from ' + @TargetTableName1;
		DECLARE @SQLWhere NVARCHAR(MAX) = '';
		DECLARE @strPriKeyValue INT;
		DECLARE @param1 NVARCHAR(100), @value1 NVARCHAR(100);
		DECLARE @Cursor1 CURSOR;DECLARE @tb_pri_key_found BIT = 0;SET @Cursor1 = CURSOR
		FOR
		SELECT (
				SELECT FieldName
				FROM tbl_GenericTemplateDefinition
				WHERE TableName = @TargetTableName1 AND TagName = x.value('local-name(.)', 'NVARCHAR(100)') AND 
					TemplateName = @strModuleName
				) AS ParamName, x.value('(text())[1]', 'NVARCHAR(100)') AS ParamValue
		FROM @dsXml.nodes('/dsXml/X_Filter/*') AS T(x)
		PRINT @param1
		OPEN @Cursor1;
		FETCH NEXT
		FROM @Cursor1
		INTO @param1, @value1;
		-- Loop through each element and build the WHERE clause
		WHILE @@FETCH_STATUS = 0
		BEGIN
			IF @param1 IS NOT NULL AND @value1 IS NOT NULL
			BEGIN
				IF @param1 = @strAutoGenColumnName
				BEGIN
					SET @tb_pri_key_found = 1;
					SET @strPriKeyValue = @value1;
				END
				SET @SQLWhere = @SQLWhere + ' AND ' + QUOTENAME(@param1) + ' = ' + QUOTENAME(@value1, '''');
			END
			FETCH NEXT
			FROM @Cursor1
			INTO @param1, @value1;
		END
		IF @tb_pri_key_found = 0
		BEGIN
			PRINT 'tb_pri_key was NOT found in the parameters.';
			RETURN 1;
		END
		CLOSE @Cursor1;
		DEALLOCATE @Cursor1;
		SET @SQLWhere = SUBSTRING(@SQLWhere, 5, LEN(@SQLWhere) - 4)
		PRINT (@SQL2 + ' WHERE ' + @SQLWhere)
		RETURN 1;
	END
	ELSE IF @strOption = 'display'
	BEGIN
		DECLARE @td_srno VARCHAR(50) = @dsXml.value('(/dsXml/X_Filter/SerialNo)[1]', 'VARCHAR(50)')
		IF UPPER(@strModuleName) = 'TradeListing'
		BEGIN
		  SELECT [TradeDate] = td_dt, [Settlement] = td_stlmnt, td_clientcd, [ScripCode] = td_scripcd, 
		  [BuySell] = td_bsflag, [BuyQty] = td_bqty, [SellQty] = td_Sqty, [MarketRate] = td_marketrate, [Brokerage] = td_brokerage, 
          [GST] = td_ServiceTax, [STT] = td_STT, [Charges1] = td_OtherChrgs1, [Charges2] = td_OtherChrgs2, [SerialNo] = td_srno
          FROM TRX_INVPL(NOLOCK) 
          WHERE td_TRDType = 'DL' AND td_TRXFlag ='M' 
		  and td_srno = @td_srno
		  --AND TD_DT >='20240401'
          ORDER BY td_scripcd, td_dt, td_bsflag 	
		END
		RETURN
	END
END
GO

CREATE PROCEDURE CommonSerch @i_vcinput XML, @o_vcFlag VARCHAR(1) OUTPUT, @o_vcMessage VARCHAR(MAX) OUTPUT
WITH ENCRYPTION
AS
BEGIN
  DECLARE @tbl_InputJSONTable DBO.tb_ParamList;
  DECLARE @o_ParameterList VARCHAR(max) = '', @o_ParameterListxml XML;
  DECLARE @strModuleName VARCHAR(50) = '', @strOption VARCHAR(50) = '', @strUserid VARCHAR(50)='',
  @strUserType VARCHAR(10), @strSelection varchar(1)='C', @strString VARCHAR(MAX)='', @strClientString VARCHAR(MAX)='',
  @strSearchQuery VARCHAR(MAX)='', @strUserAccess VARCHAR(50)=''
  
  EXEC SP_ParameterXMLRep @i_vcinput, @o_ParameterList OUTPUT
  DECLARE @tbl_UserList TABLE(ClientCode VARCHAR(50)) 
  IF ISNULL(@o_ParameterList, '') <> ''
  BEGIN
	SET @o_ParameterListxml = CAST(@o_ParameterList AS XML)

	INSERT INTO @tbl_InputJSONTable (ParameterName, ParameterValue, HeaderName, Jsontag)
	SELECT Parameter.value('(ColumnName)[1]', 'VARCHAR(MAX)') AS Client_Code, Parameter.value(
				'(ColumnValue)[1]', 'VARCHAR(MAX)') AS ColumnValue, Parameter.value('(MasterTag)[1]', 
				'VARCHAR(MAX)') AS MasterTag, Parameter.value('(JsonLevel)[1]', 'VARCHAR(MAX)') AS 
			JsonLevel
	FROM @o_ParameterListxml.nodes('/Parameter') AS XTbl(Parameter)
  END
	
  SELECT TOP 1 @strUserid = ParameterValue FROM @tbl_InputJSONTable where ParameterName = 'UserId'
  SELECT @strSelection = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Selection'
  SELECT @strUserType = REPLACE(ParameterValue,'null','')  FROM @tbl_InputJSONTable WHERE ParameterName = 'UserType'
  SELECT @strSearchQuery = REPLACE(ParameterValue,'null','')  FROM @tbl_InputJSONTable WHERE ParameterName = 'SearchQuery'
  SELECT @strUserAccess = REPLACE(ParameterValue,'null','')  FROM @tbl_InputJSONTable WHERE ParameterName = 'UserAccess'
  
  
  
  
  IF ISNULL(@strSelection,'C') = 'C'
  BEGIN
	SET @strSelection = 'C'
  END
  
  IF ISNULL(@strSearchQuery,'') = ''
  BEGIN
    SET @strSearchQuery = ''
  END
	
  DECLARE @strGROUPLOGIN VARCHAR(30)=''	
  SELECT @strGROUPLOGIN = sp_sysvalue 
  FROM WebParameter(NOLOCK) WHERE sp_parmcd = 'GROUPLOGIN'	
    
  IF ISNULL(@strUserType,'') ='user'
  BEGIN
	IF ISNULL(@strGROUPLOGIN,'') IN('Group','Family')
	BEGIN
      SET @strString = 'SELECT cm_cd FROM CLIENT_MASTER(NOLOCK) '
	  IF @strGROUPLOGIN = 'Group'
	  BEGIN
	    set @strString = @strString+' WHERE ISNULL(cm_groupcd,'''') <> ''ZZZ'' and cm_groupcd IN(SELECT DISTINCT cm_groupcd  '
	  END
	  ELSE IF @strGROUPLOGIN = 'Family'
      BEGIN
	    set @strString = @strString+' WHERE ISNULL(cm_familycd,'''') <> ''ZZZ'' and cm_familycd IN(SELECT DISTINCT cm_familycd  '
	  END
	  set @strString = @strString+' FROM CLIENT_MASTER(NOLOCK) '
	     +' WHERE CM_CD  = '''+@strUserid+''' )'
	  --select @strString	 
	  INSERT INTO @tbl_UserList 
	  EXEC(@strString)
	END  
	
	INSERT INTO @tbl_UserList
	SELECT @strUserid
    
	INSERT INTO @tbl_UserList
	SELECT CF_CD FROM  Client_Family(NOLOCK) XX WHERE CF_FamilyCd IN(
    SELECT CF_FamilyCd FROM Client_Family(NOLOCK) WHERE CF_CD = @strUserid)
	AND NOT EXISTS(SELECT 1 FROM @tbl_UserList WHERE ClientCode = XX.CF_CD)
	
	SELECT DISTINCT LTRIM(RTRIM(cm_cd)) AS [Value], cm_name + ' [' + cm_cd + ']' AS [DisplayName]
	FROM Client_master(NOLOCK) XMAIN, @tbl_UserList 
	WHERE cm_schedule = 49843750 
	AND CM_CD = ClientCode
  END
  ELSE
  BEGIN
	IF ISNULL(@strUserAccess,'') <> 'HO'
	BEGIN
	  SELECT @strClientString = DBO.fn_ReturnQueryAccess(@strUserid,'','')
	  IF ISNULL(@strClientString,'') = ''
	  BEGIN  
	    SET @strClientString = ''
	  END	
	END
    ELSE
    BEGIN
	  SET @strClientString = ' 1 = 1 '
    END	

	IF @strSelection = 'C'
	BEGIN
      SET @strString = 'SELECT DISTINCT TOP 100 LTRIM(RTRIM(cm_cd)) AS [Value], cm_name + '' ['' + cm_cd + '']'' AS [DisplayName] '
		+' FROM Client_master(NOLOCK) XMAIN '
		+' WHERE cm_schedule = ''49843750'' AND  ((CHARINDEX('''+@strSearchQuery+''',cm_name + '' ['' + cm_cd + '']'' ) > 0  AND '''+@strSearchQuery +''' <> '''')
		OR '''+@strSearchQuery +''' = '''') AND '+@strClientString +' ORDER BY 1 '
	END
	ELSE IF @strSelection = 'B'
	BEGIN
      SET @strString = 'SELECT DISTINCT LTRIM(RTRIM(bm_branchcd)) AS [Value], bm_branchname + '' ['' + bm_branchcd + '']'' AS [DisplayName]
		FROM branch_master WITH (NOLOCK)
		WHERE bm_branchcd <> '''' AND  ((CHARINDEX('''+@strSearchQuery+''',bm_branchname + '' ['' + bm_branchcd + '']'' ) > 0  AND '''+@strSearchQuery +''' <> '''')
		OR '''+@strSearchQuery +''' = '''') 
		AND bm_branchcd IN(SELECT DISTINCT cm_brboffcode FROM CLIENT_MASTER(NOLOCK) XMAIN WHERE cm_schedule = ''49843750''  AND '+@strClientString +') ' +' ORDER BY 1 '
	END
	ELSE IF @strSelection = 'G'
	BEGIN
      SET @strString = 'SELECT DISTINCT gr_cd AS [Value], gr_desc + '' ['' + gr_cd + '']'' AS [DisplayName]
		 FROM Group_master WITH (NOLOCK)
		 WHERE gr_cd IN(SELECT DISTINCT cm_groupcd FROM CLIENT_MASTER(NOLOCK) XMAIN WHERE cm_schedule = ''49843750''  AND '+@strClientString +') 
		 AND  ((CHARINDEX('''+@strSearchQuery+''',gr_desc + '' ['' + gr_cd + '']''  ) > 0  AND '''+@strSearchQuery +''' <> '''')
		 OR '''+@strSearchQuery +''' = '''')  ' +' ORDER BY 1 '
	END
	ELSE IF @strSelection = 'F'
	BEGIN
      SET @strString = 'SELECT DISTINCT fm_cd AS [Value], fm_desc + '' ['' + fm_cd + '']'' AS [DisplayName]
	  FROM Family_master WITH (NOLOCK)
	  WHERE fm_cd <> ''''
	  AND fm_cd IN(SELECT DISTINCT cm_familycd FROM CLIENT_MASTER(NOLOCK) XMAIN WHERE cm_schedule = ''49843750''  AND '+@strClientString  +') 
	  AND  ((CHARINDEX('''+@strSearchQuery+''',fm_desc + '' ['' + fm_cd + '']'' ) > 0  AND '''+@strSearchQuery +''' <> '''')
	  OR '''+@strSearchQuery +''' = '''')  ' +' ORDER BY 1 '
	END
	--SELECT @strString
	EXEC(@strString)
  END
  
END	
GO

CREATE PROCEDURE [stpr_ValidateTemplateData] @i_vcinput XML, @o_vcFlag VARCHAR(1) OUTPUT, @o_vcMessage VARCHAR(MAX) OUTPUT
WITH ENCRYPTION
AS
BEGIN
  DECLARE @tbl_InputJSONTable DBO.tb_ParamList;
  DECLARE @o_ParameterList VARCHAR(max) = '', @o_ParameterListxml XML, @strFlag VARCHAR(20)='';
  DECLARE @strModuleName VARCHAR(50) = '', @strOption VARCHAR(50) = '', @StrXML XML, @StrData1 VARCHAR(MAX)='' ,
  @strISIN VARCHAR(20)='', @strThirdPartyURL VARCHAR(MAX)='', @o_vcOutPutJSON VARCHAR(MAX)='', @strUserid VARCHAR(50)=''
  
	--- PARAMETER LIST  
  EXEC SP_ParameterXMLRep @i_vcinput, @o_ParameterList OUTPUT

  IF ISNULL(@o_ParameterList, '') <> ''
  BEGIN
	SET @o_ParameterListxml = CAST(@o_ParameterList AS XML)

	INSERT INTO @tbl_InputJSONTable (ParameterName, ParameterValue, HeaderName, Jsontag)
	SELECT Parameter.value('(ColumnName)[1]', 'VARCHAR(MAX)') AS Client_Code, Parameter.value(
				'(ColumnValue)[1]', 'VARCHAR(MAX)') AS ColumnValue, Parameter.value('(MasterTag)[1]', 
				'VARCHAR(MAX)') AS MasterTag, Parameter.value('(JsonLevel)[1]', 'VARCHAR(MAX)') AS JsonLevel
		FROM @o_ParameterListxml.nodes('/Parameter') AS XTbl(Parameter)
  END

  SELECT @strModuleName = ParameterValue
  FROM @tbl_InputJSONTable
  WHERE ParameterName = 'ActionName'

  SELECT @strOption = ParameterValue
  FROM @tbl_InputJSONTable
  WHERE ParameterName = 'Option'

  SELECT @strUserid = ParameterValue
  FROM @tbl_InputJSONTable
  WHERE ParameterName = 'Userid'
  
  DECLARE @strStep INT = 1, @i_vcRefNo INT = 0

  SELECT @strThirdPartyURL = sp_sysvalue 
  FROM Sysparameter(NOLOCK) WHERE sp_parmcd = 'ThirdParty'
  
  
  IF @strOption = 'TabChangeAPI'
  BEGIN
    declare @strConstitution1 VARCHAR(50)='', @strSubStatus1 VARCHAR(100)='',
	@strRekycClientCode1 VARCHAR(50)='', @strcm_dob VARCHAR(8)=''
	SELECT @strConstitution1 = ParameterValue
    FROM @tbl_InputJSONTable
    WHERE ParameterName = 'Constitution'
	
	SELECT @strSubStatus1 = ParameterValue
    FROM @tbl_InputJSONTable
    WHERE ParameterName = 'SubStatus'
	
	SELECT @strRekycClientCode1 = ParameterValue
    FROM @tbl_InputJSONTable
    WHERE ParameterName = 'ClientCode'
	
	SELECT @strcm_dob = cm_dob FROM Client_master(NOLOCK) WHERE cm_cd = @strRekycClientCode1
	
	IF (@strConstitution1 = 'Individual' AND CAST(DATEDIFF(YEAR,CAST(@strcm_dob AS DATE),GETDATE()) AS INT) > 18)
	BEGIN
	  SET @o_vcFlag = 'T'
	  SET @o_vcMessage = '<Message></Message><RelatedPersonDetails>false</RelatedPersonDetails>'
	  RETURN 1
	END
	ELSE
	BEGIN
	  SET @o_vcFlag = 'T'
	  SET @o_vcMessage = '<Message></Message><RelatedPersonDetails>true</RelatedPersonDetails>'
	  RETURN 1
	END
  END
  
  IF @strModuleName IN('REKYC') AND @strOption = 'IncomeDate_validate'
  BEGIN
	DECLARE @strIncome VARCHAR(10) ='', @strIncomeDate VARCHAR(15)='' , @strOldIncome VARCHAR(10) =''
	
	SELECT @strIncome = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'Income'
	
	SELECT @strIncomeDate = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'IncomeDate'
	
	SELECT @strOldIncome = cm_grossincome 
	FROM CLIENT_INFO(NOLOCK) WHERE cm2_CD = @strUserid
	
	IF @strIncome <> @strOldIncome
	BEGIN

	  IF DATEDIFF(MONTH,CAST(@strIncomeDate AS DATE),GETDATE()) > 12
	  BEGIN
	    SET @o_vcFlag = 'E'
	    SET @o_vcMessage = '<Message>Income Date Should not be less than 12 months</Message>'
		RETURN 1
	  END
	  
	  IF CAST(@strIncomeDate AS DATE)> CAST(getdate() AS DATE)
	  BEGIN
	    SET @o_vcFlag = 'E'
	    SET @o_vcMessage = '<Message>Income Date Should not be Future date</Message>'
		RETURN 1
	  END
	END
  END
  ELSE 
  IF @strModuleName IN('TradeListing') AND @strOption = 'BuySell_Validate'
  BEGIN
	DECLARE @strBuySell VARCHAR(1) =''
	SELECT @strBuySell = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'BuySell'
	IF ISNULL(@strBuySell,'') = 'B'
	BEGIN
      SET @o_vcFlag = 'D'
	  SET @o_vcMessage = '<Message></Message><SellQty>false</SellQty><BuyQty>true</BuyQty>'
		RETURN 1
	END
	ELSE IF ISNULL(@strBuySell,'') = 'S'
	BEGIN
      SET @o_vcFlag = 'D'
	  SET @o_vcMessage = '<Message></Message><BuyQty>false</BuyQty><SellQty>true</SellQty>'
		RETURN 1
	END
  END
  ELSE 
  IF @strModuleName IN('REKYCVALIDATE') AND @strOption = 'ReAppStatusv'
  BEGIN
	DECLARE @strRekycClientCode VARCHAR(20) ='', @strRekycFormNo VARCHAR(10)='',
	@strRekycStatus VARCHAR(10)='', @strRekycReason VARCHAR(MAX)=''
	
	SELECT @strRekycClientCode = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'ClientCode'
	
	SELECT @strRekycFormNo = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'FormNo'
	
	SELECT @strRekycStatus = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'Status'
	
	SELECT @strRekycReason = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'Reason'
	/*
	IF ISNULL(@strRekycStatus,'') = ''
	BEGIN
	  SET @o_vcFlag = 'E'
	  SET @o_vcMessage = '<Message>Status can not blank</Message>'
	  RETURN 1
	END
	
	IF NOT EXISTS(select 1 from Client_ReKycMain(nolock) where rm_cmcd = @strRekycClientCode 
    and  rm_refno = @strRekycFormNo and rm_status = 'Pending' and rm_rekyc = 'N') AND ISNULL(@strRekycStatus,'') <> ''
	BEGIN
	  SET @o_vcFlag = 'E'
	  SET @o_vcMessage = '<Message>Invalid Request</Message>'
	  RETURN 1
	END
	
	IF NOT EXISTS(SELECT 1 FROM Client_ModifyAttach  WHERE ma_cmcd = @strRekycClientCode 
	AND ma_refno = @strRekycFormNo AND ma_filename = 'SignedKRAPdf' AND ma_proof IS NOT NULL) AND ISNULL(@strRekycStatus,'') = 'A'
	BEGIN
	  SET @o_vcFlag = 'E'
	  SET @o_vcMessage = '<Message>KRA SIGN PDF NOT GENERATED</Message>'
	  RETURN 1
	END
	
    IF NOT EXISTS(SELECT 1 FROM Client_ModifyAttach  WHERE ma_cmcd = @strRekycClientCode 
	AND ma_refno = @strRekycFormNo AND ma_filename = 'SignedPdf' AND ma_proof IS NOT NULL)  AND ISNULL(@strRekycStatus,'') = 'A'
	BEGIN
	  SET @o_vcFlag = 'E'
	  SET @o_vcMessage = '<Message>FINAL SIGN PDF NOT GENERATED</Message>'
	  RETURN 1
	END*/
  END
  ELSE
  IF @strModuleName IN('PLEDGEREQ') AND @strOption = 'RequestQty'
  BEGIN
    DECLARE @strPRequestQty INT = 0 , @StrPQty INT = 0
	
	SELECT @strPRequestQty = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'RequestQty'
	
	SELECT @StrPQty = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'Qty'
	
	IF ISNULL(@strPRequestQty,0) <= 0
	BEGIN
	  SET @o_vcFlag = 'E'
	  SET @o_vcMessage = '<Message>Request qty can not be zero or less then zero</Message>'
	  RETURN 1
	END
	
	IF ISNULL(@strPRequestQty,0) > ISNULL(@StrPQty,0)
	BEGIN
	  SET @o_vcFlag = 'E'
	  SET @o_vcMessage = '<Message>Request qty can not be greater then Pledge Qty</Message>'
	  RETURN 1
	END
  END
  ELSE IF @strModuleName IN('Rekyc') AND @strOption = 'Validate_IFSC'
  BEGIN
	DECLARE @strIFSC VARCHAR(15) ='', @strBankName VARCHAR(200)='', @StrBKMICR VARCHAR(20)=''
	SELECT @strIFSC = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'BankIFSC'
	
	SELECT @strBankName = BK_NAME, @StrBKMICR = BK_MICR 
    FROM Bank_master(NOLOCK) WHERE bk_IFCCode = @strIFSC AND ISNULL(BK_MICR,'') <> ''
	IF ISNULL(@strBankName,'') <> ''
	BEGIN
	  SET @o_vcFlag = 'S'
	  SET @o_vcMessage = '<Message></Message><BankName>'+@strBankName+'</BankName><BankMICR>'+@StrBKMICR+'</BankMICR>'
	  RETURN 1
	END
	ELSE
	BEGIN
	  SET @o_vcFlag = 'S'
	  SET @o_vcMessage = '<Message>Bank Not Found In Bank Master</Message><BankName></BankName><BankMICR></BankMICR>'
	  RETURN 1
	END
  END
  ELSE IF @strModuleName IN('RekycOffLine') AND @strOption = 'Validate_ProofType'
  BEGIN
	DECLARE @strProofType VARCHAR(15) =''
	
	SELECT @strProofType = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'ProofType'
	
	if @strProofType IN('SignAttachment','PhotoAttachment')
	BEGIN
	  SET @o_vcFlag = 'D'
	  SET @o_vcMessage = '<Message></Message><DocumentType>false</DocumentType><DocumentName>false</DocumentName><DocumentNo>false</DocumentNo>'
	  RETURN 1
	END
	ELSE
	BEGIN
	  SET @o_vcFlag = 'D'
	  SET @o_vcMessage = '<Message></Message><DocumentType>true</DocumentType><DocumentName>true</DocumentName><DocumentNo>false</DocumentNo>'
	  RETURN 1
	END
  END
  ELSE IF @strModuleName IN('RekycOffLine') AND @strOption = 'Validate_DocumentType'
  BEGIN
	DECLARE @strDocumentType VARCHAR(15) ='', @str1ClientCode VARCHAR(50)='', @strDocumentNo VARCHAR(50)=''
	
	SELECT @strDocumentType = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'DocumentType'

	SELECT @str1ClientCode = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'ClientCode'

	
	IF EXISTS(SELECT 1 FROM CKYC_StaticCodes WHERE CS_DataType in('DocumentAttachment') 
	and CS_Description like '%PAN%' AND CS_DataTypeCd = @strDocumentType)
	BEGIN
	 SELECT @strDocumentNo = CM_PANNO FROM  CLIENT_MASTER(NOLOCK) WHERE CM_cD = @str1ClientCode
	END
	
	IF EXISTS(SELECT 1 FROM CKYC_StaticCodes WHERE CS_DataType in('DocumentAttachment') 
	and CS_Description like '%Aadhaar%' AND CS_DataTypeCd = @strDocumentType)
	BEGIN
	 SELECT @strDocumentNo = cm_uid FROM  CLIENT_INFO(NOLOCK) WHERE CM2_cD = @str1ClientCode
	END
	
	if (@strDocumentType like '%99' OR @strDocumentType IN('98','29'))
	BEGIN
	  SET @o_vcFlag = 'D'
	  SET @o_vcMessage = '<Message></Message><DocumentName>true</DocumentName><DocumentNo>true</DocumentNo>'
	  RETURN 1
	END
	ELSE
	BEGIN
	  IF ISNULL(@strDocumentNo,'') <> ''
	  BEGIN
	    SET @o_vcFlag = 'D'
	    SET @o_vcMessage = '<Message></Message><DocumentName>false</DocumentName><DocumentNo>'+@strDocumentNo+'</DocumentNo>'
	    RETURN 1
	  END
	  ELSE
	  BEGIN
	    SET @o_vcFlag = 'D'
	    SET @o_vcMessage = '<Message></Message><DocumentName>false</DocumentName><DocumentNo>true</DocumentNo>'
	    RETURN 1
	  END
	END
  END
  ELSE IF @strModuleName IN('Common') AND @strOption = 'BenefAccountNo'
  BEGIN
	DECLARE @strBenefClientCode VARCHAR(15) ='', @strPOAIDS VARCHAR(200) =''
	SELECT @strBenefClientCode = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'ClientCode'

	SELECT @strPOAIDS = sp_sysvalue FROM Sysparameter WHERE sp_parmcd = 'POADPIDS'
	
    SELECT CASE WHEN SUBSTRING(da_dpid,1,2)='IN' then da_actno else da_actno end
    AS [Value], CASE WHEN SUBSTRING(da_dpid,1,2)='IN' then da_actno else da_actno end
    AS [DisplayName] FROM Dematact(NOLOCK) WHERE  da_clientcd = @strBenefClientCode and sign(patindex('%'+rtrim(da_dpid)+'%', @strPOAIDS )) = 1
	
  END
  ELSE IF @strModuleName IN('OffLineMarginPledge') AND @strOption = 'Retain'
  BEGIN
	DECLARE @strRClientCode VARCHAR(15) ='', 
	@strRScripCode VARCHAR(15) ='', @strRSClosingPrice MONEY = 0, @strRSHaircut MONEY = 0, @strRSRetain INT=0,
	@ReqValue MONEY = 0, @strRSTotalQty INT = 0
		
	SELECT @strRSClosingPrice = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'ClosingPrice'
	
	SELECT @strRSHaircut = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'Haircut'
	
	SELECT @strRSRetain = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'Retain'
	
	SELECT @strRSTotalQty = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'TotalQty'
	
	IF ISNULL(@strRSRetain,0) <= 0
	BEGIN
	  SET @o_vcFlag = 'E'
	  SET @o_vcMessage = '<Message>Retain qty can not be zero or less then zero</Message>'
	  RETURN 1
	END
	
	IF ISNULL(@strRSRetain,0) >  ISNULL(@strRSTotalQty,0)
	BEGIN
	  SET @o_vcFlag = 'E'
	  SET @o_vcMessage = '<Message>Retain qty can not be greater then Total Qty</Message>'
	  RETURN 1
	END
	
	
	SET @ReqValue = ROUND(((@strRSRetain*@strRSClosingPrice) * (100-@strRSHaircut))/100,2)
	SET @o_vcFlag = 'S'
	SET @o_vcMessage = '<Message>Validated</Message>'+'<ReqValue>'+CAST(@ReqValue AS VARCHAR)+'</ReqValue>'
	RETURN 1
  END
  ELSE IF @strModuleName IN('BUYBACK') AND @strOption = 'Offers'
  BEGIN
	DECLARE @strBuyBackQty INT = 0, @strBuyBackRate MONEY, @strOffer INT = 0
	
	SELECT @strBuyBackQty = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'HoldingQty'
	
	SELECT @strBuyBackRate = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'BuyBackRate'
	
	SELECT @strOffer = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'Offers'
	
	IF ISNULL(@strOffer,0) <= 0 
	BEGIN
	  SET @o_vcFlag = 'E'
	  SET @o_vcMessage = '<Message>Offer qty can not be zero or less then zero</Message>'
	  RETURN 1
	END
	
	IF ISNULL(@strOffer,0) > ISNULL(@strBuyBackQty,0)
	BEGIN
	  SET @o_vcFlag = 'E'
	  SET @o_vcMessage = '<Message>Offer qty can not be greater then Holding Qty</Message>'
	  RETURN 1
	END
	
	SET @ReqValue = ROUND((@strOffer*@strBuyBackRate),2)
	SET @o_vcFlag = 'S'
	SET @o_vcMessage = '<Message>Validated</Message>'+'<TotalValue>'+CAST(@ReqValue AS VARCHAR)+'</TotalValue>'
	RETURN 1
  END
  ELSE IF @strModuleName IN('FundRequest') AND @strOption = 'RequestedAmount'
  BEGIN
	DECLARE @strClientCode VARCHAR(15) ='', @strPayableAmount MONEY = 0, @strRequestedAmount MONEY = 0
	
	SELECT @strClientCode = ParameterValue
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'ClientCode'
	
	
	SELECT @strPayableAmount = CAST(ISNULL(ParameterValue,'0') AS MONEY)
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'PayableAmount'
	
	SELECT @strRequestedAmount = CAST(ISNULL(ParameterValue,'0') AS MONEY)
	FROM @tbl_InputJSONTable
	WHERE ParameterName = 'RequestedAmount'
	
	
	IF ISNULL(@strRequestedAmount,0) < 0
	BEGIN
	  SET @o_vcFlag = 'E'
	  SET @o_vcMessage = '<Message>Requested Amount can not be zero or less then zero</Message>'
	  RETURN 1
	END
	
	IF ISNULL(@strPayableAmount,0) = 0
	BEGIN
	  SET @o_vcFlag = 'E'
	  SET @o_vcMessage = '<Message>Payable Amount can not be zero or less then zero</Message>'
	  RETURN 1
	END
	--select @strPayableAmount, @strRequestedAmount
	IF ISNULL(@strPayableAmount,0) < isnull(@strRequestedAmount,0)
	BEGIN
	  SET @o_vcFlag = 'E'
	  SET @o_vcMessage = '<Message>Requested Amount is not greater then Payable Amount</Message>'
	  RETURN 1
	END
	SET @o_vcFlag = 'S'
	SET @o_vcMessage = '<Message>Validated</Message>'
	RETURN 1
	
  END
  ELSE IF @strOption IN('EValidateOTP','MValidateOTP')
  BEGIN
    DECLARE @strVEmailid VARCHAR(100)='',@strVMobile VARCHAR(10)='', @i_vJSON VARCHAR(MAX)='', @VOTP INT = 0,
	@VType VARCHAR(10)='', @VMobileRelation VARCHAR(10)='', @VEmailRelation VARCHAR(10)=''
	
	IF ISNULL(@strClientCode,'') = ''
	BEGIN
	  SET @strClientCode = @strUserid
	END
 
    IF NOT EXISTS(SELECT 1 FROM Client_ReKycMain(NOLOCK) WHERE rm_cmcd = @strClientCode AND rm_RequestType = @strModuleName
    AND ISNULL(rm_rekyc,'N') = 'N') 
    BEGIN
      SET @i_vcRefNo = ISNULL((select MAX(ISNULL(rm_refno, 0)) + 1 FROM Client_ReKycMain(NOLOCK)),1)
	
	  IF ISNULL(@i_vcRefNo,0) = 0
	  BEGIN
	    SET @i_vcRefNo = 1
	  END
  
	  INSERT INTO Client_ReKycMain(rm_cmcd, rm_cdate, rm_ctime, rm_rekyc, rm_status, rm_desc, mkrdt, mkrtm, rm_step, rm_refno, rm_RequestType)
	  VALUES(@strClientCode, CONVERT(VARCHAR,GETDATE(),112), CONVERT(VARCHAR,GETDATE(),108), 'N', 'Pending','',
	  CONVERT(VARCHAR,GETDATE(),112), CONVERT(VARCHAR,GETDATE(),108), 1, @i_vcRefNo, @strModuleName)
    END
    ELSE
    BEGIN
      SELECT @i_vcRefNo = rm_refno, @strStep = rm_step FROM Client_ReKycMain(NOLOCK) 
	  WHERE rm_cmcd = @strClientCode AND rm_RequestType = @strModuleName
      AND ISNULL(rm_rekyc,'N') = 'N' AND rm_srno IN( SELECT MAX(ISNULL(rm_srno, 0)) 
	  FROM Client_ReKycMain(NOLOCK) WHERE rm_cmcd = @strClientCode AND rm_RequestType = @strModuleName
	  AND ISNULL(rm_rekyc,'N') = 'N')
    END  
	  
	SELECT @strVEmailid  = ParameterValue FROM @tbl_InputJSONTable where ParameterName = 'Email'
	SELECT @strVMobile  = ParameterValue FROM @tbl_InputJSONTable where ParameterName = 'Mobile'
	SELECT @VOTP  = ParameterValue FROM @tbl_InputJSONTable where ParameterName = 'OTP'
	SELECT @VType  = ParameterValue FROM @tbl_InputJSONTable where ParameterName = 'Type'
	SELECT @VMobileRelation  = ParameterValue FROM @tbl_InputJSONTable where ParameterName = 'MobileRelation'
	SELECT @VEmailRelation  = ParameterValue FROM @tbl_InputJSONTable where ParameterName = 'EmailRelation'
	SET @i_vJSON = '{"userId": "##userId##","otp": "##otp##","otpFor": "##otpFor##","product": "TradePlus","otpType":"MCR"}'
	IF @strOption = 'EValidateOTP'
	BEGIN
	  SET @i_vJSON = REPLACE(@i_vJSON,'##otpFor##',@strVEmailid)	
	END
	ELSE IF @strOption = 'MValidateOTP'
	BEGIN
	  SET @i_vJSON = REPLACE(@i_vJSON,'##otpFor##',@strVMobile)	
	END
	SET @i_vJSON = REPLACE(@i_vJSON,'##userId##',@strClientCode)	
	SET @i_vJSON = REPLACE(@i_vJSON,'##otp##',@VOTP)
	--SELECT @i_vJSON
    EXEC stpr_APISendEmail @i_vJSON, 'OTPValidate', @strThirdPartyURL, @o_vcOutPutJSON OUTPUT
	SET @o_vcFlag = 'S'
	
	if @o_vcOutPutJSON NOT LIKE '%OTP verified%'
	BEGIN
	  SET @o_vcFlag = 'E'
	END
	
	IF @o_vcOutPutJSON LIKE '%OTP verified%' AND @VType = 'NEW'
	BEGIN
	  IF ISNULL(@strVEmailid,'') <> '' AND  @strOption = 'EValidateOTP'
	  BEGIN
	    IF EXISTS(SELECT 1 FROM Client_ModifyAPI(NOLOCK) WHERE ca_cmcd = @strClientCode and ca_Nfiller3 = @i_vcRefNo
	    AND ISNULL(ca_Tplus,'') = 'N' AND ca_field IN('cm_email'))
	    BEGIN
		  UPDATE A SET A.ca_newValue = @strVEmailid
		  FROM Client_ModifyAPI A
		  WHERE ca_cmcd = @strClientCode and ca_Nfiller3 = @i_vcRefNo
	      AND ISNULL(ca_Tplus,'') = 'N' AND ca_field = 'cm_email'
		  
		  UPDATE A SET A.ca_newValue = CASE WHEN LEN(@VEmailRelation) = 1 THEN @VEmailRelation ELSE @VEmailRelation END
		  FROM Client_ModifyAPI A
		  WHERE ca_cmcd = @strClientCode and ca_Nfiller3 = @i_vcRefNo
	      AND ISNULL(ca_Tplus,'') = 'N' AND ca_field = 'cc_RelationEmail'
		  
	    END
		ELSE
		BEGIN
		  
		  INSERT INTO Client_ModifyAPI(ca_cmcd, ca_field, ca_desc, ca_oldValue, ca_newValue, ca_date, ca_time, ca_computername, ca_Tplus,
		  ca_Cross, ca_Estro, ca_Dematacno, ca_filler1, ca_filler2, ca_filler3, ca_Nfiller1, ca_Nfiller2, ca_Nfiller3)
		  VALUES(@strClientCode, 'cm_email','Email','',@strVEmailid, CONVERT(VARCHAR,GETDATE(),112), CONVERT(VARCHAR,GETDATE(),108),
		  '','N','N','N','','PersonalDetails',0,0,0,0,@i_vcRefNo)
		  
		  INSERT INTO Client_ModifyAPI(ca_cmcd, ca_field, ca_desc, ca_oldValue, ca_newValue, ca_date, ca_time, ca_computername, ca_Tplus,
		  ca_Cross, ca_Estro, ca_Dematacno, ca_filler1, ca_filler2, ca_filler3, ca_Nfiller1, ca_Nfiller2, ca_Nfiller3)
		  VALUES(@strClientCode, 'cc_RelationEmail','EmailRelation','',
		  CASE WHEN LEN(@VEmailRelation) = 1 THEN @VEmailRelation ELSE @VEmailRelation END, 
		  CONVERT(VARCHAR,GETDATE(),112), CONVERT(VARCHAR,GETDATE(),108),
		  '','N','N','N','','PersonalDetails',0,0,0,0,@i_vcRefNo)
		END
	  END
	  ELSE IF ISNULL(@strVMobile,'') <> '' AND  @strOption = 'MValidateOTP'
	  BEGIN
	    IF EXISTS(SELECT 1 FROM Client_ModifyAPI(NOLOCK) WHERE ca_cmcd = @strClientCode and ca_Nfiller3 = @i_vcRefNo
	    AND ISNULL(ca_Tplus,'') = 'N' AND ca_field IN('cm_mobile'))
	    BEGIN
		  UPDATE A SET A.ca_newValue = @strVMobile
		  FROM Client_ModifyAPI A
		  WHERE ca_cmcd = @strClientCode and ca_Nfiller3 = @i_vcRefNo
	      AND ISNULL(ca_Tplus,'') = 'N' AND ca_field = 'cm_mobile'
		  
		  UPDATE A SET A.ca_newValue = CASE WHEN LEN(@VMobileRelation) = 1 THEN @VMobileRelation ELSE @VMobileRelation END
		  FROM Client_ModifyAPI A
		  WHERE ca_cmcd = @strClientCode and ca_Nfiller3 = @i_vcRefNo
	      AND ISNULL(ca_Tplus,'') = 'N' AND ca_field = 'cc_RelationMobile'
		  
	    END
		ELSE
		BEGIN
		  INSERT INTO Client_ModifyAPI(ca_cmcd, ca_field, ca_desc, ca_oldValue, ca_newValue, ca_date, ca_time, ca_computername, ca_Tplus,
		  ca_Cross, ca_Estro, ca_Dematacno, ca_filler1, ca_filler2, ca_filler3, ca_Nfiller1, ca_Nfiller2, ca_Nfiller3)
		  VALUES(@strClientCode, 'cm_mobile','Mobile','',@strVMobile, CONVERT(VARCHAR,GETDATE(),112), CONVERT(VARCHAR,GETDATE(),108),
		  '','N','N','N','','PersonalDetails',0,0,0,0,@i_vcRefNo)
		  
		  INSERT INTO Client_ModifyAPI(ca_cmcd, ca_field, ca_desc, ca_oldValue, ca_newValue, ca_date, ca_time, ca_computername, ca_Tplus,
		  ca_Cross, ca_Estro, ca_Dematacno, ca_filler1, ca_filler2, ca_filler3, ca_Nfiller1, ca_Nfiller2, ca_Nfiller3)
		  VALUES(@strClientCode, 'cc_RelationMobile','MobileRelation','',CASE WHEN LEN(@VMobileRelation) = 1 THEN @VMobileRelation ELSE @VMobileRelation END, 
		  CONVERT(VARCHAR,GETDATE(),112), CONVERT(VARCHAR,GETDATE(),108),
		  '','N','N','N','','PersonalDetails',0,0,0,0,@i_vcRefNo)
		END
	  END
	END
	
	SET @o_vcMessage = '<Message>'+@o_vcOutPutJSON+'</Message>'
    RETURN 1	
  END
  ELSE IF @strOption IN('MSendOTP','ESendOTP')
  BEGIN
	DECLARE @oldOTPFlag VARCHAR(20)='', @strOldEmailid VARCHAR(100)='', @i_sendJSON VARCHAR(MAX)='',
	@strType VARCHAR(10)='', @strNewEmailid VARCHAR(100)='', @strOldMobile VARCHAR(20)='',
	@StremailText NVARCHAR(MAX)='', @strSubject VARCHAR(MAX)='', @StrClientName VARCHAR(100)='',
	@strNewMobile VARCHAR(10)='', @strSMSText VARCHAR(MAX)=''
	  --SELECT @oldOTPFlag = sp_sysvalue FROM WebParameter(NOLOCK) WHERE sp_parmcd='OldEmailMobOTP' 
	
	  
	IF ISNULL(@strClientCode,'') = ''
	BEGIN
	  SET @strClientCode = @strUserid
	END
	  
	SELECT @strOldEmailid = CM_EMAIL, @strOldMobile = cm_MOBILE, 
	@StrClientName = CM_NAME 
	FROM client_master(NOLOCK) WHERE CM_CD = @strClientCode
	  
	SELECT @strNewEmailid  = ParameterValue FROM @tbl_InputJSONTable where ParameterName = 'Email'
	SELECT @strNewMobile  = ParameterValue FROM @tbl_InputJSONTable where ParameterName = 'Mobile'
	SELECT @oldOTPFlag  = ParameterValue FROM @tbl_InputJSONTable where ParameterName = 'OTPRequire'
	  
	SELECT @strSMSText = sp_sysvalue from  Sysparameter WHERE sp_parmcd='SMSCLMMO'
	  
	IF @strOption = 'ESendOTP'
	BEGIN
	  IF ISNULL(@strNewEmailid,'') = ''
	  BEGIN
		SET @o_vcFlag = 'E'
	    SET @o_vcMessage = '<Message>New Email id not Found</Message>'
        RETURN 1
	  END

	  
	  SELECT @StremailText = BodyText, @strSubject = EmailSubject From tbl_EmailTemplate(NOLOCK) WHERE RefName ='EmailChange'
	  SET @StremailText = REPLACE(@StremailText,'<<ClientName>>',@StrClientName)
	  SET @StremailText = REPLACE(@StremailText,'<<OldEmailid>>',@strOldEmailid)
	  SET @StremailText = REPLACE(@StremailText,'<<NewEmailid>>',@strNewEmailid)
		 
	  IF ISNULL(@StremailText,'') = ''
	  BEGIN
		SET @o_vcFlag = 'E'
	    SET @o_vcMessage = '<Message>Email Template Not Define in Email Templete Table</Message>'
        RETURN 1
	  END
		
	  IF ISNULL(@oldOTPFlag,'') LIKE '%OLD%' AND ISNULL(@strOldEmailid,'') <> '' 
	  BEGIN
		IF ISNULL(@strSMSText,'') <> ''
		BEGIN
		  SET @i_sendJSON = '{"userId":"##userId##","type":"BT","email":"##Email##","mobile":"##Mobile##",
          "smsText":"##SMSText##","emailSubject":"##EmailSubject##","emailBody":"##EmailBody##",
          "product":"TradePlus","otpType":"MCR"}'
		  SET @i_sendJSON = REPLACE(@i_sendJSON,'##Mobile##',@strOldMobile)		  
		  SET @i_sendJSON = REPLACE(@i_sendJSON,'##SMSText##',@strSMSText)	
		END
		ELSE
		BEGIN
		  SET @i_sendJSON = '{"userId":"##userId##","type":"EI","email":"##Email##","emailSubject":"##EmailSubject##",
	      "emailBody":"##EmailBody##","product":"TradePlus","otpType":"MCR"}'
		END
		  
		SET @i_sendJSON = REPLACE(@i_sendJSON,'##userId##',@strClientCode)	
		SET @i_sendJSON = REPLACE(@i_sendJSON,'##Email##',@strOldEmailid)
        SET @i_sendJSON = REPLACE(@i_sendJSON,'##EmailSubject##',@strSubject)		  
		SET @i_sendJSON = REPLACE(@i_sendJSON,'##EmailBody##',@StremailText)	
		--select @i_sendJSON  
		SET @o_vcOutPutJSON = ''
		EXEC stpr_APISendEmail @i_sendJSON, 'OTP', @strThirdPartyURL, @o_vcOutPutJSON OUTPUT
		SET @o_vcFlag = 'S'
	    SET @o_vcMessage = '<Message>'+@o_vcOutPutJSON+'</Message>'
        --RETURN 1
	  -- SEND EMAIL TEXT 	
	  END	
	  IF ISNULL(@strNewEmailid,'') <> ''
	  BEGIN
		SET @i_sendJSON = '{"userId":"##userId##","type":"EI","Email":"##Email##","EmailSubject":"##EmailSubject##",
		 "EmailBody":"##EmailBody##","Product":"TradePlus","otpType":"MCR"}'
		SET @i_sendJSON = REPLACE(@i_sendJSON,'##Email##',@strNewEmailid)
        SET @i_sendJSON = REPLACE(@i_sendJSON,'##EmailSubject##',@strSubject)		  
		SET @i_sendJSON = REPLACE(@i_sendJSON,'##EmailBody##',@StremailText)	
        SET @i_sendJSON = REPLACE(@i_sendJSON,'##userId##',@strClientCode)			  
		SET @o_vcOutPutJSON = ''
		--SELECT @i_sendJSON
		EXEC stpr_APISendEmail @i_sendJSON, 'OTP', @strThirdPartyURL, @o_vcOutPutJSON OUTPUT
		SET @o_vcFlag = 'S'
	    SET @o_vcMessage = '<Message>'+ISNULL(@o_vcOutPutJSON,'')+'</Message>'
        RETURN 1

	  END
	END	
	IF @strOption = 'MSendOTP'
	BEGIN
	  IF ISNULL(@strSMSText,'') <> ''
	  BEGIN
		SET @o_vcFlag = 'E'
	    SET @o_vcMessage = '<Message>SMS Template not Define in Sysparameter in SMSCLMMO</Message>'
        RETURN 1
	  END  
	  IF ISNULL(@strNewMobile,'') =''
	  BEGIN
		SET @o_vcFlag = 'E'
	    SET @o_vcMessage = '<Message>New Mobile no not Found</Message>'
        RETURN 1
	  END
		
	  IF ISNULL(@oldOTPFlag,'') LIKE '%OLD%' AND ISNULL(@strOldMobile,'') <> '' 
	  BEGIN
		SELECT @StremailText = BodyText, @strSubject = EmailSubject From tbl_EmailTemplate(NOLOCK) WHERE RefName ='MobileChange'
		SET @StremailText = REPLACE(@StremailText,'<<ClientName>>',@StrClientName)
		SET @StremailText = REPLACE(@StremailText,'<<OldMobile>>',@strOldMobile)
		SET @StremailText = REPLACE(@StremailText,'<<NewMobile>>',@strNewMobile)
		  
		  
		SET @i_sendJSON = '{"userId":"##userId##","type":"BT","email":"##Email##","mobile":"##Mobile##",
          "smsText":"##SMSText##","emailSubject":"##EmailSubject##","emailBody":"##EmailBody##",
          "product":"TradePlus","otpType":"MCR"}'
		SET @i_sendJSON = REPLACE(@i_sendJSON,'##Mobile##',@strOldMobile)		  
		SET @i_sendJSON = REPLACE(@i_sendJSON,'##SMSText##',@strSMSText)
		SET @i_sendJSON = REPLACE(@i_sendJSON,'##userId##',@strClientCode)			  
		SET @i_sendJSON = REPLACE(@i_sendJSON,'##Email##',@strOldEmailid)
        SET @i_sendJSON = REPLACE(@i_sendJSON,'##EmailSubject##',@strSubject)		  
		SET @i_sendJSON = REPLACE(@i_sendJSON,'##EmailBody##',@StremailText)		  
		  
		SET @o_vcOutPutJSON = ''
		EXEC stpr_APISendEmail @i_sendJSON, 'OTP', @strThirdPartyURL, @o_vcOutPutJSON OUTPUT
		SET @o_vcFlag = 'S'
	    SET @o_vcMessage = '<Message>'+@o_vcOutPutJSON+'</Message>'
        --RETURN 1

		   -- send SMS
	  END
	  IF ISNULL(@strNewMobile,'') <> ''
	  BEGIN
		SELECT @StremailText = BodyText, @strSubject = EmailSubject From tbl_EmailTemplate(NOLOCK) WHERE RefName ='MobileChange'
		SET @StremailText = REPLACE(@StremailText,'<<ClientName>>',@StrClientName)
		SET @StremailText = REPLACE(@StremailText,'<<OldMobile>>',@strOldMobile)
		SET @StremailText = REPLACE(@StremailText,'<<NewMobile>>',@strNewMobile)
		  
		SET @i_sendJSON = '{"userId":"##userId##","type":"BT","email":"##Email##","mobile":"##Mobile##",
            "smsText":"##SMSText##","emailSubject":"##EmailSubject##","emailBody":"##EmailBody##",
            "product":"TradePlus","otpType":"MCR"}'
		SET @i_sendJSON = REPLACE(@i_sendJSON,'##Mobile##',@strNewMobile)		  
		SET @i_sendJSON = REPLACE(@i_sendJSON,'##SMSText##',@strSMSText)
		SET @i_sendJSON = REPLACE(@i_sendJSON,'##userId##',@strClientCode)			  
		SET @i_sendJSON = REPLACE(@i_sendJSON,'##Email##',@strOldEmailid)
        SET @i_sendJSON = REPLACE(@i_sendJSON,'##EmailSubject##',@strSubject)		  
		SET @i_sendJSON = REPLACE(@i_sendJSON,'##EmailBody##',@StremailText)		  
		  
		SET @o_vcOutPutJSON = ''
		EXEC stpr_APISendEmail @i_sendJSON, 'OTP', @strThirdPartyURL, @o_vcOutPutJSON OUTPUT
		SET @o_vcFlag = 'S'
	    SET @o_vcMessage = '<Message>'+@o_vcOutPutJSON+'</Message>'
        RETURN 1

	  END
	END
	
	SET @o_vcFlag = 'S'
	SET @o_vcMessage = '<Message>OTP Send</Message>'
    RETURN 1
  END	
  ELSE IF @strModuleName IN('ReceiptsEntry') AND @strOption = 'ExchSeg'
  BEGIN
	
    SELECT CASE WHEN SUBSTRING(da_dpid,1,2)='IN' then da_actno else da_actno end
    AS [Value], CASE WHEN SUBSTRING(da_dpid,1,2)='IN' then da_actno else da_actno end
    AS [DisplayName] FROM Dematact(NOLOCK)
	
  END
END
GO

CREATE PROCEDURE stpr_Rpt_BPPerformanceReport @vcXML NVARCHAR(MAX), @o_vcErrorFlag VARCHAR(1) OUTPUT, @o_vcErrorMessage VARCHAR(MAX) OUTPUT 
WITH ENCRYPTION
AS
BEGIN

  DECLARE @dtFromDate VARCHAR(8), @dtToDt VARCHAR(8), @strUserId VARCHAR(500) = '', @strExchSeg VARCHAR(100),
  @XMLData XML, @strAccountType VARCHAR(500)='', @strTable VARCHAR(50)='', @strsql VARCHAR(MAX) = '',
  @strSplFilter VARCHAR(MAX)='',
  @strCompanyCode VARCHAR(1), @StrString VARCHAR(MAX)='', @optTurnover VARCHAR(100)='', @EXTurnover VARCHAR(100)='',
  @strStringMin VARCHAR(MAX)='', @strOutputType VARCHAR(1)='G', @strSelectTag VARCHAR(1)='', @strSelectUsers VARCHAR(500)='',
  @strClientString NVARCHAR(MAX)='', @strExchange VARCHAR(10)='', @strRepType VARCHAR(50)='', @strRepSubType VARCHAR(50)=''
  
  IF @vcXML = ''
  BEGIN
    SET @o_vcErrorFlag  = 'E'
    SET @o_vcErrorMessage = 'Please Send Input Parameter(s)'
    RETURN 1
  END 

  
  SET @XMLData = CAST('<root>'+@vcXML+'</root>' AS XML)
  
  SELECT @dtFromDate = ISNULL(x.value('(FromDt)[1]', 'VARCHAR(8)'),''),
  @dtToDt = ISNULL(x.value('(ToDt)[1]', 'VARCHAR(8)'),''),
  @strUserId = ISNULL(x.value('(UserId)[1]', 'VARCHAR(500)'),''),
  @strOutputType = ISNULL(x.value('(OutputType)[1]', 'VARCHAR(1)'),''),
  @strSplFilter = ISNULL(x.value('(SplFilter)[1]', 'VARCHAR(MAX)'),''),
  @strCompanyCode = ISNULL(x.value('(CompanyCode)[1]', 'VARCHAR(20)'),''),
  @optTurnover = Isnull(X.value('(optTurnover)[1]', 'VARCHAR(50)'),''),
  @EXTurnover = Isnull(X.value('(ASEXTurnover)[1]', 'VARCHAR(50)'),''),
  @strSelectTag = ISNULL(x.value('(SelectTag)[1]', 'VARCHAR(1)'),''),
  @strSelectUsers = ISNULL(x.value('(SelectUsers)[1]', 'VARCHAR(500)'),''),
  @strExchange = ISNULL(x.value('(ExchSeg)[1]', 'VARCHAR(500)'),''),
  @strRepType = ISNULL(x.value('(RepType)[1]', 'VARCHAR(500)'),''),
  @strRepSubType = ISNULL(x.value('(RepSubType)[1]', 'VARCHAR(500)'),'')
  FROM @XMLData.nodes('/root') AS XTbl(x) 
  
  
   
  

  DECLARE @tbl_UserList TABLE (Client_Code VARCHAR(10))
  
  
  SELECT @strClientString = DBO.fn_ReturnQueryAccess(@strUserid,@strSelectTag,@strSelectUsers)
	
  /*
  IF @strSplFilter = ''
  BEGIN
    INSERT INTO @tbl_UserList(Client_Code) 
    SELECT * FROM DBO.[fn_GetClients](@strUserId,'','') 
  END  
  ELSE IF @strSplFilter <> ''
  BEGIN
    SET @StrString  = ' SELECT distinct CM_CD FROM Client_master(NOLOCK) WHERE  1 = 1 AND cm_type <> ''T'' AND '+@strSplFilter
	INSERT INTO @tbl_UserList(Client_Code)  
	EXEC(@StrString) 
	SET @StrString = ''
  END
  
  IF @strSplFilter = ''
  BEGIN
	SET @strStringMin  = 'DECLARE @tbl_UserList TABLE(Client_Code VARCHAR(50)) '
    +' INSERT INTO @tbl_UserList(Client_Code) '
    +' SELECT * FROM DBO.[fn_GetClients]('''+@strUserId+''','''','''') '
  END  
  ELSE IF @strSplFilter <> ''
  BEGIN
    SET @strStringMin  = ' DECLARE @tbl_UserList TABLE (Client_Code VARCHAR(10)) '
	                   +' INSERT INTO @tbl_UserList(Client_Code) SELECT distinct CM_CD FROM Client_master(NOLOCK) WHERE 1 = 1  AND '+@strSplFilter
  END	
  
  SET @strStringMin = @strStringMin+' DELETE FROM @tbl_UserList 
  WHERE CLIENT_CODE IN(SELECT CM_cD FROM CLIENT_MASTER WHERE cm_type = ''T'') '
  
  
  DELETE FROM @tbl_UserList 
  WHERE CLIENT_CODE IN(SELECT CM_cD FROM CLIENT_MASTER WHERE cm_type = 'T')

  */
  

  IF OBJECT_ID('tempdb..#cftover') IS NOT NULL
  BEGIN
	DROP TABLE #cftover
  END
  
  CREATE TABLE #cftover (
	ft_dpid CHAR(5) NOT NULL, ft_companycode CHAR(1) NOT NULL, ft_exchange CHAR(1) NOT NULL, ft_segment CHAR(1) 
	NOT NULL, ft_dt VARCHAR(11), ft_rptcd CHAR(20) NOT NULL, ft_rptnm CHAR(50) NOT NULL, ft_grpcd CHAR(8) NOT NULL, ft_grpnm CHAR(30) 
	NOT NULL, ft_Scrip VARCHAR(20) NOT NULL, ft_CashTotal MONEY NOT NULL DEFAULT 0, ft_CashFiller MONEY NOT NULL DEFAULT 0, ft_FutTotal MONEY NOT 
	NULL DEFAULT 0, ft_OptTotal MONEY NOT NULL DEFAULT 0, ft_FOTotal NUMERIC(25, 2) NOT NULL DEFAULT 0, ft_FOFiller 
	MONEY NOT NULL DEFAULT 0, ft_CashBrokerage Money not null default 0, ft_FOBrokerage Money not null default 0,
	ft_CommFutTotal MONEY NOT 
	NULL DEFAULT 0, ft_CommOptTotal MONEY NOT NULL DEFAULT 0, ft_CommFOTotal NUMERIC(25, 2) NOT NULL DEFAULT 0,
	ft_CommFOFiller MONEY NOT NULL DEFAULT 0, ft_CommFOBrokerage Money not null default 0)

  TRUNCATE TABLE #cftover

  SET @StrString = ' SELECT td_companycode + ''C'', td_companycode, '''', ''C'', td_dt, td_clientcd, '''', '''', '''', td_Scripcd, sum((td_bqty + td_sqty '
			+' ) * td_marketrate),  sum(Round((td_bqty+td_sqty)*td_brokerage,4)), 0 '
  +' FROM trx WITH (INDEX (idx_trx_dt_clientcd)), Settlements(NOLOCK),  '
  +' settlement_type(NOLOCK), CLIENT_MASTER(NOLOCK) ' 
  +' WHERE td_stlmnt = se_stlmnt AND se_type = sy_type AND se_exchange = sy_exchange  '
  +' AND td_companycode = '''+@strCompanyCode+''' AND td_dt >= '''+@dtFromDate+''' AND td_dt <= '''+@dtToDt+'''' 
  +' AND td_clientcd = CM_CD AND ' +@strClientString+'  '
  
  IF ISNULL(@strExchange,'All') NOT IN('All','')
  BEGIN
    SET @StrString = @StrString+' AND td_companycode+se_exchange+''C'' IN(SELECT Value FROM DBO.RETURNTABLE('''+@strExchange+''','','')) '
  END
  
  SET @StrString = @StrString+' GROUP BY td_companycode, td_clientcd, CASE WHEN Left(td_stlmnt, 2) IN (''BW'', ''NN'', ''BQ'', ''NQ'')  '
  +' THEN sy_maptype ELSE td_stlmnt END, td_companycode + ''C'', sy_maptype, td_marginYN, td_dt,  '
  +' td_clientcd, td_scripcd '
  
  --SELECT @StrString

  INSERT INTO #cftover (
	ft_dpid, ft_companycode, ft_exchange, ft_segment, ft_dt, ft_rptcd, ft_rptnm, ft_grpcd, ft_grpnm, ft_Scrip, ft_cashTotal, 
	ft_CashBrokerage, ft_CashFiller
	)
  EXEC(@StrString)
  
  
  
  	
  SET @StrString = 'SELECT td_companycode + td_Segment, td_companycode, td_exchange, td_segment, td_dt, td_clientcd, '''', '''', '''', '
                   +' td_seriesid, sum(CASE sign(sm_strikeprice) WHEN 0 THEN '
				   
