CREATE PROCEDURE stpr_GenerateRequestEmail @dsXml XML WITH ENCRYPTION AS
BEGIN
  DECLARE @tbl_InputJSONTable DBO.tb_ParamList;
  DECLARE @o_ParameterList VARCHAR(max) = '', @o_ParameterListxml XML, @strFlag VARCHAR(20)='';
  DECLARE @strModuleName VARCHAR(50) = '', @strOption VARCHAR(50) = '', @StrXML XML, @StrData1 VARCHAR(MAX)='' ,
  @strISIN VARCHAR(20)='', @strClientCode VARCHAR(50)='', @o_vcOutPutJSON VARCHAR(MAX)='', @strUserid VARCHAR(50)='',
  @strtradeplustempdb VARCHAR(100)='', @strType VARCHAR(50)='', @strEntryName VARCHAR(50)='',@o_vcErrorFlag VARCHAR(1)='', @o_vcErrorMessage VARCHAR(MAX)=''
  DECLARE @o_vcJsonOutput VARCHAR(MAX)='', @strFromDate VARCHAR(20), @strToDate VARCHAR(20), @strReportType VARCHAR(100)=''
  
  
	--- PARAMETER LIST  
  EXEC SP_ParameterXMLRep @dsXml, @o_ParameterList OUTPUT


  CREATE TABLE #TBL_JsonCutter(SerialNo INT, ColumnName VARCHAR(50), ColumnValue VARCHAR(MAX), ValueTypeColumn INT,
    UpdateFlag VARCHAR(1), MasterTag VARCHAR(50), JsonLevel INT, MasterLevel INT)


  IF ISNULL(@o_ParameterList, '') <> ''
  BEGIN
	SET @o_ParameterListxml = CAST(@o_ParameterList AS XML)

	INSERT INTO @tbl_InputJSONTable (ParameterName, ParameterValue, HeaderName, Jsontag)
	SELECT Parameter.value('(ColumnName)[1]', 'VARCHAR(MAX)') AS Client_Code, Parameter.value(
				'(ColumnValue)[1]', 'VARCHAR(MAX)') AS ColumnValue, Parameter.value('(MasterTag)[1]', 
				'VARCHAR(MAX)') AS MasterTag, Parameter.value('(JsonLevel)[1]', 'VARCHAR(MAX)') AS JsonLevel
		FROM @o_ParameterListxml.nodes('/Parameter') AS XTbl(Parameter)
  END
  
  DECLARE @tbl_jsonoutput TABLE(SerialNo INT, ColumnName VARCHAR(50), ColumnValue VARCHAR(MAX), 
  MasterTag VARCHAR(100), JSONLEVEL INT, MASTERLEVEL INT)
  
  DECLARE @JsonCutterXML XML
  
  DECLARE @jsonCutterOutput VARCHAR(MAX)='', @strDanSql NVARCHAR(MAX)='',
  @strRequestId NVARCHAR(MAX)='', @strCallUrl VARCHAR(MAX)='', @strThirdPartyURL VARCHAR(MAX)='',
  @strReportName VARCHAR(100)='', @strRekycDocumentType VARCHAR(100)='', @strFormNo VARCHAR(20),
  @strFormStatus VARCHAR(50)='', @strExportType VARCHAR(50)='', @strSegment VARCHAR(100)='', 
  @strDataSegment VARCHAR(100)='', @strDataOption VARCHAR(100)='', @strdataReportType  VARCHAR(100)='',
  @strBenefAccountNo VARCHAR(16)='', @strAsOnDate VARCHAR(50)='', @StrSelection VARCHAR(10)='',@StrCode VARCHAR(50)='',
  @strReportDisplay VARCHAR(1)='D'
  
  SELECT @strModuleName = ParameterValue
  FROM @tbl_InputJSONTable
  WHERE ParameterName = 'ActionName'


  SELECT @strOption = ParameterValue
  FROM @tbl_InputJSONTable
  WHERE ParameterName = 'Option'
  
  SELECT @strClientCode = ParameterValue
  FROM @tbl_InputJSONTable
  WHERE ParameterName = 'ClientCode'
  
  SELECT @strFromDate = ParameterValue
  FROM @tbl_InputJSONTable
  WHERE ParameterName = 'FromDate'
  
  
  SELECT @strToDate = ParameterValue
  FROM @tbl_InputJSONTable
  WHERE ParameterName = 'ToDate'
  
  SELECT @strReportType = ParameterValue
  FROM @tbl_InputJSONTable
  WHERE ParameterName = 'ReportType'
  
  SELECT @strReportName = ParameterValue
  FROM @tbl_InputJSONTable
  WHERE ParameterName = 'ReportName'
  
  SELECT @strSegment = ParameterValue
  FROM @tbl_InputJSONTable
  WHERE ParameterName = 'Segment'
  
  SELECT @strUserid = ParameterValue
  FROM @tbl_InputJSONTable
  WHERE ParameterName = 'Userid'
  
  SELECT @strReportDisplay = ParameterValue
  FROM @tbl_InputJSONTable
  WHERE ParameterName = 'ReportDisplay1'
  
  IF ISNULL(@strReportDisplay,'') = ''
  BEGIN
    SET @strReportDisplay = 'D'
  END
  
  
  IF ISNULL(@strClientCode,'') = '' OR NOT EXISTS(SELECT 1 FROM CLIENT_MASTER(NOLOCK) WHERE CM_cD =  @strClientCode)
  BEGIN
    SELECT [ErrorMessage] = 'Client is Require Sending Email', [ErrorFlag] = 'E'
	RETURN 1
  END
  
  IF @strReportName = 'Holding'  AND @strSegment = 'DP'
  BEGIN
    SET @strFromDate = @strToDate
  END
  
  IF @strModuleName = 'TRADEWEB' AND @strOption = 'SENDEMAIL'
  BEGIN
    DECLARE @XML VARCHAR(MAX) =''
    SELECT @XML = DefaultXML FROM TBL_ReportSetting(NOLOCK) WHERE ReportType ='IncomeTax' AND IsActive='Y'
    AND ReportName = @strReportName AND Segment = @strSegment
   
    SET @XML = REPLACE(@XML,'##FromDate##',@strFromDate)
	SET @XML = REPLACE(@XML,'##ToDate##',@strToDate)
	SET @XML = REPLACE(@XML,'##AsOnDate##',@strToDate)
	SET @XML = REPLACE(@XML,'##ClientCode##',@strClientCode)
	SET @XML = REPLACE(@XML,'##UserId##',@strUserid)
	
    SELECT @strBenefAccountNo = CASE WHEN SUBSTRING(da_actno,1,2) = 'IN' THEN RIGHT(da_actno,8)  ELSE da_actno END
    FROM Dematact(NOLOCK) WHERE da_clientcd = @strClientCode AND DA_STATUS='A' AND da_defaultyn ='Y'
	
	SET @XML = REPLACE(@XML,'##BenefAccountNo##',@strBenefAccountNo)
	SET @XML = REPLACE(@XML,'##ReportDisplay##',@strReportDisplay)
  
	SELECT @XML AS EmailPayload
	RETURN 1
  END
  
  IF @strModuleName = 'TRADEWEB' AND @strOption = 'CLIENTEMAIL'
  BEGIN
	SELECT ReportName, Segment from TBL_ReportSetting(NOLOCK)
    WHERE ReportType ='IncomeTax' AND IsActive='Y'
    ORDER BY SerialNo
  END	
  
  
  DECLARE @StrShowFilter1 VARCHAR(MAX)='', @StrShowFilter2 VARCHAR(MAX)='', @StrShowFilter3 VARCHAR(MAX)=''
  SELECT TOP 1 @StrShowFilter1 = ShowFilter1, @StrShowFilter2 = ShowFilter2, @StrShowFilter3 = ShowFilter3
  FROM tbl_TradeWebMenu(NOLOCK) WHERE  MenuTag = @strOption
      
  IF ISNULL(@StrShowFilter1,'') = ''
     SET @StrShowFilter1 = ''
	  
  IF ISNULL(@StrShowFilter2,'') = ''
     SET @StrShowFilter2 = ''
	  
  IF ISNULL(@StrShowFilter3,'') = ''
    SET @StrShowFilter3 = ''
	  
  SET @StrShowFilter1 = REPLACE(@StrShowFilter1,'<<FromDate>>',CONVERT(VARCHAR,CAST(ISNULL(@strFromDate,'') AS DATE),106))
  SET @StrShowFilter1 = REPLACE(@StrShowFilter1,'<<ToDate>>',CONVERT(VARCHAR,CAST(ISNULL(@strToDate,'') AS DATE),106))
  SET @StrShowFilter1 = REPLACE(@StrShowFilter1,'<<ClientCode>>',ISNULL(@strClientCode,''))
  
  SET @StrShowFilter2 = REPLACE(@StrShowFilter2,'<<FromDate>>',CONVERT(VARCHAR,CAST(ISNULL(@strFromDate,'') AS DATE),106))
  SET @StrShowFilter2 = REPLACE(@StrShowFilter2,'<<ToDate>>',CONVERT(VARCHAR,CAST(ISNULL(@strToDate,'') AS DATE),106))
  SET @StrShowFilter2 = REPLACE(@StrShowFilter2,'<<ClientCode>>',ISNULL(@strClientCode,''))
  
        
  DECLARE @XMLStringFilter VARCHAR(MAX)=''

  SELECT @XMLStringFilter = '<XmlData>
						<Headings>'
  IF ISNULL(@StrShowFilter1,'') <> ''
  BEGIN
	SET @XMLStringFilter = @XMLStringFilter+'<Heading>'+@StrShowFilter1+'</Heading>'				
  END                        
    
  IF ISNULL(@StrShowFilter2,'') <> ''
  BEGIN
	SET @XMLStringFilter = @XMLStringFilter+'<Heading>'+@StrShowFilter2+'</Heading>'				
  END                        
		
  IF ISNULL(@StrShowFilter3,'') <> ''
  BEGIN
	SET @XMLStringFilter = @XMLStringFilter+'<Heading>'+@StrShowFilter3+'</Heading>'				
  END                        
  SET @XMLStringFilter = @XMLStringFilter+'</Headings></XmlData>' 
  SELECT @XMLStringFilter AS [Settings]
  RETURN 1
END
GO

CREATE PROCEDURE stpr_PerformanceReport_ACC @dsXml VARCHAR(MAX)  
WITH ENCRYPTION
AS
BEGIN 
  DECLARE @tbl_InputJSONTable DBO.tb_ParamList ;
  DECLARE @o_ParameterList varchar(max)='', @o_ParameterListxml XML; 
  DECLARE @tbl_UserList dbo.UserAccessList;
  
  EXEC SP_ParameterXMLRep @dsXml, @o_ParameterList OUTPUT
  
  IF ISNULL(@o_ParameterList,'') <> ''
  BEGIN
	SET @o_ParameterListxml = CAST(@o_ParameterList AS XML)
    INSERT INTO @tbl_InputJSONTable (ParameterName,  ParameterValue, HeaderName, Jsontag) 
    SELECT Parameter.value('(ColumnName)[1]', 'VARCHAR(MAX)') AS Client_Code ,
    Parameter.value('(ColumnValue)[1]', 'VARCHAR(MAX)') AS ColumnValue,
	Parameter.value('(MasterTag)[1]', 'VARCHAR(MAX)') AS MasterTag,
	Parameter.value('(JsonLevel)[1]', 'VARCHAR(MAX)') AS JsonLevel
    FROM @o_ParameterListxml.nodes('/Parameter') AS XTbl(Parameter)
  END	  
  
  DECLARE @StrRequestFrom VARCHAR(1)='M', @strJson VARCHAR(MAX)='', @strUserid VARCHAR(50)='', @strUserType VARCHAR(50)='',
  @o_strJson2 VARCHAR(MAX), @strFromDate VARCHAR(8)='', @strToDate VARCHAR(8)='', @strCompanyCode VARCHAR(1)='A',
  @strReportType VARCHAR(10)='', @strActionName VARCHAR(50)='', @strOption VARCHAR(50)='', @strClientCode VARCHAR(50)='',
  @strSQL NVARCHAR(MAX)
  
  DECLARE @TBL_json TABLE(SerialNo int, Jsonvalue VARCHAR(MAX), ParentName VARCHAR(MAX), TargetForm VARCHAR(50), MenuNameP VARCHAR(100),
  PMenuCode VARCHAR(50))

  SELECT @strRequestFrom = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'RequestFrom'
  SELECT @strUserid = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Userid'
  SELECT @strFromDate = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'FromDate'
  SELECT @strToDate = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'ToDate'
  SELECT @strReportType = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'ReportType'
  SELECT @strActionName = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'ActionName'
  SELECT @strOption = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Option'
  SELECT @strClientCode = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'ClientCode'
  
  DECLARE @companyCount INT = 0
  SELECT @companyCount = ISNULL(SUM(ISNULL(cnt,0)),0)  
  FROM ( SELECT COUNT(0) Cnt From Entity_master with (NoLock) 
  WHERE em_bse <> 'N' and isNull(em_bclearingno,'') in ('189') 
  UNION ALL 
  SELECT COUNT(0) Cnt From Entity_master with (NoLock) 
  WHERE em_nse <> 'N' and isNull(em_nclearingno,'') in ('07277') ) a
	 
  IF @companyCount = 0
  BEGIN
	SELECT @strCompanyCode = em_cd 
	FROM Entity_Master with (nolock) where em_cd =(select min(em_cd) from Entity_master)
  END
  ELSE
  BEGIN
	SELECT @strCompanyCode = em_cd 
	FROM Entity_Master with (nolock) where em_cd = 'B'
  END
  
  SELECT @strUserType = ParameterValue  FROM @tbl_InputJSONTable WHERE ParameterName = 'Selection' 
  
  DECLARE @strSelection VARCHAR(20), @StrCode VARCHAR(50)
  SELECT @strSelection = LTRIM(RTRIM(ParameterValue)) FROM @tbl_InputJSONTable WHERE ParameterName = 'Selection'
  SELECT TOP 1 @StrCode = LTRIM(RTRIM(ParameterValue)) FROM @tbl_InputJSONTable WHERE ParameterName in('Code','ClientCode')
  
   
  IF ISNULL(@strUserType,'') = ''
  BEGIN
    SELECT TOP 1 @strUserType = ParameterValue  FROM @tbl_InputJSONTable 
    WHERE ParameterName = 'UserType'
  END
  
  DECLARE @strClientString VARCHAR(MAX)=''
  SELECT @strClientString = DBO.fn_ReturnQueryAccess(@strUserid,@strSelection,@StrCode)
  IF ISNULL(@strClientString,'') = ''
  BEGIN  
	SET @strClientString = ''
  END	
  

    IF OBJECT_ID('tempdb..#tbl_Performance') IS NOT NULL
    BEGIN
      DROP TABLE #tbl_Performance
    END

    IF OBJECT_ID('tempdb..#tbl_PerChanges') IS NOT NULL
    BEGIN
      DROP TABLE #tbl_PerChanges
    END
	
	IF OBJECT_ID('tempdb..#tbl_PerChangesMain') IS NOT NULL
    BEGIN
      DROP TABLE #tbl_PerChangesMain
    END
	
	IF OBJECT_ID('tempdb..#tbl_PerformanceMain') IS NOT NULL
    BEGIN
      DROP TABLE #tbl_PerformanceMain
    END


    CREATE TABLE #tbl_Performance (acckey INT , Exchange VARCHAR(3), td_clientcd VARCHAR(10), td_Settlement VARCHAR(20),  
    td_date VARCHAR(8), td_scripcd VARCHAR(10), turnover MONEY, Brokerage MONEY, xkey INT)

    CREATE INDEX INDX_tbl_Performance on #tbl_Performance
    (acckey, Exchange, td_clientcd, td_Settlement)

    CREATE TABLE #tbl_PerformanceMain (Settlement VARCHAR(10), td_clientcd VARCHAR(10), td_date VARCHAR(8), 
	turnover MONEY, Brokerage MONEY)
	
    CREATE INDEX INDX_tbl_PerformanceMain on #tbl_PerformanceMain
    (Settlement, td_clientcd, td_date)

    CREATE TABLE #tbl_PerChanges(acckey INT ,sh_stlmnt VARCHAR(20) , sh_clientcd VARCHAR(20), sh_desc VARCHAR(100), 
	sh_dt VARCHAR(8), sh_amount MONEY, xkey INT, ChargeType VARCHAR(50))
	
	CREATE TABLE #tbl_PerChangesMain(sh_dt VARCHAR(20), sh_stlmnt VARCHAR(20) , sh_clientcd VARCHAR(20), sh_desc VARCHAR(100), sh_amount MONEY, ChargeType VARCHAR(50))

    CREATE INDEX INDX_tbl_PerChanges on #tbl_PerChanges
    (sh_dt, sh_clientcd)
	
	
	SET @strSQL = ' SELECT td_acckey, td_companycode+se_exchange+''C'', td_dt, td_clientcd, td_stlmnt, td_Scripcd, '
	+' trrunover = sum((td_bqty + td_sqty ) * td_marketrate),  Brokerage = sum(Round((td_bqty+td_sqty)*td_brokerage,4)), 1 '
    +' FROM trx WITH (INDEX (idx_trx_dt_clientcd)), Settlements(NOLOCK), CLIENT_MASTER(NOLOCK)  '
    +' WHERE td_stlmnt = se_stlmnt '
	+' AND td_companycode = '''+@strCompanyCode+''' '
    +' AND td_dt >= '''+@strFromDate+''' AND td_dt <= '''+@strToDate+''''
    +' AND td_clientcd = CM_CD  '
	
	IF ISNULL(@strClientString,'') <>  ''
	BEGIN
	  SET @strSQL = @strSQL+' AND '+@strClientString
	END
	
	SET @strSQL = @strSQL+ ' AND Left(td_stlmnt, 2) IN (''BQ'',''BU'',''NQ'',''NU'')   '
    +' GROUP BY  td_acckey, td_companycode+se_exchange+''C'', '
	+' td_companycode + ''C'', td_dt,  td_clientcd, td_stlmnt, td_scripcd '
    +' ORDER BY td_clientcd, td_dt '
	
	INSERT INTO #tbl_Performance(acckey, Exchange, td_date,td_clientcd, td_Settlement , td_scripcd, turnover, Brokerage, xkey)
    EXEC(@strSQL)
	
	 
	SET @strSQL = ' SELECT td_acckey, td_companycode+se_exchange+''C'', td_dt, td_clientcd, td_stlmnt, td_Scripcd, '
	+' trrunover = sum((td_bqty + td_sqty ) * td_marketrate),  Brokerage = sum(Round((td_bqty+td_sqty)*td_brokerage,4)), 2 '
    +' FROM Trx_accumulated(NOLOCK), Settlements(NOLOCK), CLIENT_MASTER(NOLOCK)   '
    +' WHERE td_stlmnt = se_stlmnt  '
    +' AND td_companycode = '''+@strCompanyCode +''''
    +' AND td_dt >= '''+@strFromDate+''' AND td_dt <= '''+@strToDate+''''
    +' AND td_clientcd = CM_CD  '
	
	IF ISNULL(@strClientString,'') <> ''
	BEGIN
	  SET @strSQL = @strSQL+' AND '+@strClientString
	END
	
	
	SET @strSQL = @strSQL+ ' and cm_contractprint not in (''B'',''O'') '
	+' AND Left(td_stlmnt, 2) IN (''BQ'',''BU'',''NQ'',''NU'')  '
	+' AND td_acckey > 0 '
    +' GROUP BY  td_acckey, td_companycode+se_exchange+''C'', '
	+' td_companycode + ''C'', td_dt,  td_clientcd, td_stlmnt, td_scripcd '
    +' ORDER BY td_clientcd, td_dt '


    INSERT INTO #tbl_Performance(acckey, Exchange, td_date, td_clientcd, td_Settlement, td_scripcd, turnover, Brokerage, xkey)
    EXEC(@strSQL)
	
    /*DELETE X FROM #tbl_Performance X WHERE X.XKEY = 1 
    AND X.ACCKEY > 0 AND EXISTS (SELECT 1  FROM #tbl_Performance Y 
    WHERE Y.acckey = X.acckey AND Y.td_clientcd = X.td_clientcd 
	AND Y.td_scripcd = X.td_scripcd
    AND td_date = X.td_date 
	AND Y.XKEY = 2);
	*/
	
	DELETE X FROM #tbl_Performance X WHERE X.XKEY = 1 
    AND X.ACCKEY > 0 AND EXISTS (SELECT 1  FROM #tbl_Performance Y 
    WHERE Y.acckey = X.acckey AND Y.td_scripcd = X.td_scripcd AND td_date = X.td_date 
	AND Y.XKEY = 2);
	
   
	
    SET @strSQL = ' SELECT 0,  X.sh_stlmnt, Sett.se_stdt, X.sh_clientcd, sh_desc,sh_amount, 1 , sh_recordsource '
    +' FROM Specialcharges(NOLOCK) X, Settlements(NOLOCK) Sett, CLIENT_MASTER(NOLOCK)   '
    +' WHERE sh_companycode = '''+@strCompanyCode+''''
    +' and x.sh_stlmnt = sett.se_stlmnt '
	+' AND Left(sh_stlmnt, 2) IN (''BQ'',''BU'',''NQ'',''NU'') '
    +' AND se_stdt >= '''+@strFromDate+''' AND se_stdt <= '''+@strToDate+''''
	+' and sh_clientcd = CM_CD '
		
	IF ISNULL(@strClientString,'')  <> ''
	BEGIN
	  SET @strSQL = @strSQL+' AND '+@strClientString
	END
	
	INSERT INTO #tbl_PerChanges(acckey, sh_stlmnt, sh_dt, sh_clientcd,sh_desc, sh_amount, xkey, ChargeType)
	EXEC(@strSQL)
	
	DELETE A FROM #tbl_PerChanges A
	, Specialcharges_accumulated B, Settlements(NOLOCK) SETT
	WHERE B.sh_stlmnt = SETT.se_stlmnt
    AND EXISTS(sELECT 1 from #tbl_Performance where ACCKEY = B.sh_AccKey
	AND td_clientcd = B.sh_clientcd AND sh_dt = SETT.se_stdt)
	AND Left(B.sh_stlmnt, 2) IN ('BQ','BU','NQ','NU')  
	and A.sh_clientcd = B.sh_clientcd
    

    
   	SET @strSQL = ' SELECT X.sh_AccKey,  X.sh_stlmnt, Sett.se_stdt, X.sh_clientcd, sh_desc,sh_amount, 2 , sh_recordsource '
	+' FROM Specialcharges_accumulated(NOLOCK) X, Settlements(NOLOCK) Sett, CLIENT_MASTER(NOLOCK)  '
    +' WHERE sh_companycode = '''+@strCompanyCode+''''
    +' and x.sh_stlmnt = sett.se_stlmnt '
	+' AND Left(sh_stlmnt, 2) IN (''BQ'',''BU'',''NQ'',''NU'') '
    +' AND se_stdt >= '''+@strFromDate+''' AND se_stdt <= '''+@strToDate+''''
	+' and sh_clientcd = CM_CD '
	
	IF ISNULL(@strClientString,'') <> ''
	BEGIN
	  SET @strSQL = @strSQL+' AND '+@strClientString
	END
	
	
	INSERT INTO #tbl_PerChanges(acckey, sh_stlmnt, sh_dt, sh_clientcd,sh_desc, sh_amount, xkey, ChargeType)
	EXEC(@strSQL)
	
	
	INSERT INTO #tbl_PerChangesMain(sh_dt, sh_stlmnt, sh_clientcd, sh_desc, sh_amount, ChargeType)
	SELECT sh_dt, sh_stlmnt, sh_clientcd, sh_desc, SUM(sh_amount) AS sh_amount, ChargeType
	FROM #tbl_PerChanges
	GROUP BY sh_dt, sh_stlmnt, sh_clientcd, sh_desc, ChargeType
	
    UPDATE X
    SET X.sh_stlmnt = A.se_stlmnt
    FROM #tbl_PerChangesMain AS X
    INNER JOIN Settlements AS B
    ON SUBSTRING(B.se_stlmnt, 1, 2) = 'NU'
    INNER JOIN Settlements AS A
    ON A.se_stdt = B.se_stdt
    AND SUBSTRING(A.se_stlmnt, 1, 2) = CASE WHEN SUBSTRING(B.se_stlmnt, 1, 2) = 'NQ' THEN 'BQ'
            WHEN SUBSTRING(B.se_stlmnt, 1, 2) = 'NU' THEN 'BU' ELSE '' END
    WHERE LTRIM(RTRIM(X.ChargeType)) = 'TRX'
    AND SUBSTRING(X.sh_stlmnt, 1, 2) = 'NU'
    AND B.se_stlmnt = X.sh_stlmnt
    AND A.se_stdt IN (
        SELECT se_stdt FROM Settlements WHERE se_stlmnt = X.sh_stlmnt)
    AND SUBSTRING(A.se_stlmnt, 1, 2) = 'BU';

	
    UPDATE X
    SET X.sh_stlmnt = A.se_stlmnt
    FROM #tbl_PerChangesMain AS X
    INNER JOIN Settlements AS B
    ON SUBSTRING(B.se_stlmnt, 1, 2) = 'NQ'
    INNER JOIN Settlements AS A
    ON A.se_stdt = B.se_stdt
    AND SUBSTRING(A.se_stlmnt, 1, 2) = CASE WHEN SUBSTRING(B.se_stlmnt, 1, 2) = 'NQ' THEN 'BQ'
            WHEN SUBSTRING(B.se_stlmnt, 1, 2) = 'NU' THEN 'BU' ELSE '' END
    WHERE LTRIM(RTRIM(X.ChargeType)) = 'TRX'
    AND SUBSTRING(X.sh_stlmnt, 1, 2) = 'NQ'
    AND B.se_stlmnt = X.sh_stlmnt
    AND A.se_stdt IN (
        SELECT se_stdt FROM Settlements WHERE se_stlmnt = X.sh_stlmnt)
    AND SUBSTRING(A.se_stlmnt, 1, 2) = 'BQ';
	

    INSERT INTO #tbl_PerformanceMain(Settlement, td_date, td_clientcd, turnover, Brokerage)
	SELECT td_Settlement, td_date, td_clientcd, turnover = SUM(turnover), Brokerage = SUM(Brokerage)
	FROM #tbl_Performance
	GROUP BY td_Settlement, td_date, td_clientcd
	
    DECLARE @cols NVARCHAR(MAX), @query NVARCHAR(MAX), @col1s NVARCHAR(MAX), @col2s NVARCHAR(MAX), @col3s  NVARCHAR(MAX);

   SELECT @cols = STUFF((SELECT ',' + QUOTENAME(sh_desc) 
   FROM (SELECT DISTINCT sh_desc FROM #tbl_PerChangesMain) AS x FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 1, '');
   
   SELECT @col1s = STUFF((SELECT ',' + QUOTENAME(sh_desc) + ' = ISNULL(' + QUOTENAME(sh_desc) + ',0)' FROM (SELECT DISTINCT sh_desc FROM #tbl_PerChangesMain) AS x
   FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 1, '');

   SELECT @col2s = STUFF((SELECT ',' + QUOTENAME(sh_desc) + ' = SUM(ISNULL(' + QUOTENAME(sh_desc) + ',0))' FROM (SELECT DISTINCT sh_desc FROM #tbl_PerChangesMain) AS x
   FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 1, '');

   SELECT @col3s = STUFF((SELECT ',' + QUOTENAME(sh_desc) + ' = 0' FROM (SELECT DISTINCT sh_desc FROM #tbl_PerChangesMain) AS x FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 1, '');
   
    --IF @strReportType = 'Summary'
    --BEGIN
      SET @query = 'SELECT sh_clientcd, sh_dt, sh_stlmnt, ' + @col1s + ' INTO #TBL_PERMAIN FROM  ( 
      SELECT sh_clientcd, sh_dt, sh_stlmnt,  sh_desc, sh_amount FROM #tbl_PerChangesMain) AS src
      PIVOT (SUM(sh_amount) FOR sh_desc IN (' + @cols + ') ) AS pvt ORDER BY sh_dt; '
  
      SET @query = @query+' SELECT [Client Code] = ClientCode, [Client Name] = CM_NAME, Settlement,  SUM(turnover) AS Turnover, '+ @col2s+'    
	  FROM (SELECT Settlement, ClientCode = td_clientcd, turnover, '+@col3s+ '
	  FROM #tbl_PerformanceMain X1
	  UNION ALL
	  SELECT Settlement = sh_stlmnt, ClientCode = sh_clientcd, turnover = 0, '+@col1s+' 
      FROM #TBL_PERMAIN X2) X12, Client_Master(NOLOCK)
	  WHERE X12.ClientCode = CM_CD
	  GROUP BY Settlement, ClientCode, CM_NAME
	  ORDER BY ClientCode, Settlement ';
    --END
	
    EXEC sp_executesql @query;
 -- END
END  
GO

CREATE PROCEDURE stpr_SubBrokerLedger @dsXml VARCHAR (MAX)
WITH ENCRYPTION
AS
BEGIN
 DECLARE @VCXML VARCHAR (MAX)='';
	DECLARE @tbl_InputJSONTable DBO.tb_ParamList;
	DECLARE @o_ParameterList varchar (max)='', @o_ParameterListxml XML;
	DECLARE @tbl_UserList dbo.UserAccessList;
	
	EXEC SP_ParameterXMLRep @dsXml, @o_ParameterList OUTPUT
	
	
	IF ISNULL(@o_ParameterList,'') <> ''
	BEGIN
		SET @o_ParameterListxml= CAST (@o_ParameterList AS XML)
		INSERT INTO @tbl_InputJSONTable (ParameterName, ParameterValue, HeaderName, Jsontag)
		SELECT Parameter.value(' (ColumnName) [1]', 'VARCHAR (MAX)') AS Client_Code,
		Parameter.value(' (ColumnValue) [1]', 'VARCHAR (MAX)') AS ColumnValue, 
		Parameter.value(' (MasterTag) [1]', 'VARCHAR (MAX)') AS MasterTag, 
		Parameter.value(' (JsonLevel) [1]', 'VARCHAR (MAX)') AS JsonLevel
		FROM @o_ParameterListxml.nodes ('/Parameter') AS XTbl (Parameter)
	END
	DECLARE @strActionName VARCHAR (50)='', @stroption VARCHAR (50)='', @strFromDate VARCHAR (8)='', 
	@strToDate VARCHAR (8)='', @strUserid VARCHAR (20)='', @strRequestFrom VARCHAR(1)='W', 
	@strClientCode VARCHAR (50)='', @strReportDisplay VARCHAR(1)='P', @strUserType VARCHAR(50)=''

	
	SELECT @strActionName = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'ActionName' 
	SELECT @strOption =  ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Option' 
	SELECT @strFromDate = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'FromDate' 
	SELECT @strToDate = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'ToDate' 
	SELECT TOP 1 @strUserid = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'Userid' 
	SELECT @strRequestFrom = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'RequestFrom' 
	SELECT TOP 1 @strClientCode = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'ClientCode'
	SELECT @strReportDisplay = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'ReportDisplay' 
	SELECT @strUserType = ParameterValue FROM @tbl_InputJSONTable WHERE ParameterName = 'UserType' 
	
	IF @strActionName = 'TradeWeb' and @stroption= 'SubBrokerLedger'
	BEGIN
	  DECLARE @tbl_AccessRights TABLE(Client VARCHAR(50))
      INSERT INTO @tbl_AccessRights(Client)
      SELECT CLIENT_CODE FROM DBO.fn_GetClients(@strUserid,'','')

      DECLARE @tbl_SubBrokerLedger TABLE(SubBrokerCode VARCHAR(50),  SubBrokerName VARCHAR(200), SubBrokerGLCode VARCHAR(50), 
	  SubBrokerDepositGL VARCHAR(50), SubBrokerLedger MONEY, SubBrokerDEPOSITLedger MONEY)

      INSERT INTO @tbl_SubBrokerLedger(SubBrokerCode, SubBrokerName, SubBrokerGLCode, SubBrokerDepositGL)
      SELECT SubBrokerCode = RM_CD, RM_Name AS  SubBrokerName, RM_GLActCode As SubBrokerGLCode, RM_Introducer
      FROM SubBrokers(NOLOCK)
      WHERE RM_CD IN(SELECT cm_subbroker FROM Client_master(NOLOCK)
      WHERE cm_cd IN(SELECT Client FROM @tbl_AccessRights))

      UPDATE A SET A.SubBrokerLedger = B.LedgerBal
      FROM @tbl_SubBrokerLedger A,(Select ld_clientcd, SUM(Ld_Amount) As LedgerBal
      FROM Ledger(NOLOCK)
	  WHERE ld_dt <= @strTODate
      GROUP BY ld_clientcd) B
      WHERE A.SubBrokerGLCode = B.ld_clientcd


      UPDATE A SET A.SubBrokerDEPOSITLedger = B.LedgerBal
      FROM @tbl_SubBrokerLedger A,(Select ld_clientcd, SUM(Ld_Amount) As LedgerBal
      FROM Ledger(NOLOCK)
	  WHERE ld_dt <= @strTODate
      GROUP BY ld_clientcd) B
      WHERE A.SubBrokerDepositGL = B.ld_clientcd

      SELECT SubBrokerCode, SubBrokerName, SubBrokerGLCode, SubBrokerDepositGL , SubBrokerLedger = ISNULL(SubBrokerLedger,0), 
      SubBrokerDepositLedger = ISNULL(SubBrokerDEPOSITLedger,0)
      FROM @tbl_SubBrokerLedger
    END
    
	IF @strReportDisplay NOT IN('D','E','A')
    BEGIN
      DECLARE @StrShowFilter1 VARCHAR(MAX)='', @StrShowFilter2 VARCHAR(MAX)='', @StrShowFilter3 VARCHAR(MAX)=''
      SELECT TOP 1 @StrShowFilter1 = ShowFilter1, @StrShowFilter2 = ShowFilter2, @StrShowFilter3 = ShowFilter3
      FROM tbl_TradeWebMenu(NOLOCK) WHERE  MenuTag = @strOption
       
      IF ISNULL(@StrShowFilter1,'') = ''
        SET @StrShowFilter1 = ''
	  
      IF ISNULL(@StrShowFilter2,'') = ''
        SET @StrShowFilter2 = ''
	  
      IF ISNULL(@StrShowFilter3,'') = ''
	    SET @StrShowFilter3 = ''
  
      SET @StrShowFilter1 = REPLACE(@StrShowFilter1,'<<FROMDATE>>',CONVERT(VARCHAR(10), CAST(@strFromDate AS DATE), 103))
	  SET @StrShowFilter1 = REPLACE(@StrShowFilter1,'<<TODATE>>',CONVERT(VARCHAR(10), CAST(@strTODate AS DATE), 103))
	  SET @StrShowFilter1 = REPLACE(@StrShowFilter1,'<<EXCHANGE>>','')
	  
      declare @strReportHeader VARCHAR(MAX)=''
	  SET @strReportHeader = 'Sub Broker ledger Report '+'From Date - ' +CONVERT(VARCHAR(10), CAST(@strFromDate AS DATE), 103)
	  +' - TO Date - ' +CONVERT(VARCHAR(10), CAST(@strTODate AS DATE), 103)
	  DECLARE @o_XMLData VARCHAR(MAX)=''
	  EXEC stpr_GetXMLExceldata @strActionName, @strOption, @strOption, @strUserType, @o_XMLData OUTPUT
      
	  
      DECLARE @XMLStringFilter VARCHAR(MAX)=''
      SET @XMLStringFilter = '<XmlData>'
	
	  IF ISNULL(@o_XMLData,'') <> ''
	  BEGIN
	    SET @XMLStringFilter = @XMLStringFilter+@o_XMLData
	  END
	
	  SET @XMLStringFilter = @XMLStringFilter+'<ReportHeader>'+ISNULL(@strReportHeader,'')+'</ReportHeader> '
	  
	   SET @XMLStringFilter = @XMLStringFilter+'<WebColumns>Client Code,Client Name,Date,Voucher,Cheque No,Particular,Debit,Credit,Balance,Flag,LookUp,SubBrokerCode,SubBrokerName,SubBrokerGLCode,SubBrokerDepositGL,SubBrokerLedger,SubBrokerDepositLedger</WebColumns>'
	  
	  SET @XMLStringFilter = @XMLStringFilter+'<Headings>'
      IF ISNULL(@StrShowFilter1,'') <> ''
      BEGIN
	    SET @XMLStringFilter = @XMLStringFilter+'<Heading>'+@StrShowFilter1+'</Heading>'				
      END                        
      SET @XMLStringFilter = @XMLStringFilter+'</Headings><TableHeadings></TableHeadings></XmlData>' 
      SELECT [Settings] = @XMLStringFilter
   END
   RETURN 1
End
GO

CREATE PROCEDURE stpr_RunQueryFormAPI @dsXml XML
WITH ENCRYPTION
AS
BEGIN
  DECLARE @tbl_InputJSONTable DBO.tb_ParamList;
  DECLARE @o_ParameterList VARCHAR(max) = '', @o_ParameterListxml XML, @strFlag VARCHAR(20)='';
  DECLARE @strModuleName VARCHAR(50) = '', @strOption VARCHAR(50) = '', @StrXML XML, @StrData1 VARCHAR(MAX)='' ,
  @strISIN VARCHAR(20)='', @strDPType VARCHAR(20)='', @strCompCode VARCHAR(1), @strDematActNo VARCHAR(50)='',
  @o_vcOutPutJSON VARCHAR(MAX)=''
  
	--- PARAMETER LIST  
  EXEC SP_ParameterXMLRep @dsXml, @o_ParameterList OUTPUT

  IF ISNULL(@o_ParameterList, '') <> ''
  BEGIN
	SET @o_ParameterListxml = CAST(@o_ParameterList AS XML)

	INSERT INTO @tbl_InputJSONTable (ParameterName, ParameterValue, HeaderName, Jsontag)
	SELECT Parameter.value('(ColumnName)[1]', 'VARCHAR(MAX)') AS Client_Code, Parameter.value(
				'(ColumnValue)[1]', 'VARCHAR(MAX)') AS ColumnValue, Parameter.value('(MasterTag)[1]', 
				'VARCHAR(MAX)') AS MasterTag, Parameter.value('(JsonLevel)[1]', 'VARCHAR(MAX)') AS JsonLevel
		FROM @o_ParameterListxml.nodes('/Parameter') AS XTbl(Parameter)
  END

  DECLARE @strUserid VARCHAR(50)='', @i_vcInputJSON VARCHAR(MAX)='', @strClientCode VARCHAR(50), @strModule VARCHAR(100)=''

  SELECT @strModuleName = ParameterValue
  FROM @tbl_InputJSONTable
  WHERE ParameterName = 'ActionName'

  SELECT @strOption = ParameterValue
  FROM @tbl_InputJSONTable
  WHERE ParameterName = 'Option'

  DECLARE @o_vcFlag VARCHAR(1), @o_vcMessage VARCHAR(MAX)=''


  IF (@strModuleName IN ('TradeWeb') AND (@strOption = 'GetDataQueryForm' ))  
  BEGIN
	
	DECLARE @strQuery NVARCHAR(MAX) = '';
    
	DECLARE @strDataBase VARCHAR(50) = '', @opOP_DataBase VARCHAR(50)=''
    
    SELECT @strQuery = ParameterValue
    FROM @tbl_InputJSONTable
    WHERE ParameterName = 'Query'
	
    SELECT @strDataBase = ParameterValue
    FROM @tbl_InputJSONTable
    WHERE ParameterName = 'DataBase'
	
	SELECT @opOP_DataBase = LTRIM(RTRIM(OP_DataBase)) 
    FROM Other_Products(NOLOCK) WHERE OP_Product = @strDataBase AND OP_Status='A'
	
    
    BEGIN TRY
      BEGIN TRAN

      DECLARE @FullQuery NVARCHAR(MAX);
	  IF @strDataBase <> 'TradePlus' AND ISNULL(@opOP_DataBase,'') <> ''
	  BEGIN
        SET @FullQuery = 'USE ' + QUOTENAME(@opOP_DataBase) + '; ' + @strQuery;
	  END
	  IF @strDataBase = 'TradePlus'
	  BEGIN
	    SET @FullQuery = @strQuery;
	  END
      EXEC sp_executesql @FullQuery;
    
      ROLLBACK TRAN;
    
      SET @o_vcFlag = 'S';
      SET @o_vcMessage = 'Query executed successfully';
      SELECT SuccessFlag = @o_vcFlag, [Message] = @o_vcMessage;
    
   END TRY
   BEGIN CATCH
     ROLLBACK TRAN;
     SET @o_vcFlag = 'E';
     SET @o_vcMessage = ERROR_MESSAGE();
    
     SELECT [ErrorFlag] = @o_vcFlag,  [ErrorMessage] = @o_vcMessage, ErrorNumber = ERROR_NUMBER(), 
	 ErrorLine = ERROR_LINE(), ErrorProcedure = ISNULL(ERROR_PROCEDURE(), 'Ad-hoc query');
     RETURN 1;
   END CATCH;
  END	
END  
GO